insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'GEN', 1, 1, 'Mwambĩlĩlyonĩ Ngai nĩwatw’ĩkĩthisye matu na nthĩ.'),
('kam', 'GEN', 1, 2, 'Na nthĩ yaĩ ntheĩ na ndĩaĩ kĩndũ; na kĩvindu kyaĩ ĩũlũ wa ĩ kyũngũ: na Veva wa Ngai avw’ĩkĩte ĩũlũ wa manzĩ.'),
('kam', 'GEN', 1, 3, 'Na Ngai asya, Nĩkwĩthĩwe kyeni; na kweethĩwa kyeni.'),
('kam', 'GEN', 1, 4, 'Na Ngai oona kyeni, atĩ nĩ kĩseo: na Ngai avathan’ya kye ni na kĩvindu.'),
('kam', 'GEN', 1, 5, 'Na Ngai eeta kyeni Mũthenya, na kĩvindu akĩta Ũtukũ. Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya ũmwe.'),
('kam', 'GEN', 1, 6, 'Na Ngai asya, Nĩkwĩthĩwe yayaya katĩ wa manzĩ, nayo yĩvathan’ye manzĩ na manzĩ.'),
('kam', 'GEN', 1, 7, 'Na Ngai aseũvya yayaya, na avathan’ya manzĩ ala maĩ ĩtheo wa yayaya na manzĩ ala maĩ ĩũlũ wa yayaya: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 8, 'Na Ngai eeta yayaya Ĩtu. Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya wa kelĩ.'),
('kam', 'GEN', 1, 9, 'Na Ngai asya, Manzĩ ala me ĩtheo wa matu nĩmasyokeanĩe vamwe, na nthĩ nyũmũ yumĩle: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 10, 'Na Ngai eeta mũthanga mũmũ Nthĩ; na kũsyokeanĩa kwa manzĩ akwĩta Maũkanga: na Ngai oona nĩ ũseo.'),
('kam', 'GEN', 1, 11, 'Na Ngai asya, Nthĩ nĩmesye nyeki, nyũnyi ikĩsyaa mbeũ, na mĩtĩ yĩ mosyao ĩkĩsyaa mosyao o mũthemba wayo, ala me na mbeũ syamo nthĩnĩ wamo, ĩũlũ wa nthĩ: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 12, 'Na nthĩ yamesya nyeki, nyũnyi ikĩsyaa mbeũ o mũthemba wasyo, na mĩtĩ ĩkĩsyaa mosyao, ala me na mbeũ syamo o mũthemba wayo nthĩnĩ wamo: na Ngai oona nĩ ũseo.'),
('kam', 'GEN', 1, 13, 'Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya wa katatũ.'),
('kam', 'GEN', 1, 14, 'Na Ngai asya, Nĩkwĩthĩwe syeni yayayanĩ ya ĩtu ivathanasye mũthenya na ũtukũ; na nĩsyĩthĩwe mawonan’yo, na mavinda, na matukũ na myaka:'),
('kam', 'GEN', 1, 15, 'nasyo syĩthĩwe syeni yayayanĩ ya ĩtu sya kũete kyeni ĩũlũ wa nthĩ: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 16, 'Na Ngai aseũvya syeni ilĩ nene; kyeni kĩnene kya kũsumbĩka mũthenya, na kyeni kĩnini kya kũsumbĩka ũtukũ: o na ndata nasyo.'),
('kam', 'GEN', 1, 17, 'Na Ngai asia yayayanĩ ya ĩtu sya kũete kyeni ĩũlũ wa nthĩ,'),
('kam', 'GEN', 1, 18, 'na kũsumbĩka mũthenya na ũtukũ, na kũvathan’ya kyeni na kĩvindu: na Ngai oona nĩ ũseo.'),
('kam', 'GEN', 1, 19, 'Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya wa kana.'),
('kam', 'GEN', 1, 20, 'Na Ngai asya, Manzĩ nĩmausũwe nĩ wingĩ wa nyamũ syĩ thayũ, na nyũnyi iũlũkae ĩũlũ wa nthĩ yayayanĩ.'),
('kam', 'GEN', 1, 21, 'Na Ngai atw’ĩkĩthya mĩkũnga mĩnene, na syũmbe syonthe syĩ thayũ ila ithambĩaa, ila syusũĩte manzĩnĩ, o mũthemba wasyo, na kĩla nyũnyi ĩ nthwau o mũthemba wayo: na Ngai oona nĩ ũseo.'),
('kam', 'GEN', 1, 22, 'Na Ngai aiathima, akyasya, Ongelekai, mwingĩve, musũe manzĩ ma maũkanga, na nyũnyi singĩve kũũ nthĩ.'),
('kam', 'GEN', 1, 23, 'Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya wa katano.'),
('kam', 'GEN', 1, 24, 'Na Ngai asya, Nthĩ nĩyumye syũmbe syĩ thayũ o mũthemba wasyo, indo, na tũsamũ tũla tũtambũkaa, na nyamũ sya kũũ nthĩ o mũthemba wasyo: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 25, 'Na Ngai oombie nyamũ sya kũũ nthĩ o mũthemba wasyo, na indo o mũthemba wasyo, na kĩla kĩndũ kĩtambũkaa ĩũlũ wa nthĩ o mũthemba wakyo: na Ngai oona nĩ ũseo.'),
('kam', 'GEN', 1, 26, 'Na Ngai asya, Nĩtũmbe mũndũ na mũvw’ano witũ, na kĩtutya kitũ: na methĩwe na ũsumbĩko ĩũlũ wa makũyũ ma ũkanganĩ, na ĩũlũ wa nyũnyi sya yayaya, na ĩũlũ wa indo, na ĩũlũ wa nthĩ yonthe, na ĩũlũ wa kĩla kasamũ katambũkaa, kala katambũkaa ĩũlũ wa nthĩ.'),
('kam', 'GEN', 1, 27, 'Na Ngaĩ atw’ĩkĩthya mũndũ na mũvw’ano wake, na mũvw’ano wa Ngai amũtw’ĩkĩthya; mũũme na mũka amatw’ĩkĩthya.'),
('kam', 'GEN', 1, 28, 'Na Ngai amaathima: na Ngai amea, Ongelekai, mwingĩve, mu-sũsye nthĩ, na kũmĩkĩlya vinya; na ĩthĩ-wai na ũsumbĩko ĩũlũ wa makũyũ ma ũkanga, na ĩũlũ wa nyũnyi sya yayaya, na ĩũlũ wa kĩla kĩndũ kĩ thayũ kĩendaa ĩũlũ wa nthĩ.'),
('kam', 'GEN', 1, 29, 'Na Ngai asya, Sisya, nĩnĩmũnengete kĩla nyũnyi ĩsyaaa mbeũ, yĩ ĩũlũ wa nthĩ yonthe, na kĩla mũtĩ wĩ ũsyao wa mũtĩ ũsyaaa mbeũ; ũkeethĩwa wĩ lĩu kwenyu:'),
('kam', 'GEN', 1, 30, 'na kĩla nyamũ ya kũũ nthĩ, na kĩla nyũnyi ya yayaya, na kĩla kĩndũ kĩtambũkaa ĩũlũ wa nthĩ, kĩla kĩ thayũ, nĩninengete nyũnyi nziũ syonthe sya ũya: na kweethĩwa ũu.'),
('kam', 'GEN', 1, 31, 'Na Ngai oona kĩla kĩndũ wombie, na, sisya, kyaĩ kĩseo mũno. Na kweethĩwa wĩoo na kweethĩwa kĩoko, mũthenya wa thanthatũ.'),
('kam', 'GEN', 2, 1, 'Na matu na nthĩ syathela kũmbwa, na nguthu yonthe yasyo.'),
('kam', 'GEN', 2, 2, 'Na mũthenya wa mũonza Ngaĩ nĩwaminĩte wĩa wake ũla watethasya; nake athũmũa mũthenya wa mũonza ũndũ wa wĩa wake w’onthe ũla watethasya.'),
('kam', 'GEN', 2, 3, 'Na Ngaĩ aathima mũthenya wa mũonza, na oovathan’ya wĩthĩwe mũtheu; nũndũ nĩw’o wathũmũie ũndũ wa wĩa wake w’onthe ũla Ngai watw’ĩkĩthisye na wombie.'),
('kam', 'GEN', 2, 4, 'Ii nĩ nzyawa sya matu na nthĩ yĩla syatw’ĩkĩthiw’e, mũthenya ũla Yeova Ngai wombie nthĩ na ĩtu.'),
('kam', 'GEN', 2, 5, 'Na kutyaĩ kamũtĩ ka kĩthekanĩ kambĩte kwĩthĩwa nthĩ, o na nyũnyi sya kĩthekanĩ ityambĩte kũmea; nũndũ Yeova Ngai ndauĩtye mbua nthĩ: o na kũtyaĩ mũndũ wa kũĩma nthĩ:'),
('kam', 'GEN', 2, 6, 'ĩndĩ mũumbĩ wambataa kuma nthĩ, na kuasya manzĩ ĩũlũ wa nthĩ yonthe.'),
('kam', 'GEN', 2, 7, 'Na Yeova Ngai oomba mũndũ na kĩtoo kya nthĩ, na amũvevea mĩthũmũ ya thayũ manyiũũnĩ make; na mũndũ atw’ĩka kyuu kĩ thayũ.'),
('kam', 'GEN', 2, 8, 'Na Yeova Ngai avanda mũũnda ngalĩko ya wumĩlonĩ wa syũa, nthĩnĩ wa Etenĩ; na nĩkw’o wamwiie mũndũ ũla wombie.'),
('kam', 'GEN', 2, 9, 'Na Yeova Ngai amesya mũthanganĩ kĩla mũtĩ wendeeasya kwoneka, na mũseo wa kũya; mũtĩ wa thayũ naw’o mũũndanĩ katĩ, na mũtĩ wa kũmanyĩthya ũseo na ũthũku.'),
('kam', 'GEN', 2, 10, 'Na ũsĩ waumĩte Eteni wa kũnyithya mũũnda; na kuma vau wataanĩsya, watw’ĩka mbũsĩ inya.'),
('kam', 'GEN', 2, 11, 'Syĩtwa ya ũla wa mbee nĩ Visoni: nĩw’o ũthyũlũlũkĩte nthĩ yonthe ya Avila, kũla kwĩ thaavu;'),
('kam', 'GEN', 2, 12, 'na thaavu wa nthĩ ĩsu nĩ mũseo: ve veteliumu na tũvila twa nzumalati.'),
('kam', 'GEN', 2, 13, 'Na syĩtwa ya ũsĩ wa kelĩ nĩ Ngioni: nĩw’o ũthyũlũlũkĩte nthĩ yonthe ya Kusi.'),
('kam', 'GEN', 2, 14, 'Na syĩtwa ya ũsĩ wa katatũ nĩ Itekelĩ: nĩw’o ũvĩtĩle mbee wa Asũli. Na ũsĩ wa kana nĩ Euvalati.'),
('kam', 'GEN', 2, 15, 'Na Yeova Ngai oosa mũndũ, na amwia mũũndanĩ wa Eteni oseũvasye na kũsũvĩaa.'),
('kam', 'GEN', 2, 16, 'Na Yeova Ngai amwĩaĩa mũndũ, akĩmwĩa, Wa kĩla mũtĩ wa mũũndanĩ nũtonya ũya o ũndũ ũkwenda:'),
('kam', 'GEN', 2, 17, 'ĩndĩ wa mũtĩ wa kũmanyĩthya ũseo na ũthũku, ndũkaye: nĩkwĩthĩwa mũthenya ũla ũkaya waw’o ndũkatĩa ũkw’a.'),
('kam', 'GEN', 2, 18, 'Na Yeova Ngai asya, Ti ũseo mũndũ ethĩwe e weka; nĩngũmũmbĩa mũtetheesya ũmwaĩle.'),
('kam', 'GEN', 2, 19, 'Na kuma mũthanganĩ Yeova Ngai oombie kĩla nyamũ ya kĩthekanĩ, na kĩla nyũnyi ya yayaya; nake atwaĩa mũndũ one ũndũ wĩsyĩta: na o ũndũ wetie kĩla kyũmbe kĩ thayũ, noyo syĩtwa yakyo.'),
('kam', 'GEN', 2, 20, 'Na mũndũ atw’ĩĩa indo syonthe masyĩtwa, na nyũnyi sya yayaya, na kĩla nyamũ ya kĩthekanĩ; ĩndĩ kwondũ wa ũ mũndũ kũtyaaoneka mũtetheesya ũmwaĩle.'),
('kam', 'GEN', 2, 21, 'Na Yeova Ngai akomethya mũndũ too mũnene, na akoma; nake aumya wau ũmwe wake, na akwantan’ya nyama vandũ vaw’o:'),
('kam', 'GEN', 2, 22, 'na wau, ũla Yeova Ngaĩ waumisye mũndũnĩ, oombie mũndũ mũka, na amũtwaĩa ũ mũndũ.'),
('kam', 'GEN', 2, 23, 'Na mũndũ asya, Ũũ yu nĩ ĩvĩndĩ ya mavĩndĩ makwa, na nyama ya mwĩĩ wakwa: akeetwa Mũndũ mũka, nĩkwĩthĩwa nĩwaumiw’e nthĩnĩ wa Mũndũ mũũme.'),
('kam', 'GEN', 2, 24, 'Kwondũ wa ũu mũndũ mũũme akatia ĩthe na nyinyia, na akalũman’ya na mũka wake: nao makeethĩwa mwĩĩ ũmwe.'),
('kam', 'GEN', 2, 25, 'Na me elĩ maĩ athei, mũndũ mũũme na mũka, na maiaasonoka.'),
('kam', 'GEN', 3, 1, 'Na ĩndĩ nzoka yaĩ nzeleke mũno kwĩ nyamũ o na yĩva ya kĩthekanĩ ĩla Yeova Ngai wombie. Na yamwĩa mũndũ mũka atĩĩ, Nĩ w’o, Ngai nĩwaisye, Mũtikaye ma mĩtĩ yonthe ya mũũndanĩ?'),
('kam', 'GEN', 3, 2, 'Na ĩndĩ mũndũ mũka eea nzoka, Mosyao ma mĩtĩ ya mũũndanĩ nĩtũtonya ũya:'),
('kam', 'GEN', 3, 3, 'ĩndĩ ũsyao wa mũtĩ ũla wĩ katĩ wa mũũnda, Ngai nĩwaisye, Mũĩkaye waw’o, o na mũikakiite, mũikese ũkw’a.'),
('kam', 'GEN', 3, 4, 'Na nzoka yamwia mũndũ mũka, Mũikakw’a nongĩ:'),
('kam', 'GEN', 3, 5, 'nũndũ Ngai nĩwĩsĩ kana mũthenya ũla mũkaya waw’o, nĩvo mũkasalukw’a metho, nenyu mũkeethĩwa ta Ngai, mũkĩmanya ũseo na ũthũku.'),
('kam', 'GEN', 3, 6, 'Na yĩla mũndũ mũka wonie kana mũtĩ nĩ mũseo wa ũya, na nĩ wa kwendeesya methonĩ, na nĩ mũtĩ wa kwendwa kwa kũĩvya mũndũ, atw’a ũsyao waw’o, aya; na ĩngĩ anenga mũũme, nake aya.'),
('kam', 'GEN', 3, 7, 'Na masalukw’a metho moo me elĩ, mamanya nĩ athei; na matuman’ya matũ ma mũkũyũ, meeseũvĩsya ngũa.'),
('kam', 'GEN', 3, 8, 'Na meew’a wasya wa Yeova Ngai aitambũka mũũndanĩ syũa yausya: na mũndũ mũũme na mũka wake meevitha katĩ wa mĩtĩ ya mũũnda Yeova Ngai ndakamone.'),
('kam', 'GEN', 3, 9, 'Na Yeova Ngai eeta ũ mũndũ mũũme, amũkũlya, Ũĩva we?'),
('kam', 'GEN', 3, 10, 'Nake asũngĩa, Nĩneew’a wasya waku mũũndanĩ, na nakĩa, nũndũ nyie nĩĩ mũthei; na neevitha.'),
('kam', 'GEN', 3, 11, 'Nake amũkũlya, Nũũ ũkwĩie wĩĩ mũthei? Nũĩte wa mũti, ũla nakwĩaĩe ndũkaye?'),
('kam', 'GEN', 3, 12, 'Na mũndũ mũũme asũngĩa, Mũndũ mũka ũla wanengie ethĩwe nakwa, nĩwe ũnengie wa mũtĩ, na naya.'),
('kam', 'GEN', 3, 13, 'Na Yeova Ngai akũlya mũndũ mũka, Ũndũ ũũ wĩkie nata? Na mũndũ mũka asũngĩa, Nzoka nĩngengie, na naya.'),
('kam', 'GEN', 3, 14, 'Na Yeova Ngai eea nzoka, Nũndũ nĩwĩkie ũu, nũumanĩwe, we, kwĩ indo syonthe, na kwĩ nyamũ syonthe sya kĩthekanĩ; ũkaendaa na ĩvu, na ũkaĩsaa kĩtoo mĩthenya yonthe ya thayũ waku:'),
('kam', 'GEN', 3, 15, 'na ngeekĩa ũmaitha katĩ wenyu we na mũndũ mũka, na katĩ wa ũsyao waku na ũsyao wake: akatumba mũtwe waku, naku ũkatumba kĩtiinyo kyake.'),
('kam', 'GEN', 3, 16, 'Amwĩa mũndũ mũka, Ngaingĩvya mũno woo waku wa kũsyaa; woonĩ ũkasyaa syana; na kwenda kwaku kũkeethĩwa kwa mũemeu, nake akasumbĩka ĩũlũ waku.'),
('kam', 'GEN', 3, 17, 'Na amwĩa Atamu, Nũndũ, nĩweethukĩĩsye wasya wa mũkau, na ĩngĩ waya wa mũtĩ, ũla nakwĩaĩe, ngĩkwĩa, Ndũkaaye waw’o: nthĩ nĩumanĩwe nũndũ waku; ũkaĩsaa wayo woonĩ matũkũ onthe ma thayũ waku;'),
('kam', 'GEN', 3, 18, 'mĩw’a nayo na thangila ĩkakũmeesya; naku ũkaĩsaa nyũnyi sya mũũndanĩ;'),
('kam', 'GEN', 3, 19, 'yuutĩanĩ ya ũthyũ waku ũkaĩsaa lĩu, kũvika yĩla ũkasyoka mũthanganĩ; nũndũ nĩvo waumiw’e: nũndũ wĩ kĩtoo, na nũkasyoka kĩtoonĩ.'),
('kam', 'GEN', 3, 20, 'Na mũndũ mũũme atw’ĩĩa mũka wake syĩtwa Eva; nũndũ nĩwe inyia wa onthe me thayũ.'),
('kam', 'GEN', 3, 21, 'Na Yeova Ngai amaseũvĩsya Atamu na mũka wake ngũa sya mbũa, na amavw’ĩka.'),
('kam', 'GEN', 3, 22, 'Na Yeova Ngai asya, Sisya, mũndũ nũtw’ĩkĩte ta ũmwe wa ithyĩ, kũmanya ũseo na ũthũku; na yu, ndakese kũtambũũkya kw’oko, ose wa mũtĩ wa thayũ naw’o, na kũya, na kwĩkalaa tene na tene—'),
('kam', 'GEN', 3, 23, 'kwondũ wa ũu Yeova Ngai amumya mũũndanĩ wa Eteni, aĩme nthĩ vala waumiw’e.'),
('kam', 'GEN', 3, 24, 'Na ĩndĩ alũngya ũla mũndũ; na aia ngalĩ ya wumĩlonĩ wa syũa ya mũũnda wa Eteni Akeluvi, na ũlĩlĩnzĩku wa ũvyũ ũla weethyũũaa ngalĩko syonthe, kũsũvĩaa nzĩa ya mũtĩ wa thayũ.'),
('kam', 'GEN', 4, 1, 'Na Atamu amanya Eva mũka wake; nake aya ĩvu, na asyaa Kaini, asya, Nĩnoosa mũndũ mũũme kwa kũtethw’a nĩ Yeova.'),
('kam', 'GEN', 4, 2, 'Na ĩngĩ asyaa mwana‐a‐inyia Aveli. Na Aveli aĩ mũĩthi wa malondu, ĩndĩ Kaini aĩ mũĩmi wa nthĩ.'),
('kam', 'GEN', 4, 3, 'Na kweethĩwa matukũ amwe mathela, Kaini aetee Yeova nthembo ya ũsyao wa nthĩ.'),
('kam', 'GEN', 4, 4, 'Nake Aveli aete mosyao ma mbee ma ĩĩthya yake na mathunya mamo. Na Yeova eetĩkĩla Aveli na nthembo yake:'),
('kam', 'GEN', 4, 5, 'ĩndĩ ndaaĩtĩkĩla Kaini na nthembo yake. Na Kaini aĩ mũthilĩku mũno, na aluta ũthyũ wake.'),
('kam', 'GEN', 4, 6, 'Na Yeova amwĩa Kaini, Ũthilĩkĩte nĩkĩ? Na ũlutĩte ũthyũ nĩkĩ?'),
('kam', 'GEN', 4, 7, 'Weeka nesa, ndwĩĩtĩkĩlwa? Na ethĩwa ndwĩĩka nesa, naĩ yovesyaa mũomonĩ; na kwenda kwayo kũkeethĩwa kwaku; ĩndĩ naku ũmĩsumbĩke.'),
('kam', 'GEN', 4, 8, 'Na Kaini aneena na mwana‐a‐inyia Aveli. Na kweethĩwa, yĩla maĩ kĩsesinĩ, Kaini amũkĩlĩla mwana‐a‐inyia Aveli, na amũaa.'),
('kam', 'GEN', 4, 9, 'Na Yeova akũlya Kaini, Aĩva Aveli, mwana‐a‐mwenyu? Nake asũngĩa, ndyĩsĩ: ninyie mũsũvĩi wa mwana‐a‐ia?'),
('kam', 'GEN', 4, 10, 'Nake akũlya, Wĩkie ata? Wasya wa nthakame ya mwana‐a‐mwenyu nũĩngaĩla kuma nthĩ.'),
('kam', 'GEN', 4, 11, 'Na yu ĩndĩ nũumanĩwe kuma nthĩ, ĩla yathamisye kanyw’a wayo kwosa nthakame ya mwana‐a‐mwenyu kuma kw’okonĩ kwaku;'),
('kam', 'GEN', 4, 12, 'ũkĩĩma nthĩ, ndĩkakũnengae ĩngĩ vinya wayo; ũkeethĩwa mũkĩi na mwangangi kũũ nthĩ.'),
('kam', 'GEN', 4, 13, 'Na Kaini amũsũngĩa Yeova, Kũsilĩlwa kwakwa nĩ kũnene mbee wa ũndũ ndonya kũmĩĩsya.'),
('kam', 'GEN', 4, 14, 'Sisya, ũmũnthĩ nĩwandũngya kuma ĩũlũ wa nthĩ; o na ũthyũnĩ waku ngavithĩka; na ngeethĩwa mũkĩi na mwangangi, kũũ nthĩ; na kũkeethĩwa, o ũla ũkambĩthĩa nũkambũaa.'),
('kam', 'GEN', 4, 15, 'Na Yeova amwĩa, Kwondũ wa ũu o ũla ũkoaa Kaini, nũkaĩvanĩw’a kũndũ mũonza. Na Yeova amwĩkĩa Kaini ũvano, kana o ũla ũkamwĩthĩa ndakaamũae.'),
('kam', 'GEN', 4, 16, 'Na Kaini auma mbee wa Yeova, na atũa nthĩ ya Noti, ngalĩ ya wumĩlonĩ wa syũa ya Eteni.'),
('kam', 'GEN', 4, 17, 'Na Kaini amanya mũka wake; nake aya ĩvu, na asyaa Enoko: na aaka ndũa, na eeta syĩtwa ya ndũa, o ta syĩtwa ya mwana wake, Enoko.'),
('kam', 'GEN', 4, 18, 'Na Enoko asyaa Ilati; na Ilati asyaa Meuyaeli; na Meuyaeli asyaa Methusaeli; na Methusaeli asyaa Lameki.'),
('kam', 'GEN', 4, 19, 'Na Lameki atwaa aka elĩ; syĩtwa ya ũmwe eetawa Ata, na syĩtwa ya ũla ũngĩ eetawa Nzila.'),
('kam', 'GEN', 4, 20, 'Na Ata asyaa Yavali: nĩwe ĩthe wa ala matũaa maeemanĩ na me indo.'),
('kam', 'GEN', 4, 21, 'Na syĩtwa ya mwana‐a‐inyia eetawa Yuvali: nĩwe ĩthe wa onthe ala makwataa mbeve na mũtũlilũ.'),
('kam', 'GEN', 4, 22, 'Na Nzila nake asyaa Tuvali‐kaini, nĩwe mũmanyĩsya wa atwii onthe ma mĩio myũĩ ya ũthuku na kĩaa: na mwĩĩtu‐a‐inyia wa Tuvali‐kaini aĩ Naama.'),
('kam', 'GEN', 4, 23, 'Na Lameki amea aka make: Ata na Nzila, ĩw’ai wasya wakwa; Inyw’ĩ aka ma Lameki, ĩthukĩĩsyei kũneena kwakwa: Nũndũ nĩnooaa mũndũ nũndũ wa ũngũna, O na mwanake nũndũ wa ũndumba:'),
('kam', 'GEN', 4, 24, 'Ethĩwa Kaini akaĩvanĩw’a kũndũ mũonza, Nĩ w’o Lameki nĩ kũndũ mĩongo mũonza na mũonza.'),
('kam', 'GEN', 4, 25, 'Na Atamu amanya mũka ĩngĩ; nake asyaa mwana, na amwĩta syĩtwa yake Sethi: akyasya, Nũndũ Ngai nũmbiĩe ũsyao ũngĩ vandũ va Aveli; nũndũ Kaini nĩwamũaie.'),
('kam', 'GEN', 4, 26, 'Na Sethi o nake asyaĩwa mwana; amwĩta syĩtwa yake Enosi. Ĩvinda yĩu andũ mambĩlĩlya kwĩkaĩla syĩtwa ya Yeova.'),
('kam', 'GEN', 5, 1, 'Yĩĩ nĩyo ĩvuku ya mosyaanĩo ma Atamu. Mũthenya ũla Ngai watw’ĩkĩthisye mũndũ, amũmbie na kĩtutya kya Ngai;'),
('kam', 'GEN', 5, 2, 'mũũme na mũka amatw’ĩkĩthya, na amaathima, na ameta syĩtwa yoo Atamu, mũthenya ũla wamatw’ĩkĩthisye.'),
('kam', 'GEN', 5, 3, 'Na Atamu ekala myaka ĩana na mĩongo ĩtatũ, na asyaa mwana ũmũtutĩtye, e na mũvw’ano wake; na amwĩta syĩtwa yake Sethi:'),
('kam', 'GEN', 5, 4, 'na matukũ ma Atamu ĩtina wa kũsyaa Sethi maĩ myaka maana nyanya: o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 5, 5, 'Na matukũ onthe ala Atamu wekalile maĩ myaka maana kenda na mĩongo ĩtatũ: na akw’a.'),
('kam', 'GEN', 5, 6, 'Na Sethi ekala myaka ĩana na ĩtano, na asyaa Enosi:'),
('kam', 'GEN', 5, 7, 'na Sethi ekala ĩtina wa kũsyaa Enosi myaka maana nyanya na mũonza, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 8, 'na matukũ onthe ma Sethi maĩ myaka maana kenda na ĩkũmi na ĩlĩ: na akw’a.'),
('kam', 'GEN', 5, 9, 'Na Enosi ekala myaka mĩongo kenda, na asyaa Kenani:'),
('kam', 'GEN', 5, 10, 'na Enosi ekala ĩtina wa kũsyaa Kenani myaka maana nyanya na ĩkũmi na ĩtano, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 11, 'na matukũ onthe ma Enosi maĩ myaka maana kenda na ĩtano: na akw’a.'),
('kam', 'GEN', 5, 12, 'Na Kenani ekala myaka mĩongo mũonza, na asyaa Maalaleli:'),
('kam', 'GEN', 5, 13, 'na Kenani ekala ĩtina wa kũsyaa Maalaleli myaka maana nyanya na mĩongo ĩna, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 14, 'na matukũ onthe ma Kenani maĩ myaka maana kenda na ĩkũmi: na akw’a.'),
('kam', 'GEN', 5, 15, 'Na Maalaleli ekala myaka mĩongo thanthatũ na ĩtano, na asyaa Yaleti:'),
('kam', 'GEN', 5, 16, 'na Maalaleli ekala ĩtina wa kũsyaa Yaleti myaka maana nyanya na mĩongo ĩtatũ, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 17, 'na matukũ onthe ma Maalaleli maĩ myaka maana nyanya na mĩongo kenda na ĩtano: na akw’a.'),
('kam', 'GEN', 5, 18, 'Na Yaleti ekala myaka ĩana na mĩongo thanthatũ na ĩlĩ, na asyaa Enoko:'),
('kam', 'GEN', 5, 19, 'na Yaleti ekala ĩtina wa kũsyaa Enoko myaka maana nyanya, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 20, 'na matukũ onthe ma Yaleti maĩ myaka maana kenda na mĩongo thanthatũ na ĩlĩ: na akw’a.'),
('kam', 'GEN', 5, 21, 'Na Enoko ekala myaka mĩongo thanthatũ na ĩtano, na asyaa Methusela:'),
('kam', 'GEN', 5, 22, 'na Enoko aendanasya na Ngai ĩtina wa kũsyaa Methusela myaka maana atatũ, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 23, 'na matikũ onthe ma Enoko maĩ myaka maana atatũ na mĩongo thanthatũ na ĩtano:'),
('kam', 'GEN', 5, 24, 'na Enoko aendanasya na Ngai: na ndaĩ vo; nũndũ Ngai nĩwamwosie.'),
('kam', 'GEN', 5, 25, 'Na Methusela ekala myaka ĩana na mĩongo nyanya na mũonza, na asyaa Lameki:'),
('kam', 'GEN', 5, 26, 'na Methusela ekala ĩtina wa kũsyaa Lameki myaka maana mũonza na mĩongo nyanya na ĩlĩ, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 27, 'na matukũ onthe ma Methusela maĩ myaka maana kenda na mĩongo thanthatũ na kenda: na akw’a.'),
('kam', 'GEN', 5, 28, 'Na Lameki ekala myaka ĩana na mĩongo nyanya na ĩlĩ, na asyaa mwana:'),
('kam', 'GEN', 5, 29, 'na amwĩta syĩtwa yake Noa, akyasya, Nĩwe ũkatũkiakisya wĩanĩ wĩtũ na thĩnanĩ wa moko maitũ, kwondũ wa nthĩ ĩla Yeova waumanĩe.'),
('kam', 'GEN', 5, 30, 'Na Lameki ekala ĩtina wa kũsyaa Noa myaka maana atano na mĩongo kenda na ĩtano, o akĩsyaa ana na eĩtu:'),
('kam', 'GEN', 5, 31, 'na matukũ onthe ma Lameki maĩ myaka maana mũonza na mĩongo mũonza na mũonza: na akw’a.'),
('kam', 'GEN', 5, 32, 'Na Noa aĩ wa myaka maana atano: na Noa asyaa Semu na Amu na Yavethi.'),
('kam', 'GEN', 6, 1, 'Na kweethĩwa, yĩla andũ mambĩlĩlye kwĩngiva ĩũlũ wa nthĩ, na masyaĩwa eĩtu,'),
('kam', 'GEN', 6, 2, 'ana ma Ngai moona kana eĩtu ma andũ maĩ aseo; na meetwaĩa aka, onthe ala manyuvie.'),
('kam', 'GEN', 6, 3, 'Na Yeova asya, Veva wakwa ndakakĩlan’ya vinya na mũndũ tene na tene, nũndũ we nake nĩ mwĩĩ: ĩndĩ matukũ make makeethĩwa myaka ĩana na mĩongo ĩlĩ.'),
('kam', 'GEN', 6, 4, 'Nevilimu maĩ kũũ nthĩ matukũ asu, o na ĩtina wa ĩvinda yĩu, yĩla ana ma Ngai malikile kwa eĩtu ma andũ, na mamasyaĩa syana: syo syaĩ ngũmbaũ tene, andũ me nguma.'),
('kam', 'GEN', 6, 5, 'Na Yeova oona kana ũthũku wa mũndũ waĩ mũnene kũũ nthĩ, na kĩla kĩsũanĩo kya malilikano ma ngoo yake kyaĩ kyathe vyũ mavinda onthe.'),
('kam', 'GEN', 6, 6, 'Na Yeova eelila nũndũ nĩwombie mũndũ ĩũlũ wa nthĩ, na eew’ĩthw’a woo ngoonĩ yake.'),
('kam', 'GEN', 6, 7, 'Na Yeova asya, Ngaananga mũndũ ũla natw’ĩkĩthisye aume ĩũlũ wa nthĩ; mũndũ, vamwe na nyamũ, na kĩla kasamũ katambũkaa, na nyũnyi sya yayaya; nĩkwĩthĩwa nĩngwĩlila nũndũ nĩnasyũmbie.'),
('kam', 'GEN', 6, 8, 'Ĩndĩ Noa nĩwendeesye mbee wa Yeova.'),
('kam', 'GEN', 6, 9, 'Mosyaanĩo ma Noa nĩmo aa. Noa aĩ mũndũ mũlũngalu, na mwĩanĩu nzyawanĩ sya ĩvinda yake: Noa aendanasya na Ngai.'),
('kam', 'GEN', 6, 10, 'Na Noa asyaa ana atatũ, Semu na Amu na Yavethi.'),
('kam', 'GEN', 6, 11, 'Na nthĩ yaĩ nthũku mbee wa Ngai, na nthĩ yausũĩte ũng’endu.'),
('kam', 'GEN', 6, 12, 'Na Ngai oona nthĩ, na, sisya, yaĩ nthũku; nũndũ mĩĩ yonthe nĩyathũkisye nzĩa yoo ĩũlũ wa nthĩ.'),
('kam', 'GEN', 6, 13, 'Na Ngai amwĩa Noa, Mũminũkĩlyo wa mĩĩ yonthe nĩwooka mbee wakwa; nũndũ nthĩ nĩyusũĩtwe nĩ ũng’endu kwondũ woo; na, sisya, ngamananga vamwe na nthĩ.'),
('kam', 'GEN', 6, 14, 'Ĩyakĩe ngalawa ya mũtĩ wa mũkova; na ũtilanga tũsũmba ngalawanĩ, na ũivaka ngalĩ ya nthĩnĩ na ngalĩ ya nza kĩsia.'),
('kam', 'GEN', 6, 15, 'Na ũũ nĩw’o wĩaka: ũasa wa ngalawa mĩkono maana atatũ, na ũthanthau wayo mĩkono mĩongo ĩtano, na ũtũlu wayo mĩkono mĩongo ĩtatũ.'),
('kam', 'GEN', 6, 16, 'Ũkaseũvye vandũ va kũete kyenĩ ngalawanĩ, na ũkaseũvye va mũkono ũmwe kuma ĩũlũ; na mũomo wa ngalawa ũkekĩe ũteenĩ wayo; nyũmba ya nthĩ, na ya katĩ, na ya ĩũlũ, nĩw’o wĩseũvya.'),
('kam', 'GEN', 6, 17, 'Nakwa, sisya, nĩngũete kĩw’ũ kingĩ ĩũlũ wa nthĩ, kyanange mĩĩ yonthe, yĩ na mĩvevo ya thayũ nthĩnĩ wayo, ungu wa ĩtu, kyonthe kĩla kĩ kũũ nthĩ kĩkakw’a.'),
('kam', 'GEN', 6, 18, 'Ĩndĩ ngalũlũmĩlya ũtianĩo wakwa naku; naku ũkalika ngalawanĩ, we, na ana maku, na mũkau, na aka ma ana maku vamwe naku.'),
('kam', 'GEN', 6, 19, 'Na kĩla kĩndũ kĩ thayũ kya mĩĩ yonthe, ilĩ sya kĩla mũthemba ũkaete nthĩnĩ wa ngalawa, kũsyĩkalya thayũ vamwe naku; ikeethĩwa nũme na nga.'),
('kam', 'GEN', 6, 20, 'Nyũnyi o mũthemba wasyo, na indo o mũthemba wasyo, na kĩla kasamũ katambũkaa ka nthĩ o mũthemba wako, ili sya kĩla mũthemba w’onthe ikakũkĩa, ũsyĩkalye thayũ.'),
('kam', 'GEN', 6, 21, 'Naku ũkeyosee lĩu w’onthe ũla ũĩsawa, wĩyũmbanĩsye; na ũkeethĩwa wĩ lĩu waku, na wasyo.'),
('kam', 'GEN', 6, 22, 'Noa eeka ũu; kwĩanana na w’onthe ũla Ngai wamwĩaĩe, nĩw’o wekie.'),
('kam', 'GEN', 7, 1, 'Na Yeova amwĩa Noa, Lika, we, na andũ maku onthe ngalawanĩ; nũndũ we nĩngwonete wĩ mũlũngalu mbee wakwa nzyawanĩ ĩno.'),
('kam', 'GEN', 7, 2, 'Sya kĩla nyamũ ntheu ũkeyosee mũonza, mũonza, nũme na nga yayo; na sya nyamũ ila ite ntheu ilĩ, nũme na nga yayo:'),
('kam', 'GEN', 7, 3, 'na ĩngĩ sya nyũnyi sya yayaya, mũonza, mũonza, nũme na nga, kwĩkalya ũsyao wĩ thayũ ĩũlũ wa nthĩ yonthe.'),
('kam', 'GEN', 7, 4, 'Nũndũ vatiele matukũ mũonza, na ĩndĩ ngausya mbua nthĩ mĩthenya mĩongo ĩna na matukũ mĩongo ĩna; na kyonthe kĩ thayũ kĩla noombie ngaananga vyũ kuma ĩũlũ wa nthĩ.'),
('kam', 'GEN', 7, 5, 'Na Noa eeka w’onthe ũla Yeova wamwĩaĩe.'),
('kam', 'GEN', 7, 6, 'Nake Noa aĩ wa myaka maana thanthatũ yĩla kĩla kĩw’ũ kingĩ kyai ĩũlũ wa nthĩ.'),
('kam', 'GEN', 7, 7, 'Na Noa alika ngalawanĩ, we, na ana make, na mũka wake, na aka ma ana make, nũndũ wa manzĩ ma kĩla kĩw’ũ kingĩ.'),
('kam', 'GEN', 7, 8, 'Syalika sya nyamũ ntheu, na sya nyamũ ite ntheu, na sya nyũnyi, na sya kĩla kĩndũ kĩtambũkaa ĩũlũ wa nthĩ,'),
('kam', 'GEN', 7, 9, 'ilĩ, ilĩ ngalawanĩ kwa Noa, nũme na nga, o tondũ Ngai weaĩe Noa.'),
('kam', 'GEN', 7, 10, 'Na kweethĩwa ĩtina wa mĩthenya ĩsu mũonza, manzĩ ma kĩla kĩw’ũ kingĩ meethĩwa ĩũlũ wa nthĩ.'),
('kam', 'GEN', 7, 11, 'Mwaka wa maana thanthatũ wa thayũ wa Noa, mwei wa kelĩ, mũthenya wa ĩkũmi na mũonza wa mwei, mũthenya o ũsu kwavingũka nthongo syonthe sya kyũngũ kyu kĩnene, na mbũthĩ sya ĩtu syavingũka.'),
('kam', 'GEN', 7, 12, 'Na kweethĩwa mbua ĩũlũ wa nthĩ mĩthenya mĩongo ĩna na matukũ mĩongo ĩna.'),
('kam', 'GEN', 7, 13, 'Mũthenya o ũsu malika ngalawanĩ Noa, na Semu na Amu na Yavethĩ, ana ma Noa, na mũka wa Noa, na aka atatũ ma ana make vamwe nao;'),
('kam', 'GEN', 7, 14, 'mo na kĩla nyamũ o mũthemba wayo, na indo syonthe o mũthemba wasyo, na kĩla kasamũ katambũkaa, kala katambũkaa ĩũlũ wa nthĩ o mũthemba wako, na kĩla nyũnyi o mũthemba wayo, kĩla nyũnyi ya kĩla mũthemba.'),
('kam', 'GEN', 7, 15, 'Na syalika kwa Noa ngalawanĩ, ilĩ, ilĩ sya mĩĩ yonthe ĩla yĩ na mĩthũmũ ya thayũ.'),
('kam', 'GEN', 7, 16, 'Na ila syalikile, syalika nũme na nga sya mĩĩ yonthe, o tondũ Ngai wamwĩaĩe: na Yeova amũvingĩa nthĩnĩ.'),
('kam', 'GEN', 7, 17, 'Na kĩla kĩw’ũ kingĩ kyeethĩwa ĩũlũ wa nthĩ matukũ mĩongo ĩna; na manzĩ mongeleka, na mookĩlya ngalawa, na yookĩlĩtw’e ĩũlũ wa nthĩ.'),
('kam', 'GEN', 7, 18, 'Na manzĩ makĩlya vinya, na mongeleka mũno ĩũlũ wa nthĩ; na ngalawa yaendaa ĩũlũ wa manzĩ.'),
('kam', 'GEN', 7, 19, 'Na manzĩ makĩlya vinya mũno mũnene ĩũlũ wa nthĩ; na iĩma syonthe ndũlu ila syaĩ ungu wa ĩtu yonthe syavw’ĩkwa.'),
('kam', 'GEN', 7, 20, 'Manzĩ makĩlya vinya kwambata ĩũlũ mĩkono ĩkũmi na ĩtano; na iĩma syavw’ĩkwa.'),
('kam', 'GEN', 7, 21, 'Na mĩĩ yonthe yakw’a ĩla ĩendaa ĩũlũ wa nthĩ, nyũnyi, o na indo, na nyamũ, na kĩla kasamũ katambũkaa, kala katambũkaa ĩũlũ wa nthĩ, na kĩla mũndũ:'),
('kam', 'GEN', 7, 22, 'syonthe ila syaĩ na mĩthũmũ ya veva wa thayũ manyiũũnĩ masyo, sya syonthe ila syaĩ mũthanganĩ mũmũ, syakw’a.'),
('kam', 'GEN', 7, 23, 'Na kĩla kĩndũ kyaĩ thayũ ĩũlũ wa nthĩ kyaanangwa, andũ, o na indo, na tũsamũ tũla tũtambũkaa, na nyũnyi sya yayaya; na nĩsyanangiwe kuma nthĩ: no Noa watiiwe, na ala maĩ nake ngalawanĩ.'),
('kam', 'GEN', 7, 24, 'Na manzĩ makĩlya vinya ĩũlũ wa nthĩ matukũ ĩana na mĩongo ĩtano.'),
('kam', 'GEN', 8, 1, 'Na Ngai alilikana Noa, na nyamũ syonthe, na indo syonthe ila syaĩ nake ngalawanĩ: na Ngai avĩtĩlya kĩseve ĩũlũ wa nthĩ, na manzĩ manyivanga;'),
('kam', 'GEN', 8, 2, 'nasyo nthongo sya kyũngũ kyu na mbũthi sya ĩtunĩ syavingwa, na mbua kuma ĩtunĩ yasiĩĩwa;'),
('kam', 'GEN', 8, 3, 'na manzĩ maendeea na kũolekanga nthĩ: na mũminũkĩlyo wa matukũ ĩana na mĩongo ĩtano manzĩ manyiva.'),
('kam', 'GEN', 8, 4, 'Na mwei wa mũonza, mũthenya wa ĩkũmi na mũonza wa mwei, ngalawa yekala ĩũlũ wa iĩma sya Alalati.'),
('kam', 'GEN', 8, 5, 'Na manzĩ maendeea na kũnyiva kũvika mwei wa ĩkũmi; na mwei wa ĩkũmi, mũthenya wa mbee wa mwei, mĩthya ya iĩma yooneka.'),
('kam', 'GEN', 8, 6, 'Na kweethĩwa mũminũkĩlyo wa matukũ mĩongo ĩna, Noa avingũa mbũthi ya ngalawa ĩla waseũvisye:'),
('kam', 'GEN', 8, 7, 'na aumya ngũngũũ, nayo yathi kũũ na kũũ, mũvaka yĩla manzĩ mang’alile ĩũlũ wa nthĩ.'),
('kam', 'GEN', 8, 8, 'Na aumya ĩvũĩ vala ũĩ, amanye kana manzĩ nĩmanyivĩte ĩũlũ wa nthĩ;'),
('kam', 'GEN', 8, 9, 'ĩndĩ ĩvũĩ yĩtyaona ũthũmũo wa kĩlata kyayo, na yamũsyokea ngalawanĩ; nũndũ manzĩ maĩ ĩũlũ wa nthĩ yonthe: na atambũũkya kw’oko, ayosa, ayĩlikya vala ũĩ ngalawanĩ.'),
('kam', 'GEN', 8, 10, 'Na ekalanga ĩngĩ matukũ angĩ mũonza; na aumya ĩngĩ yĩla ĩvũĩ ngalawanĩ;'),
('kam', 'GEN', 8, 11, 'na ĩvũĩ yamũsyokea wĩoo; na, sisya, kanyw’anĩ wayo ĩtũ ya mũthata yĩtw’ĩte; na ĩndĩ Noa amanya kana manzĩ nĩmanyivĩte kuma nthĩ.'),
('kam', 'GEN', 8, 12, 'Na ekalanga ĩngĩ matukũ angĩ mũonza, na aumya yĩla ĩvũĩ; na yĩtyaamũsyokea ĩngĩ nongi.'),
('kam', 'GEN', 8, 13, 'Na kweethĩwa mwaka wa maana thanthatũ na ũmwe, mwei wa mbee, mũthenya wa mbee wa mwei, manzĩ nĩmang’alĩte kuma nthĩ: na Noa athasya vandũ ngalawanĩ ĩũlũ, na oona, na, sĩsya, ĩũlũ wa nthĩ nĩkũnyiaĩte.'),
('kam', 'GEN', 8, 14, 'Na mwei wa kelĩ, mũthenya wa mĩongo ĩlĩ na mũonza wa mwei, nthĩ yaĩ nyũmũ.'),
('kam', 'GEN', 8, 15, 'Na Ngai aneena na Noa, akĩmwĩa,'),
('kam', 'GEN', 8, 16, 'Uma ngalawanĩ, we, na mũkau, na ana maku, na aka ma ana maku vamwe naku.'),
('kam', 'GEN', 8, 17, 'Vamwe naku umya kĩla kĩ thayũ kyonthe kĩ vamwe naku kya mĩĩ yonthe, nyũnyi, o na indo, na kĩla kĩtambũkaa kyonthe, kĩla kĩtambũkaa ĩũlũ wa nthĩ; nĩ kana isyaanĩe mũno nthĩ, na kwongeleka, na kwingĩva ĩũlũ wa nthĩ.'),
('kam', 'GEN', 8, 18, 'Na Noa aumaala, na ana make, na mũka wake, na aka ma ana make vamwe nake:'),
('kam', 'GEN', 8, 19, 'na kĩla nyamũ, na kĩla kasamũ katambũkaa, na kĩla nyũnyi, o kĩla kĩendaa ĩũlũ wa nthĩ, o mĩthemba yasyo, syauma ngalawanĩ.'),
('kam', 'GEN', 8, 20, 'Na Noa aakĩa Yeova kĩthembeo, na oosa ya kĩla nyamũ ntheu, na kĩla nyũnyi ntheu, na athemba nthembo sya kũvĩvw’a kĩthembeonĩ.'),
('kam', 'GEN', 8, 21, 'Na Yeova eew’a mũuke mũseo; na Yeova asya ngoonĩ yake, Ndĩkaumanĩa nthĩ ĩngĩ nongi kwondũ wa mũndũ, nũndũ kĩsũanĩo kya ngoo ya mũndũ nĩ kĩthũku kuma wana wake; o na ndikakũna ĩngĩ kyonthe kĩla kĩ thayũ, tondũ nĩkĩte.'),
('kam', 'GEN', 8, 22, 'Ĩvinda yĩla nthĩ ĩĩkalaa, kũvanda na kũketha, na mbevo na muutĩa, na ĩvinda ya syũa na ĩvinda ya mbevo, na mũthenya na ũtukũ itikathela.'),
('kam', 'GEN', 9, 1, 'Na Ngai aathima Noa na ana make, na amea, Ongelekai, mwingĩve, na mũyusũsya nthĩ.'),
('kam', 'GEN', 9, 2, 'Na kũkĩwa kwenyu na kwĩw’ĩwa w’ĩa kwenyũ kũkeethĩwa ĩũlũ wa kĩla nyamũ ya nthĩ, na ĩũlũ wa kĩla nyũnyi ya yayaya; nasyo syonthe ila syusũĩte nthĩ, na makũyũ onthe ma ũkanganĩ, ninenganĩtwe mokonĩ menyu.'),
('kam', 'GEN', 9, 3, 'Kĩla kĩndũ kĩendaa kĩ thayũ kĩkeethĩwa lĩu kwenyu; o ta nyũnyi nziũ nĩnĩmũnengete syonthe.'),
('kam', 'GEN', 9, 4, 'Ĩndĩ nyama ĩ na thayũ wayo, nĩw’o nthakame yayo, mũtikaye.'),
('kam', 'GEN', 9, 5, 'Na vate ndĩi nthakame yenyu, nthakame ya mathayũ menyu, ngaandũa; kw’okonĩ kwa kĩla nyamũ ngaandũa: na kw’okonĩ kwa mũndũ, o kw’okonĩ kwa mwana‐a‐inyia wa kĩla mũndũ, ngaandũa thayũ wa mũndũ.'),
('kam', 'GEN', 9, 6, 'Ũla ũketa nthakame ya mũndũ, nthakame yake ĩketwa nĩ mũndũ: nũndũ mũvw’anonĩ wa Ngaĩ nĩwombie mũndũ.'),
('kam', 'GEN', 9, 7, 'Nenyu, ongelekai, mwingĩve; syaanai mũno kũũ nthĩ, na mũyingĩva ĩũlũ wayo.'),
('kam', 'GEN', 9, 8, 'Na Ngai aneena na Noa, na ana make vamwe nake, akĩmea,'),
('kam', 'GEN', 9, 9, 'Nakwa, sisya, nĩngũlũlũmĩlya ũtianĩo wakwa nenyu, na ũsyao wenyu ĩtina wenyu;'),
('kam', 'GEN', 9, 10, 'o na kĩla kyũmbe kĩ thayũ kĩ vamwe nenyu, na nyũnyi, na indo, na kĩla nyamũ ya nthĩ vamwe nenyu; syonthe ila syumĩte ngalawanĩ, o kĩla nyamũ ya nthĩ.'),
('kam', 'GEN', 9, 11, 'Na ngalũlũmĩlya ũtianĩo wakwa nenyu; o na mĩĩ yonthe ndĩkanangwa ĩngĩ nĩ manzĩ ma kĩla kĩw’ũ kingĩ; o na kũikethĩwa kĩw’ũ kingĩ ĩngĩ, kya kwananga nthĩ.'),
('kam', 'GEN', 9, 12, 'Na Ngai asya, Ũũ nĩw’o ũvano wa ũtianĩo ũla ngũtianĩa katĩ wakwa nenyu na kĩla kĩndũ kĩ thayũ kĩ vamwe nenyu, nzyawa na nzyawa:'),
('kam', 'GEN', 9, 13, 'nyie nĩngwia ũtaathi wakwa ĩthweonĩ, naw’o ũkeethĩwa ũvano wa ũtianĩo katĩ wakwa na nthĩ.'),
('kam', 'GEN', 9, 14, 'Na kũkeethĩwa, yĩla ngaete ĩthweo ĩũlũ wa nthĩ, ũtaathĩ ũkoonekaa ĩthweonĩ,'),
('kam', 'GEN', 9, 15, 'nakwa ngalilikana ũtianĩo wakwa, ũla wĩ katĩ wakwa nenyu na kĩla kyũmbe kĩ thayũ kya mĩĩ yonthe; na manzĩ maikethĩwa kĩla kĩw’ũ kingĩ ĩngĩ kya kwananga mĩĩ yonthe.'),
('kam', 'GEN', 9, 16, 'Na ũtaathi ũkeethĩwa ĩthweonĩ; nakwa ngoosisya, nĩ kana nĩlilikanae ũtianĩo wa tene na tene ũla wĩ katĩ wa Ngai na kĩla kyũmbe kĩ thayũ kya mĩĩ yonthe kĩ ĩũlũ wa nthĩ.'),
('kam', 'GEN', 9, 17, 'Na Ngai amwĩa Noa, Ũsu nĩ ũvano wa ũtianĩo ũla nalũlũmĩlya katĩ wakwa na mĩĩ yonthe ĩla yĩ ĩũlũ wa nthĩ.'),
('kam', 'GEN', 9, 18, 'Na ana ma Noa, ala maumie ngalawanĩ, nĩ Semu na Amu na Yavethi: na Amu nĩ ĩthe wa Kanaani.'),
('kam', 'GEN', 9, 19, 'Asu atatũ nĩo ana ma Noa: na nũndũ wa asu nthĩ yonthe yausũa.'),
('kam', 'GEN', 9, 20, 'Na Noa ambĩlĩlya kwĩthĩwa mũĩmi, na avanda mũũnda mĩsavivũ:'),
('kam', 'GEN', 9, 21, 'na anyw’a mbinyu, akwatwa nĩyo: na eethĩwa evuĩte e ĩeemanĩ yake.'),
('kam', 'GEN', 9, 22, 'Na Amu, ĩthe wa Kanaani, oona ĩthe wake e mũthei, na atavya ana‐a‐inyia make elĩ me nza.'),
('kam', 'GEN', 9, 23, 'Na Semu na Yavethi moosa ngũa, mailĩĩla ituonĩ syoo me elĩ, na mathi na kyamũtete, mavw’ĩka ĩthe woo e mũthei; na mothyũ moo melekele ĩtina, na matyaona ĩthe woo e mũthei.'),
('kam', 'GEN', 9, 24, 'Na Noa aamũka kuma mbinyunĩ yake, na amanya ũndũ wĩkiwe nĩ mwana wake ũla mũnini.'),
('kam', 'GEN', 9, 25, 'Nake asya, Naumanĩwe Kanaani; Mũthũkũmi wa athũkũmi akeethĩwa kwa ana‐a‐inyia make.'),
('kam', 'GEN', 9, 26, 'Na asya, Nataĩwe Yeova, Ngai wa Semu; Na Kanaani nĩethĩwe mũthũkũmi wake,'),
('kam', 'GEN', 9, 27, 'Ngai anenevye Yavethi, Nake nĩekale maeemanĩ ma Semu; Na Kanaani nĩethĩwe mũthũkũmi wake.'),
('kam', 'GEN', 9, 28, 'Na Noa ekala ĩtina wa kĩla kĩw’ũ kingĩ myaka maana atatũ na mĩongo ĩtano.'),
('kam', 'GEN', 9, 29, 'Na matukũ onthe ma Noa maĩ myaka maana kenda na mĩongo ĩtano: na akw’a.'),
('kam', 'GEN', 10, 1, 'Na ĩndĩ aa nĩo mosyaanĩo ma ana ma Noa, ma Semu na Amu na Yavethi: na masyaĩwa ana ĩtina wa kĩla kĩw’ũ kingĩ.'),
('kam', 'GEN', 10, 2, 'Ana ma Yavethi: Ngomeli, na Makoki, na Matai, na Yavani, na Tuvali, na Meseki, na Tilasi.'),
('kam', 'GEN', 10, 3, 'Na ana ma Ngomeli: Asikenasi, na Livathi, na Tokalima.'),
('kam', 'GEN', 10, 4, 'Na ana ma Yavani: Elisaa, na Talisisi, na Kitimu, na Alotani.'),
('kam', 'GEN', 10, 5, 'Na kwa asu ithama sya mbaĩ syaaanw’a katĩ wa nthĩ syoo, kĩla ũmwe na kĩthyomo kyake, kũatĩĩa mĩvĩa yoo, mbaĩnĩ syoo.'),
('kam', 'GEN', 10, 6, 'Na ana ma Amu: Kusi, na Misili, na Vutu, na Kanaani.'),
('kam', 'GEN', 10, 7, 'Na ana ma Kusi: Seva, na Avila, na Savita, na Laama, na Saviteka; na ana ma Laama: Sieva, na Ndetani.'),
('kam', 'GEN', 10, 8, 'Na Kusi asyaa Nimiloti: ambĩlĩlya kwĩthĩwa ũmwe wĩ vinya kũũ nthĩ.'),
('kam', 'GEN', 10, 9, 'Aĩ mũsyĩmi wĩ vinya mbee wa Yeova: kwa ũu kwaaw’a, Ta Nimiloti mũsyĩmi wĩ vinya mbee wa Yeova.'),
('kam', 'GEN', 10, 10, 'Na wambĩlĩyo wa ũsumbĩ wake weethĩwa Mbaveli, na Eleku, na Akati, na Kalene, nthĩ ya Sinali.'),
('kam', 'GEN', 10, 11, 'Nthĩ ĩsu nĩkw’o waumie athi Asuli, na aaka Nineva, na LeovothiIli, na Kala,'),
('kam', 'GEN', 10, 12, 'na Leseni katĩ wa Nineva na Kala (nĩyo ĩla ndũa nene).'),
('kam', 'GEN', 10, 13, 'Na Misili asyaa Aluti, na Aanami, na Aleavi, na Anavitui,'),
('kam', 'GEN', 10, 14, 'na Avathilusi, na Akasilui (vala Avilisiti maumie), na Akavitoli.'),
('kam', 'GEN', 10, 15, 'Na Kanaani asyaa Sitoni ĩkithathi yake, na Ethi,'),
('kam', 'GEN', 10, 16, 'na Mũyevusĩ, na Mũamoli, na Mũngilikasi,'),
('kam', 'GEN', 10, 17, 'na Mũivi, na Mũaliki, na Mũsini,'),
('kam', 'GEN', 10, 18, 'na Mũalivati, na Mũnzemali, na Mũamathi: na ĩtina mĩvĩa ya Mũkanaani yanyaĩĩka.'),
('kam', 'GEN', 10, 19, 'Na mũvaka wa Mũkanaani waĩ kuma Sitoni, ũendete Ngelali, kũvika Ngasa; ũendete Sotomo na Ngomola na Atima na Nzevoiimu, kũvika Lasa.'),
('kam', 'GEN', 10, 20, 'Asu nĩo ana ma Amu, kũatĩĩa mĩvĩa yoo, na kũatĩĩa ithyomo syoo, katĩ wa nthĩ syoo, mbaĩnĩ syoo.'),
('kam', 'GEN', 10, 21, 'Na Semu, ĩthe wa ana onthe ma Eveli, mũkũũwe wa Yavethi, nake asyaĩwa syana.'),
('kam', 'GEN', 10, 22, 'Ana ma Semu: Elamu, na Asuli, na Alivakasati, na Luti, na Alamu.'),
('kam', 'GEN', 10, 23, 'Na ana ma Alamu: Usi, na Uli, na Ngetheli, na Masi.'),
('kam', 'GEN', 10, 24, 'Na Alivakasati asyaa Siela; na Siela asyaa Eveli.'),
('kam', 'GEN', 10, 25, 'Na Eveli asyaĩwa ana elĩ: syĩtwa ya ũmwe eetawa Veleki; nũndũ nthĩ yaaaniw’e matukũnĩ make; na syĩtwa ya mwana‐a‐inyia wake eetawa Yokitani.'),
('kam', 'GEN', 10, 26, 'Na Yokitani asyaa Alimotati, na Selevu, na Asalimavethi, na Yela,'),
('kam', 'GEN', 10, 27, 'na Aatolamu, na Usali, na Ndikila,'),
('kam', 'GEN', 10, 28, 'na Ovali, na Avimaeli, na Sieva,'),
('kam', 'GEN', 10, 29, 'Ovilu, na Avila, na Yovavu: asu onthe maĩ ana ma Yokitani.'),
('kam', 'GEN', 10, 30, 'Na ũtũo woo waĩ kuma Mesa, ũendete Sevali, kĩĩma kya wumĩlonĩ wa syũa.'),
('kam', 'GEN', 10, 31, 'Asu nĩ ana ma Semu, kũatĩĩa mĩvĩa yoo, na kũatĩĩa ithyomo syoo, katĩ wa nthĩ yoo, kũatĩĩa mbaĩ syoo.'),
('kam', 'GEN', 10, 32, 'Ĩsu nĩyo mĩvĩa ya ana ma Noa, kũatĩĩa mosyaanĩo moo, mbaĩnĩ syoo: na nũndũ wa asu mbaĩ syaaanw’a katĩ wa nthĩ ĩtina wa kĩla kĩw’ũ kingĩ.'),
('kam', 'GEN', 11, 1, 'Na nthĩ yonthe yaĩ ya kĩthyomo kĩmwe na kĩneeno kĩmwe.'),
('kam', 'GEN', 11, 2, 'Na kweethĩwa, yĩla maendete kyalo wumĩlonĩ wa syũa, moona ũiĩ nthĩ ya Sinali; na matũa vo.'),
('kam', 'GEN', 11, 3, 'Na meeana, Ũkai, tũmbe mavali, na tũimavĩvya vyũ. Na meethĩwa na mavali vandũ va mavia, na lami vandũ va ndaka.'),
('kam', 'GEN', 11, 4, 'Na masya, Ũkai, twĩyakĩe, ndũa, na mwako mũtũlu wa mũnyoolo, ũla mũthya waw’o ũtonya ũvika ĩtunĩ, na twĩmanthĩe syĩtwa; tũikese kũnyaĩĩkw’a ĩũlũ wa nthĩ yonthe.'),
('kam', 'GEN', 11, 5, 'Na Yeova atheea one ndũa na mwako ũsu mũtũlu, ũla ana ma andũ makĩte.'),
('kam', 'GEN', 11, 6, 'Na Yeova asya, Sisya, mo nĩ ũko ũmwe, na onthe me na kĩthyomo kĩmwe; na ũũ nĩ ũndũ mambĩlĩlya kwĩka; namo yu maikasiĩĩwa ũndũ meũsũanĩa kwĩka.'),
('kam', 'GEN', 11, 7, 'Ũkai, tũtheee, na tũithokoan’ya kĩthyomo kyoo vo, maikew’ane ũneeni.'),
('kam', 'GEN', 11, 8, 'Na ĩndĩ Yeova amanyaĩĩkya ĩũlũ wa nthĩ yonthe kuma vau: na maeka kwaka ndũa.'),
('kam', 'GEN', 11, 9, 'Kwondũ wa ũu syĩtwa yayo yeetwa Mbaveli; nũndũ nĩvo Yeova wathokoanĩsye kĩthyomo kya nthĩ yonthe: na kuma vau Yeova amanyaĩĩkya ĩũlũ wa nthĩ yonthe.'),
('kam', 'GEN', 11, 10, 'Aa nĩo mosyaanĩo ma Semu. Semu aĩ wa myaka ĩana, na asyaa Alivakasati myaka ĩlĩ ĩtina wa kĩla kĩw’ũ kingĩ:'),
('kam', 'GEN', 11, 11, 'na Semu ekala ĩtina wa kũsyaa Alivakasati myaka maana atano, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 12, 'Na Alivakasati ekala myaka mĩongo ĩtatũ na ĩtano, na asyaa Siela:'),
('kam', 'GEN', 11, 13, 'na Alivakasati ekala ĩtina wa kũsyaa Siela myaka maana ana na ĩtatũ, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 14, 'Na Siela ekala myaka mĩongo ĩtatũ, na asyaa Eveli:'),
('kam', 'GEN', 11, 15, 'na Siela ekala ĩtina wa kũsyaa Eveli myaka maana ana na ĩtatũ, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 16, 'Na Eveli ekala myaka mĩongo ĩtatũ na ĩna, na asyaa Veleki:'),
('kam', 'GEN', 11, 17, 'na Eveli ekala ĩtina wa kũsyaa Veleki myaka maana ana na mĩongo ĩtatũ, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 18, 'Na Veleki ekala myaka mĩongo ĩtatũ, na asyaa Leu:'),
('kam', 'GEN', 11, 19, 'na Veleki ekala ĩtina wa kũsyaa Leu myaka maana elĩ na kenda, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 20, 'Na Leu ekala myaka mĩongo ĩtatũ na ĩlĩ, na asyaa Seluki:'),
('kam', 'GEN', 11, 21, 'na Leu ekala ĩtina wa kũsyaa Seluki myaka maana elĩ na mũonza, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 22, 'Na Seluki ekala myaka mĩongo ĩtatũ, na asyaa Naoli:'),
('kam', 'GEN', 11, 23, 'na Seluki ekala ĩtina wa kũsyaa Naolĩ myaka maana elĩ, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 24, 'Na Naoli ekala myaka mĩongo ĩlĩ na kenda, na asyaa Tela:'),
('kam', 'GEN', 11, 25, 'na Naoli ekala ĩtina wa kũsyaa Tela myaka ĩana na ĩkũmi na kenda, o akĩsyaa ana na eĩtu.'),
('kam', 'GEN', 11, 26, 'Na Tela ekala myaka mĩongo mũonza, na asyaa Avalamu, na Naoli, na Aalani.'),
('kam', 'GEN', 11, 27, 'Na ĩndĩ aa nĩo mosyaanĩo ma Tela. Tela asyaa Avalamu, na Naoli, na Aalani; na Aalani asyaa Loto.'),
('kam', 'GEN', 11, 28, 'Na Aalani nĩwakw’ĩĩe nthĩ ĩla wasyaĩwe nthĩ ya Ulu wa Akalitei, ĩthe wake Tela atanakw’a.'),
('kam', 'GEN', 11, 29, 'Na Avalamu na Naoli meetwaĩa aka: syĩtwa ya mũka wa Avalamu eetawa Salai; na syĩtwa ya mũka wa Naoli, eetawa Milika, mwĩĩtu wa Aalani, ĩthe wa Milika, na ĩthe wa Isika.'),
('kam', 'GEN', 11, 30, 'Na Salai aĩ ngũngũ; ndaĩ mwana.'),
('kam', 'GEN', 11, 31, 'Na Tela oosa Avalamu mwana wake, na Loto mwana wa Aalani, mwĩsũkũũe, na Salai mũka wa mwana, o mũka wa mwana wake Avalamu; na mathi nao kuma Ulu wa Akalitei, kũlika nthĩ ya Kanaani; na mavika Aalani, na matũa vo.'),
('kam', 'GEN', 11, 32, 'Na matukũ ma Tela maĩ myaka maana elĩ na ĩtano: na Tela akw’ĩa Aalani.'),
('kam', 'GEN', 12, 1, 'Na ĩndĩ Yeova amwĩa Avalamu, Uma, we, nthĩ yaku, na kwa ũko waku, na nyũmba ya au, kũvika nthĩ ĩla nĩkwon’ya:'),
('kam', 'GEN', 12, 2, 'na ngakũtw’ĩkĩthya mbaĩ nene, na ngakũathima, na kũnenevya syĩtwa yaku; naku wĩthĩwe ũathimo:'),
('kam', 'GEN', 12, 3, 'nakwa ngamaathima ala makũathimaa, na ũla ũkũumanĩaa ngamũumanĩa: na nthĩnĩ waku, we, mĩvĩa yonthe ya nthĩ ĩkaathimwa.'),
('kam', 'GEN', 12, 4, 'Na ĩndĩ Avalamu athi, o tondũ Yeova wamwĩie; na Loto athi nake: na Avalamu aĩ wa myaka mĩongo mũonza na ĩtano yĩla waumie Aalani.'),
('kam', 'GEN', 12, 5, 'Na Avalamu oosa Salai mũka wake, na Loto mwana wa mwana‐a‐inyia, na syĩndũ syoo syonthe ila moombanĩtye, na andũ ala masyaĩwe Aalani; na mauma nĩ kana maende nthĩ ya Kanaani; na mavota nthĩ ya Kanaani.'),
('kam', 'GEN', 12, 6, 'Na Avalamu avĩtĩla ĩ nthĩ avika vandũ vetawa Sekemu, kũvika mũtĩ wa mwaloni wĩ Mole. Na ĩvinda yĩu Mũkanaani atũaa nthĩ ĩsu.'),
('kam', 'GEN', 12, 7, 'Na Yeova aumĩlĩla Avalamu, na asya, Nganenga ũsyao waku nthĩ ĩno: na vau aakĩa Yeova, ũla wamumĩlĩle, kĩthembeo.'),
('kam', 'GEN', 12, 8, 'Na auma vau avika kĩĩmanĩ ngalĩ ya wumĩlonĩ wa syũa ya Mbethi‐eli, na amba ĩeema yake, Mbethi‐eli yĩ ngalĩ ya ũthũĩlonĩ wa syũa, na Ai yĩ ngalĩ ya wumĩlonĩ wa syũa: na vau aakĩa Yeova kĩthembeo, na eekaĩla syĩtwa ya Yeova.'),
('kam', 'GEN', 12, 9, 'Na Avalamu athi kyalo, aendeea elekele ngalĩ ya Ĩtheo.'),
('kam', 'GEN', 12, 10, 'Na kwaĩ yũa nthĩ ĩsu: na Avalamu atheea Misili ekale ũeni kw’o: nũndũ yũa yaĩ ĩnene nthĩ ĩsu.'),
('kam', 'GEN', 12, 11, 'Na kweethĩwa, yĩla wathengeeie kũlika Misili, amwĩa Salai mũka wake, Na yu ĩndĩ, nĩnĩsĩ wĩ mũndũ mũka mwanake mũno kwa kũsiw’a:'),
('kam', 'GEN', 12, 12, 'na kũkeethĩwa, yĩla Amisili mekwona, makasya, Ũũ nĩ mũka wake: na makambũaa, ĩndĩ we makakũeka wĩ thayũ.'),
('kam', 'GEN', 12, 13, 'Nĩngũkwĩsũva, asya wĩ mwĩĩtũ‐a‐ia; nĩ kana kwĩthĩwe kwĩ kũseo kwakwa kwondũ waku, na kyuu kyakwa kĩkale thayũ kwondũ waku.'),
('kam', 'GEN', 12, 14, 'Na kweethĩwa, Avalamu avika Misili, Amisili moona mũka wake kana nĩ mwanake mũno.'),
('kam', 'GEN', 12, 15, 'Na anene me mbee ũsumbĩnĩ ma Valao mamwona, na mamũkatha kwa Valao: na mũndũ mũka atwawa nyũmbanĩ ya Valao.'),
('kam', 'GEN', 12, 16, 'Na amwĩka Avalamu nesa kwondũ wake: na aĩ na malondu, na ng’ombe, na mang’oi maũme, na athũkũmi aũme na eĩtu, na mang’oi maka, na ngamĩle.'),
('kam', 'GEN', 12, 17, 'Na Yeova athĩn’ya Valao na nyũmba yake mothĩn’yo manene kwondũ wa Salai, mũka wa Avalamu.'),
('kam', 'GEN', 12, 18, 'Na Valao amwĩta Avalamu, na amũkũlya, Ũu ũmbĩkĩte nata? Nĩkĩ ndwaandavya kana nĩ kĩveti kyaku?'),
('kam', 'GEN', 12, 19, 'Nĩkĩ waisye, Nĩ mwĩĩtu‐a‐ia, ũndũ nĩmũtwaie ethĩwe mũka wakwa? Yu ĩndĩ sisya mũka waku, mwose, ũkwate nzĩa ũthi.'),
('kam', 'GEN', 12, 20, 'Na Valao eeaĩa andũ ũndũ wake: nao mamumaasya nzĩanĩ, na mũka wake, na syonthe ila waĩ nasyo.'),
('kam', 'GEN', 13, 1, 'Na Avalamu ambata kuma Misili, we, na mũka wake, na syonthe ila waĩ nasyo, na Loto vamwe nake, kũvika ngalĩ ya Ĩtheo.'),
('kam', 'GEN', 13, 2, 'Na Avalamu aĩ mũthwii mũno na indo, na vetha, na thaavu.'),
('kam', 'GEN', 13, 3, 'Na aenda kyalo kuma ngalĩ ya Ĩtheo kũvika Mbethi‐eli, vandũ vala ĩeema yake yaĩ mbee, katĩ wa Mbethi‐eli na Ai,'),
('kam', 'GEN', 13, 4, 'kũvika vandũ va kĩthembeo, kĩla waseũvĩtye vo mbee: na vau Avalamu eekaĩla syĩtwa ya Yeova.'),
('kam', 'GEN', 13, 5, 'Nake Loto, ũla waendanasya vamwe na Avalamu, aĩ na ndĩthya sya mbũi na malondu, na sya ng’ombe, na maeema.'),
('kam', 'GEN', 13, 6, 'Na nthĩ ndĩaatonya kũmeanĩa, mekalae vamwe: nũndũ ũthwii woo waĩ mwingĩ, ũndũ mataatonya kwĩkala vamwe.'),
('kam', 'GEN', 13, 7, 'Na kwaĩ iteta katĩ wa aĩthĩ ma indo sya Avalamu na aĩthi ma indo sya Loto: na ĩvinda yĩu Mũkanaani na Mũvelisi matũaa nthĩ ĩsu.'),
('kam', 'GEN', 13, 8, 'Na Avalamu amwĩa Loto, Nĩngũkwĩsũva, kũikethĩwe iteta katĩ wakwa naku, na katĩ wa aĩthi makwa na aĩthi maku; nũndũ twĩ ana‐a‐asa.'),
('kam', 'GEN', 13, 9, 'Nthĩ yonthe ndĩ mbee waku? Nĩngũkwĩsũva, ũtaanĩsye nakwa: wenda kũthi ngalĩ ya kw’oko kwa aka, nakwa ngathi ngalĩ ya kw’oko kwa aũme; kana wathi ngalĩ ya kw’oko kwa aũme, nakwa ngathi ngalĩ ya kw’oko kwa aka.'),
('kam', 'GEN', 13, 10, 'Na Loto ookĩlya metho, oona Ũiĩ wa Yolotani w’onthe, kana wĩ na manzĩ ngalĩ syonthe, Yeova atanamba kwananga Sotomo na Ngomola, o ta ũla mũũnda wa Yeova, ta nthĩ ya Misili, ũendete Nzoali.'),
('kam', 'GEN', 13, 11, 'Na ĩndĩ Loto eenyuvĩa Ũiĩ w’onthe wa Yolotani; na Loto athi kyalo ngalĩ ya wumĩlonĩ wa syũa: na mataanĩsya ene kwa ene.'),
('kam', 'GEN', 13, 12, 'Avalamu ekala nthĩ ya Kanaani na Loto ekala ndũanĩ sya ũla Ũiĩ, na athamĩĩsya ĩeema yake kũvika Sotomo.'),
('kam', 'GEN', 13, 13, 'Na ĩndĩ andũ ma Sotomo maĩ athũku na athe mũno kwa Yeova.'),
('kam', 'GEN', 13, 14, 'Na Yeova amwĩa Avalamu, ĩtina wa kũtaanĩsya na Loto, Yu ũkĩlya metho maku, ũsisye kuma vandũ vala ũĩ, ngalĩ ya ĩũlũ na ngalĩ ya ĩtheo na wumĩlonĩ wa syũa na ũthũĩlonĩ wa syũa:'),
('kam', 'GEN', 13, 15, 'nũndũ nthĩ yonthe ĩla ũkwona, ngakũnenga we, na ũsyao waku tene na tene.'),
('kam', 'GEN', 13, 16, 'Na ũsyao waku ngootw’ĩkĩthya ta kĩtoo kya nthĩ: nũndũ ethĩwa mũndũ nũtonya kũtala kĩtoo kya nthĩ, nĩvo ĩndĩ ũsyao waku ũtonya kũtalĩka.'),
('kam', 'GEN', 13, 17, 'Ukĩla, ũtambũke katĩ wa nthĩ ũasanĩ wayo na ũthanthaunĩ wayo, nũndũ ngakũnenga yo.'),
('kam', 'GEN', 13, 18, 'Na Avalamu athamya ĩeema yake, ooka ekala mĩtĩnĩ ya myaloni yĩ Mamile, ĩla yĩ Evilonĩ, na vau aakĩa Yeova kĩthembeo.'),
('kam', 'GEN', 14, 1, 'Na kweethĩwa matukũ ma Amulaveli mũsumbĩ wa Sinali, na Alioko mũsumbĩ wa Elasali, na Ketololaomeli mũsumbĩ wa Elamu, na Titali mũsumbi wa Ngoiimu,'),
('kam', 'GEN', 14, 2, 'makwatya kaũ na Vela mũsumbĩ wa Sotomo, na Mbilisa mũsumbĩ wa Ngomola, na Sinavu mũsumbĩ wa Atima, na Semeveli mũsumbĩ wa Nzevoiimu, na mũsũmbĩ wa Mbela (nĩyo Nzoali).'),
('kam', 'GEN', 14, 3, 'Asu onthe makomanĩa mwandanĩ wa Sitimi (nĩw’o Ũkanga wa Mũnyũ).'),
('kam', 'GEN', 14, 4, 'Myaka ĩkũmi na ĩlĩ mathũkũmaa Ketololaomeli, na mwaka wa ĩkũmi na ĩtatũ mamũng’endea.'),
('kam', 'GEN', 14, 5, 'Na mwaka wa ĩkũmi na ĩna Ketololaomeli ooka na asũmbĩ ala maĩ nake, na makũnĩa Alevai nthĩnĩ wa Asetelothi‐kalinaimu, na Asusi nthĩnĩ wa Amu, na Aemi nthĩnĩ wa Save‐kiliathaimu.'),
('kam', 'GEN', 14, 6, 'Na Aoli kĩĩmanĩ kyoo Seili, kũvika Eli‐valani, ĩla yĩ ũtee wa weũ.'),
('kam', 'GEN', 14, 7, 'Na masyoka, na mavika Eni‐misivati (nĩyo Katesi), makũna nthĩ yonthe ya Aamaleki, o na ya Aamoli, ala matwĩe Asasoni‐tamali.'),
('kam', 'GEN', 14, 8, 'Na mũsũmbĩ wa Sotomo, na mũsumbĩ wa Ngomola, na mũsũmbĩ wa Atima, na mũsumbĩ wa Nzevoiimu, na mũsumbĩ wa Mbela (nĩyo Nzoali) maumaala; na maselelya ita mamelekele mwandanĩ wa Sitimi;'),
('kam', 'GEN', 14, 9, 'mokite na Ketololaomeli mũsũmbĩ wa Elamu, na Titali mũsumbĩ wa Ngoiimu, na Amulaveli mũsumbĩ wa Sinali, na Alioko mũsumbĩ wa Elasali; asumbĩ ana mokite na atano.'),
('kam', 'GEN', 14, 10, 'Na ĩndĩ mwanda wa Sitimi wausũĩte maima ma lami; na asumbĩ ma Sotomo na Ngomola makũka, na mavalũka vo, na ala matialile makũka maelete kĩĩmanĩ.'),
('kam', 'GEN', 14, 11, 'Na makua ũthwii w’onthe wa Sotomo na Ngomola, na lĩu woo w’onthe, na makwata nzĩa mathi.'),
('kam', 'GEN', 14, 12, 'Na moosa Loto, mwana wa mwana‐a‐inyia wa Avalamu, ũla watwĩe Sotomo, na ũthwii wake, na mathi.'),
('kam', 'GEN', 14, 13, 'Na ũmwe ũla wavonokie ooka, na atavya Avalamu Mũevelania: nake atwĩe mĩtĩnĩ ya myaloni yĩ Mamile, Mũamoli, mwana‐a‐inyia wa Esikoli, na mwana‐a‐inyia wa Aneli; nao nĩmeew’anĩte na Avalamu.'),
('kam', 'GEN', 14, 14, 'Na yĩla Avalamu wewie kana mwana‐a‐ĩthe nũtavĩtwe, aumya andũ make ala wamamanyĩĩtye, ala masyaĩwe nyũmbanĩ yake, maana atatũ na ĩkũmi na nyanya, na amaatĩĩa kũvika Ndani.'),
('kam', 'GEN', 14, 15, 'Na ũtukũ eeyĩaan’ya okite nao, we na athũkũmi make, na amakũna, na amaatĩĩa kũvika Ova, ĩla yĩ ngalĩ ya kw’oko kwa aka ya Ndamasiku.'),
('kam', 'GEN', 14, 16, 'Nake atũnga ũthwii w’onthe, na ĩngĩ atũnga mwana‐a‐ĩthe Loto, na ũthwii wake, na aka nao na andũ.'),
('kam', 'GEN', 14, 17, 'Na mũsumbĩ wa Sotomo athi kũmũthaũa, ĩtina wa kũsyoka kwake kuma kũaa Ketololaomeli na asumbĩ ala maĩ vamwe nake, mwandanĩ wa Save (nĩw’o Mwanda wa Mũsumbĩ).'),
('kam', 'GEN', 14, 18, 'Na Melikiseteki mũsumbĩ wa Saleme aete kĩmũtũ na mbinyu: nake aĩ mũthembi wa Ngai Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'GEN', 14, 19, 'Na amũathima, na asya, Naathimwe Avalamu wa Ngai Ũla Wĩ Ĩũlũ wa Onthe, mwene wa ĩtu na nthĩ:'),
('kam', 'GEN', 14, 20, 'na nataĩwe Ngai Ũla wĩ Ĩũlũ wa Onthe, ũla ũnenganĩte amaitha maku kw’okonĩ kwaku. Na amũnenga kĩlungu kya ĩkũmi kya syonthe.'),
('kam', 'GEN', 14, 21, 'Na mũsumbĩ wa Sotomo amwĩa Avalamu, Nenga andũ, na ũkĩyosea ũthwii.'),
('kam', 'GEN', 14, 22, 'Na Avalamu amwĩa mũsumbĩ wa Sotomo, Nĩnookĩlya kw’oko kwakwa kwa Yeova, Ngai Ũla Wĩ Ĩũlũ wa Onthe, mwene wa ĩtu na nthĩ,'),
('kam', 'GEN', 14, 23, 'kana ndikosa ũlii, kana ũlii wa kĩatũ, kana kĩndũ o na kĩva kyaku, ndũkese kwasya, Nĩthuĩtye Avalamu:'),
('kam', 'GEN', 14, 24, 'ate o kĩla anake maĩe, na kĩlungu kya andũ ala maendie nakwa, Aneli, na Esikoli, na Mamile; asu nĩmose kĩlungu kyoo.'),
('kam', 'GEN', 15, 1, 'Ĩtina wa maũndũ asu ndeto ya Yeova yamũkĩa Avalamu woninĩ, ĩkĩmwĩa, Ndũkakĩe, Avalamu: ninyie ngao yaku, na ĩtuvi yaku ĩnene mũno mbee.'),
('kam', 'GEN', 15, 2, 'Na Avalamu akũlya, Ame Mwĩaĩĩ Yeova, ũkanenga kĩ, nĩkwĩthĩwa nĩendaa nde mwana, na ũla ũkethĩwa e mwene wa nyũmba yakwa nĩ Elieseli wa Ndamasiku?'),
('kam', 'GEN', 15, 3, 'Na Avalamu amwĩa, Nĩ w’o, ndwaanenga ũsyao: na, sisya, ũmwe wasyaĩwe nyũmbanĩ yakwa nĩ mũtiĩwa wakwa.'),
('kam', 'GEN', 15, 4, 'Na, sisya, ndeto ya Yeova yamũkĩa, ĩkĩmwĩa, Mũndũ ũsu ndakethĩwa mũtiĩwa waku; ĩndĩ ũla ũkauma kĩnyunyunĩ kyaku mwene nĩwe ũkethĩwa mũtiĩwa waku.'),
('kam', 'GEN', 15, 5, 'Na amumaalya nza, na amwĩa, Sisya yu kwelekela ĩtunĩ, ũtale ndata, ethĩwa nũtonya kwitala: na amwĩa, Ũsyao waku ũkeethĩwa o ta ũu.'),
('kam', 'GEN', 15, 6, 'Nake aĩkĩĩa Yeova; nake amũtalĩla ũndũ ũsu kwĩthĩwa ũlũngalu.'),
('kam', 'GEN', 15, 7, 'Na amwĩa, Ninyie Yeova ũla nakumisye Ulu wa Akalitei, nĩkũnenge nthĩ ĩno ũtiĩwe yo.'),
('kam', 'GEN', 15, 8, 'Na akũlya, Ame Mwĩaĩĩ Yeova, nĩmanya ata kana ngatiĩwa yo?'),
('kam', 'GEN', 15, 9, 'Nake amwĩa, Mbosea moi ya myaka ĩtatũ, na mbũi nga ya myaka ĩtatũ, na ndũũme ya myaka ĩtatũ, na ndumbũ, na ĩswii ya ĩvũĩ.'),
('kam', 'GEN', 15, 10, 'Na eeyosea ii syonthe, na aatũan’ya katĩ, na aia kĩla nyunzu yelekele ĩla ĩngĩ: ĩndĩ nyũnyi ndaatũan’ya.'),
('kam', 'GEN', 15, 11, 'Na ndei syatheeea ila nyama, na Avalamu ailũngya.'),
('kam', 'GEN', 15, 12, 'Na syũa yĩkĩthũa, Avalamu akwatwa nĩ too mũnene; na, sisya, w’ĩa mũnene wa kĩvindu kĩnene wamũkwata.'),
('kam', 'GEN', 15, 13, 'Nake amwĩa Avalamu, Manya vyũ kana ũsyao waku ũkeethĩwa mũeni nthĩ ĩte yoo, na makamathũkũma: na makamathĩn’ya myaka maana ana;'),
('kam', 'GEN', 15, 14, 'o na mbaĩ ĩsũ, ĩla makathũkũma, ngamĩsilĩla: na ĩtina makauma na ũthwii mwingi.'),
('kam', 'GEN', 15, 15, 'Ĩndĩ, we, ũkathi kwa aasa maku na mũuo; ũkathikwa wĩ na ũtumĩu mũseo.'),
('kam', 'GEN', 15, 16, 'Na nzyawanĩ ya kana makasyoka kũũ ĩngĩ: nũndũ ũthũku wa Mũamoli ndũnamba kwĩanĩa.'),
('kam', 'GEN', 15, 17, 'Na kweethĩwa, syũa yathũa, na kwaya kĩvindu, sisya, iko yĩ syũki, na kĩsinga kyakanu kyavĩtĩla katĩ wa myondo ĩsu.'),
('kam', 'GEN', 15, 18, 'Mũthenya ũsu Yeova atianĩa ũtianĩo na Avalamu, akĩmwĩa, Nĩnanenga ũsyao waku nthĩ ĩno, kuma ũsĩ wa Misili kũvika ũsĩ mũnene, ũsĩ wa Euvalati:'),
('kam', 'GEN', 15, 19, 'Mũkeni, na Mũkenisi, na Mũkatimoni,'),
('kam', 'GEN', 15, 20, 'na Mũititi, na Mũvelisi, na Mulevai,'),
('kam', 'GEN', 15, 21, 'na Mũamoli, na Mũkanaani, na Mũngilikasi, na Mũyevusi.'),
('kam', 'GEN', 16, 1, 'Na ĩndĩ Salai, mũka wa Avalamu, ndaamũsyaĩa syana: nake aĩ na mũthũkũmi mwĩĩtu, Mũmisili, syĩtwa yake eetawa Akali.'),
('kam', 'GEN', 16, 2, 'Na Salai amwĩa Avalamu, Sisya yu, Yeova nũnziĩĩe ndikasyae; nĩngũkwĩsũva ĩndĩ, lika kwa mũthũkũmi wakwa, mwĩĩtu; nokwĩthĩwa ngosa syana kwake. Na Avalamu eethukĩĩsya wasya wa Salai.'),
('kam', 'GEN', 16, 3, 'Na Salai, mũka wa Avalamu, oosa Akali, Mũmisili, mũthũkũmi wake, mwĩĩtu, ĩtina wa Avalamu ekala myaka ĩkũmi nthĩ ya Kanaani, na amũnenga Avalamu, mũũme wake, atw’ĩke mũka.'),
('kam', 'GEN', 16, 4, 'Na alika kwa Akali, nake aya ĩvu: na yĩla wonie kana e ĩvu, avũthya vivi wake methonĩ make.'),
('kam', 'GEN', 16, 5, 'Na Salai amwĩa Avalamu, Ũthũku wakwa wĩthĩwe kwaku: nĩngũnengete mũthũkũmi wakwa, mwĩĩtu, kĩthũinĩ kyaku; na yĩla wonie kana e ĩvu, ambũthya methonĩ make: Yeova nasile katĩ wakwa naku.'),
('kam', 'GEN', 16, 6, 'Ĩndĩ Avalamu amwĩa Salai, Sisya, mũthũkũmi waku, mwĩĩtu, e kw’okonĩ kwaku; mwĩke ũndũ ũkwona wĩ ũseo methonĩ maku. Na Salai amũthĩn’ya, nake akĩa auma mbee wa ũthyũ wake.'),
('kam', 'GEN', 16, 7, 'Na mũlaĩka wa Yeova amwĩthĩa nthongonĩ ya manzĩ weũnĩ, ĩla nthongo yĩ nzĩanĩ ya Suli.'),
('kam', 'GEN', 16, 8, 'Nake akũlya, Akali, mũthũkũmi mwĩĩtu wa Salai, wauma va? Na wĩthi kũ? Na asũngĩa, Nĩngĩĩte nume mbee wa ũthyũ wa vivi wakwa Salai.'),
('kam', 'GEN', 16, 9, 'Na mũlaĩka wa Yeova amwĩa, Mũsyokee vivi waku, na ũyĩnyivya mokonĩ make.'),
('kam', 'GEN', 16, 10, 'Na mũlaĩka wa Yeova amwĩa, Ngaingĩvya mũno ũsyao waku, ũndũ ũtakatalĩka nũndũ wa kwingĩva.'),
('kam', 'GEN', 16, 11, 'Na mũlaĩka wa Yeova amwĩa, Sisya, wĩ ĩvu, na ũkasyaa mwana; na ũkamwĩta syĩtwa yake Isumaeli, nũndũ Yeova nĩwew’a thĩna waku.'),
('kam', 'GEN', 16, 12, 'Nake akeethĩwa ta ĩng’oi ya kĩthekanĩ katĩ wa andũ; kw’oko kwake kũkeethĩwa ĩũlũ wa kĩla mũndũ, na kw’oko kwa kĩla mũndũ ĩũlũ wake; nake akatũa elekanĩle na ana‐a‐ĩthe make onthe.'),
('kam', 'GEN', 16, 13, 'Na eeta syĩtwa ya Yeova ũla waneenie nake, Nue Ngai ũla wonaa: nũndũ aisye, O na vaa nĩnamwonea ũla ũnziasya?'),
('kam', 'GEN', 16, 14, 'Kwondũ wa ũu kĩthima kyeetwa Mbeeli‐laai‐loi; sisya, kĩ katĩ wa Katesi na Mbeleti.'),
('kam', 'GEN', 16, 15, 'Na Akalĩ amũsyaĩa Avalamu mwana: na Avalamu amwĩta mwana wake Isumaeli, ũla Akali wasyaie.'),
('kam', 'GEN', 16, 16, 'Na Avalamu aĩ wa myaka mĩongo nyanya na thanthatũ, yĩla Akali wamũsyaĩe Avalamu Isumaeli.'),
('kam', 'GEN', 17, 1, 'Na yĩla Avalamu waĩ wa myaka mĩongo kenda na kenda, Yeova amumĩlĩla Avalamu, na amwĩa, Ninyie Ngai Mwene Vinya W’onthe; endaa mbee wakwa, na ĩthĩwa wĩ mwĩanĩu.'),
('kam', 'GEN', 17, 2, 'Nakwa ngatianĩa ũtianĩo wakwa katĩ wakwa naku, na ngakwingĩvya mũno.'),
('kam', 'GEN', 17, 3, 'Na Avalamu avalũka na ũthyũ wake: na Ngai aneena nake, akĩmwĩa,'),
('kam', 'GEN', 17, 4, 'Nyie, sisya, ũtianĩo wakwa wĩ naku, na ũkeethĩwa ĩthe wa mbaĩ mbingĩ mũno.'),
('kam', 'GEN', 17, 5, 'O na ndũketwa ĩngĩ syĩtwa yaku Avalamu, ĩndĩ syĩtwa yaku yĩkeethĩwa Avalaamu; nũndũ nĩnakũtw’ĩkĩthya ĩthe wa mbaĩ mbingĩ mũno.'),
('kam', 'GEN', 17, 6, 'Na ngakwingĩvya mũno mũnene, na ngakũtw’ĩkĩthya mbaĩ, na asumbĩ makauma kwaku.'),
('kam', 'GEN', 17, 7, 'Na ngalũlũmĩlya ũtianĩo wakwa katĩ wakwa naku na ũsyao waku ĩtina waku mosyaanĩonĩ moo wĩthĩwe wĩ ũtianĩo wa tene na tene, nĩthĩwe nĩ Ngai kwaku na kwa ũsyao waku ĩtina waku.'),
('kam', 'GEN', 17, 8, 'Na ngakũnenga we, na ũsyao waku ĩtina waku, nthĩ ĩla wĩkalaa wĩ mũeni, nthĩ yonthe ya Kanaani, yĩthĩwe ng’ũndũ yenyu tene na tene; nakwa ngeethĩwa Ngai woo.'),
('kam', 'GEN', 17, 9, 'Na Ngai amwĩa Avalaamu, Naku, lũmya ũtianĩo wakwa, we, na ũsyao waku ĩtina waku mosyaanĩonĩ moo.'),
('kam', 'GEN', 17, 10, 'Ũũ nĩ ũtianĩo wakwa, ũla mwĩkwata, katĩ wakwa naku na ũsyao waku ĩtina waku: kĩla mũndũ mũũme katĩ wenyu akaĩkwa.'),
('kam', 'GEN', 17, 11, 'Mũkaĩkwa nyama ya ikonde sya mbinũ: nayo ĩkeethĩwa ũvano wa ũtianĩo katĩ wakwa naku.'),
('kam', 'GEN', 17, 12, 'Na ũla wa matukũ nyanya katĩ wenyu akaĩkwa, kĩla mũndũ mũũme mosyaanĩonĩ menyu, ũla ũsyaĩtwe nyũmbanĩ, kana ũla ũthooetwe na mbesa kwa mũeni o na wĩva w’onthe ũte wa ũsyao waku.'),
('kam', 'GEN', 17, 13, 'Ũla ũsyaĩtwe nyũmbanĩ kwaku, na ũla ũthooetwe na mbesa syaku, ndakatĩa kwaĩkwa: na ũtianĩo wakwa ũkeethĩwa mwĩĩnĩ wenyu wĩthĩwe ũtianĩo wa tene na tene.'),
('kam', 'GEN', 17, 14, 'Na mũndũ mũũme ũte mwaĩke ũtanaĩkwa nyama ya kĩkonde kya mbinũ yake, mũndũ ũsu akavetwa kuma andũnĩ make: nũtũlĩte ũtianĩo wakwa.'),
('kam', 'GEN', 17, 15, 'Na Ngai amwĩa Avalaamu, Nake Salai mũka waku, ndũkamwĩte Salai, ĩndĩ syĩtwa yake yĩkeethĩwa Sala.'),
('kam', 'GEN', 17, 16, 'Nakwa ngamũathima, na ĩngĩ ngakũnenga mwana kuma kwake: ĩĩ, ngamũathima, nake akeethĩwa inyia wa mbaĩ; asumbĩ ma andũ makauma kwake.'),
('kam', 'GEN', 17, 17, 'Na ĩndĩ Avalaamu avalũka na ũthyũ wake, na atheka, na akũlya ngoonĩ yake, Ũla wĩ myaka ĩana akasyaĩwa mwana? Na Sala, ũla wĩ myaka mĩongo kenda, akasyaa?'),
('kam', 'GEN', 17, 18, 'Na Avalaamu amwĩa Ngai, Ame, kethĩwa Isumaeli nĩwĩkalaa thayũ mbee waku!'),
('kam', 'GEN', 17, 19, 'Na Ngai asũngĩa, Aiee, ĩndĩ Sala mũka waku akakũsyaĩa mwana; naku ũkeeta syĩtwa yake Isaka: na ngalũlũmĩlya ũtianĩo wakwa nake wĩthĩwe ũtianĩo wa tene na tene kwondũ wa ũsyao wake ĩtina wake.'),
('kam', 'GEN', 17, 20, 'Na Isumaeli ũndũ wake, nĩnakwĩw’a: sisya, nĩnamũathima, na ngamwongeleela, na kũmwingĩvya mũno mũnene; akasyaa anene ĩkũmi na elĩ, nakwa ngamũtw’ĩkĩthya mbai nene.'),
('kam', 'GEN', 17, 21, 'Ĩndĩ ngalũlũmĩlya ũtianĩo wakwa na Isaka, ũla Sala ũkakũsyaĩa ĩvinda ta yĩĩ mwaka ũla ũngĩ.'),
('kam', 'GEN', 17, 22, 'Na Ngai amina ũneena nake, na ambata kuma kwa Avalaamu.'),
('kam', 'GEN', 17, 23, 'Na Avalaamu oosa Isumaeli mwana wake, na onthe ala masyaĩwe nyũmbanĩ kwake, na onthe mathooiwe na mbesa syake, kĩla mũndũ mũũme katĩ wa nyũmba ya Avalaamu, na amaĩka nyama ya ikonde sya mbinũ syoo mũthenya ũsu, o tondũ Ngai wamũtavisye.'),
('kam', 'GEN', 17, 24, 'Nake Avalaamu aĩ wa myaka mĩongo kenda na kenda, yĩla waĩkiwe nyama ya kĩkonde kya mbinũ yake.'),
('kam', 'GEN', 17, 25, 'Na Isumaeli mwana wake aĩ wa myaka ĩkũmi na ĩtatũ, yĩla waĩkiwe nyama ya kĩkonde kya mbinũ yake.'),
('kam', 'GEN', 17, 26, 'Mũthenya o ũsu ũmwe Avalaamu aĩkwa, na Isumaeli mwana wake.'),
('kam', 'GEN', 17, 27, 'Na aũme onthe ma nyũmba yake, ala masyaĩwe nyũmbanĩ yake, na ala mathooiwe na mbesa kwa mũeni, nĩmaĩkiwe vamwe nake.'),
('kam', 'GEN', 18, 1, 'Na Yeova amumĩlĩla mĩtĩnĩ ya myaloni yĩ Mamile, ekalĩte mũomonĩ wa ĩeema mũthenya kwavyũva;'),
('kam', 'GEN', 18, 2, 'na ookĩlya metho na oona, na, sisya andũ atatũ nĩmaũngamĩte mbee wake; na amona, asemba kuma mũomonĩ wa ĩeema amathaũe, na eekunamya kũvika nthĩ,'),
('kam', 'GEN', 18, 3, 'na asya, Mwĩaĩĩ wakwa, yu ethĩwa nĩnonete ũseo mbee waku, nĩngũkwĩsũva, ndũkavĩte kuma kwa mũthũkũmi waku:'),
('kam', 'GEN', 18, 4, 'manzĩ manini maetwe yu, na mũithambya maũũ, na kwĩthũmũsya ĩtina wa kĩtĩ:'),
('kam', 'GEN', 18, 5, 'nakwa ngaete lĩu mũnini, mũvuũkye ngoo; ĩtina wa ũu mũkavĩta: nũndũ mwamũkĩa mũthũkũmi wenyu. Na masya, Ĩka, o tondũ wasya.'),
('kam', 'GEN', 18, 6, 'Na Avalaamu aenda mĩtũkĩ ĩeemanĩ vala ve Sala, na amwĩa, Seũvya mĩtũkĩ mũtu mũseo wa ithimi itatũ, wũmbe, ũseũvye tũmũtũ.'),
('kam', 'GEN', 18, 7, 'Na Avalaamu asemba ndĩthyanĩ, aete kasaũ kololo na kaseo, anenga mũthũkũmi; nake akalaata kũthĩnza.'),
('kam', 'GEN', 18, 8, 'Na oosa mauta, na ĩia, na kasaũ kala wathĩnza, na aia mbee woo; na aũngama ũtee woo ĩtina wa kĩtĩ, nao maya.'),
('kam', 'GEN', 18, 9, 'Na mamũkũlya, Aĩva Sala mũka waku? Nake asũngĩa, Sisya, e ĩeemanĩ.'),
('kam', 'GEN', 18, 10, 'Nake amwĩa, Nĩ w’o ngakũsyokea kyathĩ kyavĩka; na, sisya, Sala mũka waku akeethĩwa na mwana. Na Sala eew’a e mũomonĩ wa ĩeema, yĩla yaĩ ĩtina wa ũsu.'),
('kam', 'GEN', 18, 11, 'Na ĩndĩ Avalaamu na Sala maĩ akũu, na ma myaka mingĩ; waĩ ũnaeka kwĩthĩwa na Sala mwĩkalĩle wa aka.'),
('kam', 'GEN', 18, 12, 'Na Sala atheka ngoonĩ yake, akĩkũlya, Nĩ mũtumĩu ngeethĩwa na mũyo, mwĩaĩi wakwa nake e mũtumĩu?'),
('kam', 'GEN', 18, 13, 'Na Yeova akũlya Avalaamu, Sala atheka nĩkĩ, akĩkũlya, Nĩ w’o ngasyaa mwana, nĩ mũkũu?'),
('kam', 'GEN', 18, 14, 'Kwĩ ũndũ ũtatonyeka kwa Yeova? Ĩvinda yĩtw’ĩtwe ngakũsyokea, kyathĩ kyavika, na Sala akeethĩwa na mwana.'),
('kam', 'GEN', 18, 15, 'Na ĩndĩ Sala akaĩa, akyasya, Ndinatheka; nũndũ aĩ na w’ĩa. Nake asya, Aiee; ĩndĩ nĩwatheka.'),
('kam', 'GEN', 18, 16, 'Na ala andũ mauma vau, masisya ngalĩ ya Sotomo: na Avalaamu aendan’ya nao amaumaaĩtye.'),
('kam', 'GEN', 18, 17, 'Na Yeova eekũlya, Nĩmũvithe Avalaamu ũndũ ngwĩka:'),
('kam', 'GEN', 18, 18, 'nũndũ vate ndĩi Avalaamu akeethĩwa mbaĩ nene yĩ vinya, na mbaĩ syonthe sya nthĩ ikaathimwa nthĩnĩ wake?'),
('kam', 'GEN', 18, 19, 'Nũndũ nĩnĩmwĩsĩ, nĩ kana eaĩae syana syake na andũ make ĩtina wake, makwate nzĩa ya Yeova, mekae ũlũngalu na ũsili wa katĩ; nĩ kana Yeova amũetee Avalaamu ũndũ ũla waneenie ũndũ wake.'),
('kam', 'GEN', 18, 20, 'Na Yeova asya, Nũndũ kĩĩo kya Sotomo na Ngomola nĩ kĩnene, na nũndũ naĩ yoo yongelekete mũno:'),
('kam', 'GEN', 18, 21, 'nĩngũtheea yu, none kana nĩw’o mekĩte o ũndũ kĩĩo kyayo kĩmbikĩe; na ethĩwa ti w’o ngamanya.'),
('kam', 'GEN', 18, 22, 'Na ala andũ meethyũũa kuma vau, mathi melekele Sotomo: ĩndĩ Avalaamu no waũngyĩ mbee wa Yeova.'),
('kam', 'GEN', 18, 23, 'Na Avalaamu athengeea, na akũlya, Ũkamina alũngalu vamwe na ala athũku?'),
('kam', 'GEN', 18, 24, 'Nokwĩthĩwa kwĩ alũngalu mĩongo ĩtano ndũanĩ: ũkamina o na ndũeka a vandũ kwondũ wa alũngalu mĩongo ĩtano ala me vo nthĩnĩ?'),
('kam', 'GEN', 18, 25, 'Ũu wĩthĩwe kũasa naku kwĩka ta ũu, kũaa alũngalu vamwe na ala athũku, nĩ kana alũngalu methĩwe ta athũku; ũu wĩthĩwe kũasa naku: Mũsili wa nthĩ yonthe ndakeka ũlũngalu?'),
('kam', 'GEN', 18, 26, 'Na Yeova asũngĩa, Noona nthĩnĩ wa Sotomo alũngalu mĩongo ĩtano ndũanĩ, nĩw’o nĩeka vandu vonthe kwondũ woo.'),
('kam', 'GEN', 18, 27, 'Na Avalaamu asũngĩa asya, Na ĩndĩ sisya, nĩnakwata kũneena na Mwĩaĩi, nakwa nĩ o kĩtoo na mũu:'),
('kam', 'GEN', 18, 28, 'nokwĩthĩwa maoleka atano kwa ala alũngalu mĩongo ĩtano: ũkaananga ndũa yonthe kwondũ wa ala atano aoleku? Nake amwĩa, Ndikamyananga, noona vo mĩongo ĩna na atano.'),
('kam', 'GEN', 18, 29, 'Na aneena nake ĩngĩ, na asya, Nokwĩthĩwa vakoneka vo mĩongo ĩna. Nake asũngĩa, Ndikeka ũu kwondũ wa asu mĩongo ĩna.'),
('kam', 'GEN', 18, 30, 'Nake asya, Ame Mwĩaĩi ndakathate, nakwa nĩngũneena: nokwĩthĩwa vakoneka vo mĩongo ĩtatũ. Na asya, Ndikeka ũu, noona vo mĩongo ĩtatũ.'),
('kam', 'GEN', 18, 31, 'Na amwĩa, Sisya yu, nĩnakwata kũneena na Mwĩaĩi: nokwĩthĩwa vakoneka vo mĩongo ĩlĩ. Nake asũngĩa, Ndikamyananga kwondũ wa asu mĩongo ĩlĩ.'),
('kam', 'GEN', 18, 32, 'Nake asya, Ame Mwĩaĩi ndakathate, nakwa nĩngũneena no ĩvinda yĩĩ yĩmwe yoka: nokwĩthĩwa ĩkũmi makoneka vo. Nake asũngĩa, Ndikamyananga kwondũ wa asu ĩkũmi.'),
('kam', 'GEN', 18, 33, 'Na Yeova athi na nzĩa yake, mamina kũneenan’ya e na Avalaamu: na Avalaamu asyoka vandũ vake.'),
('kam', 'GEN', 19, 1, 'Na ala alaĩka elĩ mooka Sotomo wĩoo; na Loto ekalĩte mbingĩlonĩ ya Sotomo: na Loto amona, na ookĩla amathaũe; na eekunamya na ũthyũ wake kũvika nthĩ,'),
('kam', 'GEN', 19, 2, 'na amea, Na yu ĩndĩ, eaĩi makwa, nĩngũmũvoya, elelũkai mũlike nyũmbanĩ ya mũthũkũmi wenyu, na kwĩkala ũtukũ w’onthe, na mũithambya maũũ menyu, na mũkookĩla kĩoko tene, mũkwate nzĩa yenyu mũthi. Nao masũngĩa, Aiee, ĩndĩ tũkekala nzĩanĩ ũtukũ w’onthe.'),
('kam', 'GEN', 19, 3, 'Na amathetheesya mũno; na maathũkĩĩa kwake, malika nyũmbanĩ yake; na amavokea mboka na aua kĩmũtũ kĩte ĩlawa, nao maya.'),
('kam', 'GEN', 19, 4, 'Ĩndĩ matanakoma, andũ ma ndũa, o andũ ma Sotomo, mathyũlũlũka nyũmba, ala anini o na ala akũũ, andũ onthe kuma ngalĩ syonthe;'),
('kam', 'GEN', 19, 5, 'na meeta Loto, na mamũkũlya, Maĩva andũ ala mooka kwaku wĩoo ũũ? Tumaalĩlye mo, tũmamanye.'),
('kam', 'GEN', 19, 6, 'Na Loto aumaala mũomonĩ vala maĩ, na avinga mũomo ĩtina wake.'),
('kam', 'GEN', 19, 7, 'Na amea, Nĩngũmwĩsũva, ana‐a‐asa, mũikeke ũthũku ta ũu.'),
('kam', 'GEN', 19, 8, 'Sisya yu, nĩ na eĩtu elĩ mataamanya mũndũ mũũme; nĩngũmwĩsũva, nĩmumĩsye mo, mũmeke ũla mwĩona wĩ ũseo: ĩndĩ andũ aa mũikameke ũndũ, nĩkwĩthĩwa nĩmooka muunyĩnĩ wa kĩala kyakwa.'),
('kam', 'GEN', 19, 9, 'Na mamwĩa, Ĩvete. Na masya, Mũndũ ũũ ũmwe alikile kwitũ kwĩkala ũeni, na kaĩ akeethĩwa mũsili: na yu ĩndĩ nĩtũũkwĩka naĩ, kwĩ aa. Na mamũvivinya mũndũ ũsu Loto mũno, na mathengeea matũle mũomo.'),
('kam', 'GEN', 19, 10, 'Ĩndĩ ala andũ matambũũkya moko moo, malikya Loto vala maĩ nyũmbanĩ, na mavinga mũomo.'),
('kam', 'GEN', 19, 11, 'Na mamekĩa metho mbindu andũ ala maĩ mũomonĩ wa nyũmba, anini o na anene, na ĩndĩ meenosya makĩmantha mũomo.'),
('kam', 'GEN', 19, 12, 'Na andũ asu mamũkũlya Loto, Vaa wĩ na ũngĩ ate o aa? Mũthonuu, na ana maku, na eĩtu maku, na o ũla wĩ nake nthĩnĩ wa ndũa, ũmaumye vandũ vaa:'),
('kam', 'GEN', 19, 13, 'nũndũ tũkaananga vandũ vaa nũndũ ũkayo woo nĩwingĩvĩte mbee wa Yeova; na Yeova nũtũtũmĩte tũvanange.'),
('kam', 'GEN', 19, 14, 'Na Loto aumaala, na aneena na athoni make, ala matwaĩte eĩtu make, amea, Ũkĩlai, mume vandũ vaa; nũndũ Yeova akaananga ndũa. Ĩndĩ kwa athoni make ethĩwa ta ũmwe ũla ũnũũmavũĩa ngũĩ.'),
('kam', 'GEN', 19, 15, 'Na kũikya, nĩvo alaĩka makalaatile Loto, makĩmwĩa, Ũkĩla, wose mũka waku, na eĩtu maku elĩ ala me vaa, ndũkese kwanangĩkĩa kũsilĩlwanĩ kwa ndũa.'),
('kam', 'GEN', 19, 16, 'Ĩndĩ ekalanga; na ala andũ mamũkwata kw’oko, na kw’oko kwa mũka wake, na kw’oko kwa eĩtu make elĩ, kwondũ wa Yeova kũmwĩw’ĩa tei: na mamumaalya, mamwia ũtee wa ndũa.'),
('kam', 'GEN', 19, 17, 'Na kweethĩwa, mamaumaalya ũtee, asya, Vonokya thayũ waku; ndũkasisye na ĩtina, o na ndũkekale Ũiĩnĩ w’onthe; ĩthae ũvike kĩĩmanĩ, ndũkese kwanangĩka.'),
('kam', 'GEN', 19, 18, 'Na Loto amea, Ai, ndũkasye ũu, mwĩaĩi wakwa:'),
('kam', 'GEN', 19, 19, 'sisya yu, mũthũkũmi waku nĩwona ĩnee methonĩ maku, na nĩwaingĩvya ũseo waku wĩ wendo, ũla ũmbonisye ũitangĩĩa thayũ wakwa; na nditonya kwĩthaa kũvika kĩĩmanĩ, ũthũku ndũkese kũngwata, na ngĩkw’a:'),
('kam', 'GEN', 19, 20, 'sisya yu, ndũa ĩno yĩ vakuvĩ nĩindũkĩĩe vo, nayo nĩ nini. Ame nĩvonokesye vo (tĩ nini?), Na kyuu kyakwa kĩkekala.'),
('kam', 'GEN', 19, 21, 'Na amwĩa, Sisya, nĩnakwĩtĩkĩla o na ũndũnĩ ũũ, kana ndikang’uthũla ndũa ĩla waweta.'),
('kam', 'GEN', 19, 22, 'Ĩkalaate, wĩvonokesye vo; nũndũ nditonya kwĩka ũndũ o na wĩva mũvaka yĩla wĩlika vo. Kwondũ wa ũu syĩtwa ya ndũa ĩsu yeetwa Nzoali.'),
('kam', 'GEN', 19, 23, 'Syũa yaĩ yĩnambata ĩũlũ wa nthĩ yĩla Loto walikile Nzoali.'),
('kam', 'GEN', 19, 24, 'Nĩvo Yeova wauisye ĩũlũ wa Sotomo na ĩũlũ wa Ngomola mũvĩlĩtĩ na mwaki kuma ĩtunĩ kwa Yeova;'),
('kam', 'GEN', 19, 25, 'na ang’uthũlanga ndũa isu, na Ũiĩ w’onthe, na andũ onthe ala matwĩe ndũanĩ, na kĩla kyameete ĩũlũ wa nthĩ.'),
('kam', 'GEN', 19, 26, 'Ĩndĩ mũka wake asisya na ĩtina e ĩtina wake, na atw’ĩka kĩtuĩ kya mũnyũ.'),
('kam', 'GEN', 19, 27, 'Na Avalaamu ambata kĩoko tene kũvika vandũ vala ũnaũngamĩte mbee wa Yeova:'),
('kam', 'GEN', 19, 28, 'nake asisya ngalĩ ya Sotomo na Ngomola na ngalĩ ya nthĩ yonthe ya Ũiĩ, na oona, na, sisya, syũki ya nthĩ yambatĩte ta syũki ya iko ĩnene.'),
('kam', 'GEN', 19, 29, 'Na kweethĩwa, Ngai akyananga ndũa sya Ũiĩ, Ngai alilikana Avalaamu, na amumya Loto katĩ wa wanangĩko, yĩla wang’uthũlile ndũa vala Loto watwĩe.'),
('kam', 'GEN', 19, 30, 'Na Loto ambata kuma Nzoali, na ekala kĩĩmanĩ, na eĩtu make elĩ vamwe nake; nũndũ nĩwakĩie kwĩkalaa Nzoali: na ekala ngunganĩ, we na eĩtu make elĩ.'),
('kam', 'GEN', 19, 31, 'Na ũla mũkũũ amwĩa ũla mũnini, Nau nĩ mũkũũ, na kũti mũndũ kũũ nthĩ wa kũlika kwitũ kũatĩĩa ũndũ kwĩkawa nthĩ yonthe:'),
('kam', 'GEN', 19, 32, 'ũka, tũnyw’ĩthye nau mbinyu, tũkome nake, tũmwiĩe nau ũsyao.'),
('kam', 'GEN', 19, 33, 'Na mamũnyw’ĩthya ĩthe mbinyu ũtukũ ũsu: na ũla mũkũũ alika, na akoma na ĩthe wake; na ndaamanya yĩla wakomie, kana yĩla wokĩlile.'),
('kam', 'GEN', 19, 34, 'Na kweethĩwa ũnĩ ũsu, ũla mũkũũ amwĩa ũla mũnini, Sisya, nĩnĩnakomie ũtukũ wa ĩoo na nau: tũmũ-nyw’ĩthye mbinyu ĩngĩ ũtukũ ũũ naw’o; ũlike, ũkome nake, twiĩe nau ũsyao.'),
('kam', 'GEN', 19, 35, 'Na mamũnyw’ĩthya ĩthe mbinyu ĩngĩ ũtukũ ũsu naw’o; na ũla mũnini ookĩla, akoma nake; o na ndaamanya yĩla wakomie, o na yĩla wokĩlile.'),
('kam', 'GEN', 19, 36, 'Na ĩndĩ eĩtu asu elĩ ma Loto maitava ũndũ wa ĩthe woo.'),
('kam', 'GEN', 19, 37, 'Na ũla mũkũũ asyaa mwana, na amwĩta syĩtwa yake Moavi: nĩwe ĩthe wa Amoavi kũvika mũnthĩ ũũ.'),
('kam', 'GEN', 19, 38, 'Na ũla mũnini, nake asyaa mwana, na amwĩta syĩtwa yake Mbeni‐ami: nĩwe ĩthe wa ana ma Amimoni kũvika mũnthĩ ũũ.'),
('kam', 'GEN', 20, 1, 'Na Avalaamu athi kyalo kuma vo aende nthĩ ya ngalĩ ya Ĩtheo, na ekala katĩ wa Katesi na Suli; na ekala ũeni kũu Ngelali.'),
('kam', 'GEN', 20, 2, 'Na Avalaamu asya ũndũ wa Sala mũka wake, Nĩwe mwĩĩtuwa‐ia: na Avimeleki mũsumbĩ wa Ngelali atũmana, na amwosa Sala.'),
('kam', 'GEN', 20, 3, 'Ĩndĩ Ngai amũkĩa Avimeleki ndotonĩ ya ũtukũ, na amwĩa, Sisya, we wĩ o mũndũ mũkw’ũ, kwondũ wa mũndũ mũka ũla wosete; nĩkwĩthĩwa nĩ mũka wa mũndũ.'),
('kam', 'GEN', 20, 4, 'O na Avimeleki ndaĩ anamũthengeea: nake asya, Mwĩaĩi, ũkooaa o na mbaĩ ndũ-ngalu?'),
('kam', 'GEN', 20, 5, 'We mwene ndanambĩa, Nĩwe mwĩĩtu‐a‐ia? O nake, we mwene asya, We nĩ mwana‐a‐ia: nĩneeka ũu na ũlũngalu wa ngoo yakwa na ũtheu wa moko makwa.'),
('kam', 'GEN', 20, 6, 'Na Ngai amwĩa ndotonĩ, Ĩĩ, nĩnĩsĩ kana nĩweeka ũu na ũlũngalu wa ngoo yaku, o nakwa nĩnakũsiĩĩa ndũkambĩtanĩsye; kwondũ wa ũu ndinakũeka ũmũkiite.'),
('kam', 'GEN', 20, 7, 'Na yu ĩndĩ mũtũngĩe mũũme mũka wake; nũndũ nĩ mwathani, nake akakũvoyea, na ũkekala thayũ: na ethĩwa ndwĩmũtũngĩa, we, manya atĩĩ, ndwĩtĩa ũkw’a, we, na onthe ala maku.'),
('kam', 'GEN', 20, 8, 'Na Avimeleki ookĩla kĩoko tene, na ameta athũkũmi make onthe, na amatavya maũndũ asu onthe matũnĩ moo: na andũ makĩa mũno.'),
('kam', 'GEN', 20, 9, 'Na ĩndĩ Avimeleki amwĩta Avalaamu, na amũkũlya, Ũtwĩkie ata? Nakwa ngũvĩtanĩsye ũndũnĩ wĩva, kana ũndetee nyie na ũsumbĩ wakwa naĩ nene? Nũmbĩkie meko mataĩle kwĩkwa.'),
('kam', 'GEN', 20, 10, 'Na Avimeleki akũlya Avalaamu, Wonie kyaũ, ũkĩka ũndũ ũũ?'),
('kam', 'GEN', 20, 11, 'Na Avalaamu asũngĩa, Nũndũ naisye, Nĩ w’o kũkĩa Ngai kũi vandũ vaa; nao makambũaa kwondũ wa mũka wakwa.'),
('kam', 'GEN', 20, 12, 'Na ĩngĩ nĩ w’o nĩ mwĩĩtu‐a‐ia, mwĩĩtu wa nau, ĩndĩ ti mwĩĩtu wa mwaitũ; na atw’ĩka mũka wakwa:'),
('kam', 'GEN', 20, 13, 'na kweethĩwa, yĩla Ngai watumie nĩthi kyalo kuma nyũmbanĩ ya nau, namwĩa, Ũseo waku ũla wĩmbĩkaa nĩ ũũ: kĩla vandũ vala twĩvikaa, ũndũ wakwa aasya, Nĩ mwana‐a‐ia.'),
('kam', 'GEN', 20, 14, 'Na Avimeleki oosa malondu na ng’ombe, na athũkũmi aũme na eĩtu, amũnenga Avalaamu, na amũtũngĩa Sala mũka wake.'),
('kam', 'GEN', 20, 15, 'Na Avimeleki amwĩa, Sisya, nthĩ yakwa yĩ mbee waku: ĩkala vala ũkwenda.'),
('kam', 'GEN', 20, 16, 'Nake amwĩa Sala, Sisya, nĩnanenga mwana‐a‐au ilungu ngili sya vetha: sisya, kwaku nĩ sya ũkũvw’ĩka metho kwa onthe ala me vamwe naku; na ĩngĩ nũlũngalĩtw’e kwa onthe.'),
('kam', 'GEN', 20, 17, 'Na Avalaamu avoya Ngai: na Ngai avosya Avĩmeleki, na mũka wake, na athũkũmi make eĩtu; na masyaa syana.'),
('kam', 'GEN', 20, 18, 'Nũndũ Yeova nĩwavingĩte vyũ mavu ma onthe ma nyũmba ya Avimeleki, kwondũ wa Sala, mũka wa Avalaamu.'),
('kam', 'GEN', 21, 1, 'Na Yeova amũkĩa Sala tondũ waisye, na Yeova amwĩka Sala tondũ waneenie.'),
('kam', 'GEN', 21, 2, 'Na Sala aya ĩvu, na amũsyaĩa Avalaamu mwana ũkũunĩ wake, ĩvinda yĩtw’e yĩla watavĩw’e nĩ Ngai.'),
('kam', 'GEN', 21, 3, 'Na Avalaamu eeta syĩtwa ya mwana wake ũla wasyaiwe, ũla Sala wamũsyaĩe, Isaka.'),
('kam', 'GEN', 21, 4, 'Na Avalaamu amwaĩka Isaka mwana wake e wa matukũ nyanya, o tondũ Ngai wamwĩaĩe.'),
('kam', 'GEN', 21, 5, 'Na Avalaamu aĩ wa myaka ĩana, yĩla wasyaĩwe mwana wake Isaka.'),
('kam', 'GEN', 21, 6, 'Na Sala asya, Ngai nũtumie nĩtheka; kĩla ũmwe wĩĩw’aa akathekaa vamwe nakwa.'),
('kam', 'GEN', 21, 7, 'Nake asya, Nũũ ũla waĩ atavya Avalaamu, atĩ Sala nũkongya syana? Nũndũ nĩnamũsyaĩa mwana ũkũunĩ wake.'),
('kam', 'GEN', 21, 8, 'Na mwana eana, na aaĩw’a: na Avalaamu avoka mboka nene mũthenya ũla Isaka waaĩw’e.'),
('kam', 'GEN', 21, 9, 'Na Sala oona mwana wa Akali, Mũmisili, ũla wamũsyaĩe Avalaamu, aivũa ngũĩ.'),
('kam', 'GEN', 21, 10, 'Kwondũ wa ũu amwĩa Avalaamu, Lũngya mũthũkũmi ũũ, mwĩĩtu, na mwana wake: nũndũ mwana wa mũthũkũmi ũũ, mwĩĩtu, ndakethĩwa e mũtiĩwa vamwe na mwana wakwa, o ũũ Isaka.'),
('kam', 'GEN', 21, 11, 'Na ũndũ ũsu waĩ ũthũku mũno methonĩ ma Avalaamu kwondũ wa mwana wake.'),
('kam', 'GEN', 21, 12, 'Na Ngai amwĩa Avalaamu, Ndũkethĩwe wĩ ũthũku methonĩ maku nũndũ wa mwana, na nũndũ wa mũthũkũmi waku, mwĩĩtu; nthĩnĩ wa w’onthe ũla Sala ũnũũkũtavya, wĩthukĩĩsye wasya wake; nũndũ ũsyao waku ũkeetwa nthĩnĩ wa Isaka.'),
('kam', 'GEN', 21, 13, 'O na mwana wa mũthũkũmi, mwĩĩtu, ngamũtw’ĩkĩthya mbaĩ, nũndũ nake nĩ ũsyao waku.'),
('kam', 'GEN', 21, 14, 'Na Avalaamu ookĩla kĩoko tene, na oosa kĩmũtũ na kathatwa ka manzĩ, na amũnenga Akali, amwaĩkya kĩtuonĩ kyake, na amũnenga mwana, na amwĩa athi: nake athi, na anganga weũnĩ wa Mbeeli‐sieva.'),
('kam', 'GEN', 21, 15, 'Na manzĩ mathela kathatwanĩ, na aia mwana ungu wa kakuthu kamwe.'),
('kam', 'GEN', 21, 16, 'Nake aenda, na ekala nthĩ amwelekele e kũasa, ta yĩkwa ya ũta: nũndũ asya, Ndikone kĩkw’ũ kya mwana. Na ekala amwelekele, na ookĩlya wasya wake, na aĩa.'),
('kam', 'GEN', 21, 17, 'Na Ngai eew’a wasya wa kĩvĩsĩ; na mũlaĩka wa Ngai amwĩta Akali e ĩtunĩ, na amũkũlya, Wĩ na ũndũ mwaũ, Akali? Ndũkakĩe; nũndũ Ngai nĩwew’a wasya wa kĩvĩsĩ vala kĩĩ.'),
('kam', 'GEN', 21, 18, 'Ũkĩla wũkĩlye kĩvĩsĩ, na ũkĩkĩkwata kw’okonĩ kwaku; nũndũ ngakĩtw’ĩkĩthya mbaĩ nene.'),
('kam', 'GEN', 21, 19, 'Na Ngai amũsalukya metho make, na oona kĩthima kya manzĩ; na athi, na ausũsya kathatwa manzĩ, na akĩnenga kĩvĩsĩ kĩnyw’e.'),
('kam', 'GEN', 21, 20, 'Na Ngai aĩ vamwe na kĩvĩsĩ, nakyo kyeana; na kyekalaa kũu weũnĩ, na kĩkĩana, kyatw’ĩka mũndũ wa ũta.'),
('kam', 'GEN', 21, 21, 'Na atũaa ũiĩnĩ wa Valani: na inyia wake amumĩsye mũka nthĩ ya Misili.'),
('kam', 'GEN', 21, 22, 'Na kweethĩwa ĩvinda yĩu, Avimeleki na Vikoli kavuteni wa nguthu yake maneena na Avalaamu, makĩmwĩa, Ngai e vamwe naku maũndũnĩ onthe ala wĩkaa:'),
('kam', 'GEN', 21, 23, 'na yu ĩndĩ ĩmbĩtĩe vaa na Ngai kana ndũkambĩka na ũkengani, o na mwana wakwa, o na mwĩsũkũũwa: ĩndĩ kwĩanana na ũseo ũla nakwĩkie, we ũkambĩka nyie, na nthĩ ĩla wĩkalĩte ũeni.'),
('kam', 'GEN', 21, 24, 'Na Avalaamu asũngĩa, Nĩngwĩvĩta.'),
('kam', 'GEN', 21, 25, 'Na Avalaamu amũkan’ya Avimeleki nũndũ wa kĩthima kya manzĩ, kĩla athũkũmi ma Avimeleki mavenanie.'),
('kam', 'GEN', 21, 26, 'Na Avimeleki amwĩa, Ndyĩsĩ ũla wekie ũndũ ũũ: o na ndwaandavya, o na ndyaaĩw’a nyie, ate o ũmũnthĩ.'),
('kam', 'GEN', 21, 27, 'Na Avalaamu oosa malondu na ng’ombe, na amũnenga Avimeleki; na me elĩ matianĩa ũtianĩo.'),
('kam', 'GEN', 21, 28, 'Na Avalaamu aia tũmyati mũonza twa ĩĩthya twĩ tw’oka.'),
('kam', 'GEN', 21, 29, 'Na Avimeleki amũkũlya Avalaamu, Nĩ twa kĩ tũmyati tũũ mũonza wiĩte tw’oka?'),
('kam', 'GEN', 21, 30, 'Nake asũngĩa, Tũmyati tũũ mũonza ũtwose kw’okonĩ kwakwa, wĩthĩwe ũkũsĩ kwakwa, kana ninyie nĩnzĩte kĩthima kĩĩ.'),
('kam', 'GEN', 21, 31, 'Kwondũ wa ũu eeta vandũ vau Mbeeli‐sieva; nũndũ nĩvo meevĩtĩe me elĩ.'),
('kam', 'GEN', 21, 32, 'Na ĩndĩ matianĩa ũtianĩo vu Mbeeli‐sieva: na Avimeleki ookĩla, na Vikoli kavuteni wa nguthu yake, na masyoka nthĩ ya Avilisiti.'),
('kam', 'GEN', 21, 33, 'Na Avalaamu avanda mũtĩ wa mweseli vau Mbeeli‐sieva, na eekaĩlĩla syĩtwa ya Yeova kũu, Ngai Wa Tene Na Tene.'),
('kam', 'GEN', 21, 34, 'Na Avalaamu ekala ũeni nthĩ ya Avilisiti matukũ maingĩ.'),
('kam', 'GEN', 22, 1, 'Na kweethĩwa ĩtina wa maũndũ asu, Ngai atata Avalaamu, na amwĩa, Avalaamu; nake asũngĩa, Ninyioo.'),
('kam', 'GEN', 22, 2, 'Na amwĩa, Osa yu mwana waku, mwana waku e ũmwe, ũla wendete, o Isaka, ũende nthĩ ya Molia; na ũkamũthembee vo ethĩwe nthembo ya kũvĩvw’a ĩũlũ wa kĩĩma kĩmwe kĩla ngakũtavya.'),
('kam', 'GEN', 22, 3, 'Na Avalaamu ookĩla kĩoko tene, na atandĩka ĩng’oi yake, na oosa anake elĩ make mathi nake, na Isaka mwana wake; na aalya ngũ sya nthembo ya kũvĩvw’a, na ookila, na aenda vandũ vala Ngai ũmũtavisye.'),
('kam', 'GEN', 22, 4, 'Mũthenya wa katatũ Avalaamu ookĩlya metho make, oona vala vandũ ve kũasa.'),
('kam', 'GEN', 22, 5, 'Na Avalaamu amea anake make, Inyw’ĩ ĩkalai vaa na ĩng’oi, nakwa na mwana nĩtũũthi kũya; na tũkathaitha, na kũmũsyokea ĩngĩ.'),
('kam', 'GEN', 22, 6, 'Na Avalaamu oosa ngũ sya nthembo ya kũvĩvw’a, amwaĩkya Isaka mwana wake; na akua kw’okonĩ kwake mwaki na kavyũ; na maendan’ya me elĩ.'),
('kam', 'GEN', 22, 7, 'Na Isaka aneena na Avalaamu ithe wake, na amwĩa, Nau: nake asũngĩa, Ninyioo, mwana wakwa. Na asya, Sisya, mwaki na ngũ: ĩndĩ kaĩva katena ka ĩlondu ka nthembo ya kũvĩvw’a?'),
('kam', 'GEN', 22, 8, 'Na Avalaamu asũngĩa, Ngai akeemanthĩa katena ka ĩlondu ka nthembo ya kũvĩvw’a, mwana wakwa: na ĩndĩ maendan’ya me elĩ.'),
('kam', 'GEN', 22, 9, 'Na mavika vandũ vala Ngai wamũtavĩtye; na Avalaamu aaka kĩthembeo vo, na aĩĩa ngũ, na amwova Isaka mwana wake, na amwia kĩthembeonĩ, ĩũlũ wa ngũ.'),
('kam', 'GEN', 22, 10, 'Na Avalaamu atambũũkya kw’oko kwake, oosa kavyũ oae mwana wake.'),
('kam', 'GEN', 22, 11, 'Na mũlaĩka wa Yeova amwĩta kuma ĩtunĩ, na amwĩa, Avalaamu, Avalaamu: nake asũngĩa, Ninyioo.'),
('kam', 'GEN', 22, 12, 'Na amwĩa, Ndũkailĩĩle mwana kw’oko kwaku, o na ndũkamwĩke ũndũ; nũndũ yu nĩnĩsĩ kana nũmũkĩĩte Ngai, nũndũ ndũnambata mwana waku, mwana waku e ũmwe.'),
('kam', 'GEN', 22, 13, 'Na Avalaamu ookĩlya metho, oona, na, sisya, ĩtina wake ndũũme ĩkwetwe mbya syayo nĩ kĩkuthu: na Avalaamu aenda na oosa ndũũme, na amĩthemba nthembo ya kũvĩvw’a vandũ va mwana wake.'),
('kam', 'GEN', 22, 14, 'Na Avalaamu eeta vandũ vau syĩtwa yavo Yeova‐yile: o tondũ kwaaw’a kũvika mũnthĩ ũũ, Kĩĩmanĩ kya Yeova kĩkooneka.'),
('kam', 'GEN', 22, 15, 'Na mũlaĩka wa Yeova amwĩta Avalaamu ya kelĩ e ĩtunĩ,'),
('kam', 'GEN', 22, 16, 'na amwĩa, Nyie mwene nĩneevĩta, Yeova easya ũu, nũndũ nĩweeka ũndũ ũũ, na ndũnambata mwana waku, mwana waku e ũmwe,'),
('kam', 'GEN', 22, 17, 'kana kũathima ngakũathima, na kwingĩvya ngaingĩvya ũsyao waku ta ndata sya matunĩ, na ta kĩthangathĩ kĩ ũtee wa ũkanga; na ũsyao waku ũkatiĩwa mbingĩlo ya amaitha maw’o;'),
('kam', 'GEN', 22, 18, 'na ũsyaonĩ waku mbaĩ syonthe sya nthĩ ikaathimwa; nũndũ nĩweew’a wasya wakwa.'),
('kam', 'GEN', 22, 19, 'Na ĩndĩ Avalaamu amasyokea anake make, na mookĩla maendan’ya kũvika Mbeeli‐sieva; na Avalaamu atũa Mbeeli‐sieva.'),
('kam', 'GEN', 22, 20, 'Na kweethĩwa ĩtina wa maũndũ asu, Avalaamu atavw’a, kũineenwa, Sisya, Milika, nake nũsyaĩe mwana‐a‐mwenyu Naoli syana:'),
('kam', 'GEN', 22, 21, 'Usi ĩkithathi yake, na Mbusi mwana‐a‐inyia, na Kemueli ĩthe wa Alamu,'),
('kam', 'GEN', 22, 22, 'na Keseti, na Aso, na Vilitasi, na Yitilavu, na Mbethueli.'),
('kam', 'GEN', 22, 23, 'Na Mbethueli asyaa Leveka: asu nyanya Milika asyaĩa Naoli, mwana‐a‐inyia wa Avalaamu.'),
('kam', 'GEN', 22, 24, 'Na mũka wake ngombo, syĩtwa yake Leuma, nake asyaa Teva, na Ngaamu, na Taasi, na Maaka.'),
('kam', 'GEN', 23, 1, 'Na Sala ekalile thayũ myaka ĩana na mĩongo ĩlĩ na mũonza: nĩyo myaka ya thayũ wa Sala.'),
('kam', 'GEN', 23, 2, 'Na Sala akw’ĩa Kiliathi‐aliva (nĩyo Eviloni), kũu nthĩ ya Kanaani: na Avalaamu ooka kũmũmetea Sala, na kũmũĩĩa.'),
('kam', 'GEN', 23, 3, 'Na Avalaamu ookila kuma mbee wa mũkw’ũ wake, na aneena na ana ma Ethi, akĩmea,'),
('kam', 'GEN', 23, 4, 'Nĩ mũeni na mwĩkali wa ũeninĩ kwenyu: nengai vandũ va mbũa kwenyu, nĩthike mũkw’ũ wakwa nĩeke ũmwona.'),
('kam', 'GEN', 23, 5, 'Na ana ma Ethi masũngĩa Avalaamu, makĩmwĩa,'),
('kam', 'GEN', 23, 6, 'Twĩthukĩĩsye, mwĩaĩi wakwa; wĩ mũnene katĩ waitũ wa Ngai: ngunganĩ sitũ ila nzeo mbee thika mũkw’ũ waku; vai ũmwe katĩ waitũ wĩkũvata ngunga yake, ndũkathike mũkw’ũ waku.'),
('kam', 'GEN', 23, 7, 'Na Avalaamu ookĩla, eekunamĩsya andũ ma nthĩ ĩsu, ala andũ ma Ethi.'),
('kam', 'GEN', 23, 8, 'Nake aneenan’ya nao, akĩmea, Ethĩwa nĩ kĩsũanĩo kyenyu nĩthike mũkw’ũ wakwa nĩeke ũmwona, mbĩthukĩĩsyai, na mboyeai kwa Eveloni mwana wa Nzooali,'),
('kam', 'GEN', 23, 9, 'nĩ kana anenge ngunga yĩ Makivela, ĩla wĩ nayo, ĩla yĩ mũthyanĩ wa kĩsesi kyake; na thooa mwĩanĩu anengee katĩ wenyu yĩthĩwe vandũ va mbũa.'),
('kam', 'GEN', 23, 10, 'Na ĩndĩ Eveloni ekalĩte katĩ wa ana ma Ethi: na Eveloni, ũla Mũititi, asũngĩa Avalaamu ana ma Ethi makĩw’a, o na onthe ala malikaa mbingĩlonĩ ya ndũa yake, akĩmwĩa,'),
('kam', 'GEN', 23, 11, 'Aiee, mwĩaĩi wakwa, mbĩthukĩĩsya: kĩsesi nĩngũũnenga, na ngunga ĩla yĩ vo, nĩngũũnenga; ana ma andũ makwa me vaa nĩngũũnenga: thika mũkw’ũ waku.'),
('kam', 'GEN', 23, 12, 'Na Avalaamu eekunamĩsya andũ ma nthĩ ĩsu.'),
('kam', 'GEN', 23, 13, 'Na aneena na Eveloni andũ ma nthĩ ĩsu makĩwa’, aimwĩa, Ĩndĩ wenda, nĩngũkwĩsũva, mbĩthukĩĩsya: nĩngũũnenga thooa wa kĩsesi; osa kwakwa, nakwa nĩngũthika mũkw’ũ wakwa vo.'),
('kam', 'GEN', 23, 14, 'Na Eveloni asũngĩa Avalaamu, akĩmwĩa,'),
('kam', 'GEN', 23, 15, 'Mwĩaĩi wakwa mbĩthukĩĩsya: kĩlungu kya nthĩ kĩanĩe thooa wa sekeli sya vetha maana ana, isu nĩ myaũ katĩ wakwa naku? Thika ĩndĩ mũkw’ũ waku.'),
('kam', 'GEN', 23, 16, 'Na Avalaamu eethukĩĩsya Eveloni; na Avalaamu athimĩa Eveloni vetha ila wawetie ana ma Ethi makĩw’a, sekeli sya vetha maana ana, ila itandĩthasya na mũthoosya.'),
('kam', 'GEN', 23, 17, 'Na ĩndĩ kĩsesi kya Eveloni, kĩla kyaĩ nthĩnĩ wa Makivela, kĩla kyaĩ mbee wa Mamile, kĩsesi, na ngunga ĩla yaĩ nthĩnĩ wakyo, na mĩtĩ yonthe ĩla yaĩ kĩsesinĩ, ĩla yaĩ nthĩnĩ wa mĩvaka yakyo yonthe, kyalũlũmĩlw’a'),
('kam', 'GEN', 23, 18, 'kyatw’ĩka kya Avalaamu ki, ana ma Ethi me vo, mbee wa onthe ala malikaa mbingilonĩ ya ndũa yake.'),
('kam', 'GEN', 23, 19, 'Na ĩtina wa ũu, Avalaamu athika Sala mũka wake ngunganĩ ya kĩsesi kĩ Makivela mbee wa Mamile (nĩyo Eviloni), kũu nthĩ ya Kanaani.'),
('kam', 'GEN', 23, 20, 'Na kĩsesi, na ngunga ĩla yaĩ nthĩnĩ wakyo, kyalũlũmĩlw’a kwa Avalaamu nĩ ana ma Ethi kĩthĩwe vandũ va mbũa.'),
('kam', 'GEN', 24, 1, 'Na Avalaamu aĩ mũkũu, na wa myaka mingĩ: na Yeova ethĩwa aathimĩte Avalaamu maũndũnĩ onthe.'),
('kam', 'GEN', 24, 2, 'Na Avalaamu amwĩa mũthũkũmi wake, ũla waĩ mũkũu nyũmbanĩ yake, ũla waiĩtwe ĩũlũ wa syonthe ila waĩ nasyo, Nĩngũũvoya, ĩkĩa kw’oko kwaku ungu wa waswa wakwa:'),
('kam', 'GEN', 24, 3, 'nakwa nĩngũkwĩavĩthya kwa Yeova, Ngai wa ĩtu na Ngai wa nthĩ, ndũkatwaĩe mwana wakwa mũka eĩtunĩ ma Akanaani, ala nĩtũaa katĩ woo:'),
('kam', 'GEN', 24, 4, 'ĩndĩ ũkaenda kũvika nthĩ yakwa, na ũkonĩ wakwa, ũtwaĩe mwana wakwa Isaka mũka.'),
('kam', 'GEN', 24, 5, 'Na mũthũkũmi amwĩa, Nokwĩthĩwa mũndũ mũka ndakenda kũmbikĩla kũvika nthĩ ĩno: no mũvaka nĩmũtũnga ĩngĩ mwana waku nthĩ ĩla waumie?'),
('kam', 'GEN', 24, 6, 'Na Avalaamu amwĩa, Ĩsũvĩe ndũkaamũtũnge mwana wakwa kũu ĩngĩ.'),
('kam', 'GEN', 24, 7, 'Yeova, Ngai wa ĩtu, ũla wanumisye nyũmbanĩ ya asa wakwa, na kuma nthĩ ĩla nasyaĩwe, ũla waneenie nakwa, na eembĩtĩa, akyasya, Ũsyao waku ngoonenga nthĩ ĩno; we akatũma mũlaĩka wake mbee waku, naku ũkatwaĩa mwana wakwa mũka kuma kw’o.'),
('kam', 'GEN', 24, 8, 'Na ethĩwa mũndũ mũka ndekwenda ũkũvikĩla, ũkaekewa wĩvĩto ũũ wakwa: ĩndĩ ndũkaamũtũnge mwana wakwa kũu ĩngĩ.'),
('kam', 'GEN', 24, 9, 'Na mũthũkũmi eekĩa kw’oko kwake ungu wa waswa wa Avalaamu vwana wake, na amwĩavĩa ũndũnĩ ũsu.'),
('kam', 'GEN', 24, 10, 'Na mũthũkũmi oosa ngamĩle ĩkũmi, ngamĩlenĩ sya vwana wake, na akũsya e na syĩndũ syonthe nzeo sya vwana wake kw’okonĩ kwake: na ookĩla, na aenda Mesovotamia, kũvika ndũanĩ ya Naoli.'),
('kam', 'GEN', 24, 11, 'Na atulĩthya ngamĩle ndu ũtee wa ndũa kĩthimanĩ ĩvinda ya wĩoo, ĩvinda yĩla aka maendaa kũtava manzĩ.'),
('kam', 'GEN', 24, 12, 'Nake asya, Ame Yeova, Ngai wa vwana wakwa Avalaamu, nĩngũũvoya, mbaĩlĩlya ũmũnthĩ, wĩke vwana wakwa Avalaamu nesa.'),
('kam', 'GEN', 24, 13, 'Sisya, nyie nĩũngamĩte nthongonĩ ya manzĩ; na eĩtu andũ ma ndũa nĩmekũka kũtava manzĩ:'),
('kam', 'GEN', 24, 14, 'nĩkwĩthĩwe, mwĩĩtu ũla ngũmũtavya, Aũa kĩtete kyaku kya yũmba, nĩngũũvoya, nĩnyw’e; nake akambĩa, Nyw’a, na nĩngũnyithya ngamĩle syaku nasyo: ũsu nĩethĩwe ũla wamũnyuvĩe mũthũkũmi waku Isaka; nĩw’o nĩmanya kana nũmwĩkĩte vwana wakwa nesa.'),
('kam', 'GEN', 24, 15, 'Na kweethĩwa, atanamina kũneena, sisya, Leveka aumaala, ũla wasyaĩwe Mbethueli mwana wa Milika, mũka wa Naoli, mwana‐a‐inyia wa Avalaamu, e na kĩtete kyake kĩtuonĩ kyake.'),
('kam', 'GEN', 24, 16, 'Na mwĩĩtu aĩ mwanake mũno kwa kũsiw’a, mũtheu, o na vatyaĩ mũndũ mũũme waamũmanya; nake atheea nthongonĩ, ausũsya kĩtete kyake, na ambata.'),
('kam', 'GEN', 24, 17, 'Na mũthũkũmi asemba kũmũthaũa, amwĩa, Nenga nĩnyw’e, nĩngũũvoya, tũmanzĩ kuma kĩtetenĩ kyaku.'),
('kam', 'GEN', 24, 18, 'Nake asũngĩa, Nyw’a, mwĩaĩi wakwa: nake eekalaata, na atheesya kĩtete kyake kw’okonĩ kwake, na amũnenga anyw’e.'),
('kam', 'GEN', 24, 19, 'Na amina ũmũnenga anyw’e, amwĩa, Nĩngũtavĩa ngamĩle syaku nasyo, mũvaka ilaũke.'),
('kam', 'GEN', 24, 20, 'Na eekalaata, oonosya kĩtete kyake mũvalatĩnĩ, na asemba ĩngĩ kĩthimanĩ kũtava, na atavĩa ngamĩle syake syonthe.'),
('kam', 'GEN', 24, 21, 'Na ũla mũndũ amũketeea, akilĩtye, amanye kana Yeova nũmwaĩlĩlye kyalo kyake kana ti w’o.'),
('kam', 'GEN', 24, 22, 'Na kweethĩwa, ngamĩle syalaũka, ũla mũndũ oosa ngome ya thaavu, ũito wayo nyunzu ya sekeli, na itang’a ilĩ kwondũ wa moko make ũito wa thaavu wa sekeli ĩkũmi,'),
('kam', 'GEN', 24, 23, 'akũlya, Wĩ mwĩĩtu waũ, we? Nĩngũkwĩsũva, ndavya. Ve ũthei nyũmbanĩ ya au wa ũtũ-komya?'),
('kam', 'GEN', 24, 24, 'Nake amũsũngĩa, Nĩ mwĩĩtu wa Mbethueli mwana wa Milika, ũla wamũsyaĩe Naoli.'),
('kam', 'GEN', 24, 25, 'Na ĩngĩ amwĩa, Twĩ na ũa o na ũĩthyo mwĩanĩu, na ũthei wa kũmũkomya.'),
('kam', 'GEN', 24, 26, 'Na ũla mũndũ akunamya mũtwe, na athaitha Yeova.'),
('kam', 'GEN', 24, 27, 'Nake asya, Nataĩwe Yeova, Ngai wa vwana wakwa Avalaamu, ũla ũtaaeka ũseo wake wĩ wendo na w’o wake kwa vwana wakwa: nakwa, Yeova nũndongoesye nzĩanĩ kũvika nyũmba ya ana‐a‐inyia ma vwana wakwa.'),
('kam', 'GEN', 24, 28, 'Na mwĩĩtu asemba, atavan’ya nyũmbanĩ ya inyia wake o ndeto isu.'),
('kam', 'GEN', 24, 29, 'Na Leveka aĩ na mwana‐a‐inyia, na syĩtwa yake eetawa Lavani: na Lavani asemba vala ve ũla mũndũ, kũvika nthongonĩ.'),
('kam', 'GEN', 24, 30, 'Na kweethĩwa, yĩla wonie ngome, na itang’a mokonĩ ma mwĩĩtu‐a‐inyia, na eew’a ndeto sya Leveka, mwĩtũ‐a‐inyia, akyasya, Ũla mũndũ andavya ũna na ũna; ooka vala ve ũla mũndũ; na, sisya, aũngamĩte na ngamĩle nthongonĩ.'),
('kam', 'GEN', 24, 31, 'Na amwĩa, Lika, we, ũathimĩtwe nĩ Yeova; ũũngamĩte nza nĩkĩ? Nũndũ nĩnzeũvisye nyũmba, na vandũ va ngamĩle.'),
('kam', 'GEN', 24, 32, 'Na ũla mũndũ avota nyũmbanĩ, na athasya ngamĩle; na anenga ngamĩle ũa na ũĩthyo, na manzĩ ma ũthambya maũũ make na maũũ ma andũ ala maĩ nake.'),
('kam', 'GEN', 24, 33, 'Na vaiwa lĩu mbee wake aye: ĩndĩ asya, Ndiya, ndanatavan’ya ũndũ ndũmiwe. Na asũngĩa, Neena ĩndĩ.'),
('kam', 'GEN', 24, 34, 'Nake asya, Nyie nĩ mũthũkũmi wa Avalaamu.'),
('kam', 'GEN', 24, 35, 'Na Yeova nũathimĩte vwana wakwa mũno; na nũtw’ĩkĩte mũnene: nũmũnengete ndĩthya sya mbũi na malondu na sya ng’ombe, na vetha na thaavu, na athũkũmi aũme na eĩtu, na ngamĩle na mang’oi.'),
('kam', 'GEN', 24, 36, 'Na Sala mũka wa vwana wakwa nĩwamũsyaĩe vwana wakwa mwana yĩla waĩ mũkũu: nake amũnengete syonthe ila wĩ nasyo.'),
('kam', 'GEN', 24, 37, 'Na vwana wakwa nĩwatumie nĩvĩta, akĩmbĩa, Ndũkaamũtwaĩe mwana wakwa mũka eĩtunĩ ma Akanaani, ala nĩtwĩe nthĩ yoo:'),
('kam', 'GEN', 24, 38, 'ĩndĩ ũkathi nyũmbanĩ ya asa wakwa, kwa ũko wakwa, na ũkamũtwaĩe mwana wakwa mũka.'),
('kam', 'GEN', 24, 39, 'Nakwa namwĩa vwana wakwa, Nokwĩthĩwa mũndũ mũka atakambikĩla.'),
('kam', 'GEN', 24, 40, 'Nake ambĩa, Yeova, ũla nĩendaa mbee wake, akatũma mũlaĩka wake vamwe naku, akwaĩlĩlye nzĩa yaku; naku ũkamũtwaĩa mwana wakwa mũka wa ũko wakwa, na wa nyũmba ya asa wakwa:'),
('kam', 'GEN', 24, 41, 'nĩvo wĩekewa wĩvĩto wakwa, wavika kwa ũko wakwa; na malea ũkũnenga, ũkaekewa wĩvĩto wakwa.'),
('kam', 'GEN', 24, 42, 'Na nĩnũkie mũnthĩ ũũ nthongonĩ, nasya, Ame Yeova, Ngai wa vwana wakwa Avalaamu, ethĩwa yu nũũmbaĩlĩlya nzĩa yakwa ĩla nĩendaa:'),
('kam', 'GEN', 24, 43, 'sisya, nĩũngamĩte nthongonĩ ya manzĩ; na nĩkwĩthĩwe, mwĩĩtu ũla ũnũũka kũtava, ũla ngũmwĩa, Nenga nĩnyw’e, nĩngũũvoya, tũmanzĩ kuma kĩtetenĩ kyaku:'),
('kam', 'GEN', 24, 44, 'nake akambĩa, Nyw’a, we, na ngamĩle syaku nasyo nĩngwitavĩa: ũsu nĩethĩwe mũndũ mũka ũla Yeova ũnyuvĩe mwana wa vwana wakwa.'),
('kam', 'GEN', 24, 45, 'Na ndanamina kũneena ngoonĩ yakwa, sisya, Leveka aumaala na kĩtete kyake kĩtuonĩ kyake; na atheea nthongonĩ, na atava: nakwa namwĩa, Nenga nĩnyw’e, nĩngũkwĩsũva.'),
('kam', 'GEN', 24, 46, 'Nake eekalaata, atheesya kĩtete kyake kuma kĩtuonĩ kyake, na ambĩa, Nyw’a, na nĩngũnyithya ngamĩle syaku nasyo: nakwa nanyw’a, na anyithya ngamĩle nasyo.'),
('kam', 'GEN', 24, 47, 'Na namũkũlya, nasya, Wĩ mwĩĩtu waũ, we? Nake asũngĩa, Nĩ mwĩĩtu wa Mbethueli, mwana wa Naoli, ũla Milika wamũsyaĩe: nakwa namwĩkĩa ngome ĩnyiũũ, na itang’a moko.'),
('kam', 'GEN', 24, 48, 'Nakwa nakunamya mũtwe, nathaĩtha Yeova, na nataĩa Yeova, Ngai wa vwana wakwa Avalaamu, ũla wandongoesye nzĩanĩ ya w’o nĩmũtwaĩe mwana wa vwana wakwa mwĩĩtu wa mwana‐a‐inyia wake.'),
('kam', 'GEN', 24, 49, 'Na yu ĩndĩ ethĩwa mũkeeka vwana wakwa nesa na w’o, ndavyai: na ethĩwa ti w’o, ndavyai; nĩthyũũe kw’okonĩ kwa aũme, kana kwa aka.'),
('kam', 'GEN', 24, 50, 'Nĩvo Lavani na Mbethueli masũngĩie na masya, Ũndũ ũũ wumĩte kwa Yeova: tũitonya kũneena naku ũthũku kana ũseo.'),
('kam', 'GEN', 24, 51, 'Sisya, Leveka e mbee waku, mwose, ũende, ethĩwe mũka wa mwana wa vwana waku, o tondũ Yeova waĩtye.'),
('kam', 'GEN', 24, 52, 'Na kweethĩwa, mũthũkũmi wa Avalaamu eew’a ndeto syoo, eekunamĩsya Yeova kũvika nthĩ.'),
('kam', 'GEN', 24, 53, 'Na ũla mũthũkũmi aumya mĩio ya wanake ya vetha, na thaavu, na ngũa, na amũnenga Leveka: o na mwana‐a‐inyia na inyia amanenga syĩndũ syĩ vata mũno.'),
('kam', 'GEN', 24, 54, 'Nao maya na manyw’a, we na andũ ala maĩ vamwe nake, na mekala ũtukũ w’onthe; na mookĩla kĩoko, nake asya, Ekai nĩthi kwa vwana wakwa.'),
('kam', 'GEN', 24, 55, 'Na mwana‐a‐inyia na inyia masya, Mwĩĩtu ekale naitũ matukũ mavũthũ, ta ĩkũmi; ĩtina wa ũu akathi.'),
('kam', 'GEN', 24, 56, 'Na amea, Mũikanziĩĩe, nũndũ Yeova nũmbaĩlĩlye nzĩa yakwa; ekai nĩthi kwa vwana wakwa.'),
('kam', 'GEN', 24, 57, 'Nao masya, Nĩtũkwĩta mwĩĩtu, tũmũkũlye ũndũ ũnũkwasya.'),
('kam', 'GEN', 24, 58, 'Na mamwĩta Leveka, mamũkũlya, Nũkũenda na mũndũ ũũ? Nake asũngĩa, Nĩngũthi.'),
('kam', 'GEN', 24, 59, 'Na maeka Leveka mwĩĩtu‐a‐inyia woo athi, na mũei wake, na mũthũkũmi wa Avalaamu, na andũ make.'),
('kam', 'GEN', 24, 60, 'Na maathima Leveka, mamwĩa, We mwĩĩtu‐a‐ia, wĩthĩwe wĩ inyia wa ngili kũndũ ngili makũmi, na ũsyao waku nĩũmesye mbingĩlo ya ala mamamenaa.'),
('kam', 'GEN', 24, 61, 'Na Leveka ookĩla, na athũkũmi make eĩtu, na matũla ngamĩle, mamũvikĩla ũla mũndũ: na mũthũkũmi oosa Leveka, akwata nzĩa yake athi.'),
('kam', 'GEN', 24, 62, 'Na Isaka ooka na nzĩa ya Mbeeli‐laai‐loi; nũndũ atũaa nthĩ ya ngalĩ ya Ĩtheo.'),
('kam', 'GEN', 24, 63, 'Na Isaka aumaala akasũanĩe kĩsesinĩ wĩoo: na ookĩlya metho, oona, na, sisya, kwaĩ ngamĩle syũkĩte.'),
('kam', 'GEN', 24, 64, 'Na Leveka ookĩlya metho, na oona Isaka, auma ngamĩlenĩ.'),
('kam', 'GEN', 24, 65, 'Na amũkũlya mũthũkũmi, Mũndũ ũya nũũ ũnũkũtambũka kĩsesinĩ atũthaũĩte? Na ũla mũthũkũmi amwĩa, Nĩwe vwana wakwa: na oosa suka wake mũvũthũ, eekunĩkĩlya.'),
('kam', 'GEN', 24, 66, 'Na ũ mũthũkũmi atavya Isaka maũndũ onthe ala wĩkĩte.'),
('kam', 'GEN', 24, 67, 'Na Isaka amũete ĩeemanĩ ya inyia wake Sala, na oosa Leveka, na atw’ĩka mũka wake; na amwenda: na Isaka akiakiw’a ĩtina wa kĩkw’ũ kya inyia wake.'),
('kam', 'GEN', 25, 1, 'Na Avalaamu atwaa mũka ũngĩ, na syĩtwa yake eetawa Ketula.'),
('kam', 'GEN', 25, 2, 'Nake amũsyaĩa Nzimilani, na Yokisani, na Metani, na Mitiani, na Isivaki, na Suua.'),
('kam', 'GEN', 25, 3, 'Na Yokisani asyaa Sieva, na Ndetani. Na ana ma Ndetani maĩ Aasuli, na Aletusi, na Aleumi.'),
('kam', 'GEN', 25, 4, 'Na ana ma Mitiani: Evaa, na Evieli, na Anoki, na Avita, na Elitaa. Asu onthe maĩ ana ma Ketula.'),
('kam', 'GEN', 25, 5, 'Na Avalaamu anenga Isaka syonthe ila waĩ nasyo.'),
('kam', 'GEN', 25, 6, 'Ĩndĩ ana ma aka ngombo, ala Avalaamu waĩ nao, Avalaamu amanenga mĩthĩnzĩo; nake e thayũ, amea mathi kũasa na Isaka mwana wake, melekele wumĩlonĩ wa syũa, kũvika nthĩ ya wumĩlonĩ wa syũa.'),
('kam', 'GEN', 25, 7, 'Aa nĩmo matukũ ma myaka ya thayu wa Avalaamu ala wekalile, myaka ĩana na mĩongo mũonza na ĩtano.'),
('kam', 'GEN', 25, 8, 'Na Avalaamu aumwa nĩ veva, akw’a ũkũunĩ mũseo, e mũtumĩu mũno, na wa myaka mingĩ, na oombanw’a vamwe na andũ make.'),
('kam', 'GEN', 25, 9, 'Na Isaka na Isumaeli, ana make, mamũthika ngungani yĩ Makivela, kĩsesinĩ kya Eveloni mwana wa Nzooali, Mũititi, kĩla kĩ mbee wa Mamile;'),
('kam', 'GEN', 25, 10, 'kĩsesi kĩla Avalaamu wathooee ana ma Ethi: nĩvo Avalaamu wathikiwe, na Sala mũka wake.'),
('kam', 'GEN', 25, 11, 'Na kweethĩwa, ĩtina wa kĩkw’ũ kya Avalaamu, Ngai aathima Isaka mwana wake: na Isaka atũaa ku Mbeeli‐laai‐loi.'),
('kam', 'GEN', 25, 12, 'Na yu ĩndĩ aa nĩmo mosyaanĩo ma Isumaeli, mwana wa Avalaamu, ũla Akali, Mũmisili, mũthũkũmi wa Sala mwĩĩtu, wamũsyaĩe Avalaamu:'),
('kam', 'GEN', 25, 13, 'na aa nĩmo masyĩtwa ma ana ma Isumaeli, masyĩtwa moo, kũatĩĩa mosyaanĩo moo: ĩkithathi ya Isumaeli, Nevaiothi; na Ketali, na Ativeeli, na Mivisamu,'),
('kam', 'GEN', 25, 14, 'na Misima, na Nduma, na Masa,'),
('kam', 'GEN', 25, 15, 'na Aatati, na Tema, na Yetuli, na Navisi, na Ketema:'),
('kam', 'GEN', 25, 16, 'asu nĩo ana ma Isumaeli, na asu nĩo masyĩtwa moo, kũatĩĩa mĩsyĩ yoo, na motũo moo; anene ĩkũmi na elĩ kũatĩĩa mbaĩ syoo.'),
('kam', 'GEN', 25, 17, 'Na ĩno nĩyo myaka ya thayũ wa Isumaeli, myaka ĩana na mĩongo ĩtatũ na mũonza: nake aumwa nĩ veva na akw’a, an oombanw’a vamwe na andũ make.'),
('kam', 'GEN', 25, 18, 'Na matũaa kuma Avila kũvika Suli ũla welekele Misili, ũendete Asuli: atũaa elekanĩle na ana‐a‐inyia make onthe.'),
('kam', 'GEN', 25, 19, 'Na aa nĩmo mosyaanĩo ma Isaka, mwana wa Avalaamu: Avalaamu asyaa Isaka:'),
('kam', 'GEN', 25, 20, 'na Isaka aĩ wa myaka mĩongo ĩna yila wamũtwaie Leveka, mwĩĩtu wa Mbethueli, Mũsilia wa Vatani‐alamu, mwĩĩtu‐a‐inyia wa Lavani, Mũsilia, ethĩwe mũka wake.'),
('kam', 'GEN', 25, 21, 'Na Isaka eesũva Yeova kwondũ wa mũka wake, nũndũ aĩ ngũngũ: na Yeova eesũvĩka, na Leveka mũka wake aya ĩvu.'),
('kam', 'GEN', 25, 22, 'Na syana syakĩlan’ya vinya nthĩnĩ wake; na asya, Ethĩwa nũu, nĩkĩ ngwĩkala thayũ? Na aenda akũlya Yeova.'),
('kam', 'GEN', 25, 23, 'Na Yeova amwĩa, Mbaĩ ilĩ syĩ ĩvunĩ yaku, Na ngo ilĩ sya andũ ikauma ĩvunĩ yaku ivathũkanĩte: Na ũko ũmwe ũkeethĩwa na vinya kũte ũko ũla ũngĩ; Na ũla mũkũũ akathũkũma ũla mũnini.'),
('kam', 'GEN', 25, 24, 'Na yĩla matukũ make ma kũsyaa meanĩie, sisya, vaĩ mavatha ĩvunĩ yake.'),
('kam', 'GEN', 25, 25, 'Na ũla wa mbee auma e mũtune, ta ngũa ya w’ĩa, kw’onthe; na mamwĩta syĩtwa yake Esau.'),
('kam', 'GEN', 25, 26, 'Na ĩtina wa ũu mwana‐a‐inyia auma, na kw’oko kwake kwakwete Esau kĩtiinyo; na syĩtwa yake eetwa Yakovo: na Isaka aĩ wa myaka mĩongo thanthatũ yĩla Leveka wamasyaie.'),
('kam', 'GEN', 25, 27, 'Na ivĩsĩ syeana: na Esau aĩ mũsyĩmi mwai, mũndũ wa kĩsesi; na Yakovo ai mũndũ mũuu, ekalaa maeemanĩ.'),
('kam', 'GEN', 25, 28, 'Na ĩndĩ Isaka amwendaa Esau, nũndũ aĩsaa nyama sya nzyĩma yake: na Leveka amwendaa Yakovo.'),
('kam', 'GEN', 25, 29, 'Na Yakovo aua ũsũũ: na Esau auma kĩthekanĩ, na aĩ mũnyalu:'),
('kam', 'GEN', 25, 30, 'na Esau amwĩa Yakovo, Ngathĩsya, nĩngũkwĩsũva, ũsũũ ũsu mũtune; nũndũ nĩ mũnyalu: kwondũ wa ũu syĩtwa yake eetwa Etomu.'),
('kam', 'GEN', 25, 31, 'Na Yakovo amwĩa, Amba ũnthooesya ũkithathi waku.'),
('kam', 'GEN', 25, 32, 'Na Esau asũngĩa, Sisya, ngilĩlye ũkw’a: na ũkithathi ũkanguna na kyaũ?'),
('kam', 'GEN', 25, 33, 'Na Yakovo amwĩa, Amba kwĩmbĩtĩa; nake amwĩvĩtĩa: na athooesya Yakovo ũkithathi wake.'),
('kam', 'GEN', 25, 34, 'Na Yakovo amũnenga Esau kĩmũtũ na ũsũũ wa ndengũ; nake aya na anyw’a, na ookĩla, na akwata nzĩa yake, na athi: ũu nĩw’o Esau wavũthisye ũkithathi wake.'),
('kam', 'GEN', 26, 1, 'Na kwaĩ yũa nthĩ, eka yũa ya mbee yĩla yaĩ matukũ ma Avalaamu. Na Isaka aenda kwa Avimeleki mũsumbĩ wa Avilisiti, kũvika Ngelali.'),
('kam', 'GEN', 26, 2, 'Na Yeova amumĩlĩla, na amwĩa, Ndũkatheee Misili; tũa nthĩ ĩla ngũũtavya:'),
('kam', 'GEN', 26, 3, 'ĩkalaa ũeni nthĩ ĩno, nakwa ngeethĩwa vamwe naku, na ngakũathima; nũndũ nthĩ ii syonthe ngakũnenga, we na ũsyao waku, na ngalũlũmĩlya wĩvĩto ũla neevĩtĩe Avalaamu ĩthe waku;'),
('kam', 'GEN', 26, 4, 'na ngaingĩvya ũsyao waku ta ndata sya ĩtunĩ, na nganenga ũsyao waku nthĩ ii syonthe; na ũsyaonĩ waku mbaĩ syonthe sya nthĩ ikaathimwa;'),
('kam', 'GEN', 26, 5, 'nĩkwĩthĩwa Avalaamu nĩwew’aa wasya wakwa, na asũvĩaa wĩaĩo wakwa, na myamũlo yakwa, na motw’ĩo makwa, na mĩao yakwa.'),
('kam', 'GEN', 26, 6, 'Na Isaka atũaa Ngelali:'),
('kam', 'GEN', 26, 7, 'na andũ ma vandũ vau mamũkũlya ũndũ wa mũka wake; nake amea, Nĩ mwĩĩtu‐a‐ia: nũndũ akĩaa kwasya, Nĩ mũka wakwa; akĩsũanĩa, andũ ma vandũ vau maikese ũmbũaa nũndũ wa Leveka; nũndũ aĩ mwanake kwa kũsiw’a.'),
('kam', 'GEN', 26, 8, 'Na kweethĩwa, ekalĩte vo ĩvinda ĩasa, Avimeleki mũsumbĩ wa Avilisiti asyaĩlya mbũthinĩ, na oona, na, sisya, Isaka nĩwathaũkaa na Leveka mũka wake.'),
('kam', 'GEN', 26, 9, 'Na Avimeleki amwĩta Isaka, amwĩa, Sisya, nĩ w’o ũsu nĩ mũka waku: nũndũ wa kĩ waisye, Nĩ mwĩĩtu‐a‐ia? Na Isaka amwĩa, Nũndũ nĩnaisye, Ndikese ũkw’a nũndũ wake.'),
('kam', 'GEN', 26, 10, 'Na Avimeleki akũlya, Nata ũndũ ũsu ũtwĩkĩte? Ũmwe wa kwitũ anaĩ atonya kũkoma na mũka waku, naku wĩthĩwa watũetee ũthũku kwitũ.'),
('kam', 'GEN', 26, 11, 'Na Avimeleki ameaĩa andũ onthe, akĩmea, Ũla ũkakiita mũndũ ũũ kana mũka wake ndakatĩa kũawa.'),
('kam', 'GEN', 26, 12, 'Na Isaka avanda nthĩ ĩsu, na oona mwaka ũsu kũndũ ĩana: na Yeova amũathima.'),
('kam', 'GEN', 26, 13, 'Na mũndũ ũsu aingĩvĩwa mũno, na aendeea kwingĩvĩwa mũvaka atw’ĩka mũnene mũno:'),
('kam', 'GEN', 26, 14, 'na aĩ na ũthwii wa ndĩthya sya mbũi na malondu, na ũthwii wa ndĩthya sya ng’ombe, na andũ aingĩ ma nyũmba: na Avilisiti mamwĩw’ĩa kĩwĩu.'),
('kam', 'GEN', 26, 15, 'Na ĩndĩ ithima syonthe ila athũkũmi ma ĩthe wake menzie matukũ ma ĩthe wake Avalaamu, Avilisiti nĩmailindĩte, na kũsyusũsya mũthanga.'),
('kam', 'GEN', 26, 16, 'Na Avimeleki amwĩa Isaka, Uma kwitũ; nũndũ wĩ vinya mũno kwĩ ithyĩ.'),
('kam', 'GEN', 26, 17, 'Na Isaka auma kũu, na aaka maeema mwandanĩ wa Ngelali, na atũa kw’o.'),
('kam', 'GEN', 26, 18, 'Na Isaka avukũa ĩngĩ ithima sya manzĩ, ila menzĩte matukũ ma Avalaamu ĩthe wake; nũndũ Avilisiti nĩmailindile Avalaamu akw’a: na asyĩta masyĩtwa masyo kũatĩĩa masyĩtwa ala syeetawa nĩ ĩthe.'),
('kam', 'GEN', 26, 19, 'Na athũkũmi ma Isaka menza mwandanĩ, na vo moona kĩthima kya manzĩ meũvulutya.'),
('kam', 'GEN', 26, 20, 'Na aĩthi ma Ngelali matetan’ya na aĩthi ma Isaka, makĩmea, Manzĩ nĩ maitũ: na akĩta kĩthima syĩtwa yakyo Esekĩ, nĩkwĩthĩwa nĩmatetanisye nake.'),
('kam', 'GEN', 26, 21, 'Na menza kĩthima kĩngĩ, nakyo makĩtetanĩsya: na akĩta syĩtwa yakyo Sitina.'),
('kam', 'GEN', 26, 22, 'Na auma ku, enza kĩthima kĩngĩ; na kyu maiaakĩtetanĩsya: na akĩta syĩtwa yakyo Leovothi; na asya, Nũndũ yu Yeova nũtwonee ũthei, naitũ tũkongeleka ĩ nthĩ.'),
('kam', 'GEN', 26, 23, 'Na ambata kuma vau kũvika Mbeeli‐sieva.'),
('kam', 'GEN', 26, 24, 'Na Yeova amumĩlĩla o ũtukũ ũsu, na amwĩa, Ninyie Ngai wa Avalaamu ĩthe waku: ndũkakĩe, nũndũ nĩ vamwe naku, nakwa ngakũathima, na kwingĩvya ũsyao waku kwondũ wa muthũkũmi wakwa Avalaamu.'),
('kam', 'GEN', 26, 25, 'Na aaka kĩthembeo vau, na eekaĩla syĩtwa ya Yeova, na amba ĩeema yake vo: na athũkũmi ma Isaka menza kĩthima vo.'),
('kam', 'GEN', 26, 26, 'Na ĩndĩ Avimeleki aenda vala ũĩ kuma Ngelali, e na Ausathi mũnyanyae, na Vikoli kavuteni wa nguthu yake.'),
('kam', 'GEN', 26, 27, 'Na Isaka amakũlya, Mwambũkĩa nyie nĩkĩ, nũndũ nĩmũũmena, na nĩmwanumisye kwenyu?'),
('kam', 'GEN', 26, 28, 'Nao masũngĩa, Nĩtwoonie ki kana Yeova aĩ vamwe naku: na twasya, Vethĩwe wĩvĩto katĩ waitũ, o katĩ waitũ naku, na tũtianĩe ũtianĩo naku,'),
('kam', 'GEN', 26, 29, 'kana ndũkatwĩka ũthũku, tondũ ithyĩ tũtaakũkiita, na tondũ ithyĩ tũtaakwĩka ũndũ ate o ũseo, na twakumya kwitũ na mũuo: naku yu wĩ mũathimwa wa Yeova.'),
('kam', 'GEN', 26, 30, 'Na amavokea mboka, na maya na manyw’a.'),
('kam', 'GEN', 26, 31, 'Na mookĩla kĩoko tene, meeavanĩa kĩla mũndũ na ũla ũngĩ: na Isaka amaeka mathi, na mauma kwake na mũuo.'),
('kam', 'GEN', 26, 32, 'Na kweethĩwa mũthenya o ũsu athũkũmi ma Isaka mooka, na mamũtavya ũvoo wa kĩthima kĩla menzie, mamwĩa, Nĩtwonie manzĩ.'),
('kam', 'GEN', 26, 33, 'Na akĩta Siva: kwondũ wa ũu syĩtwa ya ndũa ĩsu nĩ Mbeeli‐sieva kũvika mũnthĩ ũũ.'),
('kam', 'GEN', 26, 34, 'Na yĩla Esau waĩ wa myaka mĩongo ĩna atwaa Yutithi mwĩĩtu wa Veeli, Mũititi, na Mbasemathi mwĩĩtu wa Eloni, Mũititi:'),
('kam', 'GEN', 26, 35, 'na asu maĩ woo vevanĩ kwa Isaka na kwa Leveka.'),
('kam', 'GEN', 27, 1, 'Na kweethĩwa, yĩla Isaka waĩ mũkũu, na metho make me mbindu, atona, amwĩta Esau mwana wake mũkũũ, na amwĩa, Mwana wakwa: na asũngĩa, Nĩ vaa.'),
('kam', 'GEN', 27, 2, 'Na amwĩa, sisya yu, nĩ mũkũu, o na ndyĩsĩ mũthenya wa kũkw’a kwakwa.'),
('kam', 'GEN', 27, 3, 'Na yu ĩndĩ, nĩngũkwĩsũva, osa mĩio yaku, thyaka waku na ũta waku, ũende weũnĩ ũnzyĩmĩe;'),
('kam', 'GEN', 27, 4, 'naku ũnzeũvĩsye lĩu mũseo, tondũ nendete ũndetee, nĩye; nĩ kana ngoo yakwa ĩkũathime ndanakw’a.'),
('kam', 'GEN', 27, 5, 'Na Leveka eew’a Isaka akĩneena na Esau mwana wake. Na Esau athi weũnĩ kũsyĩma nyama sya nzyĩma, na kwiete.'),
('kam', 'GEN', 27, 6, 'Na Leveka aneena na Yakovo mwana wake, akĩmwĩa, Sisya, nĩneew’a au aineena na Esau mwana‐a‐mwenyu, akĩmwĩa,'),
('kam', 'GEN', 27, 7, 'Ndetee nyama sya nzyĩma, ũnzeũvĩsye lĩu mũseo, nĩye, na ngĩkũathimĩa mbee wa Yeova, ndanakw’a.'),
('kam', 'GEN', 27, 8, 'Yu ĩndĩ, mwana wakwa, ĩw’a wasya wakwa o ũndũ ngũkwĩaĩa.'),
('kam', 'GEN', 27, 9, 'Enda yu ndĩthyanĩ ya mbũi na malondu, na ndatĩlya vo tũtena twĩlĩ tũseo twa mbũi: nakwa nĩngũtũseũvya lĩu mũseo nũndũ wa au, o tondũ wendete:'),
('kam', 'GEN', 27, 10, 'naku ũkamũtwaĩa au, aye, nĩ kana akũathime atanakw’a.'),
('kam', 'GEN', 27, 11, 'Na Yakovo amwĩa Leveka inyia wake, Sisya, Esau mwana‐a‐ia nĩ mũndũ wĩ na maw’ĩa, nakwa nĩ mũndũ mũtendeu.'),
('kam', 'GEN', 27, 12, 'Nokwĩthĩwa nau ambavata, na ngeethĩwa kwake ta mũkengani; na ĩndĩ ngĩyĩetee kĩumo, na ti ũathimo.'),
('kam', 'GEN', 27, 13, 'Na inyia wake amwĩa, Kĩumo kyaku nĩkĩthĩwe ĩũlũ wakwa, mwana wakwa; ĩndĩ ĩw’a wasya wakwa, na enda ũndatĩlye tw’o.'),
('kam', 'GEN', 27, 14, 'Na athi, na alatya, na atũetee inyia wake: na inyia wake aseũvya lĩu mũseo, o tondũ ĩthe wake wendete.'),
('kam', 'GEN', 27, 15, 'Na Leveka oosa ngũa nzeo sya Esau mwana wake mũkũũ, ila syaĩ kwake nyũmbanĩ, na eekĩa Yakovo mwana wake mũnini:'),
('kam', 'GEN', 27, 16, 'na mbũa sya tũtena twa mbũi asyĩkĩa mokonĩ make, na ũtendeunĩ wa ngingo yake:'),
('kam', 'GEN', 27, 17, 'na amũnenga mwana wake Yakovo kw’okonĩ kwake lĩu mũseo na kĩmũtũ kĩla ũseũvisye.'),
('kam', 'GEN', 27, 18, 'Na ooka kwa ĩthe, na amwĩa, Nau; nake asũngĩa, Nĩ vaa; nue ũũ, mwana wakwa?'),
('kam', 'GEN', 27, 19, 'Na Yakovo amwĩa ĩthe, Ninyie Esau ĩkithathi yaku; nĩneeka o tondũ ũmbĩie; nĩngũkwĩsũva ũkĩla, wĩkale nthĩ ũye nyama syakwa sya nzyĩma, nĩ kana ngoo yaku ĩngathime.'),
('kam', 'GEN', 27, 20, 'Na Isaka amũkũlya mwana wake, Wasyona na mĩtũkĩ ĩana ũu ata, mwana wakwa? Na asũngĩa, Nĩkwĩthĩwa Yeova Ngai waku nĩwambaĩlĩlya.'),
('kam', 'GEN', 27, 21, 'Na Isaka amwĩa Yakovo, Nĩngũkwĩsũva, mwana wakwa, thengeea, nĩkũvavate, kana nue mwana wakwa Esau, kana tiwe.'),
('kam', 'GEN', 27, 22, 'Na Yakovo amũthengeea Isaka ĩthe wake; nake amũvavata, na asya, Wasya nĩ wasya wa Yakovo, ĩndĩ moko nĩ moko ma Esau.'),
('kam', 'GEN', 27, 23, 'Na ndaamũmanya, nĩkwĩthĩwa moko make maĩ na maw’ĩa, ta moko ma Esau mwana‐a‐inyia: na ĩndĩ amũathima.'),
('kam', 'GEN', 27, 24, 'Na akũlya, Nue ki mwana wakwa Esau? Nake asũngĩa, Ninyie.'),
('kam', 'GEN', 27, 25, 'Na amwĩa, Ndetee vakuvĩ, nakwa nĩngũya nyama sya nzyĩma sya mwana wakwa, nĩ kana ngoo yakwa ĩkũathime. Na amũetee vakuvĩ, nake aya: na amũetee mbinyu na anyw’a.'),
('kam', 'GEN', 27, 26, 'Na Isaka ĩthe wake amwĩa, Mwana wakwa, thengeea yu, ũmumunye.'),
('kam', 'GEN', 27, 27, 'Nake athengeea, amũmumunya: na anyungĩa mũuke wa ngũa syake, na amũathima, na asya, Sisya, mũuke wa mwana wakwa Nĩ ta mũuke wa kĩsesi kĩathimĩtwe nĩ Yeova:'),
('kam', 'GEN', 27, 28, 'Na Ngai akũnenge sya ĩmwe ya ĩtunĩ, Na sya ũnou wa nthĩ, Na wingĩ wa lĩu wa mbaa ngetha na mbinyu mbĩthĩ:'),
('kam', 'GEN', 27, 29, 'Ngo sya andũ ikũthũkũme, Na mbaĩ ikũkunamĩe: Ĩthĩwa mwĩaĩi ĩũlũ wa ana‐a‐au, Na ana‐a‐mwenyu nĩmakũkunamĩae: Naumanĩwe o ũla ũkũumanĩaa, Na naathimwe o ũla ũkũathimaa.'),
('kam', 'GEN', 27, 30, 'Na kweethĩwa, kavinda kala Isaka waminie kũmũathima Yakovo, na Yakovo eethĩwa akyuma mbee wa Isaka ĩthe wake, Esau mwana‐a‐inyia ooka aumĩte nzyĩmanĩ yake.'),
('kam', 'GEN', 27, 31, 'Nake aseũvya lĩu mũseo, amũtwaĩa ĩthe; na amwĩa ĩthe, Nau okĩle, aye nyama sya nzyĩma sya mwana wake, nĩ kana ngoo yaku ĩngathime.'),
('kam', 'GEN', 27, 32, 'Na Isaka ĩthe wake amũkũiya, Nue ũũ? Nake asũngĩa, Ninyie mwana waku, ĩkithathi yaku, Esau.'),
('kam', 'GEN', 27, 33, 'Na Isaka atetema mũno mũnene, na akũlya, Nũũ ĩndĩ ũsu wosie nyama sya nzyĩma, na andetee, nakwa nĩnaya syonthe mbee wa ũtanoka, na namũathima? Ĩĩ, nake akaathimwa.'),
('kam', 'GEN', 27, 34, 'Esau eew’a ndeto sya ĩthe, aĩa kĩĩo kĩnene mũno kĩ woo, na amwĩa ĩthe, Ngathima, nyie nakwa, ame nau.'),
('kam', 'GEN', 27, 35, 'Na amwĩa, Mwana‐a‐mwenyu nĩwũkie na ũĩ wa ũkengani, na akũvena ũathimo waku.'),
('kam', 'GEN', 27, 36, 'Nake asya, Ndetawa w’o syĩtwa yake Yakovo? Nũndũ nũngũanĩsye mavinda asu elĩ: nĩwosie ũkithathi wakwa; na, sisya, yu nĩwambena kũathimwa kwakwa. Na akũlya, Ndũnandialĩlya nyie ũathimo?'),
('kam', 'GEN', 27, 37, 'Na Isaka asũngĩa na amwĩa Esau, Sisya, namũtw’a mwĩaĩi waku, na ana‐a‐ĩthe onthe nĩnamũnenga methĩwe athũkũmi; na namwĩkalya na lĩu wa mbaa ngetha na mbinyu mbĩthĩ: naku yu, mwana wakwa, nĩkwĩke ata?'),
('kam', 'GEN', 27, 38, 'Na Esau akũlya ĩthe, Wĩ na ũathimo o ũmwe tũ, we nau? Ngathima nyie, o nakwa, ame nau. Na Esau ookĩlya wasya, aĩa.'),
('kam', 'GEN', 27, 39, 'Na Isaka ĩthe wake asũngĩa amwĩa, Sisya, kũla kũnou kwa nthĩ kũkeethĩwa wĩkalo waku, Na sya ĩmwe ya ĩtunĩ kuma ĩũlũ;'),
('kam', 'GEN', 27, 40, 'Na kwondũ wa ũvyũ waku ũkeethĩwa thayũ, naku ũkamũthũkũma mwana‐a‐mwenyu; Na kũkeethĩwa, yĩla ũkavonoka, Ũkathingithya ĩsoki yake yume ngingonĩ yaku.'),
('kam', 'GEN', 27, 41, 'Na ĩndĩ Esau amũmena Yakovo kwondũ wa ũathimo ũla ĩthe wamũathimie: na Esau asya ngoonĩ yake, Mĩthenya ya kũmũĩĩa nau yĩ vakuvĩ; nĩvo ngoaa mwana‐a‐ia Yakovo.'),
('kam', 'GEN', 27, 42, 'Na Leveka atavw’a ndeto sya Esau mwana wake mũkũũ; nake atũmana amwĩta Yakovo mwana wake mũnini, na amwĩa, Sisya, Esau, mwana‐a‐mwenyu, nũkwĩkiakisya ũndũ waku, akĩtw’ĩĩa kũkũaa.'),
('kam', 'GEN', 27, 43, 'Na yu ĩndĩ, mwana wakwa, Ĩw’a wasya wakwa; ũkĩla, ũkĩĩe Aalani kwa mwana‐a‐ia Lavani;'),
('kam', 'GEN', 27, 44, 'ũkekale kwake matukũ mavũthũ, mũvaka ũthatu mwai wa mwana‐a‐mwenyu ũlike;'),
('kam', 'GEN', 27, 45, 'mũvaka ũthatu wa mwana‐a‐mwenyu wume kwaku, nake oolwa nĩ ũla wamwĩkie: nĩvo ngatũmana, nĩkũete kuma kũu; nũndũ wa kĩ nĩkwĩĩw’e nĩ inyw’ĩ elĩ mũthenya ũmwe?'),
('kam', 'GEN', 27, 46, 'Na Leveka amwĩa Isaka, Nĩngũnow’a thayũ wakwa nũndũ wa eĩtu ma Ethi: ethĩwa Yakovo akatwaa mũka wa eĩtu ma Ethi, ta asu, ma eĩtu ma nthĩ ĩno, thayũ wakwa ũkambaĩla kyaũ?'),
('kam', 'GEN', 28, 1, 'Na Isaka amwĩta Yakovo, na amũathima, na amwĩaĩa, na amwĩa, Ndũkaatwae mũka wa eĩtu ma Kanaani.'),
('kam', 'GEN', 28, 2, 'Ũkĩla, ũende Vatani‐alamu, nyũmbanĩ ya Mbethueli ĩthe wa mwenyu; na ũketwaĩe mũka kuma kũu eĩtunĩ ma Lavani mwana‐a‐inyia wa mwenyu.'),
('kam', 'GEN', 28, 3, 'Na Ngai Mwene Vinya W’onthe akũathime, na akwongeleele, na akwingĩvye, wĩthĩwe wĩ nguthu sya ngo sya andũ;'),
('kam', 'GEN', 28, 4, 'na akũnenge ũathimo wa Avalaamu, we, na ũsyao waku vamwe naku; nĩ kana ũtiĩwe nthĩ ya kwĩkala ũeni kwaku, ĩla Ngai wamũnengie Avalaamu.'),
('kam', 'GEN', 28, 5, 'Na Isaka amwĩa Yakovo athi: nake aenda Vatani‐alamu kwa Lavani, mwana wa Mbethueli, Mũsilia, mwana‐a‐ĩthe wa Leveka, inyia wa Yakovo na Esau.'),
('kam', 'GEN', 28, 6, 'Na ĩndĩ Esau oona kana Isaka nĩwamũathima Yakovo na amũtũma Vatani‐alamu, akatwae mũka kuma kũu; nake akĩmũathima, amwĩaĩa, akĩmwĩa, Ndũkaatwae mũka wa eĩtu ma Kanaani;'),
('kam', 'GEN', 28, 7, 'na kana Yakovo nĩwew’a ĩthe na nyinyia, nake athi Vatani‐alamu:'),
('kam', 'GEN', 28, 8, 'na Esau oona kana Isaka ĩthe wake ndaaendeew’a nĩ eĩtu ma Kanaani;'),
('kam', 'GEN', 28, 9, 'na ĩndĩ Esau athi kwa Isumaeli, atwaa Maalathi mwĩĩtu wa Isumaeli mwana wa Avalaamu, mwĩĩtu‐a‐inyia wa Nevaiothi, ethĩwe mũka wake vamwe na aka ala waĩ nao.'),
('kam', 'GEN', 28, 10, 'Na Yakovo auma Mbeeli‐sieva, na athi elekele Aalani.'),
('kam', 'GEN', 28, 11, 'Na avika vandũ vamwe, na ekala vo ũtukũ mũima, nũndũ syũa yaĩ yĩnathũa; na oosa ĩvia yĩmwe ya vandũ vau, aia ungu wa mũtwe, na akoma o vo.'),
('kam', 'GEN', 28, 12, 'Na aota; na, sisya, mbasya ĩũngamĩtw’e ĩũlũ wa nthĩ, na mũthya wayo wavikĩte ĩtunĩ; na, sisya, alaĩka ma Ngai makyambata na makĩtheea nayo.'),
('kam', 'GEN', 28, 13, 'Na, sisya, Yeova aũngamĩte ĩũlangũ wayo, na amwĩa, Ninyie Yeova, Ngai wa Avalaamu ĩthe waku, na Ngai wa Isaka: nthĩ ĩla ũkomete, ngakũnenga we, na ũsyao waku;'),
('kam', 'GEN', 28, 14, 'na ũsyao waku ũkeethĩwa ta kĩtoo kya nthĩ, naku ũkanyaĩĩka ngalĩ ya ũthũĩlonĩ wa syũa, na wumĩlonĩ wa syũa, na ngalĩ ya ĩũlũ, na ngalĩ ya ĩtheo: na nthĩnĩ wakũ, we, na ũsyaonĩ waku mĩvĩa yonthe ya nthĩ ĩkaathimwa.'),
('kam', 'GEN', 28, 15, 'Na, sisya, nyie nĩ vamwe naku, na ngakũsũvĩa o kũla wĩendaa, na ngakũtũnga ĩngĩ nthĩ ĩno; nũndũ ndikakũtia, mũvaka neeka ũla nakũtavisye.'),
('kam', 'GEN', 28, 16, 'Na Yakovo aamũka kuma toonĩ, na asya, Nĩ w’o, Yeova nĩ voĩ vaa; nakwa ndyĩĩsĩ.'),
('kam', 'GEN', 28, 17, 'Na akĩa, na asya, Vandũ va ũtĩsya nĩ vaa! Ti vangĩ vaa ate o nyũmba ya Ngai, na ĩno nĩ mbingĩlo ya ĩtunĩ.'),
('kam', 'GEN', 28, 18, 'Na Yakovo ookĩla kĩoko tene, na oosa ĩvia yĩla waiĩte ungu wa mũtwe wake, ayĩũngamya ta kĩtuĩ, na etĩkĩsya mauta mũthyanĩ ĩũlũ.'),
('kam', 'GEN', 28, 19, 'Na eeta syĩtwa ya vandũ vau, Mbethi‐eli: ĩndĩ mbee syĩtwa ya ndũa ĩsu yeetawa Lusu.'),
('kam', 'GEN', 28, 20, 'Na Yakovo eevĩta, akyasya, Ethĩwa Ngai akeethĩwa vamwe nakwa, na akĩnzũvĩa nzĩanĩ ĩno ĩla nĩendele, na kũnenga lĩu nĩye, na ngũa sya kwĩkĩa,'),
('kam', 'GEN', 28, 21, 'nĩ kana nĩsyoke ĩngĩ na mũuo nyũmbanĩ ya nau, nĩvo ĩndĩ Yeova ũkethĩwa Ngai wakwa,'),
('kam', 'GEN', 28, 22, 'nayo ĩvia yĩĩ yĩla naũngamya ta kĩtuĩ, yĩkeethĩwa nyũmba ya Ngai: na ndikatĩa ũkũnengae, we, kĩlungu kya ĩkũmi kya kyonthe kĩla ũkanenga.'),
('kam', 'GEN', 29, 1, 'Nĩvo Yakovo wakwatie nzĩa, na avika nthĩ ya ana ma wumĩlonĩ wa syũa.'),
('kam', 'GEN', 29, 2, 'Nake oona, na, sisya, kĩthĩma kĩsesinĩ, na, sisya, ndĩthya itatũ sya malondu itindiĩte ũtee wakyo; nũndũ kĩthimanĩ kyu nĩmanyithasya ndĩthya: na ĩvia yĩla yaĩ mũomonĩ wa kĩthima yaĩ ĩnene.'),
('kam', 'GEN', 29, 3, 'Na ndĩthya syonthe syoombanĩaw’a vo: na mavingilitasya ĩvia kuma mũomonĩ wa kĩthima, na mainyithya malondu, na maitũnga ĩvia mũomonĩ wa kĩthima vandũ vayo.'),
('kam', 'GEN', 29, 4, 'Na Yakovo amakũlya, Ana‐a‐asa, inyw’ĩ mwĩ ma va? Nao masũngĩa, Twĩ ma Aalani ithyĩ.'),
('kam', 'GEN', 29, 5, 'Na akũlya, Nĩmũmwĩsĩ Lavani mwana wa Naoli? Nao masũngĩa, Nĩtũmwĩsĩ.'),
('kam', 'GEN', 29, 6, 'Na amakũlya, Nĩ kũseo kwake? Nao masũngĩa, Nĩ kũseo: na, sisya, Lakeli mwĩĩtu wake wũkĩte na malondu.'),
('kam', 'GEN', 29, 7, 'Nake amea, Sisya, no kũkye, na ti ĩvinda ya kũmban’ya indo: nyithyai malondu, na ĩndĩ endai mũkaĩthye.'),
('kam', 'GEN', 29, 8, 'Na masũngĩa, Tũitonya, mũvaka ndĩthya syonthe syũmbanw’e, na maivingilitya ĩvia yume mũomonĩ wa kĩthima; nĩvo ĩndĩ tũnyithasya malondu.'),
('kam', 'GEN', 29, 9, 'Akĩneena nao, Lakeli ooka na malondu ma ĩthe; nũndũ nĩwe waĩthasya.'),
('kam', 'GEN', 29, 10, 'Na kweethĩwa Yakovo oona Lakeli mwĩĩtu wa Lavani mwana‐a‐ĩthe wa inyia wake, na malondu ma Lavani mwana‐a‐inyia wa inyia wake, Yakovo athengeea, na avingilitya ivia yume mũomonĩ wa kĩthima, na anyithya malondu ma Lavani mwana‐a‐inyia wa inyia wake.'),
('kam', 'GEN', 29, 11, 'Na Yakovo amũmumunya Lakeli, na ookĩlya wasya, na aĩa.'),
('kam', 'GEN', 29, 12, 'Na Yakovo atavya Lakeli kana we nĩ mwana‐a‐ĩthe wa ĩthe, na nĩ mwana wa Leveka: nake asemba na atavya ĩthe.'),
('kam', 'GEN', 29, 13, 'Na kweethĩwa, Lavani eew’a ũvoo wa Yakovo mwana wa mwĩĩtu‐a‐inyia aemba amũthaũe, na amwĩvĩtĩĩsya, na amũmumunya, na amũete kwake nyũmbanĩ. Nake amũtavya Lavani maũndũ asu onthe.'),
('kam', 'GEN', 29, 14, 'Na Lavani amwĩa, Nĩ w’o wĩ ĩvĩndĩ yakwa na mwĩĩ wakwa. Na ekala kwake ĩvinda ya mwei.'),
('kam', 'GEN', 29, 15, 'Na Lavani amwĩa Yakovo, Nĩkwĩthĩwa wĩ mwana‐a‐asa, we, kwondũ wa ũu ũnthũkũme mana? Ndavya, ĩtuvi yaku yĩkeethĩwa kyaũ?'),
('kam', 'GEN', 29, 16, 'Na ĩndĩ Lavani aĩ na eĩtu elĩ: ũla mũkũũ syĩtwa yake eetawa Lea, na ũla mũnini syĩtwa yake eetawa Lakeli.'),
('kam', 'GEN', 29, 17, 'Na Lea, metho make matyaĩ na vinya, ĩndĩ Lakeli aĩ mwanake na aĩ na wũmbe mũseo.'),
('kam', 'GEN', 29, 18, 'Na Yakovo amwendete Lakeli; nake asya, Ngakũthũkũma myaka mũonza kwondũ wa Lakeli mwĩĩtu waku ũla mũnini.'),
('kam', 'GEN', 29, 19, 'Na Lavani amwĩa, Kavaa nĩkũnenge we, kwĩ kũmũnenga mũndũ ũngĩ: ĩkalaa kwakwa.'),
('kam', 'GEN', 29, 20, 'Na Yakovo athũkũma myaka mũonza kwondũ wa Lakeli; na kwake yeethĩwa o ta matukũ mavũthũ, nũndũ wa wendo ũla wamwendaa.'),
('kam', 'GEN', 29, 21, 'Na Yakovo amwĩa Lavani, Nenga mũka wakwa, nĩlike kwake nũndũ matukũ makwa nĩ meanĩu.'),
('kam', 'GEN', 29, 22, 'Na Lavani oomban’ya andũ onthe ma vandũ vau, avoka mboka.'),
('kam', 'GEN', 29, 23, 'Na kweethĩwa wĩoo, oosa Lea mwĩĩtu wake, amũtwaĩa; nake alika kwake.'),
('kam', 'GEN', 29, 24, 'Na Lavani amũnenga Lea Nziliva mũthũkũmi wake mwĩĩtu, ethĩwe mũthũkũmi wake.'),
('kam', 'GEN', 29, 25, 'Na kweethĩwa kĩoko, sisya, nĩ Lea: nake amwĩa Lavani, Ũndũ ũũ ũmbĩkie nata? Ndiũthũkũmĩte kwondũ wa Lakeli? Nĩkĩ ĩndĩ wangenga?'),
('kam', 'GEN', 29, 26, 'Na Lavani asũngĩa, Ũũ ndwĩkawa kwitũ, kũnengane ũla mũnini kwĩ ũla wambie kũsyawa.'),
('kam', 'GEN', 29, 27, 'Ĩanĩĩsya kyumwa kya ũsu, na tũkaũnenga ũla ũngĩ nake kwondũ wa ũthũkũmi ũla ũkanthũkũma myaka ĩngĩ mũonza.'),
('kam', 'GEN', 29, 28, 'Na Yakovo eeka ũu, eanĩĩsya kyumwa kyake: na amũnenga Lakeli mwĩĩtu wake ethĩwe mũka.'),
('kam', 'GEN', 29, 29, 'Na Lavani amũnenga Lakeli mwĩĩtu weke, Mbila mũthũkũmi wake mwĩĩtu, ethĩwe mũthũkũmi wake.'),
('kam', 'GEN', 29, 30, 'Na alika kwa Lakeli nake, na ĩndĩ amwendaa Lakeli kwĩ Lea, na athũkũma kwake myaka ĩngĩ mũonza.'),
('kam', 'GEN', 29, 31, 'Na Yeova oona kana Lea nĩ mũmene, na amũnenga kũsyaa: ĩndĩ Lakeli aĩ ngũngũ.'),
('kam', 'GEN', 29, 32, 'Na Lea aya ĩvu, na asyaa mwana, na amwĩta syĩtwa yake Leuveni: nũndũ asya, Nĩkwĩthĩwa Yeova nĩwona thĩna wakwa; nũndũ yu mũemewa akambenda.'),
('kam', 'GEN', 29, 33, 'Na aya ĩvu ĩngĩ, na asyaa mwana: na asya, Nĩkwĩthĩwa Yeova nĩwew’a kana nyie nĩ mũmene, kwondũ wa ũu anenga mwana ũũ nake: na amwĩta syĩtwa yake Simeoni.'),
('kam', 'GEN', 29, 34, 'Na aya ĩvu ĩngĩ, na asyaa mwana; na asya, Yu ĩvinda yĩĩ mũemewa akalũman’ya nakwa, nũndũ namũsyaĩa ana atatũ: kwondũ wa ũu syĩtwa yake eetwa Livai.'),
('kam', 'GEN', 29, 35, 'Na aya ĩvu ĩngĩ, na asyaa mwana: na asya, ĩvinda yĩĩ nĩngũtaĩa Yeova: kwondũ wa ũu amwĩta syĩtwa yake Yuta; nake aeka ũsyaa.'),
('kam', 'GEN', 30, 1, 'Na Lakeli oona kana ndaamũsyaĩa Yakovo syana, Lakeli amwĩw’ĩa mwĩĩtu‐a‐inyia kĩwĩu; na amwĩa Yakovo, Nenga syana, ethĩwa ti ũu ngakw’a nyie.'),
('kam', 'GEN', 30, 2, 'Na Yakovo amũthatĩa Lakeli: na akũlya, Nyie nĩ vandũ va Ngai, ũla ũkũvatĩte ũsyao wa ĩvu?'),
('kam', 'GEN', 30, 3, 'Nake asya, Sisya, Mbila, mũthũkũmi wakwa mwĩĩtu, lika kwake; nĩ kana asyaĩe maunĩ makwa, nose syana nũndũ wake.'),
('kam', 'GEN', 30, 4, 'Na amũnenga Mbila mũthũkũmi wake mwĩĩtu, ethĩwe mũka wake: na Yakovo alika kwake.'),
('kam', 'GEN', 30, 5, 'Na Mbila aya ĩvu, na amũsyaĩa Yakovo mwana.'),
('kam', 'GEN', 30, 6, 'Na Lakeli asya, Ngai nĩwanzilĩla katĩ, na ĩngĩ nĩwew’a wasya wakwa, na anenga mwana: kwondũ wa ũu anwĩta syĩtwa yake Ndani.'),
('kam', 'GEN', 30, 7, 'Na Mbila mũthũkũmi wa Lakeli, mwĩĩtu, aya ĩvu ĩngĩ, na amũsyaĩa Yakovo mwana wa kelĩ.'),
('kam', 'GEN', 30, 8, 'Na Lakeli asya, Nakĩlan’ya na mwĩĩtu‐a‐ia na mokĩlan’yo manene, nakwa nakĩlya: na amwĩta syĩtwa yake Navitali.'),
('kam', 'GEN', 30, 9, 'Nake Lea oona kana nũekete ũsyaa, oosa Nziliva mũthũkũmi wake, mwĩĩtu, anenga Yakovo ethĩwe mũka wake.'),
('kam', 'GEN', 30, 10, 'Na Nziliva mũthũkũmi wa Lea, mwĩĩtu, amũsyaĩa Yakovo mwana.'),
('kam', 'GEN', 30, 11, 'Na Lea asya, Nĩ ĩvuso yakwa! Na amwĩta syĩtwa yake Ngati.'),
('kam', 'GEN', 30, 12, 'Na Nziliva mũthũkũmi wa Lea, mwĩĩtu, amũsyaĩa Yakovo mwana wa kelĩ.'),
('kam', 'GEN', 30, 13, 'Na Lea asya, Nĩ mũtanu nyie! Nũndũ eĩtu makambĩta mũtanu: na amwĩta syĩtwa yake Aseli.'),
('kam', 'GEN', 30, 14, 'Na mĩthenya ya ũketha nganũ, Leuveni athi oona mũũndanĩ mosyao ma kwendana, na amũetee Lea inyia wake. Nĩvo Lakeli wamwĩie Lea, Ame, nenga ala mosyao ma kwendana ma mwana waku.'),
('kam', 'GEN', 30, 15, 'Nake amwĩa, Nĩ ũndũ ũnini we kũmbena mũũme wakwa? Na ĩngĩ nũkwenda kwosa mosyao ma kwendana ma mwana wakwa namo? Na Lakeli asũngĩa, Kwa ũu akakoma naku ũtukũ ũũ nũndũ wa mosyao ma kwendana ma mwana waku.'),
('kam', 'GEN', 30, 16, 'Na wĩoo Yakovo ooka aumĩte mũũndanĩ, na Lea athi kũmũthaũa, na amwĩa, Mũvaka ũlike kwakwa: nũndũ nĩ w’o nĩkumĩsye ĩtuvi ya mosyao ma kwendana ma mwana wakwa. Na akoma nake ũtukũ ũsu.'),
('kam', 'GEN', 30, 17, 'Na Ngai amwĩthukĩĩsya Lea, nake aya ĩvu, na amũsyaĩa Yakovo mwana wa katano.'),
('kam', 'GEN', 30, 18, 'Na Lea asya, Ngai nĩwanenga ĩtuvi yakwa, nĩkwĩthĩwa nĩnĩmũnengete mũemewa mũthũkũmi wakwa, mwĩĩtu: na amwĩta syĩtwa yake Isakali.'),
('kam', 'GEN', 30, 19, 'Na Lea aya ĩvu ĩngĩ, na amũsyaĩa Yakovo mwana wa thanthatũ.'),
('kam', 'GEN', 30, 20, 'Na Lea asya, Ngai nĩwanenga mũthĩnzĩo mũseo; yu mũemewa akekalaa nakwa, nũndũ nĩnĩmũsyaĩe ana thanthatũ: na amwĩta syĩtwa yake Nzevuluni.'),
('kam', 'GEN', 30, 21, 'Na ĩtina asyaa mwĩĩtu, na amwĩta syĩtwa yake Ndina.'),
('kam', 'GEN', 30, 22, 'Na Ngai amũlilikana Lakeli, na Ngai amwĩthukĩĩsya, na amũnenga kũsyaa.'),
('kam', 'GEN', 30, 23, 'Nake aya ĩvu, na asyaa mwana: na asya, Ngai nũmbetee nthoni syakwa:'),
('kam', 'GEN', 30, 24, 'na amwĩta syĩtwa yake Yosevu, akyasya, Yeova nambongele mwana ũngĩ.'),
('kam', 'GEN', 30, 25, 'Na kweethĩwa, Lakeli asyaa Yosevu, Yakovo amwĩa Lavani, Eka nĩthĩ, nĩ kana nĩende vandũ vakwa mwene, na nthĩ yakwa.'),
('kam', 'GEN', 30, 26, 'Nenga aka makwa na syana syakwa ila nakũthũkũmĩe, noindeka nĩthi: nũndũ nĩwĩsĩ ũthũkũmi wakwa ũla nakũthũkũmie.'),
('kam', 'GEN', 30, 27, 'Na Lavani amwĩa, Ethĩwa ĩndĩ nĩnonete ũseo methonĩ maku, ĩkala: nũndũ nĩnamanyie kana Yeova nũngathimĩte kwondũ waku.'),
('kam', 'GEN', 30, 28, 'Na asya, Weta ĩtuvi yaku, nakwa nĩngumya.'),
('kam', 'GEN', 30, 29, 'Nake amwĩa, Nĩwĩsĩ ũndũ nakũthũkũmie, na ũndũ indo syaku syekalile nĩ nasyo.'),
('kam', 'GEN', 30, 30, 'Nũndũ mbee wa ndanoka waĩ na nini, nasyo syongeleka syeethĩwa nyingĩ; na Yeova nũkũathimĩte o kũla naendie nyie: na yu ĩndĩ ngamombanĩsya ĩndĩĩ asu ma nyũmba yakwa mwene nao?'),
('kam', 'GEN', 30, 31, 'Nake akũlya, Ngũnenge kyaũ? Na Yakovo asũngĩa, Ndũkanenge kĩndũ: ethĩwa ũkambĩka ũndũ ũũ, ngaĩthya ndĩthya yaku ya mbũi na malondu.'),
('kam', 'GEN', 30, 32, 'Ũmũnthĩ ngavĩtĩla ndĩthyanĩ yaku yonthe, ngyumya vo kĩla ĩmwe yĩ kĩtathe na yĩ maa, na kĩla yĩmwe yiũ malondunĩ, na ila syĩ maa na ila syĩ kĩtathe mbũinĩ: nĩsyo ikeethĩwa ĩtuvi yakwa.'),
('kam', 'GEN', 30, 33, 'O ta ũu ũlũngalu wakwa ũkangũsĩĩa ĩtina, yĩla wĩũka kwondũ wa ĩtuvi yakwa yĩla yĩ mbee waku: kĩla ĩmwe ĩte kĩtathe kana maa mbũinĩ, kana yĩte yiũ malondunĩ, ĩkyoneka kwakwa, ĩsu ĩkatalwa nĩyoyiwe.'),
('kam', 'GEN', 30, 34, 'Na Lavani asũngĩa, Sisya, nenda kwĩthĩwe o ta ndeto yaku.'),
('kam', 'GEN', 30, 35, 'Na mũthenya ũsu aumya nthenge ila syaĩ matw’ana na maa, na mbũi nga syonthe ila syaĩ kĩtathe na maa, o kĩla ĩmwe yaĩ na weũ, o na maiũ onthe malondunĩ, ainengane mokonĩ ma ana make:'),
('kam', 'GEN', 30, 36, 'nake ataanĩsya na Yakovo mũendo wa matukũ atatũ: na Yakovo aĩthya ndĩthya sya mbũi na malondu sya Lavani ila syatialile.'),
('kam', 'GEN', 30, 37, 'Na Yakovo oosa ndata sya mĩtĩ ya mĩlivina mĩũ, na ya mĩlosi na ya mĩalamoni; na aisyũlya nzoa nzaũ, na atuma weũ ũla waĩ ndatanĩ woneka.'),
('kam', 'GEN', 30, 38, 'Na aia ndata ila wasyũlĩtye tũmĩtalũnĩ mĩvalatĩnĩ kwelekela ndĩthya sya mbũi na malondu, vala ndĩthya syokaa kũnyw’a; na syaya mavu yĩla syookaa kũnyw’a.'),
('kam', 'GEN', 30, 39, 'Na i ndĩthya syaya mavu syĩ o mbee wa ila ndata, na i ndĩthya syasyaa tũtena twĩ matw’ana, na kĩtathe, na maa.'),
('kam', 'GEN', 30, 40, 'Na Yakovo avathan’ya tũtena twa malondu, na ekalya mothyũ ma ndĩthya melekele ila syaĩ matw’ana na ila nziũ syonthe sya ndĩthya ya Lavani: nake avathan’ya maĩthya make mwene, o na ndaavulan’ya na ndĩthya ya Lavani.'),
('kam', 'GEN', 30, 41, 'Na kweethĩwa, ila sya ndĩthya ila syaĩ na vinya mbee syaya mavu, Yakovo aia ila ndata mbee wa metho ma ndĩthya tũmĩtalũnĩ, nĩ kana iye mavu syĩ katĩ wa ila ndata;'),
('kam', 'GEN', 30, 42, 'ĩndĩ yĩla ĩĩthya yĩtaĩ na vinya, ndaayiĩa: na ĩndĩ ila itaĩ na vinya syeethĩwa sya Yakovo.'),
('kam', 'GEN', 30, 43, 'Na mũndũ ũsu ongeleka mũno, na aĩ na ndĩthya nene sya mbũi na malondu, na athũkũmi eĩtu na aũme, na ngamĩle na mang’oi.'),
('kam', 'GEN', 31, 1, 'Nake eew’a ndeto sya ana ma Lavani, makyasya, Yakovo nũtwaĩte syonthe ila syaĩ sya asa waitũ; nake nĩwĩyoseete ũthwii ũũ w’onthe kuma ũla waĩ wa asa waitũ.'),
('kam', 'GEN', 31, 2, 'Na Yakovo asisya ũthyũ wa Lavani, na, lĩlĩ, ndwailyĩ kwake ta tene.'),
('kam', 'GEN', 31, 3, 'Na Yeova amwĩa Yakovo, Syoka nthĩ ya aau, na kwa ũko waku; nakwa ngeethĩwa vamwe naku.'),
('kam', 'GEN', 31, 4, 'Na Yakovo atũmana ameta Lakeli na Lea moke kĩsesinĩ ndĩthyanĩ yake,'),
('kam', 'GEN', 31, 5, 'na amea, Nĩngwona ũthyũ wa ĩthe wenyu, kana ndũilyĩ kwakwa ta tene; ĩndĩ Ngai wa nau eĩ nakwa.'),
('kam', 'GEN', 31, 6, 'Na inyw’ĩ nĩmwĩsĩ kana nĩthũkũmĩte ĩthe wenyu na vinya wakwa w’onthe.'),
('kam', 'GEN', 31, 7, 'Na ĩthe wenyu nũngengete, na kũalyũla ĩtuvi yakwa mavinda ĩkũmi; ĩndĩ Ngai ndaamũeka ambĩke naĩ.'),
('kam', 'GEN', 31, 8, 'Ethĩwa nĩwaisye ũũ, Ila syĩ kĩtathe ikeethĩwa ĩtuvi yaku; nĩvo ndĩthya yonthe yasyaie syĩ kĩtathe: na ethĩwa nĩwaisye ũũ, Ila syĩ matw’ana ikeethĩwa ĩtuvi yaku; nĩvo ndĩthya yonthe yasyaie syĩ matw’ana.'),
('kam', 'GEN', 31, 9, 'Ũu nĩw’o Ngai waumisye indo sya ĩthe wenyu, na anenga.'),
('kam', 'GEN', 31, 10, 'Na kweethĩwa yĩla ndĩthya yaĩe mavu, nookĩlya metho, noona ndotonĩ, na, sisya, nthenge ila syatũlĩĩlaa ndĩthya syaĩ matw’ana, na kĩtathe, na ĩumbĩ.'),
('kam', 'GEN', 31, 11, 'Na mũlaĩka wa Ngai ambĩa ndotonĩ, Yakovo: nakwa nasũngĩa, Nĩ vaa.'),
('kam', 'GEN', 31, 12, 'Nake ambĩa, Yu ũkĩlya metho, wone: nthenge syonthe ila itũlĩĩlaa ndĩthya syĩ matw’ana, na kĩtathe, na ĩumbĩ: nũndũ nĩnonete w’onthe ũla Lavani ũkwĩkĩte.'),
('kam', 'GEN', 31, 13, 'Ninyie Ngai wa Mbethi‐eli, vala wetĩkĩsye kĩtuĩ mauta, vala weembĩtĩe wĩvĩto: yu ũkĩla, wume nthĩ ĩno, ũsyoke nthĩ ĩla wasyaĩwe.'),
('kam', 'GEN', 31, 14, 'Na Lakeli na Lea masũngĩa mamwĩa, Kwĩ kĩanda kĩngĩ kana ũtiĩwa witũ nyũmbanĩ ya asa waitũ?'),
('kam', 'GEN', 31, 15, 'Tũtitalawa nĩwe ta andũ ma nthĩ ĩngĩ? Nũndũ nũtũthooetye, nake aya vyũ thooa witũ.'),
('kam', 'GEN', 31, 16, 'Nũndũ ũthwii w’onthe ũla Ngai wosie kwa asa waitũ, nĩw’o witũ na wa syana sitũ: na yu ĩndĩ, o ũla Ngai ũkũtavĩtye, wĩke.'),
('kam', 'GEN', 31, 17, 'Nĩvo Yakovo wokĩlile, na atũlya ana make na aka make ĩũlũ wa ngamĩle;'),
('kam', 'GEN', 31, 18, 'na atwaa indo syake syonthe, na ũthwii wake w’onthe ũla wombanisye, indo ila weyosee, ila wombanĩsye kũu Vatani‐alamu, nĩ kana aende nthĩ ya Kanaani kwa Isaka ĩthe wake.'),
('kam', 'GEN', 31, 19, 'Na ĩndĩ Lavani ethĩwe anaenda kũtila malondu make w’ĩa: na Lakeli nĩwoyie telavimu ya ĩthe wake.'),
('kam', 'GEN', 31, 20, 'Na Yakovo nĩwamwĩvithĩie Lavani Mũsilia na athi, nĩkwĩthĩwa ndaamũtavya kana nũnũũkĩa.'),
('kam', 'GEN', 31, 21, 'Na ĩndĩ akĩa we na syonthe ila waĩ nasyo; na ookĩla, na ainga ũla Ũsĩ, na eelekelya ũthyũ kĩĩmanĩ kya Ngileati.'),
('kam', 'GEN', 31, 22, 'Na mũthenya wa katatũ Lavani atavw’a kana Yakovo nũkĩĩte.'),
('kam', 'GEN', 31, 23, 'Na aendan’ya na ana‐a‐ĩthe, na amũatĩĩa mũendo wa matukũ mũonza; na amwĩthĩa kĩĩmanĩ kya Ngileati.'),
('kam', 'GEN', 31, 24, 'Na Ngai amũkĩa Lavani Mũsilia ndotonĩ ya ũtukũ, na amwĩa, Ĩsũvĩe ndũkaneene na Yakovo ũseo kana ũthũku.'),
('kam', 'GEN', 31, 25, 'Na Lavani avika vala ve Yakovo. Na Yakovo ethĩwe anamba ĩeema yake kĩĩmanĩ: na Lavani vamwe na ana‐a‐ĩthe make amba maeema kĩĩmani kya Ngileati.'),
('kam', 'GEN', 31, 26, 'Na Lavani amwĩa Yakovo, Wĩkĩte ata, we, wathi wĩmbithĩte, na watwaa eĩtu makwa wathi nao ta mĩtavo ya ũvyũ?'),
('kam', 'GEN', 31, 27, 'Nĩkĩ ũkĩie kĩmbithĩ, na kwĩmbũyĩa, o na ndũneendavya, nĩ kana nĩkumaasye na ũtanu na mbathi, na tũthembe na mbeve;'),
('kam', 'GEN', 31, 28, 'o na ndũneenenga ũthei nĩmamumunye ana makwa na eĩtu makwa? Yu ĩndĩ nĩwĩkĩte ũtumanu.'),
('kam', 'GEN', 31, 29, 'Nĩ na ũtonyi kw’okonĩ kwakwa wa ũkwĩka naĩ: ĩndĩ Ngai wa au nũneenie nakwa ũtukũ, akĩmbĩa, Ĩsũvĩe ndũkaneene na Yakovo ũseo kana ũthũku.'),
('kam', 'GEN', 31, 30, 'Na yu ĩndĩ, o na ethĩwa nũkwenda kũthi, nĩkwĩthĩwa wĩ na mea mũno ma nyũmba ya au, nĩkĩ ĩndĩ ũnooyie ngai syakwa?'),
('kam', 'GEN', 31, 31, 'Na Yakovo asũngĩa na amwĩa Lavani, Nĩkwĩthĩwa nĩnĩnakũkĩaa: nũndũ nĩnaasya, Nokwĩthĩwa ũkambena eĩtu maku na vinya.'),
('kam', 'GEN', 31, 32, 'O ũla ũkwona e na ngai syaku, ũsu ndakekala thayũ: ana‐a‐asa maitũ me vo manya kĩla kyaku kĩ kwakwa, wĩyosee. Nũndũ Yakovo ndaamanya kana Lakeli nũnasyũyĩte.'),
('kam', 'GEN', 31, 33, 'Na Lavani avota ĩeemanĩ ya Yakovo, na ĩeemanĩ ya Lea, na ĩeemanĩ ya athũkũmi elĩ eĩtu; ĩndĩ ndaasyona. Na auma ĩeemanĩ ya Lea, na avota ĩeemanĩ ya Lakeli.'),
('kam', 'GEN', 31, 34, 'Nake Lakeli nĩwosete telavimu, na akaia nthĩnĩ wa matandĩko ma ngamĩle, na akamĩkalĩla. Na Lavani avavata ĩeemanĩ kw’onthe, o na ndaamyona.'),
('kam', 'GEN', 31, 35, 'Nake amwĩa ĩthe, Mwĩaĩi wakwa ndakanthatĩe nũndũ nditonya kũkĩla mbee waku; nũndũ mwĩkalĩle wa aka wĩ nakwa. Nake amantha mũno o na ndaaona ĩla telavimu.'),
('kam', 'GEN', 31, 36, 'Na Yakovo aĩ mũthilĩku mũno, na akandanĩa na Lavani: na Yakovo asũngĩa na amwĩa Lavani, Ĩvĩtyo yakwa nĩ yaũ? Naĩ yakwa nĩ myaũ, ũndũ wangatĩĩa na ũthatu?'),
('kam', 'GEN', 31, 37, 'Ũndũ wavavata mĩionĩ yonthe yakwa, wona mũio mwaũ wa nyũmba yaku yonthe? Ia vaa mbee wa anaasa na ana‐au nĩ kana matũsilan’ye ithyĩ elĩ.'),
('kam', 'GEN', 31, 38, 'Myaka ĩno mĩongo ĩlĩ naĩ kwaku; malondu maka maku na mbũi nga syaku ityaavuna, o na ndũũme sya ndĩthya syaku sya malondu ndyaaya.'),
('kam', 'GEN', 31, 39, 'Ĩla yavũnyangiwe nĩ nyamũ mbai ndyaakũetee; nyie nĩnoosie wasyo wayo; kw’okonĩ kwakwa nĩwamĩandũie, ethĩwa yooyiwe mũthenya kana ethĩwa yooyiwe ũtukũ.'),
('kam', 'GEN', 31, 40, 'Nethĩiwe ũu; mũthenya mũnyao nĩwaminie, na mbevo ũtukũ; na too nĩwanthelile methonĩ.'),
('kam', 'GEN', 31, 41, 'Myaka ĩno mĩongo ĩlĩ naĩ nyũmbanĩ kwaku; nĩnakũthũkũmie myaka ĩkũmi na ĩna kwondũ wa eĩtu maku elĩ, na myaka thanthatũ kwondũ wa ndĩthya yaku ya mbũi na malondu: naku nũalyũlĩte ĩtuvi yakwa mavinda ĩkũmi.'),
('kam', 'GEN', 31, 42, 'Keka Ngai wa asa wakwa, Ngai wa Avalaamu, na Kĩkĩo kya Isaka, kwĩthĩwa vamwe nakwa, nĩ w’o yu wĩthĩwa wandũngilye nde na kĩndũ. Ngai nĩwonete thĩna wakwa na wĩa wa moko makwa, nake akũkan’ya ũtukũ ũũ.'),
('kam', 'GEN', 31, 43, 'Na Lavani asũngĩa na amwĩa Yakovo, Eĩtu nĩ eĩtu makwa, na syana nĩ syana syakwa, na ndĩthya nĩ ndĩthya syakwa, na syonthe ila ũkwona nĩ syakwa: na eĩtu aa makwa ndonya kũmeka ata ũmũnthĩ, o na syana syoo ila masyaie?'),
('kam', 'GEN', 31, 44, 'Na yu ĩndĩ ũka, tũtianĩe ũtianĩo, nyie naku; naw’o wĩthĩwe ũkũsĩ katĩ wakwa naku.'),
('kam', 'GEN', 31, 45, 'Na Yakovo oosa ĩvia, ayĩũngamya kĩtuĩ.'),
('kam', 'GEN', 31, 46, 'Na Yakovo amea ana‐a‐ĩthe, Ũmban’yai mavia; na moosa mavia, moomban’ya mbumbu: na maĩsanĩĩa vu mbumbunĩ.'),
('kam', 'GEN', 31, 47, 'Na Lavani amĩta Yekali‐saatutha: ĩndĩ Yakovo amĩta Ngaleeti.'),
('kam', 'GEN', 31, 48, 'Na Lavani asya, Mbumbu ĩno nĩ ũkũsĩ katĩ wakwa naku ũmũnthĩ. Kwondũ wa ũu syĩtwa yayo yeetwa Ngaleeti;'),
('kam', 'GEN', 31, 49, 'na Misiva, nũndũ aisye, Yeova nasyaĩĩsye katĩ wakwa naku, twataanĩsya ũmwe na ũngĩ.'),
('kam', 'GEN', 31, 50, 'Ethĩwa ũkathĩn’ya eĩtu makwa, na ethĩwa ũkatwaanĩsya aka angĩ vamwe na eĩtu makwa, vati mũndũ wĩ vamwe naitũ; sisya, Ngai nĩwe ngũsĩ yakwa naku.'),
('kam', 'GEN', 31, 51, 'Na Lavani amwĩa Yakovo, Sisya mbumbu ĩno, na sisya kĩtuĩ, kĩla naũngamya katĩ wakwa naku.'),
('kam', 'GEN', 31, 52, 'Mbumbu ĩno ĩthĩwe ũkũsĩ, na kĩtuĩ kĩĩ nakyo kĩthĩwe ũkũsĩ, kana nyie ndikakĩla mbumbu ĩno nũke kwaku, o naku we ndũkakĩla mbumbu ĩno o na kĩtuĩ kĩĩ wũke kwakwa, kwondũ wa ũthũku.'),
('kam', 'GEN', 31, 53, 'Ngai wa Avalaamu, na Ngai wa Naoli, nake nĩwe Ngai wa ĩthe woo, asile katĩ waitũ. Na Yakovo eevĩta kwa Kĩkĩo kya ĩthe wake Isaka.'),
('kam', 'GEN', 31, 54, 'Na Yakovo athemba nthembo kĩĩmanĩ, na ameta ana‐a‐ĩthe moke maye lĩu: nao maya lĩu, na mekala ũtukũ mũima kĩĩmanĩ.'),
('kam', 'GEN', 31, 55, 'Na kĩoko tene Lavani ookĩla, na amamumunya ana make na eĩtu make na amaathima: na Lavani auma vau, asyoka kwake.'),
('kam', 'GEN', 32, 1, 'Na Yakovo eeyĩendea, na alaĩka ma Ngai makomana nake.'),
('kam', 'GEN', 32, 2, 'Na Yakovo amona asya, Nguthu ya Ngai nĩ ĩno: na aveta vandũ vau syĩtwa yavo Maanaimu.'),
('kam', 'GEN', 32, 3, 'Na Yakovo atũma atũmwa mbee wake kwa Esau mwana‐a‐inyia kũvika nthĩ ya Seili, ũiĩnĩ wa Etomu.'),
('kam', 'GEN', 32, 4, 'Na ameaĩa, akĩmea, Mũtavyei mwĩaĩi wakwa Esau ũũ: Mũthũkũmi waku Yakovo easya atĩĩ, Nĩnekalĩte nĩ mũeni kwa Lavani, na nĩtwĩe kw’o kũvika o na yu:'),
('kam', 'GEN', 32, 5, 'nakwa nĩ na ng’ombe, na mang’oi, na ndĩthya sya mbũi na malondu na athũkũmi aũme na eĩtu: nakwa nĩnatũmana nĩmũtavye mwĩaĩi wakwa, nĩ kana none ũseo methonĩ maku.'),
('kam', 'GEN', 32, 6, 'Na atũmwa mamũsyokea Yakovo, makĩmwĩa, Nĩtũvikie kwa mwana‐a‐mwenyu Esau, nake nĩwũkĩte akũthaũe, e na andũ maana ana vamwe nake.'),
('kam', 'GEN', 32, 7, 'Nĩvo Yakovo wakĩie mũno na aũũya: na aan’ya nguthu ilĩ andũ ala maĩ nake, na ndĩthya sya mbũi na malondu, na sya ng’ombe, na ngamĩle;'),
('kam', 'GEN', 32, 8, 'na asya, Ethĩwa Esau akooka kwa nguthu ya mbee, na kũmĩkũna, nguthu ĩla yĩtiala ĩkavonoka.'),
('kam', 'GEN', 32, 9, 'Na Yakovo asya, Ame Ngai wa asa wakwa Avalaamu, na Ngai wa asa wakwa Isaka, ame Yeova, ũla wambĩie, Syoka nthĩ yaku, na kwa ũko waku, nakwa ngakwĩka nesa:'),
('kam', 'GEN', 32, 10, 'ndyaĩlwe nyie nĩ kanini mbee ka moseo maku me wendo, na w’o w’onthe ũla wamwonisye mũthũkũmi waku; nĩkwĩthĩwa nĩnaingie Yolotani ũũ na ndata yakwa; na yu nĩnĩtw’ĩkĩte nguthu ilĩ.'),
('kam', 'GEN', 32, 11, 'Nĩngũkwĩsũva, ndangĩĩa kuma kw’okonĩ kwa mwana‐a‐ia, kw’okonĩ kwa Esau: nũndũ nyie nĩngũmũkĩa, ndakese kũka na kũngũna, o na inyia vamwe na syana.'),
('kam', 'GEN', 32, 12, 'Naku waisye, Nditĩa kũkwĩka nesa, na kũtw’ĩkĩthya ũsyao waku ta kĩthangathĩ kya ũkanga, kĩla kĩtatalĩka nĩ kwingĩva.'),
('kam', 'GEN', 32, 13, 'Na akoma vo ũtukũ ũsu, na kuma katĩ wa ila waĩ nasyo oosa mũthĩnzĩo kwondũ wa Esau, mwana‐a‐inyia:'),
('kam', 'GEN', 32, 14, 'mbũi nga maana elĩ na nthenge mĩongo ĩlĩ, na malondu maka maana elĩ na ndũũme mĩongo ĩlĩ,'),
('kam', 'GEN', 32, 15, 'na ngamĩle ikwongya mĩongo ĩtatũ na tũtena twasyo, na ng’ombe nga mĩongo ĩna na nzaũ ĩkũmi, na mang’oi maka mĩongo ĩlĩ na tũtena twamo ĩkũmi.'),
('kam', 'GEN', 32, 16, 'Na anengane mokonĩ ma athũkũmi make, kĩla ĩĩthya yĩ yoka, na amea athũkũmi make, Ingai mbee wakwa, na tiai ũthei katĩ wa ĩĩthya na ĩĩthya.'),
('kam', 'GEN', 32, 17, 'Na amwĩaĩa wa mbee, akĩmwĩa, Mwana‐a‐ia Esau akomana naku, na akũkũlya, akyasya, Wĩ waũ? Na wĩthi kũ? Na nĩ syaũ ii syĩ mbee wakũ?'),
('kam', 'GEN', 32, 18, 'Nĩvo wĩasya, Nĩ sya mũthũkũmi waku Yakovo: nĩsyo mũthĩnzĩo waetwe kwa mwĩaĩi wakwa Esau: na, sisya, nake mwene e ĩtina waitũ.'),
('kam', 'GEN', 32, 19, 'Na eaĩa wa kelĩ nake, na wa katatũ, na onthe ala maatĩĩe maĩthya, akĩmea, Mũkaneene na Esau o ta ũu, mwoonana nake;'),
('kam', 'GEN', 32, 20, 'na mũkasya, Na ĩngĩ, sisya, mũthũkũmi waku Yakovo e ĩtina waitũ. Nũndũ nĩwaisye, Ngamũvoovya na mũthĩnzĩo ũla ũendete mbee wakwa, na ĩtina ngoona ũthyũ wake; nokwĩthĩwa embĩtĩkĩla nyie.'),
('kam', 'GEN', 32, 21, 'Na ĩndĩ ũla mũthĩnzĩo wainga mbee wake: nake mwene akoma ũtukũ ũsu vamwe na nguthu.'),
('kam', 'GEN', 32, 22, 'Na ookĩla ũtukũ ũsu, na oosa aka make elĩ, na athũkũmi make elĩ, eĩtu, na ana make ĩkũmi na ũmwe, ainga ĩsyũko ya Yavoki.'),
('kam', 'GEN', 32, 23, 'Na amatwaa, amaingya ũsĩ, na aingya ila waĩ nasyo.'),
('kam', 'GEN', 32, 24, 'Na Yakovo atiwa e weka; na kweethĩwa mũndũ akĩthĩan’ya nake mũvaka kũikya.'),
('kam', 'GEN', 32, 25, 'Na oona ndamũtonya, amũkiita kĩna kya waswa; na kĩna kya waswa wa Yakovo kyakitũka, akĩthĩan’ya nake.'),
('kam', 'GEN', 32, 26, 'Nake amwĩa, Ndeka nĩthi, nũndũ nĩkũũkya. Na asũngĩa, Ndikũeka, ũtangathimĩte.'),
('kam', 'GEN', 32, 27, 'Nake amũkũlya, Syĩtwa yaku nata? Na asũngĩa, Yakovo.'),
('kam', 'GEN', 32, 28, 'Nake amwĩa, Syĩtwa yaku ndũketwa Yakovo ĩngĩ, ĩndĩ Isilaeli: nũndũ nĩwakĩlan’ya vinya na Ngai na ĩngĩ na andũ, na wakĩlya vinya.'),
('kam', 'GEN', 32, 29, 'Na Yakovo amũkũlya na asya, Nĩngũũvoya, ndavya syĩtwa yaku. Nake asũngĩa, Wĩngũlya syĩtwa yakwa nĩkĩ? Na amũathimĩa o vau.'),
('kam', 'GEN', 32, 30, 'Na Yakovo aveta syĩtwa ya vandũ vau Venieli: asya, Nũndũ nĩnamwona Ngai ũthyũ kwa ũthyũ, na nĩnatangĩĩwa thayũ wakwa.'),
('kam', 'GEN', 32, 31, 'Na syũa yamumĩa akĩinga Venueli, nake nĩwathuaa waswa.'),
('kam', 'GEN', 32, 32, 'Kwondũ wa ũu ana ma Isilaeli matiĩsaa kaliilii ka nthũnũ kala ke kĩnanĩ kya waswa, kũvika mũnthĩ ũũ: nũndũ nĩwakiitie kĩna kya waswa wa Yakovo vala ve kaliilii ka nthũnũ.'),
('kam', 'GEN', 33, 1, 'Na Yakovo ookĩlya metho, na oona, na, sisya, Esau okĩte, na andũ maana ana vamwe nake. Na amaaĩa syana Lea, na Lakeli, na ala athũkũmi elĩ eĩtu.'),
('kam', 'GEN', 33, 2, 'Na ekalya ala athũkũmi eĩtu, na syana syoo mbee, na Lea na syana syake ĩtina woo, na Lakeli na Yosevu ĩtina.'),
('kam', 'GEN', 33, 3, 'Nake mwene ainga mbee woo, na eekunamya nthĩ kũndũ mũonza, mũvaka athengeea mwana‐a‐inyia.'),
('kam', 'GEN', 33, 4, 'Na Esau asemba kũmũthaũa, na amwĩvĩtĩĩsya, na amũvalũkĩla ngingo, amũmumunya: na maĩanĩa.'),
('kam', 'GEN', 33, 5, 'Na ĩndĩ ookĩlya metho, oona aka na syana; na akũlya, Naaũ aa me naku? Na asũngĩa, Nĩ syana ila Ngai wanengie mũthũkũmi waku kwa ĩnee.'),
('kam', 'GEN', 33, 6, 'Na ĩndĩ athũkũmi eĩtu, mathengeea, mo na syana syoo, nao meekunamya.'),
('kam', 'GEN', 33, 7, 'Na Lea nake na syana syake mathengeea, na meekunamya: na ĩtina Yosevu athengeea e na Lakeli, na meekunamya.'),
('kam', 'GEN', 33, 8, 'Na akũlya, Wĩasya ata na nguthu ino nene ĩla nakomana nayo? Na asũngĩa, Nĩ kana none ĩnee methonĩ ma mwĩaĩi wakwa.'),
('kam', 'GEN', 33, 9, 'Na Esau amwĩa, Nĩnĩanĩwe, mwana‐a‐ia; syĩthĩwe syaku ila wĩ nasyo.'),
('kam', 'GEN', 33, 10, 'Na Yakovo asya, Aiee, nĩngũkwĩsũva, yu ĩndĩ ethĩwa nĩnoona ĩnee methonĩ maku, osa mũthĩnzĩo wakwa kw’okonĩ kwakwa; nĩkwĩthĩwa nĩnoona ũthyũ waku, o ta kwona ũthyũ wa Ngai, naku nĩwendeew’e ninyie.'),
('kam', 'GEN', 33, 11, 'Nĩngũkwĩsũva, osa mũthĩnzĩo wakwa ũla ũetewe; nĩkwĩthĩwa Ngai nũmbĩw’ĩĩte ĩnee, nũndũ nĩnĩanĩwe. Na amũthetheesya, na awosa.'),
('kam', 'GEN', 33, 12, 'Na asya, Tũkwate kyalo, tũthi, nakwa nĩngũendaa mbee waku.'),
('kam', 'GEN', 33, 13, 'Na amwĩa, Mwĩaĩi wakwa nĩwĩsĩ kana syana nĩ masanga, na ndĩthya sya mbũi na malondũ na sya ng’ombe ila nĩ nasyo nikwongya: na ikakalaatwa mũthenya ũmwe, ndĩthya syonthe sya mbũi na malondu no ũkw’a.'),
('kam', 'GEN', 33, 14, 'Nĩngũkwĩsũva, mwĩaĩi wakwa nainge mbee wa mũthũkũmi wake: nakwa ngooka mbola, mũendo wĩanĩe indo ila syĩ mbee wakwa na mũendo wĩanĩe syana, mũvaka yĩla ngavika Seili kwa mwĩaĩi wakwa.'),
('kam', 'GEN', 33, 15, 'Na Esau asya, Nĩngũtiĩe andũ amwe ala me nakwa. Nake akũlya, Ma kĩ? Nĩnone ũseo methonĩ ma mwĩaĩi wakwa.'),
('kam', 'GEN', 33, 16, 'Na ĩndĩ Esau asyoka mũthenya ũsu na nzĩa yake ya kũthi Seili.'),
('kam', 'GEN', 33, 17, 'Na Yakovo athi kyalo kũvika Sukothi, na eeyakĩa nyũmba, na aakĩa indo syake malwanda: na kwa ũu syĩtwa ya vandũ vau vetawa Sukothi.'),
('kam', 'GEN', 33, 18, 'Na Yakovo ooka na mũuo ndũa ya Sekemu, ĩla yĩ nthĩ ya Kanaani, yĩla waumie Vatani‐alamu; na amba maeema mbee wa ndũa.'),
('kam', 'GEN', 33, 19, 'Na vala wambie ĩeema yake, athooa na ilungu ĩana sya vetha, kĩlungu kya nthĩ, kw’okonĩ kwa ana ma Amolu, ĩthe wa Sekemu.'),
('kam', 'GEN', 33, 20, 'Na vau aakĩa kĩthembeo, na akĩta Eli‐EloeIsilaeli.'),
('kam', 'GEN', 34, 1, 'Na Ndina mwĩĩtu wa Lea, ũla wamũsyaĩe Yakovo, aumaala kũsisya eĩtu ma nthĩ ĩsu.'),
('kam', 'GEN', 34, 2, 'Na Sekemu mwana wa Amolu Mũivi, mũnene wa nthĩ ĩsu, amwona; na amwosa, na akoma nake, na amũthũkya.'),
('kam', 'GEN', 34, 3, 'Na ngoo yake yalũman’ya na Ndina mwĩĩtu wa Yakovo, na amwenda ũla mwĩĩtu, na amũneenea ũla mwĩĩtu nesa.'),
('kam', 'GEN', 34, 4, 'Na Sekemu aneena na Amolu ĩthe wake, akĩmwĩa, Mbĩvaĩsya mwĩĩtu ũũ.'),
('kam', 'GEN', 34, 5, 'Na ĩndĩ Yakovo eew’a kana nũvukĩtye mwĩĩtu wake Ndina; na ana make maĩ na indo syake kĩsesinĩ: na Yakovo akilya kũvika masyoka.'),
('kam', 'GEN', 34, 6, 'Na Amolu ĩthe wa Sekemu aumaala athi kwa Yakovo kũneenan’ya nake.'),
('kam', 'GEN', 34, 7, 'Na ana ma Yakovo mooka kuma kĩsesinĩ yĩla meewie ũu: na aũme asu meew’a woo, na maĩ athilĩku mũno, nũndũ nĩwĩkĩte ũtumanu kwa Isilaeli akĩkoma na mwĩĩtu wa Yakovo; ũndũ ũtaĩle kwĩkwa.'),
('kam', 'GEN', 34, 8, 'Na Amolu aneenan’ya nao, akĩmea, Ngoo ya mwana wakwa Sekemu yĩ na wendi wa mwĩĩtu waku: nĩngũkwĩsũva, ũmũnenge ethĩwe mũka wake.'),
('kam', 'GEN', 34, 9, 'Tũtwaanĩei; inyw’ĩ mũtũnenge eĩtu menyu, na mũitwaa eĩtu maitũ.'),
('kam', 'GEN', 34, 10, 'Nenyu mũkatũaa naitũ: na ĩ nthĩ ĩkeethĩwa mbee wenyu; tũai mũtandĩthĩsye kw’o, mwĩmanthĩe ũthwii kw’o.'),
('kam', 'GEN', 34, 11, 'Na Sekemu amwĩa ĩthe wa Ndina na ana‐a‐ĩthe make, Nĩnone ĩnee methonĩ menyu, na kĩla mwĩndavya nĩngumya.'),
('kam', 'GEN', 34, 12, 'Mbĩtyai ngasya na mũthĩnzĩo o na syaingĩva ata, nakwa ngamũnenga o ũndũ mwĩndavya: ĩndĩ nengai mwĩĩtu ndwae.'),
('kam', 'GEN', 34, 13, 'Na ana ma Yakovo mamasũngĩa na ũĩ wa ũkengani Sekemu na Amolu ĩthe wake, na masya, nĩkwĩthĩwa nĩwanangĩte Ndina mwĩĩtu‐a‐inyia woo,'),
('kam', 'GEN', 34, 14, 'na mamea, Tũitonya kwĩka ũndũ ũũ, kũmũnenga mwĩĩtu‐wa‐inyia waitũ ũmwe ũte mwaĩke; nũndũ ũndũ ũsu kwitũ nĩ nthoni.'),
('kam', 'GEN', 34, 15, 'Kwondũ wa ũndũ ũũ w’oka ithyĩ tũkamwĩtĩkĩla inyw’ĩ; ethiwa ĩnyw’ĩ mũkeethĩwa taitũ, kana kĩla mũndũ mũũme wĩ kwenyu nĩaĩkwe;'),
('kam', 'GEN', 34, 16, 'nĩvo twĩmũnenga inyw’ĩ eĩtu maitũ, naitũ tũkatwaa eĩtu menyu, na tũkatũaa vamwe nenyu, naitũ tũkeethĩwa mbaĩ ĩmwe.'),
('kam', 'GEN', 34, 17, 'Ĩndĩ ethĩwa mũitwĩw’a, na kwaĩkwa; nĩvo ĩndĩ twĩosa mwĩĩtu waitũ, na tũkathi.'),
('kam', 'GEN', 34, 18, 'Na ĩndĩ ndeto syoo syendeesya Amolu, na Sekemu mwana wa Amolu.'),
('kam', 'GEN', 34, 19, 'O na mwanake ũsu ndaaĩkala ataneka ũndũ ũsu, nĩkwĩthĩwa amũtanĩaa mwĩĩtu wa Yakovo mũno: nake ataĩawa kwĩ onthe ma nyũmba ya ĩthe.'),
('kam', 'GEN', 34, 20, 'Na Amolu na Sekemu mwana wake mooka mbingĩlonĩ ya ndũa yoo, na maneenan’ya na aũme ma ndũa yoo, makĩmea,'),
('kam', 'GEN', 34, 21, 'Andũ aa me na mũuo naitũ; kwondũ wa ũu nĩmatũae nthĩ ĩno, matandĩthĩasye kw’o; nũndũ, sisya, nthĩ ĩno nĩmeanĩe; naitũ tũtwaae eĩtu moo methĩwe aka maitũ, na ĩndĩ tũimanenga eĩtu maitũ.'),
('kam', 'GEN', 34, 22, 'Kwondũ wa ũndũ ũũ w’oka andũ asu makatwĩtĩkĩla matũae naitũ, twĩthĩwe mbaĩ ĩmwe, ethĩwa kĩla mũndũ mũũme katĩ waitũ akaĩkwa, tondũ mo maĩkawa.'),
('kam', 'GEN', 34, 23, 'Indo syoo na ũthwii woo na nyamũ syoo syonthe itikethĩwa sitũ? Ĩndĩ nĩtũmetĩkĩlĩle ũndũ ũũ, na makatũa naitũ.'),
('kam', 'GEN', 34, 24, 'Na onthe ala maumie mbingĩlonĩ ya ndũa yake mamwĩw’a Amolu na mwana wake Sekemu; na kĩla mũndũ mũũme aĩkwa, onthe ala maumie mbingĩlonĩ ya ndũa yake.'),
('kam', 'GEN', 34, 25, 'Na kweethĩwa mũthenya wa katatũ, yĩla maalaw’a mũno, ana elĩ ma Yakovo, Simeoni na Livai, ana‐a‐inyia ma Ndina, moosa kĩla mũndũ ũvyũ wake, na mookĩa ĩla ndũa mevithĩte, na mooaa aũme onthe.'),
('kam', 'GEN', 34, 26, 'Na mooaa Amolu na Sekemu mwana wake kwa kũmatemanga na ũvyũ, nao maumya Ndina nyũmbanĩ ya Sekemu, na maumaala mathi.'),
('kam', 'GEN', 34, 27, 'Ana ma Yakovo mooka vala ve ala moaĩtwe, matava ĩla ndũa, nĩkwĩthĩwa nĩmavukĩtye mwĩĩtu‐a‐inyia woo.'),
('kam', 'GEN', 34, 28, 'Matava ndĩthya syoo sya mbũi na malondu na ndĩthya syoo sya ng’ombe na mang’oi moo, na kĩla kyaĩ ndũanĩ, na kĩla kyaĩ kĩsesinĩ;'),
('kam', 'GEN', 34, 29, 'na ũthwii woo w’onthe, na syana syoo syonthe nini na aka moo, mamatava matw’ĩka mũtavo, o na kyonthe kĩla kyaĩ nyũmbanĩ.'),
('kam', 'GEN', 34, 30, 'Na Yakovo amea Simeoni na Livai, Inyw’ĩ nĩmwanthĩn’ya, mwatuma nĩnyunga naĩ kwa ala matwĩe ĩ nthĩ, kwa Akanaani na Avelisi: nakwa, nĩkwĩthĩwa ũtalonĩ wakwa nĩ mũvũthũ, makambũmbanĩa na kũngũna; na ngaanangwa, nyie na nyũmba yakwa.'),
('kam', 'GEN', 34, 31, 'Na masya, Akeeka na mwĩĩtu wa mwaitũ ta ĩlwaya?'),
('kam', 'GEN', 35, 1, 'Na Ngai amwĩa Yakovo, Ũkĩla, wambate kũvika Mbethi‐eli, ũkatũe kw’o: na ũimwakĩa Ngai kĩthembeo kũu, ũla wakumĩlĩle yĩla wakĩie kuma mbee wa ũthyũ wa Esau mwana‐a‐mwenyu.'),
('kam', 'GEN', 35, 2, 'Na ĩndĩ Yakovo amea ala ma nyũmba yake, na onthe ala maĩ vamwe nake, Vetai ngai ngeni ila syĩ katĩ wenyu, mwĩthesye, na kũkũan’ya ngũa syenyu:'),
('kam', 'GEN', 35, 3, 'na ĩndĩ tũkĩle, twambate kũvika Mbethi‐eli; nakwa ngamwakĩa Ngai kĩthembeo kw’o, we ũla wanzũngĩie mũthenya wa thĩna wakwa, nake aĩ vamwe nakwa nzĩanĩ ĩla naendele.'),
('kam', 'GEN', 35, 4, 'Na mamũnenga Yakovo ngai ngeni syonthe ĩla syaĩ mokonĩ moo, na ngome ila syaĩ matũnĩ moo; na Yakovo aivitha ĩtina wa mũtĩ wa mwaloni ũla waĩ Sekemu.'),
('kam', 'GEN', 35, 5, 'Na makwata kyalo: na w’ĩa mũnene wa Ngai waĩ ndũanĩ ila syamathyũlũlũkĩte, na maiaamaatĩĩa ana ma Yakovo.'),
('kam', 'GEN', 35, 6, 'Na ĩndĩ Yakovo avika Lusu, ĩla yĩ nthĩ ya Kanaani (nĩyo Mbethi‐eli), we na andũ onthe ala maĩ nake.'),
('kam', 'GEN', 35, 7, 'Na aaka kĩthembeo vau, na aveeta vandũ vau Eli‐Mbethi‐eli; nĩkwĩthĩwa nĩvo Ngai weyonanĩsye kwake, yĩla wakĩĩte kuma mbee wa ũthyũ wa mwana‐a‐inyia.'),
('kam', 'GEN', 35, 8, 'Na Ndevola mũei wa Leveka akw’a, na athikwa ĩtheo wa Mbethi‐eli ĩtina wa mũtĩ wa mwaloni: na syĩtwa yaw’o weetawa Mwaloni‐mbakuthi.'),
('kam', 'GEN', 35, 9, 'Na Ngai amumĩlĩla Yakovo ĩngĩ, auma Vatani‐alamu, na amũathima.'),
('kam', 'GEN', 35, 10, 'Na Ngai amwĩa, Syĩtwa yaku nĩ Yakovo: ndũketwa ĩngĩ syĩtwa yaku Yakovo, ĩndĩ Isilaeli nĩyo yĩĩthĩwa syĩtwa yaku: na amwĩta syĩtwa yake Isilaeli.'),
('kam', 'GEN', 35, 11, 'Na Ngai amwĩa, Ninyie Ngai Mwene Vinya W’onthe: ongeleka wingĩve; mbaĩ na nguthu ya mbaĩ ikauma kwaku, na asumbĩ makauma kĩnyunyunĩ kyaku;'),
('kam', 'GEN', 35, 12, 'na nthĩ ĩla namanengie Avalaamu na Isaka, ngakũnenga we, na ũsyao waku ĩtina waku ngaũnenga nthĩ ĩsu.'),
('kam', 'GEN', 35, 13, 'Na Ngai ambata kuma vala ũĩ o vandũ vala waneenee nake.'),
('kam', 'GEN', 35, 14, 'Na Yakovo aũngamya kĩtuĩ vandũ vala waneenee nake, kĩtuĩ kya ĩvia: na etĩkĩsya nthembo ya kũnyuwa ĩũlũ wakyo, na etĩkĩsya mauta ĩũlũ wakyo.'),
('kam', 'GEN', 35, 15, 'Na Yakovo eeta vandũ vau vala Ngai waneenee nake, Mbethi‐eli.'),
('kam', 'GEN', 35, 16, 'Na mathi kyalo kuma Mbethi‐eli; na vatiele kĩlungu kya mũendo mavike Evilathi: na Lakeli akwatwa nĩ woo wa kũsyaa, na aũnya na vinya.'),
('kam', 'GEN', 35, 17, 'Na kweethĩwa, akyaũnya na vinya, mwĩsikya amwĩa, Ndũkakĩe; nũndũ yu nũkwĩthĩwa na mwana ũngĩ.'),
('kam', 'GEN', 35, 18, 'Na kweethĩwa, veva wake ũkyuma (nũndũ nĩwakwie), amwĩta syĩtwa yake Mbenioni: ĩndĩ ĩthe wake amwĩta Mbenyamini.'),
('kam', 'GEN', 35, 19, 'Na Lakeli akw’a, na athikwa nzĩanĩ ya kũthi Evilathi (nĩyo Mbethi‐leemu).'),
('kam', 'GEN', 35, 20, 'Na Yakovo aũngamya kĩtuĩ ĩũlũ wa mbũa yake: nĩkyo Kĩtuĩ kya mbũa ya Lakeli kũvika mũnthĩ ũũ.'),
('kam', 'GEN', 35, 21, 'Na Isilaeli athi kyalo, na amba ĩeema yake mbee wa mwako mũtũlu wa mũnyoolo wa Eteli.'),
('kam', 'GEN', 35, 22, 'Na kweethĩwa yĩla Isilaeli watũĩte nthĩ ĩsu, Leuveni aenda na akoma na Mbila mũka ngombo wa ĩthe wake: na Isilaeli eew’a ũvoo ũsu. Na ĩndĩ ana ma Yakovo maĩ ĩkũmi na elĩ:'),
('kam', 'GEN', 35, 23, 'ana ma Lea: Leuveni, ĩkithathi ya Yakovo, na Simeoni, na Livai, na Yuta, na Isakali, na Nzevuluni;'),
('kam', 'GEN', 35, 24, 'ana ma Lakeli: Yosevu na Mbenyamini;'),
('kam', 'GEN', 35, 25, 'na ana ma Mbila, mũthũkũmi mwĩĩtu wa Lakeli: Ndani na Navitali;'),
('kam', 'GEN', 35, 26, 'na ana ma Nziliva, mũthũkũmi mwĩĩtu wa Lea: Ngati na Aseli; asu nĩo ana ma Yakovo, ala wasyaĩwe Vatani‐alamu.'),
('kam', 'GEN', 35, 27, 'Na Yakovo avika kwa Isaka ĩthe wake kũvika Mamile, kũu Kiliathi‐aliva (nĩyo Eviloni), vala Avalaamu na Isaka mekalaa ũeni.'),
('kam', 'GEN', 35, 28, 'Na matukũ ma Isaka maĩ myaka ĩana na mĩongo nyanya.'),
('kam', 'GEN', 35, 29, 'Na Isaka aumwa nĩ veva, na akw’a, na oombanw’a vamwe na andũ make, e mũkũũ, na wa matukũ maingĩ: na Esau na Yakovo ana make mamũthika.'),
('kam', 'GEN', 36, 1, 'Aa nĩmo mosyaanĩo ma Esau (nĩwe Etomu).'),
('kam', 'GEN', 36, 2, 'Esau atwaa aka make eĩtunĩ ma Kanaani: Ata mwĩĩtu wa Eloni Mũititi, na Oolivama mwĩĩtu wa Anaa, mwĩĩtu wa Nziveoni Mũivi,'),
('kam', 'GEN', 36, 3, 'na Mbasemathi mwĩĩtu wa Isumaeli, mwĩĩtu‐a‐inyia wa Nevaiothi.'),
('kam', 'GEN', 36, 4, 'Na Ata amũsyaĩa Esau Elivasi; na Mbasemathi asyaa Leueli;'),
('kam', 'GEN', 36, 5, 'na Oolivama asyaa Yeusu, na Yalamu, na Kola: aa nĩo ana ma Esau, ala wasyaĩwe nthĩ ya Kanaani.'),
('kam', 'GEN', 36, 6, 'Na Esau oosa aka make, na ana make, na eĩtu make, na andũ onthe ma nyũmba yake, na indo syake, na nyamũ syake syonthe, na ũthwii wake w’onthe, ũla weyũmbanĩsye nthĩ ya Kanaani; na aenda nthĩ yĩ kũasa na mwana‐a‐inyia Yakovo.'),
('kam', 'GEN', 36, 7, 'Nũndũ ũthwii woo waingĩvie mũno ũndũ matatonya kũtũan’ya; na nthĩ ya kwĩkala kwoo ũeninĩ ndĩaatonya kũmeanĩa nũndũ wa indo syoo.'),
('kam', 'GEN', 36, 8, 'Na Esau atũaa kĩĩmanĩ kya Seili: Esau nĩwe Etomu.'),
('kam', 'GEN', 36, 9, 'Na aa nĩmo mosyaanĩo ma Esau ĩthe wa Aetomu ma kĩima kya Seili:'),
('kam', 'GEN', 36, 10, 'aa nĩmo masyĩtwa ma ana ma Esau: Elivasi mwana wa Ata mũka wa Esau, na Leueli mwana wa Mbasemathi mũka wa Esau.'),
('kam', 'GEN', 36, 11, 'Na ana ma Elivasi maĩ Temani, na Omali, na Nzevo, na Ngatamu, na Kenasĩ.'),
('kam', 'GEN', 36, 12, 'Na Timina aĩ mũka ngombo wa Elivasi mwana wa Esau; nake amũsyaĩa Elivasi Amaleki: asu nĩo ana ma Ata, mũka wa Esau.'),
('kam', 'GEN', 36, 13, 'Na aa nĩo ana ma Leueli: Naathi, na Nzela, na Samama, na Misa: asu nĩo maĩ ana ma Mbasemathi, mũka wa Esau.'),
('kam', 'GEN', 36, 14, 'Na aa maĩ ana ma Oolivama mwĩĩtu wa Anaa, mwĩĩtu wa Nziveoni, mũka wa Esau: na amũsyaĩa Esau Yeusu, na Yalamu, na Kola.'),
('kam', 'GEN', 36, 15, 'Aa nĩo anene ananĩ ma Esau: ana ma Elivasi ĩkithathi ya Esau: mũnene Temani, na mũnene Omali, na mũnene Nzevo, na mũnene Kenasi,'),
('kam', 'GEN', 36, 16, 'na mũnene Kola, na mũnene Ngatamu, na mũnene Amaleki: asu nĩo anene ala maĩ ma Elivasi, nthĩ ya Etomu; asu nĩo ana ma Ata.'),
('kam', 'GEN', 36, 17, 'Na aa nĩo ana ma Leueli, mwana wa Esau: mũnene Naathi, na mũnene Nzela, na mũnene Samama, na mũnene Misa: asu nĩo anene ala maĩ ma Leueli nthĩ ya Etomu; asu nĩ ana ma Mbasemathi, mũka wa Esau.'),
('kam', 'GEN', 36, 18, 'Na aa nĩo ana ma Oolivama, mũka wa Esau: mũnene Yeusu, na mũnene Yalamu, na mũnene Kola: asu nĩo anene ala maĩ ma Oolivama mwĩĩtu wa Anaa, mũka wa Esau.'),
('kam', 'GEN', 36, 19, 'Asu nĩo ana ma Esau, na nĩo anene moo: ũsu nĩwe Etomu.'),
('kam', 'GEN', 36, 20, 'Aa nĩo ana ma Seili Mũoli, ala matwĩe nthĩ ĩsu: Lotani na Sovali na Nziveoni na Anaa,'),
('kam', 'GEN', 36, 21, 'na Ndisoni na Eseli na Ndisani: asu nĩo anene ala ma Aoli, ana ma Seili nthĩ ya Etomu.'),
('kam', 'GEN', 36, 22, 'Na ana ma Lotani maĩ Oli na Emani; na mwĩĩtu‐a‐inyia wa Lotani aĩ Timina.'),
('kam', 'GEN', 36, 23, 'Na aa nĩo ana ma Sovali: Alivani na Manaathi na Evali, na Sevo na Onamu.'),
('kam', 'GEN', 36, 24, 'Na aa nĩo ma Nziveoni: Aia na Anaa; nĩwe Anaa ũla wonie mbuluti sya manzĩ mavyũ weũnĩ, yĩla waĩthasya mang’oi ma Nziveoni ĩthe wake.'),
('kam', 'GEN', 36, 25, 'Na aa nĩo ana ma Anaa: Ndisoni na Oolivama mwĩĩtu wa Anaa.'),
('kam', 'GEN', 36, 26, 'Na aa nĩo ana ma Ndisoni: Emitani na Esivani na Ithilani na Kelani.'),
('kam', 'GEN', 36, 27, 'Aa nĩo ana ma Eseli: Mbĩliani na Nzaavani na Akani.'),
('kam', 'GEN', 36, 28, 'Aa nĩo ana ma Ndisani: Usi na Alani.'),
('kam', 'GEN', 36, 29, 'Aa nĩo anene ma Aoli: mũnene Lotani, na mũnene Sovali, na mũnene Nziveoni, na mũnene Anaa,'),
('kam', 'GEN', 36, 30, 'na mũnene Ndisoni, na mũnene Eseli, na mũnene Ndisani: asu nĩo anene ma Aoli, kũatĩĩa anene moo nthĩ ya Seili.'),
('kam', 'GEN', 36, 31, 'Na aa nĩo asumbĩ ala masumbĩkie nthĩ ya Etomu, mbee wa kũtanasumbĩka mũsumbĩ o na wĩva ĩũlũ wa ana ma Isilaeli.'),
('kam', 'GEN', 36, 32, 'Na Mbela mwana wa Mbeoli asumbĩka Etomu; na syĩtwa ya ndũa yake yeetawa Ndiniava.'),
('kam', 'GEN', 36, 33, 'Na Mbela akw’a, na Yovavu mwana wa Nzela wa ku Mbosila asũmbĩka vandũ vake.'),
('kam', 'GEN', 36, 34, 'Na Yovavu akw’a, na Usamu wa nthĩ ya Atemani asumbĩka vandũ vake.'),
('kam', 'GEN', 36, 35, 'Na Usamu akw’a, na Aatati mwana wa Mbetati, ũla wakũnĩe Mitiani ũiĩnĩ wa Moavi, asumbĩka vandũ vake: na syĩtwa ya ndũa yake yeetwa Avithi.'),
('kam', 'GEN', 36, 36, 'Na Aatati akw’a, na Samala wa Maseleka asumbĩka vandũ vake.'),
('kam', 'GEN', 36, 37, 'Na Samala akw’a, na Sauli wa ku Leovothi vakuvĩ na ũla Ũsĩ asumbĩka vandũ vake.'),
('kam', 'GEN', 36, 38, 'Na Sauli akw’a, na Mbaali‐aanani mwana wa Akivoli asumbĩka vandũ vake.'),
('kam', 'GEN', 36, 39, 'Na Mbaali‐aanani mwana wa Akivoli akw’a, na Aatali asumbĩka vandũ vake: na syĩtwa ya ndũa yake yeetawa Vau, na syĩtwa ya mũka eetawa Meetaveli, mwĩĩtu wa Matileti, mwĩĩtu wa Menzaavu.'),
('kam', 'GEN', 36, 40, 'Na aa nĩo masyĩtwa ma anene ala maĩ ma Esau, kũatĩĩa mĩvĩa yoo, kwĩanana na kũndũ kwoo, na masyĩtwa moo: mũnene Timina, na mũnene Aliva, na mũnene Yethethi,'),
('kam', 'GEN', 36, 41, 'na mũnene Oolivama, na mũnene Ela, na mũnene Vinoni,'),
('kam', 'GEN', 36, 42, 'na mũnene Kenasi, na mũnene Temani, na mũnene Mivisalu,'),
('kam', 'GEN', 36, 43, 'na mũnene Makitieli, na mũnene Ilami: asu nĩo anene ma Etomu, kwĩanana na mawĩkalo moo nthĩ ya ng’ũndũ yoo. Ũsũ nĩwe Esau, ĩthe wa Aetomu.'),
('kam', 'GEN', 37, 1, 'Na Yakovo atũaa nthĩ ĩla ĩthe wake wekalaa ũeni, nthĩ ya Kanaani.'),
('kam', 'GEN', 37, 2, 'Mosyaanĩo ma Yakovo nĩmo aa. Yosevu, e wa myaka ĩkũmi na mũonza, aĩthasya ndĩthya ya mbũi na malondu vamwe na ana‐a‐ĩthe; na aĩ kĩmwana vamwe na ana ma Mbila, na vamwe na ana ma Nziliva, aka ma ĩthe: na Yosevu atwaĩa ĩthe ũvoo woo mũthũku.'),
('kam', 'GEN', 37, 3, 'Na ĩndĩ Isilaeli amwendaa Yosevu kwĩ ana make onthe, nũndũ nĩwe mwana wa ũkũu wake: na amũseũvĩsya kanzũ wĩ langi wa mĩthemba mingĩ.'),
('kam', 'GEN', 37, 4, 'Na ana‐a‐ĩthe moona kana ĩthe woo nũmwendete kwĩ ana‐a‐ĩthe onthe; nao nĩmamũmenaa, o na maiaatonya kũneena nake na mũuo.'),
('kam', 'GEN', 37, 5, 'Na Yosevu aota ndoto, na atavya ana‐a‐ĩthe: nao mongela kũmũmena.'),
('kam', 'GEN', 37, 6, 'Na amea, Nĩngũmwĩsũva, ĩthukĩĩsyei ndoto ĩno nĩotie:'),
('kam', 'GEN', 37, 7, 'nũndu, sisya, ĩthyĩ twĩthĩiwe tũkyova syove sya ngetha mũũndanĩ, nakyo kyove kyakwa kyookĩla na ĩngĩ kyaũngama kĩlũngele; na, sisya, syove syenyu syathyũlũlũka, na syeekunamĩsya kyove kyakwa.'),
('kam', 'GEN', 37, 8, 'Na ana‐a‐ĩthe mamwĩa, Ai nĩ w’o ũkatũsumbĩka? Kana ũu nĩ w’o ũkeethĩwa na ũsumbĩko ĩũlũ waitũ? Nao mongela mũno kũmũmena nũndũ wa ndoto syake, na nũndũ wa ndeto syake.'),
('kam', 'GEN', 37, 9, 'Na aota ndoto ĩngĩ, na atavya ana‐a‐ĩthe, na amea, Sisya, nĩnĩotie ndoto ĩngĩ; na, sisya, syũa na mwei na ndata ĩkũmi na ĩmwe syeengunamĩsya.'),
('kam', 'GEN', 37, 10, 'Na atavya ĩthe, na ana‐a‐ĩthe; na ĩthe amũkan’ya, na amwĩa, Ndoto ĩsu nĩ myaũ ĩla ũotie? Nĩ w’o tũkooka nyie na mwenyu na ana‐a‐au tũkwĩkunamĩsye kũvika nthĩ?'),
('kam', 'GEN', 37, 11, 'Na ana‐a‐ĩthe mamwĩw’ĩa kĩwĩu; ĩndĩ ĩthe aia ĩla ndeto ngoonĩ.'),
('kam', 'GEN', 37, 12, 'Na ana‐a‐ĩthe maenda Sekemu kũĩthya ndĩthya ya mbũi na malondu ya ĩthe woo.'),
('kam', 'GEN', 37, 13, 'Na Isilaeli amwĩa Yosevu, Ana‐a‐au matikũĩthya ndĩthya ya mbũi na malondu Sekemu? Ũka, nĩngũũtũma vala maĩ. Na amwĩa, Nĩ vaa.'),
('kam', 'GEN', 37, 14, 'Nake amwĩa, Enda yu, ũsisye kana ana‐a‐au nĩ aseo, na ndĩthya kana nĩ nzeo; na ũindetee ũvoo. Na ĩndĩ amũtũma kuma mwandanĩ wa Eviloni, nake avika Sekemu.'),
('kam', 'GEN', 37, 15, 'Na mũndũ ũmwe amwĩthĩa, na, sisya, angangaa weũnĩ: na ũla mũndũ amũkũlya, akyasya, Wĩmantha kĩ?'),
('kam', 'GEN', 37, 16, 'Na asũngĩa, Nĩmanthaa ana‐a‐asa makwa: nĩngũkwĩsũva, ndavya vala meũĩthya.'),
('kam', 'GEN', 37, 17, 'Na ũla mũndũ amwĩa, Nĩmaumie vaa; nũndũ nĩneewie makyasya, Tũthii Ndothani. Na Yosevu amaatĩĩa ana‐a‐ĩthe na amethĩa Ndothani.'),
('kam', 'GEN', 37, 18, 'Nao mamwona e kũasa, na mbee wa atanamathengeea, mamũsũanĩĩa mamũae.'),
('kam', 'GEN', 37, 19, 'Na maneenan’ya ene kwa ene, Sisya, ũla mũoti nĩwũkĩte.'),
('kam', 'GEN', 37, 20, 'Ũkai ĩndĩ, tũmũae, na tũimwĩkya nthĩnĩ wa ĩima yĩmwe, naitũ tũkasya, Nũlĩkĩte nĩ nyamũ mbai: na ĩndĩ tũkasisya ũndũ ndoto syake ikethĩwa.'),
('kam', 'GEN', 37, 21, 'Na Leuveni eew’a ũu, na amũtangĩĩa kuma mokonĩ moo, na amea, Tũikamũae.'),
('kam', 'GEN', 37, 22, 'Na Leuveni amea, Mũtikete nthakame; mwĩkyei ĩimanĩ yĩĩ yĩ vaa weũnĩ, ĩndĩ mũikamwilĩĩle kw’oko: nĩ kana amũtangĩĩe kuma kw’okonĩ kwoo, amũtũnge kwa ĩthe.'),
('kam', 'GEN', 37, 23, 'Na kweethĩwa, Yosevu avika kũla ana‐a‐ĩthe maĩ, mamumya Yosevu ũla kanzũ wake, kanzũ wa langi wa mĩthemba mingĩ ũla wekĩe;'),
('kam', 'GEN', 37, 24, 'na mamwosa, na mamwĩkya ĩimanĩ: na ĩima yaĩ ĩthei, yĩtyaĩ na manzĩ.'),
('kam', 'GEN', 37, 25, 'Na mekala nthĩ maye lĩu; na mookĩlya metho na moona, na, sisya, kyalo kya Aisumaeli maumĩte Ngileati, na ngamĩle syoo ikuĩte mĩtĩ ĩnyungaa nesa na seli na manemane, maendete matheeetye Misili.'),
('kam', 'GEN', 37, 26, 'Na Yuta amea ana‐a‐ĩthe, Ve ũtandĩthyo mwaũ twooaa mwana‐a‐asa na kũvitha nthakame yake?'),
('kam', 'GEN', 37, 27, 'Ũkai, tũmũthoosye we kwa Aisumaeli, o na kw’oko kwitũ kũtikethĩwe ĩũlũ wake; nũndũ nĩ mwana‐a‐asa, mwĩĩ witũ. Na ana‐a‐ĩthe mamwĩw’a.'),
('kam', 'GEN', 37, 28, 'Na kwavĩta Amitiani, atandĩthya; na mamũkusya na mamumya Yosevu ĩimanĩ, na mamũthoosya Yosevu kwa Aisumaeli ilungu mĩongo ĩlĩ sya vetha. Nao mamũvikya Yosevu Misili.'),
('kam', 'GEN', 37, 29, 'Na Leuveni asyoka ĩimanĩ; na, sisya, Yosevu ndaĩ ĩimanĩ; na atembũa ngũa syake.'),
('kam', 'GEN', 37, 30, 'Na asyoka kwa ana‐a‐ĩthe, na amea, Mwana nde vo; nakwa, nĩela va?'),
('kam', 'GEN', 37, 31, 'Na moosa kanzũ wa Yosevu, na mooaa nthenge, na mainda kanzũ nthakamenĩ;'),
('kam', 'GEN', 37, 32, 'na matwaa kanzũ wa langi wa mĩthemba mingĩ, mamũetee ĩthe woo, na mamwĩa, Tũnawĩthĩie ũũ: manya ĩndĩ kana nĩ kanzũ wa mwana waku kana ti w’o.'),
('kam', 'GEN', 37, 33, 'Na oomanya, na asya, Nĩ kanzũ wa mwana wakwa; nũlĩkĩte nĩ nyamũ mbai; vate nzĩka Yosevu nũtilangĩtwe ilungu.'),
('kam', 'GEN', 37, 34, 'Na Yakovo atembũa ngũa syake, na eevotoa makunia kĩnyunyu, na amũĩĩa mwana wake matukũ maingĩ.'),
('kam', 'GEN', 37, 35, 'Na ana make onthe na eĩtu make onthe mookĩla mamũkiakisye; ĩndĩ we alea kũkiakiĩka; na asya, Nũndũ ngamũtheeea mwana wakwa Seoli ngĩmũĩa. Na ĩthe nĩwamũĩĩaa.'),
('kam', 'GEN', 37, 36, 'Na Amitiani mamũthoosya Misili kwa Votivali, mũnene ũmwe wa kwa Valao, kavuteni wa nguthu ya asũvĩi.'),
('kam', 'GEN', 38, 1, 'Na kweethĩwa ĩvinda yĩu, Yuta atheea kuma kwa ana‐a‐ĩthe, aathũkĩla kwa Mũatulamu ũmwe, ũla syĩtwa yake wetawa Iila.'),
('kam', 'GEN', 38, 2, 'Na Yuta oona mwĩĩtu kũu wa Mũkanaani ũmwe ũla syĩtwa yake wetawa Suua; nake amũtwaa, na alika kwake.'),
('kam', 'GEN', 38, 3, 'Nake aya ĩvu, na asyaa mwana; na amwĩta syĩtwa yake Eeli.'),
('kam', 'GEN', 38, 4, 'Na aya ĩvu ĩngĩ, na asyaa mwana; na amwĩta syĩtwa yake Onani.'),
('kam', 'GEN', 38, 5, 'Na ongela ũsyaa mwana ũngĩ, na amwĩta syĩtwa yake Siela: na akĩmũsyaa, Yuta aĩ Kesivu.'),
('kam', 'GEN', 38, 6, 'Na Yuta atwaĩa Eeli ĩkithathi yake mũka, na syĩtwa yake eetawa Tamali.'),
('kam', 'GEN', 38, 7, 'Nake Eeli, ĩkithathi ya Yuta, aĩ mwathe methonĩ ma Yeova; na Yeova amũaa.'),
('kam', 'GEN', 38, 8, 'Na Yuta amwĩa Onani, Lika kwa mũka wa mwana‐a‐mwenyu, ũmwĩke ũndũ waĩle kwĩkawa kwa mwana‐a‐inyia wa mũũme, na ũkimũũngamĩsya mwana‐a‐mwenyu ũsyao.'),
('kam', 'GEN', 38, 9, 'Na Onani amanya kana ũsyao ndũkethĩwa wake; na kweethĩwa, alika kwa mũka wa mwana‐a‐inyia, eta nthĩ, ndakanenge mwana‐a‐inyia ũsyao.'),
('kam', 'GEN', 38, 10, 'Na ũndũ ũla wekie waĩ ũthũku methonĩ ma Yeova: na amũaa o nake.'),
('kam', 'GEN', 38, 11, 'Na ĩndĩ Yuta amwĩa Tamali mũka‐a‐mwana, Ĩkala wĩ ndiwa nyũmbanĩ ya au, kũvika yĩla Siela mwana wakwa ũkeana; nũndũ aisye, Nake ndakese ũkw’a, ta ana‐a‐inyia. Na Tamali athi ekala nyũmbanĩ kwa ĩthe wake.'),
('kam', 'GEN', 38, 12, 'Na matukũ amwe mathela mwĩĩtu wa Suua, mũka wa Yuta, akw’a; na Yuta akiakiw’a, na ambata kũvika Timina kwa atili ma w’ĩa wa malondu make, we na mũnyanyae Iila ũla Mũatulamu.'),
('kam', 'GEN', 38, 13, 'Na Tamali atavw’a, kũineenwa, Sisya, ĩthe wa mũemeu nũkwambata Timina kũtila malondu make w’ĩa.'),
('kam', 'GEN', 38, 14, 'Nake aumya ngũa sya ũtiwa wake, na eevw’ĩka suka wake mũvũthũ, na eekunĩkĩlya, na ekala mbingĩlonĩ ya Enaimu, ĩla yĩ nzĩanĩ ya Timina; nũndũ oonie kana Siela aĩ aneana, nake ndaanenganwe kwake ethĩwe mũka.'),
('kam', 'GEN', 38, 15, 'Yila Yuta wamwonie, atalĩlya kana nĩ ĩlwaya; nũndũ eevw’ĩkĩte ũthyũ.'),
('kam', 'GEN', 38, 16, 'Na aathũkĩla vala ũĩ kuma nzĩanĩ, na amwĩa, Nĩngũkwĩsũva, ũka, nĩlike kwaku: nũndũ ndaamanya kana nĩ mũka‐a‐mwana. Na akũlya, ũkanenga kyaũ, nĩ kana ũtonye ũlika kwakwa?'),
('kam', 'GEN', 38, 17, 'Nake asũngĩa, Ngakũetee katena ka mbũi kuma ĩĩthyanĩ. Na akũlya, Ũkanenga ngwatĩlĩlyo mũvaka wĩete?'),
('kam', 'GEN', 38, 18, 'Nake akũlya, Nĩkũnenge ngwatĩlĩlyo myaũ? Na asũngĩa, Ngome yaku ya ũvana ũsiĩlo, na ũlii waku, na ndata yaku yĩ kw’okonĩ kwaku. Na amũnenga, na alika kwake, nake aya ĩvu nũndũ wake.'),
('kam', 'GEN', 38, 19, 'Na ookĩla, athi, na aumya suka wake mũvũthũ, na eekĩa ngũa sya ũtiwa wake.'),
('kam', 'GEN', 38, 20, 'Na Yuta atwaa katena ka mbũi na kw’oko kwa mũnyanyae Mũatulamu, nĩ kana ose ngwatĩlĩlyo kw’okonĩ kwa ũla mũndũ mũka: ĩndĩ ndaamwĩthĩa.'),
('kam', 'GEN', 38, 21, 'Nĩvo ĩndĩ wamakũlilye andũ ma vandũ vake, akyasya, Yĩĩva ĩlwaya, yĩla yaĩ Enaimu ũtee wa nzĩa? Nao masũngĩa, Vaa vatyaaĩthĩwa ĩlwaya.'),
('kam', 'GEN', 38, 22, 'Na asyoka kwa Yuta, na amwĩa, Ndineeyona; na andũ ma vandũ vau nao masya, Vaa vatyaaĩthĩwa ĩlwaya.'),
('kam', 'GEN', 38, 23, 'Na Yuta asya, Nĩeyosee, tũikese ũsonokw’a. Sisya, nĩtwaĩte katena kaa, o na ndũneeyona.'),
('kam', 'GEN', 38, 24, 'Na kweethĩwa myei ĩtatu yathela, Yuta atavw’a, kũineenwa, Tamali mũkawa‐mwana waku nĩwekie ũmalwaya; na mũndũ ũngi, sisya, e na ĩvu kwondũ wa ũmalwaya. Na Yuta asya, Mumaalyei, avĩvw’e.'),
('kam', 'GEN', 38, 25, 'Aumaalw’a, atũmana kwa ĩthe wa mũũme, akyasya, Kwa mũndũ mwene ii, nyie nĩ ĩvu: na asya, Nĩngũkwĩsũva, manya, ii nĩ syaũ, ngome ya ũvana ũsiĩlo, na ndii, na ndata.'),
('kam', 'GEN', 38, 26, 'Na Yuta asyĩtĩkĩla, na asya, Nĩwe mũlũngalu kwĩ nyie, nĩkwĩthĩwa ndyaamũnenga Siela mwana wakwa. Nake ndaamũmanya ĩngĩ nongi.'),
('kam', 'GEN', 38, 27, 'Na kweethĩwa ĩvinda ya kwaũnya kwake, sisya, mavatha maĩ ĩvunĩ yake.'),
('kam', 'GEN', 38, 28, 'Na kweethĩwa, akĩsyaa, kamwe kaumĩlya kw’oko: na mwĩsikya oosa ũlii mũtune na ooveea kw’oko kwako, akyasya, Kaa nĩko kauma mbee.'),
('kam', 'GEN', 38, 29, 'Na kweethĩwa, kakĩtũnga kw’oko kwako, sisya, mwana‐a‐inyia auma: na asya, Nĩkĩ weevũthũĩa? Kwondũ wa ũu syĩtwa yako keetwa Velesi.'),
('kam', 'GEN', 38, 30, 'Na ĩtina mwana‐a‐inyia auma, ũsu waĩ na ũlii mũtune kw’okonĩ: na syĩtwa yako keetwa Nzela.'),
('kam', 'GEN', 39, 1, 'Na Yosevu atheew’a Misili; na Votivali, mũnene ũmwe wa kwa Valao, kavuteni wa nguthu ya asũvĩi, Mũmisili, amũthooa kw’okonĩ kwa Aisumaeli, ala mamũtheeisye kũu.'),
('kam', 'GEN', 39, 2, 'Na Yeova aĩ vamwe na Yosevu, nake aĩ mũndũ mũathime; na aĩ nyũmbanĩ ya vwana wake Mũmisili.'),
('kam', 'GEN', 39, 3, 'Na vwana wake oona kana Yeova aĩ vamwe nake, na w’onthe ũla wekaa Yeova nĩwaĩlasya kw’okonĩ kwake.'),
('kam', 'GEN', 39, 4, 'Na Yosevu endeesya methonĩ make, nake amũthũkũma: na amũtw’a mũsyaĩĩsya ĩũlũ wa nyũmba yake, na kyonthe kĩla waĩ nakyo aia kw’okonĩ kwake.'),
('kam', 'GEN', 39, 5, 'Na kweethĩwa kuma ĩvinda yĩla wamũtwie mũsyaĩĩsya nyũmbanĩ yake, na ĩũlũ wa kyonthe kĩla waĩ nakyo, Yeova aathima nyũmba ya Mũmisili kwondũ wa Yosevu; na ũathimo wa Yeova waĩ ĩũlũ wa kyonthe kĩla waĩ nakyo, nyũmbanĩ na mũũndanĩ.'),
('kam', 'GEN', 39, 6, 'Na kyonthe kĩla waĩ nakyo aia kw’okonĩ kwa Yosevu; o na ndaamanya kĩndũ o na kĩva kĩla kyaĩ nake, ate o lĩu ũla waĩsaa. Na Yosevu aĩ mwanake, na aĩ na wũmbe mũseo.'),
('kam', 'GEN', 39, 7, 'Na kweethĩwa ĩtina wa maũndũ asu, mũka wa vwana wake amũtemethya Yosevu metho; na amwĩa, Koma nakwa.'),
('kam', 'GEN', 39, 8, 'Ĩndĩ alea, na amwĩa mũka wa vwana wake, Sisya, vwana wakwa ndesĩ kĩla nĩ nakyo nyũmbanĩ, na aiĩte kyonthe kĩla wĩ nakyo kw’okonĩ kwakwa:'),
('kam', 'GEN', 39, 9, 'nake ti mũnene nyũmbanĩ ĩno kwĩ nyie; o na ndaambata kĩndũ o na kĩva ate o we, nĩkwĩthĩwa, we, wĩ mũka wake: ndonya ata kwĩka ũthũku ũsu mũnene, na kũmũvĩtanĩsya Ngai?'),
('kam', 'GEN', 39, 10, 'Na kweethĩwa, akĩneena na Yosevu mũthenya na mũthenya, ndaamwĩthukĩĩsya, akome nake, kana kwĩthĩwa nake.'),
('kam', 'GEN', 39, 11, 'Na kweethĩwa ĩvinda o ta yĩu, avota nyũmbanĩ atethye wĩa wake; na kũtyaĩ ũmwe wa aũme ma nyũmba ku nthĩnĩ.'),
('kam', 'GEN', 39, 12, 'Na amũkwata ngũa yake, akĩmwĩa, Koma nakwa: na atia ngũa yake kw’okonĩ kwake, na akuthũka athi nza.'),
('kam', 'GEN', 39, 13, 'Na kweethĩwa, yĩla wonie nĩwatia ngũa yake kw’okonĩ kwake, na akuthũka, athi nza,'),
('kam', 'GEN', 39, 14, 'eetana kwa aũme ma nyũmba yake, na aneena nao, akĩmea, Sisyai, nũtũetee Mũevelania atũvũĩae ngũĩ: alikile kwakwa akome nakwa, nakwa nakaya na wasya mũnene:'),
('kam', 'GEN', 39, 15, 'na kweethĩwa yĩla wewie kana nĩnookĩlya wasya na kũkaya, atia ngũa yake kwakwa, na akuthũka, athi nza.'),
('kam', 'GEN', 39, 16, 'Na aia ngũa yake kwake, kũvika yĩla vwana wake wenũkie.'),
('kam', 'GEN', 39, 17, 'Na aneena nake kwĩanana na ndeto ii, akĩmwĩa, Mũthũkũmi Mũevelania, ũla watũetee, avotie kwakwa ambũĩe ngũĩ:'),
('kam', 'GEN', 39, 18, 'na kweethĩwa, ngyũkĩlya wasya na kũkaya, atia ngũa yake kwakwa, na akuthũka athi nza.'),
('kam', 'GEN', 39, 19, 'Na kweethĩwa, vwana wake eew’a ndeto sya mũka, ila wamũtavisye, akĩmwĩa, Mũthũkũmi waku nũmbĩkie ũndũ ũilyĩ ũu; ũthilĩku wake wookĩla.'),
('kam', 'GEN', 39, 20, 'Na vwana wa Yosevu amwosa, amwĩkĩa kolokolonĩ, vandũ vala ovwa ma mũsumbĩ mooveawa: nake ekala vau kolokolonĩ.'),
('kam', 'GEN', 39, 21, 'Ĩndĩ Yeova aĩ vamwe na Yosevu, na amwĩka nesa, na amũnenga kwona ũseo methonĩ ma mũsũvĩi wa kolokolo.'),
('kam', 'GEN', 39, 22, 'Na mũsũvĩi wa kolokolo aia kw’okonĩ kwa Yosevu ovwa onthe ala maĩ kolokolonĩ; na ũndũ o na wĩva w’onthe ũla meekaa vo, nĩwe waĩ mwĩkĩthya waw’o.'),
('kam', 'GEN', 39, 23, 'Mũsũvĩi wa kolokolo ndaasisya ũndũ o na wĩva ũla waĩ kw’okonĩ kwake, nĩkwĩthĩwa Yeova aĩ vamwe nake; na ũla wekie Yeova nĩwaĩlasya.'),
('kam', 'GEN', 40, 1, 'Na kweethĩwa ĩtina wa maũndũ asu, mũnengani wa mbinyu wa mũsumbĩ wa Misili na mũui wake wa mĩkate mamwĩw’ĩthya woo, mwĩaĩi woo, mũsumbĩ wa Misili.'),
('kam', 'GEN', 40, 2, 'Na Valao amathilĩkĩla ala anene elĩ ma kwake, mũnene wa anengani ma mbinyu, na mũnene wa aui.'),
('kam', 'GEN', 40, 3, 'Nake amekĩa ũsũvĩonĩ nyũmbanĩ ya kavuteni wa nguthu ya asũvĩi, nthĩnĩ wa kolokolo, vala Yosevu wovewe.'),
('kam', 'GEN', 40, 4, 'Na kavuteni wa asũvĩi amwia Yosevu ĩũlũ wa asu, nake amathũkũma: nao mekala ũsũvĩonĩ ĩvinda.'),
('kam', 'GEN', 40, 5, 'Nao maota ndoto me elĩ, kĩla mũndũ ndoto yake, ũtukũ o ũmwe, kĩla mũndũ kwĩanana na ũalyũlo wa ndoto yake, mũnengani wa mbinyu na mũui wa mũsumbĩ wa Misili, ala mooviwe kolokolonĩ.'),
('kam', 'GEN', 40, 6, 'Na Yosevu athĩ vala maĩ kĩoko, na amona, na, sisya, maĩ na woo.'),
('kam', 'GEN', 40, 7, 'Nake akũlya anene ma kwa Valao ala maĩ vamwe nake ũsũvĩonĩ nyũmbanĩ ya vwana wake, akyasya, Nĩkĩ mũkwoneka mwĩ na woo ũmũnthĩ?'),
('kam', 'GEN', 40, 8, 'Na mamũsũngĩa, Nĩtũotie ndoto, na vai ũmwe ũtonya kũmĩalyũla. Na Yosevu amea, Moalyũlo ti ma Ngai? Nĩngũmwĩsũva, ndavyai syo.'),
('kam', 'GEN', 40, 9, 'Na mũnenganĩ mũnene wa mbinyu atavya Yosevu ndoto yake, na amwĩa, Ndotonĩ yakwa, sisya, mũsavivũ waĩ mbee wakwa;'),
('kam', 'GEN', 40, 10, 'na mũsavivũnĩ kwaĩ mbonge itatũ: naw’o wailyĩ ta ũũete wenze, na malaa maw’o malaũka; na ĩtũngo syaw’o syasyaa nzavivũ mbĩu:'),
('kam', 'GEN', 40, 11, 'na kĩkombe kya Valao kyaĩ kw’okonĩ kwakwa; nakwa noosa nzavivũ, navivĩĩa kĩkombenĩ kya Valao, nakwa nanengane kĩkombe kw’okonĩ kwa Valao.'),
('kam', 'GEN', 40, 12, 'Na Yosevu amwĩa, Ũalyũlo wayo nĩ ũũ: ila mbonge itatũ nĩ matukũ atatũ;'),
('kam', 'GEN', 40, 13, 'o ĩtina wa matukũ atatũ Valao akookĩlya mũtwe waku, na akakũtũnga wĩanĩ waku: naku ũkanengane kĩkombe kya Valao kw’okonĩ kwake, o tondũ weekaa mbee yĩla waĩ mũnengani wake wa mbinyu.'),
('kam', 'GEN', 40, 14, 'Ĩndĩ nĩngũkwĩsũva, ũkandilikane nyie yĩla kwaku kwĩĩthĩwa kũseo, ũkambĩke nesa, na ũingweta kwa Valao, na kũnumya nyũmbanĩ ĩno:'),
('kam', 'GEN', 40, 15, 'nũndũ nĩ w’o noyiwe kuma nthĩ ya Aevelania: o na kũũ ndyaaĩka ũndũ nĩ kana nĩkĩwe kasũmbanĩ ke nthĩnĩ wa nthĩ.'),
('kam', 'GEN', 40, 16, 'Mũui mũnene oona kana ũalyũlo waĩ mũseo, amwĩa Yosevu, Nakwa naĩ ndotonĩ yakwa, na sisya, ikavũ itatũ sya imũtũ nzaũ syĩĩ mũtwenĩ wakwa:'),
('kam', 'GEN', 40, 17, 'na kĩkavũnĩ kĩla kĩĩ ĩũlũ kĩĩ lĩu mũue wa mĩthemba yonthe kwondũ wa Valao; na nyũnyi syaĩĩa kĩkavũnĩ ĩũlũ wa mũtwe wakwa.'),
('kam', 'GEN', 40, 18, 'Na Yosevu asũngĩa na asya, Ũalyũlo wayo nĩ ũũ: ila ikavũ itatũ nĩ matukũ atatũ;'),
('kam', 'GEN', 40, 19, 'o ĩtina wa matukũ asu atatũ Valao akookĩlya mũtwe waku kuma kwaku, na akakũsũsya mũtĩnĩ; na nyũnyi ikaya nyama syaku mwĩĩnĩ waku.'),
('kam', 'GEN', 40, 20, 'Na kweethĩwa mũthenya wa katatũ, mũthenya ũla waĩ wa kũsyawa kwa Valao, amavokea athũkũmi make onthe mboka: na ookĩlya mũtwe wa mũnengani mũnene wa mbinyu na mũtwe wa mũui mũnene katĩ wa athũkũmi make.'),
('kam', 'GEN', 40, 21, 'Na atũnga mũnengani mũnene wa mbinyu wĩanĩ wake wa kũnengane mbinyu; nake anengane kĩkombe kw’okonĩ kwa Valao:'),
('kam', 'GEN', 40, 22, 'ĩndĩ asũsya mũui mũnene: o tondũ Yosevu wamaalyũlĩle.'),
('kam', 'GEN', 40, 23, 'Ĩndĩ mũnengani mũnene wa mbinyu ndaamũlilikana Yosevu, ĩndĩ oolwa nĩwe.'),
('kam', 'GEN', 41, 1, 'Na kweethĩwa mũminũkĩlyo wa myaka ĩlĩ mĩima, Valao aota: na, sisya, aũngama ũtee wa ũsĩ.'),
('kam', 'GEN', 41, 2, 'Na, sisya, syambata kuma ũsĩnĩ ng’ombe nga mũonza, nzeo na nou; na syeeĩthya kĩtothyanĩ.'),
('kam', 'GEN', 41, 3, 'Na, sisya, ng’ombe nga ingĩ mũonza syambata ĩtina wasyo kuma ũsĩnĩ, ite nzeo na mosu, na syaũngama ũtee wa ng’ombe ila ingĩ ũtee wa ũsĩ.'),
('kam', 'GEN', 41, 4, 'Na ila ng’ombe ite nzeo na mosu syaya ila ng’ombe mũonza nzeo na nou. Na ĩndĩ Valao aamũka.'),
('kam', 'GEN', 41, 5, 'Na akoma na aota ĩngĩ ya kelĩ: na, sisya, iia mũonza sya nganũ syamea mũtĩnĩ ũmwe, nene na nzeo.'),
('kam', 'GEN', 41, 6, 'Na, sisya, ila mũonza ntheke, syũmanĩlĩtw’e nĩ kĩseve kyumĩte wumĩlonĩ wa syũa, syamea ĩtina wasyo.'),
('kam', 'GEN', 41, 7, 'Na iia ntheke syamelya ila iia mũonza nene na nima. Na Valao aamũka, na, sisya, yaĩ ndoto.'),
('kam', 'GEN', 41, 8, 'Na kweethĩwa kwakya veva wake nĩwaũũyaa; na atũmana eki onthe ma syama ma Misili, na andũ oĩ onthe mayo: na Valao amatavya ndoto yake; ĩndĩ kũtyaĩ ũmwe ũla waĩ atonya kũmũalyũlĩla Valao syo.'),
('kam', 'GEN', 41, 9, 'Na ĩndĩ ũla mũnengani mũnene wa mbinyu aneena na Valao, akĩmwĩa, Mũnthĩ ũũ nĩngũlilikana mavĩtyo makwa:'),
('kam', 'GEN', 41, 10, 'Valao amathilĩkĩle athũkũmi make, na ambĩkĩa ũsũvĩonĩ nyũmbanĩ ya kavuteni wa nguthu ya asũvĩi, nyie na mũui mũnene:'),
('kam', 'GEN', 41, 11, 'na twaota ndoto ũtukũ o ũmwe, nyie nake; twaota kĩla mũndũ o ta ũalyũlo wa ndoto yake.'),
('kam', 'GEN', 41, 12, 'Na vo vamwe naitũ vaĩ mwanake, Mũevelania, mũthũkũmi wa kavuteni wa nguthu ya asũvĩi; na twamũtavya, nake atũalyũlĩla ila ndoto sitũ; amũalyũlĩla kĩla mũndũ kwĩanana na ndoto yake.'),
('kam', 'GEN', 41, 13, 'Na kweethĩwa, o tondũ watũalyũlĩla, nĩw’o kweethĩiwe; nyie andũnga wĩanĩ wakwa, na ũsu amũsũsya.'),
('kam', 'GEN', 41, 14, 'Nĩvo Valao watũmanie amwĩta Yosevu, na mamũete na mĩtũkĩ kuma kasũmbanĩ ke nthĩnĩ wa nthĩ: nake eeyenza, na eekĩa ngũa ingĩ, na avota kwa Valao.'),
('kam', 'GEN', 41, 15, 'Na Valao amwĩa Yosevu, Nĩnĩotie ndoto, o na vai ũmwe ũla ũtonya kũmĩalyũla: nakwa nĩneew’a kũineenwa ũndũ waku, yĩla ũkwĩw’a ndoto nũtonya kũmĩalyũla.'),
('kam', 'GEN', 41, 16, 'Na Yosevu amũsũngĩa Valao, akĩmwĩa, Ti nthĩnĩ wakwa: Ngai akamũnenga Valao ũsũngĩo wa mũuo.'),
('kam', 'GEN', 41, 17, 'Na Valao amwĩa Yosevu, Ndotonĩ yakwa, sĩsya, naũngyĩ ũtee wa ũsĩ:'),
('kam', 'GEN', 41, 18, 'na, sisya, kwambata kuma ũsĩnĩ ng’ombe nga mũonza, nou na nzeo: na syeeĩthya kĩtothyanĩ:'),
('kam', 'GEN', 41, 19, 'na, sisya, ng’ombe nga ingĩ mũonza syambata ĩtina wasyo, mbonzu na ite nzeo nongi na mosu, o na kũthũka ndyaaona ta isu o na ĩndĩĩ, nthĩ yonthe ya Misili:'),
('kam', 'GEN', 41, 20, 'na ng’ombe ila mosu na ite nzeo syaya ila ng’ombe nou sya mbee:'),
('kam', 'GEN', 41, 21, 'na syamina kwiya, kũiaamanyĩka kana niĩte; ĩndĩ syeethĩwa ite nzeo, o ta mbee. Na ĩndĩ naamũka.'),
('kam', 'GEN', 41, 22, 'Na noona ndotonĩ yakwa, na, sisya, iia mũonza, syamea mũtĩnĩ ũmwe, nima na nzeo:'),
('kam', 'GEN', 41, 23, 'na, sisya, iia mũonza, mbovu, na ntheke, na syũmanĩlĩtw’e nĩ kĩseve kyumĩte wumĩlonĩ wa syũa, syamea ĩtina wasyo:'),
('kam', 'GEN', 41, 24, 'na iia ntheke syamelya iia mũonza nzeo: na ĩndĩ natavya eki ma syama; ĩndĩ kũtyaĩ ũmwe ũla waĩ atonya kũmanyĩthya.'),
('kam', 'GEN', 41, 25, 'Na Yosevu amwĩa Valao, Ndoto ya Valao nĩ ĩmwe: ũndũ Ngai ũkilĩlye kwĩka nĩwamanyĩthya Valao.'),
('kam', 'GEN', 41, 26, 'Ng’ombe mũonza nzeo nĩ myaka mũonza; na iia mũonza nzeo nĩ myaka mũonza: ndoto nĩ ĩmwe.'),
('kam', 'GEN', 41, 27, 'Na ng’ombe mũonza mosu na ite nzeo ila syambatie ĩtina wasyo nĩ myaka mũonza, nasyo iia mũonza nthei syũmanĩlĩtw’e nĩ kĩseve kyumĩte wumĩlonĩ wa syũa; isu ikeethĩwa myaka mũonza ya yũa.'),
('kam', 'GEN', 41, 28, 'Ũu nĩw’o ũndũ ũla namũtavya Valao: ũla Ngai ũkilĩlye kwĩka nĩwamwon’ya Valao.'),
('kam', 'GEN', 41, 29, 'Sisya, myaka mũonza nĩyũkĩte ya lĩu mwingĩ mũno katĩ wa nthĩ yonthe ya Misili:'),
('kam', 'GEN', 41, 30, 'na ĩtina wayo ĩkaumĩla myaka mũonza ya yũa; na lĩu mwingĩ w’onthe ũkoola nthĩ ya Misili; na yũa yĩkamina nthĩ;'),
('kam', 'GEN', 41, 31, 'na ũla lĩu mwingĩ ndũkamanyĩka nthĩ nũndũ wa yĩla yũa yĩatĩĩe; nũndũ yĩkeethĩwa yĩ ĩnene mũno.'),
('kam', 'GEN', 41, 32, 'Na nĩkwĩthĩwa ndoto ĩsu ĩmũkĩe Valao kelĩ, nĩ kwa kwĩthĩwa ũndũ ũsu ũlũlũmĩlwe nĩ Ngai, na Ngai akeanĩsya mĩtũkĩ.'),
('kam', 'GEN', 41, 33, 'Na ĩndĩ yuyu Valao namanthe mũndũ wĩ na kĩlĩko na ũĩ, na kũmwia ĩũlũ wa nthĩ ya Misili.'),
('kam', 'GEN', 41, 34, 'Valao nĩeke ũu, na ĩndĩ aie asyaĩĩsya ĩũlũ wa nthĩ, na kĩlungu kya katano kya nthĩ ya Misili kyoswe myakanĩ mũonza ya lĩu mwingĩ.'),
('kam', 'GEN', 41, 35, 'Na nĩmomban’ye lĩu w’onthe wa myaka ĩsu mĩseo ĩla yũkĩte, na maie nganũ kw’okonĩ kwa Valao kwondũ wa kya ũya kya i ndũa, nao mosũvĩe.'),
('kam', 'GEN', 41, 36, 'Na lĩu ũsu ũkeethĩwa wa kwĩanĩsya nthĩ ũndũ wa myaka mũonza ya yũa, ĩla ĩkethĩwa nthĩ ya Misili; nĩ kana nthĩ ndĩkanangĩke kwondũ wa yũa.'),
('kam', 'GEN', 41, 37, 'Na ũndũ ũsu Valao oona nĩ ũseo, na athũkũmi make onthe moona nĩ ũseo.'),
('kam', 'GEN', 41, 38, 'Na Valao akũlya athũkũmi make, Nĩtũtonya kũmwona ũmwe ũtilyĩ ũũ, mũndũ ũla wĩ na veva wa Ngai nthĩnĩ wake?'),
('kam', 'GEN', 41, 39, 'Na Valao amwĩa Yosevu, Nĩkwĩthĩwa Ngai nũkũmanyĩthĩtye ũu w’onthe, kũi ũmwe wĩ na kĩlĩko na ũĩ taku:'),
('kam', 'GEN', 41, 40, 'ũkeethĩwa wĩ ĩũlũ wa nyũmba yakwa, na kwĩanana na ndeto yaku nĩw’o andũ makwa onthe makeaĩwa: no kĩvĩlanĩ kya ũsumbĩ nĩĩthĩwa nĩ mũnene kwĩ we.'),
('kam', 'GEN', 41, 41, 'Na Valao amwĩa Yosevu, Sisya, nĩkwia ĩũlũ wa nthĩ yonthe ya Misili.'),
('kam', 'GEN', 41, 42, 'Na Valao aumya kyaanĩ kyake ngome yake ya ũvana ũsiĩlo, na amĩkĩa kyaanĩ kya Yosevu, na amwĩkĩa ngũa ya katane nzeo, na amwĩkĩa mũnyoo wa thaavu ngingo;'),
('kam', 'GEN', 41, 43, 'na amũtũlya ĩkasyanĩ ya kelĩ ĩla waĩ nayo; na maneena na wasya mũnene mbee wake, Tulyai ndu: na amwia ĩũlũ wa nthĩ yonthe ya Misili.'),
('kam', 'GEN', 41, 44, 'Na Valao amwĩa Yosevu, Ninyie Valao, naku ũte vo vai mũndũ nthĩ yonthe ya Misili ũla ũkokĩlya kw’oko kwake kana kũũ kwake.'),
('kam', 'GEN', 41, 45, 'Na Valao amwĩta Yosevu syĩtwa yake, Nzevenathivanea; na amũnenga Asenathi, mwĩĩtu wa Voti‐vela mũthembi wa Oni, ethĩwe mũka wake. Na Yosevu aumaala athi nthĩ yonthe ya Misili.'),
('kam', 'GEN', 41, 46, 'Na Yosevu aĩ wa myaka mĩongo ĩtatũ yĩla waũngamie mbee wa Valao mũsumbĩ wa Misili. Na Yosevu auma mbee wa Valao, na athi nthĩ yonthe ya Misili.'),
('kam', 'GEN', 41, 47, 'Na ĩla myakanĩ mũonza ya lĩu mwingĩ nthĩ yasyaa mbĩ syusĩe.'),
('kam', 'GEN', 41, 48, 'Nake oomban’ya lĩu w’onthe wa myaka ĩsu mũonza ĩla yaĩ nthĩ ya Misili, na aia lĩu ndũanĩ: lĩũ wa mĩũnda ĩla yathyũlũlũkĩte kĩla ndũa, aia nthĩnĩ wayo.'),
('kam', 'GEN', 41, 49, 'Na Yosevu aia lĩu wa mbaa ngetha ta kĩthangathĩ kya ũkanga, mwingĩ mũno, kũvika aeka ũtala; nũndũ ndwaĩ ũtalĩka.'),
('kam', 'GEN', 41, 50, 'Na Yosevu asyaĩwa ana elĩ mbee wa mwaka wa yũa ũtanoka, ala Asenathi, mwĩĩtu wa Voti‐vela mũthembi wa Oni, wamũsyaĩe.'),
('kam', 'GEN', 41, 51, 'Na Yosevu ayĩta ĩkithathi syĩtwa yayo Manase: asya, Nũndũ Ngai nũmbũlĩthĩtye thĩna wa wĩa wakwa w’onthe, na nyũmba yonthe ya nau.'),
('kam', 'GEN', 41, 52, 'Na ũla wa kelĩ amwĩta syĩtwa yake Evalaimu: Nũndũ Ngai ambingĩvĩsya nthĩ ya thĩna wakwa.'),
('kam', 'GEN', 41, 53, 'Na ĩla myaka mũonza ya lĩu mwingĩ, ĩla yaĩ nthĩ ya Misili, yathela.'),
('kam', 'GEN', 41, 54, 'Na myaka mũonza ya yũa yambĩlĩlya kũka, o tondũ Yosevu waisye: na kwaĩ yũa nthĩ syonthe; ĩndĩ nthĩ yonthe ya Misili kwaĩ lĩu.'),
('kam', 'GEN', 41, 55, 'Na yila nthĩ yonthe ya Misili yaĩ na nzaa nene, andũ mamwĩkaĩla Valao nũndũ wa lĩu: na Valao amea Amisili onthe, Endai kwa Yosevu; o ũndũ wĩmũtavya, wĩkei.'),
('kam', 'GEN', 41, 56, 'Na yũa yaĩ ĩũlũ wa nthĩ yonthe vyũ: na Yosevu avingũa makũmbĩ onthe, na amathooesya Amisili, na yũa yaĩ ĩnene nthĩ ya Misili.'),
('kam', 'GEN', 41, 57, 'Na nthĩ syonthe syooka Misili kwa Yosevu kũthooa nganũ, nũndũ yũa yaĩ ĩnene nthĩ yonthe.'),
('kam', 'GEN', 42, 1, 'Na Yakovo oona kana kwĩ lĩu wa mbaa ngetha Misili, na Yakovo amea ana make, Nũndũ wa kĩ mũũsian’ya?'),
('kam', 'GEN', 42, 2, 'Na amea, Sisya, nĩnĩw’ĩte kana kwĩ lĩu wa mbaa ngetha Misili: theeai kw’o, mũkatũthooee kuma kũu; nĩ kana twĩkale thayũ, tũtikakw’e.'),
('kam', 'GEN', 42, 3, 'Na ana‐a‐ĩthe ĩkũmi ma Yosevu matheea mathooe lĩu Mĩsili.'),
('kam', 'GEN', 42, 4, 'Ĩndĩ Mbenyamini, mwana‐a‐ĩthe wa Yosevu, Yakovo ndaamũtũmanĩsya vamwe na ana‐a‐ĩthe; nũndũ aisye, Ndakese ũkwatwa nĩ ũndũ ũthũku.'),
('kam', 'GEN', 42, 5, 'Na ana ma Isilaeli mooka kũthooa vamwe na ala mookie: nũndũ yũa yaĩ nthĩ ya Kanaani.'),
('kam', 'GEN', 42, 6, 'Na Yosevu aĩ ngavana ĩũlũ wa nthĩ; nĩwe ũla wathooesye andũ onthe ma nthĩ. Na ana‐a‐ĩthe ma Yosevu mooka, na mamwĩkunamĩsya mothyũ moo melekele nthĩ.'),
('kam', 'GEN', 42, 7, 'Na Yosevu oona ana‐a‐ĩthe, na amamanya, ĩndĩ eeyĩkalya ta mũeni kwoo, na aneena nao na vinya; na amakũlya, Mwauma va? Na masũngĩa, Twauma nthĩ ya Kanaani nĩ kana tũthooe lĩu.'),
('kam', 'GEN', 42, 8, 'Na Yosevu amanya ana‐a‐ĩthe, ĩndĩ mo maiaamũmanya.'),
('kam', 'GEN', 42, 9, 'Na Yosevu alilikana ndoto ila waotie ũndũ woo, na amea, Mwĩ athiani inyw’ĩ; nĩmwooka kũsisya ũthei wa nthĩ.'),
('kam', 'GEN', 42, 10, 'Nao masũngĩa, Aiee, mwĩaĩi wakwa, ĩndĩ ithyĩ athũkũmi maku twoka kũthooa lĩu.'),
('kam', 'GEN', 42, 11, 'Ithyonthe twĩ ana ma mũndũ ũmwe; ithyĩ twĩ andũ ma w’o, athũkũmi maku ti athianĩ.'),
('kam', 'GEN', 42, 12, 'Na amea, Aiee, ĩndĩ nĩmwooka kũsisya ũthei wa nthĩ.'),
('kam', 'GEN', 42, 13, 'Nao masya, Ithyĩ athũkũmi maku twĩ ana‐a‐asa ĩkũmi na elĩ, ana ma mũndũ ũmwe nthĩ ya Kanaani; na, sisya, mũnthĩ ũũ ĩlumaita yĩ vamwe na asa waitũ, na ũmwe ti vo ũĩ.'),
('kam', 'GEN', 42, 14, 'Na Yosevu amea, Ũu nĩw’o naneena nenyu, ngĩmwĩa, Mwĩ athiani:'),
('kam', 'GEN', 42, 15, 'nĩmũũtatwa na ũndũ ũũ: kwa thayũ wa Valao inyw’ĩ mũikauma kũũ, ate o ĩlumaita yenyu yooka kũũ.'),
('kam', 'GEN', 42, 16, 'Tũmai ũmwe wenyu, na alatye mwana‐a‐ĩthe wenyu, nenyu mũkoovwa, nĩ kana ndeto syenyu itatwe, ethĩwa w’o nĩ vo ũĩ kwenyu: kana ethĩwa tĩ w’o, kwa thayũ wa Valao nĩw’o mwĩthĩwa athiani.'),
('kam', 'GEN', 42, 17, 'Na amekĩa onthe vamwe ũsũvĩonĩ matukũ atatũ.'),
('kam', 'GEN', 42, 18, 'Na mũthenya wa katatũ Yosevu amea, Ĩkai ũũ, na mũkĩkala thayũ; nĩkwĩthĩwa nyie nĩngũkĩa Ngai:'),
('kam', 'GEN', 42, 19, 'ethĩwa mwĩ andũ ma w’o, ũmwe wa ana‐a‐ĩthe menyu nĩovwe nyũmbanĩ yenyu vala mwovewe: ĩndĩ endaĩ, mũkue lĩu kwondũ wa yũa ya nyũmba syenyu:'),
('kam', 'GEN', 42, 20, 'na mũindetee ĩlumaita yenyu; na ĩndĩ ndeto syenyu ikamanyĩka kana nĩ sya w’o, nenyu mũikakw’a. Nao meeka ũu.'),
('kam', 'GEN', 42, 21, 'Na maneenan’ya ene kwa ene, Nĩ w’o twĩ avitan’ya ũndũ wa mwana‐a‐asa waitũ, nĩkwĩthĩwa nĩtwoonie thĩna wa ngoo yake, yĩla watwĩsũvie, o na tũtyaaĩthukĩĩsya; kwondũ wa ũu thĩna ũũ nĩwatũkwata.'),
('kam', 'GEN', 42, 22, 'Na Leuveni amasũngĩa, akyasya, Ndyaaneena nenyu, ngĩmwĩa, Mũikamwĩke mwana naĩ: o na mũtyaaĩthukĩĩsya? Na ĩngĩ, kwondũ wa ũu, sisya, nthakame yake nĩnĩkũandũwa.'),
('kam', 'GEN', 42, 23, 'Na maiaamanya kana Yosevu nĩwamew’a; nũndũ mũalyũli aĩ katĩ woo.'),
('kam', 'GEN', 42, 24, 'Na eethyũũa auma vala maĩ, na aĩa; na amasyokea, na aneena nao, na oosa Simeoni amumya katĩ woo, na amwova mene.'),
('kam', 'GEN', 42, 25, 'Na ĩndĩ Yosevu eeaa mĩio yoo yusũwe lĩu, na kĩla mũndũ natũngĩwe mbesa syake ĩkunianĩ yake, na kũnengwa kya ũya kya nzĩanĩ: na nĩw’o meekiwe.'),
('kam', 'GEN', 42, 26, 'Na maĩkya mang’oi moo mĩio yoo ya lĩu, na mauma kũu.'),
('kam', 'GEN', 42, 27, 'Na ũmwe woo akĩthasya ĩkunia yake anenge ĩng’oi yake lĩu vandũ vala maee, asyona mbesa syake; na, sisya, syaĩ kanyw’anĩ wa ĩkunia yake.'),
('kam', 'GEN', 42, 28, 'Na amea ana‐a‐ĩthe, Mbesa syakwa nĩnatũngĩwa; na, sisya, syĩ vo o ĩkunianĩ yakwa: na ngoo syoo syakw’a, na masian’ya na kũtetema, makyasya, Ũndũ ũũ nĩ ata Ngai ũtwĩkie?'),
('kam', 'GEN', 42, 29, 'Na mooka kwa Yakovo ĩthe woo nthĩ ya Kanaani, na mamũtavya ũvoo w’onthe ũla wamakĩtĩkĩe, makĩmwĩa,'),
('kam', 'GEN', 42, 30, 'Mũndũ ũsu, mwĩaĩi wa nthĩ ĩsu, aneenie naitũ na vinya, atwona twĩ athiani ma ĩ nthĩ.'),
('kam', 'GEN', 42, 31, 'Naitũ twamwĩa, Twĩ andũ ma w’o; tũi athiani:'),
('kam', 'GEN', 42, 32, 'twĩ ana‐a‐asa ĩkũmi na elĩ, ana ma asa waitũ; ũmwe ti vo ũĩ, na mũnthĩ ũũ ĩlumaita yĩ vamwe na asa waitũ nthĩ ya Kanaani.'),
('kam', 'GEN', 42, 33, 'Na ũla mũndũ, mwĩaĩi wa nthĩ ĩsu, atwĩa, Ngamanya kana mwĩ andũ ma w’o na nzĩa ĩno: tiai ũmwe wa ana‐a‐ĩthe menyu nakwa, na kuai lĩu kwondũ wa yũa ya nyũmba syenyu, na mũithi;'),
('kam', 'GEN', 42, 34, 'na mwĩndetee ĩlumaita yenyu: nĩvo nĩmanya kana mũi athiani, ĩndĩ mwĩ andũ ma w’o: na ĩndĩ ngamũnenga mwana‐a‐ĩthe wenyu, nenyu mũkatandĩthĩsya ĩ nthĩ.'),
('kam', 'GEN', 42, 35, 'Na kweethĩwa makĩtulũla makunia moo, sisya, kyove kya mbesa kya kĩla mũndũ kyaĩ nthĩnĩ wa ĩkunia yake: nao na ĩthe woo, yĩla moonie syove syoo sya mbesa, makĩa.'),
('kam', 'GEN', 42, 36, 'Na Yakovo ĩthe woo amea, Nĩnakw’ĩĩwe nĩ syana syakwa nũndũ wenyu: Yosevu nde vo, o na Simeoni nde vo, na Mbenyamini mũkamũtwaa: maũndũ aa onthe nĩmeũmbũkĩa.'),
('kam', 'GEN', 42, 37, 'Na Leuveni aneena na ĩthe, akĩmwĩa, Ũaa ana makwa elĩ ethĩwa ndimũete kwaku: nenga we kw’okonĩ kwakwa, nakwa ngamũete kwaku ĩngĩ.'),
('kam', 'GEN', 42, 38, 'Nake amea, Mwana wakwa ndakatheea nenyu; nũndũ mwana‐a‐inyia nĩ mũkw’ũ, nake atiele e weka: ethĩwa we akakwatwa nĩ ũndũ ũthũku nzĩanĩ ĩla mwĩendela, nĩvo mwĩtheesya mbũĩ syakwa na woo Seoli.'),
('kam', 'GEN', 43, 1, 'Na yũa yaĩ ĩnene nthĩ.'),
('kam', 'GEN', 43, 2, 'Na kweethĩwa, yĩla maminie ũya lĩu ũla maumisye Misili, ĩthe woo amea, Syokai, mũkatũthooee lĩu mũnini.'),
('kam', 'GEN', 43, 3, 'Na Yuta aneena nake, akĩmwĩa, Ũla mũndũ nĩwatũkũsĩĩe mũno, akĩtwĩa, Mũikona ũthyũ wakwa, mwana‐a‐ĩthe wenyu ate vamwe nenyu.'),
('kam', 'GEN', 43, 4, 'Ethĩwa ũkamũtũma mwana‐a‐asa naitũ, tũkatheea kũkũthooea lĩu:'),
('kam', 'GEN', 43, 5, 'ĩndĩ ethĩwa ndũũmũtũma, tũikatheea; nũndũ ũla mũndũ nĩwatwĩie, Mũikona ũthyũ wakwa, mwana‐a‐ĩthe wenyu ate vamwe nenyu.'),
('kam', 'GEN', 43, 6, 'Na Isilaeli akũlya, Nĩkĩ mwambĩka ũthũku ta ũu, kũtavya mũndũ ũsu kana mwĩ na mwana‐a‐au ũngĩ?'),
('kam', 'GEN', 43, 7, 'Nao masũngĩa, Mũndũ ũsu atũkũlilye mũno ũvoo witũ, na ũvoo wa ũko witũ, akyasya, Au e o thayũ? Mwĩ na mwana‐a‐ĩthe ũngĩ? Naitũ twamũtavisye ũvoo kwĩanana na ndeto isu: twaĩ tũtonya kũmanya o na vanini kana akasya, Theeai na mwana‐a‐au?'),
('kam', 'GEN', 43, 8, 'Na Yuta amwĩa Isilaeli ĩthe wake, Tũma kĩmwana vamwe nakwa, naitũ tũkookĩla tũende; nĩ kana twĩkale thayũ, tũikakw’e, ithyĩ, o naku, na syana sitũ nini nasyo.'),
('kam', 'GEN', 43, 9, 'Ngeethĩwa nĩ mũĩkĩĩwa kwondũ wake; kw’okonĩ kwakwa ũkamũkũlya: ethĩwa ndimũete kwaku, na kũmwia mbee waku, nĩvo nĩĩthĩwa nĩkũvĩtanĩsye tene na tene:'),
('kam', 'GEN', 43, 10, 'nũndũ keka twĩkalangĩte, nĩ w’o twĩthĩwa yu tũsyokete ĩvinda ya kelĩ.'),
('kam', 'GEN', 43, 11, 'Na ĩthe woo Isilaeli amea, Ethĩwa nĩ ũu yu, ĩkai ũũ: osai mosyao ma nthĩ maseo mbee mĩionĩ yenyu, mũmũkuĩe ũla mũndũ mũthĩnzĩo, seli mũnini, na ũkĩ wa nzũkĩ mũnini, na mĩtĩ ĩnyungaa nesa na manemane, na mbĩndĩ sya mbatani, na malosi:'),
('kam', 'GEN', 43, 12, 'na mũitwaa mbesa kũndũ kwĩlĩ kw’okonĩ kwenyu; na mbesa ila syatũngĩiwe makanyw’anĩ ma makunia menyu mũkue ĩngĩ kw’okonĩ kwenyu; nokwĩthĩwa waĩ ĩvĩtyo:'),
('kam', 'GEN', 43, 13, 'na ĩngĩ mwosei mwana‐a‐au nake, na ũkĩlai, mũsyokee ũla mũndũ:'),
('kam', 'GEN', 43, 14, 'na Ngai Mwene Vinya W’onthe namwĩw’ĩe tei kwa ũla mũndũ, nĩ kana amũthaĩsye mwana‐a‐ĩthe wenyu ũla ũngĩ na Mbenyamini. Na ethĩwa ngakw’ĩĩwa nĩ syana syakwa, nĩnakw’ĩĩwa.'),
('kam', 'GEN', 43, 15, 'Na ala andũ moosa mũthĩnzĩo ũsu, na moosa mbesa kũndũ kwĩlĩ kw’okonĩ kwoo, na Mbenyamini; na mookĩla, na matheea Misili, na maũngama mbee wa Yosevu.'),
('kam', 'GEN', 43, 16, 'Na Yosevu amwona Mbenyamini e vamwe nao, amwĩa mũsyaĩĩsya wa nyũmba yake, Ete andũ asu nyũmbanĩ, noithĩnza, na kũseũvya; nũndũ andũ asu nĩmeũya vamwe nakwa syũa yaũngama.'),
('kam', 'GEN', 43, 17, 'Na ũla mũndũ eeka o ũndũ Yosevu wamwĩaĩe; na mũndũ ũsu aete ala andũ nyũmbanĩ ya Yosevu.'),
('kam', 'GEN', 43, 18, 'Na andũ asu meew’a w’ĩa, nũndũ maetiwe nyũmbanĩ ya Yosevu; na masya, Nũndũ wa mbesa ila syatũngĩiwe makunianĩ maitũ ĩvinda ya mbee nĩtwaetwe nthĩnĩ; nĩ kana amanthe ũndũ wa ũtwilĩĩla, na kũtũvalũkĩla, atũthũkũmĩthye ithyĩ, na mang’oi maitũ.'),
('kam', 'GEN', 43, 19, 'Na mamũthengeea mũsyaĩĩsya wa nyũmba ya Yosevu, na maneena nake me mũomonĩ wa nyũmba,'),
('kam', 'GEN', 43, 20, 'na mamwĩa, Atĩ, mwĩaĩi wakwa, nĩ w’o nĩtwatheeie ĩvinda ya mbee kũthooa lĩu:'),
('kam', 'GEN', 43, 21, 'na kweethĩwa, twavika vandũ vala twaee, twathasya makunia maitũ, na, sisya, mbesa sya kĩla mũndũ syaĩ kanyw’anĩ wa ĩkunia yake, mbesa sitũ ũito wasyo wĩanĩe: naitũ nĩtwaitũnga na moko maitũ.'),
('kam', 'GEN', 43, 22, 'Na mbesa ingĩ twaete na moko maitũ tũthooe lĩu: tũyĩsĩ nũũ wekĩie mbesa sitũ makunianĩ maitũ.'),
('kam', 'GEN', 43, 23, 'Na amasũngĩa, Mũuo wĩthĩwe kwenyu, mũikakĩe: Ngai wenyu, na Ngai wa ĩthe wenyu, nĩwamũnengie ũthwii makunianĩ menyu: nyie naĩ na mbesa syenyu. Na amaumĩlĩlya Simeoni.'),
('kam', 'GEN', 43, 24, 'Na ũla mũndũ aete andũ asu nyũmbanĩ ya Yosevu, na amanenga manzĩ, na mathambya maũũ moo; na anenga mang’oi moo lĩu.'),
('kam', 'GEN', 43, 25, 'Na ũla mũthĩnzĩo maia wũmbanĩtw’e Yosevu akyũka syũa yaũngama: nũndũ nĩmeewie kana nĩmeũya lĩu kw’o.'),
('kam', 'GEN', 43, 26, 'Na Yosevu enũka, mamũetee mũthĩnzĩo nyũmbanĩ ũla waĩ mokonĩ moo, na mamwĩkunamĩsya nthĩ.'),
('kam', 'GEN', 43, 27, 'Na amakũlya ũvoo woo, na asya, Ĩthe wenyu no mũvoo, ũla mũtumĩa mwaneenie ũndũ wake? E thayũ o na yu?'),
('kam', 'GEN', 43, 28, 'Na mamũsũngĩa, Mũthũkũmi waku asa waitũ no mũvoo, e thayũ o na yu. Na makunamya mĩtwe yoo, na meekunamya kũvika nthĩ.'),
('kam', 'GEN', 43, 29, 'Nake ookĩlya metho make, na oona mwana‐a‐inyia Mbenyamini, ũla wasyaanĩw’e nake, na akũlya, Yĩĩ nĩ ĩlumaita yenyu, yĩla mwaneenie nakwa ũndũ wayo? Na ayĩa, Ngai nakwĩke nesa, mwana wakwa.'),
('kam', 'GEN', 43, 30, 'Na Yosevu eekalaata; nũndũ ngoo yake yaĩ na mea ma mwana‐a‐inyia: na amantha vandũ va kũĩĩa; na alika kasũmbanĩ kake, aĩĩa vo.'),
('kam', 'GEN', 43, 31, 'Na athamba ũthyũ, na aumaala; na eeyũmĩĩsya, na asya. Iai lĩu mesanĩ.'),
('kam', 'GEN', 43, 32, 'Na maia kwondũ wake weka, na kwondũ woo me oka, na kwondũ wa Amisili, ala maĩsaa vamwe nake, me oka: nĩkwĩthĩwa Amisili matitonya kũya lĩu vamwe na Aevelania; nũndũ ũu nĩ ũthatyo kwa Amisili.'),
('kam', 'GEN', 43, 33, 'Na mekala mbee wake, ĩkithathi kwĩanana na ũkithathi wayo, na ĩlumaita kwĩanana na ũlumaita wayo: na ala andũ maseng’a ene kwa ene.'),
('kam', 'GEN', 43, 34, 'Na matwaĩwa lĩu kuma mbee wake: ĩndĩ lĩu wa Mbenyamini waĩ mwingĩ kũndũ kũtano kwĩ lĩu w’onthe wa ũmwe. Na manyw’a, na matana vamwe nake.'),
('kam', 'GEN', 44, 1, 'Na amwĩaĩa mũsyaĩĩsya wa nyũmba yake, akĩmwĩa, Usũsya makunia ma andũ lĩu, o ũndũ matonya ũkua, noyĩkĩa mbesa sya kĩla mũndũ kanyw’anĩ wa ĩkunia yake.'),
('kam', 'GEN', 44, 2, 'Na kĩkombe kyakwa, kĩla kĩkombe kya vetha, ĩkĩa kanyw’anĩ wa ĩkunia ya ĩlumaita, o na mbesa syake sya lĩu. Nake eeka kwĩanana na ndeto ĩla Yosevu waneenete.'),
('kam', 'GEN', 44, 3, 'Na kĩoko kũikya, ala andũ maekwa mathi, mo na mang’oi moo.'),
('kam', 'GEN', 44, 4, 'Nao meethĩwa mauma ndũanĩ, o na matanaendeea mũno, Yosevu amwĩa mũsyaĩĩsya wa nyũmba yake, Ũkĩla, atĩĩa andũ asu; na wamawĩla, makũlye, Mwatũnga ũthũku vandũ va ũseo nĩkĩ?'),
('kam', 'GEN', 44, 5, 'Kyu tikyo kĩla mwĩaĩi wakwa ũnyusaa nakyo, o na tikyo wathanaa nakyo? Nĩmwĩkie naĩ mweeka ũu.'),
('kam', 'GEN', 44, 6, 'Na amawĩla amatavya ndeto isu.'),
('kam', 'GEN', 44, 7, 'Nao mamwĩa, Mwĩaĩi wakwa eneena ndeto ta isu nĩkĩ? Kwĩthĩwe kũasa na athũkũmi maku kwĩka ũndũ ta ũsu.'),
('kam', 'GEN', 44, 8, 'Sisya, mbesa, ila tweethĩie makanyw’anĩ ma makunia maitũ, nĩtwatũngie kwaku kuma nthĩ ya Kanaani: twĩũya ata ĩndĩ vetha kana thaavu kuma nyũmbanĩ ya mwĩaĩi waku?'),
('kam', 'GEN', 44, 9, 'O na wĩva wa athũkũmi maku ũla ũkwoneka e nakyo, nakw’e, o naitũ tũkeethĩwa twĩ ngombo sya mwĩaĩi wakwa.'),
('kam', 'GEN', 44, 10, 'Nake asya, Yu nĩkwĩthĩwe o kwĩanana na ndeto syenyu: we ũla ũnũkwoneka e nakyo akeethĩwa ngombo yakwa; nenyu mũkeethĩwa mũte na ĩvĩtyo.'),
('kam', 'GEN', 44, 11, 'Na ĩndĩ meekalaata, na maũa kĩla mũndũ ĩkunia yake nthĩ, mathasya kĩla mũndũ ĩkunia yake.'),
('kam', 'GEN', 44, 12, 'Nake amantha, ambĩlĩlya kwa ũla mũkũũ, o na kũminĩa kwa ũla mũnini: na kĩla kĩkombe kyooneka ĩkunianĩ ya Mbenyamini.'),
('kam', 'GEN', 44, 13, 'Na ĩndĩ matembũa ngũa syoo, na maĩkya kĩla mũndũ ĩng’oi yake mũio, na masyoka ndũanĩ.'),
('kam', 'GEN', 44, 14, 'Na Yuta na ana‐a‐ĩthe mavika nyũmbanĩ ya Yosevu; nake aĩ o vo: nao mavalũka nthĩ mbee wake.'),
('kam', 'GEN', 44, 15, 'Na Yosevu amea, Ũndũ ũũ nata mwĩkie? Mũyĩsĩ kana mũndũ takwa nũtonya kwathana ki?'),
('kam', 'GEN', 44, 16, 'Na Yuta akũlya, Tũmwĩe mwĩaĩi wakwa ata? Tũneene ata? O na twĩtw’ĩe ũlũngalu ata? Ngai nĩwonete ũthũku wa athũkũmi maku: sisya, twĩ ngombo sya mwĩaĩi wakwa, ithyĩ, ona ũsu nake ũla kĩkombe kyonekie kw’okonĩ kwake.'),
('kam', 'GEN', 44, 17, 'Nake asũngĩa, Kwĩthĩwe kũasa nakwa kwĩka ũndũ ta ũsu: mũndũ ũla kĩkombe kyonekie kw’okonĩ kwake, ũsu akeethĩwa ngombo yakwa; ĩndĩ inyw’ĩ ambatai na mũuo kwa ĩthe wenyu.'),
('kam', 'GEN', 44, 18, 'Na nĩvo ĩndĩ Yuta wamũthengeeie, na amwĩa, Ame, mwĩaĩi wakwa, nĩngũkwĩsũva, eka mũthũkũmi waku aneene ndeto ĩmwe matũnĩ ma mwĩaĩi wakwa, na ũthatũ waku ndũkakanĩe mũthũkũmi waku; nũndũ we wĩ o ta Valao.'),
('kam', 'GEN', 44, 19, 'Mwĩaĩi wakwa akũlilye athũkũmi make, akyasya, Mwi na au, kana mwana‐a‐au?'),
('kam', 'GEN', 44, 20, 'Naitũ twamwĩa mwĩaĩi wakwa, Twĩ na asa, mũtumĩa mũkũũ, na mwana wa ũkũũ wake, mũnini; na mwana‐a‐inyia wake nĩ mũkw’ũ, nake atiele e weka wa inyia wake; na ĩthe wake nũmwendete.'),
('kam', 'GEN', 44, 21, 'Naku watavisye ithyĩ athũkũmi maku, Mwĩmũtheesya kwakwa nĩmwone na metho.'),
('kam', 'GEN', 44, 22, 'Na twamwĩa mwĩaĩi wakwa, Kĩmwana kĩitonya kũtia ĩthe: nũndũ ethĩwa kĩkatia ĩthe, ĩthe akakw’a.'),
('kam', 'GEN', 44, 23, 'Naku wamatavya athũkũmi maku, Ate o ĩlumaita yenyu kũtheea vamwe nenyu, mũikambona ũthyũ ĩngĩ.'),
('kam', 'GEN', 44, 24, 'Na kweethĩwa twambata kwa nau mũthũkũmi waku, twamũtavya ndeto sya mwĩaĩi wakwa.'),
('kam', 'GEN', 44, 25, 'Na asa waitũ asya, Syokai, mũkatũthooee lĩu mũnini.'),
('kam', 'GEN', 44, 26, 'Na twasũngĩa, Tũitonya kũtheea: ethĩwa ĩlumaita yĩ vamwe naitũ, nĩvo tũũtheea; nũndũ tũitonya kwona ũthyũ wa ũla mũndũ, ate o ĩlumaita yĩ vamwe naitũ.'),
('kam', 'GEN', 44, 27, 'Na mũthũkũmi waku, asa wakwa, atwĩa, Nĩmwĩsĩ kana mũka wakwa nĩwanzyaĩe ana elĩ:'),
('kam', 'GEN', 44, 28, 'na ũmwe wauma kwakwa, na nasya, Nĩ w’o atilangĩtwe ilungu; o na kuma ĩvinda yĩu ndyaamwona:'),
('kam', 'GEN', 44, 29, 'na ethĩwa ũsu nake mũkamumya kwakwa, na ũthũku ũkamũkwata, mũkatheesya mbuĩ syakwa Seoli na woo.'),
('kam', 'GEN', 44, 30, 'Na yu ĩndĩ navika kwa mũthũkũmi waku, ĩthe wakwa, na kĩmwana kĩte vamwe naitũ; nĩkwĩthĩwa thayũ wake nĩwovanĩte na thayũ wa kĩmwana;'),
('kam', 'GEN', 44, 31, 'kũkeethĩwa, oona kana kĩmwana kĩti vamwe naitũ, akakw’a: na athũkũmi maku makatheesya mbuĩ sya mũthũkũmi waku, asa waitũ, Seoli na woo.'),
('kam', 'GEN', 44, 32, 'Nũndũ mũthũkũmi waku nĩwetwie mũĩkĩĩwa kwa ĩthe wakwa kwondũ wa kĩmwana, ngĩmwĩa, Ethĩwa ndimũete kwaku, nĩvo nĩĩthĩwa nĩvĩtanĩsye nau tene na tene.'),
('kam', 'GEN', 44, 33, 'Na yu ĩndĩ, nĩngũkwĩsũva, eka mũthũkũmi waku ekale ngombo kwa mwĩaĩi wakwa vandũ va kĩmwana; na eka kĩmwana kyambate vamwe na ana‐a‐ĩthe makyo.'),
('kam', 'GEN', 44, 34, 'Nũndũ ngatonya ata kwambata kwa ĩthe wakwa, ethĩwa kĩmwana kĩti vamwe nakwa? Ndikese kwona ũthũku ũla wĩmũkwata asa wakwa.'),
('kam', 'GEN', 45, 1, 'Na ĩndĩ Yosevu ndaatonya kwĩyũmĩĩsya mbee wa onthe ala maũngamĩte nake; na aneena na wasya mũnene, Umaalyai kĩla mũndũ aume vaa nĩĩ. O na vaiaaũngama mũndũ vamwe nake, Yosevu akĩĩmanyĩthya kwa ana‐a‐ĩthe.'),
('kam', 'GEN', 45, 2, 'Na aĩa na wasya mũnene: na Amisili meew’a, na ala ma nyũmba ya Valao meew’a.'),
('kam', 'GEN', 45, 3, 'Na Yosevu amea ana‐a‐ĩthe make, Ninyie Yosevu; nau e o thayũ? Na ana‐a‐ĩthe maiaatonya kũmũsũngĩa; nũndũ maĩ na kĩũũyũ mbee wake.'),
('kam', 'GEN', 45, 4, 'Na Yosevu amea ana‐a‐ĩthe, Nĩngũmwĩsũva, thengeeaĩ vakuvĩ nakwa. Na mathengeea. Na asya, Ninyie Yosevu mwana‐a‐ĩthe wenyu, ũla mwathooisye Misili.'),
('kam', 'GEN', 45, 5, 'Na yu ĩndĩ mũikew’e woo, o na mũikethatĩe ene, nũndũ mwanthooisye kũũ: nĩkwĩthĩwa Ngai nĩwandũmie mbee wenyu kũtangĩĩa thayũ.'),
('kam', 'GEN', 45, 6, 'Nũndũ myaka ĩno ĩlĩ kũnaĩ yũa nthĩ: na vatiele myaka ĩtano, ĩla nthĩnĩ wayo kũtakethĩwa kwĩnza kana kũketha.'),
('kam', 'GEN', 45, 7, 'Na Ngai nĩwandũmie mbee wenyu kũmwiĩa ũtialo kũũ nthĩ, na kũmwovosya na wovosyo mũnene mwĩthĩwe thayũ.'),
('kam', 'GEN', 45, 8, 'Na yu ĩndĩ ti inyw’ĩ mwandũmie kũũ, ĩndĩ nĩ Ngai: na andwie ĩthe wa Valao, na mwĩaĩi wa onthe ma nyũmba yake, na mũsumbĩki ĩũlũ wa nthĩ yonthe ya Misili.'),
('kam', 'GEN', 45, 9, 'Ĩkalaatei, mwambate kwa nau, mũmwĩe, Yosevu mwana waku asya ũũ, Ngai nĩwandwie mwĩaĩi wa Misili yonthe: theea kwakwa, ndũkekalange;'),
('kam', 'GEN', 45, 10, 'na ũkatũa nthĩ ya Ngoseni, na ũkeethĩwa wĩ vakuvĩ nakwa, we, na ana maku, na esũkũũu, na ndĩthya syaku sya mbũi na malondu, na ndĩthya syaku sya ng’ombe, na syonthe ila wĩ nasyo:'),
('kam', 'GEN', 45, 11, 'na vau ngakũĩthĩsya; ndũkese kwĩthĩwa na ũkya, we, na andũ ma nyũmba yaku, na syonthe ila wĩ nasyo; nũndũ vatiele myaka ĩtano ya yũa.'),
('kam', 'GEN', 45, 12, 'Na, sisya, metho menyu nĩmekwona, na metho ma mwanaa‐mwaitũ Mbenyamini, kana nĩ kanyw’a wakwa ũũneena nenyu.'),
('kam', 'GEN', 45, 13, 'Na mũkatavya nau ũvoo wa ndaĩa yakwa yonthe kũũ Misili, na ũvoo wa onthe ala mwonete: nenyu mũkekalaate kũmũtheesya nau kũũ.'),
('kam', 'GEN', 45, 14, 'Na amũvalũkĩla ngingo mwana‐a‐inyia Mbenyamini, na aĩa; na Mbenyamini amũĩĩa ngingonĩ.'),
('kam', 'GEN', 45, 15, 'Na amamumunya ana‐a‐ĩthe make onthe, amaĩĩa: na ĩtina wa ũu ana‐a‐ĩthe make maneenan’ya nake.'),
('kam', 'GEN', 45, 16, 'Na ũvoo ũsu nĩweew’ĩkie nyũmbanĩ ya Valao, kũineenwa, Ana‐a‐ĩthe ma Yosevu nĩmooka: na Valao endeew’a mũno, o na athũkũmi make.'),
('kam', 'GEN', 45, 17, 'Na Valao amwĩa Yosevu, Tavya ana‐a‐au, Ĩkai ũũ: aĩkyai nyamũ syenyu mĩio, na endai, mũthi nthĩ ya Kanaani;'),
('kam', 'GEN', 45, 18, 'na mũiosa ĩthe wenyu na andũ ma nyũmba syenyu, na mũimbũkĩa: nakwa ngamũnenga ũseo wa nthĩ ya Misili, na mũkaya ũnou wa nthĩ.'),
('kam', 'GEN', 45, 19, 'Na ĩndĩ nĩweeaĩwa, ĩkai ũũ: mumye makasya nthĩ ya Misili, kwondũ wa syana syenyu nini, na kwondũ wa aka menyu, na mũkamũete au, na mũyũka.'),
('kam', 'GEN', 45, 20, 'O na mũikaketeee syĩndũ syenyu; nũndũ ũseo wa nthĩ yonthe ya Misili nĩ wenyu.'),
('kam', 'GEN', 45, 21, 'Na ana ma Isilaeli meeka o ta ũu: na Yosevu amanenga makasya, kwĩanana na mwĩao wa Valao, na amanenga lĩu wa nzĩanĩ.'),
('kam', 'GEN', 45, 22, 'Nao onthe anenga kĩla mũndũ ngũa sya ũkũan’ya; ĩndĩ Mbenyamini amũnenga ilungu maana atatũ sya vetha, na ngũa sya ũkũan’ya katano.'),
('kam', 'GEN', 45, 23, 'Na atwaĩa ĩthe ta ũũ: mang’oi ĩkũmi makuĩthĩtw’e syĩndũ nzeo sya Misili, na mang’oi maka ĩkũmi makuĩthĩtw’e lĩu wa mbaa ngetha na imũtũ na kya ũya kya ithe kya nzĩanĩ.'),
('kam', 'GEN', 45, 24, 'Na ĩndĩ amea ana‐a‐ĩthe mathi, na makũsya: na amea, Sisyai mũikatetan’ye mwĩ nzĩanĩ.'),
('kam', 'GEN', 45, 25, 'Na mambata kuma Misili, na malika nthĩ ya Kanaani kwa Yakovo ĩthe woo.'),
('kam', 'GEN', 45, 26, 'Na mamũtavya, makyasya, Yosevu e o thayũ, nake nĩ mũsumbĩki ĩũlũ wa nthĩ yonthe ya Misili. Na ngoo yake yakw’a, nũndũ ndaametĩkĩla.'),
('kam', 'GEN', 45, 27, 'Na mamũtavya ndeto syonthe sya Yosevu, ila wamatavĩtye: na yĩla wonie makasya ala maetetwe nĩ Yosevu sya kũmũkua, veva wa Yakovo ĩthe woo wavuũka:'),
('kam', 'GEN', 45, 28, 'na Isilaeli asya, Nũũ; Yosevu mwana wakwa e o thayũ: ngaenda ngamwone ndanakw’a.'),
('kam', 'GEN', 46, 1, 'Na Isilaeli aenda kyalo na syonthe ila waĩ nasyo, na avika Mbeeli‐sieva, na athembea Ngai wa ĩthe wake Isaka nthembo.'),
('kam', 'GEN', 46, 2, 'Na Ngai aneena na Isilaeli mawoninĩ ma ũtukũ, na amwĩa, Yakovo, Yakovo. Nake asũngĩa, Nĩ vaa.'),
('kam', 'GEN', 46, 3, 'Na amwĩa, Ninyie Ngai, Ngai wa ĩthe waku: ndũkakĩe kũtheea Misili; nĩkwĩthĩwa nyie ngakũtw’ĩkĩthĩsya mbaĩ nene kũu:'),
('kam', 'GEN', 46, 4, 'nyie ngatheea vamwe naku kũvika Misili; nakwa vate ndĩi ngakwambatya ĩngĩ: na Yosevu akailĩĩla kw’oko kwake methonĩ maku.'),
('kam', 'GEN', 46, 5, 'Na Yakovo ookĩla auma Mbeeli‐sieva: na ana ma Isilaeli makua Yakovo ĩthe woo na makasya ala Valao waetie mamũkue, e na syana syoo nini, na aka moo.'),
('kam', 'GEN', 46, 6, 'Na moosa indo syoo, na ũthwii woo, ũla moosie nthĩ ya Kanaani, na mavika Misili, Yakovo, na ũsyao wake w’onthe vamwe nake:'),
('kam', 'GEN', 46, 7, 'ana make, na esũkũũe, vamwe nake, na eĩtu make, na esũkũũe make eĩtu, na ũsyao wake w’onthe athi vamwe naw’o kũvika Misili.'),
('kam', 'GEN', 46, 8, 'Na aa nĩo masyĩtwa ma ana ma Isilaeli, ala mookie Misili, Yakovo na ana make: Leuveni, ĩkithathi ya Yakovo.'),
('kam', 'GEN', 46, 9, 'Na ana ma Leuveni: Anoki, na Valu, na Esiloni, na Kalimi.'),
('kam', 'GEN', 46, 10, 'Na ana ma Simeoni: Yemueli, na Yamini, na Oati, na Yakini, na Nzooali, na Sauli mwana wa mũndũ mũka Mũkanaani.'),
('kam', 'GEN', 46, 11, 'Na ana ma Livai: Ngelisoni, na Koathi, na Melali.'),
('kam', 'GEN', 46, 12, 'Na ana ma Yuta: Eeli, na Onani, na Siela, na Velesi, na Nzela; ĩndĩ Eeli na Onani nĩmakw’ĩĩe nthĩ ya Kanaani. Na ana ma Velesi maĩ Esiloni na Amuli.'),
('kam', 'GEN', 46, 13, 'Na ana ma Isakali: Tola, na Vuva, na Yovu, na Similoni.'),
('kam', 'GEN', 46, 14, 'Na ana ma Nzevuluni: Seletu, na Eloni, na Yaleeli.'),
('kam', 'GEN', 46, 15, 'Aa nĩo ana ma Lea, ala wamũsyaĩe Yakovo Vatani‐alamu, vamwe na mwĩĩtu wake Ndina: syuu syonthe sya ana make na eĩtu make syaĩ mĩongo ĩtatũ na itatũ.'),
('kam', 'GEN', 46, 16, 'Na ana ma Ngati: Nzivioni, na Aki, na Suni, na Esevoni, na Eeli, na Aloti, na Aleli.'),
('kam', 'GEN', 46, 17, 'Na ana ma Aseli: Imina, na Isiva, na Isivi, na Mbelia, na Selaa mwĩĩtu‐wa‐inyia woo; na ana ma Mbelia: Eeveli, na Malikieli.'),
('kam', 'GEN', 46, 18, 'Aa nĩo ana ma Ngiliva, ũla Lavani wamũnengie Lea mwĩĩtu wake; na amũsyaĩa Yakovo asu, syuu ikũmi na thanthatũ.'),
('kam', 'GEN', 46, 19, 'Ana ma Lakeli mũka wa Yakovo: Yosevu na Mbenyamini.'),
('kam', 'GEN', 46, 20, 'Na nthĩ ya Misili Yosevu asyaĩwe Manase na Evalaimu, ala Asenathi, mwĩĩtu wa Voti‐vela mũthembi wa Oni, wamũsyaĩe.'),
('kam', 'GEN', 46, 21, 'Na ana ma Mbenyamini: Mbela, na Mbekeli, na Asiveli, na Ngela, na Naamani, na Ei, na Losi, na Muvimu, na Uvimu, na Aliti.'),
('kam', 'GEN', 46, 22, 'Aa nĩo ana ma Lakeli, ala masyaĩwe Yakovo: syuu syonthe syaĩ ĩkũmi na inya.'),
('kam', 'GEN', 46, 23, 'Na ana ma Ndani: Usimu.'),
('kam', 'GEN', 46, 24, 'Na ana ma Navitali: Yaseeli, na Nguni, na Yeseli, na Silemu.'),
('kam', 'GEN', 46, 25, 'Aa nĩo ana ma Mbila, ũla Lavani wamũnengie Lakeli mwĩĩtu wake, na aa nĩo wamũsyaĩe Yakovo: syuu syonthe syaĩ mũonza.'),
('kam', 'GEN', 46, 26, 'Syuu syonthe ila syookie Misili vamwe na Yakovo, ila syaumie kĩnyunyuni kyake, eka aka ma ana ma Yakovo, syuu syonthe syaĩ mĩongo thanthatũ na thanthatũ;'),
('kam', 'GEN', 46, 27, 'na ana ma Yosevu, ala wasyaĩwe Misili, syaĩ syuu ilĩ: syuu syonthe sya nyũmba ya Yakovo, ala malikile Misili, syaĩ mĩongo mũonza.'),
('kam', 'GEN', 46, 28, 'Na atũma Yuta mbee wake kwa Yosevu, amũtongoesye kũvika Ngoseni; na mavika nthĩ ya Ngoseni.'),
('kam', 'GEN', 46, 29, 'Na Yosevu aseũvya ĩkasya yake ya kĩũsumbĩ, na ambata amũthaũe Isilaeli ĩthe wake, kũvika Ngoseni; na eeyonan’ya kwake, na amũvalũkĩla ngingo, na aĩĩa ngingonĩ yake ĩvinda ĩasa.'),
('kam', 'GEN', 46, 30, 'Na Isilaeli amwĩa Yosevu, Yu ĩndĩ nĩkw’e, nĩkwĩthĩwa nĩnakwona ũthyũ waku, kana wĩ o thayũ.'),
('kam', 'GEN', 46, 31, 'Na Yosevu amea ana‐a‐ĩthe, na andũ ma nyũmba ya ĩthe, Nyie nĩngwambata, nĩmũtavye Valao, nĩmwĩe, Ana‐a‐asa makwa, na andũ ma nyũmba ya asa, ala maĩ nthĩ ya Kanaani, nĩmambũkĩe;'),
('kam', 'GEN', 46, 32, 'na andũ asu nĩ aĩthi, nĩkwĩthĩwa wĩa woo waĩ kũĩthya; na nĩmaetie ndĩthya syoo sya mbũi na malondu na ndĩthya syoo sya ng’ombe, na syonthe ila me nasyo.'),
('kam', 'GEN', 46, 33, 'Na kũkeethĩwa, yĩla Valao wĩmwĩta, na kũkũlya, Wĩa wenyu nĩ mwaũ?'),
('kam', 'GEN', 46, 34, 'Inyw’ĩ mwĩasya, Athũkũmi maku nĩ aĩthi kuma wana witũ kũvika o na yu, ithyĩ, o na aasa maitũ: nĩ kana mwĩkale nthĩ ya Ngoseni; nũndũ kĩla mũĩthi nĩ ũthatyo kwa Amisili.'),
('kam', 'GEN', 47, 1, 'Na ĩndĩ Yosevu alika na atavya Valao, na amwĩa, Nau na ana‐a‐asa, na ndĩthya syoo sya mbũi na malondu, na ndĩthya syoo sya ng’ombe, na syonthe ila me nasyo, nĩmaumĩte nthĩ ya Kanaani; na, sisya, me nthĩ ya Ngoseni.'),
('kam', 'GEN', 47, 2, 'Na oosa andũ atano kuma katĩ wa ana‐a‐ĩthe make, amonan’ya kwa Valao.'),
('kam', 'GEN', 47, 3, 'Na Valao akũlya ana‐a‐ĩthe make, Wĩa wenyu nĩ mwaũ? Na mamwĩa Valao, Athũkũmi maku nĩ aĩthi, ithyĩ, o na aasa maitũ.'),
('kam', 'GEN', 47, 4, 'Na mamwĩa Valao, Tũkĩte kwĩkala ũeni nthĩ; nĩkwĩthĩwa vati ũĩthyo wa ndĩthya sya mbũi na malondu sya athũkũmi maku; nũndũ yũa nĩ ĩnene nthĩ ya Kanaani: na yu ĩndĩ, nĩtũũkũvoya, athũkũmi maku matũe nthĩ ya Ngoseni.'),
('kam', 'GEN', 47, 5, 'Na Valao aneena na Yosevu, akĩmwĩa, Au na ana‐a‐au nĩmakũkĩe;'),
('kam', 'GEN', 47, 6, 'nthĩ ya Misili yĩ mbee waku; tũsya au na ana‐a‐au nthĩ ĩla nzeo mbee: nĩmatũe nthĩ ya Ngoseni: na ethĩwa nĩwĩsĩ andũ amwe me ũtonyi katĩ woo, matw’e ĩndĩ anene ĩũlũ wa indo syakwa.'),
('kam', 'GEN', 47, 7, 'Na Yosevu aete Yakovo ĩthe wake nthĩnĩ, na amwia mbee wa Valao: na Yakovo amũathima Valao.'),
('kam', 'GEN', 47, 8, 'Na Valao akũlya Yakovo, Nĩ meana ata matukũ ma myaka ya thayũ waku?'),
('kam', 'GEN', 47, 9, 'Na Yakovo asũngĩa Valao, Matukũ ma myaka ya ũeni wakwa nĩ myaka ĩana na mĩongo ĩtatũ: matukũ ma myaka ya thayũ wakwa meethĩwe mavũthũ na mathũku, o na matyaaĩanĩa matukũ ma myaka ya thayũ wa aasa makwa matukũnĩ ma kwĩkala ũeni kwoo.'),
('kam', 'GEN', 47, 10, 'Na Yakovo amũathima Valao, na auma vala ve Valao.'),
('kam', 'GEN', 47, 11, 'Na Yosevu amekalya ĩthe na ana‐a‐ĩthe make, na amanenga wĩkalo nthĩ ya Misili, katĩ wa nthĩ ĩla nzeo mbee, nthĩ ya Lamesesi, o tondũ Valao weaie.'),
('kam', 'GEN', 47, 12, 'Na Yosevu aĩthya ĩthe, na ana‐a‐ĩthe, na andũ onthe ma ĩthe wake na lĩu, kwĩanana na mĩvĩa yoo.'),
('kam', 'GEN', 47, 13, 'Na kũtyaĩ lĩu nthĩ ĩsu yonthe; nũndũ yũa yaĩ ĩnene mũno, o na nthĩ ya Misili na nthĩ ya Kanaani nĩsyanyalĩte kwondũ wa yũa.'),
('kam', 'GEN', 47, 14, 'Na Yosevu oomban’ya mbesa syonthe ila syoonekie nthĩ ya Misili, na nthĩ ya Kanaani, kwondũ wa lĩu wa mbaa ngetha ũla mathooie: na Yosevu atwaa ila mbesa nyũmbanĩ ya Valao,'),
('kam', 'GEN', 47, 15, 'Na yĩla mbesa syonthe syathelile nthĩ ya Misili, na nthĩ ya Kanaani, Amisili onthe mamũkĩa Yosevu, na mamwĩa, Tũnenge lĩu: tũkw’e wene nĩkĩ? Nũndũ mbesa sitũ nĩ nthelu.'),
('kam', 'GEN', 47, 16, 'Na Yosevu amea, Umyai indo syenyu: nakwa ngamũnenga kwondũ wa indo syenyu, ethĩwa mbesa nĩ nthelu.'),
('kam', 'GEN', 47, 17, 'Na mamũetee Yosevu indo syoo; na Yosevu amanenga lĩu vandũ va mbalasi, na va ndĩthya sya mbũi na malondu, na va ndĩthya sya ng’ombe, na va mang’oi: na amanenga lĩu vandũ va indo syoo syonthe mwaka ũsu.'),
('kam', 'GEN', 47, 18, 'Na mwaka ũsu wathela, mamũkĩa mwaka wa kelĩ, na mamwĩa, Tũtiũmũvitha mwĩaĩi wakwa, ũndũ mbesa sitũ ĩthelete vyũ; na ndĩthya sya indo nĩ sya mwĩaĩi wakwa; vati kĩndũ kĩtiele mbee wa mwĩaĩi wakwa; ate o mĩĩ yaitũ, na nthĩ sitũ:'),
('kam', 'GEN', 47, 19, 'tũkw’e wene nĩkĩ, ithyĩ o na nthĩ yaitũ? Tũthooe ithyĩ na nthĩ yaitũ kwondũ wa lĩu, na ithyĩ na nthĩ yaitũ tũkeethĩwa athũkũmi ma Valao: naku tũne mbeũ, nĩ kana twĩkale thayũ, tũikakw’e, na nthĩ ndĩkethĩwe nthei.'),
('kam', 'GEN', 47, 20, 'Na ĩndĩ Yosevu amũthooea Valao nthĩ yonthe ya Misili; nũndũ Amisili mathooisye kĩla mũndũ mũũnda wake, nũndũ yũa yamakwatie mũno: na nthĩ yatw’ĩka ya Valao.'),
('kam', 'GEN', 47, 21, 'Nao andũ, amathamĩĩsya ndũanĩ kuma ũtee ũmwe wa mũvaka wa Misili kũvika ũtee ũla ũngĩ wayo.'),
('kam', 'GEN', 47, 22, 'No nthĩ ya athembi ũtaathooa: nũndũ athembi maĩ na kya ũya kyoo kuma kwa Valao, na maya kya ũya kyoo kĩla Valao wamanengie; kwondũ wa ũu matyaathoosya nthĩ yoo.'),
('kam', 'GEN', 47, 23, 'Na ĩndĩ Yosevu amea andũ, Sisya, mũnthĩ ũũ nĩnamũthooa inyw’ĩ, na nthĩ yenyu kwondũ wa Valao: sisya, vaa ve mbeũ kwondũ wenyu, nenyu mũkavanda nthĩ.'),
('kam', 'GEN', 47, 24, 'Na kũkeethĩwa ngethanĩ, mũkanenga Valao kĩlungu kya katano, na ilungu inya ikeethĩwa syenyu ene, sya mbeũ sya mĩũnda, na sya lĩu wenyu, na wa ala ma nyũmba syenyu, na sya lĩu wa syana syenyu nini.'),
('kam', 'GEN', 47, 25, 'Nao mamwĩa, Nũtũtangĩĩĩte mathayũ maitũ; twone ũseo mbee wa mwĩaĩi wakwa, naitũ tũkeethĩwa athũkũmi ma Valao.'),
('kam', 'GEN', 47, 26, 'Na Yosevu atw’a mwĩao kũvika ũmũnthĩ ũũ ũndũ wa nthĩ ya Misili, kana Valao ethĩwe na kĩlungu kya katano; no nthĩ ya athembi yoka ĩtaatw’ĩka ya Valao.'),
('kam', 'GEN', 47, 27, 'Na Isilaeli atũa nthĩ ya Misili, nthĩ ya Ngoseni; na meeyosea mothwii kw’o, na mongeleka na maingĩva mũno.'),
('kam', 'GEN', 47, 28, 'Na Yakovo ekala nthĩ ya Misili myaka ĩkũmi na mũonza: na ĩndĩ matukũ ma Yakovo, myaka ya thayũ wake, yaĩ myaka ĩana na mĩongo ĩna na mũonza.'),
('kam', 'GEN', 47, 29, 'Na ĩvinda ya kũkw’a kwa Isilaeli yathengeea: na amwĩta mwana wake Yosevu, na amwĩa, Ethĩwa yu nĩnona ũseo mbee waku, nĩngũkwĩsũva, ia kw’oko kwaku ungu wa waswa wakwa, ũmbĩke nesa na w’o: nĩngũkwĩsũva, ndũkaanthike kũũ Misili;'),
('kam', 'GEN', 47, 30, 'ĩndĩ nakoma vamwe na aasa makwa, ũkangua kuma Misili, ũkanthike vandũ voo va ũthikwa. Na asũngĩa, Ngeeka ũndũ wasya.'),
('kam', 'GEN', 47, 31, 'Nake amwĩa, Ĩndavĩe: nake amwĩavĩa. Na Isilaeli eekunamya mũtwenĩ wa ũkomo.'),
('kam', 'GEN', 48, 1, 'Na kweethĩwa ĩtina wa maũndũ asu, mũndũ ũmwe amwĩa Yosevu, Sisya, au nĩ mũwau: nake aenda na ana make elĩ, Manase na Evalaimu.'),
('kam', 'GEN', 48, 2, 'Na ũmwe atavya Yakovo, na asya, Sisya, mwana waku Yosevu nũnũũkũkĩa: na Isilaeli eevandĩĩa, ekala ĩũlũ wa ũkomo.'),
('kam', 'GEN', 48, 3, 'Na Yakovo amwĩa Yosevu, Ngai Mwene Vinya W’onthe anumĩlĩle Lusu nthĩ ya Kanaani, na angathima,'),
('kam', 'GEN', 48, 4, 'na ambĩa, Sisya, ngakwongela, na ngakwingĩvya, na ngakũtw’ĩkĩthya nguthu ya mbaĩ, na nthĩ ĩno nganenga ũsyao waku ĩtina waku yĩthĩwe ng’ũndũ tene na tene.'),
('kam', 'GEN', 48, 5, 'Na yu ĩndĩ ana maku elĩ, ala wasyaĩwe nthĩ ya Misili ndanoka kwaku Misili, nĩ makwa; Evalaimu na Manase, makeethĩwa makwa, o ta Leuveni na Simeoni.'),
('kam', 'GEN', 48, 6, 'Na ũsyao waku, ũla ũkasyaa ĩtina wa aa, ũkeethĩwa waku; makeetawa kũatĩĩa syĩtwa ya ana‐a‐ĩthe moo ũtiĩwanĩ woo.'),
('kam', 'GEN', 48, 7, 'Nakwa, yĩla naumĩte Vatani, nakw’ĩĩwe nĩ Lakeli nzĩanĩ nthĩ ya Kanaani, yĩla vatiele o mũendo nĩvike Evilathi: na namũthikie vo nzĩanĩ ya Evilathi (nĩyo Mbethi‐leemu).'),
('kam', 'GEN', 48, 8, 'Na Isilaeli oona ana ma Yosevu, na akũlya, Aa naaũ?'),
('kam', 'GEN', 48, 9, 'Na Yosevu amwĩa ĩthe, Aa nĩ ana makwa, ala Ngai wanengee kũũ. Na amwĩa, Nĩngũkwĩsũva, maete vaa nĩĩ, nakwa nĩngũmaathima.'),
('kam', 'GEN', 48, 10, 'Na ĩndĩ metho ma Isilaeli maĩ mbindu nũndũ wa kũkũa, ũndũ ũtatonya kwona. Na amathengeesya kwake, na amamumunya, na amevĩtĩĩsya.'),
('kam', 'GEN', 48, 11, 'Na Isilaeli amwĩa Yosevu, Ndyaatalĩlya kwona ũthyũ waku: na, sisya, Ngai nũnengete kwona ũsyao waku naw’o.'),
('kam', 'GEN', 48, 12, 'Na Yosevu amaumya katĩ wa mau make; na eekunamya ũthyũ wake welekele nthĩ.'),
('kam', 'GEN', 48, 13, 'Na Yosevu amatwaa me elĩ, Evalaimu kw’okonĩ kwake kwa aũme elekele kw’oko kwa aka kwa Isilaeli, na Manase kw’okonĩ kwake kwa aka elekele kw’oko kwa aũme kwa Isilaeli, amathengeesya vala ũĩ.'),
('kam', 'GEN', 48, 14, 'Na Isilaeli atambũũkya kw’oko kwake kwa aũme, ailĩĩla mũtwenĩ wa Evalaimu, ũla waĩ mũnini, na kw’oko kwake kwa aka ailĩĩla mũtwenĩ wa Manase, aivĩtan’ya moko make kwa kũmanya; nũndũ Manase aĩ ĩkithathi.'),
('kam', 'GEN', 48, 15, 'Na amũathima Yosevu, na asya, Ngai ũla aasa makwa Avalaamu na Isaka maendaa mbee wake, Ngai ũla wandĩthisye thayũ wakwa w’onthe kũvika mũnthĩ ũũ,'),
('kam', 'GEN', 48, 16, 'mũlaĩka ũla wambovoisye kuma ũthũkunĩ w’onthe, aathime imwana; na syĩtwa yakwa yĩtanĩaw’e nasyo, na syĩtwa ya aasa makwa Avalaamu na Isaka; nao nĩmeane methĩwe nguthu katĩ wa nthĩ.'),
('kam', 'GEN', 48, 17, 'Na Yosevu oona kana ĩthe wake ailĩĩla kw’oko kwake kwa aũme mũtwenĩ wa Evalaimu, ndaendeew’a: na ookĩlya kw’oko kwa ĩthe, nĩ kana akumye mũtwenĩ wa Evalaimu, ailĩĩle mũtwenĩ wa Manase.'),
('kam', 'GEN', 48, 18, 'Na Yosevu amwĩa ĩthe, Ti w’o, nau; nũndũ ũũ nĩwe ĩkithathi; ilĩĩla kw’oko kwaku kwa aũme mũtwenĩ wake.'),
('kam', 'GEN', 48, 19, 'Na ĩthe alea, na amwĩa, Nĩnĩsĩ, mwana wakwa, nĩnĩsĩ; nake we akatw’ĩka mbaĩ, nake we akeethĩwa mũnene: ĩndĩ nĩ w’o mũinae akeethĩwa mũnene kwĩ we, na ũsyao wake ũkatw’ĩka mbaĩ mbingĩ mũno.'),
('kam', 'GEN', 48, 20, 'Na mũthenya ũsu amaathima, akyasya, Kwaku nthĩnĩ waku Isilaeli makaathimaa, makyasya, Ngai namũtw’ĩkĩthye ta Evalaimu na ta Manase: na amwia Evalaimu mbee wa Manase.'),
('kam', 'GEN', 48, 21, 'Na Isilaeli amwĩa Yosevu, Sisya, nĩngũkw’a: ĩndĩ Ngai akeethĩwa vamwe nenyu, na akamũtũnga ĩngĩ nthĩ ya aaĩthe menyu.'),
('kam', 'GEN', 48, 22, 'Nakwa nĩnakũnenga kĩlungu kĩmwe mbee wa ana‐a‐au, kĩla naumisye kw’okonĩ kwa Mũamoli na ũvyũ wakwa na ũta wakwa.'),
('kam', 'GEN', 49, 1, 'Na Yakovo ameta ana make, na amea, Ũmbanai vamwe, nĩmũtavye maũndũ ala makamũkĩtĩkĩa mĩthenya ya mũminũkĩlyo.'),
('kam', 'GEN', 49, 2, 'Ũmbanai, na ĩw’ai, inyw’ĩ ana ma Yakovo; Na mwĩthukĩĩsyei Isilaeli ĩthe wenyu.'),
('kam', 'GEN', 49, 3, 'Leuveni, nue ĩkithathi yakwa, vinya wakwa, na mwambĩlĩlyo wa ũtonyi wakwa; Ũnene wa kũkathwa, na ũnene wa ũtonyi.'),
('kam', 'GEN', 49, 4, 'Mũtheũkangi ta manzĩ, ndũkethĩwa na ũnene; Nĩkwĩthĩwa nĩwatũlile ũkomonĩ wa aũ; Na ĩndĩ woovukya: atũla ũkomonĩ wakwa.'),
('kam', 'GEN', 49, 5, 'Simeoni na Livai nĩ ma ĩthe ũmwe; Mĩio ya ũng’endu nĩ mbyũ syoo.'),
('kam', 'GEN', 49, 6, 'We ngoo yakwa, ndũkalike nzamanĩ yoo; We ndaĩa yakwa, ndũkalũman’ye na ũmbano woo; Nũndũ nĩmooaie mũndũ ũthatunĩ woo, Na nũndũ wa ngũlũ syoo matema nzaũ mũlangũ.'),
('kam', 'GEN', 49, 7, 'Nũumanĩwe ũthatu woo, nũndũ waĩ mwai; Na ũthilĩku woo, nũndũ waĩ ũng’endu: Ngamaan’ya nthĩnĩ wa Yakovo, Na kũmanyaĩĩkya katĩ wa Isilaeli.'),
('kam', 'GEN', 49, 8, 'Yuta, nue ũkataĩawa nĩ ana‐a‐au: Kw’oko kwaku kũkakwataa ngingo ya amaitha maku; Ana ma au makakwĩkunamĩasya.'),
('kam', 'GEN', 49, 9, 'Yuta nĩ ĩswii ya mũnyambũ; Nĩwambata, mwana wakwa, kuma nzyĩmanĩ: Amamĩlĩla, oovesya ta mũnyambũ, Na ta mũnyambũ mũka; nũũ ũkamũamũkya?'),
('kam', 'GEN', 49, 10, 'Ndata ya ũsumbĩ ndĩkauma kwa Yuta, O na ndata ya mũsumbĩki ndĩkauma katĩ wa maũũ make, Kũvika yĩla Silo ũkoka; Na kwĩw’awa nĩ ngo sya andũ kũkeethĩwa kwake we.'),
('kam', 'GEN', 49, 11, 'Akyova katena kake mũsavivũnĩ, Na ndena ya ĩng’oi yake mũsavivũnĩ mũseo; Nũthambĩtye ngũa syake mbinyunĩ, Na ngũa yake ndasa nthakamenĩ ya nzavivũ:'),
('kam', 'GEN', 49, 12, 'Metho make makeethĩwa me matune nũndũ wa mbinyu, Na maeo make meũ nũndũ wa ĩia.'),
('kam', 'GEN', 49, 13, 'Nzevuluni akekala kĩthũmũonĩ ũkanganĩ; Nake akeethĩwa e kĩthũmũo kya ngalawa; Na mũvaka wake ũkeethĩwa Sitoni.'),
('kam', 'GEN', 49, 14, 'Isakali nĩ ĩng’oi yĩ vinya, Akyoveesya katĩ wa syengo sya malondu:'),
('kam', 'GEN', 49, 15, 'Nake oona vandũ va ũthũmũo atĩ nĩ vaseo, Na nthĩ atĩ nĩyendeesye; Na akunamya kĩtuo kyake akue, Na atw’ĩka mũthũkũmi wĩanĩ wĩ vinya.'),
('kam', 'GEN', 49, 16, 'Ndani akasilĩla andũ make, Ta mbaĩ ĩmwe ya Isilaeli.'),
('kam', 'GEN', 49, 17, 'Ndani akeethĩwa nzoka nzĩanĩ, Kĩmbuva ũendelonĩ, Ĩla ĩũmaa mbalasi mathaio, Na kwondũ wa ũu mũtũli wayo akĩvalũka na ngala.'),
('kam', 'GEN', 49, 18, 'Ame Yeova, nĩneteelete ũtangĩĩo waku.'),
('kam', 'GEN', 49, 19, 'Ngati, nguthu ĩkamũvivinya; Ĩndĩ akavivinya kĩtiinyo kyayo.'),
('kam', 'GEN', 49, 20, 'Kuma kwa Aseli lĩu wake ũkeethĩwa wĩ mũnou, Nake akaumya kya ũya kĩseo kya kĩũsumbĩ.'),
('kam', 'GEN', 49, 21, 'Navitali nĩ ndaatai ĩla yathaiw’e: Aumasya ndeto nzeo.'),
('kam', 'GEN', 49, 22, 'Yosevu nĩ ũvonge wĩ na ũsyao, Ũvonge wĩ na ũsyao vakuvĩ na nthongo; Nthanzu syake ing’okelaa ũvainĩ.'),
('kam', 'GEN', 49, 23, 'Andũ ma mata nĩmamwĩw’ĩthĩtye woo mũno, Na mamũatha, na kũmũthĩn’ya:'),
('kam', 'GEN', 49, 24, 'Ĩndĩ ũta wake wekala na vinya, Na moko ma itaa syake meekĩwa vinya Nĩ moko ma Ũla Mwene Vinya wa Yakovo (Kuma kũu nĩ ũla mũĩthi, nĩwe ĩvia ya Isilaeli),'),
('kam', 'GEN', 49, 25, 'O kwondũ wa Ngai wa au, ũla ũkakũtethya, Na kwondũ wa Mwene Vinya W’onthe ũla ũkakũathima, Na moathimo ma ĩtunĩ ĩũlũ, Moathimo ma syũngũ ila syĩkalaa ĩtheo, Moathimo ma nondo, na ma ĩvu.'),
('kam', 'GEN', 49, 26, 'Moathimo ma au Nĩmakĩlĩtye vinya mbee wa moathimo ma aasa makwa Kũvika mũthelelo wa iĩma sya tene na tene: Makeethĩwa mũtwenĩ wa Yosevu, Na lolotyanĩ wa ũsu ũla wataanĩtw’e na ana‐a‐ĩthe make.'),
('kam', 'GEN', 49, 27, 'Mbenyamini nĩ nzũi ĩla ĩtembũangaa: Kwakya akaya sya nzyĩma, Na wĩoo akaaan’ya mũtavo.'),
('kam', 'GEN', 49, 28, 'Isu syonthe nĩ mbaĩ ĩkũmi na ilĩ sya Isilaeli: na ũu nĩw’o ũla ĩthe woo waneenie nao na amaathima, kĩla ũmwe kwaĩnana na ũathimo wake amaathima.'),
('kam', 'GEN', 49, 29, 'Na ameaĩa, na amea, Nyie nĩngũmbanw’a vamwe na andũ makwa: mũnthikei vamwe na aasa makwa ngũnganĩ ĩla yĩ kĩsesinĩ kya Eveloni Mũititi,'),
('kam', 'GEN', 49, 30, 'nguganĩ ĩla yĩ kĩsesinĩ kĩ Makivela, ĩla yĩ mbee wa Mamile, nthĩ ya Kanaani, ĩla Avalaamu wamũthooee Eveloni Mũititi vamwe na kĩsesi vethĩwe vandũ vake va mbũa.'),
('kam', 'GEN', 49, 31, 'Kũu mathikie Avalaamu na Sala mũka wake; kũu mathikie Isaka na Leveka mũka wake; na kũu nathikie Lea—'),
('kam', 'GEN', 49, 32, 'kĩsesi na ngunga ĩla yĩ nthĩnĩ wakyo, ĩla namathooee ana ma Ethi.'),
('kam', 'GEN', 49, 33, 'Na yĩla Yakovo waminie kũmeaĩa ana make, aluta maũũ make ũkomonĩ, na aumwa nĩ veva, na oombanw’a vamwe na andũ make.'),
('kam', 'GEN', 50, 1, 'Na Yosevu amũvalũkĩla ĩthe wake ũthyũ, na amũĩĩa, na amũmumunya.'),
('kam', 'GEN', 50, 2, 'Na Yosevu ameaĩa athũkũmi make aiiti mekĩe kimba kya ĩthe wake mũtĩ: na ala aiiti meekĩa kimba kya Isilaeli mũtĩ.'),
('kam', 'GEN', 50, 3, 'Na matukũ mĩongo ĩna meanĩw’a kwondũ wake; nĩkwĩthĩwa nĩw’o meanĩw’a matukũ ma kwĩkĩa kimba mũtĩ: na Amisili mamũĩĩa matukũ mĩongo mũonza.'),
('kam', 'GEN', 50, 4, 'Na matukũ ma kũmũĩĩa mathela, Yosevu aneena na andũ ma nyũmba ya Valao, akĩmea, Ethĩwa yu nĩnonete ũseo methonĩ menyu, nĩngũmwĩsũva, neenai matũnĩ ma Valao, mũkĩmwĩa,'),
('kam', 'GEN', 50, 5, 'Nau nĩwambĩavĩthisye, akĩmbĩa, Sisya, nĩngũkw’a: mbũanĩ yakwa ĩla neeyĩnzĩe nthĩ ya Kanaani, kũu mũkanthika. Na yu ĩndĩ, nĩngũkwĩsũva, eka nambate nĩthike nau, na ngĩsyoka ĩngĩ.'),
('kam', 'GEN', 50, 6, 'Na Valao amwĩa, Ambata, ũthike au, kwĩanana na ũndũ wakwĩavĩthisye.'),
('kam', 'GEN', 50, 7, 'Na Yosevu ambata athike ĩthe wake; na athũkũmi onthe ma Valao mambata vamwe nake, atumĩa ma nyũmba yake, na atumĩa onthe ma nthĩ ya Misili,'),
('kam', 'GEN', 50, 8, 'na andũ onthe ma nyũmba ya Yosevu, na ana‐a‐ĩthe make, na andũ ma nyũmba ya ĩthe wake: no syana syoo nini, na ndĩthya syoo sya mbũi na malondu na ndĩthya syoo sya ng’ombe, matiie nthĩ ya Ngoseni.'),
('kam', 'GEN', 50, 9, 'Na vambata vamwe nake makasya o na ala matũlĩte mbalasi: na meethĩwa nguthu nene mũno.'),
('kam', 'GEN', 50, 10, 'Na mavika kĩvũĩoni kya Atati, kĩla kĩ mũingo wa Yolotani, kw’o maĩĩa kĩĩo kĩnene mũno kĩ woo: na aseũvya maĩo kwondũ wa ĩthe wake matukũ mũonza.'),
('kam', 'GEN', 50, 11, 'Na ala matwĩe nthĩ ĩsu, Akanaani, moona ala maĩo kĩvũĩonĩ kya Atati, masya, Aa nĩ maĩo me woo kwa Amisili: kwondũ wa wa ũu syĩtwa ya vo veetwa Aveli‐misili, na vo nĩ mũingo wa Yolotani.'),
('kam', 'GEN', 50, 12, 'Na ana make mamwĩka kwĩanana na ũndũ wameaĩe:'),
('kam', 'GEN', 50, 13, 'nũndũ ana make nĩmamũkuie mamũtwaa nthĩ ya Kanaani, na mamũthika ngunganĩ ya kĩsesi kĩ Makivela, ĩla Avalaamu wamũthooee Eveloni Mũititi, vu mbee wa Mamile, vamwe na kĩsesi, vethĩwe vake va mbũa.'),
('kam', 'GEN', 50, 14, 'Na Yosevu asyoka Misili ĩtina wa kũthika ĩthe wake, we na ana‐a‐ĩthe na onthe ala mambatie vamwe nake kũthika ĩthe wake.'),
('kam', 'GEN', 50, 15, 'Na yĩla ana‐a‐ĩthe ma Yosevu moonie kana ĩthe woo nũnakwie, masya, Nokwĩthĩwa Yosevu atũmena, na kwĩĩvanĩsya vyũ ũthũku w’onthe ũla twamwĩkie.'),
('kam', 'GEN', 50, 16, 'Na matũma ũtũmane kwa Yosevu, makĩmwĩa, Au atanakw’a eaie, akyasya,'),
('kam', 'GEN', 50, 17, 'Neenai ũũ na Yosevu, Nĩngũkwĩsũva yu, ekea ana‐a‐au ĩvĩtyo na naĩ yoo, nĩkwĩthĩwa nĩmakwĩkie ũthũku. Na yu ĩndĩ, nĩtũũkwĩsũva, ekea athũkũmi ma Ngai wa au ĩvĩtyo yoo. Na Yosevu aĩa yĩla maneenie nake.'),
('kam', 'GEN', 50, 18, 'Na ĩngĩ ana‐a‐ĩthe mathi na mavalũka nthĩ mbee wa ũthyũ wake; na mamwĩa, Sisya, ithyĩ twĩ athũkũmi maku.'),
('kam', 'GEN', 50, 19, 'Na Yosevu amea, Mũikakĩe: nũndũ nyie nĩ vandũ va Ngai?'),
('kam', 'GEN', 50, 20, 'Nenyu nĩmwanzũanĩĩe ũthũku; ĩndĩ Ngai asũanĩa wĩthĩwe ũseo, kwĩkĩke, o tondũ kũilyĩ mũnthĩ ũũ, nĩtangĩĩe andũ aingĩ mekale thayũ.'),
('kam', 'GEN', 50, 21, 'Kwondũ wa ũu mũikakĩe: ngamũĩthya inyw’ĩ, na syana syenyu nini. Na amakiakisya, na aneena nesa nao.'),
('kam', 'GEN', 50, 22, 'Na Yosevu atũa Misili, we, na andũ ma nyũmba ya ĩthe: na Yosevu ekala myaka ĩana na ĩkũmi.'),
('kam', 'GEN', 50, 23, 'Na Yosevu oona syana sya Evalaimu kũvika nzyawa itatũ: syana sya Makili mwana wa Manase nasyo syaasyaĩwe maunĩ ma Yosevu.'),
('kam', 'GEN', 50, 24, 'Na Yosevu amea ana‐a‐ĩthe, Nyie nĩngũkw’a; ĩndĩ nĩ w’o Ngai akamũkĩa inyw’ĩ, na kũmwambatya kuma nthĩ ĩno kũvika nthĩ ĩla wevĩtĩe Avalaamũ, na Isaka, na Yakovo.'),
('kam', 'GEN', 50, 25, 'Na Yosevu eeavĩthya ana ma Isilaeli, akĩmea, Nĩ w’o Ngai akamũkĩa na mũkakua mavĩndĩ makwa mwambatye kuma kũũ.'),
('kam', 'GEN', 50, 26, 'Na ĩndĩ Yosevu akw’a, e wa myaka ĩana na ĩkũmi ũkũũ wake: na meekĩa kimba kyake mũtĩ, na eekĩĩwa ĩsandũkũnĩ Misili.'),
('kam', 'EXO', 1, 1, 'Na masyĩtwa ma ana ma Isilaeli ala malikile Misili nĩmo aa (o kĩla mũndũ na andũ ma nyũmba yake mookie na Yakovo):'),
('kam', 'EXO', 1, 2, 'Leuveni, na Sĩmeoni, na Livai, na Yuta,'),
('kam', 'EXO', 1, 3, 'na Isakali, na Nzevuluni, na Mbenyamini,'),
('kam', 'EXO', 1, 4, 'na Ndani, na Navitali, na Ngati, na Aseli.'),
('kam', 'EXO', 1, 5, 'Na andũ onthe ala maumie kĩnyunyunĩ kya Yakovo maĩ andũ mĩongo mũonza: nake Yosevu aĩ o ku Misili.'),
('kam', 'EXO', 1, 6, 'Na Yosevu akw’a, na ana‐a‐ĩthe make onthe, na nzyawa ĩsu yonthe.'),
('kam', 'EXO', 1, 7, 'Na ana ma Isilaeli masyaanie, na maingĩva mũno, na kwongelela, na maendeea na kũya vinya mũno; na nthĩ yausũwa nĩo.'),
('kam', 'EXO', 1, 8, 'Na ĩndĩ kwookĩla mũsumbĩ ũngĩ Misili, ũla ũtamwĩsĩ Yosevu.'),
('kam', 'EXO', 1, 9, 'Na amea andũ make, Sisyai, andũ ma ana ma Isilaeli nĩ aingĩ na me na vinya kwĩ ithyĩ:'),
('kam', 'EXO', 1, 10, 'yuyu ĩndĩ tũmekei na ũĩ, matikese kwingĩva, na kũkeethĩwa, yĩla kaũ o na wĩva ũkokĩla, nao makeevulan’ya na amaitha maitũ, na kũkita naitũ, na makyuma nthĩ ĩno.'),
('kam', 'EXO', 1, 11, 'Kwondũ wa ũu mamaiĩa aũngamĩi nĩ kana mamathĩn’ye na mĩio yoo. Nao mamwakĩa Valao ndũa sya kwia mĩio, Vithomu na Lamesesi.'),
('kam', 'EXO', 1, 12, 'Ĩndĩ makĩendeea na kũmathĩn’ya, namo maendeea kwingĩva na kusũa nthĩ. Na maĩ na woo kwondũ wa ana ma Isilaeli.'),
('kam', 'EXO', 1, 13, 'Na Amĩsili mamathũkũmĩthya ana ma Isilaeli na vinya mũno:'),
('kam', 'EXO', 1, 14, 'na meekĩa ũũ mathayũnĩ moo kwondũ wa ũthũkũmi wi vinya, wa ndaka, na wa mavali, na wĩa w’onthe wa mĩũndanĩ, ũthũkũmi woo w’onthe ũla mamathũkũmĩthisye na vinya mũno.'),
('kam', 'EXO', 1, 15, 'Na mũsumbĩ wa Misili aneena na esikya Aevelania, syĩtwa ya ũmwe eetawa Sivila, na syĩtwa ya ũngĩ eetawa Vua:'),
('kam', 'EXO', 1, 16, 'na amea, Yĩla mũkwĩsikya aka ma Aevelania, na kũmona makĩsyaa; ethĩwa nĩ kavĩsĩ, koaei ĩndĩ; ethĩwa nĩ kelĩtu, nĩkaekwe kekale thayũ.'),
('kam', 'EXO', 1, 17, 'Ĩndĩ esikya mamũkĩa Ngai, na maiaaĩka tondũ mũsumbĩ wa Misili wameaĩe, ĩndĩ maeka twana twa tũvĩsĩ twĩ thayũ.'),
('kam', 'EXO', 1, 18, 'Na mũsumbĩ wa Misili eeta esikya, na amakũlya, Mwĩkĩte ũndũ ũũ nĩki, mũkĩeka twana twa tũvĩsĩ twĩ thayũ?'),
('kam', 'EXO', 1, 19, 'Na esikya mamwĩa Valao, Nĩkwĩthĩwa aka ma Aevelania matiilyĩ aka ma Amisili; nũndũ nĩ athangaau, na nĩmasyaaa mwĩsikya atanavika.'),
('kam', 'EXO', 1, 20, 'Na Ngai ameka esikya nesa: na andũ maingĩva, na maya vinya mũnene.'),
('kam', 'EXO', 1, 21, 'Na kweethĩwa, nũndũ esikya mamũkĩaa Ngaĩ, amanenga ũsyao.'),
('kam', 'EXO', 1, 22, 'Na Valao ameaĩa andũ make onthe, akĩmea, Kĩla kana ka kavĩsĩ kasyawa kekasyei ũsĩnĩ, na kĩla kana ka kelĩtu kaekaei kekale thayũ.'),
('kam', 'EXO', 2, 1, 'Na kwaenda mũndũ wa nyũmba ya Livai, na amũtwaa mwĩĩtu wa a Livai.'),
('kam', 'EXO', 2, 2, 'Na mũndũ mũka ũsu aitava, na asyaa mwana: na oona kana nĩ kana kaseo, akavitha myei ĩtatũ.'),
('kam', 'EXO', 2, 3, 'Na yĩla ũtaatonya kũkavithĩkya, akosea kakalawa ka malula na akavaka lami na kĩsia; na eekĩa kala kana nthĩnĩ, na aia makangaanĩ ũtee wa ũsĩ.'),
('kam', 'EXO', 2, 4, 'Na mwĩĩtu‐a‐inyia wako aũngama kũasa amanye ũndũ keĩkwa.'),
('kam', 'EXO', 2, 5, 'Na mwĩĩtu wa Valao atheea ũsĩnĩ atuunye; na athũkũmi make eĩtu matambũka ũtee wa ũsĩ; nake oona kakalawa nthĩnĩ wa makangaa, na atũma mũthũkũmi wake mwĩĩtu aete.'),
('kam', 'EXO', 2, 6, 'Na akavingũa, na oona kala kana: na, sisya, kana nĩkaĩaa. Na akew’ĩa ĩnee, na asya, Kaa nĩ kamwe ka ana ma Aevelania.'),
('kam', 'EXO', 2, 7, 'Na ĩndĩ mwĩĩtu‐ainyĩa wako akũlya mwĩĩtu wa Valao, Nĩende nĩkwĩtĩe mũei akanĩ ma Aevelania, akũee kana?'),
('kam', 'EXO', 2, 8, 'Na mwĩĩtu wa Valao amwia, Enda. Na ũla mwĩĩtu athi, eeta inyia wa kala kana.'),
('kam', 'EXO', 2, 9, 'Na mwĩĩtu wa Valao amwĩa, Kua kana kaa ũthi nako ũkandee, na ngaũnenga ĩtuvi yaku. Na ũla mũndũ mũka akua kana, na akaea.'),
('kam', 'EXO', 2, 10, 'Na kana keana, na akaete kwa mwĩĩtu wa Valao, na katw’ĩka mwana wake. Na syĩtwa yake amwĩta Mose, na asya, Nĩkwĩthĩwa nĩnamumisye manzĩnĩ.'),
('kam', 'EXO', 2, 11, 'Na kweethĩwa mĩthenya ĩsũ, yĩla Mose weanie, aenda kwa ana‐a‐ĩthe make, na asisya mĩio yoo: na oona Mũmisili akĩmũkũna Mũevelania, ũmwe wa ana‐a‐ĩthe make.'),
('kam', 'EXO', 2, 12, 'Na asisya kũũ na kũũ, na yĩla wonĩe atĩ vati mũndũ, amũaa ũla Mũmisili, na amumbĩka kĩthangathĩnĩ.'),
('kam', 'EXO', 2, 13, 'Na aumaala ũnĩ ũsu, na, sĩsya, andũ elĩ ma Aevelania nĩmokitaa ene kwa ene: na amwĩa ũla ũmũtheie ũngĩ, Wĩmũkũna mũtindan’ya waku nĩkĩ?'),
('kam', 'EXO', 2, 14, 'Nake amũkũlya, Ũla ũkũtw’ĩte mũnene na mũsili ĩũlũ waitũ nũũ? Wĩsũanĩa kũmbũaa, o tondũ ũnamũaie ũla Mũmisili? Na Mose atelema, na asya, Kaĩ ũndũ ũsu nĩ ũmanyĩku.'),
('kam', 'EXO', 2, 15, 'Na ĩndĩ yĩla Valao wewie ũndũ ũsu, enda kũmũaa Mose. Ĩndĩ Mose akĩa, auma kwa Valao, na atũa nthĩ ya Mitiani: na ekala nthĩ ũtee wa kĩthima.'),
('kam', 'EXO', 2, 16, 'Na ĩndĩ mũthembi wa Mitiani aĩ na eĩtu mũonza: nao mooka na matava manzĩ, na mausũsya mĩvalati manzĩ manyithye ndĩthya ya mbũi na malondu ya ĩthe woo.'),
('kam', 'EXO', 2, 17, 'Na aĩthi mooka na mamalũngya; ĩndĩ Mose ookĩla na amatethya, na anyĩthya ndĩthya yoo.'),
('kam', 'EXO', 2, 18, 'Na yila mookie vala Leueli ĩthe woo ũĩ, amakũlya, Ũmũnthĩ mwooka mĩtũkĩ ũũ ata?'),
('kam', 'EXO', 2, 19, 'Na mamwĩa, Mũmisili nũtũvonokisye mokonĩ ma aĩthi, o na ĩngĩ nũtũtavĩĩe manzĩ, na anyithya ndĩthya.'),
('kam', 'EXO', 2, 20, 'Na akũlya eĩtũ make, Na aĩva? Mũtiie mũndũ ũsu nĩkĩ? Mwĩtei, aye lĩu.'),
('kam', 'EXO', 2, 21, 'Na Mose eanĩwa nĩ kwĩkala na mũndũ ũsu: na amũnenga Mose Nzivola mwĩĩtu wake.'),
('kam', 'EXO', 2, 22, 'Na asyaa mwana, nake amwĩta syĩtwa yake Ngelisoni; nũndũ aisye, Nĩnaĩ mwĩkali wa ũeninĩ nthĩ ĩngĩ.'),
('kam', 'EXO', 2, 23, 'Na kweethĩwa matukũ asu maingĩ mathela, mũsumbĩ wa Misili akw’a: na ana ma Isilaeli mavevũũka kwondũ wa ũkombo ũsu, na maĩa, na kĩĩo kyoo kwondũ wa ũla ũkombo kyavika kwa Ngai.'),
('kam', 'EXO', 2, 24, 'Na Ngai eew’a kũluma kwoo, na Ngai alilikana ũtianĩo wake na Avalaamu, na Isaka, na Yakovo.'),
('kam', 'EXO', 2, 25, 'Na Ngai oona ana ma Isilaeli, na Ngaĩ asisya ũndũ woo.'),
('kam', 'EXO', 3, 1, 'Na ĩndĩ Mose eethĩwa akĩĩthya ndĩthya ya mbũi na malondu ya Yethilo mũthoni wake, mũthembi wa Mitiani: na atongoesya ĩla ndĩthya avĩtĩlya weũnĩ, na avika kĩĩma kya Ngai o Olevu.'),
('kam', 'EXO', 3, 2, 'Na mũlaĩka wa Yeova amumĩlĩla ũlĩlĩnzĩnĩ wa mwaki ũla wakanĩte kakuthunĩ katĩ: na oona, na, sisya, kakuthu nĩkakanĩte mwaki, na kakuthu katyavĩsaa.'),
('kam', 'EXO', 3, 3, 'Na Mose asya, Nĩngwathũka yu none ũndũ ũũ ũnene, na kĩla kĩũtuma kakuthu katavya.'),
('kam', 'EXO', 3, 4, 'Na yĩla Yeova wonie kana nĩwathũka ũtee one, Ngai amwĩta kuma kakuthunĩ katĩ, na amwĩa, Mose, Mose. Nake eetĩka, Ninyioo.'),
('kam', 'EXO', 3, 5, 'Na amwĩa, Ndũkathengeee vaa: umya iatũ syaku maũũnĩ maku, nũndũ vau ũũngeme nĩ vandũ vatheu.'),
('kam', 'EXO', 3, 6, 'Na ĩngĩ amwĩa, Nyie ninyie Ngai wa ĩthe waku, Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo. Na Mose avitha ũthyũ wake; nũndũ akĩa kũmũsisya Ngai.'),
('kam', 'EXO', 3, 7, 'Na Yeova amwĩa, Nĩ w’o, nĩnonete thĩna wa andũ makwa ala me Misili, na ngew’a ũkayo woo kwondũ wa aũngamĩi moo; nũndũ nĩnĩsĩ mathĩna moo;'),
('kam', 'EXO', 3, 8, 'nakwa nĩtheete nĩmavonokye mokonĩ ma Amisili, na kũmaumya nthĩ ĩsu nĩmatwae nthĩ nzeo na nene, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ; o kũndũ kwa Mũkanaani, na Mũititi, na Mũamoli, na Mũvelisi, na Mũivi, na Mũyevusi.'),
('kam', 'EXO', 3, 9, 'Na yu sisya, kĩĩo kya ana ma Isilaeli nĩkĩvikĩte kwakwa: na ĩngĩ nĩnonete mathĩna ũndũ Amisili mamathĩnasya.'),
('kam', 'EXO', 3, 10, 'Ũkĩla ĩndĩ yu, na nĩngũũtũma kwa Valao, nĩ kana wumye andũ makwa, ana ma Isilaeli, Misili.'),
('kam', 'EXO', 3, 11, 'Na Mose amwĩa Ngai, Nyie nĩ ũũ, nĩende kwa Valao, na nĩ kana nyie numye ana ma Isilaeli Misili?'),
('kam', 'EXO', 3, 12, 'Na amwĩa, Vate ndĩi ngeethĩwa vamwe naku; na ũndũ ũũ ũkeethĩwa kĩmanyĩthya kwaku kana nĩngũtũmĩte: waumya andũ Misili, mũkathũkũma Ngai kĩĩmanĩ kĩĩ.'),
('kam', 'EXO', 3, 13, 'Na Mose amwĩa Ngai, Sisya, yĩla nĩendea ana ma Isilaeli, na ngĩmea, Ngai wa aaĩthe menyu nũndũmĩte kũla mũi namo makangũlya, Syĩtwa yake nata? Ngamea ata?'),
('kam', 'EXO', 3, 14, 'Na Ngai amwĩa Mose, NINYIE ŨLA NINYIE: na amwĩa, Ũũ nĩw’o wĩtavya ana ma Isilaeli, NINYIE nĩwe ũndũmĩte kũla mũĩ.'),
('kam', 'EXO', 3, 15, 'Na ĩngĩ Ngai amwĩa Mose, Ũũ nĩw’o wĩtavya ana ma Isilaeli, Yeova, Ngai wa aaĩthe menyu, Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo, nũndũmĩte kũla mũĩ: yĩu nĩyo syĩtwa yakwa kũvika tene na tene, nayo nĩ ya kũndilikana kũvika nzyawa syonthe.'),
('kam', 'EXO', 3, 16, 'Enda, ũkomban’ye atumĩa ma Isilaeli, ũmee atĩĩ, Yeova, Ngai wa aaĩthe menyu, Ngai wa Avalaamu, na wa Isaka, na wa Yakovo, nĩwanumĩlĩle, akĩmbĩa, Nĩ w’o, nĩnamũkĩie na noona ũla mweekĩwe Misili:'),
('kam', 'EXO', 3, 17, 'nakwa nĩneenete atĩĩ, Ngamumya monyamaonĩ ma Misili na kũmũvikya nthĩ ya Mũkanaani, na Mũititi, na Mũamoli, na Mũvelisi, na Mũivi, na Mũyevusi, o nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'EXO', 3, 18, 'Na makeethukĩĩsya wasya waku: naku we na atumĩa ma Isilaeli mũkathi kwa mũsumbĩ wa Misili, na mũkĩmwĩa, Yeova, Ngai wa Aevelania, nĩwakomanie naitũ: na yu nĩtũũkwĩsũva, tũnenge ũtheĩ wa kũthi weũnĩ kyalo kya mĩthenya ĩtatũ, tũmũthembee Yeova Ngai waitũ.'),
('kam', 'EXO', 3, 19, 'Nakwa nĩnĩsĩ kana mũsumbĩ wa Misili ndakamũlekya mũthi, aiee, o na kwa kw’oko kwĩ vinya.'),
('kam', 'EXO', 3, 20, 'Na ngatambũũkya kw’oko kwakwa, na ngĩkũna Misili na syama syakwa syonthe ila ngeka katĩ wayo: na ĩtina wa ũu akamũlekya mũthi.'),
('kam', 'EXO', 3, 21, 'Na ngamendethya andũ aa kũla kwĩ Amisili: na kũkeethĩwa, mũkĩthi, mũtikaenda mwĩ athei:'),
('kam', 'EXO', 3, 22, 'ĩndĩ kĩla mũndũ mũka akakũlya mũtũi wake, na ũla wĩkalaa ũeni nyũmbanĩ yake, mĩio ya wanake ya vetha, na mĩio ya wanake ya thaavu, na ngũa: na mũkasyĩkĩa ana menyu, na eĩtu menyu; na mũkatavĩa Amisili.'),
('kam', 'EXO', 4, 1, 'Na Mose asũngĩa na amwĩa, Ĩndĩ, sisya, matikambĩtĩkĩla, kana kwĩthukĩĩsya wasya wakwa: nũndũ makasya, Yeova ndaakumĩlĩla.'),
('kam', 'EXO', 4, 2, 'Na Yeova amũkũlya, Kĩla kĩ kw’okonĩ kwaku nĩ kyaũ? Na asũngĩa, Nĩ ndata.'),
('kam', 'EXO', 4, 3, 'Na amwĩa, Mĩkye nthĩ. Na amĩkya nthĩ, na yatw’ĩka nzoka; na Mose amĩkĩa.'),
('kam', 'EXO', 4, 4, 'Na Yeova amwĩa Mose, Tambũũkya kw’oko kwaku ũmĩkwate mwĩthe (na atambũũkya kw’oko amĩkwata, na yatw’ĩka ndata ĩ kw’okonĩ kwake);'),
('kam', 'EXO', 4, 5, 'nĩ kana metĩkĩle atĩ Yeova, Ngaĩ wa aaĩthe moo, Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo, nũkumĩlĩle.'),
('kam', 'EXO', 4, 6, 'Na ĩngĩ Yeova amwĩa, Yu likya kw’oko kwaku kĩthũinĩ kyaku. Na alikya kw’oko kwake kĩthũinĩ kyake: na yĩla wakumisye, sisya, kw’oko kwake kweethĩwa na mangũ, kwĩ kweũ ta ĩa.'),
('kam', 'EXO', 4, 7, 'Na amwĩa, Likya kw’oko kwaku kĩthũinĩ kyaku ĩngĩ. (Na alikya kw’oko kwake kĩthũinĩ kyake ĩngĩ; na yĩla wakumĩsye kĩthũinĩ kyake, sisya, kwaĩ kũalyũku ĩngĩ kũilyĩ mwĩĩ wake ũla ũngĩ.)'),
('kam', 'EXO', 4, 8, 'Na kũkeethĩwa, ethĩwa matikakwĩtĩkĩla, o na kwĩthukĩĩsya wasya wa kyama kya mbee, makeetĩkĩla wasya wa kyama kya kelĩ.'),
('kam', 'EXO', 4, 9, 'Na kũkeethĩwa, ethĩwa matiketĩkĩla o na syama isu ilĩ, o na kwĩthukĩĩsya wasya waku, nĩvo wĩtava manzĩ ma ũsĩnĩ ũmatulũle nthĩ nyũmũ: na manzĩ ala wĩtava ũsĩnĩ makatw’ĩka nthakame ĩũlũ wa nthĩ nyũmũ.'),
('kam', 'EXO', 4, 10, 'Na Mose amwĩa Yeova, Ame Mwĩaĩi, ndi mũneeni, kuma tene, o na yu waneena na mũthũkũmi waku; nũndũ nĩ mũndũ ũneenaa mbola, na ũĩmĩ wakwa nĩ mũito.'),
('kam', 'EXO', 4, 11, 'Na Yeova amwĩa, Ũla wombie kanyw’a wa mũndũ nũũ? O na nũũ ũtumaa mũndũ ũtaneena, kana kwĩw’a, kana nũũ ũtumaa ona, kana kũlea kwona? Ti nyie, Yeova?'),
('kam', 'EXO', 4, 12, 'Yu ĩndĩ, enda, nakwa ngeethĩwa nĩ vamwe na kanyw’a waku, na ngĩkũmanyĩsya ũndũ ũkaneena.'),
('kam', 'EXO', 4, 13, 'Na amwĩa, Ame Mwĩaĩi, nĩngũkũvoya, tũma na kanyw’a wa ũla wĩtũma.'),
('kam', 'EXO', 4, 14, 'Na ũthatu wa Yeova wamwakanĩa Mose, na amwĩa, Mwana‐a‐mwenyu Alunĩ, Mũlivai, nde vo? Nĩnĩsĩ atĩ nũtonya kũneena nesa. Na ĩngĩ, sisya, nĩwũkĩte akũthaũe: na akwona, akeew’a mũyo ngoonĩ yake.'),
('kam', 'EXO', 4, 15, 'Na ũkaneene nake, na kwĩkĩa i ndeto kanyw’anĩ wake: nakwa ngeethĩwa na kanyw’a waku, na kanyw’a wake, na ngĩmũmanyĩsya ũla mwaĩle kwĩka.'),
('kam', 'EXO', 4, 16, 'Nake akeethĩwa e mũneeni waku andũnĩ: na kũkeethĩwa, atĩ akeethĩwa ta kanyw’a kwaku, naku ũkeethĩwa ta Ngai kwake.'),
('kam', 'EXO', 4, 17, 'Na ũkakue ndata ĩno kw’okonĩ kwaku ĩla wĩkaa syama isu nayo.'),
('kam', 'EXO', 4, 18, 'Na Mose athi asyokea mũthoni Yethilo, na amwĩa, Nĩngũkwĩsũva, nenga ũthei nĩthi, nĩsyokee ana‐a‐ia makwa ala me Misili, nĩmanye ethĩwa me o thaũ. Na Yethilo amwĩa Mose, Enda na mũuo.'),
('kam', 'EXO', 4, 19, 'Na Yeova amwĩĩa Mose ku Mitiani, Thi, ũsyoke Misili; nũndũ andũ onthe ala mamanthaa thayũ waku nĩ akw’ũ.'),
('kam', 'EXO', 4, 20, 'Na Mose oosa mũka na ana make, na amatũlya ĩng’oinĩ, na asyoka nthĩ ya Misili: na Mose akua ndata ya Ngai kw’okonĩ kwake.'),
('kam', 'EXO', 4, 21, 'Na Yeova amwĩa Mose, Yĩla wĩsyoka Misili, ndũkatĩe kwĩka syama syonthe ila neekĩa kw’okonĩ kwaku, Valao ene: ĩndĩ ngoomya ngoo yake, na ndakalekya andũ mathĩ.'),
('kam', 'EXO', 4, 22, 'Naku ũkamwĩe Valao, Ũũ nĩw’o Yeova ũnũkwasya, Isilaeli nĩ mwana wakwa, ĩkithathi yakwa:'),
('kam', 'EXO', 4, 23, 'na nĩkũtavĩtye, Lekya mwana wakwa athi, anthũkũme; na nũleete kũmũlekya athi: sisya, ngooaa mwana waku, ĩkithathi yaku.'),
('kam', 'EXO', 4, 24, 'Na kweethĩwa, me nzĩanĩ vandũ va ũkoma, Yeova akomana nake, akyenda kũmũaa.'),
('kam', 'EXO', 4, 25, 'Nĩvo ĩndĩ Nzivola wosie ĩvia yũmũ yũĩ, na atila kĩkonde kya mbinũ ya mwana wake, na ekya maũũnĩ ma Mose; na amwĩa, Nĩ w’o, wĩ mũtwaani wa nthakame kwakwa.'),
('kam', 'EXO', 4, 26, 'Na kwondũ wa ũu Ngai amũeka. Nĩvo ĩndĩ Nzivola wamwĩie, Wĩ mũtwaani wa nthakame we, nũndũ wa nzaĩko.'),
('kam', 'EXO', 4, 27, 'Na Yeova amwĩa Aluni, Enda weũnĩ ũmũthaũe Mose. Na athi, na amũthaũĩa kĩĩmanĩ kya Ngai, na amũmumunya.'),
('kam', 'EXO', 4, 28, 'Na Mose atavya Alunĩ ndeto syonthe sya Yeova ila ũnamũtũmie nasyo, na syama syonthe ila ũnamwĩaĩe.'),
('kam', 'EXO', 4, 29, 'Na Mose na Aluni maenda na mamomban’ya atumĩa onthe ma ana ma Isilaeli:'),
('kam', 'EXO', 4, 30, 'na Aluni aneena ndeto syonthe ila Yeova ũnamũtavisye Mose, na eeka syama andũ mene.'),
('kam', 'EXO', 4, 31, 'Na andũ meetĩkĩla: na yĩla meewie kana Yeova nĩwũkĩte kũsisya ana ma Isilaeli, na kana nĩwonete monyamao moo, nĩvo ĩndĩ makunamisye mĩtwe yoo na mathaitha.'),
('kam', 'EXO', 5, 1, 'Na ĩtina wa ũu Mose na Alunĩ maenda, na mamwĩa Valao, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Lekya andũ makwa mathi, methĩwe na mboka weũnĩ kwondũ wakwa.'),
('kam', 'EXO', 5, 2, 'Na Valao asya, Yeova nũũ, nĩthukĩĩsye wasya wake nĩlekya Isilaeli mathi? Ndimwĩsĩ Yeova, o na ndikalekya Isilaeli mathi.'),
('kam', 'EXO', 5, 3, 'Na mamwĩa, Ngai wa Aevelania nũnakomanie naitũ: nĩtũũkwĩsũva, ũtũlekye tũthi weũnĩ kyalo kya mĩthenya ĩtatũ, tũthembee Yeova, Ngai waitũ, ndakese kũtũvalũkĩlya mũimũ, kana ũvyũ.'),
('kam', 'EXO', 5, 4, 'Na mũsumbĩ wa Misili amea, Nĩ ũndũ wa kĩ inyw’ĩ, Mose na Aluni, mũũtuma andũ matia mawĩa moo? Endai mũsyokee mĩio yenyu.'),
('kam', 'EXO', 5, 5, 'Na Valao amea, Sisya, andũ ma nthĩ yu nĩ aingĩ, na nĩmũũtuma mathũmũia mĩio yoo.'),
('kam', 'EXO', 5, 6, 'Na mũthenya o ũsu Valao ameaĩa aũngamĩi ma andũ, na anene moo, akĩmea,'),
('kam', 'EXO', 5, 7, 'Mũikanenge andũ ũa ĩngĩ ta tene, wa kũmba mavali: nĩmaende memanthĩe ũa mo ene.'),
('kam', 'EXO', 5, 8, 'Na ũtalo wa mavali, ala mombaa tene, manengei o w’o; mũtikanyivye o na vanini: nĩkwĩthĩwa nĩ atulu; kwondũ wa ũu nimeũlonzan’ya, na kwasya, Tũendei tũmũthembee Ngai waitũ.'),
('kam', 'EXO', 5, 9, 'Andũ nĩmanengwe wĩa wĩ vinya mbee, motethye; na matikethukĩĩsye ndeto sya ũvũngũ.'),
('kam', 'EXO', 5, 10, 'Na aũngamĩi ma andũ, na anene moo, maumaala, na maneena na andũ, makĩmea, Ũũ nĩw’o Valao ũnũkwasya, Ndimũnenga ũa.'),
('kam', 'EXO', 5, 11, 'Endai inyw’ĩ, mũkemanthĩe ũa o vala mũtonya kũwona; nũndũ wĩa wenyu o na wĩva ndũkaoleka.'),
('kam', 'EXO', 5, 12, 'Kwondũ wa ũu andũ manyaĩĩkwa nthĩ yonthe ya Misili mamanthe mavuthĩ vandũ va ũla ũa.'),
('kam', 'EXO', 5, 13, 'Na aũngamĩi mamakalaata mũno, makĩmea, Ianĩsyai mawĩa menyu, mawĩa ma kĩla mũthenya, o ta yĩla ũa waĩ vo.'),
('kam', 'EXO', 5, 14, 'Na anene ma ana ma Isilaeli, ala aũngamĩi ma Valao mamaiĩte, makũnwa, makĩwa, Nĩ ũndũ wa kĩ muineanĩsya wĩa wenyu wa kũmba mavali ĩoo, o na ũmũnthĩ, ta tene?'),
('kam', 'EXO', 5, 15, 'Nĩvo ĩndĩ anene ma ana ma Isilaeli mathi manũĩĩa Valao, makĩmũkũlya, Wĩĩka na athũkũmi maku ũu nĩkĩ?'),
('kam', 'EXO', 5, 16, 'Ithyĩ athũkũmi maku tũtinengawe ũa, nao metwĩa, Ũmbai mavali: na, sisya, athũkũmi maku nĩtũkũnawa; ĩndĩ ĩvĩtyo yĩ kwa andũ maku mwene.'),
('kam', 'EXO', 5, 17, 'Ĩndĩ amea, Mwĩ atulu, mwĩ atulu: kwondũ wa ũu mwĩasya, Tũendei tũmũthembee Yeova.'),
('kam', 'EXO', 5, 18, 'Endai yu ĩndĩ, mũtethye wĩa; nĩkwĩthĩwa mũikanengwa ũa, ĩndĩ mũkeanĩsye ũla ũtalo wa mavali.'),
('kam', 'EXO', 5, 19, 'Na anene ma ana ma Isilaeli moona atĩ me ũndũnĩ ũthũku, yĩla matavĩw’e, Mũtikaole o na vanini mavali menyu, ũtalo wa kĩla mũthenya.'),
('kam', 'EXO', 5, 20, 'Na makyuma kwa Valao makomana na Mose na Aluni, ala maũngeme nzĩani:'),
('kam', 'EXO', 5, 21, 'na mamea, Yeova amũsisye, na kũsila; nũndũ nĩmũtũnyungĩtye naĩ kũla kwĩ Valao, na kũla kwĩ athũkũmi make, kũmanenga ũvyũ mokonĩ moo matũae.'),
('kam', 'EXO', 5, 22, 'Na Mose amũsyokea Yeova, na amwĩa, Mwĩaĩi, ũmekĩte andũ aa naĩ nĩkĩ? Ũndũmĩte nĩkĩ?'),
('kam', 'EXO', 5, 23, 'Nũndũ kuma navika kwa Valao nĩneene syĩtwanĩ yaku, nũmekĩte andũ aa naĩ; o naku ndũmathonoketye andũ maku nongi.'),
('kam', 'EXO', 6, 1, 'Na Yeova amwĩa Mose, Yu ũkoona ũndũ nĩmwĩka Valao: nũndũ akamalekya mathi kwondũ wa kw’oko kwĩ vinya, na akamalũngya nthĩ yake na kw’oko kwĩ vinya.'),
('kam', 'EXO', 6, 2, 'Na Ngai aneena na Mose, na amwĩa, Ninyie Yeova:'),
('kam', 'EXO', 6, 3, 'nakwa namũmĩlĩle Avalaamu, na Isaka, na Yakovo, nĩ Ngai Mwene Vinya W’onthe; ĩndĩ na syĩtwa yakwa Yeova ndyaamanyĩka kwoo.'),
('kam', 'EXO', 6, 4, 'Na ĩngĩ nĩnĩlũlũmĩlye ũtianĩo wakwa namo, nĩmanenge nthĩ ya Kanaani, ĩla nthĩ ya kwĩkala ũeni kwoo, ĩla mekalile me ũeninĩ.'),
('kam', 'EXO', 6, 5, 'Na ĩngĩ nĩnĩw’ĩte kũluma kwa ana ma Isilaeli, ala Amisili mekalasya ũkombonĩ; na nĩnĩlilikanĩte ũtianĩo wakwa.'),
('kam', 'EXO', 6, 6, 'Kwondũ wa ũu matavye ana ma Isilaeli, Ninyĩe Yeova, na ngamumya mume mĩionĩ ya Amisili, na ngatuma muma ũkombonĩ woo, nakwa ngamwovosya na kw’oko kũtambũũkĩtwe, na mosilĩlo manene:'),
('kam', 'EXO', 6, 7, 'na ngamwosa mwĩthĩwe andũ makwa, na ngeethĩwa nĩ Ngai wenyu; na mũkamanya ninyie Yeova Ngai wenyu; ũla ũnũũmumya mĩionĩ ya Amisili.'),
('kam', 'EXO', 6, 8, 'Na ngamũete nthĩ ĩla neevĩtĩe kũmanenga Avalaamu, na Isaka, na Yakovo; na ngamũnenga ĩthĩwe ũtiĩwa wenyu: ninyie Yeova.'),
('kam', 'EXO', 6, 9, 'Na Mose atavya ana ma Isilaeli ũu: ĩndĩ matyaamwĩthukĩĩsya Mose ũndũ wa woo mũnene wa veva, na ũndũ wa ũkombo mwai.'),
('kam', 'EXO', 6, 10, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 6, 11, 'Lika, ũmwĩe Valao mũsumbĩ wa Misili, alekye ana ma Isilaeli maume nthĩ yake.'),
('kam', 'EXO', 6, 12, 'Na Mose aneena vala ve Yeova, akĩmwĩa, Sisya, ana ma Isilaeli matinaambĩtukĩĩsya; Valao akambĩw’a ata ĩndĩ, nyie ũla nĩ na ilomo ite mbaĩke?'),
('kam', 'EXO', 6, 13, 'Na Yeova aneena na Mose na Aluni, na amea meaĩe ana ma Isilaeli, o na Valao mũsumbĩ wa Misili, mamaumye ana ma Isilaeli nthĩ ya Misili.'),
('kam', 'EXO', 6, 14, 'Aa nĩo atongoi ma nyũmba sya aaĩthe moo. Ana ma Leuveni, ĩkithathi ya Isilaeli, nĩ Anoki, na Valu, na Esiloni, na Kalimi; asu nĩo mĩvĩa ya Leuveni.'),
('kam', 'EXO', 6, 15, 'Na ana ma Simeoni: Yemueli, na Yamini, na Oati, na Yakini, na Nzooali, na Sauli, mwana wa mũndũ mũka Mũkanaani: asu nĩo mĩvĩa ya Simeoni.'),
('kam', 'EXO', 6, 16, 'Na aa nĩ masyĩtwa ma ana ma Livai kũatĩĩa nzyawa syoo: Ngelisoni, na Koathi, na Melali: na myaka ya thayũ wa Livai yaĩ myaka ĩana na mĩongo ĩtatũ na mũonza.'),
('kam', 'EXO', 6, 17, 'Ana ma Ngelisoni: Livini, na Simei, kũatĩĩa mĩvĩa yoo.'),
('kam', 'EXO', 6, 18, 'Na ana ma Koathi: Amilamu, na Isali, na Eviloni, na Usieli; na myaka ya thayũ wa Koathi yaĩ myaka ĩana na mĩongo ĩtatũ na ĩtatũ.'),
('kam', 'EXO', 6, 19, 'Na ana ma Melali: Mali na Musi. Aa nĩo mĩvĩa ya Alivai kũatĩĩa nzyawa syoo.'),
('kam', 'EXO', 6, 20, 'Na Amilamu atwaa Yokeveti, mwendw’a‐ĩthe wake, atw’ĩke mũka; na amũsyaĩa Aluni na Mose: na myaka ya thayũ wa Amilamu yaĩ myaka ĩana na mĩongo ĩtatũ na mũonza.'),
('kam', 'EXO', 6, 21, 'Na ana ma Isali: Kola, na Neveki, na Nzikili.'),
('kam', 'EXO', 6, 22, 'Na ana ma Usieli: Misaeli, na Elisavani, na Sithili.'),
('kam', 'EXO', 6, 23, 'Na Aluni atwaa Elesieva, mwĩĩtu wa Aminatavu, mwĩĩtu‐a‐inyia wa Nasoni, atw’ĩke mũka; nake amũsyaĩa Natavu, na Aviu, na Eleasali, na Ithamali.'),
('kam', 'EXO', 6, 24, 'Na ana ma Kola: Asili, na Elikana, na Aviasavu; asu nĩo mĩvĩa ya Akola.'),
('kam', 'EXO', 6, 25, 'Na Eleasali, mwana wa Aluni, atwaa ũmwe wa eĩtu ma Vutieli atw’ike mũka; nake amũsyaĩa Vineasi. Asu nĩo atongoi ma nyũmba sya aaĩthe ma Alivai kũatĩĩa mĩvĩa yoo.'),
('kam', 'EXO', 6, 26, 'Asu, Mose na Aluni, nĩo ala Yeova watavisye atĩĩ, Umyai ana ma Isilaeli nthĩ ya Misili kwĩanana na nguthu syoo.'),
('kam', 'EXO', 6, 27, 'Asu nĩo ala maneenie na Valao mũsumbĩ wa Misili, nĩ kana maumye ana ma Isilaeli Misili: asu nĩ ala Mose na Aluni.'),
('kam', 'EXO', 6, 28, 'Na kweethĩwa mũthenya ũla Yeova waneenie na Mose nthĩ ya Misili,'),
('kam', 'EXO', 6, 29, 'Yeova aneena na Mose, akĩmwĩa, Ninyie Yeova: neena na Valao mũsumbĩ wa Misili maũndũ onthe ala ngũkũtavya.'),
('kam', 'EXO', 6, 30, 'Na Mose aneena vala ve Yeova, Sisya, nĩ na ilomo ite mbaĩke, na Valao akambĩthukĩĩsya ata?'),
('kam', 'EXO', 7, 1, 'Na Yeova amwĩa Mose, Sisya, nĩkũtw’ĩkĩthĩtye ta Ngai kwa Valao; na Aluni, mwana‐a‐mwenyu, akeethĩwa mwathani waku.'),
('kam', 'EXO', 7, 2, 'Ũkaneene onthe ala ngũkwĩaĩa; na Aluni, mwana‐a‐mwenyu, akaneena na Valao, nĩ kana alekye ana ma Isilaeli maume nthĩ yake.'),
('kam', 'EXO', 7, 3, 'Nakwa ngoomya ngoo ya Valao, na ngingĩvya syama syakwa na moseng’yo makwa nthĩ ya Misili.'),
('kam', 'EXO', 7, 4, 'Ĩndĩ Valao ndakamwĩthukĩĩsya, nakwa ngailĩĩla kw’oko kwakwa Misili, na ngyumya nguthu syakwa, andũ makwa ana ma Isilaeli, kuma nthĩ ya Misili na mosilĩlo manene.'),
('kam', 'EXO', 7, 5, 'Na Amisili makamanya ninyie Yeova, yĩla nĩtambũũkya kw’oko kwakwa ĩũlũ wa Misili, na ngyumya ana ma Isilaeli katĩ woo.'),
('kam', 'EXO', 7, 6, 'Na Mose na Aluni meeka ũu; o tondũ Yeova wameaĩe, now’o meekie.'),
('kam', 'EXO', 7, 7, 'Na Mose aĩ wa myaka mĩongo nyanya, na Aluni wa myaka mĩongo nyanya na ĩtatũ, yĩla maneenie na Valao.'),
('kam', 'EXO', 7, 8, 'Na Yeova aneena na Mose na Aluni, akyasya,'),
('kam', 'EXO', 7, 9, 'Yĩla Valao wĩneena nenyu, akĩmwĩa, Onan’yai kyama kwondũ wenyu: nĩvo ĩndĩ wĩmwĩa Aluni, Osa ndata yaku, nokĩkya nthĩ mbee wa Valao ĩtw’ĩke nzoka.'),
('kam', 'EXO', 7, 10, 'Na Mose na Aluni malika kwa Valao, na meeka ũu, o tondũ Yeova wameaĩe: na Aluni ekya ndata yake nthĩ mbee wa Valao na mbee wa athũkũmi make, na yatw’ĩka nzoka.'),
('kam', 'EXO', 7, 11, 'Nĩvo ĩndĩ Valao nake wetie andũ oĩ na aoi: na asu nao, eki ma syama ma Misili, meeka o ta ũu na mowe moo.'),
('kam', 'EXO', 7, 12, 'Nũndũ mekya kĩla mũndũ ndata yake nthĩ, nasyo syatw’ĩka nzoka: ĩndĩ ĩla ndata ya Aluni yamelya ndata syoo.'),
('kam', 'EXO', 7, 13, 'Na ngoo ya Valao yoomwa, na ndaamethukĩĩsya; o tondũ Yeova ũneenete.'),
('kam', 'EXO', 7, 14, 'Na Yeova amwĩa Mose, Ngoo ya Valao nĩ nyũmũ, nũleete kũlekya andũ mathi.'),
('kam', 'EXO', 7, 15, 'Enda kwa Valao kwakya; sisya, ũkeethĩa aienda manzĩnĩ; naku ũkaũngame ũtee wa ũsĩ ũkomane nake; na ĩla ndata yalyũlilwe nzoka ũkethĩwe nayo kw’okonĩ kwaku.'),
('kam', 'EXO', 7, 16, 'Noimwĩa, Yeova, Ngai wa Aevelania, nũndũmĩte kũla ũĩ, akĩkwĩa, Lekya andũ makwa mathi, manthũkũme weũnĩ: na sisya, kũvika o na yu ndwaaĩthukĩĩsya.'),
('kam', 'EXO', 7, 17, 'Ũũ nĩw’o Yeova ũnũkwasya, Ũndũnĩ ũũ ũkamanya ninyie Yeova: sisya, ngakũna manzĩ ala me ũsĩnĩ na ndata ĩla yĩ kw’okonĩ kwakwa, na makaalyũka nthakame.'),
('kam', 'EXO', 7, 18, 'Na makũyũ ala me ũsĩnĩ makakw’a, na ũsĩ ũkanyunga naĩ; na Amisili makamena mũno kũnyw’a manzĩ ma ũsĩnĩ.'),
('kam', 'EXO', 7, 19, 'Na Yeova amwĩa Mose, Mwĩe Alunĩ, Osa ndata yaku, noitambũũkya kw’oko kwaku ĩũlũ wa manzĩ ma Misili, ĩũlũ wa mbũsĩ syoo, na ĩũlũ wa tũlũsĩ twoo, na ĩũlũ wa ndia syoo, na ĩũlũ wa maia moo onthe ma manzĩ, matw’ĩke nthakame; na kũkeethĩwa nthakame nthĩ yonthe ya Misili, syĩndũnĩ sya mĩtĩ o na syĩndũnĩ sya mavia.'),
('kam', 'EXO', 7, 20, 'Na Mose na Aluni meeka ũu, o tondũ Yeova weaie; na ookĩlya ndata, na akũna manzĩ ala maĩ ũsĩnĩ, Valao ene, o na athũkũmi make mene; na manzĩ onthe ala maĩ ũsĩnĩ maalyũka nthakame.'),
('kam', 'EXO', 7, 21, 'Na makũyũ ala maĩ ũsĩnĩ makw’a; na ũsĩ wanyunga naĩ, na Amisili matyaatonya kũnyw’a manzĩ ma ũsĩnĩ; nayo nthakame yakomana nthĩ yonthe ya Misili.'),
('kam', 'EXO', 7, 22, 'Na eki ma syama ma Misili meeka o ta ũu na mowe moo: na ngoo ya Valao yoomwa, na ndaamethukĩĩsya; o tondũ Yeova ũneenete.'),
('kam', 'EXO', 7, 23, 'Na Valao eethyũũa alika nyũmba kwake, o na ndaaona ũu ta ũndũ ngoonĩ yake.'),
('kam', 'EXO', 7, 24, 'Na Amisili onthe menzanga kũndũ kw’onthe ũtee wa ũsĩ mone manzĩ ma ũnyw’a; nũndũ matyaatonya kũnyw’a ala manzĩ ma ũsĩnĩ.'),
('kam', 'EXO', 7, 25, 'Na mĩthenya mũonza yathela, ĩtina wa Yeova akũna ũla ũsĩ.'),
('kam', 'EXO', 8, 1, 'Na Yeova amwĩa Mose, Lika kwa Valao, noimwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Lekya andũ makwa mathĩ, manthũkũme.'),
('kam', 'EXO', 8, 2, 'Na ethĩwa nũũlea ũmalekya mathi, sisya, ngakũna mĩvaka yaku yonthe na kũete syoa:'),
('kam', 'EXO', 8, 3, 'na ũsĩ ũkausũa syoa ki, ila ikambata ilike nyũmbanĩ yaku, o na nthĩnĩ wa kasũmba kaku ka kũkoma, na ũkomonĩ waku, na nthĩnĩ wa nyũmba ya athũkũmi maku, na ĩũlũ wa andũ maku, na nthĩnĩ wa maiko maku, na nthĩnĩ wa syĩndũ syaku ila iluĩlawa mũtu:'),
('kam', 'EXO', 8, 4, 'na ila syoa ikambata ĩũlũ waku, na ĩũlũ wa andũ maku, na ĩũlũ wa athũkũmi maku onthe.'),
('kam', 'EXO', 8, 5, 'Na Yeova amwĩa Mose, Mwĩe Aluni, Tambũũkya kw’oko kwaku kwĩ na ndata yaku ĩũlũ wa mbũsĩ, na ĩũlũ wa tũlũsĩ, na ĩũlũ wa ndia, ũkambatĩthye syoa nthĩ ya Misili.'),
('kam', 'EXO', 8, 6, 'Na Aluni atambũũkya kw’oko kwake ĩũlũ wa manzĩ ma Misili; na syoa syauma, syausũa nthĩ ya Misili.'),
('kam', 'EXO', 8, 7, 'Na eki ma syama nao meeka o ta ũu na mowe moo, na mambatĩthya syoa nthĩ ya Misili.'),
('kam', 'EXO', 8, 8, 'Nĩvo ĩndĩ Valao wametie Mose na Aluni, na amea, Mwĩsũvei Yeova, ambetee syoa kwakwa, na kwa andũ makwa; nakwa ngalekya andũ mathi, mamũthembee Yeova.'),
('kam', 'EXO', 8, 9, 'Na Mose amwĩa Valao, Ĩnenevye ĩndĩ vala nĩĩ: nĩ ĩvinda yĩva nĩũvoyea, na athũkũmi maku, na andũ maku, nĩ kana syoa syanangwe kuma kwaku na nyũmbanĩ syaku, na ikĩkala ũsĩnĩ wĩ w’oka?'),
('kam', 'EXO', 8, 10, 'Na amwĩa, Nĩ ũnĩ. Nake amwĩa, Kwĩthĩwe kwĩanana na ndeto yaku; nĩ kana ũmanye vati ũngĩ ũtilyĩ Yeova Ngaĩ waitũ.'),
('kam', 'EXO', 8, 11, 'Na syoa ikaũma kũla ũĩ, na kuma nyũmbanĩ syaku, na kuma athũkũminĩ maku na kuma andũnĩ maku; ikekala ũsĩni wĩ w’oka.'),
('kam', 'EXO', 8, 12, 'Na Mose na Alunĩ maumaala vala ve Valao: na Mose amwikaĩla Yeova ũndũ wa syoa ila wamũetee Valao.'),
('kam', 'EXO', 8, 13, 'Na Yeova eeka kwĩanana na ndeto ya Mose; na ila syoa syakw’a syathela nyũmbanĩ, na nza, na mĩũndanĩ.'),
('kam', 'EXO', 8, 14, 'Na masyũmban’ya mavumbu: na nthĩ yanyunga naĩ.'),
('kam', 'EXO', 8, 15, 'Ĩndĩ yĩla Valao wonie ũthũmũo, oomya ngoo yake, na ndaamethukĩĩsya; o tondũ Yeova ũneenete.'),
('kam', 'EXO', 8, 16, 'Na Yeova amwĩa Mose, Mwĩe Aluni, Tambũũkya ndata yaku, noĩkũna kĩtoo kya nthĩ, kĩtw’ĩke ndaa nthĩ yonthe ya Misili.'),
('kam', 'EXO', 8, 17, 'Na meeka ũu; na Aluni atambũũkya kw’oko kwake kwĩ na ndata yake, na akũna kĩtoo kya nthĩ, na kweethĩwa ndaa andũnĩ, na nyamũnĩ; kĩtoo kyonthe kya nthĩ kyatw’ĩka ndaa nthĩ yonthe ya Misili.'),
('kam', 'EXO', 8, 18, 'Na ala eki ma syama meeka o ta ũu na mowe moo maete ndaa, ĩndĩ matyaatonya: na kwaĩ ndaa andũnĩ, na nyamũnĩ.'),
('kam', 'EXO', 8, 19, 'Nĩvo ĩndĩ eki ma syama mamwĩie Valao, Kĩĩ nĩ kyaa kya Ngai: na ngoo ya Valao yaĩ nyũmũ, na ndaamethũkĩĩsya; o tondũ Ngai ũneenete.'),
('kam', 'EXO', 8, 20, 'Na Yeova amwĩa Mose, Ũkĩla kĩoko tene ũũngame mbee wa Valao; sisya, nĩwũkĩte manzĩnĩ; naku ũmwĩe, Ũũ nĩw’o Yeova ũnũkwasya, Lekya andũ makwa mathi, manthũkũme.'),
('kam', 'EXO', 8, 21, 'Kana ethĩwa ndũũlekya andũ makwa mathi, sisya, ngakũetee ngi mbingĩ, na athũkũmi maku, na andũ maku, na iilika nyũmbanĩ syaku: na nyũmba sya Amisili ikausũa ngi mbingĩ, o na nthĩ ĩla matwĩe.'),
('kam', 'EXO', 8, 22, 'Na mũthenya ũsu ngavathũkan’ya nthĩ ya Ngoseni ĩla andũ makwa matwĩe, kũtikethĩwe ngi isu mbingĩ vo; nĩ kana ũmanye ninyie Yeova katĩ wa nthĩ.'),
('kam', 'EXO', 8, 23, 'Na ngeekĩa kĩvathũkan’yo katĩ wa andũ makwa na andũ maku: na kyama kyu kĩkooneka ũnĩ.'),
('kam', 'EXO', 8, 24, 'Na Yeova eeka ũu; na kwalika ngi mbingĩ nyũmbanĩ ya Valao, na nyũmbanĩ sya athũkũmi make: na nthĩnĩ wa nthĩ yonthe ya Misili nthĩ yathũkwa mũno kwondũ wa ngi isu mbingĩ.'),
('kam', 'EXO', 8, 25, 'Na Valao eeta Mose na Aluni, na amea, Endai inyw’ĩ, mũthembee Ngai wenyu o nthĩ ĩno.'),
('kam', 'EXO', 8, 26, 'Na Mose amwĩa, Kũtyaĩle twĩke ũu; nũndũ tũkathembea Yeova Ngai waitũ nthembo ĩla ĩthatasya Amisili: sisya, tũkathemba ĩla ĩthatasya Amisili mene, namo matitũkima na mavia?'),
('kam', 'EXO', 8, 27, 'Tũkaenda weũnĩ kyalo kya mĩthenya ĩtatũ, na tũkĩthembea Yeova Ngai waitũ, o tondũ wĩtwĩaĩa.'),
('kam', 'EXO', 8, 28, 'Na Valao amea, Ngamũlekya mũthi, mũthembee Yeova Ngai wenyu weũnĩ; ĩndĩ mũtikaende kũasa mũno: nenyu mboyeai.'),
('kam', 'EXO', 8, 29, 'Na Mose asya, Sisya nĩnguma kũla ũĩ, na ngamwĩsũva Yeova nĩ kana ila ngi mbingĩ syume ũnĩ kwa Valao, na kwa athũkũmi make, na andũ make: no ĩndĩ, Valao ndakasyoke kũkengana ĩngĩ ũndũ wa kũlea kũlekya andũ mathi mathembee Yeova.'),
('kam', 'EXO', 8, 30, 'Na Mose aumaala kwa Valao, na amwĩsũva Yeova.'),
('kam', 'EXO', 8, 31, 'Na Yeova eeka kwĩanana na ndeto ya Mose; na amũvetea Valao, na athũkũmi make, na andũ make ngi isu mbingĩ; o na kũtyaatiala kamwe.'),
('kam', 'EXO', 8, 32, 'Na Valao oomya ngoo yake ĩvinda yĩu nayo, na ndaalekya andũ mathi.'),
('kam', 'EXO', 9, 1, 'Nĩvo ĩndĩ Yeova wamwĩie Mose, Lika kwa Valao, ũmwĩe, Ũũ nĩw’o Yeova, Ngai wa Aevelania, ũnũkwasya, Lekya andũ makwa mathi, manthũkũme.'),
('kam', 'EXO', 9, 2, 'Nũndũ ethĩwa nũkũlea kũmalekya mathi, na kũmekalangya,'),
('kam', 'EXO', 9, 3, 'sisya, kw’oko kwa Yeova kwĩ ĩũlũ wa ĩndo syaku ila syĩ isesinĩ, ĩũlũ wa mbalasi, na mang’oi, na ngamĩle, na ndĩthya sya ng’ombe, na ndĩthya sya mbũi na malondu: kũkeethĩwa mũimũ mũthũku mũno.'),
('kam', 'EXO', 9, 4, 'Na Yeova akavathũkan’ya katĩ wa indo sya Isilaeli na indo sya Misili: na kũikakw’a ĩmwe ya syonthe ĩla sya ana ma Isilaeli.'),
('kam', 'EXO', 9, 5, 'Na Yeova atw’a kyathĩ, akyasya, Ũnĩ nĩw’o Yeova wĩĩka ũndũ ũsu nthĩ ĩno.'),
('kam', 'EXO', 9, 6, 'Na ũnĩ ũsu Yeova eeka ũndũ ũsu, na indo syonthe sya Misili syakw’a: ĩndĩ indonĩ sya ana ma Isilaelĩ kũtyaakw’a o na ĩmwe.'),
('kam', 'EXO', 9, 7, 'Na Valao atũmana, na eethĩa kũtyaĩ o na ĩmwe ngw’ũ ya indo sya Aisilaeli. Ĩndĩ ngoo ya Valao yaĩ nyũmũ, na ndaalekya andũ mathi.'),
('kam', 'EXO', 9, 8, 'Na Yeova amea Mose na Aluni, Utai mũu ikonĩ mbĩ syusĩe, na Mose naũlũkye kwelekela ĩtunĩ Valao ene.'),
('kam', 'EXO', 9, 9, 'Na ũkatw’ĩka kĩtoo kĩvinyu nthĩ yonthe ya Misili, na kwĩthĩwa mĩimũ mimbu ĩkĩvũthũkanga ĩũlũ wa andũ na ĩũlũ wa nyamũ, nthĩ yonthe ya Misili.'),
('kam', 'EXO', 9, 10, 'Na mauta mũu ikonĩ, na maũngama mbee wa Valao; na Mose aũlũkya kwelekela ĩtunĩ; na watw’ĩka mĩimũ mimbu ĩkĩvũthũkanga ĩũlũ wa andũ na ĩũlũ wa nyamũ.'),
('kam', 'EXO', 9, 11, 'Na ala eki ma syama matyaatonya kũũngama mbee wa Mose nũndũ wa mĩimũ; nĩkwĩthĩwa eki ma syama maĩ na mĩlimũ ĩsu, o na Amisili onthe.'),
('kam', 'EXO', 9, 12, 'Na Yeova oomya ngoo ya Valao, na ndaamethukĩĩsya; o tondũ Yeova ũtavĩtye Mose.'),
('kam', 'EXO', 9, 13, 'Na Yeova amwĩa Mose, Ũkĩla kĩoko tene, ũũngame mbee wa Valao, na ũimwĩa, Ũũ nĩw’o Yeova, Ngai wa Aevelania, ũnũkwasya, Lekya andũ makwa mathi, manthũkũme.'),
('kam', 'EXO', 9, 14, 'Nũndũ ĩvinda yĩĩ ngaetee ngoo yaku mothĩn’yo makwa onthe, we na athũkũmi maku, na andũ maku; nĩ kana ũmanye kana vati ũngĩ ũtilyĩ takwa nthĩ yonthe.'),
('kam', 'EXO', 9, 15, 'Nũndũ yu nĩĩthĩwa ndambũũkĩtye kw’oko kwakwa, ngũkũne we na andũ maku na mũimũ, na ũivetwa kuma nthĩ:'),
('kam', 'EXO', 9, 16, 'ĩndĩ nĩ w’o, kwondũ wa ũndũ ũũ nĩngũũngamĩtye, nĩkwon’ye vinya wakwa, na nĩ kana syĩtwa yakwa yĩtavanw’e nthĩ yonthe.'),
('kam', 'EXO', 9, 17, 'O na yu, we, wĩneneveasya andũ makwa, ndũkamalekye mathi?'),
('kam', 'EXO', 9, 18, 'Sisya, ũnĩ ta yu ngausya mbua mbai mũno ya mavia, mũthemba ũla ũtaaoneka Misili kuma mũthenya ũla yambĩlĩlw’e o na kũvika yu.'),
('kam', 'EXO', 9, 19, 'Yu ĩndĩ tũmana, ũkalaate indo syaku na syonthe ila wĩ nasyo kĩsesinĩ syĩnũkw’e; nũndũ kĩla mũndũ na nyamũ ĩla ĩkakitw’a kĩsesinĩ, ĩte mbĩnũkye, mbua ĩsu ya mavia ĩkasyuĩa, na ikakw’a.'),
('kam', 'EXO', 9, 20, 'Ũla wakĩie ndeto ya Yeova athũkũminĩ ma Valao atuma athũkũmĩ make na indo syake ikũka ilike nyũmbanĩ:'),
('kam', 'EXO', 9, 21, 'nake ũla ũtaaona ndeto ya Yeova ta kĩndũ atia athũkũmi make na indo syake kĩsesinĩ.'),
('kam', 'EXO', 9, 22, 'Na Yeova amwĩa Mose, Tambũũkya kw’oko kwaku keelekela ĩtunĩ, kue, mbua ya mavia nthĩ yonthe ya Misili, mũndũnĩ, na nyamũnĩ, na nyũnyinĩ syonthe sya mũũndanĩ, nathĩ yonthe ya Misili.'),
('kam', 'EXO', 9, 23, 'Na Mose atambũũkya ndata yake kwelekela ĩtunĩ: na Yeova aete ĩtundumo na mbua ya mavia, na mwaki watheea wavika nthĩ; na Yeova ausya mbua ya mavia nthĩ ya Misili.'),
('kam', 'EXO', 9, 24, 'Na kwondũ wa ũu kweethĩwa mbua ya mavia, na mwaki ũvulene na ĩla mbua ya mavia, mbai mũno, mũthemba ũla ũtaaoneka nthĩ yonthe ya Misili kuma yĩla yambĩlĩlye kũtũwa nĩ andũ.'),
('kam', 'EXO', 9, 25, 'Na mbua ĩsu ya mavia yakũna syonthe ila syaĩ kĩsesinĩ, andũ o na nyamũ, nthĩ yonthe ya Misili; na mbua ĩsu ya mavia yakũna nyũnyi syonthe sya mũũndani, na yatũlanga kĩla mũtĩ wa kĩsesinĩ.'),
('kam', 'EXO', 9, 26, 'No nthĩ ya Ngoseni ĩ yoka, ĩla yatwĩe ana ma Isilaeli, ĩtaĩ mbua ya mavia.'),
('kam', 'EXO', 9, 27, 'Na Valao atũmana, na eeta Mose na Aluni, na amea, Nĩnĩvĩtĩtye ĩvinda yĩĩ: Yeova nĩ mwene ũlũngalu, nakwa nyie na andũ makwa twĩ athe.'),
('kam', 'EXO', 9, 28, 'Mwĩsũvei Yeova; nũndũ itundumo ii nene mũno na mbua ya mavia nĩsyĩanĩe; nakwa ngamũlekya mũthi, na mũtiendeea na kwĩkala kũũ.'),
('kam', 'EXO', 9, 29, 'Na Mose amwĩa, O yĩla nĩuma ndũanĩ, ngookĩlĩlya Yeova moko makwa; na itundumo ikathela, o na kũtikethĩwa mbua ya mavia ĩngĩ; nĩ kana ũmanye atĩ nthĩ nĩ ya Yeova.'),
('kam', 'EXO', 9, 30, 'Ĩndĩ ũndũ waku na athũkũmi maku, nĩnĩsĩ kana o na yu mũtikakĩa Yeova Ngai.'),
('kam', 'EXO', 9, 31, 'Na katane na mbaale syakũnwa: nũndũ mbaale syaĩ na iia, na katane kaĩ kalaũku.'),
('kam', 'EXO', 9, 32, 'Ĩndĩ nganũ na kusemethu ityaakũnwa: nũndũ ityaameete.'),
('kam', 'EXO', 9, 33, 'Na Mose auma ndũanĩ kwa Valao, na atambũũkĩsya Yeova moko make: na itundumo na mbua ya mavia syatĩa, na mbua ndĩaaua ĩũlũ wa nthĩ.'),
('kam', 'EXO', 9, 34, 'Na yĩla Valao wonie atĩ mbua na mbua ya mavia na itundumo nitĩĩte, aendeea kũvĩtya, na oomya ngoo yake, we na athũkũmi make.'),
('kam', 'EXO', 9, 35, 'Na ngoo ya Valao yoomĩthw’a, na ndaalekya ana ma Isilaeli mathi; o tondũ Yeova ũneenete na kanyw’a wa Mose.'),
('kam', 'EXO', 10, 1, 'Na Yeova amwĩa Mose, Lika kwa Valao: nũndũ nĩnũmĩtye ngoo yake, na ngoo sya athũkũmi make, nĩ kana nonan’ye syama ii syakwa katĩ woo,'),
('kam', 'EXO', 10, 2, 'na nĩ kana ũtonye kũneena mwana waku akĩw’a, o na mwĩsũkũũu, maũndũ ala nĩkĩte Misili, na syama syakwa ila nĩkĩte katĩ woo: nĩ kana mũmanye ninyie Yeova.'),
('kam', 'EXO', 10, 3, 'Na Mose na Aluni malika kwa Valao, na mamwĩa, Ũũ nĩw’o Yeova, Ngaĩ wa Aevelania, ũnũkwasya, Wĩlea kwĩnyivya mbee wakwa kũvika ĩndĩĩ? Lekya andũ makwa mathi, manthũkũme.'),
('kam', 'EXO', 10, 4, 'Kana, ethĩwa nũũlea kũlekya andũ makwa mathĩ, sĩsya, ũnĩ ngaete ngie ilike mĩvakanĩ yaku:'),
('kam', 'EXO', 10, 5, 'na ikavw’ĩka ĩũlũ wa nthĩ, o ũndũ mũndũ ũtatonya kũmyona nthĩ: na ikaya kĩla kĩtiele kya kĩla kĩthonokete, kĩla kyamũtialĩle mbuanĩ ya mavia, na ikaya kĩla mũtĩ ũla ũmeaa kwondũ wenyu kĩsesinĩ:'),
('kam', 'EXO', 10, 6, 'na nyũmba syaku, na nyũmba sya athũkũmi maku onthe, na nyũmba sya Amisili onthe ĩkausũwa nĩsyo; o tondũ aaĩthe maku, o na aũmae maku mataaona, kuma mũthenya mambĩlĩlya kũsyawa kũũ nthĩ kũvika ũmũnthĩ. Na eethyũũa, na auma kwa Valao.'),
('kam', 'EXO', 10, 7, 'Na athũkũmi ma Valao mamũkũlya, Mũndũ ũũ akekala e mũtei kwitũ kũvika ĩndĩĩ? Lekya andũ mathi, mathũkũme Yeova Ngai woo: ndũnamba kũmanya kana Misili nĩ mbanangĩku?'),
('kam', 'EXO', 10, 8, 'Na Mose na Aluni matũngwa kwa Valao ĩngĩ: na amea, Endai, mũthũkũme Yeova Ngai wenyu: ĩndĩ ala methĩ naaũ?'),
('kam', 'EXO', 10, 9, 'Na Mose amwĩa, Tũkaenda na syana sitũ na akũũ maitũ; na tũkaenda na ana maitũ na eĩtu maitũ, na ndĩthya sitũ sya mbũi na malondu na ndĩthya sitũ sya ng’ombe; nĩkwĩthĩwa no mũvaka twĩthĩwe na mboka kwondũ wa Yeova.'),
('kam', 'EXO', 10, 10, 'Na amea, Yeova ethĩwe nenyu ĩndĩ, o tondũ ngũmũlekya mũthi na syana nini syenyu: sisyai; nũndũ kwĩ ũthũku mũsũanĩĩte.'),
('kam', 'EXO', 10, 11, 'Tiw’o: endai yu, inyw’ĩ andũ aima, mũthũkũme Yeova; nũndũ ũu nĩ ũla mũkwenda. Na malũngw’a kuma kwa Valao.'),
('kam', 'EXO', 10, 12, 'Na Yeova amwĩa Mose, Tambũũkya kw’oko kwaku ĩũlũ wa nthĩ ya Misili, nĩ kana ngie syũke syambate nthĩ ya Misili, na kũya nyũnyi syonthe sya nthĩ, o syonthe ila itialĩtw’e nĩ mbua ya mavia.'),
('kam', 'EXO', 10, 13, 'Na Mose atambũũkya ndata yake ĩũlũ wa nthĩ ya Misili, na Yeova aete kĩuutani kyumĩte wumĩlonĩ wa syũa ĩũlũ wa nthĩ mũthenya ũsu w’onthe, na ũtukũ w’onthe; na kwakya, kĩuutani kĩla kyumite wumiloni wa syũa kyaete ngie.'),
('kam', 'EXO', 10, 14, 'Na ila ngie syambata ĩũlũ wa nthĩ yonthe ya Misili, na syekala mĩvakanĩ yonthe ya Misili; syaĩ mbai mũno; kũtyaaoneka ĩngĩ ngie itilyĩ ta isu, o na kũtikethĩwa ĩngĩ tasyo.'),
('kam', 'EXO', 10, 15, 'Nũndũ syavw’ĩkie ĩũlũ wa nthĩ yonthe, mũvaka nthĩ yaya kĩvindu; nasyo syaya nyũnyi syonthe sya nthĩ, na ũsyao w’onthe wa mĩtĩ ũla mbua ya mavia yatialĩtye: na kũtyaatialwa kĩndũ kĩũ o na kĩmwe, kya mũtĩ kana nyũnyi sya mũũndanĩ, nthĩ yonthe ya Misili.'),
('kam', 'EXO', 10, 16, 'Nĩvo ĩndĩ Valao wetie Mose na Aluni na mĩtũkĩ; na amea, Nĩnĩmũvĩtanĩsye Yeova Ngai wenyu, o nenyu.'),
('kam', 'EXO', 10, 17, 'Na yu ĩndĩ, nĩngũmwĩsũva, ũndekee ĩvĩtyo yakwa ĩvinda o yĩĩ yĩmwe, na ũimwĩsũva Yeova Ngai wenyu, ambetee kĩkw’ũ kĩĩ kyoka.'),
('kam', 'EXO', 10, 18, 'Na auma kwa Valao, na amwĩsũva Yeova.'),
('kam', 'EXO', 10, 19, 'Na Yeova aalyũla kĩuutani kĩ vinya mũno kyumĩte ngalĩ ya ũthũĩlonĩ wa syũa, kĩla kyookĩlilye ila ngie, na kyaitwaa na vinya Ũkanganĩ Mũtune; kũtyaatialwa ngie o na ĩmwe mĩvakanĩ yonthe ya Misili.'),
('kam', 'EXO', 10, 20, 'Ĩndĩ Yeova oomya ngoo ya Valao, nake ndaalekya ana ma Isilaeli mathi.'),
('kam', 'EXO', 10, 21, 'Na Yeova amwĩa Mose, Tambũũkya kw’oko kwaku kwelekela ĩtuni, kwĩthĩwe kĩvindu ĩũlũ wa nthĩ ya Misili, o kĩvindu kĩla kĩtonya kũkwatangwa.'),
('kam', 'EXO', 10, 22, 'Na Mose atambũũkya kw’oko kwake kwelekela ĩtunĩ; na kweethĩwa kĩvindu kya ngokomi nthĩ yonthe ya Misili mĩthenya ĩtatũ;'),
('kam', 'EXO', 10, 23, 'matyoonanaa, o na kũtyaaũkĩla mũndũ ũmwe kwake mĩthenya ĩtatũ: ĩndĩ ana onthe ma Isilaeli maĩ na kyeni kũla matwĩe.'),
('kam', 'EXO', 10, 24, 'Na Valao amwĩta Mose, na amwĩa, Endai inyw’ĩ, mũthũkũme Yeova; ĩndĩ ndĩthya syenyu sya mbũi na malondu na ndĩthya syenyu sya ng’ombe nitiwe: syana syenyu nini nasyo iende nenyu.'),
('kam', 'EXO', 10, 25, 'Na Mose asya, Ndwĩ ndĩi ya kũlea ũtũnenga nthembo sya kũtonywa mokonĩ maitũ, na nthembo sya kũvĩvw’a, tũthembee Yeova Ngai waitũ.'),
('kam', 'EXO', 10, 26, 'Indo sitũ nasyo tũkathi nasyo; kũti ĩvũngũ yĩmwe yĩkatiwa ĩtina; nũndũ kuma nthĩnĩ wasyo mũvaka twose tuthũkũme Yeova Ngai waitũ; na tũtyĩsĩ mũvaka no twavika vo, ila twaĩle kũthũkũma Yeova nasyo.'),
('kam', 'EXO', 10, 27, 'Ĩndĩ Yeova oomya ngoo ya Valao, na alea ũmalekya mathi.'),
('kam', 'EXO', 10, 28, 'Na Valao amwĩa, Uma vaa nĩĩ, wĩsũvĩe, ndũkone ũthyũ wakwa ĩngĩ; nũndũ mũthenya o ũla wĩona ũthyũ wakwa ũkakw’a.'),
('kam', 'EXO', 10, 29, 'Na Mose, amwĩa, Nĩwaneena nesa; ndikona ũthyũ waku ĩngĩ nongi.'),
('kam', 'EXO', 11, 1, 'Na Yeova amwĩa Mose, Kwĩ ũthĩn’yo ũngĩ o ũmwe nĩmũetee Valao, na Misili; ĩtina wa ũu akamũlekya mume kũũ: yĩla wĩmũlekya mũthi ndetĩa kũmũlũngya vyũ.'),
('kam', 'EXO', 11, 2, 'Neena yu matũnĩ ma andũ, namo metye kĩla mũndũ mũũme mũtũi wake, na kĩla mũndũ mũka mũtũi wake, mĩio ya wanake ya vetha, na mĩio ya wanake ya thaavu.'),
('kam', 'EXO', 11, 3, 'Na Yeova atuma andũ mona ũseo methonĩ ma Amisili. O na ĩngĩ, mũndũ ũsu Mose aĩ mũnene mũno nthĩ ya Misili, kũla kwĩ athũkũmi ma Valao, na kũla kwĩ andũ ma kw’o.'),
('kam', 'EXO', 11, 4, 'Na Mose asya, Ũũ nĩw’o Yeova ũnũkwasya, Ta ũtukũ katĩ ngathi mbĩtĩle Misili katĩ:'),
('kam', 'EXO', 11, 5, 'na makithathi onthe nthĩ ya Misili makakw’a, kuma ĩkithathi ya Valao ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ, o na kũvika ĩkithathi ya mũthũkũmi mwĩĩtu ũla ũnũũthia; o na makithathi onthe ma indo.'),
('kam', 'EXO', 11, 6, 'Na kũkeethĩwa kĩĩo kĩnene nthĩ yonthe ya Misili, o ta kĩla kĩtaaĩthĩwa, o na kĩtakethĩwa ĩngĩ.'),
('kam', 'EXO', 11, 7, 'Ĩndĩ kwa ana ma Isilaeli o na ngitĩ ndikamakũnĩa o na ũmwe, mũndũ o na nyamũ: nĩ kana mũmanye ũndũ Yeova ũvathũkanasya katĩ wa Amisili na Isilaeli.'),
('kam', 'EXO', 11, 8, 'Na athũkũmi aa onthe maku makatheea moke vala mĩĩ, makĩndulĩlya ndu, makĩmbĩa, Uma vaa, we, na andũ onthe ala maatĩanĩe naku: na ĩtina wa ũu ngauma nĩthi. Na auma kwa Valao e mũthatu mũno.'),
('kam', 'EXO', 11, 9, 'Na Yeova amwĩa Mose, Valao ndakakwĩthukĩĩsya; nĩ kana syama syakwa syongeleke nthĩ ya Misili.'),
('kam', 'EXO', 11, 10, 'Na Mose na Aluni meeka syama isu syonthe vala ve Valao: na Yeova oomya ngoo ya Valao, na ndaalekya ana ma Isilaeli mathi maume nthĩ yake.'),
('kam', 'EXO', 12, 1, 'Na Yeova aneena na Mose na Aluni nthĩ ya Misili, akĩmea,'),
('kam', 'EXO', 12, 2, 'Mwei ũũ ũkeethĩwa mwei wa mbee wa mwaka kwenyu.'),
('kam', 'EXO', 12, 3, 'Neenai na ũmbano w’onthe wa Isilaeli, mũkĩwĩa, Mũthenya wa ĩkũmi wa mwei ũũ nĩmeĩyosea kĩla mũndũ katena ka ĩlondu, kwĩanana na nyũmba sya aaĩthe moo, o kĩla nyũmba katena:'),
('kam', 'EXO', 12, 4, 'ne ethĩwa andũ ma nyũmba nĩ anini matamina katena, nĩvo ĩndĩ we na mũtũi wake ũla ũthengeanĩa na nyũmba yake meosa kamwe kwĩanana na ũtalo wa andũ; o kwĩanana na ũndũ kĩla mũndũ ũĩsaa mwĩtala ũndũ wa katena,'),
('kam', 'EXO', 12, 5, 'Katena kenyu kakethĩwe kate kĩema. Kaũme ka mwaka ũmwe: mwĩkaumya malondunĩ, kana mbũinĩ:'),
('kam', 'EXO', 12, 6, 'na mwĩkaia kũvika mũthenya wa ĩkũmi na ĩna wa mwei o ũsu: na ũmbano w’onthe wa ĩkomano ya Isilaeli wĩkoaa wĩoo.'),
('kam', 'EXO', 12, 7, 'Na meosa nthakame ĩmwe yako, na makĩmĩvaka mĩtĩnĩ ĩlĩ yĩ ndee sya mũomo, o na kĩthaku, nyũmbanĩ ila meũkaĩĩa.'),
('kam', 'EXO', 12, 8, 'Na meya nyama syako ũtukũ o ũsu, syĩ mbĩvye na mwaki, vamwe na kĩmũtu kĩte ĩlawa; maiĩsanĩsya na nyũnyi syĩ ũũ.'),
('kam', 'EXO', 12, 9, 'Mũtikaiye syĩ mbĩthĩ, o na syĩ ndue na manzĩ ĩndĩ syĩ mbĩvye na mwaki; mũtwe wako vamwe na maũũ mako na mavu.'),
('kam', 'EXO', 12, 10, 'Na mũtikatialye kendũ kamwe kako kũvika kĩoko; ĩndĩ kĩla kĩtiala kyako kũvika kĩoko mwĩvĩvya na mwaki.'),
('kam', 'EXO', 12, 11, 'Na mwĩkaya ũũ: mwĩĩthĩwa mwĩvotoete kĩnyunyunĩ kyenyu; mwĩ na iatũ syenyu maũũnĩ, na ndata syenyu mokonĩ: na mwĩkaya mwĩkalaatĩte: nĩ vasaka wa Yeova.'),
('kam', 'EXO', 12, 12, 'Nĩkwĩthĩwa ngavĩtĩla ũtukũ ũsu nthĩ ya Misili, na ngakũna makithathi onthe nthĩ ya Misili, ya mũndũ o na ya nyamũ; na ngasilĩla ngai syonthe sya Misili: ninyie Yeova.'),
('kam', 'EXO', 12, 13, 'Na nthakame ĩkeethĩwa ũvano kwenyu nyũmbanĩ ila mũĩ: na yĩla nĩona nthakame, ngavĩtĩla ĩũlũ wenyu, na kũtikethĩwa ũthĩn’yo kwenyu wa kũmwananga, yĩla nĩkũna nthĩ ya Misili.'),
('kam', 'EXO', 12, 14, 'Na mũthenya ũũ ũkeethĩwa ũlilikan’yo kwenyu, na mũkoovatha wĩthĩwe wa mboka kwondũ wa Yeova: mosyaanĩonĩ menyu onthe mũkoovatha wĩthĩwe wa mboka kwĩanana na ũtw’ĩo wa tene na tene.'),
('kam', 'EXO', 12, 15, 'Mũkaye kĩmũtũ kĩte ĩlawa mĩthenya mũonza; o mũthenya wa mbee mũkaumye ĩlawa myũmbanĩ syenyu: nĩkwĩthĩwa o ũla ũkaya kĩmũtũ kĩ ĩlawa kuma mũthenya wa mbee kũvika mũthenya wa mũonza, mũndũ ũsu akavetwa kuma kwa Isilaeli.'),
('kam', 'EXO', 12, 16, 'Na mũthenya wa mbee kũkethĩwe ũmbano mũtheu kwenyu, na ũmbano mũtheu mũthenya wa mũonza naw’o; kũtikethĩwe wĩa o na wĩva ũkatethw’a nthĩnĩ wayo, keka ũsu wa kwĩanĩsya vata wa kĩla mũndũ wa kũya, no ũsu mwĩ na ũthei wa kũtethya.'),
('kam', 'EXO', 12, 17, 'Na mũkalilikanae mboka ya kĩmũtũ kĩte ĩlawa: nĩkwĩthĩwa mũthenya o ũsu nĩnumĩtye nguthu syenyu nthĩ ya Misili: kwondũ wa ũu mũkalilikanae mũthenya ũsu mosyaanĩonĩ menyu kwĩanana na ũtw’ĩo wa tene na tene.'),
('kam', 'EXO', 12, 18, 'Mũthenya wa ĩkũmi na ĩna wĩoo, mwei wa mbee, mũkaye kĩmũtũ kĩte ĩlawa, kũvika mũthenya wa mĩongo ĩlĩ na ũmwe wĩoo.'),
('kam', 'EXO', 12, 19, 'Mĩthenya mũonza kũtikooneke ĩlawa nyũmbanĩ syenyu: nũndũ o ũla ũkaya kyu kĩ na ĩlawa, mũndũ ũsu akavetwa kuma ũmbanonĩ wa Ĩsilaeli, ethĩwa nĩ mwĩkali wa ũeninĩ, kana o ũmwe ũsyaĩtwe nthĩ ĩsu.'),
('kam', 'EXO', 12, 20, 'Mũtikaye kĩla kĩ na ĩlawa o na kĩmwe; mũkaye kĩmũtũ kĩte ĩlawa mawĩkalonĩ menyu onthe.'),
('kam', 'EXO', 12, 21, 'Nĩvo ĩndĩ Mose wametie atumĩa onthe ma Isilaeli, na amea, Thii mwose tũtena twa malondu kwĩanana na mĩvĩa yenyu, mũae vasaka.'),
('kam', 'EXO', 12, 22, 'Na osai ĩseve ya ĩsovo, na mũkĩinda nthakamenĩ ĩla ĩ ĩsaaninĩ ĩnene, na mũikũnanga kĩthaku na mĩtĩ ĩlĩ yĩ ndee sya mũomo na nthakame ĩla ĩ ĩsaaninĩ ĩnene; na kũtikethĩwe ũmwe wenyu wĩumaala mũomonĩ wa nyũmba kwake kũvika kĩoko.'),
('kam', 'EXO', 12, 23, 'Nũndũ Yeova akavĩtĩla nthĩ akũne Amisili; na yĩla wĩona nthakame kĩthakunĩ, na mĩtĩnĩ ĩlĩ yĩ ndee sya mũomo, Yeova akavĩtĩla ĩũlũ wa mũomo ũsu, na ndakanenga mwanangi ũthei alike nyũmbanĩ syenyu amũkũne.'),
('kam', 'EXO', 12, 24, 'Na mũkalilikana ũndũ ũũ ũtw’ĩke ũtw’ĩo kwaku na kwa ana maku kũvika tene na tene.'),
('kam', 'EXO', 12, 25, 'Na kũkeethĩwa, yĩla mũkavika nthĩ ĩla Yeova ũkamũnenga, kwĩanana na ũndũ wathĩte, mũkalilikanae ũthũkũmi ũũ.'),
('kam', 'EXO', 12, 26, 'Na kũkeethĩwa, yĩla syana syenyu ikamũkũlya, Ũthũkũmi ũũ nĩ ũndũ wa kĩ kwenyu?'),
('kam', 'EXO', 12, 27, 'Nĩvo ĩndĩ mũkasyĩa, Nĩ nthembo ya vasaka wa Yeova, ũla wavĩtĩle ĩũlũ wa nyũmba sya ana ma Isilaeli Misili, yĩla woaie Amisili, na avonokya nyũmba sitũ. Na andũ makunamya mĩtwe na kũthaitha.'),
('kam', 'EXO', 12, 28, 'Na ana ma Isilaeli maenda, na meeka ũu; o tondũ Yeova wameaĩe Mose na Aluni, now’o meekie.'),
('kam', 'EXO', 12, 29, 'Na kweethĩwa ũtukũ katĩ, kana Yeova akũna makithathi onthe me nthĩ ya Misili, kuma ĩkithathi ya Valao ũla wekalĩte kĩvĩlanĩ kya ũsumbĩ kũvika ĩkithathi ya ũla mwove wĩ kasũmbanĩ ke nthĩnĩ wa nthĩ; o na makithathi onthe ma ĩndo.'),
('kam', 'EXO', 12, 30, 'Na Valao ookĩla ũtukũ, we, na athũkũmi make onthe, na Amisili onthe; na kwaĩ kĩĩo kĩnene Misili; nũndũ kũtyaĩ nyũmba ĩtakw’ĩte mũndũ.'),
('kam', 'EXO', 12, 31, 'Na eeta Mose na Aluni ũtukũ, na amea, Ũkĩlai, mume andũnĩ makwa, inyw’ĩ o na ana ma Isilaeli; na mũithi, mũthũkũme Yeova, o tondũ mwaisye.'),
('kam', 'EXO', 12, 32, 'Osai ndĩthya syenyu sya mbũi na malondu na ndĩthya syenyu sya ng’ombe, o tondũ mwaisye, na mũithi; na mũingathima nakwa.'),
('kam', 'EXO', 12, 33, 'Na Amisili mamathing’ĩĩsya andũ mũno, mamaumye nthĩ na mĩtũkĩ; nũndũ maisye, Ithyonthe twĩ andũ akw’ũ.'),
('kam', 'EXO', 12, 34, 'Na andũ moosa ngũmbwa sya mũtu itaamba kwĩkĩwa ĩlawa, na syĩndũ syoo ila iluĩlawa mũtu syoveewe ngũanĩ syoo maikũa na ituo.'),
('kam', 'EXO', 12, 35, 'Na ana ma Isilaeli meeka kwĩanana na ndeto ya Mose; na meetya Amisili mĩio ya wanake ya vetha, na mĩio ya wanake ya thaavu, na ngũa:'),
('kam', 'EXO', 12, 36, 'na Yeova atuma andũ mona ũseo methonĩ ma Amisili, kũvika mamanenga o kĩla meetisye. Na mamavuta Amisili.'),
('kam', 'EXO', 12, 37, 'Na ana ma Isilaeli maenda kyalo kuma Lamesesi kũvika Sukothi, aũme ta ngili maana thanthatũ ala maendete na maũũ, eka syana.'),
('kam', 'EXO', 12, 38, 'Na nguthu ya elikya yambata vamwe namo; na ndĩthya sya mbũi na malondu, na sya ng’ombe, indo nyingĩ mũno.'),
('kam', 'EXO', 12, 39, 'Na maua tũmũtũ tũte ĩlawa kuma ngũmbwanĩ sya mũtu ila maumie nasyo Misili; nũndũ ityaĩ na ĩlawa, nũndũ nĩmalũngilw’e Misili na vinya, na matyaatonya kwĩkalanga, o na matyaaĩseũvĩsya lĩu o na wĩva.'),
('kam', 'EXO', 12, 40, 'Na ĩndĩ, ĩvinda yĩla ana ma Isilaeli mekalĩte Misili yaĩ myaka maana ana na mĩongo ĩtatũ.'),
('kam', 'EXO', 12, 41, 'Na kweethĩwa, myaka ĩsu maana ana na mĩongo ĩtatũ yathela, mũthenya o ũsu kweethĩwa atĩ nguthu syonthe sya Yeova syauma nthĩ ya Misili.'),
('kam', 'EXO', 12, 42, 'Nĩ ũtukũ wa ũlilikanĩlwa Yeova mũno nũndũ wa kũmaumya nthĩ ya Misili: ũũ nĩw’o ũtukũ ũsu wa Yeova, wa ũlilikanawa mũno nĩ ana onthe ma Isilaeli mosyaanĩonĩ moo.'),
('kam', 'EXO', 12, 43, 'Na Yeova amea Mose na Aluni, Ũũ nĩ ũtw’ĩo wa vasaka; mũndũ wa nthĩ ĩngĩ o na wĩva ndakaye w’o;'),
('kam', 'EXO', 12, 44, 'ĩndĩ mũthũkũmi wa kĩla mũndũ ũla ũthooetwe na mbesa, yĩla wĩmwaĩka, nĩvo wĩya w’o.'),
('kam', 'EXO', 12, 45, 'Mwĩkali wa ũeninĩ, na mũthũkũmi ũtuvawa matikaye w’o.'),
('kam', 'EXO', 12, 46, 'Ũkaĩĩwe nyũmbanĩ o ĩmwe; mũtĩkaumaalye kasama o na kamwe nza kuma nyũmbanĩ; o na mũtikatũle ĩvĩndĩ yao.'),
('kam', 'EXO', 12, 47, 'Ũmbano w’onthe wa Isilaeli ũkoolilikanae.'),
('kam', 'EXO', 12, 48, 'Na yĩla mũeni ũkekala ũeni kwaku, na akyenda kũlilikana vasaka kwondũ wa Yeova, aũme make onthe nĩmaĩkwe, na ĩndĩ nathengeee oolilikane; na akeethĩwa ta ũmwe ũsyaĩwe nthĩ ĩsu: ĩndĩ mũndũ o na wĩva ũte mwaĩke ndakaye w’o.'),
('kam', 'EXO', 12, 49, 'Kũkeethĩwa mwĩao ũmwe wa ũla ũsyaawa kwenyu, na wa mũeni ũla wĩkalaa ũeni kwenyu.'),
('kam', 'EXO', 12, 50, 'Now’o ana onthe ma Isilaeli meekie; o tondũ Yeova wameaĩe Mose na Aluni, now’o meekie.'),
('kam', 'EXO', 12, 51, 'Na kweethĩwa mũthenya o ũsu, Yeova nĩwaumisye ana ma Isilaeli nthĩ ya Misili nguthu na nguthu.'),
('kam', 'EXO', 13, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 13, 2, 'Mbathĩa makithathi onthe, o yĩla yĩkamba kuma ĩvunĩ ya nyinyia ananĩ ma Isilaeli, yĩla ya mũndũ o na ya nyamũ: yĩu nĩ yakwa.'),
('kam', 'EXO', 13, 3, 'Na Mose amea andũ, Lilikanai mũthenya ũũ, ũla mumie Misili, kuma nyũmbanĩ ya ũkombo; nũndũ Yeova amumisye vandũ vaa na kw’oko kwĩ vinya: kĩmũtũ kĩ na ĩlawa kĩtikaĩwe.'),
('kam', 'EXO', 13, 4, 'Mũnthĩ ũũ wa mwei wa Avivu nĩmũkuma.'),
('kam', 'EXO', 13, 5, 'Na kũkeethĩwa, yĩla Yeova wĩmũete nthĩ ya Mũkanaani, na Mũititi, na Mũamoli, na Mũivi, na Mũyevusi, ĩla wamevĩtĩe aaĩthe maku ũkũnenga, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, nĩvo wĩlilikanae ũthũkũmi ũũ mwei o ũũ.'),
('kam', 'EXO', 13, 6, 'Mũkaye kĩmũtũ kĩte ĩlawa mĩthenya mũonza, na mũthenya wa mũonza ũkeethĩwa wa mboka kwondũ wa Yeova.'),
('kam', 'EXO', 13, 7, 'Kĩmũtũ kĩte ĩlawa kĩkaĩwe mĩthenya ĩsu mũonza; na kĩmũtũ kĩ na ĩlawa kĩtikooneke kwaku, o na ĩlawa yĩtĩkooneke kwaku, mĩvakanĩ yaku yonthe.'),
('kam', 'EXO', 13, 8, 'Na mũthenya ũsu ũkatavye mwana waku, ũkĩmwĩa, Nĩ kwondũ wa ũndũ ũla Yeova wambĩkie yĩla naumie nthĩ ya Misili.'),
('kam', 'EXO', 13, 9, 'Na ũkeethĩwa ũvano kwaku kw’okonĩ kwaku, na kwondũ wa ũlilikan’yo katĩ wa metho maku, nĩ kana mwĩao wa Yeova wĩthĩwe kanyw’anĩ waku: nũndũ Yeova akumisye Misili na kw’oko kwĩ vinya.'),
('kam', 'EXO', 13, 10, 'Kwondũ wa ũu ũkalilikanae ũtw’ĩo ũũ ĩvinda yaw’o mwaka na mwaka.'),
('kam', 'EXO', 13, 11, 'Na kũkeethĩwa, Yeova amũete nthĩ ya Mũkanaani, o tondũ wakwĩvĩtĩe we, na aaĩthe maku, na ũkũnenga,'),
('kam', 'EXO', 13, 12, 'atĩ ũkamũvathĩe Yeova onthe ala mambaa kuma ĩvunĩ ya nyinyia, o na kĩla ĩkithathi yĩla wĩ nayo yumaa nyamũnĩ; ila nũme ikeethĩwa syĩ sya Yeova.'),
('kam', 'EXO', 13, 13, 'Na kĩla ĩkithathi ya ĩng’oi ũkovosye na katena ka ĩlondu; na ethĩwa ndũkwenda kũyovosya, ũkayĩtũle ngingo ĩndĩ: na makithathi onthe ma andũ ananĩ maku ũkovosye.'),
('kam', 'EXO', 13, 14, 'Na kũkeethĩwa, o yĩla mwana waku ũkakũkũlya ĩvinda yĩla yũkĩte, aikwĩa, Ũũ nata? Ũkamwĩa, Yeova atumisye Misili, kuma nyũmbanĩ ya ũkombo na kw’oko kwĩ vinya:'),
('kam', 'EXO', 13, 15, 'na kweethĩwa, yĩla Valao womisye ngoo yake ndakatũlekye tũthi, Yeova nĩwoaie makithathi onthe nthĩ ya Misili, ĩkithathi ya mũndũ, o na ĩkithathi ya nyamũ: kwondũ wa ũu nĩthembee Yeova onthe ala mambaa kuma ĩvunĩ ya nyinyia, me maũme; ĩndĩ makithathi onthe ananĩ makwa nĩnovoasya.'),
('kam', 'EXO', 13, 16, 'Na ũndũ ũsu ũkeethĩwa ũvano kw’okonĩ kwaku, na ũlilikan’yo katĩ wa metho maku: nũndũ Yeova nĩwatumisye Misili na kw’oko kwĩ vinya.'),
('kam', 'EXO', 13, 17, 'Na kweethĩwa, yĩla Valao waĩ analekya andũ mathi; Ngai ndaamatongoesya na nzĩa ya nthĩ ya Avilisiti, o na kau yaĩ nguvĩ; nũndũ Ngai aisye, Andũ matikese kwĩalyũla moona kaũ, na makĩsyoka Misili:'),
('kam', 'EXO', 13, 18, 'ĩndĩ Ngai atongoesya andũ na nzĩa ya kĩthyũlũlũ, na nzĩa ya ya weũnĩ vakuvĩ na Ũkanga Mũtune: na ana ma Isilaeli mauma nthĩ ya Misili mekĩe mĩio ya kaũ.'),
('kam', 'EXO', 13, 19, 'Na Mose akua mavĩndĩ ma Yosevu: nũndũ we nĩwameavĩthisye na vinya ana ma Isilaeli, akĩmea, Ngai ndatia kũmũsisya; nenyu mũkakue mavĩndĩ makwa maume kũũ.'),
('kam', 'EXO', 13, 20, 'Na mathi kyalo kuma Sukothi, na mamba maeema Ethamu, mũvakanĩ wa weũnĩ.'),
('kam', 'EXO', 13, 21, 'Na Yeova aendaa mbee woo mũthenya e nthĩnĩ wa kĩtuĩ kya mũumbĩ, amatongoesye nzĩanĩ, na ũtukũ e nthĩnĩ wa kĩtuĩ kya mwaki, amanenge kyeni; nĩ kana maendae mũthenya na ũtukũ:'),
('kam', 'EXO', 13, 22, 'kĩla kĩtuĩ kya mũumbĩ mũthenya, na kĩtuĩ kya mwaki ũtukũ kĩtyaauma mbee wa andũ.'),
('kam', 'EXO', 14, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 14, 2, 'Mee ana ma Isilaeli mealyũle mambe maeema kwelekela Vi‐ailothi, katĩ wa Mikitoli na ũkanga, kwelekela Mbaali‐nzevoni: mũkambe maeema vakuvĩ na ũkanga mũmyelekele.'),
('kam', 'EXO', 14, 3, 'Na Valao akaneena ũndũ wa ana ma Isilaeli atĩĩ, Nĩmalingisanĩlw’e nĩ nthĩ, weũ nũmavingĩĩte nzĩa.'),
('kam', 'EXO', 14, 4, 'Na ngoomya ngoo ya Valao, na akamaatĩĩa; nakwa ngeethĩwa na ndaĩa kũla kwĩ Valao, na kũla kwĩ nguthu yake yonthe; na Amisili makamanya ninyie Yeova. Na meeka ũu.'),
('kam', 'EXO', 14, 5, 'Na mũsumbĩ wa Misili atavw’a kana andũ nĩmakĩie: na ngoo ya Valao na sya athũkũmi make syaalyũka ũndũ wa ala andũ, na masya, Ũũ twĩkĩte nata, kũmalekya Isilaeli mathĩ maeka kũtũthũkũmaa?'),
('kam', 'EXO', 14, 6, 'Na oomban’ya ĩkasya yake ya kaũ, na athi na andũ make:'),
('kam', 'EXO', 14, 7, 'na athi na makasya manyuve ma kaũ maana thanthatũ, na makasya onthe ma kaũ ma Misili, na makavuteni masyo syonthe.'),
('kam', 'EXO', 14, 8, 'Na Yeova oomya ngoo ya Valao mũsumbĩ wa Misili, na aatĩĩa ana ma Isilaeli; nũndũ ana ma Isilaeli maumie na kw’oko kwĩ vinya.'),
('kam', 'EXO', 14, 9, 'Na Amisili mamaatĩĩa, mbalasi na makasya onthe ma kaũ ma Valao, na andũ make onthe ala matũlĩte mbalasi, na ĩta syake, na mamawĩla mambĩte maeema vakuvĩ na ũkanga, ũtee wa Vi‐ailothi, kwelekela Mbaali‐nzevoni.'),
('kam', 'EXO', 14, 10, 'Na Valao athengeea, ana ma Isilaeli mookĩlya metho moo, na sisya, Amisili maĩ mamaatĩĩe; na makĩa mũno: na ana ma Isilaeli mamwĩkaĩla Yeova.'),
('kam', 'EXO', 14, 11, 'Na mamũkũlya Mose, Nĩkwĩthĩwa kũtyaĩ mbũa Misili, nĩwatumĩsye tũkw’ĩe weũnĩ? Ũtwĩkĩte ũu nĩkĩ, kũtumya Misili?'),
('kam', 'EXO', 14, 12, 'Ĩsu ti ĩla ndeto twakũtavĩsye Misili, tũkĩkwĩa, Tũeke, tũmathũkũmae Amisili? Nũndũ kwĩ kavaa tũmathũkũmae Amisili, kwĩ tũikw’ĩa weũnĩ.'),
('kam', 'EXO', 14, 13, 'Na Mose amea andũ, Mũtikakĩe, ũngamai, na nĩmũkwona ũtangĩĩo wa Yeova, ũla wĩĩka kwondũ wenyu ũmũnthĩ, nũndũ Amisili ala mũmene ũmũnthĩ, mũtikamona ĩngĩ nongi.'),
('kam', 'EXO', 14, 14, 'Yeova akamũkitĩa, nenyu mũkavindya ki.'),
('kam', 'EXO', 14, 15, 'Na Yeova amwĩa Mose, Wĩmbĩkaĩla nĩkĩ? Mee ana ma Isilaeli maendeee na mbee.'),
('kam', 'EXO', 14, 16, 'Naku ũkĩlya ndata yaku, noitambũũkya kw’oko kwaku ĩũlũ wa ũkanga, ũaan’ye: na ana ma Isilaeli makalika ũkanganĩ katĩ makinyĩle nthĩ nyũmũ.'),
('kam', 'EXO', 14, 17, 'Nakwa, sisya, ngoomya ngoo sya Amisili, na makalika makĩmaatĩĩa: na ngeethĩwa na ndaĩa kũla kwĩ Valao, na kũla kwĩ nguthu yake yonthe, na makasya make ma kaũ, na andũ make matũlĩte mbalasi.'),
('kam', 'EXO', 14, 18, 'Na Amisili makamanya ninyie Yeova, yĩla nĩtaĩwa kũla kwĩ Valao, na makasya make ma kaũ, na andũ make ala matũlĩte mbalasi.'),
('kam', 'EXO', 14, 19, 'Na mũlaĩka wa Ngai, ũla watongoeasya nguthu ya Isilaeli, auma vo na asyoka ĩtina woo; na kĩla kĩtuĩ kya mũumbĩ kyauma mbee woo na kyaũngama ĩtina woo:'),
('kam', 'EXO', 14, 20, 'na kyooka katĩ wa nguthu ya Misili na nguthu ya Isilaeli; na kwaĩ mũumbĩ na kĩvindu, ĩndĩ kyakenaa ũtukũ: na nguthu ĩmwe ndĩaathengeea ĩla ĩngĩ ũtukũ w’onthe.'),
('kam', 'EXO', 14, 21, 'Na Mose atambũũkya kw’oko kwake ĩũlũ wa ũkanga; na Yeova atuma ũkanga ũtaanĩsya na kĩuutani kĩ vinya kyumĩte wumĩlonĩ wa syũa ũtukũ w’onthe, na atw’ĩkĩthya ũkanga nthĩ nyũmũ, na ĩw’ũ syaanw’a.'),
('kam', 'EXO', 14, 22, 'Na ana ma Isilaeli malika ũkanganĩ katĩ makinyĩle nthĩ nyũmũ: na iw’ũ syatw’ĩka ũvai kwoo kw’okonĩ kwoo kwa aũme na kwa aka.'),
('kam', 'EXO', 14, 23, 'Na Amisili mamaatĩĩa, na malika ũkanganĩ katĩ ĩtina woo, mbalasi syonthe sya Valao, na makasya make ma kaũ, na andũ make ala matũlĩte mbalasi.'),
('kam', 'EXO', 14, 24, 'Na kweethĩwa ũsyaĩĩsyonĩ wa kĩoko, Yeova asisya nguthu ya Amisili e kĩtuĩnĩ kya mwaki na mũumbĩ, na athĩn’ya nguthu ya Amisili.'),
('kam', 'EXO', 14, 25, 'Na aumya ndĩa sya makasya moo, na matwawa na vinya; na ĩndĩ Amisili masya, Tũkĩe tume ũthyũnĩ wa Isilaeli; nũndũ Yeova nũnũũmokitĩa kwa Amisili.'),
('kam', 'EXO', 14, 26, 'Na Yeova amwĩa Mose, Tambũũkya kw’oko kwaku ĩũlũ wa ũkanga, nĩ kana iw’ũ isyokeanĩe ĩngĩ ĩũlũ wa Amisili, na ĩũlũ wa makasya moo ma kaũ, na ĩũlũ wa andũ moo matũlĩte mbalasi.'),
('kam', 'EXO', 14, 27, 'Na Mose atambũũkya kw’oko kwake ĩũlũ wa ũkanga, na kwakya ũkanga wasyoka waenda na vinya o ũndũ waendaa; na Amisili mookĩa; na Yeova anangĩa Amisili ũkanganĩ katĩ.'),
('kam', 'EXO', 14, 28, 'Na iw’ũ syasyokeanĩa, syavw’ĩka makasya ma kaũ, na andũ ala matũlĩte mbalasi, o na nguthu yonthe ya Valao ĩla yamavikĩlĩle ũkanganĩ; kũtyaatialw’a o na ũmwe woo.'),
('kam', 'EXO', 14, 29, 'Ĩndĩ ana ma Isilaeli makinyĩla nthĩ nyũmũ ũkanganĩ katĩ; na ila iw’ũ syatw’ĩka ũvai kwoo kw’okonĩ kwoo kwa aũme na kwa aka.'),
('kam', 'EXO', 14, 30, 'Ũũ nĩw’o Yeova watangĩĩe Isilaeli mũthenya ũsu kũmaumya kw’okonĩ kwa Amisili; na Isilaeli moona Amisili me akw’ũ ũtee wa ũkanga.'),
('kam', 'EXO', 14, 31, 'Na Isilaeli moona ũndũ ũsu ũnene ũla Yeova wekie Amisili, na andũ makĩa Yeova: na meetĩkĩla Yeova, na mũthũkũmi wake Mose.'),
('kam', 'EXO', 15, 1, 'Nĩvo ĩndĩ Mose na ana ma Isilaeli mamwinĩe Yeova wathi ũũ, na maina, makyasya, Nĩngũmwinĩa Yeova, nũndũ nĩwakĩlilye vinya na ũkĩlyo mũnene: Mbalasi na ũla ũmĩtũlĩte nĩwĩkĩtye ũkanganĩ.'),
('kam', 'EXO', 15, 2, 'Yeova nĩwe vinya wakwa, na wathi wakwa, Nake nũtw’ĩkĩte ũtangĩĩo wakwa. Ũsu nĩwe Ngai wakwa, na ngamũtaĩa we; Nĩ Ngai wa asa wakwa, na ngamũnenevya.'),
('kam', 'EXO', 15, 3, 'Yeova nĩ mũndũ wa kaũ: Yeova nĩ syĩtwa yake.'),
('kam', 'EXO', 15, 4, 'Makasya ma kaũ ma Valao na nguthu yake nũsyĩkĩtye ũkanganĩ; Na makavuteni make ala anyuve nĩmalikilw’e Ũkanganĩ Mũtane.'),
('kam', 'EXO', 15, 5, 'Manzĩ ma syũngũ nene nĩmamavw’ĩka: Nĩmalikile syũngũnĩ o ta ĩvia.'),
('kam', 'EXO', 15, 6, 'Ame Yeova, kw’oko kwaku kwa aũme nĩ kũnene vĩnyanĩ, Ame Yeova, kw’oko kwaku kwa aũme nĩkũng’atanasya ũla mũmaitha.'),
('kam', 'EXO', 15, 7, 'Na kwondũ wa wingĩ wa ũnene waku ũvĩtũkĩte nũmanangaa asu makũkĩlĩlaa: Nũwumasya ũthilĩku waku, naw’o ũmaminaa ta mavuthĩ.'),
('kam', 'EXO', 15, 8, 'Na ũndũ wa mĩthũmũ ya manyiũũ maku iw’ũ nĩsyookĩlanilye ĩũlũ, Iw’ũ nyingĩ syaũngama ta kĩvumbũ; Manzĩ ma syũngũ makama ũkanganĩ nthĩnĩ.'),
('kam', 'EXO', 15, 9, 'Ũla mũmaitha asya, Nyie nĩngũatĩĩa, nĩngũkwata, nĩngũaan’ya mũtavo: Wendi wakwa nũkwĩanĩw’a ku maĩ; Nĩngũkũa ũvyũ wakwa, kw’oko kwakwa kũkamananga.'),
('kam', 'EXO', 15, 10, 'Naku wauutan’ya kĩuutani kyaku, na ũkanga wamavw’ĩka: Malika o ta ĩvulũ manzĩnĩ maingĩ.'),
('kam', 'EXO', 15, 11, 'Ũla ũtilyĩ taku katĩ wa i ngai nũũ, ame Yeova? Nũũ ũtilyĩ taku, wĩ ndaĩa ũtheunĩ, Kũkĩwa ndaĩanĩ, ũkĩka moseng’yo?'),
('kam', 'EXO', 15, 12, 'Nũtambũũkisye kw’oko kwaku kwa aũme, Nthĩ yamamelya.'),
('kam', 'EXO', 15, 13, 'We, ũndũ wa ũseo waku wĩ wendo, nũtongoesye andũ ala wovoetye: Nũmatongoesye na vinya waku kũvika wĩkalonĩ waku mũtheu.'),
('kam', 'EXO', 15, 14, 'Ngo sya andũ nĩsyĩw’ĩte, nĩũtetema: Woo nũmakwatĩte ala matwĩe Vilisitia.'),
('kam', 'EXO', 15, 15, 'Nĩvo ĩndĩ anene ma Etomu matevie; Ngũmbaũ sya Moavi syakwatwa nĩ kũtetema: Onthe ala matwĩe Kanaani manyaĩĩka maaa.'),
('kam', 'EXO', 15, 16, 'Ũtĩsyo na w’ĩa mũnene niũmavalũkĩla; Kwondũ wa ũnene wa kw’oko kwaku nĩmavindĩtye ta ĩvia; Kũvika yĩla andũ maku meinga, ame Yeova, O kũvika yĩla andũ ala wathooete meinga.'),
('kam', 'EXO', 15, 17, 'Ũkamalikya, na kũmavanda kĩĩmanĩ kya ũtiĩwa waku, Vandũ vala weeseũvĩsye wĩkalae, ame Yeova, O vala vandũ vatheu, ame Mwĩaĩi, vala moko maku malũlũmĩlĩtye.'),
('kam', 'EXO', 15, 18, 'Yeova akasumbĩka tene na tene.'),
('kam', 'EXO', 15, 19, 'Nũndũ mbalasi sya Valao syalika ũkanganĩ syĩ vamwe na makasya make ma kaũ na andũ make ala matũlĩte mbalasi, na Yeova atũngĩanĩa manzĩ ma ũkanga mamavw’ĩka; ĩndĩ ana ma Isilaeli makinyĩle nthĩ nyũmũ ũkanganĩ katĩ.'),
('kam', 'EXO', 15, 20, 'Na Miliamu, mwathani, mwĩĩtu‐a‐inyia wa Aluni, oosa kathembe kw’okonĩ kwake; na aka onthe mamũatĩĩa me na tũthembe makina.'),
('kam', 'EXO', 15, 21, 'Na Miliamu ametĩkĩĩsya, Mwinĩei Yeova, nũndũ nĩwakĩlilye vinya na ũkĩlyo mũnene; Mbalasi na ũla ũmĩtũlĩte nĩwĩkĩtye ũkanganĩ.'),
('kam', 'EXO', 15, 22, 'Na Mose atongoesya Isilaeli maendeee kuma Ũkanga Mũtune, na maendeee weũnĩ wa Suli; na mathi mĩthenya ĩtatũ weũnĩ, matona manzĩ.'),
('kam', 'EXO', 15, 23, 'Na mavika Mala, matyaatonya kũnyw’a manzĩ ma Mala, nũndũ maĩ ũũ: kwondũ wa ũu veetwa Mala.'),
('kam', 'EXO', 15, 24, 'Na andũ mamũnyungunyĩĩsya Mose, makyasya, Twinyw’a kyaũ?'),
('kam', 'EXO', 15, 25, 'Nake amwĩkaĩla Yeova; na Yeova amwon’ya mũtĩ, nake awĩkya manzĩnĩ, na manzĩ maya mũyo. Vu amatw’ĩĩa mwamũlo na ũtw’ĩo, na nĩvo wamatatie;'),
('kam', 'EXO', 15, 26, 'na asya, Ethĩwa ũkew’aa wasya wa Yeova Ngai waku na kĩthing’ĩĩsyo, na kwĩkaa ũla wonaa wĩ ũlũngalu, na kũtea matũ mĩaonĩ yake, na kũkwataa myamũlo yake yonthe, ndĩkakũetee mowau o na ũmwe wa ala namaetee Amisili: nũndũ ninyie Yeova ũla ũkũvoasya.'),
('kam', 'EXO', 15, 27, 'Na mavika Elimu, vala vaĩ mbuluti ĩkũmi na ili sya manzĩ, na mĩtende mĩongo mũonza: na mamba maeema vu vakuvĩ na manzĩ.'),
('kam', 'EXO', 16, 1, 'Na maenda kyalo kuma Elimu, na ũmbano w’onthe wa ana ma Isilaeli wavika weũnĩ wa Sini, ũla wĩ katĩ wa Elimu na Sinai, mũthenya wa ĩkũmi na ĩtano wa mwei wa kelĩ ĩtina wa mauma nthĩ ya Misili.'),
('kam', 'EXO', 16, 2, 'Na ũmbano w’onthe wa ana ma Isilaeli wamanyungunyĩĩsya Mose na Aluni weũnĩ:'),
('kam', 'EXO', 16, 3, 'na ana ma Isilaeli mamea, Twenda kethĩwa tũnakwie nĩ kw’oko kwa Yeova twĩ nthĩ ya Misili, yĩla twekalaa vakuvĩ na mbisũ sya nyama yĩla twaĩsaa imũtũ tũkavũna; nũndũ nĩmũtũetete weũnĩ ũũ, mũae ũmbano ũũ w’onthe na nzaa.'),
('kam', 'EXO', 16, 4, 'Nĩvo ĩndĩ Yeova wamwĩie Mose, Sisya, ngamuĩsya mbua ya imũtũ kuma ĩtunĩ; na andũ makaumaalaa kĩla mũthenya makolan’ye sya kũmeanĩa mũthenya o ũsu, nĩ kana nĩmatate, ethĩwa makakinya mwĩaonĩ wakwa, kana ti w’o.'),
('kam', 'EXO', 16, 5, 'Na kũkeethĩwa mũthenya wa thanthatũ, makaseũvye ila mekũete, nasyo ikeethĩwa kũndũ kwĩlĩ sya ila makolanasya mũthenya na mũthenya.'),
('kam', 'EXO', 16, 6, 'Na Mose na Aluni mamea ana ma Isilaeli atĩĩ, Wĩoo, nĩvo mwĩmanya atĩ Yeova nũmumĩtye nthĩ ya Misili;'),
('kam', 'EXO', 16, 7, 'na kĩoko, nĩvo ĩndĩ mwĩona ũnene wa Yeova; nĩkwĩthĩwa nĩwĩw’aa monyungunyĩsyo menyu ĩũlũ wa Yeova: na ithyĩ twĩ aaũ, ũndũ mũũtũnyungunyĩĩsya ithyĩ?'),
('kam', 'EXO', 16, 8, 'Na Mose amea, Ũũ ũkeethĩwa, yĩla Yeova wĩmũnenga wĩoo nyama ya kũya, na kĩoko imũtũ sya kũmũvũn’ya; nĩkwĩthĩwa Yeova nĩwĩw’aa monyungunyĩsyo menyu ala mũmũnyungunyĩĩasya: na ithyĩ twĩ aaũ? Monyungunyĩsyo menyu mati ĩũlũ waitũ, ĩndĩ nĩ ĩũlũ wa Yeova.'),
('kam', 'EXO', 16, 9, 'Na Mose amwĩa Aluni, Tavya ũmbano w’onthe wa ana ma Isilaeli atĩĩ, Thengeeai Yeova; nũndũ nĩwĩw’ĩte monyungunyĩsyo menyu.'),
('kam', 'EXO', 16, 10, 'Na kweethĩwa, Aluni akĩneena na ũmbano w’onthe wa ana ma Isilaeli, masisya kwelekela weũnĩ, na sisya, ũtheu mũtisu wa Yeova waumĩla ũla mũumbĩnĩ.'),
('kam', 'EXO', 16, 11, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 16, 12, 'Nĩnĩw’ĩte monyungunyĩsyo ma ana ma Isilaeli: neena namo, ũkĩmea, Wĩoo mũkaya nyama, na kĩoko mũkavũnw’a na imũtũ; na mũkamanya ninyie Yeova Ngai wenyu.'),
('kam', 'EXO', 16, 13, 'Na kweethĩwa wĩoo, ngwae syaumĩla syavw’ĩka mwako wa maeema: na kĩoko ĩmwe yathyũlũlũka mwako wa maeema.'),
('kam', 'EXO', 16, 14, 'Na ĩmwe yĩla yaĩ nthĩ yatw’ĩka, sisya, kw’onthe weũnĩ kwaĩ kĩndũ kĩnini kĩlinge kĩ nthĩ, kĩnini ta ĩmwe yĩkamĩtw’e nĩ mbevo.'),
('kam', 'EXO', 16, 15, 'Na yĩla ana ma Isilaeli makyonie, makũlan’ya ene kwa ene, Nĩ kyaũ? Nũndũ matyaamanya nĩ kyaũ. Na Mose amea, Nĩ imũtũ ila Yeova ũmũnengete mũye.'),
('kam', 'EXO', 16, 16, 'Ũũ nĩ ũla Yeova wĩaĩte, Kolan’yai kwĩanana na ũndũ kĩla mũndũ ũĩsaa; mũkose kya ĩmisi kĩla mũndũ, kwĩanana na ũtalo wa andũ menyu, kĩla mũndũ kwondũ wa asu me ĩeemanĩ kwake.'),
('kam', 'EXO', 16, 17, 'Na ana ma Isilaeli meeka ũu, na amwe makolan’ya nyingĩ na angĩ nini.'),
('kam', 'EXO', 16, 18, 'Na yĩla mathima na ĩmisi, ũsu wakolan’ya nyingĩ ndaatialĩlwa nĩ kĩndũ, na ũsu wakolan’ya nini ndaanyivĩwa; makolanasya kĩla mũndũ kwĩanana na ũndũ ũĩsaa.'),
('kam', 'EXO', 16, 19, 'Na Mose amea, Mũndũ o na wĩva ndakaitialye kũvika kĩoko.'),
('kam', 'EXO', 16, 20, 'Ĩndĩ matyaamwĩthukĩĩsya Mose; ĩndĩ amwe moo maitialya kũvika kĩoko, na syaya iinyu na syanyunga naĩ: na Mose amathilĩkĩa mũno.'),
('kam', 'EXO', 16, 21, 'Na maikolanasya syo kĩoko na kĩoko, kĩla mũndũ kwĩanana na ũndũ ũĩsaa: na syũa yavyũva, syatweka.'),
('kam', 'EXO', 16, 22, 'Na kweethĩwa, mũthenya wa thanthatũ makolan’ya imũtũ isu kũndũ kwĩlĩ, mamisi elĩ kĩla ũmwe: na anene onthe ma ũla ũmbano mooka, matavya Mose.'),
('kam', 'EXO', 16, 23, 'Na amea, Ũũ nĩ ũndũ Yeova ũneenete, Ũnĩ nĩ ũthũmũo mũuu, savato mũtheu kwa Yeova: kaangai ila mwĩkaanga, na uai ila mwĩua; na syonthe ila itialw’a mwie ũndũ wenyu syĩkale kũvika kĩoko.'),
('kam', 'EXO', 16, 24, 'Na maia kũvika kĩoko, o tondũ Mose wameaĩe: na ityaanyunga naĩ, o na ityaĩ kĩinyu o na kĩmwe nthĩnĩ wasyo.'),
('kam', 'EXO', 16, 25, 'Na Mose amea, Yai isu ũmũnthĩ; nũndũ ũmũnthĩ nĩ savato kwondũ wa Yeova: ũmũnthĩ mũtisyona weũnĩ.'),
('kam', 'EXO', 16, 26, 'Mũkaikolanasya mĩthenya thanthatũ; ĩndĩ mũthenya wa mũonza nĩ savato, itikethĩwa mũthenya ũsu.'),
('kam', 'EXO', 16, 27, 'Na kweethĩwa mũthenya wa mũonza, andũ amwe maumaala makolan’ye, na matyaaona o na vanini.'),
('kam', 'EXO', 16, 28, 'Na Yeova amwĩa Mose, Mwĩlea kũsũvĩa motw’ĩo makwa na mĩao yakwa kũvika ĩndĩĩ?'),
('kam', 'EXO', 16, 29, 'Sisya, nĩkwĩthĩwa Yeova nũmũnengete savato, kwondũ wa ũu nũmũnengae mũthenya wa thanthatũ ĩmũtũ sya mĩthenya ĩlĩ; ĩkalai kĩla mũndũ vandũ vake, mũndũ o na wĩva ndakaumaale kwake mũthenya wa mũonza.'),
('kam', 'EXO', 16, 30, 'Na kwondũ wa ũu andũ mathũmũa mũthenya wa mũonza.'),
('kam', 'EXO', 16, 31, 'Na nyũmba ya Isilaeli yeeta kĩndũ kyu Mana: na kyaĩ kyeũ, ta mbeke ya kolianda; na ũsamo wakyo waĩ ta tũmĩkate tũvũthũ tũvulanĩtw’e na ũki wa nzũkĩ.'),
('kam', 'EXO', 16, 32, 'Na Mose asya, Ũũ nĩ ũla Yeova wĩaĩte, Ĩmisi yusĩe kyo yiwe yĩkale ũndũ wa mosyaanĩo menyu, nĩ kana mone lĩu namũathĩasya weũnĩ, yĩla namumisye nthĩ ya Misili.'),
('kam', 'EXO', 16, 33, 'Na Mose amwĩa Aluni, Osa kavisũ, wĩkĩe mana wa ĩmisi yusĩe nthĩnĩ wako, na ũkia mbee wa Yeova, ũsũvĩwe ũndũ wa mosyaanĩo menyu onthe.'),
('kam', 'EXO', 16, 34, 'O tondũ Yeova wamwĩaĩe Mose, Aluni awiie o ta ũu mbee wa Ĩsandũkũ ya Ũkũsĩ, ũsũvĩwe.'),
('kam', 'EXO', 16, 35, 'Na ana ma Isilaeli maĩsaa ũla mana myaka mĩongo ĩna, mũvaka mavika nthĩ yĩ andũ; nĩmaĩsaa ũla mana, mũvaka mavika mĩvakanĩ ya nthĩ ya Kanaani.'),
('kam', 'EXO', 16, 36, 'Na ĩndĩ ĩmisi yĩu nĩ kĩlungu kĩmwe kya ĩkũmi kya eva.'),
('kam', 'EXO', 17, 1, 'Na ũmbano w’onthe wa ana ma Isilaeli waenda kyalo kuma weũnĩ wa Sini, o ũndũ syalo syoo syailyĩ, kwĩanana na mwĩao wa Yeova, na mamba maeema Levitimu; na kũtyaĩ manzĩ ma ũnyuwa nĩ andũ.'),
('kam', 'EXO', 17, 2, 'Kwondũ wa ũu andũ matetan’ya na Mose, na mamwĩa, Tũnenge manzĩ tũnyw’e. Na Mose amea, Mwĩtetan’ya nakwa nĩkĩ? Mwĩmũtata Yeova nĩkĩ?'),
('kam', 'EXO', 17, 3, 'Na andũ meew’ĩa waũni wa manzĩ vo; na andũ mamũnyungunyĩĩsya Mose, na mamwĩa, Watumisye Misili nĩkĩ, ũtũae na syana sitũ na indo sitũ na waũni?'),
('kam', 'EXO', 17, 4, 'Na Mose amwĩkaĩla Yeova, akyasya, Nĩĩka andũ aa ata? Makilĩlye kũngima na mavia.'),
('kam', 'EXO', 17, 5, 'Na Yeova amwĩa Mose, Vĩta we mbee wa andũ, na ũkĩthi na atumĩa amwe ma Isilaeli: na ndata yaku, ĩla wakũnie ũsĩ nayo, ũkue kw’okonĩ kwaku, noithi.'),
('kam', 'EXO', 17, 6, 'Sisya, nĩngũũngama ĩvianĩ mbee waku vu Olevu; naku ũkakũne ĩvia, nayo yĩkauma manzĩ, nĩ kana andũ manyw’e. Na Mose eeka ũu atumĩa ma Isilaeli mene.'),
('kam', 'EXO', 17, 7, 'Na eeta syĩtwa ya vandũ vau Masa, na ĩngĩ Meliva, nũndũ wa motetan’yo ma ana ma Isilaeli, na nũndũ nĩmatatie Yeova, makĩkũlya, Yeova e vamwe naitũ, kana tĩ w’o?'),
('kam', 'EXO', 17, 8, 'Nĩvo ĩndĩ Amaleki mookie, na mokitĩa na Isilaeli ku Levitimu.'),
('kam', 'EXO', 17, 9, 'Na Mose amwĩa Yosua, Tũnyuvĩe andũ, noithi wũkite na Amaleki: ũnĩ ngaũngama mũtumbĩnĩ wa kĩĩma nĩ na ndata ya Ngai kw’okonĩ kwakwa.'),
('kam', 'EXO', 17, 10, 'Na ĩndĩ Yosua eeka o tondũ Mose wamwĩe, na okita na Amaleki: na Mose, na Aluni, na Uulu mambata mũtumbĩnĩ wa kĩĩma.'),
('kam', 'EXO', 17, 11, 'Na kweethĩwa, yĩla Mose wokĩlilye kw’oko kwake, Isilaeli makĩlya vinya; na yĩla watheeisye kw’oko kwake, Amaleki makĩlya vinya.'),
('kam', 'EXO', 17, 12, 'Ĩndĩ moko ma Mose maĩ maito; namo moosa ĩvia, mamwiĩa nthĩ, nake ayĩkalĩla; na Aluni na Uulu matw’ĩĩka moko make mokĩlĩtye na ĩũlũ, ũmwe ngalĩ ĩmwe, na ũndĩ ngalĩ ĩla ĩngĩ; na moko make matw’ĩĩkwa kũvika syũa yathũa.'),
('kam', 'EXO', 17, 13, 'Na Yosua amakĩlya Amaleki na andũ make vinya kwa kũmatemanga na ũvyũ.'),
('kam', 'EXO', 17, 14, 'Na Yeova amwĩa Mose, Andĩka ũũ ĩvukunĩ wĩthĩwe ũlilikan’yo, noitavya Yosua kana ew’e: atĩ ngaananga vyũ ũlilikano wa Amaleki ĩtheo wa ĩtu.'),
('kam', 'EXO', 17, 15, 'Na Mose aaka kĩthembeo, na eeta syĩtwa yakyo Yeova‐nisi:'),
('kam', 'EXO', 17, 16, 'na asya, Yeova nĩwĩvĩtĩte: Yeova akeethĩawa na kaũ na Amaleki kuma nzyawa na nzyawa.'),
('kam', 'EXO', 18, 1, 'Na ĩndĩ Yethilo, mũthembi wa Mitiani, mũthoni wa Mose, eew’a onthe ala Yeova wekĩte ũndũ wa Mose, na ũndũ wa Isilaeli andũ make, ũndũ Yeova waumĩtye Isilaeli Misili.'),
('kam', 'EXO', 18, 2, 'Na Yethilo, mũthoni wa Mose, oosa Nzivola, mũka wa Mose, ũla waĩ anatũnga kwa ĩthe,'),
('kam', 'EXO', 18, 3, 'na ivĩsĩ syake ilĩ; syĩtwa ya kĩmwe kyeetawa Ngelisoni; nũndũ aisye, Nĩnaĩ mwĩkali wa ũeninĩ nthĩ ĩngĩ:'),
('kam', 'EXO', 18, 4, 'na syĩtwa ya kĩngĩ kyeetawa Elieseli; nũndũ aisye, Ngai wa nau aĩ mũtethya wakwa, na andangĩĩa kuma ũvyũnĩ wa Valao.'),
('kam', 'EXO', 18, 5, 'Na Yethilo, mũthoni wa Mose, athi na ivĩsĩ syake na mũka wake kũla kwĩ Mose weũnĩ kũla wambĩte maeema, ku kĩĩmanĩ kya Ngai:'),
('kam', 'EXO', 18, 6, 'na amwĩa Mose, Nyie Yethilo, mũthonuu, nĩnũkĩte kũla ũĩ, o na mũka waku, vamwe na ivĩsĩ syake ilĩ.'),
('kam', 'EXO', 18, 7, 'Na Mose athi amũthaũe mũthoni, na eekunamya vyũ, na amũmumunya; na makũlan’ya ũvoo ene kwa ene; na malika ĩeemanĩ.'),
('kam', 'EXO', 18, 8, 'Na Mose atavya mũthoni onthe ala Yeova wekie Valao na Amisili kwondũ wa Isilaeli, na thĩna w’onthe ũla wamokĩie nzĩanĩ, na ũndũ Yeova wamatangĩĩe.'),
('kam', 'EXO', 18, 9, 'Na Yethilo atana ũndũ wa ũseo w’onthe ũla Yeova wamekie Isilaeli, nĩkwĩthĩwa nĩwamatangĩĩie kũmaumya mokonĩ ma Amisili.'),
('kam', 'EXO', 18, 10, 'Na Yethilo asya, Nataĩwe Yeova, ũla ũmũtangĩĩĩte kuma mokonĩ ma Amisili, na kuma kw’okonĩ kwa Valao; we ũla ũtangĩĩĩte andũ kuma mokonĩ ma Amisili.'),
('kam', 'EXO', 18, 11, 'Yu nĩnĩsĩ kana Yeova nĩ mũnene kwĩ ngai syonthe; ĩĩ, o na ũndũnĩ ũla syamekathĩĩe.'),
('kam', 'EXO', 18, 12, 'Na Yethilo, mũthoni wa Mose, amwosea Ngai nthembo ya kũvĩvw’a na nthembo sya kũtonywa: na Aluni ooka, e na atumĩa onthe ma Isilaeli, maĩĩe lĩu na mũthoni wa Mose mbee wa Ngai.'),
('kam', 'EXO', 18, 13, 'Na kweethĩwa ũnĩ ũsu, Mose ekala nthĩ asilan’ye andũ: nao andũ asu maũngama mamũthyũlũlũkĩte Mose kuma kĩoko kũvika wĩoo.'),
('kam', 'EXO', 18, 14, 'Na yĩla mũthoni wa Mose wonie onthe ala wekie andũ, amwĩa, Ũndũ ũũ wĩkaa andũ nĩ mwaũ? Nĩkĩ wĩkalaa wĩ weka, na andũ onthe makĩũngama makũthyũlũlũkĩte kuma kĩoko kũvika wĩoo?'),
('kam', 'EXO', 18, 15, 'Na Mose amwĩa mũthoni, Nĩkwĩthĩwa andũ nĩmandokeaa nĩ kana nĩmakũlĩlye kwa Ngai;'),
('kam', 'EXO', 18, 16, 'yĩla me na ũndũ, nĩmokaa kũla nĩĩ; na nĩngũmasilan’ya mũndũ na mũtũi wake, na ngĩmamanyĩthya myamũlo ya Ngai, na mĩao yake.'),
('kam', 'EXO', 18, 17, 'Na mũthoni wa Mose amwĩa, Ũndũ ũla wĩkaa ti ũseo.'),
('kam', 'EXO', 18, 18, 'Ũkanoa vate ndĩi wae vinya, naku, o na andũ aa ala me naku: nũndũ ũndũ ũũ nũvĩtũkĩte vinya waku; ndũtonya kũwĩka wĩ weka.'),
('kam', 'EXO', 18, 19, 'Ĩthukĩĩsye yu wasya wakwa, nĩngũũkũtaa, nake Ngai nĩethĩwe naku: ũmaneeneae andũ aa vala ve Ngai, na kũtwaaa maũvoo moo kwa Ngai:'),
('kam', 'EXO', 18, 20, 'na ũimamanyĩasya myamũlo na mĩao, na kũmon’ya nzĩa ĩla meendelaa nayo, na wĩa ũla meĩkaa.'),
('kam', 'EXO', 18, 21, 'Na ĩngĩ ũkamanthe andũ me na ũtonyi kuma andũnĩ onthe, ala mamũkĩaa Ngai, andũ ma w’o, mamenete ũtandĩthyo ũte wa w’o; na ũkĩmaia ta asu ĩũlũ woo, methĩwe me anene ma ngili ngili, na anene ma maana, na anene ma mĩongo ĩtano mĩongo ĩtano, na anene ma makũmi:'),
('kam', 'EXO', 18, 22, 'na nĩmasilanasye andũ mavinda onthe: na kũkeethĩwa, kĩla ũndũ ũnene makũeteae, ĩndĩ kĩla ũndũ ũnini matusae e mo: na ĩndĩ ũkavũthĩw’a nĩ wĩa, na makakuanaa naku.'),
('kam', 'EXO', 18, 23, 'Ethĩwa ũkeka ũndũ ũũ, nake Ngai akakwĩaĩa o ũu, nĩvo ĩndĩ wĩtonya kwĩkala wĩ na vinya we, na andũ aa onthe namo makaendaa kwoo na mũuo.'),
('kam', 'EXO', 18, 24, 'Kwondũ wa ũu Mose eethukĩĩsya wasya wa mũthoni, na eeka onthe ala ũnaneenĩe.'),
('kam', 'EXO', 18, 25, 'Na Mose anyuva andũ me na ũtonyi kuma kwa Isilaeli onthe, na amatw’ĩkĩthya atongoi ĩũlũ wa andũ, anene ma ngili ngili, na anene ma maana, na anene ma nĩongo ĩtano mĩongo ĩtano, na anene ma makũmi.'),
('kam', 'EXO', 18, 26, 'Namo masilanasya andũ mavinda onthe: maũndũ ala maĩ vinya mamũtwaĩaa Mose, ĩndĩ kĩla ũndũ ũnini nĩmatusaa e mo.'),
('kam', 'EXO', 18, 27, 'Na Mose atianĩa ũvoo na mũthoni; nake eeyĩendea enũka kwoo.'),
('kam', 'EXO', 19, 1, 'Mweĩ wa katatũ wathela kuma ana ma Isilaeli mauma nthĩ ya Misili, mũthenya o ũsu mavika weũnĩ wa Sinai.'),
('kam', 'EXO', 19, 2, 'Na yĩla maumie Levitimu, na mavika weũnĩ wa Sinai, mamba maeema weũnĩ; na Isilaeli mamba maeema vu vakuvĩ na kĩĩma.'),
('kam', 'EXO', 19, 3, 'Na Mose ambata vala ve Ngaĩ, na Yeova amwĩta e kĩĩmanĩ, akĩmwĩa, Ũkaneene na ala ma nyũmba ya Yakovo, na kũtavya ana ma Isilaeli atĩĩ:'),
('kam', 'EXO', 19, 4, 'Nĩmwonete ũndũ neekie Amisili, na ũndũ namũkuie nthwaunĩ sya ndiũ, na kũmũete vala nĩĩ.'),
('kam', 'EXO', 19, 5, 'Na ĩndĩ yu, ethĩwa mũkew’a wasya wakwa w’o, na kũlũmya ũtianĩo wakwa, nĩvo ĩndĩ mwĩĩthĩawa makwa mwene kuma ngonĩ syonthe sya andũ: nũndũ nthĩ yonthe nĩ yakwa:'),
('kam', 'EXO', 19, 6, 'na mũkeethĩwa kwakwa ũsumbĩ wa athembĩ, na mbaĩ ntheu. Ndeto ila wĩmatavya ana ma Isilaeli nĩ isu.'),
('kam', 'EXO', 19, 7, 'Na Mose ooka, na eeta atumĩa ma andũ, na amavuanĩsya ndeto isu syonthe ila Yeova wamwĩaĩe.'),
('kam', 'EXO', 19, 8, 'Na andũ onthe masũngĩa vamwe, na masya, Onthe ala Yeova ũneenete tũkeeka. Na Mose atũngĩa Yeova ndeto syonthe sya andũ.'),
('kam', 'EXO', 19, 9, 'Na Yeova amwĩa Mose, Sisya, nĩnũkĩte kũla ũĩ nĩ ĩthweonĩ ĩkamu, nĩ kana andũ mew’e yĩla ngũneena naku, na ĩngĩ makwĩtĩkĩle tene na tene. Na Mose amũtavya Yeova ndeto sya andũ.'),
('kam', 'EXO', 19, 10, 'Na Yeova amwĩa Mose, Enda kwa andũ, ũmavathan’ye ũmũnthĩ na ũnĩ methĩwe atheu, na nĩmathambye ngũa syoo,'),
('kam', 'EXO', 19, 11, 'na meĩthĩwa meyũmbanĩtye mũthenya wa katatũ: nũndũ mũthenya wa katatũ Yeova akatheea kĩĩmanĩ kya Sinai andũ onthe mene.'),
('kam', 'EXO', 19, 12, 'Naku ũkamaiĩe andũ mĩvaka ĩthyũlũlũkĩte kw’onthe, ũkĩmea, Ĩsũvĩei ene, mũtikambate kĩĩmanĩ, o na kũkiita mũvaka wakyo: o ũla ũkakiita kĩĩma no mũvaka oawe:'),
('kam', 'EXO', 19, 13, 'mũndũ o na wĩva ndakamũkiite na kw’oko, ĩndĩ mũvaka akimangwe na mavia, kana kũathwa; ethĩwa nĩ nyamũ kana mũndũ, ndakekale thayũ: yĩla soo wĩvuvwa ĩvinda ĩasa nĩmakathengeee kĩĩma.'),
('kam', 'EXO', 19, 14, 'Na Mose auma kĩĩmanĩ atheea kũla kwĩ andũ, na avathan’ya andũ methĩwe atheu; namo mathambya ngũa syoo.'),
('kam', 'EXO', 19, 15, 'Na amea andũ, Mwĩthĩwe mwĩyũmbanĩtye mũthenya wa katatũ: mũtikathengeee mũndũ mũka.'),
('kam', 'EXO', 19, 16, 'Na kweethĩwa mũthenya wa katatũ, kwakya, kwaĩ itundumo na motisi, na ĩthweo ĩkamu kĩĩmanĩ ĩũlũ, na wasya wa soo mũnene mũno: na andũ onthe ala maĩ mwakonĩ wa maeema matetema.'),
('kam', 'EXO', 19, 17, 'Na Mose aumaalya andũ mwakonĩ wa maeema makomane na Ngai; namo maũngama ĩtheo wa kĩĩma.'),
('kam', 'EXO', 19, 18, 'Na kĩĩma kya Sinai, kyonthe, kyatoa syũki, nũndũ Yeova akĩtheea e mwakinĩ nthĩnĩ; na syũki yaw’o yambata ta syũki ya iko ĩnene, na kĩĩma kyonthe kyatetema mũno.'),
('kam', 'EXO', 19, 19, 'Na yĩla wasya wa soo wanenevangie mũno, Mose aneena, na Ngai amũsũngĩa na wasya.'),
('kam', 'EXO', 19, 20, 'Na Yeova atheea kĩĩmanĩ kya Sinai, mũtumbĩnĩ wa kĩĩma, na Yeova amwĩta Mose ambate mũtumbĩnĩ wa kĩĩma; na Mose ambata.'),
('kam', 'EXO', 19, 21, 'Na Yeova amwĩa Mose, Theea, ũmeaĩe andũ, matikeyalĩlye nzĩa ya kwa Yeova maketeee, na aingĩ moo makĩkw’a.'),
('kam', 'EXO', 19, 22, 'O na athembi namo, ala mathengeeaa Yeova, nĩmevathan’ye methĩwe atheu, Yeova ndakese kũmakitya.'),
('kam', 'EXO', 19, 23, 'Na Mose amwĩa Yeova, Ala andũ matitonya kwambata kĩĩmanĩ kya Sinai: nũndũ ũnatwĩaĩe, ũitwĩa, Ĩkĩai mĩvaka kũthyũlũlũka kĩĩma, na mũikĩvatha kĩthĩwe kĩtheu.'),
('kam', 'EXO', 19, 24, 'Na Yeova amwĩa, Enda, ũtheee; na ũkambate, we, na Aluni e naku; ĩndĩ athembi na andũ matikeyalĩlye nzĩa mambate kũla kwĩ Yeova, ndakese kũmakitya.'),
('kam', 'EXO', 19, 25, 'Kwondũ wa ũu Mose amatheeea andũ, na amatavya.'),
('kam', 'EXO', 20, 1, 'Na Ngai aneena ndeto ii syonthe, akyasya,'),
('kam', 'EXO', 20, 2, 'Nyie ninyie Yeova Ngai waku, ũla wakumisye nthĩ ya Misili, kuma nyũmbanĩ ya ũkombo.'),
('kam', 'EXO', 20, 3, 'Ndũkethĩwe na ngai ingĩ ate o nyie.'),
('kam', 'EXO', 20, 4, 'Ndũkeseũvĩsye mũvw’anano mwasũvye, o na mũvw’ano o na wĩva wa kĩndũ kĩ ĩtunĩ ĩũlũ, kana kĩla kĩ kũũ nthĩ, kana kĩla kĩ manzĩnĩ ĩtheo wa nthĩ:'),
('kam', 'EXO', 20, 5, 'ndũkamĩkunamĩe, o na ndũkamĩthũkũme; nũndũ nyie Yeova Ngai waku nĩ Ngai wĩ kĩwĩu, ngĩĩvanĩsya kwa syana ũthũku wa aaĩthe, kũvika nzyawa ya katatũ o na ya kana sya ala mamenaa,'),
('kam', 'EXO', 20, 6, 'na ngyonan’ya ũseo wĩ wendo kũvika ngili na ngili sya ala mambendaa na kũkwataa mĩao yakwa.'),
('kam', 'EXO', 20, 7, 'Ndũkawete syĩtwa ya Yeova Ngai waku mana; nũndũ Yeova ndakasya ũsu nde ĩvĩtyo ũla ũwetaa syĩtwa yake mana.'),
('kam', 'EXO', 20, 8, 'Lilĩkana mũthenya wa savato, ũwĩkalye wĩ mũtheu.'),
('kam', 'EXO', 20, 9, 'Tethya wĩa mĩthenya thanthatũ, wĩke wĩa w’onthe:'),
('kam', 'EXO', 20, 10, 'ĩndĩ mũthenya wa mũonza nĩ savato wa Yeova Ngai waku: mũthenya ũsu ndũkatethye wĩa o na wĩva, we, o na mwana waku, o na mwĩĩtu waku, o na mũthũkũmi waku mũndũ mũũme, o na mũthũkũmi waku mwĩĩtu, o na indo syaku, o na mũeni waku ũla wĩ kwaku:'),
('kam', 'EXO', 20, 11, 'nũndũ mĩthenya thanthatũ Yeova nĩwombie ĩtu na nthĩ, na ũkanga, na syonthe ila syĩ nthĩnĩ wasyo, na aithũmũa mũthenya wa mũonza: kwondũ wa ũu aathima mũthenya wa savato, na oovathan’ya wĩthĩwe mũtheu.'),
('kam', 'EXO', 20, 12, 'Taĩaa au na mwenyu, nĩ kana matukũ maku maingĩve nthĩ ĩla Yeova Ngai waku ũkũnengae.'),
('kam', 'EXO', 20, 13, 'Ndũkoae.'),
('kam', 'EXO', 20, 14, 'Ndũkalaalae.'),
('kam', 'EXO', 20, 15, 'Ndũkoye.'),
('kam', 'EXO', 20, 16, 'Ndũkamũkũsĩĩe mũtũi waku ũvũngũ.'),
('kam', 'EXO', 20, 17, 'Ndũkew’ĩe nyũmba ya mũtũi waku ĩtomo, ndũkew’ĩe mũka wa mũtũi waku ĩtomo, o na mũthũkũmi wake mũndũ mũũme, o na mũthũkũmi wake mwĩĩtu, o na ng’ombe yake, o na ĩng’oi yake, o na kĩndũ o na kĩva kya mũtũi waku.'),
('kam', 'EXO', 20, 18, 'Na andũ onthe meew’a itundumo, na moona motisi, na meew’a wasya wa soo, na moona kĩĩma kĩkĩtoa syũki: na yĩla andũ moonie ũu, matetema, na maũngama kũasa.'),
('kam', 'EXO', 20, 19, 'Na mamwĩa Mose, Neena naitũ we, na tũkeew’a; ĩndĩ Ngai ndakaneene naitũ, tũtikakw’e.'),
('kam', 'EXO', 20, 20, 'Na Mose amea andũ, Mũtikakĩe: nũndũ Ngaĩ nĩwũkĩte amũtate, na nĩ kana kũmũkĩa kwĩthĩwe kwenyu, nĩ kana mũtikavĩtye.'),
('kam', 'EXO', 20, 21, 'Na andũ maũngama kũasa, na Mose athengeea kĩvindunĩ kĩ ngokomi, vala Ngai ũĩ.'),
('kam', 'EXO', 20, 22, 'Na Yeova amwĩa Mose, Ũũ nĩw’o wĩmatavya ana ma Isilaeli, Inyw’ĩ ene nĩmwonete kana nĩneenete nenyu nĩ ĩtunĩ.'),
('kam', 'EXO', 20, 23, 'Mũtikaseũvye ngai ingĩ sya kũthaithanĩw’a nakwa; mũtikeseũvĩsye ngai sya vetha, o na ngai sya thaavu.'),
('kam', 'EXO', 20, 24, 'Mũkanzeũvĩsye kĩthembeo kya mũthanga, na kũthembea vo nthembo syaku sya kũvĩvw’a, na nthembo syaku sya mũuo, malondu maku, na ng’ombe syaku: kĩla vandũ vala nĩtuma syĩtwa yakwa yĩlilikanw’a ngooka vala ũĩ na ngakũathima.'),
('kam', 'EXO', 20, 25, 'Na ethĩwa ũkanzeũvĩsya kĩthembeo kya ĩvia, ndũkakyake na mavia masũvye; nĩkwĩthĩwa wookĩlya mũio waku wa wĩa ĩũlũ wakyo, nĩwakĩvukya.'),
('kam', 'EXO', 20, 26, 'O na ndũkambate kĩthembeonĩ kyakwa na mbasya, nĩ kana ndũkonekee vo wĩ mũthei.'),
('kam', 'EXO', 21, 1, 'Na ĩndĩ motw’ĩo ala wĩia mbee woo nĩ aa.'),
('kam', 'EXO', 21, 2, 'Ethĩwa ũkathooa ngombo, Mũevelania, ĩkũthũkũme myaka thanthatũ: na wa mũonza ĩkauma yĩ nthasye mana.'),
('kam', 'EXO', 21, 3, 'Ethĩwa nĩyookie yĩ yoka, ĩkauma yĩ yoka: ethĩwa yaĩ na mũka, nĩvo ĩndĩ mũka wayo ũkauma nayo.'),
('kam', 'EXO', 21, 4, 'Ethĩwa vwana wayo nĩwe wĩmĩnenga mũka, na akamĩsyaĩa ana kana eĩtu; ũla mũka na syana syake makeethĩwa ma vwana wake, nayo ĩkauma yĩ yoka.'),
('kam', 'EXO', 21, 5, 'Ĩndĩ ethĩwa ĩla ngombo ĩkasya vyũ, Nĩnĩmwendete vwana wakwa, na mũka wakwa, na syana syakwa; ndyĩtĩkĩla kũthaw’a:'),
('kam', 'EXO', 21, 6, 'nĩvo ĩndĩ vwana wayo wĩmĩtwaa vala ve Ngai, na akĩmĩtwaa mũomonĩ, kana mũtĩnĩ wĩ ũtee wa mũomo; na vwana wayo akamĩtonya kũtũ na mũkuva; nayo ĩkamũthũkũmaa ĩndĩ yonthe.'),
('kam', 'EXO', 21, 7, 'Na ethĩwa mũndũ akathoosya mwĩĩtu wake ethĩwe ngombo, ndĩkauma tondũ ngombo nũme syumaa.'),
('kam', 'EXO', 21, 8, 'Ethĩwa ndĩũmwendeesya vwana wayo, ũla ũmĩtwaĩte ĩtw’ĩke yake mwene, akamĩnenga ĩndĩ ũthei wa kwovow’a: ndakatonya kũmĩthooesya andũ ma nthĩ ĩngĩ, nũndũ nũmĩkengete.'),
('kam', 'EXO', 21, 9, 'Na ethĩwa akamĩnenga mwana wake, namĩke o tondũ eĩtu make mekawa.'),
('kam', 'EXO', 21, 10, 'Ethĩwa akatwaa mũka ũngĩ; lĩu wayo, na ngũa syayo, na maũndũ maĩle kwĩkwa mũtwawa, ndakamĩnyivĩsye.'),
('kam', 'EXO', 21, 11, 'Na alea kũmĩka maũndũ asu atatũ, nĩvo yĩuma mana, vate kũĩvĩwa.'),
('kam', 'EXO', 21, 12, 'Ũla wĩkũna mũndũ, na aikw’a, no mũvaka oawe.'),
('kam', 'EXO', 21, 13, 'Na ethĩwa mũndũ ndeĩmwoveesye, ĩndĩ Ngai aimũnengane kw’okonĩ kwake; nĩvo ĩndĩ nyie ngakwon’ya vandũ vala ũkakĩĩa.'),
('kam', 'EXO', 21, 14, 'Na ethĩwa mũndũ eũkĩa mũtũi wake na ngũlũ, amũae na ũĩ wa ũkengani; no mũvaka mũkamumya kĩthembeonĩ kyakwa, akw’e.'),
('kam', 'EXO', 21, 15, 'Na ũla wĩkũna ĩthe, kana nyinyia, no mũvaka oawe.'),
('kam', 'EXO', 21, 16, 'Na ũla wĩũya mũndũ, na aimũthoosya, kana ethĩwa akooneka kwake, no mũvaka oawe.'),
('kam', 'EXO', 21, 17, 'Na ũla wĩmũuma ĩthe kana nyinyia, no mũvaka oawe.'),
('kam', 'EXO', 21, 18, 'Na ethĩwa andũ makatetan’ya, na ũmwe aimũkima ũla ũngĩ na ĩvia, kana ngundĩ, nake ailea ũkw’a, ĩndĩ akĩkala ũkomonĩ wake;'),
('kam', 'EXO', 21, 19, 'ethĩwa akookĩla, na aienda nza ethukĩtye na ndata, nĩvo ĩndĩ ũla wamũkimĩte ũtakethĩwa e na ũndũ: ĩndĩ no mũvaka aĩvĩe ĩvinda yĩla wekalĩte mana, na kũmũiitĩthya avoe vyũ.'),
('kam', 'EXO', 21, 20, 'Na ethĩwa mũndũ ekũna ngombo yake ya mũndũ mũũme kana mwĩĩtu na ndata, na ĩikw’ĩa vo; no mũvaka asilĩlwe.'),
('kam', 'EXO', 21, 21, 'Ĩndĩ ethĩwa ĩkekala mũthenya ũmwe kana ĩlĩ, ndakasilĩlwa: nũndũ nĩ mali yake.'),
('kam', 'EXO', 21, 22, 'Na ethĩwa andũ makokita, na makĩw’ĩthya mũndũ mũka woo e mũito, ĩvu yake yume, ĩndĩ ate kũwaa: no mũvaka aumye nthĩnzwa, kwĩanana na ũndũ mũũme wa mũndũ mũka ũsu wĩmũtw’ĩĩa; na akĩĩva o tondũ asili metw’a.'),
('kam', 'EXO', 21, 23, 'Ĩndĩ ethĩwa ũthũku o na wĩva ũkooneka, nĩvo ĩndĩ wĩumya thayũ vandũ va thayũ,'),
('kam', 'EXO', 21, 24, 'itho vandũ va itho, ĩeo vandũ va ĩeo, kw’oko vandũ va kw’oko, kũũ vandũ va kũũ,'),
('kam', 'EXO', 21, 25, 'ĩvya vandũ va ĩvya, wũkite vandũ va wũkite, ĩkũna vandũ va ĩkũna.'),
('kam', 'EXO', 21, 26, 'Na ethĩwa mũndũ ekũna ngombo yake ya mũndũ mũũme itho, kana ngombo yake ya mwĩĩtu itho, na akĩyĩvũthũa; akamĩthasya kwondũ wa itho yayo.'),
('kam', 'EXO', 21, 27, 'Na ethĩwa akakũna ĩeo ya ngombo yake ya mũndũ mũũme yĩkũke, o na ĩeo ya ngombo yake ya mwĩĩtu; akamĩthasya kwondũ wa ĩeo yayo.'),
('kam', 'EXO', 21, 28, 'Na ethĩwa ng’ombe yĩmũkima mũndũ mũũme kana mũndũ mũka na mbya, akw’e, ng’ombe ĩsũ no mũvaka yũawe na mavia, na nyama syayo itikaĩwe; ĩndĩ mwene wa ng’ombe ĩsu ndakatw’ĩĩwa e na ĩvĩtyo.'),
('kam', 'EXO', 21, 29, 'Ĩndĩ ethĩwa ĩla ng’ombe nĩkimanaa na mbya kuma tene, na mwene wayo nĩwataviw’e, nake ndaamĩsiĩĩa, ĩndĩ nĩyũaĩte mũndũ mũũme kana mũndũ mũka; ng’ombe ĩsu ĩkooawa na mavia, na mwene wayo nake akooawa.'),
('kam', 'EXO', 21, 30, 'Ethĩwa akatw’ĩĩwa mbovosya, nĩvo ĩndĩ wĩumya kwondũ wa wovosyo wa thayũ wake ũndũ wĩtw’ĩĩwa.'),
('kam', 'EXO', 21, 31, 'Ethĩwa nĩkimĩte mwana, kana nĩkimĩte mwĩĩtu, akeekwa kwĩanana na ũtw’ĩo ũsu.'),
('kam', 'EXO', 21, 32, 'Ethĩwa ng’ombe ĩkakima ngombo mũndũ mũũme kana ngombo mwĩĩtu, vwana wayo akanengwa sekeli mĩongo ĩtatũ sya vetha, na ĩla ng’ombe ĩkooawa na mavia.'),
('kam', 'EXO', 21, 33, 'Na ethĩwa mũndũ akakũnũa ĩima, kana ethĩwa mũndũ akenza ĩima na ailea kũyĩkũnĩka, na ng’ombe kana ĩng’oi ĩkĩvalũka nthĩnĩ wayo,'),
('kam', 'EXO', 21, 34, 'mwene wa ĩima akaĩva; akanenga mwene wayo mbesa, na ĩla ngw’ũ ĩkeethĩwa yake.'),
('kam', 'EXO', 21, 35, 'Na ethĩwa ng’ombe ya mũndũ ũmwe ĩkatũla ya ũngĩ ũndũ ĩkw’a, nĩvo ĩndĩ methoosya ng’ombe ĩla ĩ thayũ, na makiaana thooa wayo; na ĩla ngw’ũ nayo makyatũana.'),
('kam', 'EXO', 21, 36, 'Kana ethĩwa nĩkũmanyĩka atĩ ĩla ng’ombe nĩyakimanaa na mbya kuma tene, na mwene wayo ndaamĩvingĩa; no mũvaka aĩve ng’ombe vandũ va ng’ombe, na ĩla ngw’ũ ĩkĩthĩwa yake.'),
('kam', 'EXO', 22, 1, 'Ethĩwa mũndũ akoya ng’ombe, kana ĩlondu, na aiyũaa, kana aithoosya; akaĩvĩa ng’ombe ĩmwe itano, na ĩlondu yĩmwe malondu ana.'),
('kam', 'EXO', 22, 2, 'Ethĩwa kĩng’ei kyu kĩkooneka kĩivũthũa, na kĩikũnwa ũndũ kĩkw’a, kũikethĩwa kũĩvanĩsya nthakame kwondũ wakyo.'),
('kam', 'EXO', 22, 3, 'Ethĩwa nĩkyakeewa ũndũnĩ ũsu, kũkeethĩwa kũĩvanĩsya nthakame kwondũ wakyo; kĩkaĩva: ethĩwa kĩti na kĩndũ, nĩvo ĩndĩ kĩtewa kwondũ wa ũng’ei wakyo.'),
('kam', 'EXO', 22, 4, 'Ethĩwa kĩla kyoyiwe kĩkooneka kĩ thayũ kw’okonĩ kwakyo, ethĩwa nĩ ng’ombe, kana ĩng’oi, kana ĩlondu; kĩkaĩvĩa kũndũ kwĩlĩ.'),
('kam', 'EXO', 22, 5, 'Ethĩwa mũndũ akaĩthya mũũnda kana mũũnda wa mĩsavivũ wa mũndũ ũngĩ, na akathasya ng’ombe yake, nayo ĩithi kũya mũũndanĩ wa mũndũ ũngĩ; akaĩvĩa ila nzeo mbee sya mũũnda wake mwene, na ila nzeo mbee sya mũũnda wake wa mĩsavivũ.'),
('kam', 'EXO', 22, 6, 'Ethĩwa mwaki ũkakana, noikwata mĩw’anĩ, ũndũ syove sya nganũ, o na lĩu ũtũĩtye, o na mũũnda, iivya; ũsu wakwatĩsye mwaki no mũvaka aĩve.'),
('kam', 'EXO', 22, 7, 'Ethĩwa mũndũ akanenga mũtũi wake mbesa kana mĩio ĩngĩ asũvĩe, na ĩkyũyĩwa nyũmbanĩ ya mũndũ ũsu; kĩng’ei kyooneka, kĩkaĩvĩa kũndũ kwĩlĩ.'),
('kam', 'EXO', 22, 8, 'Kĩng’ei kyalea kwoneka, nĩvo ĩndĩ mwene wa nyũmba wĩthengeea vala ve Ngai, nĩ kana kũmanyĩke ethĩwa nokwĩthĩwa oyĩte mĩio ya mũtũi wake.'),
('kam', 'EXO', 22, 9, 'Kwondũ wa kĩla ũndũ wa kũvĩtya, ethĩwa nĩ ũndũ wa ng’ombe, kana ĩng’oi, kana ĩlondu, kana ngũa, o na mũthemba o na wĩva wa kĩndũ kĩla kyaĩte, na mũndũ akyasya ũndũ wakyo, Nĩkyo kĩĩ, ũvoo wa andũ asu me elĩ wĩetwe vala ve Ngai; o ũla Ngai wĩmũtw’a mũvĩtan’ya akaĩvĩa mũtũi wake kũndũ kwĩlĩ.'),
('kam', 'EXO', 22, 10, 'Ethĩwa mũndũ akamũvithya mũtũi wake ĩng’oi, kana ng’ombe, kana ĩlondu, kana nyamũ o na yĩva, asũvĩe; na ĩikw’a, kana kwĩkwa ũndũ ũthũku, kana kũtwawa, mũndũ o na wĩva atene:'),
('kam', 'EXO', 22, 11, 'makeeavĩa vala ve Yeova me elĩ, ethĩwa nokwĩthĩwa ndaatambũũkya kw’oko kwake amũvute mũtũi wake syĩndũ syake; na mwene wasyo akawĩtĩkĩla, nake ndakaĩva.'),
('kam', 'EXO', 22, 12, 'Ĩndĩ ethĩwa ĩkoyĩwa kwake, akaĩvĩa mwene wayo.'),
('kam', 'EXO', 22, 13, 'Ethĩwa ĩkalĩka ĩkĩtilangwa ilungu, namĩete ĩthĩwe ũkũsĩ; na ndakaĩva ũndũ wa ĩla ĩlĩkĩte.'),
('kam', 'EXO', 22, 14, 'Na ethĩwa mũndũ akavoya nyamũ kwa mũtũi wake, na ĩkĩkwa ũndũ ũthũku, kana kũkw’a, mwene wayo ate nayo, no mũvaka aĩve.'),
('kam', 'EXO', 22, 15, 'Ethĩwa mwene wayo e nayo ndakamĩĩvĩa: ethĩwa nĩ ngomboe, nikomboetwe yonee mwene wayo mbesa.'),
('kam', 'EXO', 22, 16, 'Na ethĩwa mũndũ akakuua mwĩĩtu ũte mwĩvasye, na aikoma nake, no mũvaka aumye indo amũthooe atw’ĩke mũka wake.'),
('kam', 'EXO', 22, 17, 'Ethĩwa ĩthe wake akalea vyũ kũmũnengane kwake, akaĩva mbesa kwĩanana na ũndũ eĩtu maasaw’a.'),
('kam', 'EXO', 22, 18, 'Ndũkaeke mũndũ mũka mũoi ekale thayũ.'),
('kam', 'EXO', 22, 19, 'O ũla ũkakoma na nyamũ no mũvaka oawe.'),
('kam', 'EXO', 22, 20, 'Ũla ũkathembea ngai ĩngĩ o na yĩva nthembo ate o Yeova e weka, no mũvaka anangwe vyũ.'),
('kam', 'EXO', 22, 21, 'Na ndũkamwĩke mwĩkali wa ũeninĩ naĩ, o na ndũkamũthĩn’ye: nĩkwĩthĩwa mwaĩ ekali ma ũeninĩ nthĩ ya Misili.'),
('kam', 'EXO', 22, 22, 'Mũtikathĩn’ye mũndũ mũka ndiwa o na wĩva, o na kana kakw’ĩĩwe nĩ ĩthe.'),
('kam', 'EXO', 22, 23, 'Ethĩwa ũkamathĩn’ya na ũndũ o na wĩva, na makeengaĩla o na ata, nditĩa kwĩw’a kũkaya kwoo;'),
('kam', 'EXO', 22, 24, 'na ũthilĩku wakwa ũkavyũva, na ngamũaa na ũvyũ; na iveti syenyu ikeethĩwa ndiwa, na syana syenyu ikakw’ĩĩwa nĩ aaĩthe.'),
('kam', 'EXO', 22, 25, 'Ethĩwa ũkakovethya mbesa ũmwe wa andũ makwa ala ngya o na mekũ ala matwĩe naku, ndũkatinde ũkĩmũandũa; o na ndũkamwĩtye ũtandĩthyo wasyo.'),
('kam', 'EXO', 22, 26, 'Ethĩwa ũkathi na ngũa o na yĩva ya mũtũi waku ĩtw’ike ngwatĩlĩlyo, ũkamũtũngĩa syũa yĩtanathũa:'),
('kam', 'EXO', 22, 27, 'nũndũ nĩyo wĩ nayo yoka ya kwĩvw’ĩka, nĩ ngũa yake ya kũvw’ika mwĩĩ wake: akakoma na kĩ? Na kũkeethĩwa, eĩngaĩla, ngeew’a; nũndũ nyie nĩ mũseo.'),
('kam', 'EXO', 22, 28, 'Ndũkamũume Ngai, o na kũuma mũnene wa andũ maku.'),
('kam', 'EXO', 22, 29, 'Ndũkekale mũno ũtekumya kĩlungu kya ngetha yaku, o na kya wingĩ wa syĩndũ syaku sya kũnyw’a. Ĩkithathi ananĩ maku aũme ũkanengae.'),
('kam', 'EXO', 22, 30, 'Na mwĩĩka o ta ũu na ng’ombe syaku, na malondu maku: ĩkekale na nyinyia matukũ mũonza; mũthenya wa nyanya ũkanengae.'),
('kam', 'EXO', 22, 31, 'Na mũkeethĩwa andũ atheu kwakwa: kwondũ wa ũu mũtikaye nyama ya ĩla ĩlĩkĩle kĩthekanĩ nĩ nyamũ; mũkamĩkĩsya ngitĩ.'),
('kam', 'EXO', 23, 1, 'Ndũkatwae ũvoo wa ũvũngũ: ndũkakwatane kw’oko kwaku na ala athũku ũtw’ĩke ngũsĩ ĩte ya ũlũngalu.'),
('kam', 'EXO', 23, 2, 'Ndũkaatĩanĩe na wingĩ wa andũ wĩke naĩ; o na ndũkaneene ũkũsĩ ũndũnĩ ũalyũle kũatĩĩa wingĩ wa andũ nĩ kana welelũkye sila wa katĩ:'),
('kam', 'EXO', 23, 3, 'o na ndũkendeesye mũndũ ngya ũndũnĩ wake.'),
('kam', 'EXO', 23, 4, 'Ethĩwa ũkakomana na ng’ombe ya ũla wĩ ũthũ naku, kana ĩng’oi yake yaĩte, ndũkatĩe kũmũtũngĩa yo kwake ĩngĩ.'),
('kam', 'EXO', 23, 5, 'Ethĩwa ũkoona ĩng’oi ya ũla ũkũmenete yĩvalũkĩte na mũio wayo, ndũkamũtiĩe, no mũvaka ũmũtethye.'),
('kam', 'EXO', 23, 6, 'Ndũkalelũkye sila wa katĩ kwa ũla ngya waku ũndũnĩ wake.'),
('kam', 'EXO', 23, 7, 'Ĩyĩkalye kũasa na ũndũ wĩ ũvũngũ; na ndũkoae ũla ũte na ĩvĩtyo wĩkĩte, o na ũla mũlũngalu: nũndũ ndikatala mwĩki wa naĩ mũlũngalu.'),
('kam', 'EXO', 23, 8, 'Na ndũkose ĩvaki o na ata: nũndũ ĩvaki nĩyĩlindaa metho ma asu mekwona, na kwelelũkya ndeto sya ũla mũlũngalu.'),
('kam', 'EXO', 23, 9, 'Na ndũkathĩn’ye mwĩkali wa ũeninĩ: nũndũ nĩmwĩsĩ ngoo ya mwĩkali wa ũeninĩ, nĩkwĩthĩwa mwaĩ ekali ma ũeninĩ nthĩ ya Misili.'),
('kam', 'EXO', 23, 10, 'Na myaka thanthatũ ũkavande nthĩ yaku, na ũiketha ũsyao wayo:'),
('kam', 'EXO', 23, 11, 'ĩndĩ mwaka wa mũonza mĩtie ĩthũmũe na kwĩkala yĩ maei, nĩ kana ala ngya ma andũ maku mone kya ũya: na kĩla meũtialya nyamũ ya kĩtheka ĩkaya. Ũkeke o ta ũu na mũũnda waku wa mĩsavivũ, o na mũũnda waku wa mĩthata.'),
('kam', 'EXO', 23, 12, 'Ũkatethye wĩa waku mĩthenya thanthatũ, na mũthenya wa mũonza ũkathũmũe; nĩ kana ng’ombe yaku na ĩng’oi yaku syone ũthũmũo, na mwana wa ngombo yaku mwĩĩtu, na mwĩkali wa ũeninĩ, manooke.'),
('kam', 'EXO', 23, 13, 'Na maũndũ onthe ala nĩmwĩĩte masisyei: na mũtikawete syĩtwa ya ngai ingĩ, o na yĩtikew’ĩke yĩkyuma kanyw’anĩ waku.'),
('kam', 'EXO', 23, 14, 'Mavinda atatũ mwaka ũkeethĩwa na mboka kwondũ wakwa.'),
('kam', 'EXO', 23, 15, 'Lilikana mboka ya kĩmũtũ kĩte ĩlawa: ũkaye kĩmũtũ kĩte ĩlawa mĩthenya mũonza, o tondũ nĩkwĩaĩĩte, ĩvinda yĩtw’ĩtwe mwei wa Avivu (nũndũ mwei ũsu nĩwaumie Misili); na ndakoneke o na ũmwe wĩũka mbee wakwa e na moko mathei:'),
('kam', 'EXO', 23, 16, 'na mboka ya ngetha, ũsyao wa mbee wa kũthĩnĩa wĩa kwaku, ũla ũvandĩte mũũndanĩ: na mboka ya kũmina ngetha, mwaka wathela, o yĩla wĩketha ũsyao wa wĩa waku w’onthe ũ wĩ mũũndanĩ.'),
('kam', 'EXO', 23, 17, 'Mavinda atatũ mwaka aũme maku onthe makaumĩla mbee wa Mwĩaĩi Yeova.'),
('kam', 'EXO', 23, 18, 'Ndũkathembanĩsye nthakame ya nthembo yakwa na kĩmũtũ kĩ ĩlawa; o na mathunya ma mboka yakwa matikekale ũtukũ w’onthe kũvika kĩoko.'),
('kam', 'EXO', 23, 19, 'Ũsyao wa mbee ki wa ũsyao wa nthĩ yaku ũkaete nyũmbanĩ ya Yeova Ngai waku. Ndũkaue katena ka mbũi na ĩia ya nyinyia wako.'),
('kam', 'EXO', 23, 20, 'Sisya, nĩngũtũma mũlaĩka akũtongoesye, akũsũvĩe nzĩanĩ na ũkũete vandũ vala nĩseũvĩtye.'),
('kam', 'EXO', 23, 21, 'Ĩsũvĩei vala ũĩ, na mũkĩthukĩĩsya wasya wake; mũtikamũthatye; nĩkwĩthĩwa ndakamũekea kũvĩtya kwenyu: nũndũ syĩtwa yakwa yĩ nthĩnĩ wake.'),
('kam', 'EXO', 23, 22, 'Ĩndĩ ethĩwa ũkethukĩĩasya wasya wake w’o, na kwĩkaa onthe ala ngũneena; nĩvo ĩndĩ nĩĩthĩawa nĩ mũmaitha kwa amaitha maku, na nthũ kwa nthũ syaku.'),
('kam', 'EXO', 23, 23, 'Nũndũ mũlaĩka wakwa akamũtongoeasya, na ũkũete kwa Mũamoli, na Mũititi, na Mũvelisi, na Mũkanaani, na Mũivi, na Mũyevusĩ: na ngamamina vyũ.'),
('kam', 'EXO', 23, 24, 'Ndũkakunamĩe ngai syoo, o na kwithũkũma, o na kwĩka kũatĩĩa meko masyo: ĩndĩ ũkaing’uthũlange vyũ, na kũtũlanga ituĩ syasyo ilungu.'),
('kam', 'EXO', 23, 25, 'Nenyu mũkathũkũmae Yeova Ngai wenyu, nake akaathimaa lĩu waku, na manzĩ maku; nakwa ngaveta ũwau kuma katĩ waku.'),
('kam', 'EXO', 23, 26, 'Kũti ũkaumya ĩvu, kana kwĩthĩwa ngũngũ, nthĩ yaku: ngeanĩsya ũtalo wa matukũ maku.'),
('kam', 'EXO', 23, 27, 'Ngatũma ũtĩsyo wakwa ũtongoasye mbee waku, na ngaananga andũ onthe kũla ũkavika, na ngatuma amaitha maku onthe makwon’ya mĩongo.'),
('kam', 'EXO', 23, 28, 'Na ngatũma mauĩ mbee waku, ala makalũngya Mũivi, na Mũkanaani, na Mũititi maume mbee waku.'),
('kam', 'EXO', 23, 29, 'Ndikamalũngya maume mbee waku nthĩnĩ wa mwaka ũmwe, nthĩ ndĩkatw’ĩke nthei, na nyamũ sya kĩtheka ikingĩva imũthĩn’ye.'),
('kam', 'EXO', 23, 30, 'Ngamalũngya maume mbee waku kavola na kavola, mũvaka yĩla mũkaingĩva, na kwosa nthĩ ĩsu yĩthĩwe yenyu.'),
('kam', 'EXO', 23, 31, 'Nakwa ngaatũa mũvaka waku kuma Ũkanganĩ Mũtune kũvika ũkanga wa Avilisiti, na kuma weũ kũvika ũla Ũsĩ: nũndũ nganengane ala matwĩe nthĩ ĩsu kw’okonĩ kwaku; na ũkamalũngya maume mbee waku.'),
('kam', 'EXO', 23, 32, 'Ndũkatianĩe ũtianĩo namo, kana na ngai syoo.'),
('kam', 'EXO', 23, 33, 'Matikatũe nthĩ yaku, matikese kũtuma mũmbĩtanĩsya; nũndũ ethĩwa ũkaithũkũma ngai syoo, ũndũ ũsu ndũkatĩa kwĩthĩwa kĩtei kwaku.'),
('kam', 'EXO', 24, 1, 'Na amwĩa Mose, Ambata wũke kũla kwĩ Yeova, we, na Alunĩ, na Natavu, na Aviu, na atumĩa mĩongo mũonza ma Isilaeli; na mũkĩthaitha mwĩ kũasa:'),
('kam', 'EXO', 24, 2, 'na Mose e weka akamũthengeea Yeova; ĩndĩ mo matikathengeee; o na andũ matikambate nake.'),
('kam', 'EXO', 24, 3, 'Na Mose athi na atavya andũ ndeto syonthe sya Yeova, na motw’ĩo onthe: na andũ onthe masũngĩa na wasya ũmwe, na masya, Ndeto syonthe ila Yeova ũneenete tũkeeka.'),
('kam', 'EXO', 24, 4, 'Na Mose aandĩka ndeto syonthe sya Yeova, na ookĩla kĩoko tene, na aaka kĩthembeo, na ituĩ ĩkĩĩmi na ilĩ ĩtina wa kĩĩma, kwĩanana na mbaĩ ĩkũmi na ili sya Isilaeli.'),
('kam', 'EXO', 24, 5, 'Na atũma anake ma ana ma Isilaeli, ala mathembie nthembo sya kũvĩvw’a, na kũthembea Yeova nthembo sya mũuo sya ng’ombe.'),
('kam', 'EXO', 24, 6, 'Na Mose oosa nyunzu ya ĩla nthakame, na amĩkĩa masaaninĩ manene; na nyunzu ya nthakame aminzangĩsya kĩthembeonĩ.'),
('kam', 'EXO', 24, 7, 'Na oosa ĩvuku ya ũtianĩo, na asoma andũ makĩw’a: namo masya, Tũkekaa onthe ala Yeova ũneenete, na kwĩkalaa twĩ ewi.'),
('kam', 'EXO', 24, 8, 'Na Mose oosa ĩla nthakame, na aminzangĩsya andũ, na amea, Sisyai nthakame ya ũtianĩo, ũla Yeova ũtianĩĩte nenyu ũndũ wa ndeto ii syonthe.'),
('kam', 'EXO', 24, 9, 'Nĩvo ĩndĩ Mose, na Aluni, na Natavu, na Aviu, na atumĩa mĩongo mũonza ma Isilaeli mambatie:'),
('kam', 'EXO', 24, 10, 'na moona Ngai wa Isilaeli; na kwaĩ ta vandũ vaseũvĩtw’e na tũvila twa savili, na ta ĩtu yo yene ũndũ wa kũthea, vala wakinyĩle.'),
('kam', 'EXO', 24, 11, 'Na ndaailĩĩla kw’oko kwake anene me ndaĩa ma ana ma Isilaeli: namo mamwona Ngai, na maya na manyw’a.'),
('kam', 'EXO', 24, 12, 'Na Yeova amwĩa Mose, Ambata vala nĩĩ kĩĩmanĩ, na wĩthĩwe vo: na ngakũnenga masengea ma mavia, na ĩla mĩao na motw’ĩo, ala nĩandĩkĩte, nĩ kana ũtonye kũmamanyĩsya.'),
('kam', 'EXO', 24, 13, 'Na Mose ookĩla, na Yosua mũthũkũmi wake: na Mose ambata kĩĩmanĩ kya Ngai.'),
('kam', 'EXO', 24, 14, 'Na amea ala atumĩa, Tweteelei vaa, kũvika twaalũka vala mũĩ ĩngĩ: na, sisyai, Aluni na Uulu me vamwe nenyu: o ũla wĩ na ũndũ, nathi vala maĩ.'),
('kam', 'EXO', 24, 15, 'Na Mose ambata kĩĩmanĩ, na ũla mũumbĩ wavw’ĩka kĩĩma.'),
('kam', 'EXO', 24, 16, 'Na ũtheu mũtisu wa Yeova wekala kĩĩmanĩ kya Sinai ĩũlũ, na ũla mũumbĩ wakĩvw’ĩka mĩthenya thanthatũ: na mũthenya wa mũonza amwĩta Mose e mũumbĩnĩ katĩ.'),
('kam', 'EXO', 24, 17, 'Na kwoneka kwa ũtheu mũtisu wa Yeova mũtumbĩnĩ wa kĩĩma, ana ma Isilaeli moona ta mwaki ũla ũvĩvasya.'),
('kam', 'EXO', 24, 18, 'Na Mose avota mũumbĩnĩ katĩ, na ambata kĩĩmanĩ: na Mose ekala kĩĩmanĩ mĩthenya mĩongo ĩna na matukũ mĩongo ĩna.'),
('kam', 'EXO', 25, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 25, 2, 'Matavye ana ma Isilaeli mambũmbanĩsye nthembo: mũkose nthembo yakwa kwa kĩla mũndũ ũla wĩ na ngoo ya kwenda.'),
('kam', 'EXO', 25, 3, 'Na nthembo ĩla mwĩosa kũla maĩ nĩ ĩno: thaavu, na vetha, na ũthuku,'),
('kam', 'EXO', 25, 4, 'na langi wa vuluu, na ũla ũtilyĩ ta mũtune, na ũla mũtune mũno, na katane nzeo, na maw’ĩa ma mbũi,'),
('kam', 'EXO', 25, 5, 'na mbũa sya ndũũme syĩkĩĩtwe langĩ mũtune, na mbũa sya vomboo, na mĩtĩ ya mũea,'),
('kam', 'EXO', 25, 6, 'na mauta ma kwakan’ya taa, na mĩtĩ ĩla ĩnyungaa nesa kwondũ wa mauta ma kwĩtĩkĩsya, na ma kũtoeesya ũvani ũla ũnyungaa nesa,'),
('kam', 'EXO', 25, 7, 'na tũvila twa nzumalati, na tũvila twa kũlũmanĩthw’a iĩndĩnĩ syatw’o, ngũanĩ yĩtawa evoti, na kakalonĩ ka kĩthũi.'),
('kam', 'EXO', 25, 8, 'Na nĩmanzeũvĩsye vandũ vatheu, nĩkalae katĩ woo.'),
('kam', 'EXO', 25, 9, 'Kwĩanana na onthe ala nĩkwon’ya, ngelekan’yo ya wĩkalo, na ngelekan’yo ya mĩio yonthe yaw’o, mũkavaseũvye o ta ũu.'),
('kam', 'EXO', 25, 10, 'Na makaseũvye ĩsandũkũ ya mĩtĩ ya mũea: ũasa wayo ũkeethĩwa mĩkono ĩlĩ na nyunzu, na ũthanthau wayo mũkono na nyunzu, na ũtũlu wayo mũkono na nyunzu.'),
('kam', 'EXO', 25, 11, 'Na ũkayĩvw’ĩke thaavu mũtheu, nthĩnĩ na ũtee ũkayĩvw’ĩke, na kũseũvya ĩũlũ wayo ũengo mũtũlu wa thaavu ũyĩlingĩle.'),
('kam', 'EXO', 25, 12, 'Na ũkayĩtũĩĩe ngome inya sya thaavu, na ũkĩsyĩkĩa maũũnĩ ana mayo; na ngome ilĩ ikethĩwe ngalĩ ĩmwe yayo, na ngome ilĩ ngalĩ ĩla ĩngĩ yayo.'),
('kam', 'EXO', 25, 13, 'Na ũkaseũvye mĩtĩ ya mũea, na ũkĩmĩvw’ĩka thaavu.'),
('kam', 'EXO', 25, 14, 'Na ũkĩkĩa ĩla mĩtĩ ngomenĩ ila syĩ mavavanĩ ma yĩla ĩsandũkũ, ya ũkua ĩsandũkũ nayo.'),
('kam', 'EXO', 25, 15, 'Ĩla mĩtĩ ĩkeethĩwa ngomenĩ sya ĩsandũkũ: ndĩkaumw’e vo.'),
('kam', 'EXO', 25, 16, 'Na ũkekĩe nthĩnĩ wa ĩsandũkũ ũkũsĩ ũla nĩkũnenga.'),
('kam', 'EXO', 25, 17, 'Na ũkaseũvye wĩkalo wa tei wa thaavu mũtheu: ũasa waw’o ũkeethĩwa mĩkono ĩlĩ na nyunzu, na ũtanthau waw’o mũkono na nyunzu.'),
('kam', 'EXO', 25, 18, 'Na ũkaseũvye akeluvi elĩ ma thaavu; ũkamaseũvye na kũmatua, ngalĩ syelĩ sya ũla wĩkalo wa tei.'),
('kam', 'EXO', 25, 19, 'Noiseũvya mũkeluvi ũmwe ngalĩ ĩmwe, na mũkeluvi ũngĩ ngalĩ ĩla ĩngĩ: ũkatuanĩsye ala akeluvi kĩlungunĩ kĩmwe na ũla wĩkalo wa tei ngalĩ syelĩ syaw’o.'),
('kam', 'EXO', 25, 20, 'Na akeluvi makatambũũkye nthwau syoo ĩũlũ, makĩvw’ika wĩkalo wa tei na nthwau syoo, mothyũ moo masianĩtye; mothyũ ma akeluvi makelekele wĩkalo wa tei.'),
('kam', 'EXO', 25, 21, 'Na ũkaie ũ wĩkalo wa tei ĩsandũkũnĩ ĩũlũ; na nthĩnĩ wa ĩsandũkũ ũkĩkĩa ũkũsĩ ũla nĩũnenga.'),
('kam', 'EXO', 25, 22, 'Na nĩvo nĩkomanĩaa naku, na nganeenanasya naku nĩ wĩkalonĩ wa tei ĩũlũ, o katĩ wa akeluvi elĩ ala me ĩũlũ wa ĩsandũkũ ya ũkũsĩ, ũndũ wa maũndũ onthe ala ngakwĩaĩaa kwondũ wa ana ma Isilaeli.'),
('kam', 'EXO', 25, 23, 'Na ũkaseũvye mesa ya mĩtĩ ya mũea: ũasa wayo ũkeethĩwa mĩkono ĩlĩ, na ũthanthau wayo mũkono, na ũtũlu wayo mũkono na nyunzu.'),
('kam', 'EXO', 25, 24, 'Na ũkamĩvw’ĩke thaavu mũtheu, noimĩseũvĩsya ũengo mũtũlu wa thaavu ũmĩlingĩle.'),
('kam', 'EXO', 25, 25, 'Na ũkamĩseũvĩsye ũengo ũmĩlingĩle, ũthanthau waw’o nĩ ta wa kĩtaa kya kw’oko; na ũkaseũvye ũengo mũtũlu wa thaavu ũengonĩ wayo ũmĩlingĩle.'),
('kam', 'EXO', 25, 26, 'Na ũkamĩseũvĩsye ngome inya sya thaavu, na ũkĩkĩa ngome mĩthyanĩ ĩna ya ĩũlũ ĩla yĩ maũũnĩ ana mayo.'),
('kam', 'EXO', 25, 27, 'Ngome ikethĩwe vakuvĩ na ũengo, syĩthĩwe kũndũ kwa kwĩkĩa mĩtĩ ya kũkua mesa.'),
('kam', 'EXO', 25, 28, 'Na ũkaseũvye ĩla mĩtĩ ya mũea, noimĩvw’ĩka thaavu, nĩ kana mesa ĩkuwe nayo.'),
('kam', 'EXO', 25, 29, 'Na ũkaseũvye masaani mayo, na syĩko syayo, na ikombe syayo, na mbakũli syayo, ila sya kwĩtĩkĩasya: ũkaiseũvye na thaavu mũtheu.'),
('kam', 'EXO', 25, 30, 'Na ũkaie mesanĩ imũtũ sya kwiawa mbee wakwa matukũ onthe.'),
('kam', 'EXO', 25, 31, 'Na ũkaseũvye kĩndũ kĩla kĩkĩawa mataa kya thaavu mũtheu: kĩla kĩndũ kĩkĩawa mataa kĩkaseũvw’e na kũtua, o ĩtina yakyo, na mũtĩ wakyo; ikombe syakyo, na mĩkauti yakyo, na malaa makyo, ikethĩwe sya kĩlungu kĩmwe nakyo:'),
('kam', 'EXO', 25, 32, 'na vakethĩwe mbonge thanthatũ ikyuma ndee syakyo; mbonge itatũ sya kĩla kĩndũ kĩkĩawa mataa kuma ngalĩ ĩmwe yakyo, na mbonge itatũ sya kĩla kĩndũ kĩkĩawa mataa kuma ngalĩ ĩla ĩngĩ yakyo:'),
('kam', 'EXO', 25, 33, 'ikombe itatũ iseũvĩtw’e ta malaa ma mũlosi ũvongenĩ ũmwe, mũkauti na ĩlaa; na ikombe itatũ iseũvitw’e ta malaa ma mũlosi ũvongenĩ ũla ũngĩ, mũkauti na ĩlaa: o ta ũu kwa ila mbonge thanthatũ ikyuma kĩla kĩndũnĩ kĩkĩawa mataa:'),
('kam', 'EXO', 25, 34, 'na nthĩnĩ wa kĩla kĩndũ kĩkĩawa mataa ikombe inya iseũvĩtw’e ta malaa ma mũlosi, mĩkauti yakyo, na malaa makyo;'),
('kam', 'EXO', 25, 35, 'na mũkauti ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, na mũkauti ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, na mũkauti ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, kwa ila mbonge thanthatũ ikyuma kĩla kĩndũnĩ kĩkĩawa mataa.'),
('kam', 'EXO', 25, 36, 'Mĩkauti yakyo na mbonge syakyo ikethĩwe sya kĩlungu kĩmwe nakyo: kĩndũ kyu kĩima kya thaavu mũtheu ũla mũtue.'),
('kam', 'EXO', 25, 37, 'Na ũkaseũvye mataa makyo, mũonza: na makakwatasye mataa makyo, maumasye kyeni vu kĩĩ.'),
('kam', 'EXO', 25, 38, 'Na mĩkasi yakyo, na masaani ma makaa makyo, ikethĩwe sya thaavu mũtheu.'),
('kam', 'EXO', 25, 39, 'Kĩkaseũvw’e kya talendi ya thaavu mũtheu, vamwe na mĩio ĩsu yonthe.'),
('kam', 'EXO', 25, 40, 'Na sisya kana ũkaitue kwĩanana na ngelekan’yo yayo, ĩla woonew’e kĩĩmanĩ.'),
('kam', 'EXO', 26, 1, 'Na ĩngĩ, ũkaseũvye ũla wĩkalo wĩthĩwe na masuka ĩkũmi; ũkamatume ma ndii sya katane nzeo mbokothe, na sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, ũkamatumĩĩe ngelekan’yo ya akeluvi, o wĩa wa mũtethya wa wĩa ũla mũĩ.'),
('kam', 'EXO', 26, 2, 'Ũasa wa kĩla suka ũkeethĩwa mĩkono mĩongo ĩlĩ na nyanya, na ũthanthau wa kĩla suka mĩkono ĩna: masuka onthe makathimwe ũndũ ũmwe.'),
('kam', 'EXO', 26, 3, 'Masuka atano nĩmakakwatanwe, ũmwe na ũla ũngĩ; na masuka atano ala angĩ nĩmakakwatanwe, ũmwe na ũla ũngĩ.'),
('kam', 'EXO', 26, 4, 'Na ũkaseũvye ikwatũ sya vuluu ũteenĩ wa suka ũmwe ũtiivonĩ vala makwatanĩlwe; na ũkeke o ta ũu ũteenĩ wa suka ũla wĩ mũminũkĩlyo wa vala vakwatanĩlwe va kelĩ.'),
('kam', 'EXO', 26, 5, 'Ikwatũ mĩongo ĩtano ũkaseũvye sukanĩ ũla ũmwe, na ikwatũ mĩongo ĩtano ũkaseũvye ũteenĩ wa suka ũla wĩ vala vakwatanĩlwe va kelĩ; kĩla kĩkwatũ kĩmwe kyelekele kĩla kĩngĩ.'),
('kam', 'EXO', 26, 6, 'Na ũkaseũvye tũvoloi mĩongo ĩtano twa thaavu, noikwatan’ya masuka ũmwe na ũla ũngĩ na tũvoloi tũu: na wĩkalo ũkatw’ĩka ũmwe.'),
('kam', 'EXO', 26, 7, 'Na ũkatume masuka ma maw’ĩa ma mbũi matw’ĩke ĩeema ĩũlũ wa wĩkalo ũsu: ũkamatume masuka ĩkũmi na ũmwe.'),
('kam', 'EXO', 26, 8, 'Ũasa wa kĩla suka ũkeethĩwa mĩkono mĩongo ĩtatũ, na ũthanthau wa kĩla suka mĩkono ĩna: masuka asu ĩkũmi na ũmwe makathimwe ũndũ ũmwe.'),
('kam', 'EXO', 26, 9, 'Na ũkakwatan’ye masuka atano me oka, na masuka thanthatũ me oka, na kũtũlanĩla ũla suka wa thanthatũ ngalĩ ya mbee ya ĩeema.'),
('kam', 'EXO', 26, 10, 'Na ũkaseũvye ikwatũ mĩongo ĩtano ũteenĩ wa suka ũmwe ũla wĩ mũminũkĩlyo wa vala vakwatanĩlwe, na ĩkwatũ mĩongo ĩtano ũteenĩ wa suka ũla wĩ mũminũkĩlyo wa vala vakwatanĩlwe va kelĩ.'),
('kam', 'EXO', 26, 11, 'Na ũkaseũvye tũvoloi mĩongo ĩtano twa ũthuku, noikolan’ya tũvoloi na ikwatũ, na kũkwatan’ya ĩeema vamwe, nĩ kana yĩthĩwe yĩ yĩmwe.'),
('kam', 'EXO', 26, 12, 'Na kĩlungu kĩla kĩtialĩte kĩniinĩte kya masũka ma ĩeema, o ĩla nyunzu ya suka ĩla ĩtialĩte, kĩkaniine wĩkalonĩ mbĩlĩlo.'),
('kam', 'EXO', 26, 13, 'Na mũkono ngalĩ ĩmwe, na mũkono ngalĩ ĩla ĩngĩ, wa ũasa ũla ũtialĩte wa masuka ma ĩeema, ũkaniine ngalĩ syelĩ sya wĩkalo, ngalĩ ĩno na ngalĩ ĩla ĩngĩ, nĩ kana wũvw’ĩke.'),
('kam', 'EXO', 26, 14, 'Na ũkaseũvye kĩndũ kya kũvw’ĩka ĩeema kya mbũa sya ndũũme syĩkĩĩtwe langi mũtune, na ĩũlũ wakyo kĩngĩ kya mbũa sya vomboo.'),
('kam', 'EXO', 26, 15, 'Na ũkaseũvye mbwaũ sya wĩkalo sya mĩtĩ ya mũea, iũngamĩtw’e.'),
('kam', 'EXO', 26, 16, 'Ũasa wa kĩla ũvwaũ ũkeethĩwa mĩkono ĩkũmi, na ũthanthau wa kĩla ũvwaũ mũkono na nyunzu.'),
('kam', 'EXO', 26, 17, 'Kĩla ũvwaũ wĩthĩwe na isinĩko ilĩ isinĩkanĩtw’e ũmwe na ũla ũngĩ: ũkeke ũu ũndũ wa mbwaũ syonthe sya ũla wĩkalo.'),
('kam', 'EXO', 26, 18, 'Na ũkaseũvye mbwaũ sya wĩkalo, mbwaũ mĩongo ĩlĩ ũndũ wa ngalĩ ya ĩtheo kwelekela ĩtheo.'),
('kam', 'EXO', 26, 19, 'Na ũkaseũvye iĩndĩ mĩongo ĩna sya vetha ungu wa ila mbawũ mĩongo ĩlĩ; iĩndĩ ilĩ ungu wa ũvwaũ ũmwe ũndũ wa isinĩko ilĩ syaw’o, na iĩndĩ ilĩ ungu wa ũvwaũ ũngĩ ũndũ wa isinĩko ilĩ syaw’o:'),
('kam', 'EXO', 26, 20, 'na ũndũ wa ngalĩ ya kelĩ ya wĩkalo, ngalĩ ya ĩũlũ, mbwaũ mĩongo ĩlĩ,'),
('kam', 'EXO', 26, 21, 'na iĩndĩ syasyo mĩongo ĩna sya vetha; iĩndĩ ilĩ ungu wa ũvwaũ ũmwe, na iĩndĩ ilĩ ungu wa ũvwaũ ũngĩ.'),
('kam', 'EXO', 26, 22, 'Na ũkaseũvye mbwaũ thanthatũ ũndũ wa ngalĩ ya mbĩlĩlo ya wĩkalo kwelekela ũthũĩlonĩ wa syũa.'),
('kam', 'EXO', 26, 23, 'Na ũkaseũvye mbwaũ ilĩ ũndũ wa ikoto sya ũ wĩkalo ngalĩ ya mbĩlĩlo.'),
('kam', 'EXO', 26, 24, 'Na ikethĩwe ilĩ ilĩ ikwatene kuma nthĩ, na ikethĩwe ikwatene o ta ũu kũvika mũthya wĩ ĩũlũ wasyo, kũvika ngomenĩ ĩmwe: kũkethĩwe ũu ũndũ wasyo syelĩ; ikeethĩwa sya ila ikoto ilĩ.'),
('kam', 'EXO', 26, 25, 'Na kũkethĩwe mbwaũ nyanya, na iĩndĩ syasyo sya vetha, iĩndĩ ĩkũmi na thanthatũ: iĩndĩ ilĩ ungu wa ũvwaũ ũmwe, na iĩndĩ ilĩ ungu wa ũvwaũ ũngĩ.'),
('kam', 'EXO', 26, 26, 'Na ũkaseũvye mĩamba ya mĩtĩ ya mũea; ĩtano ũndũ wa mbwaũ sya ngalĩ ĩmwe ya wĩkalo,'),
('kam', 'EXO', 26, 27, 'na mĩamba ĩtano ũndũ wa mbwaũ sya ngalĩ ĩla ĩngĩ ya wĩkalo, na mĩamba ĩtano ũndũ wa mbwaũ sya wĩkalo ngalĩ ya mbĩlĩlo kwelekela ũthũĩlonĩ wa syũa.'),
('kam', 'EXO', 26, 28, 'Na mũamba ũla wĩ katĩ, o ũla wĩvĩtĩlaa mbwaũnĩ katĩ, ũkavĩtĩlaa kuma mũthya kũvika mũthya ũla ũngĩ.'),
('kam', 'EXO', 26, 29, 'Na ũkavw’ĩke mbwaũ thaavu, na kũseũvya ngome syasyo sya thaavu sya kũtonyeesya ĩla mĩamba: na ũkavw’ĩke mĩamba thaavu.'),
('kam', 'EXO', 26, 30, 'Na ũkaũngamye wĩkalo kwĩanana na ngelekan’yo yaw’o ĩla woonew’e kĩĩmanĩ.'),
('kam', 'EXO', 26, 31, 'Na ũkaseũvye tũtũ wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe: ũkatumĩĩwa ngelekan’yo ya akeluvi, wĩa wa mũtethya wa wĩa ũla mũĩ:'),
('kam', 'EXO', 26, 32, 'na ũkawanĩke itũĩnĩ inya sya mĩtĩ ya mũea ivw’ĩkĩtwe thaavu; syambo syasyo ikethĩwe sya thaavu, ĩũlũ wa iĩndĩ inya sya vetha.'),
('kam', 'EXO', 26, 33, 'Na ũkanĩke ũla tũtũ ĩtheo wa tũvoloi, noiete vu nthĩnĩ wa tũtũ yĩla ĩsandũkũ ya ũkũsĩ: na ũla tũtũ ũkamũvathũkanĩsya vala vandũ vatheu na vala vandũ vatheu mbee.'),
('kam', 'EXO', 26, 34, 'Na ũkaie ũla wĩkalo wa tei ĩũlũ wa ĩsandũkũ ya ũkũsĩ nthĩnĩ wa vala vandũ vatheu mbee.'),
('kam', 'EXO', 26, 35, 'Na ũkaie ĩla mesa ũtee wa tũtũ, na kĩla kĩndũ kĩkĩawa mataa kyelekele mesa ngalĩ ya wĩkalo kwelekela ngalĩ ya ĩtheo: na ũkaie mesa ngalĩ ya ĩũlũ.'),
('kam', 'EXO', 26, 36, 'Na ũkaseũvye tama wa mũomonĩ wa yĩla Ĩeema, wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe, wĩa wa mũtumi mũĩ wa ndii.'),
('kam', 'EXO', 26, 37, 'Na ũkaseũvĩsye tama ituĩ itano sya mĩtĩ ya mũea, na kwivw’ĩka thaavu: syambo syasyo ikethĩwe sya thaavu: na ũkaiseũvĩsye iĩndĩ itano sya ũthuku.'),
('kam', 'EXO', 27, 1, 'Na ũkaseũvye kĩthembeo kya mĩtĩ ya mũea, ũasa wakyo mĩkono ĩtano, na ũthanthau wakyo mĩkono ĩtano; kĩthembeo kĩkethĩwe kĩanene ngalĩ inya: na ũtũlu wakyo ũkethĩwe mĩkono ĩtatũ.'),
('kam', 'EXO', 27, 2, 'Na ũkaseũvye mbya syakyo ĩũlũ wa ikoto ĩnya syakyo: mbya syakyo ikethĩwe kĩlungu kĩmwe nakyo: na ũkakĩvw’ĩke ũthuku.'),
('kam', 'EXO', 27, 3, 'Na ũkaseũvye mĩio yakyo ya kwokaa mũu wakyo, na mĩko yakyo, na masaani manene makyo, na itonyi sya nyama syakyo, na tũvũngũlyũ twa ũkua makaa: ũkaseũvye mĩio yonthe yakyo ya ũthuku.'),
('kam', 'EXO', 27, 4, 'Na ũkakĩseũvĩsye seng’eng’e wa ũthuku; na ĩũlũ wa seng’eng’e ũkaseũvye ngome inya sya ũthuku ikotonĩ inya syaw’o.'),
('kam', 'EXO', 27, 5, 'Na ũkawĩkĩe ĩtheo wa ũengo ũla wĩlingĩlĩte kĩthembeo ngalĩ ya ungu, nĩ kana seng’eng’e wambate ũvike kĩthembeonĩ katĩ.'),
('kam', 'EXO', 27, 6, 'Na ũkaseũvĩsye kĩthembeo mĩtĩ, mĩtĩ ya mũea, na ũimĩvw’ĩka ũthuku.'),
('kam', 'EXO', 27, 7, 'Na ĩla mĩtĩ yakyo yĩkĩawe ngomenĩ, na ĩla mĩtĩ ĩkethĩwe ngalĩ syelĩ sya kĩthembeo, kĩkĩkuwa.'),
('kam', 'EXO', 27, 8, 'Ũkakĩseũvye na mbwaũ, kĩ na ĩima nthĩnĩ katĩ: o tondũ woonew’e kĩĩmanĩ, o ta ũu makakĩseũvye.'),
('kam', 'EXO', 27, 9, 'Na ũkaseũvye nza ya ũla wĩkalo: ngalĩ ya ĩtheo kwelekela ĩtheo kũkethĩwe ngũa sya kũniinw’a sya nza sya katane nzeo mbokothe, ũasa wasyo mĩkono ĩana ngalĩ ĩmwe:'),
('kam', 'EXO', 27, 10, 'na ituĩ syasyo ikethĩwe mĩongo ĩlĩ, na iĩndĩ syasyo mĩongo ĩlĩ, sya ũthuku; syambo sya ituĩ na mĩkunzu ikethĩwe sya vetha.'),
('kam', 'EXO', 27, 11, 'Na o ta ũu ngalĩ ya ĩũlũ kũkethĩwe ngũa sya kũniinw’a, ũasa wasyo mĩkono ĩana, na ituĩ syasyo mĩongo ĩlĩ, na iĩndĩ syasyo mĩongo ĩlĩ, sya ũthuku; syambo sya ituĩ, na mĩkunzu yasyo, ikethĩwe sya vetha.'),
('kam', 'EXO', 27, 12, 'Na kwondũ wa ũthanthau wa nza ngalĩ ya ũthũĩlonĩ wa syũa kũkethĩwe ngũa sya kũniinw’a, ũasa wasyo mĩkono mĩongo ĩtano; ituĩ syasyo ĩkũmi, na iĩndĩ syasyo ĩkũmi.'),
('kam', 'EXO', 27, 13, 'Na ũthanthau wa nza ngalĩ ya wumĩlonĩ wa syũa kwelekela wumĩlonĩ wa syũa ũkethĩwe mĩkono mĩongo ĩtano.'),
('kam', 'EXO', 27, 14, 'Ngũa sya kũniinw’a ila sya ngalĩ ĩmwe ya mbingĩlo ikethĩwe sya mĩkono ĩkũmi na ĩtano; itui syasyo itatũ, na iĩndĩ syasyo itatũ.'),
('kam', 'EXO', 27, 15, 'Na ngalĩ ĩla ĩngĩ kũkethĩwe ngũa sya kũniinw’a sya mĩkono ĩkũmi na ĩtano; ituĩ syasyo itatũ, na iĩndĩ syasyo itatũ.'),
('kam', 'EXO', 27, 16, 'Na kwondũ wa mbingĩlo ya nza kũkethĩwe tama wa mĩkono mĩongo ĩlĩ, wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe, wĩa wa mũtumi mũĩ wa ndii; ituĩ syaw’o inya, na iĩndĩ syaw’o inya.'),
('kam', 'EXO', 27, 17, 'Ituĩ syonthe syĩlingĩle ĩla nza ikakwatanw’e na mũkunzu wa vetha; syambo syasyo ikethĩwe sya vetha, iĩndĩ syasyo sya ũthuku.'),
('kam', 'EXO', 27, 18, 'Ũasa wa nza ũkethĩwe wa mĩkono ĩana, na ũthanthau wayo mĩongo ĩtano kw’onthe, na ũtũlu wayo mĩkono ĩtano, yĩthĩwe ya katane nzeo mbokothe, na iĩndĩ syayo sya ũthuku.'),
('kam', 'EXO', 27, 19, 'Mĩio yonthe ya ũla wĩkalo ũthũkũminĩ waw’o w’onthe, na syambo syaw’o syonthe, na syambo syonthe sya nza, ikethĩwe sya ũthuku.'),
('kam', 'EXO', 27, 20, 'Na ũkeaĩe ana ma Isilaeli, makũetee mauta matheu ma mosyao ma mĩthata makimĩtwe mũno kwondũ wa kyeni, makanasye taa, nĩ kana matume taa wakana ĩndĩ yonthe.'),
('kam', 'EXO', 27, 21, 'Aluni na ana make makoseũvasye kuma wĩoo kũvika kĩoko vala ve Yeova ĩeemanĩ ya kũmbanĩa, ũtee wa tũtũ ũla wĩ ngalĩ ya mbee ya ĩsandũkũ ya ũkũsĩ: ũkeethĩwa mwamũlo kwondũ wa ana ma Isilaeli kũvika tene na tene mosyaanĩonĩ moo.'),
('kam', 'EXO', 28, 1, 'Naku mwĩte Aluni, mwana‐a‐mwenyu, oke vala ũĩ, na ana make vamwe nake, kuma ananĩ ma Isilaeli, nĩ kana anthũkũmae wĩanĩ wa ũthembi, Aluni, o na Natavu, na Aviu, na Eleasali, na Ithamali, ana ma Aluni.'),
('kam', 'EXO', 28, 2, 'Na ũkaseũvĩsye Aluni, mwana‐a‐mwenyu, ngũa ntheu, kwondũ wa kũmũtaĩĩthya na kũmwanakavya.'),
('kam', 'EXO', 28, 3, 'Na ũkaneene na onthe ala me na ũĩ ngoonĩ, ala nusũĩtye na veva wa ũĩ, nĩ kana maseũvye ngũa sya Aluni sya ũmũvathan’ya ethĩwe mũtheu, nĩ kana anthũkũmae wĩanĩ wa ũthembi.'),
('kam', 'EXO', 28, 4, 'Na ii nĩsyo ngũa ila metuma: kakalo ka kĩthũi, na evoti, na ngũa ndasa, na kanzũ wa kũngũlũ, na ngutw’a, na mũsivi: na makamaseũvĩsye Aluni mwana‐a‐mwenyu, na ana make, ngũa ntheu, nĩ kana anthũkũmae wĩanĩ wa ũthembi.'),
('kam', 'EXO', 28, 5, 'Na nĩmakose ũla thaavu, na ila ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo.'),
('kam', 'EXO', 28, 6, 'Na makaseũvye yĩla evoti ya thaavu, na ya ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe, wĩa wa mũtethya wa wĩa ũla mũĩ.'),
('kam', 'EXO', 28, 7, 'Yĩkethĩwe na ikwatũ ilĩ sya ituonĩ ikwatene na mĩthya ĩlĩ yayo, nĩ kana yĩkwatanw’e vamwe.'),
('kam', 'EXO', 28, 8, 'Na ũla mũsivi ũtũmĩtwe na ũĩ, ũla wĩ ĩũlũ wayo, o ũla wa kũyova yĩlũme, ũkaseũvw’e ũndũ ũmwe nayo na wa kĩlungu kĩmwe nayo; wa thaavu, na wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe.'),
('kam', 'EXO', 28, 9, 'Na ũkose tũvila twĩlĩ twa nzumalati, noitũvana masyĩtwa ma ana ma Isilaeli:'),
('kam', 'EXO', 28, 10, 'masyĩtwa thanthatũ moo kavilanĩ kamwe, na masyĩtwa thanthatũ ala matiala kavilanĩ kala kangĩ, kwĩanana na mosyaanĩo moo.'),
('kam', 'EXO', 28, 11, 'Ũkavane tũvila tũu twĩlĩ kwĩanana na wĩa wa mũvani wa tũvila, o ta movano me ngomenĩ ya kũsiĩla, kũatĩĩa masyĩtwa ma ana ma Isilaeli: ũkaseũvye tũlũmanĩthw’e iĩndĩnĩ sya thaavu.'),
('kam', 'EXO', 28, 12, 'Na ũkekĩe tũla tũvila twĩlĩ ikwatũnĩ sya ituo sya evoti, twĩthĩwe tũvila twa ũlilikan’yo kwondũ wa ana ma Isilaeli: na Aluni akakuĩaa masyĩtwa moo vu mbee wa Yeova ituonĩ syake kwondũ wa ũlilikan’yo.'),
('kam', 'EXO', 28, 13, 'Na ũkaseũvye iĩndĩ sya thaavu,'),
('kam', 'EXO', 28, 14, 'na mĩnyoo ĩlĩ ya thaavu mũtheu; ũkamĩseũvye ta tũkanda, twa wĩa wa kũvĩnda: na ũkekĩe ĩla mĩnyoo mĩvĩnde iĩndĩnĩ.'),
('kam', 'EXO', 28, 15, 'Na ũkaseũvye kakalo ka kĩthũi ka kũtw’a sila, wĩa wa mũtethya wa wĩa ũla mũĩ; ũkakaseũvye o ta evoti; ũkakaseũvye ka thaavu, na ka ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe.'),
('kam', 'EXO', 28, 16, 'Kakethĩwe keanene ngalĩ inya, katũlanĩlwa; ũasa wako ũkeethĩwa wa ĩkwata yĩmwe ya kĩtaa, na ũthanthau wayo ĩkwata yĩmwe ya kĩtaa.'),
('kam', 'EXO', 28, 17, 'Na ũkekĩe nthĩnĩ wako tũvila tũlũmanĩthw’e iĩndĩnĩ syatw’o, mĩsoa ĩna ya tũvila: mũsoa wa mbee wa salitũ, na tovasi, na alimasi ndune;'),
('kam', 'EXO', 28, 18, 'na mũsoa wa kelĩ sumalati, na savili, na salitonyi;'),
('kam', 'EXO', 28, 19, 'na mũsoa wa katatũ samawi, na yasimu, na amethusito;'),
('kam', 'EXO', 28, 20, 'na mũsoa wa kana nzumalati ntheu, na nzumalati, na yasivi: tũlũmanĩthw’e na thaavu iĩndĩnĩ syatw’o.'),
('kam', 'EXO', 28, 21, 'Na tũvila tũu tũkeethĩwa tũkĩatĩĩa masyĩtwa ma ana ma Isilaeli, ĩkũmi na elĩ, kwĩanana na masyĩtwa moo; o ta movano me ngomenĩ ya kũsiĩla, kĩla kamwe kwĩanana na syĩtwa yake, nĩtũkethĩwa kwondũ wa ila mbaĩ ĩkũmi na ilĩ.'),
('kam', 'EXO', 28, 22, 'Na ũkaseũvye mĩnyoo ĩtilyĩ tũkanda kakalonĩ ka kĩthũi ĩũlũ, ya thaavu mũtheu wĩ mũvĩnde.'),
('kam', 'EXO', 28, 23, 'Na ũkaseũvye kakalonĩ ka kĩthũi ĩũlũ ngome ilĩ sya thaavu, na kwĩkĩa ngome isu ilĩ mĩthyanĩ ĩlĩ ya kakalo ka kĩthũi.'),
('kam', 'EXO', 28, 24, 'Na ũkĩkĩa ĩla mĩnyoo ĩlĩ mĩvĩnde ya thaavu ila ngomenĩ ilĩ ila syĩ mĩthyanĩ ya kakalo ka kĩthũi.'),
('kam', 'EXO', 28, 25, 'Na mĩthya ĩla ĩngĩ ĩlĩ ya ĩla mĩnyoo ĩlĩ mĩvĩnde ũkekĩe ĩũlũ wa ila iĩndĩ ilĩ, na kũkolelya ikwatũnĩ sya ituo sya evoti ngalĩ ya mbee yayo.'),
('kam', 'EXO', 28, 26, 'Na ũkatue ngome ilĩ sya thaavu, na ũikolelya mĩthyanĩ ĩlĩ ya kakalo ka kĩthũi, ũtiivonĩ wako, ũla welekele ngalĩ ya nthĩnĩ ya evoti.'),
('kam', 'EXO', 28, 27, 'Na ũkatue ngome ilĩ sya thaavu, na ũikolelya ikwatũnĩ ilĩ sya ituo sya evoti ungu, ngalĩ ya mbee yayo, vakuvĩ na vala vakwatanĩlwe vayo, ĩũlũ wa ũla mũsivi wa evoti ũtumĩtwe na ũĩ.'),
('kam', 'EXO', 28, 28, 'Na makalũmanye kakalo ka kĩthũi na ngome syako ngomenĩ sya evoti na ũlii wa vuluu, nĩ kana kethĩwe ĩũlũ wa ũla mũsivi wa evoti ũtumĩtwe na ũĩ, na nĩ kana kala kakalo ka kĩthũi kaikathaw’e yĩla evotinĩ.'),
('kam', 'EXO', 28, 29, 'Na Aluni akakuae masyĩtwa ma ana ma Isilaeli kakalonĩ ka kĩthũi ka kũtw’a sila ĩũlũ wa ngoo yake, yĩla wĩvotaa vala vandũ vatheu, kwondũ wa ũlilikan’yo vu mbee wa Yeova ĩndĩ yonthe.'),
('kam', 'EXO', 28, 30, 'Na ũkekĩe kakalonĩ ka kĩthũi ka kũtw’a sila Ulimu na Thumimu; nasyo ikeethĩwa ĩũlũ wa ngoo ya Aluni, yĩla wĩvotaa vala ve Yeova: na Aluni akakuĩaa ũsilĩlo wa ana ma Isilaeli ĩũlũ wa ngoo yake vu mbee wa Yeova ĩndĩ yonthe.'),
('kam', 'EXO', 28, 31, 'Na ũkaseũvye ĩla ngũa ndasa ya evoti yonthe ya vuluu.'),
('kam', 'EXO', 28, 32, 'Nayo ĩkethĩwe na ĩima katĩ, ya kũlikya mũtwe: ĩkethĩwe na ũtaami mũtume wĩlingĩle ĩimanĩ yayo, yĩilyĩ ta ĩima yĩkĩwe kakotĩ ka kaũ, nĩ kana ndĩkatembũke.'),
('kam', 'EXO', 28, 33, 'Na motiivonĩ mayo ũkaseũvye makũngũmanga ma ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, kwĩlingĩla ũtiivonĩ wayo; na tũtilili twa thaavu katĩ wamo twĩlingĩlĩte:'),
('kam', 'EXO', 28, 34, 'katilili ka thaavu na ĩkũngũmanga, katilili ka thaavu na ĩkũngũmanga, kwĩlingĩla ngũa ũtiivonĩ wayo.'),
('kam', 'EXO', 28, 35, 'Nayo ĩkekĩwe nĩ Aluni nĩ kana athũkũmae: na wasya watw’o ũkeew’ĩka yĩla wĩvotaa nthĩnĩ wa vala vandũ vatheu vala ve Yeova, na yĩla wĩumĩlaa, nĩ kana ndakakw’e.'),
('kam', 'EXO', 28, 36, 'Na ũkaseũvye kĩlaũnĩ kya thaavu mũtheu, noivana ĩũlũ wakyo, o ta movano me ngomenĩ ya kũsiĩla, MŨTHEU KWA YEOVA.'),
('kam', 'EXO', 28, 37, 'Na ũkakĩkĩe ũliinĩ wa vuluu, na kĩkeethĩwa ngutw’anĩ; kĩkethĩwe ngutw’anĩ ngalĩ ya mbee.'),
('kam', 'EXO', 28, 38, 'Na kĩkeethĩwa kĩtulyanĩ kya Aluni, na Aluni akakuaa ũthũku wa ila syĩndũ ntheu, ila ana ma Isilaeli makavathan’ya syĩthĩwe ntheu mĩthĩnzĩonĩ yoo yonthe mĩtheu; na kĩkeethĩwa kĩtũlyanĩ kyake ĩndĩ yonthe, nĩ kana metĩkĩlwe kwa Yeova.'),
('kam', 'EXO', 28, 39, 'Na ũkatume ũla kanzũ wa kũngũlũ wa katane nzeo, na kũseũvya ngutw’a ya katane nzeo, na kũseũvya mũsivi, wĩa wa mũtumi mũĩ wa ndii.'),
('kam', 'EXO', 28, 40, 'Na ũkaseũvĩsye ana ma Aluni makanzũ, na kũmaseũvĩsya mĩsivi, na kũmaseũvĩsya tũkovila, kwondũ wa kũmataĩĩthya na kũmanakavya.'),
('kam', 'EXO', 28, 41, 'Na ũkasyĩkĩe Aluni mwana‐a‐mwenyu, na ana make, na kũmetĩkĩsya mauta, na kũmavathan’ya methĩwe atheu, na kũmathesya, nĩ kana manthũkũmae wĩanĩ wa ũthembi.'),
('kam', 'EXO', 28, 42, 'Na ũkamaseũvĩsye masulũalĩ ma katane mevw’ĩkae mĩĩ yoo, ĩeke kwĩthĩwa mĩthei; makaume inyunyu kũvika matako:'),
('kam', 'EXO', 28, 43, 'na makeekĩwa nĩ Aluni, na ana make, yĩla meũlika ĩeemanĩ ya kũmbanĩa, kana yĩla meũthengeea kĩthembeonĩ mathũkũme nthĩnĩ wa vala vandũ vatheu; nĩ kana matikakue ũthũku na makĩkw’a: ũkeethĩwa mwamũlo kũvika tene na tene kwake na kwa ũsyao wake ĩtina wake.'),
('kam', 'EXO', 29, 1, 'Na ũũ nĩ ũndũ ũla wĩmeka nĩ kana ũmavathan’ye methĩwe atheu, manthũkũmae wĩanĩ wa ũthembi: osa kasalũ kamwe na ndũũme ilĩ ĩte kĩema,'),
('kam', 'EXO', 29, 2, 'na kĩmũtũ kĩte ĩlawa, na tũmũtũ tũte ĩlawa tũvulanĩtw’e na mauta, na tũmĩkate tũvũthũ tũte ĩlawa tũvakĩtwe mauta: natw’o ũkatũseũvye twa mũtu wa nganũ mũvinyu mũno.'),
('kam', 'EXO', 29, 3, 'Na ũkatwikĩe kĩkavũnĩ kĩmwe, na ũkĩtũete twĩ kĩkavũnĩ, twĩ vamwe na kala kasalũ na ila ndũũme ilĩ.'),
('kam', 'EXO', 29, 4, 'Na ũkaete Aluni na ana make mũomonĩ wa yĩla ĩeema ya kũmbanĩa, na ũimathambya na manzĩ.'),
('kam', 'EXO', 29, 5, 'Na ũkose ila ngũa, na ũkĩkĩa Aluni ũla kanzũ, na ĩla ngũa ndasa ya evoti, na yĩla evoti, na kala kakalo ka kĩthũi, na ũimũvotoa na ũla mũsivi wa evoti ũtumĩtwe na ũĩ;'),
('kam', 'EXO', 29, 6, 'na ũkamwĩkĩe ĩla ngutw’a mũtwenĩ wake, na ũkĩkĩa ĩla ngovia ntheu ya ũsumbĩ iũlũ wa ĩ ngutw’a.'),
('kam', 'EXO', 29, 7, 'Nĩvo ĩndĩ wĩosa mauta ma kwĩtĩkĩsya, na ũitulũĩla mũtwe wake, na kũmwĩtĩkĩsya mauta.'),
('kam', 'EXO', 29, 8, 'Na ũkaete ana make, na kũmekĩa makanzũ.'),
('kam', 'EXO', 29, 9, 'Na ũkamavotoe na ĩla mĩsivi Aluni na ana make, na kũmekĩa tũkovila mĩtwe: na makeethĩwa na wĩa wa ũthembi kwĩanana na mwamũlo wa tene na tene: na ũkamavathan’ye Aluni na ana make methĩwe atheu.'),
('kam', 'EXO', 29, 10, 'Na ũkaete kala kasalũ ngalĩ ya mbee ya ĩeema ya kũmbanĩa: na Aluni na ana make makailĩĩle moko moo mũtwenĩ wa kala kasalũ.'),
('kam', 'EXO', 29, 11, 'Na ũkoaĩe kala kasalũ vu mbee wa Yeova, mũomonĩ wa yĩla ĩeema ya kũmbanĩa.'),
('kam', 'EXO', 29, 12, 'Na ũkose nthakame ĩmwe ya kala kasalũ, na ũkĩvaka mbyanĩ sya kĩthembeo na kyaa kyaku; na ũkatulũĩle nthakame yonthe ĩtinanĩ ya kĩthembeo.'),
('kam', 'EXO', 29, 13, 'Na ũkose mathunya onthe ala me ĩũlũ wa mavu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, na ila mbio ilĩ, na mathunya ala me ĩũlũ wasyo, na ũivĩvĩsya ĩũlũ wa kĩthembeo.'),
('kam', 'EXO', 29, 14, 'Ĩndĩ nyama ya kala kasalũ, na kĩthuma kyako, na mũyoo wako, ũkavĩvĩsye na mwaki ũtee wa mwako wa maeema: nĩ nthembo kwondũ wa naĩ.'),
('kam', 'EXO', 29, 15, 'Na ĩngĩ ũkose ĩla ndũũme ĩmwe; na Aluni na ana make makailĩĩle moko moo mũtwenĩ wa ĩla ndũũme.'),
('kam', 'EXO', 29, 16, 'Na ũkoae ĩla ndũũme, na ũkyosa nthakame yayo, na ũkĩmĩminzangĩsya ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'EXO', 29, 17, 'Na ũkatilange ndũũme ilungu syayo, na ũithambya mavu mayo, na maũũ mayo, na kwia vamwe na ilungu syayo, na vamwe na mũtwe wayo.'),
('kam', 'EXO', 29, 18, 'Na ũkavĩvĩsye ndũũme yonthe ĩũlũ wa kĩthembeo: nĩ nthembo ĩvĩvĩaw’a Yeova; nĩ mũuke mũseo, nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'EXO', 29, 19, 'Na ũkose ndũũme ĩla ĩngĩ: na Aluni na ana make makailĩĩle moko moo mũtwenĩ wa ĩla ndũũme.'),
('kam', 'EXO', 29, 20, 'Nĩvo ĩndĩ wĩũaa ĩla ndũũme, nokyosa nthakame ĩmwe yayo, na kwĩkĩa mũthyanĩ wa kũtũ kwa aũme kwa Aluni, na mũthyanĩ wa matũ ma aũme ma ana make, na kyani kĩla kĩnene kya moko moo ma aũme, na kyaanĩ kĩla kĩnene kya maũũ moo ma aũme, na kũminzanĩsya ĩla nthakame ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'EXO', 29, 21, 'Na ũkose nthakame ĩmwe ĩla yĩ ĩũlũ wa kĩthembeo, na mauta amwe ma kwĩtĩkĩsya, na ũimĩminzangĩsya Aluni, na ngũanĩ syake, na ĩũlũ wa ana make, na ngũanĩ sya ana make vamwe nake: nake akavathanĩka, na ngũa syake, na ana make, na ngũa sya ana make vamwe nake.'),
('kam', 'EXO', 29, 22, 'Na ĩngĩ ũkose mathunya amwe ma ĩla ndũũme, na mwĩthe wayo, na mathunya ala mavw’ĩkĩte mavu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, na ila mbio ilĩ, na mathunya ala me ĩũlũ wasyo, na kũũ kwa kw’oko kwa aũme (nũndũ nĩ ndũũme ya kũmavathan’ya methĩwe atheu),'),
('kam', 'EXO', 29, 23, 'na kĩmũtũ kĩmwe, na kamũtũ kamwe kala kavulene na mauta, na kamũkate kamwe kavũthũ, kuma kĩkavũnĩ kya imũtũ ite ĩlawa ila syĩ mbee wa Yeova:'),
('kam', 'EXO', 29, 24, 'na ũkaie syonthe ĩũlũ wa moko ma Aluni, na ĩũlũ wa moko ma ana make, na ũivyũlangya syĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova.'),
('kam', 'EXO', 29, 25, 'Na ũkaumye mokonĩ moo, na ũivĩvĩsya kĩthembeonĩ ĩũlũ wa nthembo ya kũvĩvw’a, yĩthĩwe mũuke mũseo kwa Yeova: nĩ nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'EXO', 29, 26, 'Na ũkose kĩng’eng’eto kya ndũũme ya Aluni ya ũvathan’yo, na ũivyũlangya kĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova: na kĩkeethĩwa kĩlungu kyaku.'),
('kam', 'EXO', 29, 27, 'Na ũkakĩvathe kĩthĩwe kĩtheu kĩla kĩng’eng’eto kya nthembo ya kũvyũlangw’a, na kũla kũũ kwa nthembo ya kũkĩlw’a, o kũla kũvyũlangaw’a, na kĩla kyũkĩlaw’a, kya ndũũme ya ũvathan’yo, o kyu kĩla kya Aluni, na kĩla kya ana make:'),
('kam', 'EXO', 29, 28, 'na kĩkeethĩwa kya Aluni na ana make, kĩthĩwe kĩlungu kyoo kũvika tene na tene kĩla kyumaw’a kwa ana ma Isilaeli; nũndũ nĩ nthembo ya kũkilw’a: na kĩkeethĩwa nthembo ya kũkĩlw’a kyumaw’a kwa ana ma Isilaeli kya nthembo sya nthembo syoo sya mũuo, o nthembo yoo ya kũkĩlĩlw’a Yeova.'),
('kam', 'EXO', 29, 29, 'Na ngũa ila ntheu sya Aluni ikeethĩwa sya ana make ĩtina wake, nĩ kana metĩkĩw’e mauta masyĩkĩĩte, na mavathanw’e methĩwe atheu masyĩkĩĩte.'),
('kam', 'EXO', 29, 30, 'Mwana ũla wĩtw’ĩka mũthembi vandũ vake akasyĩkĩe mĩthenya mũonza, yĩla wĩũka ĩeemanĩ ya kũmbanĩa athũkũme nthĩnĩ wa vala vandũ vatheu.'),
('kam', 'EXO', 29, 31, 'Na ũkose ĩla ndũũme ya ũvathan’yo, na ũiuĩa nyama syayo vandũ vatheu.'),
('kam', 'EXO', 29, 32, 'Na Aluni na ana make makaye nyama sya ĩla ndũũme, na kĩmũtũ kĩla kĩ kĩkavũnĩ, mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'EXO', 29, 33, 'Nao makaye syĩndũ isu ila wĩw’anĩthyo woonekie nũndũ wasyo, imavathan’ye methĩwe atheu na kũmathesya: ĩndĩ mũeni ndakaiye, nĩkwĩthĩwa nĩ ntheu.'),
('kam', 'EXO', 29, 34, 'Na ethĩwa nyama o na yĩva ya ĩla ĩvathĩtwe yĩthĩwe ntheu, kana kĩmũtũ o na kĩva, ikatiala kũvika kĩoko, nĩvo ĩndĩ wĩvĩvya ila itialĩte na mwakĩ: itikaĩwe, nĩkwĩthĩwa nĩ ntheu.'),
('kam', 'EXO', 29, 35, 'Na ũkeke Aluni na ana make o ta ũu, kwĩanana na onthe ala nĩkwĩaĩĩte: ũkamavathan’ye mĩthenya mũonza methĩwe atheu.'),
('kam', 'EXO', 29, 36, 'Na ũkathembe kasalũ ka nthembo kwondũ wa naĩ kĩla mũthenya ĩthĩwe ya wĩw’anĩthyo: na ũkathesya kĩla kĩthembeo, yĩla wumasya nthembo ũndũ wa wĩw’anĩthyo kwondũ wakyo; na ũkakĩtĩkĩsye mauta, ũkĩvathan’ye kĩthĩwe kĩtheu.'),
('kam', 'EXO', 29, 37, 'Ũkaumye nthembo ya wĩw’anĩthyo mĩthenya mũonza kwondũ wa kĩthembeo, ũkĩvathan’ye: na kĩthembeo kĩkeethĩwa kĩ kĩtheu mũno vyũ; kĩndũ o na kĩva kĩla kĩkakiita kĩthembeo kĩkeethĩwa kĩ kĩtheu.'),
('kam', 'EXO', 29, 38, 'Na ĩndĩ ii nĩ ila ũkathemba kĩthembeonĩ: tũtena twa ĩlondu twĩlĩ twa mwaka ũmwe kĩla mũthenya ĩndĩ yonthe.'),
('kam', 'EXO', 29, 39, 'Katena ka ĩlondu kamwe ũkathembe kĩoko; na katena ka ĩlondu kala kangĩ ũkathembe wĩoo:'),
('kam', 'EXO', 29, 40, 'na vamwe na kala katena ka ĩlondu kamwe mũtu mũvinyu wa kĩlungu kya ĩkũmi kya eva ũvulanĩtw’e na kĩlungu kya kana kya ini ya mauta makime; na kĩlungu kya kana kya ini ya mbinyu kĩthĩwe nthembo ya kũnyuwa.'),
('kam', 'EXO', 29, 41, 'Na katena ka ĩlondu kala kangĩ ũkathembe wĩoo, na ũkakeke o tondũ wĩkie nthembo ya mũtu ya kĩoko, na ta nthembo ya kũnyuwa ya kũthembanĩsya nayo, ĩthĩwe mũuke mũseo, nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'EXO', 29, 42, 'Ikethĩwe nthembo ya kũvĩvw’a ĩtatw’ĩkanaa mosyaanĩonĩ menyu onthe vu mbee wa Yeova mũomonĩ wa ĩeema ya kũmbanĩa, vala nĩkomanĩaa naku, nĩneeneae naku vo.'),
('kam', 'EXO', 29, 43, 'Na nĩvo nĩkomanĩaa na ana ma Isilaeli; na yĩla Ĩeema yĩkavathwa yĩthĩwe ĩtheu nĩ ũtheu mũtisu wakwa.'),
('kam', 'EXO', 29, 44, 'Na ngavathan’ya ĩeema ya kũmbanĩa yĩthĩwe ĩtheu, o na kĩla kĩthembeo: o na Aluni na ana make ngamavatha, nĩ kana manthũkũmae wĩanĩ wa ũthembi.'),
('kam', 'EXO', 29, 45, 'Nakwa ngekalaa katĩ wa ana ma Isilaeli, na ngeethĩwa nĩ Ngai woo.'),
('kam', 'EXO', 29, 46, 'Namo makamanya ninyie Yeova Ngai woo, ũla wamaumisye nthĩ ya Misili, nĩ kana nĩkalae katĩ woo: ninyie Yeova Ngai woo.'),
('kam', 'EXO', 30, 1, 'Naku ũkaseũvye kĩthembeo kya kũtoeeasya ũvani ĩũlũ wakyo: ũkakĩseũvye kya mĩtĩ ya mũea.'),
('kam', 'EXO', 30, 2, 'Ũasa wakyo ũkeethĩwa mũkono, na ũthanthau wakyo mũkono, ngalĩ inya syĩanene; na ũtũlu wakyo ũkeethĩwa mĩkono ĩlĩ: mbya syakyo ikethĩwe kĩlungu kĩmwe nakyo.'),
('kam', 'EXO', 30, 3, 'Na ũkakĩvw’ĩke thaavu mũtheu, ĩũlũ wakyo, na mavava makyo onthe, na mbya syakyo; na ũkakĩseũvĩsye ũengo mũtũlu wa thaavu ũkĩlingĩle.'),
('kam', 'EXO', 30, 4, 'Na ũkakĩtuĩe ngome ilĩ sya thaavu ungu wa ũengo mũtũlu wakyo; ikotonĩ ilĩ syakyo, ngalĩ syelĩ syakyo ũkaitue; na ikeethĩwa sya kũtonyeesya mĩtĩ ĩla ya kũkĩkuaa.'),
('kam', 'EXO', 30, 5, 'Na ũkaseũvye ĩla mĩtĩ ya mũea, na ũimĩvw’ĩka thaavu.'),
('kam', 'EXO', 30, 6, 'Na ũkakie ngalĩ ya mbee ya tũtũ ũla wĩ vakuvĩ na yĩla ĩsandũkũ ya ũkũsĩ, o mbee wa wĩkalo wa tei ũla wĩ ĩũlũ wa yĩla ĩsandũkũ ya ũkũsĩ, vala nĩkomanĩaa naku.'),
('kam', 'EXO', 30, 7, 'Na Aluni akatoeeasye ĩũlũ wakyo ũvani wa mĩtĩ ĩla ĩnyungaa nesa: kĩla kĩoko, yĩla ũnũũseũvya mataa, akotoeeasye.'),
('kam', 'EXO', 30, 8, 'Na yĩla Aluni ũnũũkwatya mataa wĩoo, akotoeeasye, wĩthĩwe ũvani wa kũtoeeasya ĩvinda yonthe vala ve Yeova mosyaanĩonĩ menyu onthe.'),
('kam', 'EXO', 30, 9, 'Mũtikatoeesye ũvani wa mũthemba ũngĩ ĩũlũ wakyo, o na nthembo ya kũvĩvw’a, o na nthembo ya mũtu; na mũtikete nthembo ya kũnyuwa ĩũlũ wakyo.'),
('kam', 'EXO', 30, 10, 'Na Aluni akaumĩsye nthembo ya wĩw’anĩthyo mbyanĩ syakyo ĩvinda yĩmwe mwaka: na nthakame ya ĩla nthembo kwondũ wa naĩ ya kwĩw’anĩthya akaumye nthembo ya wĩw’anĩthyo kwondũ wakyo o ĩvinda yĩmwe mwaka mosyaanĩonĩ menyu onthe: nĩ kĩtheu mũno vyũ kwa Yeova.'),
('kam', 'EXO', 30, 11, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 30, 12, 'Yĩla ũũtala ũtalo wa ana ma Isilaeli, kwĩanana na ala matalawa katĩ woo, nĩvo ĩndĩ makanengane mbovosya kwa Yeova kĩla mũndũ mũũme kwondũ wa thayũ wake, o yĩla ũũmatala; nĩ kana kũtikethĩwe ũthĩn’yo katĩ woo, yĩla ũũmatala.'),
('kam', 'EXO', 30, 13, 'Kĩla makanengane nĩ kĩĩ, o kĩla ũmwe ũla wĩvĩtũkaa e mũtale athi kũla kwĩ asu atale: nyunzu ya sekeli kwĩanana na sekeli ya vala vandũ vatheu (ĩla sekeli nĩ ngela mĩongo ĩlĩ), nyunzu ya sekeli kwondũ wa nthembo kwa Yeova.'),
('kam', 'EXO', 30, 14, 'O ũla wĩvĩtũkaa e mũtale athi kũla kwĩ asu atale, ma myaka mĩongo ĩlĩ na mbee, akaumya nthembo kwa Yeova.'),
('kam', 'EXO', 30, 15, 'Athwii matikaumye kũvĩtũkya, na ala ngya matikaumye nini kwĩ ĩla nyunzu ya sekeli, yĩla maumasya ĩla nthembo kwa Yeova, nĩ kana mwone wĩw’anĩthyo kwondũ wa mathayũ menyu.'),
('kam', 'EXO', 30, 16, 'Na ũkaumye mbesa sya wĩw’anĩthyo kuma kwa ana ma Isilaeli, na kwitw’ĩĩa kwondũ wa ũthũkũmi wa yĩla ĩeema ya kũmbanĩa; nĩ kana ikethĩwe ũlilikan’yo kwa ana ma Isilaeli vala ve Yeova, sya wĩw’anĩthyo kwondũ wa mathayũ menyu.'),
('kam', 'EXO', 30, 17, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 30, 18, 'Na ĩngĩ ũkaseũvye kĩndũ kya kũthambĩaa kya ũthuku, na ĩtina yakyo ya ũthuku, kĩla kya ũthambĩaa. Na ũkakie katĩ wa ĩeema ya kũmbanĩa na kĩthembeo, na ũkekĩe manzĩ nthĩnĩ wakyo.'),
('kam', 'EXO', 30, 19, 'Na Aluni na ana make makathambĩasye moko na maũũ vo:'),
('kam', 'EXO', 30, 20, 'yĩla meũlika ĩeemanĩ ya kũmbanĩa, makethambye na manzĩ, matikakw’e; o na yĩla meũthengeea kĩthembeonĩ mathũkũme, mavĩvĩsye Yeova nthembo ĩvĩvaw’a na mwaki.'),
('kam', 'EXO', 30, 21, 'Ũu nĩw’o methambya moko na maũũ, matikakw’e: na ũkeethĩwa mwamũlo kwoo tene na tene, o kwake na kwa ũsyao wake mosyaanĩonĩ moo onthe.'),
('kam', 'EXO', 30, 22, 'Na ĩngĩ Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 30, 23, 'Na ĩngĩ ĩyosee mĩtĩ yĩ mũuke mũseo mbee: manemane matweku ma sekeli maana atano, na mũtalasini wĩ mũuke mũseo nyunzu ya sekeli isu, o maana elĩ na mĩongo ĩtano, na ithua syĩ mũuke mũseo maana elĩ na mĩongo ĩtano,'),
('kam', 'EXO', 30, 24, 'na kalavuu maana atano, kwĩanana na sekeli ya vala vandũ vatheu, na mauta ma mosyao ma mũthata ma ini:'),
('kam', 'EXO', 30, 25, 'na ũkaiseũvye itw’ĩke mauta matheu ma kwĩtĩkĩsya, kĩndũ kĩnyungaa nesa kĩseũvĩtw’e kwĩanana na ũĩ wa mũseũvya wa manukato: makeethĩwa mauta matheu ma kwĩtĩkĩsya.'),
('kam', 'EXO', 30, 26, 'Na ũkametĩkĩsye yĩla ĩeema ya kũmbanĩa na yĩla ĩsandũkũ ya ũkũsĩ,'),
('kam', 'EXO', 30, 27, 'na ĩla mesa na mĩio yayo yonthe, na kĩla kĩndũ kĩkĩawa mataa na mĩio yakyo, na kĩla kĩthembeo kya kũtoeeasya ũvani,'),
('kam', 'EXO', 30, 28, 'na kĩla kĩthembeo kya nthembo ya kũvĩvw’a na mĩio yakyo yonthe, na kĩla kĩndũ kya kũthambĩa na ĩtina yakyo.'),
('kam', 'EXO', 30, 29, 'Na ũkaivathan’ye nĩ kana syĩthĩwe syĩ ntheu mũno vyũ: o kĩla kĩkaikiita kĩkeethĩwa kĩ kĩtheu.'),
('kam', 'EXO', 30, 30, 'Na ũketĩkĩsye Aluni na ana make mauta, na kũmavathan’ya methĩwe atheu, nĩ kana manthũkũmae wĩanĩ wa ũthembi.'),
('kam', 'EXO', 30, 31, 'Na ũkaneene na ana ma Isilaeli, ũkĩmea, Aa makeethĩwa kwakwa mauta matheu ma kwĩtĩkĩsya mosyaanĩonĩ menyu onthe.'),
('kam', 'EXO', 30, 32, 'Matiketĩkĩĩw’e mwĩĩ wa mũndũ, o na mũtikaseũvye angĩ mailyĩ asu, o tondũ asu maseũvaw’a: nĩ matheu, na makeethĩwa me matheu kwenyu.'),
('kam', 'EXO', 30, 33, 'O ũla ũkaseũvya mailyĩ asu o na meva, o na ũla ũkamavaka mũeni, ũsu akavetwa kuma andũnĩ make.'),
('kam', 'EXO', 30, 34, 'Na Yeova amwĩa Mose, Ĩyosee mĩtĩ ĩla ĩnyungaa nesa, sitakiti, na onuka, na ngalivani; o mĩtĩ ĩla ĩnyungaa nesa vamwe na ũvumba mũtheu: kĩla ũmwe ũthimĩtwe ũndũ ũnwe na ũla ũngĩ;'),
('kam', 'EXO', 30, 35, 'na ũkaseũvye ũvani nasyo, kĩndũ kĩla kĩnyungaa nesa kĩseũvĩtw’e kwĩanana na ũĩ wa mũseũvya wa manukato, kĩvulanĩtw’e na mũnyũ, kĩkelemu na kĩtheu:'),
('kam', 'EXO', 30, 36, 'na ũkakime ũmwe wĩthĩwe mũvinyu mũno, na kũwia mbee wa yĩla ĩsandũkũ ya ũkũsĩ ieemanĩ ya kũmbanĩa, vala nĩkomanĩaa naku: ũkeethĩwa kwaku mũtheu mũno vyũ.'),
('kam', 'EXO', 30, 37, 'Na ũvani ũla ũkaseũvya, mũtikeseũvĩsye kwĩanana na ũndũ ũseũvaw’a: ũkeethĩwa kwaku mũtheu kwondũ wa Yeova.'),
('kam', 'EXO', 30, 38, 'O ũla ũkaseũvya ũilyĩ ũsu, anyungae, akavetwa kuma andũnĩ make.'),
('kam', 'EXO', 31, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 31, 2, 'Sisya, nĩnaweta na syĩtwa Mbesaleli, mwana wa Ulĩ, mwana wa Uulu, wa mbaĩ ya Yuta:'),
('kam', 'EXO', 31, 3, 'na nĩnĩmusũĩtye Veva wa Ngai, ũĩnĩ, na ũmanyinĩ, na ũmanyĩsyonĩ, na wĩanĩ wa mĩthemba yonthe,'),
('kam', 'EXO', 31, 4, 'kũmantha kwĩka mawĩa ma ũĩ, nĩ kana aseũvye thaavu, na vetha, na ũthuku,'),
('kam', 'EXO', 31, 5, 'na kwasũvya tũvila twa kũlũmanĩthw’a iĩndĩnĩ syatw’o, na kwasũvya mbwaũ, o na kũtethya mawĩa ma mĩthemba yonthe.'),
('kam', 'EXO', 31, 6, 'Na sisya, nyie, o nakwa nĩniĩte Ooliavu, mwana wa Aisamaki, wa mbaĩ ya Ndani, ethĩwe nake; na ngoonĩ sya onthe ala me na ũĩ ngoonĩ nĩnĩkĩĩte ũĩ, nĩ kana maseũvye syonthe ila nĩkwĩaĩĩte:'),
('kam', 'EXO', 31, 7, 'yĩla ĩeema ya kũmbanĩa, na yĩla ĩsandũkũ ya ũkũsĩ, na wĩkalo wa tei ũla wĩ ĩũlũ wayo, na mĩio yonthe ya yĩla ĩeema,'),
('kam', 'EXO', 31, 8, 'na ĩla mesa na mĩio yayo, na kĩla kĩndũ kĩtheu kĩkĩawa mataa na mĩio yakyo yonthe, na kĩla kĩthembeo kya ũvani,'),
('kam', 'EXO', 31, 9, 'na kĩla kĩthembeo kya nthembo ya kũvĩvw’a na mĩio yakyo yonthe, na kĩla kĩndũ kya kũthambĩaa na ĩtina yakyo,'),
('kam', 'EXO', 31, 10, 'na ngũa ila ndume nesa, na ila ngũa ntheu sya mũthembi Aluni, na ngũa sya ana make, mathũkũmae wĩanĩ wa ũthembi,'),
('kam', 'EXO', 31, 11, 'na mauta ma kwĩtĩkĩsya, na ũvani wa mĩtĩ ĩla ĩnyungaa nesa wa vala vandũ vatheu: o kwĩanana na onthe ala nĩkwĩaĩĩte nĩmakeke.'),
('kam', 'EXO', 31, 12, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 31, 13, 'Na ĩngĩ, neena na ana ma Isilaeli, ũkĩmea, Mũikatĩe kũlilikanaa masavato makwa: nũndũ nĩ ũvano katĩ wakwa nenyu mosyaanĩonĩ menyu onthe; nĩ kana mũtonye kũmanya ninyie Yeova ũla ũmũvathanasya mwĩthĩwe atheu.'),
('kam', 'EXO', 31, 14, 'Kwondũ wa ũu mũkalilikanae savato; nũndũ nĩ mũtheu kwenyu: kĩla mũndũ wĩũthũkya no mũvaka oawe; nĩkwĩthĩwa o ũla wĩtethya wĩa o na wĩva nthĩnĩ waw’o, mũndũ ũsu akavetwa kuma andũnĩ make.'),
('kam', 'EXO', 31, 15, 'Wĩa ũtethawe mĩthenya thanthatũ; ĩndĩ mũthenya wa mũonza nĩ savato wa ũthũmũo mũuu, mũtheu kwa Yeova: o ũla wĩtethya wĩa o na wĩva mũthenya wa savato, no mũvaka oawe.'),
('kam', 'EXO', 31, 16, 'Kwondũ wa ũu ana ma Isilaeli makalilikanae savato, nĩ kana masũvĩe savato mosyaanĩonĩ moo onthe, wĩthĩwe ũtianĩo wa tene na tene.'),
('kam', 'EXO', 31, 17, 'Nĩ ũvano katĩ wakwa na ana ma Isilaeli kũvika tene na tene: nũndũ nthĩnĩ wa mĩthenya thanthatũ Yeova nĩwombie ĩtu na nthĩ, na mũthenya wa mũonza athũmũa, na kũnooka.'),
('kam', 'EXO', 31, 18, 'Na yĩla waminie kũneena nake kĩĩmanĩ kya Sinai, amũnenga Mose masengea elĩ me ũla ũkũsĩ, masengea ma mavia, maandĩkĩtwe na kyaa kya Ngai.'),
('kam', 'EXO', 32, 1, 'Na yĩla andũ moonie kana Mose nĩwekalile mũno ateũtheea kuma kĩĩmanĩ, ala andũ mamũmbanĩa Aluni, na mamwĩa, Ũkĩla, tũseũvĩsye ngai, ila ikatũtongoesya, nĩkwĩthĩwa ũndũ wa Mose ũsu, ũla mũndũ watumisye nthĩ ya Misili, tũtyĩsĩ ũndũ ũmũkwatĩte.'),
('kam', 'EXO', 32, 2, 'Na Aluni amea, Thalũlangai ngome sya thaavu, ila syĩ matũnĩ ma iveti syenyu, na ma ana menyu, na ma eĩtu menyu, na mũindetee.'),
('kam', 'EXO', 32, 3, 'Na andũ onthe mathalũlanga ngome sya thaavu ila syaĩ matũnĩ moo, na mamũetee Aluni.'),
('kam', 'EXO', 32, 4, 'Nake asyosa mokonĩ moo, na aitwekethya, na asũvya na ngesa, syatw’ĩka mũvw’anano wa kasaũ: na masya, Ii nĩsyo ngai syaku, we Isilaeli, ila syakumisye nthĩ ya Misili.'),
('kam', 'EXO', 32, 5, 'Na yĩla Aluni wonie ũndũ ũsu, aaka kĩthembeo mbee wako; na Aluni atavan’ya, na asya, Ũnĩ kũkeethĩwa mboka kwondũ wa Yeova.'),
('kam', 'EXO', 32, 6, 'Na mookĩla ũnĩ ũsu tene, na mathemba nthembo sya kũvĩvw’a, na maete nthembo sya mũuo; na andũ mekala nthĩ maye na kũnyw’a, na makyũkĩla mathaũke.'),
('kam', 'EXO', 32, 7, 'Na Yeova amwĩa Mose, Ũkĩla, ũtheee; nũndũ andũ maku, ala waumisye nthĩ ya Misili, nĩmethũkĩtye:'),
('kam', 'EXO', 32, 8, 'nĩmathũkĩte mĩtũkĩ nzĩanĩ ĩla nameaĩe: nĩmeseũvĩsye mũvw’anano wa kasaũ na thaavu matwekethetye, na makathaitha, na kũkathembea, na kwasya, Ĩi nĩsyo ngai syaku, we Isilaeli, ila syakumisye nthĩ ya Misili.'),
('kam', 'EXO', 32, 9, 'Na Yeova amwĩa Mose, Nĩnonete andũ aa, na sisya, nĩ andũ me na ngingo nyũmũ:'),
('kam', 'EXO', 32, 10, 'na yu kwondũ wa ũu ndeka, ũthilĩku wakwa wakane ĩũlũ woo, na nĩ kana nĩmamine: na ngakũtw’ĩkĩthya mbaĩ nene.'),
('kam', 'EXO', 32, 11, 'Na Mose amwĩsũva Yeova Ngai wake, na amwĩa, Yeova, ũthilĩku waku wakanĩte ĩũlũ wa andũ maku nĩkĩ, ala wumĩtye nthĩ ya Misili na ũtonyi mũnene na kw’oko kwĩ vinya?'),
('kam', 'EXO', 32, 12, 'Ũkaeka Amisili maneene nĩkĩ, makyasya, Nĩwamaumisye ameke naĩ, akamoaĩe iĩmanĩ, na kũmamina kuma ĩũlũ wa nthĩ? Ĩthyũũe ũtie ũthilĩku waku, na kwĩtũnga ũndũ wa ũthũku ũũ ĩũlũ wa andũ maku.'),
('kam', 'EXO', 32, 13, 'Lilikana Avalaamu, na Isaka, na Isilaeli, athũkũmi maku, ala wamevĩtĩe na thayũ waku mwene, na wamea, Ngaingĩvya ũsyao wenyu ta ndata sya ĩtunĩ, na nthĩ ĩno yonthe ĩla nĩwetete nganenga ũsyao wenyu, na ĩkeethĩwa ũtiĩwa woo kũvika tene na tene.'),
('kam', 'EXO', 32, 14, 'Na Yeova eetũnga ũndũ wa ũthũku ũla waisye akeeka andũ make.'),
('kam', 'EXO', 32, 15, 'Na Mose eethyũũa, na atheea kuma kĩĩmanĩ, e na masengea elĩ ma ũla ũkũsĩ kw’okonĩ kwake; masengea ala maandĩkĩtwe ngalĩ syelĩ syamo; nĩmaandĩkĩtwe ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ nayo.'),
('kam', 'EXO', 32, 16, 'Na ala masengea maĩ wĩa wa Ngai, na ũla ũandĩko waĩ ũandĩko wa Ngai, ũvanĩtwe masengeanĩ.'),
('kam', 'EXO', 32, 17, 'Na yĩla Yosua wewie kĩlonzo kya andũ makĩneena mũno, amwĩa Mose, Kwĩ kĩlonzo kya kaũ mwakonĩ wa maeema.'),
('kam', 'EXO', 32, 18, 'Nake asya, Ti wasya wa ala meũlonzan’ya kwondũ wa kũkĩlya vinya, o na ti wasya wa ala makaya kwondũ wa kũkĩlw’a vinya; ĩndĩ wasya ũla ngwĩw’a nĩ wa ala mekwĩna.'),
('kam', 'EXO', 32, 19, 'Na kweethĩwa, o yĩla wathengeeie mwakonĩ wa maeema, oona kala kasaũ nao makĩsũnga: na ũthatu wa Mose wakana mũno, na ekya ala masengea kuma mokonĩ make, na amoaĩa ĩtina wa kĩĩma.'),
('kam', 'EXO', 32, 20, 'Na oosa kasaũ kala maĩ manaseũvya, na akavĩvya na mwaki, na akathia katw’ĩka mũtu, na akyũnyaĩĩkya ĩũlũ wa manzi, na anywĩthya ana ma Isilaeli.'),
('kam', 'EXO', 32, 21, 'Na Mose akũlya Aluni, Andũ aa makwĩkĩte ata, ũndũ ũmaeteete naĩ nene?'),
('kam', 'EXO', 32, 22, 'Na Aluni amwĩa, Ũthatu wa mwĩaĩi wakwa ndũkakane mũno: nĩwĩsĩ andũ aa, ũndũ me na kwenda kwa kwĩka naĩ.'),
('kam', 'EXO', 32, 23, 'Nũndũ manambĩie, Tũseũvĩsye ngai, ila ikatũtongoesya; nĩkwĩthĩwa ũndũ wa Mose ũsu, ũla mũndũ watumisye nthĩ ya Misili, tũtyĩsĩ ũndũ ũmũkwatĩte.'),
('kam', 'EXO', 32, 24, 'Na namea, O ũla wĩ na thaavu nothalũle: na ĩndĩ manenga w’o; nakwa nekya mwakinĩ, na vaumĩla kasaũ kaa.'),
('kam', 'EXO', 32, 25, 'Na yĩla Mose wonie kana andũ nĩ ang’endu (nũndũ Aluni nĩwe wamang’endisye mathekw’e nĩ amaitha moo),'),
('kam', 'EXO', 32, 26, 'nĩvo ĩndĩ Mose waũngamie mbingĩlonĩ ya mwako wa maeema, na asya, O ũla wĩ ngalĩ ya Yeova, nĩoke va nĩĩ. Na ana onthe ma Livai meeyũmbanisya vala ũĩ.'),
('kam', 'EXO', 32, 27, 'Na amea, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Kĩla mũndũ wa inyw’ĩ evotoe ũvyũ wake kĩnyunyunĩ kyake, na aienda kũũ na kũũ kuma mbingĩlonĩ kũvika mbingĩlonĩ ĩla ĩngĩ mwakonĩ w’onthe wa maeema, na akyũaa kĩla mũndũ mwana‐a‐inyia, na kĩla mũndũ mũtindan’ya wake, na kĩla mũndũ mũtũi wake.'),
('kam', 'EXO', 32, 28, 'Na ana ma Livai meeka kwĩanana na ndeto ya Mose: na mũthenya ũsu mooaie ma andũ asu ta andũ ngili itatũ.'),
('kam', 'EXO', 32, 29, 'Na Mose amea, Ĩvathei ene ũmũnthĩ mwĩthĩwe ma Yeova, ĩĩ, kĩla mũndũ ailea mwana wake, na mwana‐a‐inyia wake; nĩ kana Yeova amũnenge ũmũnthĩ ũathimo.'),
('kam', 'EXO', 32, 30, 'Na kweethĩwa ũnĩ ũsu, Mose amea andũ, Nĩmũvĩtĩtye ĩvĩtyo ĩnene: na yu ngambata nĩthi kwa Yeova; nokwĩthĩwa ngaseũvya wĩw’anĩthyo ũndũ wa ĩvĩtyo yenyu.'),
('kam', 'EXO', 32, 31, 'Na Mose asyokea Yeova, na amwĩa, Ame, andũ aa nĩmavĩtĩtye ĩvĩtyo ĩnene, na meeseũvĩsye ngai sya thaavu.'),
('kam', 'EXO', 32, 32, 'Ĩndĩ yu, ethĩwa ũkaekea ĩvĩtyo yoo—; na ethĩwa ti w’o, nĩngũkũvoya, ũmbute ĩvukunĩ yaku yĩla ũandĩkĩte.'),
('kam', 'EXO', 32, 33, 'Na Yeova amwĩa Mose, O ũla ũmbĩtanĩsye, ũsu ngavuta ĩvukunĩ yakwa.'),
('kam', 'EXO', 32, 34, 'Na yu thi, ũtongoesye ala andũ kũvika vala nakũtavisye: sisya, mũlaĩka wakwa akakũtongoesya; ĩndĩ mũthenya ũla ngasilĩla, nĩngamasilĩla ũndũ wa naĩ yoo.'),
('kam', 'EXO', 32, 35, 'Na Yeova akũna andũ asu, nĩkwĩthĩwa nĩmaseũvisye kasaũ, kala Aluni waseũvisye.'),
('kam', 'EXO', 33, 1, 'Na Yeova amwĩa Mose, Enda, wambate, we na andũ ala waumisye nthĩ ya Misili kũvika nthĩ ĩla neevĩtĩe Avalaamu, na Isaka, na Yakovo, ngĩmea, Ngamĩnenga ũsyao waku:'),
('kam', 'EXO', 33, 2, 'na ngatũma mũlaĩka athi mbee waku; na ngalũngya Mũkanaani, na Mũamoli, an Mũititi, na Mũvelisi, na Mũivi, na Mũyevusi:'),
('kam', 'EXO', 33, 3, 'o kũvika nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ: nũndũ ndiambatan’ya nĩ naku; nĩkwĩthĩwa wĩ ũko wa andũ me na ngingo nyũmũ; ndikamũminĩe nzĩanĩ.'),
('kam', 'EXO', 33, 4, 'Na yĩla andũ meewie ũvoo ũsu mũthũku, maĩa: na vatyaĩ mũndũ waaĩkĩa mawanake make.'),
('kam', 'EXO', 33, 5, 'Na Yeova amwĩa Mose, Matavye ana ma Isilaeli, Inyw’ĩ mwĩ andũ mwĩ na ngingo nyũmũ; kethĩwa ngambata katĩ wenyu o kavinda kanini kamwe, ngamũmina: kwondũ wa ũu ĩtusei yu mawanake menyu, nĩ kana nĩmanye ũndũ wa kũmwĩka.'),
('kam', 'EXO', 33, 6, 'Na ana ma Isilaeli meetusĩa mawanake moo vyũ ku kĩĩmanĩ kya Olevu.'),
('kam', 'EXO', 33, 7, 'Na ĩndĩ Mose akothaa kũkua ĩeema na kũyamba ũtee wa mwako wa maeema, vaasa na mwako wa maeema; na ayĩta, Ĩeema ya kũmbanĩa. Na kweethĩwa, kana o mũndũ ũla wendaa ũndũ kwa Yeova aumaalaa akaenda yĩla ĩeemanĩ ya kũmbanĩa, yĩla yaĩ ũtee wa mwako wa maeema.'),
('kam', 'EXO', 33, 8, 'Na kweethĩwa, yĩla Mose waumaalile athi yĩla Ĩeemanĩ, andũ onthe mookĩla, na kũũngama, kĩla mũndũ mũomonĩ wa ĩeema yake, na kũmũsyaĩĩsya Mose, kũvika avota Ĩeemanĩ.'),
('kam', 'EXO', 33, 9, 'Na kweethĩwa, yĩla Mose wavotaa yĩla Ĩeemanĩ, kĩla kĩtuĩ kya mũumbĩ kyatheea, na kũũngama mũomonĩ wa Ĩeema: na Yeova aneena na Mose.'),
('kam', 'EXO', 33, 10, 'Na andũ onthe moona kĩla kĩtuĩ kya mũumbĩ kĩũngeme mũomonĩ wa Ĩeema: na andũ onthe mookĩla na mathaitha, kĩla mũndũ mũomonĩ wa ĩeema yake.'),
('kam', 'EXO', 33, 11, 'Na Yeova aneena na Mose ũthyũ kwa ũthyũ, o ta mũndũ aineena na mũnyanyae. Na asyoka ĩngĩ mwakonĩ wa maeema: ĩndĩ mũthũkũmi wake Yosua, mwana wa Nuni, mwanake ndaauma Ĩeemanĩ.'),
('kam', 'EXO', 33, 12, 'Na Mose amwĩa Yeova, Sisya, ũmbĩĩte, Kua andũ aa: na ndũnamanyĩthya nũũ ũla wĩtũma vamwe nakwa. Ĩndĩ nũneenete, Nĩngwĩsĩ na syĩtwa yaku, na ĩngĩ nĩwonete ũseo methonĩ makwa.'),
('kam', 'EXO', 33, 13, 'Yu ĩndĩ, nĩngũkũvoya, ethĩwa nĩnonete ũseo methonĩ maku, mbon’ya yu mĩendele yaku, nĩkũmanye, nĩ kana none ũseo methonĩ maku: na sũanĩa kana mbaĩ ĩno nĩ andũ maku.'),
('kam', 'EXO', 33, 14, 'Nake amwĩa, Nyie mwene ngathi naku, na ngakũnenga ũthũmũo.'),
('kam', 'EXO', 33, 15, 'Nake amwĩa, Ethĩwa ndũũthi nakwa, ndũkatumye vaa.'),
('kam', 'EXO', 33, 16, 'Nũndũ kũkamanyĩka ata ĩndĩ, atĩ nĩnonete ũseo methonĩ maku, nyie na andũ maku? Ti atĩ nũndũ ũendanasya naitũ, nĩ kana nyie na andũ maku tũvathũkanw’e na andũ onthe ala me ĩũlũ wa nthĩ yonthe?'),
('kam', 'EXO', 33, 17, 'Na Yeova amwĩa Mose, Ngeeka ũndũ ũsu naw’o ũla ũneenete; nũndũ nĩwonete ũseo methonĩ makwa, na nĩngwĩsĩ na syĩtwa yaku.'),
('kam', 'EXO', 33, 18, 'Nake amwĩa, Nĩngũkũvoya, mbon’ya ũtheu mũtisu waku.'),
('kam', 'EXO', 33, 19, 'Nake amwĩa, Ngatuma ũseo wakwa w’onthe ũvĩtĩla mbee waku na ngatavan’ya syĩtwa ya Yeova vala ũĩ; na ngekaa nesa ũla nĩĩkaa nesa, na ngew’ĩaa tei o ũla nĩw’ĩaa tei.'),
('kam', 'EXO', 33, 20, 'Na amwĩa, Ndũtonya kwona ũthyũ wakwa; nũndũ mũndũ ndakambona na kwĩkala thayũ.'),
('kam', 'EXO', 33, 21, 'Na Yeova asya, Sisya, ve vandũ vaa nĩĩ, naku ũkaũngame ĩvianĩ ĩũlũ:'),
('kam', 'EXO', 33, 22, 'na kũkeethĩwa, ũtheu mũtisu wakwa ũkĩvĩta, ngakwĩkĩa mũvatĩnĩ wa ĩvia, na ngĩkũvw’ĩka na kw’oko kwakwa kũvika navĩtũka:'),
('kam', 'EXO', 33, 23, 'na ngaumya kw’oko kwakwa, na ũkambona mũongo; ĩndĩ ũthyũ wakwa ndũkoneka.'),
('kam', 'EXO', 34, 1, 'Na Yeova amwĩa Mose, Asũvya masengea elĩ ma ĩvia mailyĩ ala ma mbee: nakwa ngaandĩka masengeanĩ ndeto ila syaĩ masengeanĩ ma mbee, ala ũnooaie.'),
('kam', 'EXO', 34, 2, 'Na wĩthĩwe wĩyũmbanĩtye kĩoko, nokyambata kĩĩmanĩ kya Sinai o kĩoko, na kumĩla vala nĩĩ ku mũtumbĩnĩ wa kĩĩma.'),
('kam', 'EXO', 34, 3, 'Na mũndũ o na wĩva ndakoke naku; o na mũndũ ndakoneke kĩĩmanĩ kyonthe; o na ndĩthya sya mbũi na malondu kana sya ng’ombe itikaĩthw’e vakuvĩ na kĩĩma kyu.'),
('kam', 'EXO', 34, 4, 'Nake asũvya masengea elĩ ma ĩvia mailyĩ ala ma mbee; na Mose ookĩla kĩoko tene, na ambata kĩĩmanĩ kya Sinai, o tondũ Yeova wamwĩaĩĩte, na atwaa masengea elĩ ma ĩvia kw’okonĩ kwake.'),
('kam', 'EXO', 34, 5, 'Na Yeova atheea mũumbĩnĩ, na aũngama e nake vo, na atavan’ya syĩtwa ya Yeova.'),
('kam', 'EXO', 34, 6, 'Na Yeova avĩtĩla mbee wake, na atavan’ya, Yeova, Yeova, Ngai wĩ tei na mũseo, ũtathataa mĩtũkĩ, na wĩ na wingĩ wa ũseo wĩ wendo na w’o;'),
('kam', 'EXO', 34, 7, 'ũla ũmaiĩaa ngili ngili ũseo wĩ wendo, na akĩekea ũthũku na ĩvĩtyo na naĩ; na ũla ũtakatw’a mũvĩtan’ya kwĩthĩwa ti mũvĩtan’ya o na ata, na akĩĩvanĩsya kwa syana ũthũku wa aaĩthe, o na kũvika nzũkũlũ, kũvika nzyawa ya katatũ na ya kana.'),
('kam', 'EXO', 34, 8, 'Na Mose eekalaata, na akunamya mũtwe, nthĩ, na athaitha.'),
('kam', 'EXO', 34, 9, 'Na asya, Ethĩwa yu nĩnonete ũseo methonĩ maku, ame Mwĩaĩi, nĩngũkũvoya, Mwĩaĩi naende katĩ waitũ; nũndũ nĩ andũ me na ngingo nyũmũ; naku tũekee ũthũku witũ na naĩ yaitũ, na ũitwosa twĩthĩwe ũtiĩwa waku.'),
('kam', 'EXO', 34, 10, 'Nake amwĩa, Sisya, nĩngũtianĩa ũtianĩo: ngeeka maũndũ ma ũseng’ya andũ maku onthe mene, o ala mataaĩkĩka nthĩ yonthe, kana mbaĩnĩ o na yĩkũ; na andũ onthe ala ũtwĩe katĩ woo makoona wĩa wa Yeova; nĩkwĩthĩwa nĩ ũndũ wa ũtĩsya ũla nĩĩka naku.'),
('kam', 'EXO', 34, 11, 'Sũvĩa ũla ngũkwĩaĩa mũnthĩ ũũ: sisya, nĩngũmalũngya maume mbee waku Mũamoli, na Mũkanaani, na Mũititi, na Mũvelisi, na Mũivi, na Mũyevusi.'),
('kam', 'EXO', 34, 12, 'Ĩsũvĩe mwene, ndũkatianĩe ũtianĩo na andũ ala matũaa nthĩ ĩla ũendete, ndũkese ũkũtw’ĩkĩa kĩtei:'),
('kam', 'EXO', 34, 13, 'ĩndĩ mũkanange ithembeo syoo, na kũtũlanga ilungu ituĩ syoo, na mũkateme Aselimu yoo ĩvalũke'),
('kam', 'EXO', 34, 14, '(nĩkwĩthĩwa, we, ndũkaathaithe ngai ĩngĩ o na yĩva: nũndũ Yeova, ũla wĩtawa Wĩ‐kĩwĩu, nĩ Ngai wĩ kĩwĩu);'),
('kam', 'EXO', 34, 15, 'nĩ kana ndũkese kũtianĩa ũtianĩo na andũ ala matũaa ĩ nthĩ, na makeeka ũmalwaya makĩatĩĩa ngai syoo, na kũthembea ngai syoo, na ũmwe akakwĩta naku ũkaya nthembo yake;'),
('kam', 'EXO', 34, 16, 'na kũmevaĩsya ana maku eĩtu moo, na eĩtu moo makeeka ũmalwaya makĩatĩĩa ngai syoo, na kũtuma ana maku meka ũmalwaya makĩatĩĩa ngai syoo.'),
('kam', 'EXO', 34, 17, 'Ndũkeseũvĩsye ngai na syĩndũ ila ũtwekethetye.'),
('kam', 'EXO', 34, 18, 'Ũkalilikanae mboka ya kĩmũtũ kĩte ĩlawa. Ũkaĩsae kĩmũtũ kĩte ĩlawa mĩthenya mũonza, o tondũ nĩkwĩaĩĩte, ĩvinda yĩtw’ĩtwe mwei wa Avivu; nũndũ mwei wa Avivu nĩwaumie Misili.'),
('kam', 'EXO', 34, 19, 'Onthe ala mambaa kuma ĩvunĩ ya nyinyia nĩ makwa; o na ĩndo syaku ila nũme, o yĩla yĩsyawa mbee ya ng’ombe kana ĩlondu.'),
('kam', 'EXO', 34, 20, 'Na yĩla yĩsyawa mbee nĩ ĩng’oi ũkovosye na katena ka ĩlondu: na ethĩwa ndũkwenda kũyovosya ũkayĩtũle ngingo ĩndĩ. Makithathi onthe ma ana maku ũkamovosye. Na vati ũmwe o na wĩva ũkoka vala nĩĩ e na moko mathei.'),
('kam', 'EXO', 34, 21, 'Ũkatethasye wĩa mĩthenya thanthatũ, ĩndĩ mũthenya wa mũonza ũkathũmũae: ũkathũmũa ĩvinda ya kũĩma na ya kũketha.'),
('kam', 'EXO', 34, 22, 'Na ũkalilikanae mboka ya syumwa, o ya ũsyao wa mbee wa ngetha ya nganũ, na mboka ya ngetha mũminũkĩlyo wa mwaka.'),
('kam', 'EXO', 34, 23, 'Mavinda atatũ kĩla mwaka aũme maku onthe makonekae vala ve Mwĩaĩi Yeova, Ngai wa Isilaeli.'),
('kam', 'EXO', 34, 24, 'Nũndũ ngakũlũngĩlya mbaĩ syume mbee waku, na ngyongela mĩvaka yaku: o na vatikethĩwa mũndũ o na wĩva ũkew’ĩa nthĩ yaku ĩtomo, yĩla ũkambataa kwoneka vala ve Yeova Ngai waku mavinda atatũ mwaka.'),
('kam', 'EXO', 34, 25, 'Ndũkathembanĩsye nthakame ya nthembo yakwa na kĩmũtũ kĩ ĩlawa; o na nthembo ya mboka ya vasaka ndĩkatialw’e kũvika kĩoko.'),
('kam', 'EXO', 34, 26, 'Wa mbee wa ũsyao wa mbee wa nthĩ yaku ũkaete nyũmbanĩ ya Yeova Ngai waku. Ndũkaue katena ka mbũi na ĩia ya nyinyia wako.'),
('kam', 'EXO', 34, 27, 'Na Yeova amwĩa Mose, Andĩka ndeto ii: nũndũ kwĩanana na ndeto ii nĩnatianĩa ũtianĩo naku vamwe na Isilaeli.'),
('kam', 'EXO', 34, 28, 'Na aĩ vo vamwe na Yeova mĩthenya mĩongo ĩna na matukũ mĩongo ĩna; ndaaya kĩmũtũ, o na kũnyw’a manzĩ. Na aandĩka ala masengeanĩ ila ndeto sya ũtianĩo, o ĩla mĩao ĩlũmi.'),
('kam', 'EXO', 34, 29, 'Na kweethĩwa, yĩla Mose watheeie kuma kĩĩmanĩ kya Sinai e na ala masengea elĩ ma ũla ũkũsĩ kw’okonĩ kwa Mose, yĩla watheeie kuma kĩĩmanĩ, Mose ndaamanya kana kĩkonde kya ũthyũ wake nĩkyatisatisaa kwondũ wa kũneena nake.'),
('kam', 'EXO', 34, 30, 'Na yĩla Aluni na ana onthe ma Isilaeli moonie Mose, sisya, kĩkonde kya ũthyũ wake kyatisatisaa; na makĩaa kũmũthengeea.'),
('kam', 'EXO', 34, 31, 'Na Mose ameta; na Aluni na asumbĩki onthe ma ũmbano mamũsykea: na Mose aneena nao.'),
('kam', 'EXO', 34, 32, 'Na ĩtina ana onthe ma Isilaeli mathengeea: na ameaĩa onthe ala Yeova ũnaneenete nake kĩĩmanĩ kya Sinai.'),
('kam', 'EXO', 34, 33, 'Na yĩla Mose waminie kũneena nao, eevw’ĩka ũthyũ wake suka mũvũthũ.'),
('kam', 'EXO', 34, 34, 'Ĩndĩ yĩla Mose walikaa kwa Yeova aneene nake, aumya ũla suka, kũvika aumaala; na aumaala, na atavya ana ma Isilaeli o ũndũ wiaĩĩtwe.'),
('kam', 'EXO', 34, 35, 'Na ana ma Isilaeli moona ũthyũ wa Mose, atĩ kĩkonde kya ũthyũ wa Mose kyatisatisaa; na Mose eevw’ĩka ũthyũ wake ũla suka ĩngĩ, kũvika yĩla walika aneene nake.'),
('kam', 'EXO', 35, 1, 'Na Mose oomban’ya ũmbano w’onthe wa ana ma Isilaeli, na awĩa, Ii nĩsyo ndeto ila Yeova wĩaĩte, nĩ kana mũsyĩkae.'),
('kam', 'EXO', 35, 2, 'Mĩthenya thanthatũ wĩa ũkatethaw’e; ĩndĩ mũthenya wa mũonza kũkeethĩwa kwenyu mũthenya mũtheu, o savato wa ũthũmũo mũuu kwa Yeova: o ũla wĩtethya wĩa o na wĩva nthĩnĩ waw’o mũvaka oawe.'),
('kam', 'EXO', 35, 3, 'Mũikakan’ye mwaki motũinĩ menyu onthe mũthenya wa savato.'),
('kam', 'EXO', 35, 4, 'Na Mose aneena na ũmbano w’onthe wa ana ma Isilaeli, akĩwĩa, Ũũ nĩw’o ũla Yeova wĩaĩte, akyasya,'),
('kam', 'EXO', 35, 5, 'Mumĩsyei Yeova nthembo kuma kwenyu; o ũla wĩ na ngoo ya kwenda, namĩete, nthembo ya Yeova: thaavu, na vetha, na ũthuku,'),
('kam', 'EXO', 35, 6, 'na langi wa vuluu, na ũla ũtilyĩ ta mũtune, na ũla mũtune mũno, na katane nzeo, na maw’ĩa ma mbũi,'),
('kam', 'EXO', 35, 7, 'na mbũa sya ndũũme syĩkĩĩtwe langi mũtune, na mbũa sya vomboo, na mĩtĩ ya mũea,'),
('kam', 'EXO', 35, 8, 'na mauta ma kwakan’ya taa, na mĩtĩ ĩla ĩnyungaa nesa kwondũ wa mauta ma kwĩtĩkĩsya, na kwondũ wa ũvani ũla ũnyungaa nesa,'),
('kam', 'EXO', 35, 9, 'na tũvila twa nzumalati, na tũvila twa kũlũmanĩthw’a iĩndĩnĩ syatw’o, evotinĩ na kakalonĩ ka kĩthũi.'),
('kam', 'EXO', 35, 10, 'Na kĩla mũndũ wĩ na ngoo yĩ na ũĩ katĩ wenyu nĩoke, na kũseũvya syonthe ila Yeova wĩaĩte:'),
('kam', 'EXO', 35, 11, 'ũla wĩkalo, na ĩeema yaw’o, na kĩla kyaw’o kya kũvw’ĩka, na tũvoloi twaw’o, na mbwaũ syaw’o, na mĩamba yaw’o, na ituĩ syaw’o, na iĩndĩ syaw’o;'),
('kam', 'EXO', 35, 12, 'na yĩla ĩsandũkũ, na mĩtĩ yayo, na ũla wĩkalo wa tei, na ũla tũtũ wa kũtilan’ya;'),
('kam', 'EXO', 35, 13, 'na ĩla mesa, na mĩtĩ yayo, na mĩio yayo yonthe, na ila imũtũ sya kwiĩawa Yeova;'),
('kam', 'EXO', 35, 14, 'na kĩla kĩndũ kĩkĩawa mataa nakyo kwondũ wa kũmulĩka, na mĩio yakyo, na mataa makyo, na ala mauta ma kwakan’ya taa;'),
('kam', 'EXO', 35, 15, 'na kĩla kĩthembeo kya kũtoeeasya ũvani, na mĩtĩ yakyo, na ala mauta ma kwĩtĩkĩsya, na ũla ũvani ũnyungaa nesa, na ũla tama wa mũomonĩ, o mũomonĩ wa wĩkalo;'),
('kam', 'EXO', 35, 16, 'na kila kĩthembeo kya nthembo ya kũvĩvw’a, vamwe na ũla seng’eng’e wakyo wa ũthuku, na mĩtĩ yakyo, na mĩio yakyo yonthe, na kĩla kĩndũ kya kũthambĩaa na ĩtina yakyo;'),
('kam', 'EXO', 35, 17, 'na ila ngũa sya kũniinw’a sya nza, na ituĩ syasyo, na iĩndĩ syasyo, na ũla tama wa mbingĩlonĩ ya nza;'),
('kam', 'EXO', 35, 18, 'na ila syambo sya wĩkalo, na ila syambo sya nza, na makanda masyo;'),
('kam', 'EXO', 35, 19, 'na ila ngũa ndume nesa kwondũ wa kũthũkũmĩa vala vandũ vatheu, ngũa ila ntheu sya mũthembi Aluni, na ngũa sya ana make, sya kũthũkũmĩa wĩanĩ wa ũthembi.'),
('kam', 'EXO', 35, 20, 'Na ũmbano w’onthe wa ana ma Isilaeli wauma vala Mose ũĩ.'),
('kam', 'EXO', 35, 21, 'Na mooka kĩla ũmwe ũla ngoo yake yamũthangaasya, na kĩla ũmwe ũla veva wake watumaa enda, na maete nthembo ya Yeova, kwondũ wa wĩa wa ĩeema ya kũmbanĩa, na kwondũ wa ũthũkũmi w’onthe wayo, na kwondũ wa ila ngũa ntheu.'),
('kam', 'EXO', 35, 22, 'Na mooka, aũme o na aka, o ala maĩ na ngoo ya kwenda, na maete mavĩnĩ, na ngome sya matũ, na ngome sya ũvana ũsiĩlo, na itang’a, mĩio yonthe ya wanake ya thaavu; o kĩla mũndũ ũla waumĩsye Yeova nthembo ya thaavu.'),
('kam', 'EXO', 35, 23, 'Na kĩla mũndũ ũla wonekie e na langi wa vuluu, na ũla ũtilyĩ ta mũtune, na ũla mũtune mũno, na katane nzeo, na maw’ĩa ma mbũi, na mbũa sya ndũũme syĩkĩtwe langi mũtune, na mbũa sya vomboo, aete.'),
('kam', 'EXO', 35, 24, 'Kĩla ũmwe ũla waumisye nthembo ya vetha na ya ũthuku aetee Yeova nthembo; na kĩla mũndũ, ũla wonekie e na mĩtĩ ya mũea ũndũ wa wĩa o na wĩva wa ũla ũthũkũmi, aete.'),
('kam', 'EXO', 35, 25, 'Na aka onthe ala maĩ na ngoo syĩ na ũĩ mokothaa na moko moo, na makĩete kĩla mokothie, ila ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo.'),
('kam', 'EXO', 35, 26, 'Na aka onthe ala ngoo syoo syamathangaasya methĩwe oĩ mokothaa maw’ĩa ma mbũi.'),
('kam', 'EXO', 35, 27, 'Na asumbĩki maete tũla tũvila twa nzumalati, na tũvila twa kũlũmanĩthw’a iĩndĩnĩ syatw’o, evotinĩ, na kakalonĩ ka kĩthũi;'),
('kam', 'EXO', 35, 28, 'na ĩla mĩtĩ ĩnyungaa nesa, na ala mauta; kwondũ wa kwakan’ya taa, na kwondũ wa mauta ma kwĩtĩkĩsya, na kwondũ wa ũvani ũla ũnyungaa nesa.'),
('kam', 'EXO', 35, 29, 'Ana ma Isilaeli manũetee Yeova nthembo na ngoo ya kwenda; o kĩla mũndũ mũũme na mũndũ mũka, ũla ngoo yake yaĩ na kwenda kwa kũete kwondũ wa wĩa ũsu w’onthe, ũla Yeova weaĩte wĩkwe nĩ Mose.'),
('kam', 'EXO', 35, 30, 'Na Mose amea ana ma Isilaeli, Sisya, Yeova nũmũwetete na syĩtwa yake Mbesaleli, mwana wa Ulĩ, mwana wa Uulu, wa mbaĩ ya Yuta;'),
('kam', 'EXO', 35, 31, 'na amusũĩtye Veva wa Ngai, ũĩnĩ, na ũmanyinĩ, na ũmanyĩsyonĩ, na wĩanĩ wa mĩthemba yonthe;'),
('kam', 'EXO', 35, 32, 'kũmantha kwĩka mawĩa ma ũĩ, nĩ kana aseũvye thaavu, na vetha, na ũthuku,'),
('kam', 'EXO', 35, 33, 'na kwasũvya tũvila twa kwĩkĩwa nthĩnĩ wa syĩndũ, na kwasũvya mbwaũ, o na kũthethya mawĩa ma ũĩ ma mĩthemba yonthe.'),
('kam', 'EXO', 35, 34, 'Na nĩwĩkĩĩte ngoonĩ yake nĩ kana amanyĩsye, we, o na Ooliavu, mwana wa Aisamaki, wa mbaĩ ya Ndani.'),
('kam', 'EXO', 35, 35, 'Asu amausũĩtye ũĩ wa ngoo, wa kũtethya wĩa wa mĩthemba yonthe, wa mũvani, na wa mũtethya wa wĩa ũla mũĩ, na wa mũtumi mũĩ wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo, na wa mũtumi wa ngũa, o asu matethasya wĩa wa mũthemba o na wĩva, na wa ala mamanthaa kwĩka mawĩa ma ũĩ.'),
('kam', 'EXO', 36, 1, 'Na Mbesaleli na Ooliavu makatethye wĩa, na kĩla mũndũ wĩ na ũĩ ngoonĩ, ũla Yeova wĩkĩĩte ũĩ na ũmanyi amanye kũtethya wĩa w’onthe wa ũthũkũmi wa vala vandũ vatheu, o kwĩanana na onthe ala Yeova wĩaĩte.'),
('kam', 'EXO', 36, 2, 'Na Mose eeta Mbesaleli na Ooliavu, na kĩla mũndũ wĩ na ũĩ ngoonĩ, ũla ngoonĩ yake Yeova wekĩĩte ũĩ, o kĩla ũmwe ũla ngoo yake yamũthangaaĩtye oke wĩanĩ otethye:'),
('kam', 'EXO', 36, 3, 'na moosa mokonĩ ma Mose nthembo yonthe ĩla ana ma Isilaeli maetete ũndũ wa wĩa wa ũthũkũmi wa vala vandũ vatheu, moseũvye. Na ĩngĩ, mamũetee kĩla kĩoko nthembo sya kwenda kwa ngoo.'),
('kam', 'EXO', 36, 4, 'Na andũ oĩ onthe, ala matethisye wĩa w’onthe wa vala vandũ vatheu, mauma kĩla mũndũ wĩanĩ wake ũla watethasya;'),
('kam', 'EXO', 36, 5, 'na maneena na Mose, makĩmwĩa, Andũ nĩmeũete nyingĩ mũno kũvĩtũka vata wa ũthũkũmi wa wĩa ũla Yeova weaĩte ũtethw’e.'),
('kam', 'EXO', 36, 6, 'Na Mose aumya mwĩao, na matuma ũtavanw’a mwakonĩ wa maeema w’onthe, makyasya, Mũndũ mũũme o na mũndũ mũka ndakatethye wĩa ũngĩ kwondũ wa nthembo ya vala vandũ vatheu. Na ĩndĩ andũ masiĩĩwa matikaete.'),
('kam', 'EXO', 36, 7, 'Nũndũ syĩndũ ila maĩ nasyo mĩsyeanĩe kũtethya wĩa ũsu w’onthe, o na kũthonoka.'),
('kam', 'EXO', 36, 8, 'Na andũ onthe me na ũĩ ngoonĩ ma ala matethasya wĩa maseũvĩsya ũla wĩkalo masuka ĩkũmi: Mbesaleli amaseũvya ma ndii sya katane nzeo mbokothe, na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, amatumĩĩa ngelekan’yo ya akeluvi, wĩa wa mũtethya wa wĩa ũla mũĩ.'),
('kam', 'EXO', 36, 9, 'Ũasa wa kĩla suka waĩ mĩkono mĩongo ĩlĩ na nyanya, na ũthanthau wa kĩla suka mĩkono ĩna: masuka onthe nĩmathimĩtwe ũndũ ũmwe.'),
('kam', 'EXO', 36, 10, 'Na akwatan’ya masuka atano ũmwe na ũla ũngĩ: na masuka ala angĩ atano akwatan’ya ũmwe na ũla ũngĩ.'),
('kam', 'EXO', 36, 11, 'Na aseũvya ikwatũ sya vuluu ũteenĩ wa suka ũmwe ũtiivonĩ vala makwatanĩlw’e: na aseũvya o ta ũu ũteenĩ wa suka ũla wĩ mũminũkĩlyo wa vala vakwatanĩlw’e va kelĩ.'),
('kam', 'EXO', 36, 12, 'Aseũvya ikwatũ mĩongo ĩtano sukanĩ ũmwe, na aseũvya ikwatũ mĩongo ĩtano ũteenĩ wa suka ũla waĩ vala vakwatanilw’e va kelĩ: kĩkwatũ kĩmwe kyelekele kĩla kĩngĩ.'),
('kam', 'EXO', 36, 13, 'Na aseũvya tũvoloi mĩongo ĩtano twa thaavu, na akwatan’ya masuka, ũmwe na ũla ũngĩ, na tũvoloi tũu: na ĩndĩ ũla wĩkalo watw’ĩka ũmwe.'),
('kam', 'EXO', 36, 14, 'Na aseũvya masuka ma maw’ĩa ma mbũi matw’ĩke ĩeema ĩũlũ wa wĩkalo ũsu: amaseũvya masuka asu ĩkũmi na ũmwe.'),
('kam', 'EXO', 36, 15, 'Ũasa wa kĩla suka waĩ mĩkono mĩongo ĩtatũ, na ũthanthau wa kĩla suka mĩkono ĩna: masuka asu ĩkũmi na ũmwe nĩmathimĩtwe ũndũ ũmwe.'),
('kam', 'EXO', 36, 16, 'Na akwatan’ya masuka atano me oka, na masuka thanthatũ me oka.'),
('kam', 'EXO', 36, 17, 'Na aseũvya ikwatũ mĩongo ĩtano ũteenĩ wa suka ũla waĩ mũminũkĩlyo wa vala vakwatanĩlw’e, na aseũvya ikwatũ mĩongo ĩtano ũteenĩ wa suka ũla waĩ mũminũkĩlyo wa vala vakwatanĩlw’e va kelĩ.'),
('kam', 'EXO', 36, 18, 'Na aseũvya tũvoloi mĩongo ĩtano twa ũthuku twa kũkwatan’ya ĩeema yĩthĩwe yĩmwe.'),
('kam', 'EXO', 36, 19, 'Na aseũvya kĩla kya kũvw’ĩka ĩeema kya mbũa sya ndũũme syĩkĩtwe langi mũtune, na ĩũlũ wakyo kĩngĩ kya mbũa sya vomboo.'),
('kam', 'EXO', 36, 20, 'Na aseũvya mbwaũ sya wĩkalo sya mĩtĩ ya mũea, iũngamĩtw’e.'),
('kam', 'EXO', 36, 21, 'Ũasa wa ũvwaũ waĩ mĩkono ĩkũmi, na ũthanthau wa kĩla ũvwaũ mũkono na nyunzu.'),
('kam', 'EXO', 36, 22, 'Kĩla ũvwaũ waĩ na isinĩko ilĩ isinĩkanĩtw’e: eekie ũu ũndũ wa mbwaũ syonthe sya wĩkalo.'),
('kam', 'EXO', 36, 23, 'Na aseũvya mbwaũ sya wĩkalo: mbwaũ mĩongo ĩlĩ kwondũ wa ngalĩ ya ĩtheo kwelekela ĩtheo;'),
('kam', 'EXO', 36, 24, 'na aseũvya iĩndĩ mĩongo ĩna sya vetha ungu wa ila mbwaũ mĩongo ĩlĩ; iĩndĩ ilĩ ungu wa ũvwaũ ũmwe ũndũ wa isinĩko syaw’o ilĩ, na iĩndĩ ilĩ ungu wa ũvwaũ ũngĩ ũndũ wa isinĩko syaw’o ilĩ.'),
('kam', 'EXO', 36, 25, 'Na ũndũ wa ngalĩ ya kelĩ ya wĩkalo, ngalĩ ya ĩũlũ, aseũvya mbwaũ mĩongo ĩlĩ,'),
('kam', 'EXO', 36, 26, 'na iĩndĩ syasyo mĩongo ĩna; iĩndĩ ilĩ ungu wa ũvwaũ ũmwe, na iĩndĩ ilĩ ungu wa ũvwaũ ũngĩ.'),
('kam', 'EXO', 36, 27, 'Na ũndũ wa ngalĩ ya mbĩlĩlo wa wĩkalo kwelekela ũthũĩlonĩ wa syũa aseũvya mbwaũ thanthatũ.'),
('kam', 'EXO', 36, 28, 'Na aseũvya mbwaũ ilĩ ũndũ wa ikoto sya wĩkalo ngalĩ ya mbĩlĩlo.'),
('kam', 'EXO', 36, 29, 'Na syeethĩwa ikwatene kuma nthĩ; na syeethĩwa ikwatene o ta ũu kũvika mũthya wĩ ĩũlũ wasyo kũvika ngomenĩ ĩmwe: asyĩka isu syelĩ ta ũu ikotonĩ syelĩ.'),
('kam', 'EXO', 36, 30, 'Na kwaĩ mbwaũ nyanya, na iĩndĩ syasyo sya vetha, iĩndĩ ĩkũmi na thanthatũ; ungu wa kĩla ũvwaũ iĩndĩ ilĩ.'),
('kam', 'EXO', 36, 31, 'Na aseũvya mĩamba ya mĩtĩ ya mũea; ĩtano ũndũ wa mbwaũ sya ngalĩ ĩmwe ya wĩkalo,'),
('kam', 'EXO', 36, 32, 'na mĩamba ĩtano ũndũ wa mbwaũ sya ngalĩ ĩla ĩngĩ ya wĩkalo, na mĩamba ĩtano ũndũ wa mbwaũ sya wĩkalo sya ngalĩ ya mbĩlĩlo kwelekela ũthũĩlonĩ wa syũa.'),
('kam', 'EXO', 36, 33, 'Na aseũvya mũamba ũla wĩ katĩ ũvĩtĩle mbwaũnĩ katĩ kuma mũthya ũmwe kũvika ũla ũngĩ.'),
('kam', 'EXO', 36, 34, 'Na avw’ĩka mbwaũ thaavu, na atua ngome syasyo sya thaavu syĩthĩwe sya kwĩkĩa mĩamba, na akĩvw’ĩka mĩamba thaavu.'),
('kam', 'EXO', 36, 35, 'Na aseũvya ũla tũtũ na ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe: ootumĩĩa ngelekan’yo ya akeluvi, wĩa wa mũtethya wa wĩa ũla mũĩ.'),
('kam', 'EXO', 36, 36, 'Na ooseũvĩsya ituĩ inya sya mĩtĩ ya mũea, na aivw’ĩka thaavu: syambo syasyo syaĩ sya thaavu; na aitũĩsya iĩndĩ inya sya vetha.'),
('kam', 'EXO', 36, 37, 'Na ooseũvĩsya mũomo wa Ĩeema tama na ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe, wĩa wa mũtumi mũĩ wa ndii;'),
('kam', 'EXO', 36, 38, 'na ituĩ itano syaw’o vamwe na syambo syasyo; na avw’ĩka ngovia syasyo na mĩkunzu yasyo thaavu; na iĩndĩ syasyo itano syaĩ sya ũthuku.'),
('kam', 'EXO', 37, 1, 'Na Mbesaleli aseũvya yĩla ĩsandũkũ ya mĩtĩ ya mũea: ũasa wayo waĩ mĩkono ĩlĩ na nyunzu, na ũthanthau wayo mũkono na nyunzu, na ũtũlu wayo mũkono na nyunzu.'),
('kam', 'EXO', 37, 2, 'Na ayĩvw’ĩka nthĩnĩ na ũtee thaavu mũtheu, na ayĩseũvĩsya ũengo mũtũlu wa thaavu ũyĩlingĩle.'),
('kam', 'EXO', 37, 3, 'Na ayĩtũĩsya ngome inya sya thaavu, maũũnĩ mayo ana; o ngome ilĩ ngalĩ ĩmwe yayo, na ngome ilĩ ngalĩ ĩla ĩngĩ yayo.'),
('kam', 'EXO', 37, 4, 'Na aseũvya mĩtĩ ya mũea, na amĩvw’ĩka thaavu.'),
('kam', 'EXO', 37, 5, 'Na eekĩa ĩla mĩtĩ ngomenĩ syĩ mavavanĩ ma yĩla ĩsandũkũ, ya ũkua yĩ ĩsandũkũ.'),
('kam', 'EXO', 37, 6, 'Na aseũvya wĩkalo wa tei wa thaavu mũtheu: ũasa waw’o waĩ mĩkono ĩlĩ na nyunzu, na ũthanthau waw’o mũkono na nyunzu.'),
('kam', 'EXO', 37, 7, 'Na aseũvya akeluvi elĩ ma thaavu; amaseũvya na kũmatua, ngalĩ syelĩ sya wĩkalo wa tei;'),
('kam', 'EXO', 37, 8, 'mũkeluvi ũmwe ngalĩ ĩmwe, na mũkeluvi ũmwe ngalĩ ĩla ĩngĩ: amaseũvya o kĩlungunĩ kĩmwe na ũla wĩkalo wa tei ngalĩ syelĩ syaw’o.'),
('kam', 'EXO', 37, 9, 'Na ala akeluvi matambũũkya nthwau syoo ĩũlũ, makĩvw’ĩka wĩkalo wa tei na nthwau syoo, mothyũ moo masianĩtye; mothyũ ma akeluvi melekele wĩkalo wa tei.'),
('kam', 'EXO', 37, 10, 'Na aseũvya ĩla mesa ya mĩtĩ ya mũea: ũasa wayo waĩ mĩkono ĩlĩ, na ũthanthau wayo mũkono, na ũtũlu wayo mũkono na nyunzu.'),
('kam', 'EXO', 37, 11, 'Na amĩvw’ĩka thaavu mũtheu; na amĩseũvĩsya ũengo mũtũlu wa thaavu ũmĩlingĩle.'),
('kam', 'EXO', 37, 12, 'Na amĩseũvĩsya ũengo ũmĩlingĩle; ũthanthau waw’o ta wa kĩtaa kya kw’oko, na aseũvya ũengo mũtũlu wa thaavu ũengonĩ wayo ũmĩlingĩle.'),
('kam', 'EXO', 37, 13, 'Na amĩtuĩsya ngome inya sya thaavu, na eekĩa ila ngome mĩthyanĩ ĩna ya ĩũlũ ĩla yaĩ maũũnĩ mayo ana.'),
('kam', 'EXO', 37, 14, 'Ila ngome syaĩ vakuvĩ na ũla ũengo, syĩthĩwe kũndũ kwa kwĩkĩa ĩla mĩtĩ ya kũkua mesa.'),
('kam', 'EXO', 37, 15, 'Na aseũvya ĩla mĩtĩ ya mũea ya ũkua mesa, na aimĩvw’ĩka thaavu.'),
('kam', 'EXO', 37, 16, 'Na aseũvya ĩla mĩio ya kwĩkĩa mesanĩ, masaani mayo, na syĩko syayo, na mbakũli syayo, na ikombe syayo, ila sya kwĩtĩkĩasya, sya thaavu mũtheu.'),
('kam', 'EXO', 37, 17, 'Na aseũvya kĩla kĩndũ kĩkĩawa mataa kya thaavu mũtheu: aseũvya kĩla kĩndũ kĩkĩawa mataa na kũtua, o ĩtina yakyo, na mũtĩ wakyo; ikombe syakyo, na mĩkauti yakyo, na malaa makyo syeethĩwa sya kĩlungu kĩmwe nakyo.'),
('kam', 'EXO', 37, 18, 'Na kwaĩ mbonge thanthatũ syumĩte ndeenĩ syakyo; mbonge itatũ sya kĩla kĩndũ kĩkĩawa mataa kuma ngalĩ ĩmwe yakyo, na mbonge itatũ sya kĩla kĩndũ kĩkĩawa mataa kuma ngalĩ ĩla ĩngĩ yakyo:'),
('kam', 'EXO', 37, 19, 'ikombe itatũ iseũvĩtw’e ta malaa ma mũlosi ũvongenĩ ũmwe, mũkauti na ĩlaa; na ikombe itatũ iseũvĩtw’e ta malaa ma mũlosi ũvongenĩ ũla ũngĩ, mũkauti na ĩlaa: mbongenĩ isu thanthatũ syumite o ta ũu kĩla kĩndũnĩ kĩkĩawa mataa.'),
('kam', 'EXO', 37, 20, 'Na kĩndũnĩ kĩla kĩkĩawa mataa kwaĩ ikombe inya iseũvĩtw’e ta malaa ma mũlosi, mĩkauti yakyo, na malaa makyo:'),
('kam', 'EXO', 37, 21, 'na mũkauti weethĩwa ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, na mũkauti ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, na mũkauti ĩtheo wa mbonge ilĩ kĩlungunĩ kĩmwe nakyo, kwa ila mbonge thanthatũ syumĩte nthĩnĩ wakyo.'),
('kam', 'EXO', 37, 22, 'Mĩkauti yakyo na mbonge syakyo syeethĩwa sya kĩlungu kĩmwe nakyo: kĩndũ kyu kĩima kyaĩ kya thaavu mũtheu ũla mũtue.'),
('kam', 'EXO', 37, 23, 'Na aseũvya mataa makyo, mũonza, na mĩkasi yakyo, na masaani ma makaa makyo, sya thaavu mũtheu.'),
('kam', 'EXO', 37, 24, 'Akĩseũvya kya talendi ya thaavu mũtheu, vamwe na mĩio yonthe yakyo.'),
('kam', 'EXO', 37, 25, 'Na aseũvya kĩla kĩthembeo kya kũtoeeasya ũvani kya mĩtĩ ya mũea: ũasa wakyo waĩ mũkono, na ũthanthau wakyo mũkono, ngalĩ inya syĩanene; na ũtũlu wakyo waĩ mĩkono ĩlĩ; mbya syakyo syaĩ sya kĩlungu kĩmwe nakyo.'),
('kam', 'EXO', 37, 26, 'Na akĩvw’ĩka thaavu mũtheu, ĩũlũ wakyo, na mavava makyo onthe, na mbya syakyo: na akĩseũvĩsya ũengo mũtũlu wa thaavu ũkĩlingĩle.'),
('kam', 'EXO', 37, 27, 'Na akĩtuĩsya ngome ilĩ sya thaavu ungu wa ũengo mũtũlu wakyo, ikotonĩ ilĩ syakyo, ngalĩ syelĩ syakyo, syĩthĩwe kũndũ kwa kũtonyesya ĩla mĩtĩ ya kũkĩkua.'),
('kam', 'EXO', 37, 28, 'Na aseũvya ĩla mĩtĩ ya mũea, na amĩvw’ĩka thaavu.'),
('kam', 'EXO', 37, 29, 'Na aseũvya ala mauta matheu ma kwĩtĩkĩsya, na ũla ũvani mũtheu wa mĩtĩ ĩla ĩnyungaa nesa, kwĩanana na ũĩ wa mũseũvya wa manukato.'),
('kam', 'EXO', 38, 1, 'Na aseũvya kĩla kĩthembeo kya nthembo ya kũvĩvw’a kya mĩtĩ ya mũea: ũasa wakyo waĩ mĩkono ĩtano, na ũthanthau wakyo mĩkono ĩtano, ngalĩ inya syĩanene; na ũtũlu wakyo mĩkono ĩtatũ.'),
('kam', 'EXO', 38, 2, 'Na aseũvya mbya syakyo ĩũlũ wa ikoto inya syakyo; mbya syakyo syaĩ sya kĩlungu kĩmwe nakyo: na akĩvw’ĩka ũthuku.'),
('kam', 'EXO', 38, 3, 'Na aseũvya mĩio yonthe ya kĩla kĩthembeo, ĩla mĩio ya kwokaa mũu, na ĩla mĩko, na ala masaani manene, na ila itonyi sya nyama, na tũla tũvũngũlyũ twa ũkua makaa: mĩio yonthe yakyo aseũvya ya ũthuku.'),
('kam', 'EXO', 38, 4, 'Na aseũvĩsya kĩla kĩthembeo seng’eng’e wa ũthuku, ĩtheo wa ũengo ũla wĩkĩlingĩlĩte ngalĩko ya ungu, ũkĩambata ũvike kĩthembeonĩ katĩ.'),
('kam', 'EXO', 38, 5, 'Na atua ngome inya ũndũ wa mĩthya ĩna ya ũla seng’eng’e wa ũthuku, syĩthĩwe kũndũ kwa kũtonyeesya ĩla mĩtĩ.'),
('kam', 'EXO', 38, 6, 'Na aseũvya ĩla mĩtĩ ya mũea, na amĩvw’ĩka ũthuku.'),
('kam', 'EXO', 38, 7, 'Na eekĩa ĩla mĩtĩ ngomenĩ syĩ mavavanĩ ma kĩthembeo, yĩthĩwe ya ũkĩkua; akĩseũvya na mbwaũ kĩ na ĩima nthĩnĩ katĩ.'),
('kam', 'EXO', 38, 8, 'Na aseũvya kĩla kĩndũ kya kũthambĩaa kya ũthuku, na ĩtina yakyo ya ũthuku, wa isisyo sya aka athũkũmi ala mathũkũmĩaa mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'EXO', 38, 9, 'Na aseũvya ĩla nza: ngalĩ ya ĩtheo kwelekela ĩtheo ngũa ila sya kũniinw’a sya nza syaĩ sya katane nzeo mbokothe, ũasa wasyo mĩkono ĩana;'),
('kam', 'EXO', 38, 10, 'ituĩ syasyo syaĩ mĩongo ĩlĩ, na iĩndĩ syasyo mĩongo ĩlĩ, sya ũthuku; syambo sya ituĩ isu na mĩkunzu yasyo syaĩ sya vetha.'),
('kam', 'EXO', 38, 11, 'Na ngalĩ ya ĩũlũ, ũasa wasyo mĩkono ĩana, ituĩ syasyo mĩongo ĩlĩ, na iĩndĩ syasyo mĩongo ĩlĩ, sya ũthuku; syambo sya ituĩ, na mĩkunzu yasyo, syaĩ sya vetha.'),
('kam', 'EXO', 38, 12, 'Na ngalĩ ya ũthũĩlonĩ wa syũa kwaĩ ngũa sya kũniinw’a, ũasa wasyo mĩkono mĩongo ĩtano, ituĩ syasyo ĩkũmi, na iĩndĩ syasyo ĩkũmi; syambo sya ituĩ, na mĩkunzu yasyo, syaĩ sya vetha.'),
('kam', 'EXO', 38, 13, 'Na ngalĩ ya wumĩlonĩ wa syũa kwelekela wumĩlonĩ wa syũa syaĩ sya mĩkono mĩongo ĩtano.'),
('kam', 'EXO', 38, 14, 'Ngũa ila sya kũniinw’a sya ngalĩ ĩmwe ya mbingĩlo syaĩ sya mĩkono ĩkũmi na ĩtano; ituĩ syasyo itatũ, na iĩndĩ syasyo itatũ;'),
('kam', 'EXO', 38, 15, 'na no ta ũu ũndũ wa ngalĩ ĩla ĩngĩ: kw’oko kũũ na kw’oko kũla kũngĩ ũtee wa mbingĩlo ya ĩla nza kwaĩ ngũa sya kũniinw’a, ũasa wasyo mĩkono ĩkũmi na ĩtano; ituĩ syasyo itatũ, na iĩndĩ syasyo itatũ.'),
('kam', 'EXO', 38, 16, 'Ngũa syonthe sya kũniinw’a sya kwĩlingĩla nza syaĩ sya katane nzeo mbokothe.'),
('kam', 'EXO', 38, 17, 'Na iĩndĩ sya ituĩ syaĩ sya ũthuku; ila syambo sya ituĩ, na mĩkunzu yasyo, syaĩ sya vetha; na kĩla kyavw’ĩkĩte ngovia syasyo, kyaĩ kya vetha; na ituĩ syonthe sya ĩla nza syakwatanw’a na mũkunzu wa vetha.'),
('kam', 'EXO', 38, 18, 'Na ũla tama wa mbingĩlonĩ ya nza waĩ wĩa wa mũtumi mũĩ wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe: ũasa waw’o waĩ mĩkono mĩongo ĩlĩ, na ũtũlu waw’o, now’o ũthanthau waw’o, waĩ mĩkono ĩtano, o ta ila ngũa sya kũniinw’a sya nza.'),
('kam', 'EXO', 38, 19, 'Na ituĩ syasyo syaĩ inya, na iĩndĩ syasyo inya, sya ũthuku; syambo syasyo syaĩ sya vetha, na kĩla kyavw’ĩkĩte ngovia syasyo, na mĩkunzu yasyo, syaĩ sya vetha.'),
('kam', 'EXO', 38, 20, 'Na syambo syonthe sya ũ wĩkalo, na ila sya nza syĩlingĩlĩte, syaĩ sya ũthuku.'),
('kam', 'EXO', 38, 21, 'Ũsu nĩw’o ũtalo wa isamũ sya wĩkalo, o wĩkalo ũsu wa ũkũsĩ, o ũndũ syatalilwe, kwĩanana na mwĩao wa Mose, ũndũ wa ũthũkũmi wa Alivai, nĩ Ithamali, mwana wa mũthembi Aluni.'),
('kam', 'EXO', 38, 22, 'Na Mbesaleli, mwana wa Ulĩ, mwana wa Uulu, wa mbaĩ va Yuta, aseũvya syonthe ila Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 38, 23, 'Na vamwe nake kwaĩ Ooliavu, mwana wa Aisamaki, wa mbaĩ ya Ndani, mũvani, na mũtethya wa wĩa ũla mũĩ, na mũtumi mũĩ wa ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo.'),
('kam', 'EXO', 38, 24, 'Thaavu w’onthe ũla waumiw’e kwondũ wa wĩa ũsu wĩanĩ w’onthe wa vala vandũ vatheu, o thaavu ũsu waumiw’e wa nthembo, waĩ wa telendi mĩongo ĩlĩ na kenda, na sekeli maana mũonza na mĩongo ĩtatũ, kwĩanana na sekeli ya vala vandũ vatheu.'),
('kam', 'EXO', 38, 25, 'Na vetha wa asu matalilwe ma ũmbano waĩ talendi ĩana, na sekeli ngili ĩmwe na maana mũonza na mĩongo mũonza na itano, kwĩanana na sekeli ya vala vandũ vatheu:'),
('kam', 'EXO', 38, 26, 'veka o kĩla mũndũ, nĩyo nyunzu ya sekeli, kwĩanana na sekeli ya vala vandũ vatheu, kwondũ wa kĩla ũmwe ũla wavĩtũkie e mũtale athi kwa asu atale, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, kwondũ wa andũ ngili maana thanthatũ na itatũ na maana atano na mĩongo ĩtano.'),
('kam', 'EXO', 38, 27, 'Na talendi isu ĩana sya vetha syaĩ kwondũ wa kũtua iĩndĩ sya vala vandũ vatheu, na iĩndĩ isu sya ũla tũtũ; iĩndĩ ĩana kuma ila talendi ĩana, talendi ĩmwe kwondũ wa kĩla kĩĩndĩ.'),
('kam', 'EXO', 38, 28, 'Na aseũvya syambo sya ituĩ isu kuma ila sekeli ngili ĩmwe na maana mũonza na mĩongo mũonza na itano, na avw’ĩka ila ngovia syasyo, na aseũvya mĩkunzu ũndũ wasyo.'),
('kam', 'EXO', 38, 29, 'Na ũthuku wa ĩla nthembo waĩ wa talendi mĩongo mũonza, na sekeli ngili ilĩ na maana ana.'),
('kam', 'EXO', 38, 30, 'Na aseũvya iĩndĩ o w’o sya mũomo wa yĩla ĩeema ya kũmbanĩa, na kĩla kĩthembeo kya ũthuku, na ũla seng’eng’e wa ũthuku wakyo, na mĩio yonthe ya kĩthembeo kyu,'),
('kam', 'EXO', 38, 31, 'na iĩndĩ sya nza ĩthyũlũlũkĩte, na iĩndĩ sya mbingĩlonĩ ya nza, na syambo syonthe sya ũla wĩkalo, na syambo syonthe sya ĩla nza ĩthyũlũlũkĩte.'),
('kam', 'EXO', 39, 1, 'Na maseũvya ngũa ndume nesa mũno sya ila ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, ũndũ wa wĩa wa kũthũkũmĩaa vala vandũ vatheu, na maseũvya ila ngũa ntheu kwondũ wa Aluni; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 2, 'Na aseũvya yĩla evoti na ndii sya thaavu, na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe.'),
('kam', 'EXO', 39, 3, 'Nao mamanda thaavu ũsu wavũtha mũno, na mawatũanga watw’ĩka tũmĩkunzu, nĩ kana motuman’ye na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo, wĩa wa mũtethya wa wĩa ũla mũĩ.'),
('kam', 'EXO', 39, 4, 'Mayĩseũvĩsya ikwatũ sya ituonĩ, ikwatene: yaĩ ĩkwatan’ye mĩthyanĩ ĩlĩ yayo.'),
('kam', 'EXO', 39, 5, 'Na ũla mũsivi ũtũmĩtwe na ũĩ, ũla waĩ ĩũlũ wayo, ũla wa kũyova yĩlũme, waĩ wa kĩlungu kĩmwe nayo na ũtũmĩtwe ũndũ ũmwe nayo; wa ndii sya thaavu, na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 6, 'Na maseuvya tũla tũvila twa nzumalati, tũlũmanĩthw’e iĩndĩnĩ sya thaavu, mavanĩtwe na movano me ngomenĩ ya kũsiĩla, kwĩanana na masyĩtwa ma ana ma Isilaeli.'),
('kam', 'EXO', 39, 7, 'Na amekĩa ikwatũnĩ sya ituonĩ sya yĩla evoti, methĩwe tũvila twa ũlilikan’yo kwondũ wa ana ma Isilaeli; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 8, 'Na aseũvya kala kakalo ka kĩthũi, wĩa wa mũtethya wa wĩa ũla mũĩ, o ta wĩa wa yĩla evoti; ka ndii sya thaavu, na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane nzeo mbokothe.'),
('kam', 'EXO', 39, 9, 'Keethĩwa keanene ngalĩ inya; maseũvya kala kakalo ka kĩthũi makĩkatulanĩla: ũasa wako waĩ ĩkwata yĩmwe ya kĩtaa, na ũthanthau wako ĩkwata yĩmwe ya kĩtaa, ke katulanĩle.'),
('kam', 'EXO', 39, 10, 'Na meekĩa mĩsoa ĩna ya tũvila nthĩnĩ wako. Mũsoa wa mbee waĩ wa salitũ, na tovasi, na alimasi ndune;'),
('kam', 'EXO', 39, 11, 'na mũsoa wa kelĩ, sumalati, na savili, na salitonyi;'),
('kam', 'EXO', 39, 12, 'na mũsoa wa katatũ, samawi, na yasimu, na amethusito;'),
('kam', 'EXO', 39, 13, 'na mũsoa wa kana, nzumalati ntheu, na nzumalati, na yasivi: tũlũmanĩthw’a na thaavu iĩndĩnĩ syatw’o.'),
('kam', 'EXO', 39, 14, 'Na tũvila tũu twaĩ kwĩanana na masyĩtwa ma ana ma Isilaeli, ĩkũmi na elĩ, o kwĩanana na masyĩtwa moo; ta movano me ngomenĩ ya kũsiĩla, kĩla mũndũ kwĩanana na syĩtwa yake, kwondũ wa ila mbaĩ ĩkũmi na ilĩ.'),
('kam', 'EXO', 39, 15, 'Na maseũvya mĩnyoo ĩtilyĩ tũkanda kakalonĩ ka kĩthũi ĩũlũ, ya thaavu mũtheu wĩ mũvĩnde.'),
('kam', 'EXO', 39, 16, 'Na maseũvya iĩndĩ ilĩ sya thaavu, na ngome ilĩ sya thaavu, na meekĩa ngome isu ilĩ mĩthyanĩ ilĩ ya kala kakalo ka kĩthũi.'),
('kam', 'EXO', 39, 17, 'Na meekĩa minyoo ĩsu ĩlĩ mĩvĩnde ya thaavu nthĩnĩ wa ngome ilĩ mĩthyanĩ ya kakalo ka kĩthũi.'),
('kam', 'EXO', 39, 18, 'Na mĩthya ĩla ĩngĩ ĩlĩ ya mĩnyoo ĩsu ĩlĩ mĩvĩnde meekĩa ĩĩndĩnĩ isu ilĩ, na mamĩkolelya ila ikwatũnĩ isu sya ituonĩ sya evoti, ngalĩ ya mbee yayo.'),
('kam', 'EXO', 39, 19, 'Na matua ngome ilĩ sya thaavu, na makolelya mĩthyanĩ ĩlĩ ya kakalo ka kĩthũi, ũteenĩ wako, ũla welekele ngalĩ ya nthĩnĩ ya evoti.'),
('kam', 'EXO', 39, 20, 'Na matua ngome ilĩ sya thaavu, na makolelya ikwatũnĩ isu ilĩ sya ituonĩ sya evoti ungu, ngali ya mbee yayo, vakuvĩ na vala vakwatanĩlw’e vayo ĩũlũ wa ũla mũsivi, wa evoti ũtumĩtwe na ũĩ.'),
('kam', 'EXO', 39, 21, 'Na malũman’ya kakalo ka kĩthũi na ngome syako ngomenĩ sya evoti na ũlii wa vuluu, nĩ kana kethĩwe ĩũlũ wa ũla mũsivi wa evoti ũtumĩtwe na ũĩ, na nĩ kana kakalo ka kĩthũi kaikathaw’e yĩla evotinĩ; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 22, 'Na aseũvya ĩla ngũa ndasa ya evoti ya ngũa ndume, yonthe ya vuluu;'),
('kam', 'EXO', 39, 23, 'yi na ĩima ya kũlikya mũtwe ya ĩla ngũa ndasa nthĩnĩ wayo katĩ, yĩilyĩ ĩima yĩkĩwe kakotinĩ ka kaũ, yĩ na ũtaami wĩlingĩle ĩimanĩ yayo, nĩ kana ndĩkatembũke.'),
('kam', 'EXO', 39, 24, 'Na motiivonĩ ma ĩla ngũa ndasa maseũvya makũngũmanga ma ndii sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, na katane mbokothe.'),
('kam', 'EXO', 39, 25, 'Na maseũvya tũtilili twa thaavu mũtheu, na meekĩa tũtilili tũu katĩ wa makũngũmanga motiivonĩ ma ĩla ngũa ndasa twĩlingĩlĩte, katĩ wa ala makũngũmanga;'),
('kam', 'EXO', 39, 26, 'o katilili na ĩkũngũmanga, katilili na ĩkũngũmanga, motiivonĩ ma ĩla ngũa ndasa twĩlingĩlĩte, kwondũ wa kũthũkũmaa ekĩe; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 27, 'Na maseũvĩsya Aluni, na ana make, ala makanzũ ma katane nzeo matume,'),
('kam', 'EXO', 39, 28, 'na ĩla ngutw’a ya katane nzeo, na tũla tũkovila twanakavye twa katane nzeo, na ala masulualĩ ma katane, katane nzeo mbokothe,'),
('kam', 'EXO', 39, 29, 'na ũla mũsivi wa ndii sya katane nzeo mbokothe, na ila sya vuluu, na ila itilyĩ ta ndune, na ila ndune mũno, o wĩa wa mũtumi mũĩ wa ndii; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 30, 'Na maseũvya kĩla kĩlaũnĩ kya ĩla ngovia ya ũsumbĩ ntheu kya thaavu mũtheu, na maandĩka ĩũlũ wakyo ũandĩko, ũilyĩ movano me ngomenĩ ya kũsiĩla, atĩĩ, MŨTHEU KWA YEOVA.'),
('kam', 'EXO', 39, 31, 'Na makyoveea ũlii wa vuluu, nĩ kana makĩlũman’ye na ngutw’a ĩũlũ wakyo; o tondũ Yeova weaĩe Mose.'),
('kam', 'EXO', 39, 32, 'Ũu nĩw’o wĩa w’onthe wa ũla wĩkalo wa ĩeema ya kũmbanĩa wathelile: na ana ma Isilaeli meeka kwĩanana na onthe ala Yeova weaĩe Mose; ũu nĩw’o meekie.'),
('kam', 'EXO', 39, 33, 'Na mamũetee Mose ũla wĩkalo, o yĩla Ĩeema, na mĩio yaw’o yonthe, tũvoloi twaw’o, na mbwaũ syaw’o, na mĩamba yaw’o, na ituĩ syaw’o, na iĩndĩ syaw’o;'),
('kam', 'EXO', 39, 34, 'na kĩla kya kũvw’ĩka ĩeema kya mbũa sya ndũũme syĩkĩtwe langi mũtune, na kĩla kĩngĩ kya ũvw’ĩka kya mbũa sya vomboo, na ũla tũtũ wa kũtilan’ya;'),
('kam', 'EXO', 39, 35, 'na yĩla ĩsandũkũ ya ũkũsĩ, na ĩla mĩtĩ yayo, na ũla wĩkalo wa tei;'),
('kam', 'EXO', 39, 36, 'na ĩla mesa, na mĩio yayo yonthe, na ila imũtũ sya kwiĩawa Yeova;'),
('kam', 'EXO', 39, 37, 'na kĩla kĩndũ kĩkĩawa mataa kĩtheu, na mataa makyo, o mataa ala maiawa vandũ vamo, na mĩio yakyo yonthe, na mauta ma kwakan’ya taa;'),
('kam', 'EXO', 39, 38, 'na kĩla kĩthembeo kya thaavu, na ala mauta ma kwĩtĩkĩsya, na ũla ũvani ũnyungaa nesa, na tama ũla wa mũomonĩ wa yĩla Ĩeema;'),
('kam', 'EXO', 39, 39, 'na kĩla kĩthembeo kya ũthuku, na seng’eng’e wakyo wa ũthuku, na mĩtĩ yakyo, na mĩio yakyo yonthe, na kĩla kĩndũ kya kũthambĩaa na ĩtina yakyo;'),
('kam', 'EXO', 39, 40, 'na ila ngũa sya kũniinw’a sya nza, na ituĩ syasyo, na iĩndĩ syasyo, na ũla tama wa mbingĩlonĩ ya nza, na makanda maw’o, na syambo syaw’o, na mĩio yonthe ya ũthũkũmi wa ũla wĩkalo, kwondũ wa yĩla ĩeema ya kũmbanĩa;'),
('kam', 'EXO', 39, 41, 'na ila ngũa ndume nesa kwondũ wa kũthũkũmĩaa vala vandũ vatheu, na ila ngũa ntheu sya mũthembi Aluni, na ngũa sya ana make, sya kũthũkũmaa wĩanĩ wa ũthembi.'),
('kam', 'EXO', 39, 42, 'O kwĩanana na onthe ala Yeova weaĩe Mose, ana ma Isilaeli matethisye wĩa w’onthe o ta ũu.'),
('kam', 'EXO', 39, 43, 'Na Mose oona wĩa ũsu w’onthe, na sisya, mawĩkĩte; o tondũ Yeova weaĩte, ũu nĩw’o mekĩte: na Mose amaathima.'),
('kam', 'EXO', 40, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'EXO', 40, 2, 'Mũthenya wa mbee wa mwei wa mbee ũkaũngamye ũla wĩkalo wa ĩeema ya kũmbanĩa.'),
('kam', 'EXO', 40, 3, 'Na ũkekĩe nthĩnĩ yĩla ĩsandũkũ ya ũkũsĩ, na ũkavw’ĩke ĩsandũkũ yĩu na ũla tũtũ.'),
('kam', 'EXO', 40, 4, 'Na ũkaete ĩla mesa nthĩnĩ, na kwia nesa syĩndũ ĩla sya ĩũlũ wayo; na ũkaete kĩla kĩndũ kĩkĩawa mataa, noikwatya mataa makyo.'),
('kam', 'EXO', 40, 5, 'Na ũkaie kĩla kĩthembeo kya thaavu kya kũtoeeasya ũvani ngalĩ ya mbee ya yĩla ĩsandũkũ ya ũkũsĩ, na kwikĩa tama ũla wa mũomonĩ wa ũ wĩkalo.'),
('kam', 'EXO', 40, 6, 'Na ũkaie kĩla kĩthembeo kya nthembo ya kũvĩvw’a ngalĩ ya mbee ya mũomo wa ũla wĩkalo wa ĩeema ya kũmbanĩa.'),
('kam', 'EXO', 40, 7, 'Na ũkaie kĩla kĩndũ kya kũthambĩaa katĩ wa yĩla ĩeema ya kũmbanĩa na kĩthembeo kyu, na kwĩkĩa manzĩ vo nthĩnĩ.'),
('kam', 'EXO', 40, 8, 'Na ũkaiie nza ũlingĩlĩte, na kwanĩka ũla tama wa mbingĩlo ya nza.'),
('kam', 'EXO', 40, 9, 'Na ũkose ala mauta ma kwĩtĩkĩsya, na ũiwĩtĩkĩsya ũ wĩkalo, na syonthe ila syĩ nthĩnĩ, na ũkovathan’ye wĩthĩwe mũtheu, na mĩio yonthe yaw’o; na ũkeethĩwa wĩ mũtheu.'),
('kam', 'EXO', 40, 10, 'Na ũketĩkĩsye kĩthembeo kya nthembo ya kũvĩvw’a mauta, na mĩio yonthe yakyo, na kũvathan’ya kĩla kĩthembeo kĩthĩwe kĩtheu: na kĩthembeo kĩkeethĩwa kĩtheu mũno vyũ.'),
('kam', 'EXO', 40, 11, 'Na ũketĩkĩsye kĩla kĩndũ kya kũthambĩaa na ĩtina yakyo mauta, na ũikĩvathan’ya kĩthĩwe kĩtheu.'),
('kam', 'EXO', 40, 12, 'Na ũkaete Aluni na ana make mũomonĩ wa ĩeema ya kũmbanĩa, na ũimathambya na manzĩ.'),
('kam', 'EXO', 40, 13, 'Na ũkekĩe Aluni ila ngũa ntheu; na ũkamwĩtĩkĩsye mauta, na kũmũvathan’ya ethĩwe mũtheu, nĩ kana anthũkũmae wĩanĩ wa ũthembĩ.'),
('kam', 'EXO', 40, 14, 'Na ũkaete ana make, na kũmekĩa makanzũ;'),
('kam', 'EXO', 40, 15, 'na ũkametĩkĩsye mauta, o tondũ wetĩkĩsye ĩthe woo mauta, nĩ kana manthũkũmae wĩanĩ wa ũthembi: na kwĩtĩkĩw’a kwoo kũkeethĩwa kwoo kwondũ wa wĩa wa ũthembi kũvika tene na tene mosyaanĩonĩ moo onthe.'),
('kam', 'EXO', 40, 16, 'Nake Mose eeka o ta ũu; kwĩanana na onthe ala Yeova wamwĩaĩe, ũu nĩw’o wekie.'),
('kam', 'EXO', 40, 17, 'Na kweethĩwa mwei wa mbee wa mwaka wa kelĩ, mũthenya wa mbee wa mwei, ũla wĩkalo nĩwaũngamĩtw’e.'),
('kam', 'EXO', 40, 18, 'Na Mose aũngamya ũ wĩkalo, na aia iĩndĩ syaw’o, na aũngamya mbwaũ syaw’o, na eekĩa mĩamba yaw’o, na aũngamya ituĩ syaw’o.'),
('kam', 'EXO', 40, 19, 'Na alan’ya ĩeema ĩũlũ wa ũ wĩkalo, na eekĩa kĩla kya kũvw’ĩka ĩeema ĩũlũ wayo; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 20, 'Na oosa ũla ũkũsĩ na eekĩa nthĩnĩ wa yĩla ĩsandũkũ, na eekĩa ĩla mĩtĩ ĩsandũkũnĩ, na eekĩa ũla wĩkalo wa tei ĩsandũkũnĩ ĩũlũ:'),
('kam', 'EXO', 40, 21, 'na aete yĩla ĩsandũkũ nthĩnĩ wa ũ wĩkalo, na anĩka ũla tũtũ wa kũtĩlan’ya, na avw’ĩka yĩla ĩsandũkũ ya ũkũsĩ; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 22, 'Na eekĩa ĩla mesa ĩeemanĩ ya kũmbanĩa, ngalĩ ya wĩkalo ya ĩũlũ, ũtee wa tũtũ.'),
('kam', 'EXO', 40, 23, 'Na aia ila imũtũ vandũ vasyo ĩũlũ wayo mbee wa Yeova; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 24, 'Na eekĩa kĩla kĩndũ kĩkĩawa mataa ĩeemanĩ ya kũmbanĩa ngalĩ ya wĩkalo ya ĩtheo, kwelekela ĩ mesa.'),
('kam', 'EXO', 40, 25, 'Na akwatya mataa mbee wa Yeova; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 26, 'Na eekĩa kĩla kĩthembeo kya thaavu ĩeemanĩ ya kũmbanĩa ngalĩ ya mbee ya ũla tũtũ:'),
('kam', 'EXO', 40, 27, 'na atoeesya ũvani wa mĩtĩ ĩla ĩnyungaa nesa ĩũlũ wakyo; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 28, 'Na eekĩa ũla tama wa mũomonĩ wa wĩkalo.'),
('kam', 'EXO', 40, 29, 'Na aia kĩthembeo kya nthembo ya kũvĩvw’a mũomonĩ wa wĩkalo wa ĩeema ya kũmbanĩa, na athemba ĩũlũ wakyo ĩla nthembo ya kũvĩvw’a na nthembo ya mũtu; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 30, 'Na aia kĩla kĩndũ kya kũthambĩaa katĩ wa ĩeema ya kũmbanĩa na kĩthembeo kyu, na eekĩa manzĩ nthĩnĩ wakyo, ma kũthamba.'),
('kam', 'EXO', 40, 31, 'Na Mose na Aluni na ana make mathambĩsya moko moo na maũũ moo vo;'),
('kam', 'EXO', 40, 32, 'o yĩla malikile ĩeemanĩ ya kũmbanĩa, na yĩla mathengeee kĩla kĩthembeo, nĩmathambaa; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'EXO', 40, 33, 'Na aiia ĩla nza alingĩlĩte ũla wĩkalo na kĩla kĩthembeo, na anĩka ũla tama wa mbingĩlonĩ ya nza. Na ĩndĩ, Mose amina wĩa ũsu.'),
('kam', 'EXO', 40, 34, 'Nĩvo ĩndĩ ũla mũumbĩ wavw’ĩkie yĩla ĩeema ya kũmbanĩa, na ũtheu mũtisu wa Yeova wausũa ũla wĩkalo.'),
('kam', 'EXO', 40, 35, 'Na Mose ndaatonya kũlika ĩeemanĩ ya kũmbanĩa, nĩkwĩthĩwa ũla mũumbĩ wekalaa ĩũlũ wayo, na ũtheu mũtisu wa Yeova wausũa wĩkalo.'),
('kam', 'EXO', 40, 36, 'Na yĩla ũla mũumbi wookĩlilw’e kuma ĩũlũ wa wĩkalo, ana ma Isilaeli nĩmaendaa, syalonĩ syoo syonthe:'),
('kam', 'EXO', 40, 37, 'ĩndĩ ũla mũumbĩ walea kũkĩlw’a, matyaendaa kyalo ĩndĩ, mũvaka mũthenya ũla wĩũkĩlw’a.'),
('kam', 'EXO', 40, 38, 'Nũndũ ũla mũumbĩ wa Yeova waĩ ĩũlũ wa ũla wĩkalo mũthenya, na kwaĩ mwaki nthĩnĩ waw’o ũtukũ, andũ onthe ma nyũmba ya Isilaeli mene, syalonĩ syoo syonthe.'),
('kam', 'LEV', 1, 1, 'Na Yeova amwĩta Mose, na aneena nake e ĩeemanĩ ya kũmbanĩa, akĩmwĩa,'),
('kam', 'LEV', 1, 2, 'Neena na ana ma Isilaeli, noimea, Mũndũ o na wĩva wenyu aithembea Yeova nthembo, mwĩthemba nthembo yenyu ya indo, ya ndĩthya ya ng’ombe na ya mbũi na malondu.'),
('kam', 'LEV', 1, 3, 'Ethĩwa nthembo yake nĩ nthembo ya kũvĩvw’a ya ndĩthya ya ng’ombe, akathembe nũme ĩte kĩema: na akamĩthembee mũomonĩ wa ĩeema ya kũmbanĩa, nĩ kana etĩkĩlwe nĩ Yeova.'),
('kam', 'LEV', 1, 4, 'Nake akailĩĩle kw’oko mũtwenĩ wa nthembo ya kũvĩvw’a; na ĩkeetĩkĩlwa kwondũ wake yĩthĩw’e nthembo ya kwĩw’anĩthw’a kwake.'),
('kam', 'LEV', 1, 5, 'Akakoaĩe kasalũ ka mũew’a mbee wa Yeova: na ana ma Aluni, ala athembi, makaete ĩla nthakame, na kũminzangĩsya nthakame ĩũlũ wa kĩthembeo kw’onthe kĩla kĩ vakuvĩ na mũomo wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 1, 6, 'Nake akathĩnze ĩla nthembo ya kũvĩvw’a, na kũmĩtilanga ilungu syayo.'),
('kam', 'LEV', 1, 7, 'Na ana ma mũthembi Aluni makekĩe mwaki kĩthembeonĩ, na kwaĩĩa ngũ ĩũlũ wa mwaki;'),
('kam', 'LEV', 1, 8, 'na ana ma Aluni, ala athembi, makaie ila ilungu, vamwe na mũtwe, na mathunya, maĩĩe ĩũlũ wa ngũ ila syĩ mwakinĩ ũla wĩ kĩthembeonĩ:'),
('kam', 'LEV', 1, 9, 'ĩndĩ mavu mako na maũũ mako akathambye na manzĩ. Na mũthembi akavĩvĩsye konthe kĩthembeonĩ, kethĩwe nthembo ya kũvĩvw’a, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 1, 10, 'Na ethĩwa nthembo yake nĩ ya ndĩthya, ya malondu, kana ya mbũi, yĩthĩwe nthembo ya kũvĩvw’a; akathembe nũme ĩte kĩema.'),
('kam', 'LEV', 1, 11, 'Akamyũaĩe ũtee wa kĩthembeo kwelekela ngalĩ ya ĩũlũ mbee wa Yeova: na ana ma Aluni, ala athembi, makaminzangĩsye nthakame yayo ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 1, 12, 'Na akamĩtilange ilungu syayo, vamwe na mũtwe wayo na mathunya mayo; na mũthembi akasyaĩĩe ngũnĩ ila syĩ mwakinĩ ũla wĩ kĩthembeonĩ:'),
('kam', 'LEV', 1, 13, 'ĩndĩ mavu na maũũ akathambye na manzĩ. Na mũthembi akathembe yonthe, na kũmĩvĩvĩsya kĩthembeonĩ: nayo nĩ nthembo ya kũvĩvw’a, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 1, 14, 'Na ethĩwa nthembo yake ya kũmũthembea Yeova nĩ nthembo ya kũvĩvw’a ya nyũnyi, nĩvo wĩthemba nthembo yake ya ndumbũ, kana ya maswii ma ĩvũĩ.'),
('kam', 'LEV', 1, 15, 'Na mũthembi akamĩete kĩthembeonĩ, na kũmila mũtwe wayo ngingo ĩtilĩke, na kũmĩvĩvĩsya kĩthembeonĩ; na nthakame yayo ĩkamenew’e ngalĩ ĩmwe ya kĩthembeo;'),
('kam', 'LEV', 1, 16, 'nake akaumye kĩmoeo kyayo vamwe na ũvuku wakyo, na kwĩkya ũtee wa kĩthembeo ngalĩ ya wumĩlonĩ wa syũa, vandũ va kwĩta mũu:'),
('kam', 'LEV', 1, 17, 'na akatũanĩlye nthwaunĩ syayo, ĩndĩ ndakatilan’ye ilungu ilĩ. Na mũthembi akamĩvĩvĩsye kĩthembeonĩ, ĩũlũ wa ngũ syĩ mwakinĩ: nayo nĩ nthembo ya kũvĩvw’a, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 2, 1, 'Na yĩla mũndũ o na wĩva wĩthemba Yeova nthembo ya mũtu, nthembo yake yĩthĩwe ya mũtu mũvinyu: na akatulũĩle mauta ĩũlũ waw’o, na kwĩkĩa ũvumba ĩũlũ:'),
('kam', 'LEV', 2, 2, 'na akamĩetee ana ma Aluni athembi; na akaute ũvĩ wake wa ũla mũtu mũvinyu wayo, na amwe ma mauta mayo, vamwe na ũvumba w’onthe wayo. Na mũthembi akamĩvĩvĩsye kĩthembeonĩ yĩthĩwe ũlilikan’yo wayo, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova:'),
('kam', 'LEV', 2, 3, 'na kĩla kĩtiala kya nthembo ya mũtu kĩkeethĩwa kya Aluni na ana make: nĩ kĩndũ kĩtheu mũno kya nthembo sya Yeova ila ivĩvaw’a na mwaki.'),
('kam', 'LEV', 2, 4, 'Yĩla wĩthemba nthembo ya mũtu ũla ũkaangĩwe nthĩnĩ wa iko, yĩthĩwe tũmũtũ tũte ĩlawa twa mũtu mũvinyu ũvulanĩtw’e na mauta, kana tũmĩkate tũvũthũ tũte ĩlawa tũvakĩtwe mauta.'),
('kam', 'LEV', 2, 5, 'Na ethĩwa nthembo yaku nĩ nthembo ya mũtu ya kũkaangwa na ĩtandaa ya kĩaa, yĩthĩwe ya mũtu mũvinyu ũte ĩlawa, ũvulanĩtw’e na mauta.'),
('kam', 'LEV', 2, 6, 'Ũkatũtilange tũlungu, na kũtulũĩla mauta ĩũlũ watw’o: nĩ nthembo ya mũtu.'),
('kam', 'LEV', 2, 7, 'Na ethĩwa nthembo yaku nĩ nthembo ya mũtu ya kũkaangwa kĩkaanginĩ, ĩseũvw’e na mũtu mũvinyu na mauta.'),
('kam', 'LEV', 2, 8, 'Na ũkamũetee Yeova nthembo ya mũtu ĩla ĩseũvĩtw’e na syĩndũ isu: na ĩkanengwe mũthembi, nake akamĩete kĩthembeonĩ.'),
('kam', 'LEV', 2, 9, 'Na mũthembi akaumye nthembonĩ ya mũtu ũlilikan’yo wayo, na kũvĩvĩsya kĩthembeonĩ, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 2, 10, 'Na kĩla kĩtiala kya nthembo ya mũtu kĩkeethĩwa kya Aluni na ana make: nĩ kĩndũ kĩtheu mũno kya nthembo sya Yeova ila ivĩvaw’a na mwaki.'),
('kam', 'LEV', 2, 11, 'Nthembo ya mũtu o na wĩva, ĩla mwĩmũthembeaa Yeova, ndĩkekĩwe ĩlawa; nũndũ nĩkũvatane kũvĩvya ĩlawa, kana ũkĩ wa nzũkĩ, syĩthĩwe nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'LEV', 2, 12, 'Mũkaithembee Yeova syĩthĩwe nthembo ya mosyao ma mbee: ĩndĩ itikethĩwe kĩthembeonĩ syĩthĩwe mũuke mũseo.'),
('kam', 'LEV', 2, 13, 'Na kĩla kĩthembawa kya nthembo yaku ya mũtu kĩkĩae mũnyũ; o na ndũketĩkĩle nthembo yaku ya mũtu yĩthĩwe ĩte na mũnyũ wa ũtianĩo wa Ngai waku: thembaa mũnyũ vamwe na nthembo syaku syonthe.'),
('kam', 'LEV', 2, 14, 'Na ethĩwa wĩmũthembea Yeova nthembo ya mũtu ya mosyao ma mbee, thembaa nganũ yĩ iianĩ syayo ĩkaangĩtwe na mwaki, nganũ nthokoe ya iia mbĩũ, yĩthĩwe nthembo ya mũtu ya mosyao maku ma mbee.'),
('kam', 'LEV', 2, 15, 'Na ĩkĩa mauta ĩũlũ wayo, noyia ũvumba ĩũlũ: nĩ nthembo ya mũtu.'),
('kam', 'LEV', 2, 16, 'Na mũthembi akavĩvye ũlilikan’yo wayo, kĩlungu kya nganũ nthokoe yayo, na kĩlungu kya mauta mayo, vamwe na ũvumba w’onthe wayo: nĩ nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'LEV', 3, 1, 'Na ethĩwa nthembo yake nĩ nthembo ya nthembo sya mũuo; ethĩwa ethemba ng’ombe, o na ethĩwa nĩ nũme kana nga, akamĩthembe ĩte kĩema mbee wa Yeova.'),
('kam', 'LEV', 3, 2, 'Nake akailĩĩle kw’oko mũtwenĩ wa nthembo yake, na kũmyũaĩa mũomonĩ wa ĩeema ya kũmbanĩa: na ana ma Aluni ala athembi makaminzangĩsya nthakame ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 3, 3, 'Nake akamũthembee Yeova nthembo na mwaki kuma nthembonĩ ya nthembo sya mũuo; koa ũla ũvw’ĩkĩte mavu, na mathunya onthe ala me ĩũlũ wa mavu,'),
('kam', 'LEV', 3, 4, 'na mbio syelĩ, na mathunya ala makwatene nasyo, ala me vakuvĩ na kĩnyunyu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, vamwe na mbio, akaumye.'),
('kam', 'LEV', 3, 5, 'Na ana ma Aluni makamĩvĩvĩsye kĩthembeonĩ ĩũlũ wa nthembo ya kũvĩvw’a, ĩla yĩ ĩũlũ wa ngũ ila syĩ mwakinĩ: nĩ nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 3, 6, 'Na ethĩwa nthembo yake ya kũmũthembea Yeova yĩthĩwe nthembo sya mũuo nĩ ya ndĩthya ya mbũi na malondu; nũme kana nga, akathembe ĩte kĩema.'),
('kam', 'LEV', 3, 7, 'Ethĩwa akathemba katena ka ĩlondu kethĩwe nthembo yake, nĩvo ĩndĩ wĩkathemba mbee wa Yeova;'),
('kam', 'LEV', 3, 8, 'na akailĩĩle kw’oko mũtwenĩ wa nthembo yake, na kũkoaĩa mbee wa ĩeema ya kũmbanĩa: na ana ma Aluni makaminzangĩsye nthakame yako ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 3, 9, 'Nake akamũthembee Yeova nthembo na mwaki kuma nthembonĩ ya nthembo sya mũuo; mathunya mayo, mwĩthe w’onthe, akotilĩle vakuvĩ na ĩvĩndĩ ya mũongo; na koa ũla ũvw’ĩkĩte mavu, na mathunya onthe ala me ĩũlũ wa mavu,'),
('kam', 'LEV', 3, 10, 'na mbio syelĩ, na mathunya ala makwatene nasyo, ala me vakuvĩ na kĩnyunyu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, vamwe na mbio, akaumye.'),
('kam', 'LEV', 3, 11, 'Na mũthembi akamĩvĩvĩsye kĩthembeonĩ: nĩ lĩu wa nthembo ĩla ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'LEV', 3, 12, 'Na ethĩwa nthembo yake nĩ mbũi, nĩvo ĩndĩ wĩmĩthemba mbee wa Yeova:'),
('kam', 'LEV', 3, 13, 'na akailĩĩle kw’oko mũtwenĩ wayo, na kũmyũaĩa mbee wa ĩeema ya kũmbanĩa; na ana ma Aluni makaminzangĩsye nthakame yayo ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 3, 14, 'Na kuma nthĩnĩ wayo akathembe nthembo yake, nayo nĩ nthembo ĩvĩvĩaw’a Yeova na mwaki; koa ũla ũvw’ĩkĩte mavu, na mathunya onthe ala me ĩũlũ wa mavu,'),
('kam', 'LEV', 3, 15, 'na mbio syelĩ, na mathunya ala makwatene nasyo, ala me vakuvĩ na kĩnyunyu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, vamwe na mbio, akaumye.'),
('kam', 'LEV', 3, 16, 'Na mũthembi akaivĩvĩsye kĩthembeonĩ: nĩ lĩu wa nthembo ĩla ĩvĩvaw’a na mwaki, yĩthĩwe mũuke mũseo; mathunya onthe nĩ ma Yeova.'),
('kam', 'LEV', 3, 17, 'Ũũ nĩ mwĩao wa tene na tene mosyaanĩonĩ menyu onthe nyũmbanĩ syenyu syonthe, atĩ mũtikaaye mathunya kana nthakame.'),
('kam', 'LEV', 4, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 4, 2, 'Neena na ana ma Isilaeli, ũkĩmea, Ethĩwa mũndũ o na wĩva akeeka naĩ atesĩ, ũndũnĩ o na wĩva ũla Yeova weaie ndũkekwe, na akeeka ũndũ o na wĩva wa asu:'),
('kam', 'LEV', 4, 3, 'o na ethĩwa mũthembi ũla wetĩkĩw’e mauta akeeka naĩ na kwondũ wa ũu aiete ũthũkũ ĩũlũ wa andũ, nĩvo ĩndĩ namũthembee Yeova kwondũ wa naĩ yake ĩla wavĩtisye, kasalũ kate kĩema kethĩwe nthembo ya naĩ.'),
('kam', 'LEV', 4, 4, 'Na akaete kasalũ kau mũomonĩ wa ĩeema ya kũmbanĩa mbee wa Yeova; na akailĩĩle kw’oko mũtwenĩ wa kasalũ kau, na kũaĩa kasalu mbee wa Yeova.'),
('kam', 'LEV', 4, 5, 'Na mũthembi ũla wetĩkĩw’e mauta akose nthakame ya kasalũ, na kũmĩete ĩeemanĩ ya kũmbanĩa:'),
('kam', 'LEV', 4, 6, 'na mũthembi akatolye kyaa kyake nthakamenĩ, na kũminzangĩsya nthakame maminzangĩsya mũonza mbee wa Yeova, mbee wa tũtũ wa vala vandũ vatheu.'),
('kam', 'LEV', 4, 7, 'Na mũthembi akavake nthakame mbyanĩ sya kĩthembeo kya kũtoeesya ũvani wĩ mũuke mũseo mbee wa Yeova, kĩla kĩ ĩeemanĩ ya kũmbanĩa; na nthakame yonthe ya kala kasalũ akatulũĩle ĩtinanĩ ya kĩthembeo kya nthembo ya kũvĩvw’a, kĩla kĩ mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 4, 8, 'Na akaumye mathunya onthe ma kala kasalũ ka nthembo ya naĩ; koa ũla ũvw’ĩkĩte mavu, na mathunya onthe ala me ĩũlũ wa mavu,'),
('kam', 'LEV', 4, 9, 'na mbio syelĩ, na mathunya ala makwatene nasyo, ala me vakuvĩ na kĩnyunyu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, vamwe na mbio, akaumye,'),
('kam', 'LEV', 4, 10, 'o tondũ maumaw’a ng’ombenĩ ya nthembo ya nthembo sya mũuo: na mũthembi akamavĩvĩsye kĩthembeonĩ kya nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 4, 11, 'Na kĩthuma kya kasalũ kau, na nyama syako syonthe, vamwe na mũtwe wako, na maũũ mako, na mavu mako, na mũyoo wako,'),
('kam', 'LEV', 4, 12, 'o kasalũ kau konthe akatwae ũtee wa mwako wa maeema vandũ vatheu, vala mũu wĩtawa, na kũkavĩvĩsya ĩũlũ wa ngũ na mwaki: vala mũu wĩtawa nĩvo kevĩvĩw’a.'),
('kam', 'LEV', 4, 13, 'Na ethĩwa ũmbano w’onthe wa Isilaeli ũkavĩtya, na ũndũ ũsu ũivithwa methonĩ ma ũmbano, na ethĩwa mekĩte ũndũ o na wĩva wa maũndũ ala Yeova weaie matikekwe, na nĩmatw’ĩka avĩtan’ya;'),
('kam', 'LEV', 4, 14, 'yĩla naĩ ĩla mavĩtisye yĩmanyĩka, nĩvo ĩndĩ ũmbano ũkathembe kasalũ kethĩwe nthembo ya naĩ, na kũkaete mbee wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 4, 15, 'Na atumĩa ma ũmbano makailĩĩle moko mũtwenĩ wa kasalũ kau mbee wa Yeova; na kasalũ kakoaĩwe mbee wa Yeova.'),
('kam', 'LEV', 4, 16, 'Na mũthembi ũla wetĩkĩw’e mauta akaete nthakame ya kala kasalũ ĩeemanĩ ya kũmbanĩa:'),
('kam', 'LEV', 4, 17, 'na mũthembi akatolye kyaa kyake nthakamenĩ, na kũmĩminzangĩsya maminzangĩsya mũonza mbee wa Yeova, mbee wa ũla tũtũ.'),
('kam', 'LEV', 4, 18, 'Na akavake nthakame mbyanĩ sya kĩthembeo kĩla kĩ mbee wa Yeova, kĩla kĩ ĩeemanĩ ya kũmbanĩa; na nthakame yonthe akatulũĩle ĩtinanĩ ya kithembeo kya nthembo ya kũvĩvw’a, kĩla kĩ mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 4, 19, 'Na akaumye mathunya onthe mako, na kũmavĩvĩsya kĩthembeonĩ.'),
('kam', 'LEV', 4, 20, 'Ũu nĩw’o ũkeka na kala kasalũ; otondũ wekie na kala kasalũ ka nthembo ya naĩ, o ta ũu akeke na kau; na mũthembi akathembe nthembo ya wĩw’anĩthyo kwondũ woo, na makaekewa.'),
('kam', 'LEV', 4, 21, 'Na akatwae kala kasalũ ũtee wa mwako wa maeema, na kukavĩvya o tondũ wavĩvisye kasalũ ka mbee: nĩ nthembo ya naĩ kwondũ wa umbano.'),
('kam', 'LEV', 4, 22, 'Yĩla mũsumbĩki ũkeka naĩ, na kwĩka atesĩ ũndũ o na wĩva wa maũndũ onthe ala Yeova Ngai wake weaie matikekwe, na nĩwatw’ĩka mũvĩtan’ya;'),
('kam', 'LEV', 4, 23, 'ethĩwa akamanyĩthw’a naĩ yake ĩla wavĩtisye, akaete mbũi, nthenge ĩte kĩema, yĩthĩwe nthembo yake.'),
('kam', 'LEV', 4, 24, 'Na akailĩĩle kw’oko mũtwenĩ wa nthenge, na kũmyũaĩa vala moaĩaa nthembo ya kũvĩvw’a mbee wa Yeova: nĩ nthembo ya naĩ.'),
('kam', 'LEV', 4, 25, 'Na mũthembi akose na kyaa kyake nthakame ya nthembo ya naĩ, na kũmĩvaka mbyanĩ sya kĩthembeo kya nthembo ya kũvĩvw’a; na nthakame yayo akatulũĩle ĩtinanĩ ya kĩthembeo kya nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 4, 26, 'Na mathunya onthe mayo akavĩvĩsye kĩthembeonĩ, o ta mathunya ma nthembo ya nthembo sya mũuo; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu nũndũ wa naĩ yake, nake akaekewa.'),
('kam', 'LEV', 4, 27, 'Na ethĩwa mũndũ, o mũndũ, akeeka naĩ atesĩ, akĩka ũndũ o na wĩva wa maũndũ asu ala Yeova weaie matikekwe, na nĩwatw’ĩka mũvĩtan’ya;'),
('kam', 'LEV', 4, 28, 'ethĩwa akamanyĩthw’a naĩ yake ĩla wavĩtisye, nĩvo ĩndĩ aete mbũi yĩthĩwe nthembo yake, mbaika ĩte kĩema, kwondũ wa naĩ yake ĩla wavĩtisye.'),
('kam', 'LEV', 4, 29, 'Na akailĩĩle kw’oko mũtwenĩ wa nthembo ya naĩ, na kũaĩa nthembo ya naĩ vandũ vau va nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 4, 30, 'Na mũthembi akose na kyaa kyake nthakame yayo, na kũmĩvaka mbyanĩ sya kĩthembeo kya nthembo ya kũvĩvw’a; na nthakame yonthe akamĩtulũĩle ĩtinanĩ ya kĩthembeo.'),
('kam', 'LEV', 4, 31, 'Na mathunya onthe mayo akaumye, o tondũ mathunya maumaw’a nthembonĩ ya nthembo sya mũuo; na mũthembi akamavĩvĩsye kĩthembeonĩ methĩwe mũuke mũseo kwa Yeova; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu, nake akaekewa.'),
('kam', 'LEV', 4, 32, 'Na ethĩwa akaete katena ka ĩlondu kethĩwe nthembo yake ya naĩ, naete kamwatĩ kate kĩema.'),
('kam', 'LEV', 4, 33, 'Na akailĩĩle kw’oko mũtwenĩ wa nthembo ya naĩ, na kũkoaĩa vala moaĩaa nthembo ya kũvĩvw’a kethĩwe nthembo ya naĩ.'),
('kam', 'LEV', 4, 34, 'Na mũthembi akose na kyaa kyake nthakame ya nthembo ya naĩ, na kũmĩvaka mbyanĩ sya kĩthembeo kya nthembo ya kũvĩvw’a; na nthakame yonthe yako akamĩtulũĩle ĩtinanĩ ya kĩthembeo.'),
('kam', 'LEV', 4, 35, 'Na mathunya onthe mako akaumye, o tondũ mathunya ma katena ka ĩlondu maumaw’a nthembonĩ ya nthembo sya mũuo; na mũthembi akamavĩvĩsye kĩthembeonĩ, ĩũlũ wa nthembo sya Yeova ila ivĩvaw’a na mwaki; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu nũndũ wa naĩ yake ĩla wavĩtisye, nake akaekewa.'),
('kam', 'LEV', 5, 1, 'Na ethĩwa mũndũ o na wĩva akeeka naĩ, akĩw’a wasya wa wĩvĩto, nake nĩ ngũsĩ, ethĩwa nĩwonete kana kũmanya, ethĩwa ndeũtavan’ya ũndũ ũsu, nĩvo ĩndĩ wĩkua naĩ yake mwene.'),
('kam', 'LEV', 5, 2, 'Kana ethĩwa mũndũ o na wĩva akakiita kĩndũ kĩvuku, ethĩwa nĩ nyamũ ngw’ũ mbuku, kana indo ngw’ũ mbuku, kana tũsamũ tũkw’ũ tũvuku tũla tũtambũkaa, na ũndũ ũsu ndawĩsĩ, nake aivukw’a, nĩvo ĩndĩ nĩwatw’ĩka mũvĩtan’ya.'),
('kam', 'LEV', 5, 3, 'Kana ethĩwa akakiita ũvuku wa mũndũ, o ũndũ ũvuku wake ũilyĩ ũla ũvukĩtw’e nĩw’o, na ũndũ ũsu ndawĩsĩ; yĩla wĩũmanya, nĩvo ĩndĩ nĩwatw’ĩka mũvĩtan’ya.'),
('kam', 'LEV', 5, 4, 'Kana ethĩwa mũndũ o na wĩva akeevĩta ateũsũanĩa aineena na ilomo syake kwĩka naĩ, kana kwĩka nesa, ũndũ o na wĩva ũla mũndũ ũkevĩta ateũsũanĩa, na ũndũ ũsu ndawĩsĩ; yĩla wĩũmanya, nĩvo ĩndĩ wĩĩthĩwa e na ĩvĩtyo ya ũmwe wa maũndũ asu.'),
('kam', 'LEV', 5, 5, 'Na kũkeethĩwa, yĩla wĩĩthĩwa e na ĩvĩtyo ũndũnĩ ũmwe wa asu, akaumbũle ũndũ ũsu ũla wavĩtisye:'),
('kam', 'LEV', 5, 6, 'na akamũetee Yeova nthembo yake ya ĩvĩtyo kwondũ wa naĩ yake ĩla wavĩtisye, kamwatĩ kana mbaika, kuma ndĩthyanĩ yĩthĩwe nthembo ya naĩ; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu ũndũ wa naĩ yake.'),
('kam', 'LEV', 5, 7, 'Na ethĩwa ndatonya kwona katena ka ĩlondu, nĩvo ĩndĩ wĩmũetee Yeova nthembo yake ya ĩvĩtyo kwondũ wa ũndũ ũla wavĩtisye, ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ; ĩmwe yĩthĩwe nthembo ya naĩ, na ĩla ĩngĩ yĩthĩwe nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 5, 8, 'Na akaietee mũthembi, nake akambe kũthemba ĩla ya nthembo ya naĩ, na kũmila mũtwe wayo ngingo ĩtilĩke, ĩndĩ ndakamyatũan’ye:'),
('kam', 'LEV', 5, 9, 'na akaminzangĩsye nthakame ĩmwe ya nthembo ya naĩ ngalĩ ya kĩthembeo; na nthakame ĩla yĩtiala ĩkamenew’e ĩtinanĩ ya kĩthembeo: nĩ nthembo ya naĩ.'),
('kam', 'LEV', 5, 10, 'Na akathembe ĩla ya kelĩ yĩthĩwe nthembo ya kũvĩvw’a, kwĩanana na ũtw’ĩo; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu ũndũ wa naĩ yake ĩla wavĩtisye, nake akaekewa.'),
('kam', 'LEV', 5, 11, 'Ĩndĩ ethĩwa ndatonya kwona ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ, nĩvo ĩndĩ wĩete nthembo yake kwondũ wa naĩ ĩla wavĩtisye, kĩlungu kya ĩkũmi kya eva ya mũtu mũvinyu wĩthĩwe nthembo ya naĩ: ndakawĩkĩe mauta, o na ndakawĩkĩe ũvumba ĩũlũ waw’o; nũndũ nĩ nthembo ya naĩ.'),
('kam', 'LEV', 5, 12, 'Na akamũetee mũthembi, na mũthembi akauta ũvĩ wake waw’o wĩthĩwe ũlilikan’yo wayo, na kũvĩvĩsya kĩthembeonĩ, ĩũlũ wa nthembo sya Yeova ila ivĩvaw’a na mwaki: nayo nĩ nthembo ya naĩ.'),
('kam', 'LEV', 5, 13, 'Na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu nũndũ wa naĩ yake ĩla wavĩtisye ũndũnĩ o na wĩva wa maũndũ aa, nake akaekewa: na kĩla kĩtiala kĩkeethĩwa kya mũthembi, o ta nthembo ya mũtu.'),
('kam', 'LEV', 5, 14, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 5, 15, 'Ethĩwa mũndũ o na wĩva akavĩtya, na kwĩka naĩ afesĩ, maũndũnĩ matheu ma Yeova; nĩvo ĩndĩ wĩmũetee Yeova nthembo yake ya ĩvĩtyo, ndũũme ya ndĩthya ĩte kĩema, kwĩanana na ũndũ wĩona thooa wayo wĩana vethanĩ wa sekeli, kwĩanana na sekeli ya vala vandũ vatheu, yĩthĩwe nthembo ya ĩvĩtyo:'),
('kam', 'LEV', 5, 16, 'nake akaĩve kwondũ wa ĩvĩtyo yake yĩla wavĩtisye ũndũnĩ mũtheu, na akwongeleele kĩlungu kya katano, na kũmũnenga mũthembi; na mũthembi akamwĩw’anĩthya kwondũ wa ĩla ndũũme ya nthembo ya ĩvĩtyo, nake akaekewa.'),
('kam', 'LEV', 5, 17, 'Na ethĩwa mũndũ o na wĩva akeeka naĩ, na kwĩka ũndũ o na wĩva ũla Yeova weaie ndũkekwe; o na ethĩwa ndesĩ nake nĩwatw’ĩka mũvĩtan’ya, na akakua ũthũku wake.'),
('kam', 'LEV', 5, 18, 'Na akamũetee mũthembi ndũũme ĩte kĩema kuma ndĩthyanĩ, kwĩanana na ũndũ wĩona thooa wayo wĩana, yĩthĩwe nthembo ya ĩvĩtyo; na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu ũndũ wa ĩvĩtyo wavĩtisye atesĩ na ndaamanya nĩ ĩvĩtyo, nake akaekewa.'),
('kam', 'LEV', 5, 19, 'Nayo nĩ nthembo ya ĩvĩtyo: vate ndĩi nĩ mũvĩtan’ya mbee wa Yeova.'),
('kam', 'LEV', 6, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 6, 2, 'Ethĩwa mũndũ o na wĩva akeeka naĩ, na kũmũvĩtanĩsya Yeova, na kũkenga mũtũi wake kwondũ wa kĩndũ wiĩte kwake, kana kwondũ wa wĩw’ano, kana kũvutana, kana kũmũthĩn’ya mũtũi wake,'),
('kam', 'LEV', 6, 3, 'kana kwona kĩndũ kyau, na kũkengana ũndũ wakyo, na kwĩvĩta ũvũngũ; ũndũnĩ ũmwe wa maũndũ aa onthe ũla mũndũ wĩkaa, akĩvĩtya ũndũnĩ ũsu;'),
('kam', 'LEV', 6, 4, 'nĩvo kũkethĩwa, ethĩwa nĩwekie naĩ, na atw’ĩka mũvĩtan’ya, akatũnge kĩla wosie kwondũ wa kũvutana, kana kĩndũ kĩla wosie kwondũ wa kũthĩn’ya ũngĩ, kana kĩndũ kiĩtwe kwake, kana kĩndũ kĩla wonie kyaĩte,'),
('kam', 'LEV', 6, 5, 'kana kĩndũ o na kĩva wevĩtie ũvũngũ ũndũ wakyo; akatũnge o kyo, na kũkyongeleela kĩlungu kya katano: akamũnenge ũsu mwene wakyo, mũthenya ũla wĩmanyĩka nĩ mũvĩtan’ya.'),
('kam', 'LEV', 6, 6, 'Na akamũetee Yeova nthembo yake ya ĩvĩtyo, ndũũme ya ndĩthya ĩte kĩema, kwĩanana na ũndũ wĩona thooa wayo wĩana, yĩthĩwe nthembo ya ĩvĩtyo, ĩetwe kwa mũthembi:'),
('kam', 'LEV', 6, 7, 'nake mũthembi akamwĩw’anĩthya ũsu mbee wa Yeova; na akaekewa ũndũ o na wĩva ũla watumie ethĩwa mũvĩtan’ya.'),
('kam', 'LEV', 6, 8, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 6, 9, 'Ĩaĩe Aluni na ana make, ũkĩmea, Ũũ nĩw’o mwĩao wa nthembo ya kũvĩvw’a: nthembo ya kũvĩvw’a yĩthĩwe ĩũlũ wa ngũ syĩ ĩũlũ wa kĩthembeo ũtukũ w’onthe kũvika kĩoko; na mwaki wakanae kĩthembeonĩ.'),
('kam', 'LEV', 6, 10, 'Na mũthembi akekĩe ĩla ngũa yake ya katane, na sulualĩ wake wa katane akekĩe mwĩĩnĩ wake; na akoke mũu wa mwaki ũla wavĩvĩsye nthembo ya kũvĩvw’a kĩthembeonĩ, na kũwia ũtee wa kĩthembeo.'),
('kam', 'LEV', 6, 11, 'Na akaumye ngũa syake, na kwĩkĩa ngũa ingĩ, na kũtwaa mũu ũtee wa mwako wa maeema vandũ vatheu.'),
('kam', 'LEV', 6, 12, 'Na mwaki wakanae kĩthembeonĩ, ndũkaavoe; na mũthembi akavĩvasye ngũ ĩũlũ wakyo kĩla kĩoko: na kwaĩĩa nthembo ya kũvĩvw’a ĩũlũ wasyo, na akavĩvĩsye mathunya ma nthembo sya mũuo vo ĩũlũ.'),
('kam', 'LEV', 6, 13, 'Mwaki wakanae kĩthembeonĩ ũtatw’ĩkanaa; ndũkaavoe.'),
('kam', 'LEV', 6, 14, 'Na ũũ nĩw’o mwĩao wa nthembo ya mũtu: ana ma Aluni makamĩthembe mbee wa Yeova, mbee wa kĩthembeo.'),
('kam', 'LEV', 6, 15, 'Na akaute ũvĩ wake wa mũtu mũvinyu wa nthembo ya mũtu, na wa mauta mayo, na ũvumba w’onthe ũla wĩ ĩũlũ wa nthembo ya mũtu, na kũvĩvĩsya kĩthembeonĩ yĩthĩwe mũuke mũseo kwa Yeova, ũlilikan’yo wayo.'),
('kam', 'LEV', 6, 16, 'Na kĩla kĩtiala kyaw’o Aluni na ana make makaye: ũkaĩwe vate ĩlawa vandũ vatheu; nza ya ĩeema ya kũmbanĩa nĩvo meĩĩa.'),
('kam', 'LEV', 6, 17, 'Ndũkaauwe wĩ na ĩlawa. Nĩnĩmanengete wĩthĩwe kĩlungu kyoo kya nthembo syakwa ila ivĩvaw’a na mwaki; ni ntheu mũno, o ta nthembo ya naĩ, na ta nthembo ya ĩvĩtyo.'),
('kam', 'LEV', 6, 18, 'Kĩla mũndũ mũũme wa ana ma Aluni akaye, kuma nthembonĩ sya Yeova ila ivĩvaw’a na mwaki, nĩ kĩlungu kyake tene na tene mosyaanĩonĩ menyu: o ũla ũkaikiita akeethĩwa e mũtheu.'),
('kam', 'LEV', 6, 19, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 6, 20, 'Ĩno nĩyo nthembo ya Aluni na ya ana make, ĩla makamũthembea Yeova mũthenya ũla ũmwe wĩĩtĩkĩw’a mauta: kĩlungu kya ĩkũmi kya eva ya mũtu mũvinyu wĩthĩwe nthembo ya mũtu mavinda onthe, nyunzu yaw’o kĩoko, na nyunzu yaw’o wĩoo.'),
('kam', 'LEV', 6, 21, 'Ũkakaangwe na mauta ĩtandaanĩ ya kĩaa; na wakaangwa, ũkaete nthĩnĩ: ũkamũthembee Yeova nthembo ya mũtu ya ilungu isu ikaangĩtwe yĩthĩwe mũuke mũseo.'),
('kam', 'LEV', 6, 22, 'Na mũthembi ũla wetĩkĩw’e mauta, ũla ũkethĩwa vandũ vake wa ana make nĩwe ũkamĩthemba: ĩkavĩvĩw’e Yeova vyũ kwondũ wa mwamũlo wa tene na tene.'),
('kam', 'LEV', 6, 23, 'Na kĩla nthembo ya mũthembi ĩvĩvw’e vyũ: ndĩkaĩwe.'),
('kam', 'LEV', 6, 24, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 6, 25, 'Neena na Aluni na ana make, ũkĩmea, Ũũ nĩw’o mwĩao wa nthembo ya naĩ: vandũ vala nthembo ya kũvĩvw’a yũaĩawa nĩvo nthembo ya naĩ ĩkoaĩawa mbee wa Yeova: nĩ ntheu mũno.'),
('kam', 'LEV', 6, 26, 'Mũthembi ũla wĩmĩthemba ũndũ wa naĩ akamĩye: ĩkaĩsĩawe vandũ vatheu, nza ya ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 6, 27, 'Kĩla kĩkakiita nyama syayo kĩkeethĩwa kĩtheu; na yĩla nthakame yayo ĩtalĩkĩla ngũanĩ o na yĩva, ngũa ĩla yatalĩkĩlwe ũkathambĩsye vandũ vatheu.'),
('kam', 'LEV', 6, 28, 'Ĩndĩ mbisũ ya yũmba ĩla yĩmĩua nĩyũawe; na ethĩwa ĩkauĩwa ĩsilianĩ ya ũthuku, yĩkutwe, na kũthambũkwa na manzĩ.'),
('kam', 'LEV', 6, 29, 'Kĩla mũndũ mũũme wa athembi akaye: nĩ ntheu mũno.'),
('kam', 'LEV', 6, 30, 'Na nthembo ya naĩ o na yĩva, ĩla nthakame yayo ĩetawe ĩeemanĩ ya kũmbanĩa yĩthĩwe ya wĩw’anĩthyo nthĩnĩ wa vala vandũ vatheu, ndĩkaĩwe: ĩvĩvw’e na mwaki.'),
('kam', 'LEV', 7, 1, 'Na ũu nĩw’o mwĩao wa nthembo ya ĩvĩtyo: nĩ ntheu mũno.'),
('kam', 'LEV', 7, 2, 'Vandũ vala moaĩaa nthembo ya kũvĩvw’a nĩvo meũaĩaa nthembo ya ĩvĩtyo; na nthakame yayo akaminzangĩsye ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 7, 3, 'Na akathembe mathunya mayo onthe: mwĩthe, na mathunya ala mavw’ĩkaa mavu,'),
('kam', 'LEV', 7, 4, 'na mbio syelĩ, na mathunya ala makwatene nasyo, ala me vakuvĩ na kĩnyunyu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, vamwe na mbio, akaumye;'),
('kam', 'LEV', 7, 5, 'na mũthembi akaivĩvĩsye kĩthembeonĩ syĩthĩwe nthembo ya kũmũvĩvĩsya Yeova na mwaki: nĩ nthembo ya ĩvĩtyo.'),
('kam', 'LEV', 7, 6, 'Kĩla mũndũ mũũme wa athembi akaye: nĩĩwe vandũ vatheu: nĩ ntheu mũno.'),
('kam', 'LEV', 7, 7, 'O ũndũ ĩilyĩ nthembo ya naĩ, nĩw’o ĩilyĩ nthembo ya ĩvĩtyo; mwĩao wasyo nĩ ũmwe: mũthembi ũla wĩthemba nthembo ya wĩw’anĩthyo nayo, ĩkeethĩwa yake.'),
('kam', 'LEV', 7, 8, 'Na mũthembi ũla wĩthemba nthembo ya kũvĩvw’a ya mũndũ o na wĩva, o mũthembi ũsu eyosee kĩthuma kya nthembo ya kũvĩvw’a ĩla wathembie.'),
('kam', 'LEV', 7, 9, 'Na kĩla nthembo ya mũtu ĩla ĩkaangĩwe ikonĩ nthĩnĩ, na yonthe ĩla ĩkaangĩwe kĩkaanginĩ, na ĩla ĩkaangĩwe ĩtandaanĩ ya kĩaa, ĩkeethĩwa ya mũthembi ũla wamĩthembie.'),
('kam', 'LEV', 7, 10, 'Na kĩla nthembo ya mũtu, ũvulanĩtw’e na mauta, kana mũmũ, ĩkeethĩwa ya ana onthe ma Aluni, meanen’ye.'),
('kam', 'LEV', 7, 11, 'Na ũu nĩw’o mwĩao wa nthembo ya nthembo sya mũuo, ĩla mũndũ wĩmũthembea Yeova.'),
('kam', 'LEV', 7, 12, 'Ethĩwa emĩthemba ũndũ wa mũvea, nĩvo ĩndĩ wĩthemba vamwe na nthembo ya mũvea tũmũtũ tũte ĩlawa tũvulanĩtw’e na mauta, na tũmĩkate tũvũthũ tũte ĩlawa tũvakĩtwe mauta, na tũmũtũ twa mũtu mũvinyu ũvulanĩtw’e na mauta, na tũkakaangwa.'),
('kam', 'LEV', 7, 13, 'Vamwe na tũmũtũ tũla twĩ na ĩlawa akathembe nthembo yake o vamwe na nthembo ya nthembo syake sya mũuo kwondũ wa mũvea.'),
('kam', 'LEV', 7, 14, 'Na kuma nthĩnĩ wayo akathembe kamwe ka kĩla nthembo kethĩwe nthembo ya kũkĩlĩw’a Yeova; ĩkeethĩwa ya mũthembi ũla ũminzangĩasya nthakame ya nthembo sya mũuo.'),
('kam', 'LEV', 7, 15, 'Na nyama sya nthembo ya nthembo syake sya mũuo kwondũ wa mũvea ikaĩwe mũthenya ũla wĩthemba nthembo yake; ndakatialye kũvika kĩoko.'),
('kam', 'LEV', 7, 16, 'Ĩndĩ ethĩwa nthembo ya kĩndũ kyake kĩla wĩthemba nĩ ya wĩvĩto, kana nthembo ya kumya na ngoo ya kwenda, ĩkaĩwe mũthenya ũla wĩthemba nthembo yake; na ũnĩ ũsu kĩla kĩtiala kyayo kĩĩwa:'),
('kam', 'LEV', 7, 17, 'ĩndĩ kĩla kĩtiala kya nyama sya nthembo ĩsu mũthenya wa katatũ kĩvĩvw’e na mwaki.'),
('kam', 'LEV', 7, 18, 'Na ethĩwa nyama o na syĩva sya nthembo ya nthembo syake sya mũuo ikaĩwa mũthenya wa katatũ, ndĩketĩkĩlwa, o na ndĩkatalĩlwa ũsu ũla wĩmĩthemba: ĩkeethĩwa ũthatyo, na mũndũ ũla wĩmĩya akakua ũthũku wake.'),
('kam', 'LEV', 7, 19, 'Nyama ila syĩkiita kĩndũ kĩvuku itikaĩwe; ivĩvw’e na mwaki. Na ũndũ wa nyama, kĩla mũndũ mũtheu nũtonya kwiya:'),
('kam', 'LEV', 7, 20, 'ĩndĩ mũndũ ũla wĩya nyama sya nthembo ya nthembo sya mũuo, ila sya Yeova, e mũvuku, mũndũ ũsu akavetwe andũnĩ make.'),
('kam', 'LEV', 7, 21, 'Na yĩla mũndũ o na wĩva wĩkiita kĩndũ o na kĩva kĩvuku, ũvuku wa mũndũ, kana nyamũ mbuku, kana kĩndũ o na kĩva kĩvuku kya kũthatya, na kũya nyama sya nthembo ya nthembo sya mũuo, ila sya Yeova, mũndũ ũsu akavetwe andũnĩ make.'),
('kam', 'LEV', 7, 22, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 7, 23, 'Neena na ana ma Isilaeli, ũkĩmea, Mũtikaye mathunya o na meva, ma ng’ombe, kana ĩlondu, kana mbũi.'),
('kam', 'LEV', 7, 24, 'Na mathunya ma nyamũ ya kũkw’a, na mathunya ma ĩla yalĩkile nĩ nyamũ, nĩmatonya kũtethya wĩa ũngĩ o na wĩva; ĩndĩ mũikamaye nongi.'),
('kam', 'LEV', 7, 25, 'Nũndũ o ũla wĩya mathunya ma nyamũ, ala andũ mamũthembeaa Yeova methĩwe nthembo ya kũvĩvw’a na mwaki, o mũndũ ũla wĩmaya akavetwe andũnĩ make.'),
('kam', 'LEV', 7, 26, 'Motũonĩ menyu onthe mũikaaye nthakame o na yĩva yonthe, ethĩwa nĩ ya nyũnyĩ kana ya nyamũ.'),
('kam', 'LEV', 7, 27, 'O ũla wĩya nthakame o na yĩva, mũndũ ũsu akavetwe andũnĩ make.'),
('kam', 'LEV', 7, 28, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 7, 29, 'Neena na ana ma Isĩlaelĩ, ũkĩmea, Ũla wĩmumĩsya Yeova nthembo ya nthembo syake sya mũuo akamũetee Yeova nthembo yake kuma nthĩnĩ wa nthembo ya nthembo sya mũuo:'),
('kam', 'LEV', 7, 30, 'moko make mwene makaete nthembo sya Yeova ila ivĩvaw’a na mwaki; akaete mathunya vamwe na kĩng’eng’eto, nĩ kana kĩng’eng’eto kĩvyũlangw’e kĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova.'),
('kam', 'LEV', 7, 31, 'Na mũthembi akavĩvĩsye mathunya kĩthembeonĩ; ĩndĩ kĩng’eng’eto kĩkeethĩwa kya Aluni na ana make.'),
('kam', 'LEV', 7, 32, 'Na kũũ kwa ngalĩ ya kw’oko kwa aũme mũkanenge mũthembi kwĩthĩwe nthembo ya kũkĩlw’a kumw’a nthĩnĩ wa nthembo sya nthembo syenyu sya mũuo.'),
('kam', 'LEV', 7, 33, 'Ũla wa ana ma Aluni ũla ũthembaa nthakame ya nthembo sya mũuo, na mathunya, kũũ kwa ngalĩ ya kw’oko kwa aũme kũkeethĩwa kĩlungu kyake.'),
('kam', 'LEV', 7, 34, 'Nũndũ kĩng’eng’eto kya kũvyũlw’a na kũũ kwa kũkĩlw’a nĩnaumisye nthĩnĩ wa nthembo sya nthembo sya mũuo sya ana ma Isilaeli, na nĩmũnengete mũthembi Aluni na ana make syĩthĩwe ilungu syoo tene na tene kuma kwa ana ma Isilaeli.'),
('kam', 'LEV', 7, 35, 'Kĩĩ nĩkyo kĩlungu kya Aluni, na kĩlungu kya ana make, kwondũ wa kwĩtĩkĩw’a mauta kwoo, kumw’a nthĩnĩ wa nthembo sya Yeova ila ivĩvaw’a na mwaki, mũthenya ũla wamanenganie mamũthũkũme Yeova wĩanĩ wa ũthembi;'),
('kam', 'LEV', 7, 36, 'kĩla Yeova weaie manengwe kya ana ma Isilaeli, mũthenya ũla wametĩkĩsye mauta. Nĩ kĩlungu kyoo tene na tene mosyaanĩonĩ moo onthe.'),
('kam', 'LEV', 7, 37, 'Ũũ nĩw’o mwĩao wa nthembo ya kũvĩvw’a, na wa nthembo ya mũtu, na wa nthembo ya naĩ, na wa nthembo ya ĩvĩtyo, na wa kũvathan’ya, na wa nthembo ya nthembo sya mũuo;'),
('kam', 'LEV', 7, 38, 'ũla Yeova wamwĩaĩe Mose kĩĩmanĩ kya Sinai, mũthenya ũla wameaĩe ana ma Isilaeli mamũthembee Yeova nthembo syoo, weũnĩ wa Sinai.'),
('kam', 'LEV', 8, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 8, 2, 'Osa Aluni na ana make vamwe nake, na ila ngũa, na mauta ma kwĩtĩkĩsya, na kala kasalũ ka nthembo ya naĩ, na ndũũme ilĩ, na kĩkavũ kya kĩmũtũ kĩte ĩlawa;'),
('kam', 'LEV', 8, 3, 'na ũmban’ya ũmbano w’onthe mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 8, 4, 'Na Mose eeka o tondũ Yeova wamwĩaĩe; na ũmbano woombanw’a mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 8, 5, 'Na Mose awĩa ũmbano, Ũũ nĩw’o ũla Yeova wĩaĩte wĩkwe.'),
('kam', 'LEV', 8, 6, 'Na Mose amaete Aluni na ana make, na amathambya na manzĩ.'),
('kam', 'LEV', 8, 7, 'Na amwĩkĩa ũla kanzũ, na amũvotoa mũsivi, na amwĩkĩa ngũa ndasa, na amwĩkĩa ngũa yĩtawa evotĩ, na amũvotoa mũsivi wa evoti ũla watumĩtwe na ũĩ, na kũmwoveea evoti naw’o.'),
('kam', 'LEV', 8, 8, 'Na amwĩkĩa kakalo ka kĩthũi: na kakalonĩ ka kĩthũi eekĩa Ulimu na Thumimu.'),
('kam', 'LEV', 8, 9, 'Na eekĩa ngutw’a mũtwenĩ wake; na ngutw’anĩ, ngalĩ ya mbee, eekĩa kĩlaũni kya thaavu, ngovĩa ntheu ya ũsumbĩ; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 8, 10, 'Na Mose oosa mauta ma kwĩtĩkĩsya, na awĩtĩkĩsya mauta ũla wĩkalo na syĩndũ syonthe ila syaĩ nthĩnĩ waw’o, kwivathan’ya syĩthĩwe ntheu.'),
('kam', 'LEV', 8, 11, 'Na aminzangĩsya amwe kĩthembeonĩ maminzangĩsya mũonza, na akĩtĩkĩsya kĩthembeo mauta na mĩio yakyo yonthe, na kĩndũ kya kũthambĩa na ĩtina yakyo, aivathan’ya syĩthĩwe ntheu.'),
('kam', 'LEV', 8, 12, 'Na etĩkĩsya mauta ma kwĩtĩkĩsya mũtwenĩ wa Aluni, na amwĩtĩkĩsya mauta, amũvathan’ye ethĩwe mũtheu.'),
('kam', 'LEV', 8, 13, 'Na Mose aete ana ma Aluni, na amavw’ĩka makanzũ, na amavotoa mĩsivi, na amekĩa tũkovila; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 8, 14, 'Na aete kala kasalũ ka nthembo ya naĩ: na Aluni na ana make mailĩĩla moko mũtwenĩ wa kala kasalũ ka nthembo ya naĩ.'),
('kam', 'LEV', 8, 15, 'Na akoaa; na Mose oosa nthakame, na amĩvaka mbyanĩ sya kĩthembeo ngalĩ syonthe na kyaa kyake, na athesya kĩthembeo, na atulũĩla nthakame ĩtinanĩ ya kĩthembeo, na akĩvatha kĩthĩwe kĩtheu, kũthemba nthembo ya wĩw’anĩthyo kwondũ wakyo.'),
('kam', 'LEV', 8, 16, 'Nake oosa mathunya onthe ala me ĩũlũ wa mavu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, na mbio syelĩ, na mathunya masyo; na Mose aivĩvĩsya kĩthembeonĩ.'),
('kam', 'LEV', 8, 17, 'Ĩndĩ kala kasalũ, na kĩthuma kyako, na nyama syako, na mũyoo wako, aivĩvĩsya na mwaki ũtee wa mwako wa maeema; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 8, 18, 'Na aete ndũũme ya nthembo ya kũvĩvw’a: na Aluni na ana make mailĩĩla moko mũtwenĩ wa ĩla ndũũme.'),
('kam', 'LEV', 8, 19, 'Na amyũaa; na Mose aminzangĩsya nthakame ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 8, 20, 'Na atilanga ndũũme ilungu syayo; na Mose avĩvya mũtwe, na ilungu, na mathunya.'),
('kam', 'LEV', 8, 21, 'Na athambya mavu na maũũ na manzĩ; na Mose avĩvĩsya ndũũme yonthe kĩthembeonĩ: yaĩ nthembo ya kũvĩvw’a yĩ mũuke mũseo: nthembo ĩla ĩvĩvĩaw’a Yeova na mwaki; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 8, 22, 'Na aete ndũũme ĩla ĩngĩ, ĩla ndũũme ya ũvathan’yo: na Aluni na ana make mailĩĩla moko mũtwenĩ wa ndũũme.'),
('kam', 'LEV', 8, 23, 'Na amyũaa; na Mose oosa nthakame yayo, na amĩvaka mũthyanĩ wa kũtũ kwa Aluni kwa ngalĩ ya kw’oko kwa aũme, na kyaanĩ kĩnene kya kw’oko kwa aũme, na kyaanĩ kĩnene kya kũũ kwa ngalĩ ya kw’oko kwa aũme.'),
('kam', 'LEV', 8, 24, 'Na aete ana ma Aluni; na Mose avaka nthakame mũthyanĩ wa matũ moo ma ngalĩ ya kw’oko kwa aũme, na kyaanĩ kĩnene kya moko moo ma aũme, na kyaanĩ kĩnene kya maũũ moo ma ngalĩ ya kw’oko kwa aũme: na Mose aminzangĩsya nthakame ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 8, 25, 'Na oosa mathunya na mwĩthe, na mathunya onthe ala me ĩũlũ wa mavu, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema, na mbio syelĩ, na mathunya masyo, na kũũ kwa ngalĩ ya kw’oko kwa aũme:'),
('kam', 'LEV', 8, 26, 'na aumya nthĩnĩ wa kĩla kĩkavũ kya kĩmũtũ kĩte ĩlawa, kĩla kiĩtwe mbee wa Yeova, kamũtũ kamwe kate ĩlawa, na kamũtũ kamwe kavakĩtwe mauta, na kamũkate kamwe kavũthũ, na atwilĩĩla ĩũlũ wa mathunya, na ĩũlũ wa kũla kũũ kwa ngalĩ ya kw’oko kwa aũme:'),
('kam', 'LEV', 8, 27, 'na ailĩĩla syonthe ĩũlũ wa moko ma Aluni, na ĩũlũ wa moko ma ana make, na aivyũlangya mbee wa Yeova syĩthĩwe nthembo ya kũvyũlw’a.'),
('kam', 'LEV', 8, 28, 'Na Mose asyumya mokonĩ moo, na aivĩvĩsya kĩthembeonĩ ĩũlũ wa nthembo ya kũvĩvw’a: nĩ syĩndũ syavathiwe syĩthĩwe mũuke mũseo: nĩ nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'LEV', 8, 29, 'Na Mose oosa kĩng’eng’eto, na akĩvyũlangya kĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova: kyaĩ kĩlungu kya Mose kya ĩla ndũũme ya ũvathan’yo; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 8, 30, 'Na Mose oosa mauta amwe ma kwĩtĩkĩsya, na nthakame ĩmwe ĩla yaĩ kĩthembeonĩ, na amũminzangĩsya Aluni, na ngũa syake, na ana make, na ngũa syoo vamwe nake, na amũvathan’ya Aluni ethĩwe mũtheu, vamwe na ngũa syake, na ana make, na ngũa syoo vamwe nake.'),
('kam', 'LEV', 8, 31, 'Na Mose amwĩa Aluni na ana make, Uĩai nyama ĩsu mũomonĩ wa ĩeema ya kũmbanĩa: na mũkamĩye vo vamwe na kĩmũtũ kĩla kĩ kĩkavũnĩ kĩla kya ũvathan’yo, o tondũ nĩaie, ngyasya, Aluni na ana make mamĩye.'),
('kam', 'LEV', 8, 32, 'Na ĩla yĩtiala ya nyama ĩsu na ya kĩmũtũ vĩvyai na mwaki.'),
('kam', 'LEV', 8, 33, 'Na mũtikaaumaale mũomonĩ wa ĩeema ya kũmbanĩa mĩthenya mũonza, kũvika mĩthenya ya kũvathwa kwenyu yĩanĩe: nũndũ akamũvathan’ya vandũ va mĩthenya mũonza mwĩthĩwe atheu.'),
('kam', 'LEV', 8, 34, 'O ũndũ kweekwa ũmũnthĩ, now’o Yeova wĩaĩte kwĩkwe, kũthemba nthembo ya wĩw’anĩthyo kwondũ wenyu.'),
('kam', 'LEV', 8, 35, 'Mũomonĩ wa ĩeema ya kũmbanĩa mũkekala ũtukũ na mũthenya vandũ va mĩthenya mũonza, na kũsũvĩaa wĩaĩo wa Yeova, nĩ kana mũikakw’e: nũndũ nĩw’o nĩaĩĩtwe.'),
('kam', 'LEV', 8, 36, 'Na Aluni na ana make meeka maũndũ onthe ala Yeova weaie na kanyw’a wa Mose.'),
('kam', 'LEV', 9, 1, 'Na kweethĩwa mũthenya wa nyanya, Mose ameta Aluni na ana make, na atumĩa ma Isilaeli;'),
('kam', 'LEV', 9, 2, 'na amwĩa Aluni, Osa kasaũ ka ndĩthya kethĩwe nthembo ya naĩ, na ndũũme yĩthĩwe nthembo ya kũvĩvw’a, ĩte kĩema, noithemba mbee wa Yeova.'),
('kam', 'LEV', 9, 3, 'Na neena na ana ma Isilaeli, ũkĩmea, Osai nthenge yĩthĩwe nthembo ya naĩ; na kasaũ na katena ka ĩlondu, twa mwaka ũmwe, tũte kĩema twĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'LEV', 9, 4, 'na ng’ombe na ndũũme syĩthĩwe nthembo sya mũuo, sya kũthembwa mbee wa Yeova; na nthembo ya mũtu ũvulanĩtw’e na mauta: nũndũ ũmũnthĩ Yeova nũnũkũmumĩlĩla.'),
('kam', 'LEV', 9, 5, 'Na maete ila Mose weaie mbee wa ĩeema ya kũmbanĩa: na ũmbano w’onthe wathengeea na waũngama mbee wa Yeova.'),
('kam', 'LEV', 9, 6, 'Na Mose asya, Ũũ nĩw’o ũla Yeova weaie mwĩke: na ũtheu mũtisu wa Yeova ũkamumĩlĩla inyw’ĩ.'),
('kam', 'LEV', 9, 7, 'Na Mose amwĩa Aluni, Thengeea kĩthembeo, ũthembe nthembo yaku ya naĩ, na nthembo yaku ya kũvĩvw’a, ũthembe nthembo ya wĩw’anĩthyo kwondũ waku mwene, na kwondũ wa andũ; na themba nthembo ya andũ, na kumya nthembo ya wĩw’anĩthyo kwondũ woo; o tondũ Yeova weaie.'),
('kam', 'LEV', 9, 8, 'Kwondũ wa ũu Aluni athengeea kĩthembeo, na ooaa kasaũ ka nthembo ya naĩ, ĩla yaĩ kwondũ wake mwene.'),
('kam', 'LEV', 9, 9, 'Na ana ma Aluni mamũetee nthakame; nake atolya kyaa kyake nthakamenĩ, na amĩvaka mbyanĩ sya kĩthembeo, na atulũĩla nthakame ĩtinanĩ ya kĩthembeo:'),
('kam', 'LEV', 9, 10, 'ĩndĩ mathunya, na mbio, na koa mũvũthũ ũla waumiw’e ĩtemanĩ ya nthembo ya naĩ, avĩvĩsya kĩthembeonĩ; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 9, 11, 'Na nyama na kĩthuma avĩvĩsya na mwaki ũtee wa mwako wa maeema.'),
('kam', 'LEV', 9, 12, 'Nake ooaa nthembo ya kũvĩvw’a; na ana ma Aluni mamũetee nthakame, na amĩminzangĩsya ĩũlũ wa kĩthembeo kw’onthe.'),
('kam', 'LEV', 9, 13, 'Na mamũetee nthembo ya kũvĩvw’a, kĩlungu, kĩlungu, na mũtwe: nake aivĩvĩsya kĩthembeonĩ.'),
('kam', 'LEV', 9, 14, 'Na athambya mavu na maũũ, na amavĩvĩsya ĩũlũ wa nthembo ya kũvĩvw’a kĩthembeonĩ.'),
('kam', 'LEV', 9, 15, 'Na aete nthembo ya andũ, na oosa mbũi ya nthembo ya naĩ ĩla yaĩ kwondũ wa andũ, na amyũaa, na amĩthemba kwondũ wa naĩ, o ta ĩla ya mbee.'),
('kam', 'LEV', 9, 16, 'Na aete nthembo ya kũvĩvw’a, na amĩthemba kwĩanana na ũtw’ĩo.'),
('kam', 'LEV', 9, 17, 'Na aete nthembo ya mũtu, na auta ũvĩ ũmwe, na oovĩvĩsya kĩthembeonĩ, vamwe na nthembo ya kũvĩvw’a ya kĩoko.'),
('kam', 'LEV', 9, 18, 'O na ooaa ng’ombe na ndũũme, nthembo ya nthembo sya mũuo, ĩla yaĩ kwondũ wa andũ: na ana ma Aluni mamũetee nthakame, na amĩminzangĩsya ĩũlũ wa kĩthembeo kw’onthe,'),
('kam', 'LEV', 9, 19, 'na mathunya ma ĩla ng’ombe na ma ĩla ndũũme, na mwĩthe, na mathunya ala mavw’ĩkĩte mavu, na mbio, na koa mũvũthũ ũla ũvw’ĩkĩte ĩtema:'),
('kam', 'LEV', 9, 20, 'na mailĩĩla mathunya ĩũlũ wa ing’eng’eto, na avĩvĩsya mathunya kĩthembeonĩ:'),
('kam', 'LEV', 9, 21, 'na ing’eng’eto na kũũ kwa ngalĩ ya kw’oko kwa aũme Aluni avyũlangya syĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova; o tondũ Mose weaie.'),
('kam', 'LEV', 9, 22, 'Na Aluni ookĩlya moko make kwelekelya andũ, na amaathima; na atheea amina kũthemba nthembo ya naĩ, na nthembo ya kũvĩvw’a, na nthembo sya mũuo.'),
('kam', 'LEV', 9, 23, 'Na Mose na Aluni malika ĩeemanĩ ya kũmbanĩa, na maumaala, na maathima andũ: na ũtheu mũtisu wa Yeova wamaumĩlĩla andũ onthe.'),
('kam', 'LEV', 9, 24, 'Na kwauma mwaki mbee wa Yeova, na wavĩvĩsya nthembo ya kũvĩvw’a na mathunya kĩthembeonĩ: na yĩla andũ onthe mawonie, mookĩlya mawasya, na mavalũka na mothyũ moo.'),
('kam', 'LEV', 10, 1, 'Na Natavu na Aviu, ana ma Aluni, kĩla ũmwe osa kĩtoeesya kyake, na eekĩa mwaki nthĩnĩ wakyo, na eekĩa ũvani ĩũlũ waw’o, na mamũthembea Yeova na mwaki ũte wa vo, ũla ũtaameaĩa.'),
('kam', 'LEV', 10, 2, 'Na mwaki wauma mbee wa Yeova, na wamavĩvya, na makw’ĩa mbee wa Yeova.'),
('kam', 'LEV', 10, 3, 'Na ĩndĩ Mose amwĩa Aluni, Ũũ nĩw’o ũla Yeova waneenie, akyasya, Ngoonanw’a kwa ala manthengeeaa atĩ nĩ mũtheu, na ngataĩwa mbee wa andũ onthe. Na Aluni avindya ki.'),
('kam', 'LEV', 10, 4, 'Na Mose ameta Misaeli na Elisavani, ana ma Usieli mwendw’a ĩthe wa Aluni, na amea, Thengeeai, mũkue ana‐a‐ĩthe menyu kũmaumya mbee wa vala vandũ vatheu mũmatwae ũtee wa mwako wa maeema.'),
('kam', 'LEV', 10, 5, 'Kwondũ wa ũu mathengeea, na mamakua me o na makanzũ moo mamatwaa ũtee wa mwako wa maeema, o tondũ Mose waisye.'),
('kam', 'LEV', 10, 6, 'Na Mose amwĩa Aluni, na Eleasali na Ithamali, ana make, Mũikaivue nzw’ĩĩ sya mĩtwe yenyu, o na mũikatembũe ngũa syenyu; nĩ kana mũikakw’e, na kana ndakathatĩe ũmbano w’onthe: indĩ ana‐a‐ĩthe menyu, nyũmba nima ya Isilaeli, maĩe ũndũ wa kũvĩvya kũla Yeova ũvĩvisye.'),
('kam', 'LEV', 10, 7, 'Na mũikaumaale mũomonĩ wa ĩeema ya kũmbanĩa, mũikakw’e; nũndũ mauta ma kwĩtĩkĩsya ma Yeova me ĩũlũ wenyu. Na meeka kwĩanana na ndeto sya Mose.'),
('kam', 'LEV', 10, 8, 'Na Yeova aneena na Aluni, akĩmwĩa,'),
('kam', 'LEV', 10, 9, 'Ndũkanyw’e mbinyu kana kĩla kĩtoonasya, we, kana ana maku vamwe naku, yĩla mwĩlika ĩeemanĩ ya kũmbanĩa, mũtikese kũkw’a: ũu ũkeethĩawa mwamũlo wa tene na tene mosyaanĩonĩ menyu onthe:'),
('kam', 'LEV', 10, 10, 'nĩ kana mũvathũkan’ye katĩ wa kĩla kĩtheu na kĩla kĩte kĩtheu, na kĩla kĩvuku na kĩla kĩte kĩvuku;'),
('kam', 'LEV', 10, 11, 'na nĩ kana mũmanyĩsye ana ma Isilaeli myamũlo yonthe ĩla Yeova ũneenete nao na kanyw’a wa Mose.'),
('kam', 'LEV', 10, 12, 'Na Mose aneena na Aluni, na Eleasali na Ithamali, ana make ala matialile, Osai nthembo ya mũtu ĩla yatiala ya nthembo sya Yeova ila ivĩvaw’a na mwaki, na mũimĩya ĩte na ĩlawa ũtee wa kĩthembeo; nũndũ nĩ ntheu mũno;'),
('kam', 'LEV', 10, 13, 'nayo ĩkaĩĩwa vandũ vatheu, nĩkwĩthĩwa nĩ kĩlungu kyaku, na kĩlungu kya ana maku, kya nthembo sya Yeova ila ivĩvaw’a na mwaki: nũndũ ũu nĩw’o nĩaĩĩtwe.'),
('kam', 'LEV', 10, 14, 'Na kĩng’eng’eto kya kũvyũlw’a na kũũ kwa kũkĩlw’a mũkaĩĩa vandũ vatheu, we, na ana maku, na eĩtu maku vamwe naku: nũndũ ninenganĩtwe syĩthĩwe kĩlungu kyaku, na kĩlungu kya ana maku, kumw’a nthĩnĩ wa nthembo sya nthembo sya mũuo sya ana ma Isilaeli.'),
('kam', 'LEV', 10, 15, 'Kũũ kwa kũkĩlw’a na kĩng’eng’eto kya kũvyũlw’a makaetanĩsye na nthembo sya mathunya ila ivĩvaw’a na mwaki, kũmĩvyũlangya ĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova: na ĩkeethĩwa yaku, na ya ana maku vamwe naku, kĩlungu kya tene na tene; o tondũ Yeova weaie.'),
('kam', 'LEV', 10, 16, 'Na Mose amantha na kĩthing’ĩĩsyo ĩla mbũi ya nthembo ya naĩ, na, sisya, yaĩ ĩnamina kũvĩvw’a: na amathatĩa Eleasali na Ithamali, ana ma Aluni ala matialile, akĩmea,'),
('kam', 'LEV', 10, 17, 'Nũndũ wa kĩ mũtinaĩa nthembo ya naĩ vala vandũ vatheu, nũndũ nĩ ntheu mũno, nake nũmũnengete ya kũveta naĩ ya ũmbano, yĩthĩwe nthembo ya wĩw’anĩthyo kwondũ woo mbee wa Yeova?'),
('kam', 'LEV', 10, 18, 'Sisya nthakame yayo ndĩnaetwe nthĩnĩ wa vala vandũ vatheu: vate ndĩĩ nĩmwaĩlwe nĩ kũmĩya mwĩ vala vandũ vatheu, o tondũ nĩaie.'),
('kam', 'LEV', 10, 19, 'Na Aluni amwĩa Mose, Sisya, ũmũnthĩ nĩmamũthembea Yeova nthembo yoo ya naĩ na nthembo yoo ya kũvĩvw’a; na maũndũ aa nĩo mangwata: kethĩwa nĩĩe nthembo ya naĩ ũmũnthĩ, wĩthĩwa ũndũ wa kwendeesya methonĩ ma Yeova?'),
('kam', 'LEV', 10, 20, 'Na Mose eew’a ũu, wamwendeesya.'),
('kam', 'LEV', 11, 1, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'LEV', 11, 2, 'Neenai na ana ma Isilaeli, mũimea, Ii nĩsyo syĩndũ syĩ thayũ ila mũtonya kũya nyamũnĩ syonthe ila syĩ kũũ nthĩ.'),
('kam', 'LEV', 11, 3, 'O ĩla yĩ na ĩvũngũ yatũe, na mathaio matũku katĩ, na ĩthaumasya, nyamũnĩ syonthe, nĩyo mũtonya kũya.'),
('kam', 'LEV', 11, 4, 'Ĩndĩ ii mũikaaye sya ila ithaumasya, kana sya ila syĩ na ĩvũngũ yatũe: ngamĩle, nĩkwĩthĩwa nĩthaumasya ĩndĩ ndĩ na ĩvũngũ yatũe, nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 5, 'Na kĩnyowe, nĩkwĩthĩwa nĩkĩthaumasya ĩndĩ kĩti na ĩvũngũ yatũe, nĩ kĩvuku kwenyu.'),
('kam', 'LEV', 11, 6, 'Na mbũkũ, nĩkwĩthĩwa nĩthaumasya ĩndĩ ndĩ na ĩvũngũ yatũe, nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 7, 'Na ngũlũe, nĩkwĩthĩwa yĩ na ĩvũngũ yatũe, na mathaio matũku katĩ, ĩndĩ ndĩthaumasya, nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 8, 'Mũikaaye nyama syasyo, na mũikaakiite syĩ ngw’ũ: nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 9, 'Ii nĩsyo mũtonya kũya sya syonthe ila syĩ manzĩnĩ: o ĩla yĩ na nthwau na makwaũ manzĩnĩ, maũkanganĩ, na mbũsĩnĩ, isu nĩmũtonya kũya.'),
('kam', 'LEV', 11, 10, 'Na syonthe ila ite na nthwau na makwaũ maũkanganĩ, na mbũsĩnĩ, sya syonthe ila ithambĩaa manzĩnĩ, na sya syonthe ila syĩ thayũ ila syĩ manzĩnĩ, nĩ ũthatyo kwenyu,'),
('kam', 'LEV', 11, 11, 'na ikeethĩwa ũthatyo kwenyu; mũtikaaye nyama syasyo, na syĩ ngw’ũ ikeethĩwa ũthatyo kwenyu.'),
('kam', 'LEV', 11, 12, 'O ĩla yĩ manzĩnĩ ĩte na nthwau kana makwaũ, nayo nĩ ũthatyo kwenyu.'),
('kam', 'LEV', 11, 13, 'Na ii nĩsyo sya nyũnyi ila ikeethĩwa ũthatyo kwenyu; itikaaĩwe, nasyo nĩ ũthatyo: ndiũ, na ndiũ ya ĩthingi, na ndei,'),
('kam', 'LEV', 11, 14, 'na kĩmangaũ, na kĩvaalala o mũthemba wakyo,'),
('kam', 'LEV', 11, 15, 'na kĩla ngũngũũ o mũthemba wayo,'),
('kam', 'LEV', 11, 16, 'na nyaa, na ĩowe, na ĩng’aa, na mbolosya o mũthemba wayo,'),
('kam', 'LEV', 11, 17, 'na mũnyũũ, na ĩvutavutĩlya, na ndundu nene,'),
('kam', 'LEV', 11, 18, 'na ndundu yĩ mbya, na ngunĩ, na ndei ya ĩthingi,'),
('kam', 'LEV', 11, 19, 'na ĩsaũ, na ĩkuthakũthĩi o mũthemba wayo, na ĩlumi, na ũvuvu.'),
('kam', 'LEV', 11, 20, 'Na tũsamũ tw’onthe tũla twĩ na nthwau na tũtambũkaa o tũla tũendaa na maũũ ana nĩ ũthatyo kwenyu.'),
('kam', 'LEV', 11, 21, 'Ĩndĩ tũũ nĩtw’o mũtonya kũya twa tũsamũ tw’onthe tũla twĩ na nthwau na tũtambũkaa o tũla tũendaa na maũũ ana, twĩ na maũũ maasa, ma kũthaanyũkanga ĩũlũ wa nthĩ namo;'),
('kam', 'LEV', 11, 22, 'tũla mũtonya kũya twatw’o nĩ tũũ: ngie o mũthemba wayo, na ngie nene o mũthemba wayo, na ndandalĩka o mũthemba wayo, na kĩtooli o mũthemba wakyo.'),
('kam', 'LEV', 11, 23, 'Ĩndĩ tũsamũ tw’onthe tũla twĩ na nthwau na tũtambũkaa, tũla twĩ na maũũ ana, nĩ ũthatyo kwenyu.'),
('kam', 'LEV', 11, 24, 'Na kwondũ wa isu mũkeethĩwa avuku: o ũla wĩikiita syĩ ngw’ũ akeethĩwa mũvuku kũvika wĩoo;'),
('kam', 'LEV', 11, 25, 'o na ũla ũkakua kĩlungu kyasyo syĩ ngw’ũ akathambya ngũa syake, na kwĩthĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 11, 26, 'Kĩla nyamũ yĩ na ĩvũngũ yatũe, na mathaio mate matũku katĩ, na ndĩthaumasya, nĩ mbuku kwenyu: kĩla mũndũ ũla wĩikiita akeethĩwa mũvuku.'),
('kam', 'LEV', 11, 27, 'Na o ĩla ĩendaa na ithu syayo, nyamũnĩ syonthe ila iendaa na maũũ ana, nĩ mbuku kwenyu: o ũla wĩikiita syĩ ngw’ũ akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 11, 28, 'Na ũla wĩikua syĩ ngw’ũ akathambya ngũa syake, na kwĩthĩwa mũvuku kũvika wĩoo: nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 29, 'Tũsamũnĩ tũla tũtambũkaa ĩũlũ wa nthĩ tũũ nĩtw’o tũvuku kwenyu: kamũũngũu, na kavĩla, na ndĩlya nene o mũthemba wayo,'),
('kam', 'LEV', 11, 30, 'na mwilũ, na ngusw’ĩ, na ĩtelembũ, na nzana, na kĩmbu.'),
('kam', 'LEV', 11, 31, 'Tũu nĩtw’o tũvuku kwenyu twa tw’onthe tũla tũtambũkaa: o ũla ũkatũkiita twĩ tũkw’ũ, akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 11, 32, 'Na kamwe katw’o ke kakw’ũ kakavalũkĩla kĩndũ o na kĩva, kĩkeethĩwa kĩvuku: ethĩwa nĩ kĩndũ kĩseũvĩtw’e kya mũtĩ, kana ngũa, kana kĩthuma, kana ĩkunia, kĩndũ o na kĩva, kĩla kĩtetheaw’a wĩa o na wĩva, mũvaka kĩkĩwe manzĩnĩ, na kĩkeethĩwa kĩvuku kũvika wĩoo; nĩvo ĩndĩ kĩĩthĩwa kĩtheu.'),
('kam', 'LEV', 11, 33, 'Kĩla kĩndũ kyũmbĩtwe kya yũmba, kĩla kamwe katw’o kakavalũka nthĩnĩ wakyo, o kĩla kĩ nthĩnĩ wakyo kĩkeethĩwa kĩvuku, na mũkakyũaa.'),
('kam', 'LEV', 11, 34, 'Lĩu w’onthe nthĩnĩ wakyo ũla ũtonya kũĩwa, ũla manzĩ asu meĩkĩwa ĩũlũ waw’o, ũkeethĩwa mũvuku; na kya ũnyw’a kyonthe kĩla kĩtonya kũnyw’ĩwa kĩ mũionĩ ũilyĩ ũu kĩkeethĩwa kĩvuku.'),
('kam', 'LEV', 11, 35, 'Na kĩla kĩndũ kĩkavalũkĩlwa nĩ kĩlungu o na kĩva kyatw’o twĩ tũkw’ũ kĩkeethĩwa kĩvuku; ethĩwa nĩ iko, kana mbisũ, ĩkooawa ilungu: nĩ mbuku, na ikeethĩwa mbuku kwenyu.'),
('kam', 'LEV', 11, 36, 'Ĩndĩ nthongo kana ĩima yĩla manzĩ mombanĩe yĩkeethĩwa yĩ ĩtheu: ĩndĩ o ũla ũkatũkiita twĩ tũkw’ũ akeethĩwa mũvuku.'),
('kam', 'LEV', 11, 37, 'Na ethĩwa kĩlungu kyatw’o twĩ tũkw’ũ kĩkavalũkĩla mbeũ ila sya ũvandwa, nĩ ntheu.'),
('kam', 'LEV', 11, 38, 'Ĩndĩ ethĩwa mbeũ ikeekĩwa manzĩ, na kĩlungu kyatw’o twĩ tũkw’ũ kĩkaivalũkĩla, nĩ mbuku kwenyu.'),
('kam', 'LEV', 11, 39, 'Na ethĩwa nyamũ o na yĩva, ĩla mũtonya kũya, ĩkakw’a; ũla wĩmĩkiita yĩ ngw’ũ akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 11, 40, 'Na ũla wĩya nyama syayo yĩ ngw’ũ akathambya ngũa syake, na kwĩthĩwa mũvuku kũvika wĩoo: o nake ũla wĩmĩkua yĩ ngw’ũ akathambya ngũa syake, na kwĩthĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 11, 41, 'Na kĩla kasamũ katambũkaa, kala katambũkaa ĩũlũ wa nthĩ nĩ ũthatyo, katikaĩwe.'),
('kam', 'LEV', 11, 42, 'O kĩla kĩendaa na ĩvu, na kĩla kĩendaa na maũũ ana, kana kĩla kĩ na maũũ maingĩ, o tũsamũ tw’onthe tũla tũtambũkaa ĩũlũ wa nthĩ, tũu mũtikatũye; nũndũ nĩ ũthatyo.'),
('kam', 'LEV', 11, 43, 'Mũtiketw’ĩkĩthye ũthatyo ũndũ wa kasamũ o na keva kala katambũkaa, o na mũikevukye ũndũ watw’o, mũvukw’e nĩtw’o.'),
('kam', 'LEV', 11, 44, 'Nũndũ nyie nĩ Yeova Ngai wenyu: kwondũ wa ũu ĩvathan’yei, na ĩthĩwai atheu; nũndũ nyie nĩ mũtheu: o na mũikevukye na kasamũ o na keva kala katambũkaa kala kaendaa ĩũlũ wa nthĩ.'),
('kam', 'LEV', 11, 45, 'Nũndũ ninyie Yeova ũla wamumisye nthĩ ya Misili, nĩthĩwe Ngai wenyu: kwondũ wa ũu ĩthĩwai atheu, nũndũ nyie nĩ mũtheu.'),
('kam', 'LEV', 11, 46, 'Ĩsu nĩyo mĩao ya nyamũ, na ya nyũnyi, na ya kĩla kyũmbe kĩ thayũ kĩthambĩaa manzĩnĩ, na ya kĩla kyũmbe kĩla kĩtambũkaa ĩũlũ wa nthĩ;'),
('kam', 'LEV', 11, 47, 'kũvathũkan’ya katĩ wa kĩla kĩvuku na kĩla kĩtheu, na katĩ wa kĩla kĩ thayũ kĩtonya kũĩwa, na kĩla kĩ thayũ kĩtatonya kũĩwa.'),
('kam', 'LEV', 12, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 12, 2, 'Neena na ana ma Isilaeli, ũkĩmea, Ethĩwa mũndũ mũka akaitava, na kũsyaa kavĩsĩ, nĩvo ĩndĩ wĩĩthĩwa mũvuku mĩthenya mũonza; o ta mĩthenyanĩ ya kũvathwa kwake kwondũ wa kwĩalũla kwake akeethĩwa mũvuku.'),
('kam', 'LEV', 12, 3, 'Na mũthenya wa nyanya kakaĩkwe ĩkonde ya mbinũ yako.'),
('kam', 'LEV', 12, 4, 'Na mũndũ mũka akekale nthakamenĩ ya kwĩthesya kwake mĩthenya mĩongo ĩtatũ na ĩtatũ; ndakakiite kĩndũ kĩvathe, kana kũlika vala vandũ vatheu, kũvika mĩthenya ya kwĩthesya kwake yĩanĩe.'),
('kam', 'LEV', 12, 5, 'Ĩndĩ ethĩwa akasyaa kelĩtu, nĩvo ĩndĩ wĩĩthĩwa mũvuku syumwa ilĩ, ta ĩvinda ya kũvathwa kwake, na akekala nthakamenĩ ya kwĩthesya kwake mĩthenya mĩongo thanthatũ na thanthatũ.'),
('kam', 'LEV', 12, 6, 'Na mĩthenya yake ya kwĩthesya kwake yeanĩa, ũndũ wa kavĩsĩ, kana ũndũ wa kelĩtu, akamũetee mũthembi, mũomonĩ wa ĩeema ya kũmbanĩa, katena ka ĩlondu ka mwaka ũmwe kethĩwe nthembo ya kũvĩvw’a, na ĩswii ya ĩvũĩ, kana ndumbũ, yĩthĩwe nthembo ya naĩ:'),
('kam', 'LEV', 12, 7, 'na akamĩthembe mbee wa Yeova, yĩthĩwe nthembo ya wĩw’anĩthyo kwondũ wake; nake akathew’a kwondũ wa nthongo ya nthakame yake. Ũu nĩw’o mwĩao wa ũla ũsyaaa, ethĩwa nĩ kũsyaa kavĩsĩ kana kelĩtu.'),
('kam', 'LEV', 12, 8, 'Na ethĩwa ndatonya kwona katena ka ĩlondu, nĩvo ĩndĩ wĩosa ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ; yĩmwe yĩthĩwe nthembo ya kũvĩvw’a, na yĩla yĩngĩ yĩthĩwe nthembo ya naĩ: na mũthembi akathembe ĩ nthembo ya wĩw’anĩthyo kwondũ wake, na akeethĩwa mũtheu.'),
('kam', 'LEV', 13, 1, 'Na Yeova aneena na Mose na Aluni, akĩmea.'),
('kam', 'LEV', 13, 2, 'Yĩla mũndũ wĩĩthĩwa na vandũ vaimbu, kana ngũsĩ, kana vandũ vaw’engu kĩkondenĩ kya mwĩĩ wake, na vakatw’ĩka ũthĩn’yo wa mangũ kĩkondenĩ kya mwĩĩ wake, nĩvo ĩndĩ wĩetwe kwa mũthembi Aluni, kana kwa mwana ũmwe wake mũthembi:'),
('kam', 'LEV', 13, 3, 'na mũthembi akasisya ũla ũthĩn’yo kĩkondenĩ kya mwĩĩ wake: na ethĩwa maw’ĩa ala me ũthĩn’yonĩ nĩ maalyũku makethĩwa meũ, na ũthĩn’yo wooneka ũlikĩte nthĩnĩ kũthonoka kĩkonde kya mwĩĩ wake, nĩ ũthĩn’yo wa mangũ; na mũthembi akamũsisya, na kwasya nĩ mũvuku.'),
('kam', 'LEV', 13, 4, 'Na ethĩwa vandũ vau vaw’engu nĩ veũ kĩkondenĩ kya mwĩĩ wake, na vandũ vau vationeka ve valiku kũthonoka kĩkonde kya mwĩĩ wake, na maw’ĩa ma vo ti maalyũku makethĩwa meũ, nĩvo ĩndĩ mũthembi wĩmũvatha ũla wĩ na ũthĩn’yo mĩthenya mũonza:'),
('kam', 'LEV', 13, 5, 'na mũthembi akamũsisya mũthenya wa mũonza: na, sisya, ethĩwa nũkwona ũthĩn’yo ũũngamĩte, na ũthĩn’yo ndũendeee kĩkondenĩ, nĩvo ĩndĩ mũthembi wĩmũvatha mĩthenya ĩngĩ mũonza:'),
('kam', 'LEV', 13, 6, 'na mũthembi akamũsisya ĩngĩ mũthenya wa mũonza; na, sisya, ethĩwa ũthĩn’yo nĩwambĩlĩlye kũvoa, na ũthĩn’yo ndũendeee kĩkondenĩ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũtheu: ve ngũsĩ: nake akathambye ngũa syake, na akeethĩwa mũtheu.'),
('kam', 'LEV', 13, 7, 'Ĩndĩ ethĩwa ngũsĩ ĩkaendeea kĩkondenĩ, ĩtina wa kwĩyonan’ya kwake kwa mũthembi kwondũ wa kũthew’a kwake, akeeyonan’ye ĩngĩ kwa mũthembi:'),
('kam', 'LEV', 13, 8, 'na mũthembi akasisya: na, sisya, ethĩwa ngũsĩ nĩendeee kĩkondenĩ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũvuku: nĩ mangũ.'),
('kam', 'LEV', 13, 9, 'Yĩla mũndũ wĩ na ũthĩn’yo wa mangũ, nĩvo wĩetwe kwa mũthembi;'),
('kam', 'LEV', 13, 10, 'na mũthembi akasisya; na, sisya, ethĩwa ve vandũ vaimbũ veũ kĩkondenĩ, na maw’ĩa nĩ maalyũku makethĩwa meũ, na vandũnĩ vau vaimbu vakethĩwa nyama yumĩlĩte,'),
('kam', 'LEV', 13, 11, 'nĩ mangũ ma tene kĩkondenĩ kya mwĩĩ wake, na mũthembi akasya nĩ mũvuku: ndakamũvathe; nũndũ nĩ mũvuku.'),
('kam', 'LEV', 13, 12, 'Na ethĩwa mangũ makaumĩla na kũendeea kĩkondenĩ, na mangũ asu makeekunĩkĩlya kĩkonde kyonthe kya ũla wĩ na ũthĩn’yo ũsu kuma mũtwe kũvika maũũ make, o ũndũ mũthembi wĩona;'),
('kam', 'LEV', 13, 13, 'nĩvo ĩndĩ mũthembi wĩsisya; na, sisya, ethĩwa mangũ nĩmekunĩkĩlĩtye mwĩĩ wake w’onthe, akasya nĩ mũtheu ũla wĩ na ũthĩn’yo ũsu: w’onthe ũalyũkĩte ũkethĩwa mweũ: nake nĩ mũtheu.'),
('kam', 'LEV', 13, 14, 'Ĩndĩ o yĩla nyama yumĩlĩte ĩkoneka mũndũnĩ ũsu akeethĩwa mũvuku.'),
('kam', 'LEV', 13, 15, 'Na mũthembi akasisya nyama ĩsu yumĩlĩte, na kwasya nĩ mũvuku: nyama ĩsu yumĩlĩte nĩ mbuku: nĩ mangũ.'),
('kam', 'LEV', 13, 16, 'Kana ethĩwa nyama ĩsu yumĩlĩte ĩkaalyũka ĩngĩ, ĩkethĩwa nzaũ, nĩvo ĩndĩ wĩenda kwa mũthembi;'),
('kam', 'LEV', 13, 17, 'na mũthembi akamũsisya; na, sisya, ethĩwa ũthĩn’yo ũsu nĩ mũalyũku ũkethĩwa mweũ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũtheu ũla wĩ na ũthĩn’yo: nake nĩ mũtheu.'),
('kam', 'LEV', 13, 18, 'Na yĩla mwĩĩ wĩĩthĩwa na mũimũ kĩkondenĩ kyaw’o, naw’o ũivoa,'),
('kam', 'LEV', 13, 19, 'na vandũ vala vaĩ mũimũ ũsu ve vandũ vaimbu veũ, kana vandũ vaw’engu vatune vanini, akamwon’ye mũthembi vandũ vau;'),
('kam', 'LEV', 13, 20, 'na mũthembi akasisya; na, sisya, ethĩwa kwoneka kwa vo nĩ valiku kũthonoka kĩkonde, na maw’ĩa ma vo nĩ maalyũku makethĩwa meũ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũvuku: nĩ ũthĩn’yo wa mangũ, nĩwumĩlĩte mũimũnĩ.'),
('kam', 'LEV', 13, 21, 'Ĩndĩ ethĩwa mũthembi akavasisya, na, sisya, vati maw’ĩa meũ nthĩnĩ wa vo, na ethĩwa tĩ valiku kũthonoka kĩkonde, ĩndĩ nĩvambĩlĩlye kũvoa; nĩvo ĩndĩ mũthembi wĩmũvatha mĩthenya mũonza:'),
('kam', 'LEV', 13, 22, 'na ethĩwa vakaendeea kĩkondenĩ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũvuku: nĩ ũthĩn’yo.'),
('kam', 'LEV', 13, 23, 'Ĩndĩ ethĩwa vandũ vau vaw’engu vakekalaa o vamwe, na vaikaendeea, nĩ ĩlanga ya mũimũ; na mũthembi akasya nĩ mũtheu.'),
('kam', 'LEV', 13, 24, 'Kana yĩla mwĩĩ wĩ na vandũ veũlalaka kĩkondenĩ kyaw’o, na nyama ĩla yumĩlĩte vala veũlalaka ĩkatw’ĩka vandũ vaw’engu, vatune vanini, kana veũ;'),
('kam', 'LEV', 13, 25, 'nĩvo ĩndĩ mũthembi wĩvasisya; na, sisya, ethĩwa maw’ĩa ala me nthĩnĩ wa vandũ vau vaw’engu nĩ maalyũku makethĩwa meũ, na kwoneka kwa vo nĩ valiku kũthonoka kĩkonde; nĩ mangũ, nĩmaumĩlĩte nthĩnĩ wa vandũ veũlalaka: na mũthembi akasya nĩ mũvuku: nĩ ũthĩn’yo wa mangũ.'),
('kam', 'LEV', 13, 26, 'Ĩndĩ ethĩwa mũthembi akavasisya, na, sisya, vati maw’ĩa meũ nthĩnĩ wa vandũ vau vaw’engu, na ti valiku kũthonoka kĩkonde, ĩndĩ nĩvambĩlĩlye kũvoa; nĩvo ĩndĩ mũthembi wĩmũvatha mĩthenya mũonza:'),
('kam', 'LEV', 13, 27, 'na mũthembi akamũsisya mũthenya wa mũonza: na ethĩwa nĩveũendeea kĩkondenĩ, nĩvo ĩndĩ mũthembi wĩasya nĩ mũvuku: nĩ ũthĩn’yo wa mangũ.'),
('kam', 'LEV', 13, 28, 'Na ethĩwa vandũ vau vaw’engu vekalaa vamwe, na vatĩendeee kĩkondenĩ, ĩndĩ nĩvambĩlĩlye kũvoa; nĩ wimbu wa vala veũlalaka, na mũthembi akasya nĩ mũtheu: nũndũ nĩ ĩlanga ya vala veũlalaka.'),
('kam', 'LEV', 13, 29, 'Na yĩla mũndũ mũũme kana mũndũ mũka wĩ na ũthĩn’yo mũtwenĩ kana kĩng’ew’anĩ,'),
('kam', 'LEV', 13, 30, 'nĩvo ĩndĩ mũthembi wĩsisya ũthĩn’yo; na, sisya, ethĩwa kwoneka kwaw’o nĩ mũliku kũthonoka kĩkonde, na nthĩnĩ waw’o ve nzw’ĩĩ mbalaanĩku iilyĩ ĩuuku, nĩvo ĩndĩ mũthembi wĩasya nĩ mũvuku: ve kĩea, nĩ mangũ ma mũtwe kana ma kĩng’ew’a.'),
('kam', 'LEV', 13, 31, 'Na ethĩwa mũthembi akasisya ũthĩn’yo ũsu wa kĩea, na, sisya, kwoneka kwakyo ti kĩliku kũthonoka kĩkonde, na vati nzw’ĩĩ nziũ nthĩnĩ wakyo, nĩvo ĩndĩ mũthembi wĩmũvatha ũla wĩ na ũthĩn’yo wa kĩea kyu mĩthenya mũonza:'),
('kam', 'LEV', 13, 32, 'na mũthenya wa mũonza mũthembi akasisya ũthĩn’yo ũsu; na, sisya, ethĩwa kĩea kĩtiendeee, na nthĩnĩ wakyo vati nzw’ĩĩ iilyĩ ĩuuku, na kwoneka kwa kĩea ti kĩliku kũthonoka kĩkonde,'),
('kam', 'LEV', 13, 33, 'nĩvo ĩndĩ wĩenzwa, ĩndĩ ndakenzwe vala ve kĩea; na mũthembi akamũvathe ũla wĩ na kĩea mĩthenya mũonza ĩngĩ:'),
('kam', 'LEV', 13, 34, 'na mũthenya wa mũonza mũthembi akasisya kĩea; na, sisya, ethĩwa kĩea kĩtinaendeea kĩkondenĩ, na kwoneka kwakyo ti kĩliku kũthonoka kĩkonde; nĩvo ĩndĩ mũthembi wĩasya nĩ mũtheu: na akathambye ngũa syake, nake akeethĩwa mũtheu.'),
('kam', 'LEV', 13, 35, 'Ĩndĩ ethĩwa kĩea nĩkĩendeee kĩkondenĩ ĩtina wa kũthew’a kwake,'),
('kam', 'LEV', 13, 36, 'nĩvo mũthembi wĩmũsisya; na, sisya, ethĩwa kĩea nĩkĩendeee kĩkondenĩ, mũthembi ndakamanthe nzw’ĩĩ iilyĩ ĩuuku; nĩ mũvuku.'),
('kam', 'LEV', 13, 37, 'Ĩndĩ ethĩwa nũnũkwona kĩea kĩũngamĩte, na nzw’ĩĩ nziũ nikũmea nthĩnĩ wa kĩea; kĩea nĩkĩvoete, nake nĩ mũtheu: na mũthembi akasya nĩ mũtheu.'),
('kam', 'LEV', 13, 38, 'Na yĩla mũndũ mũũme kana mũndũ mũka wĩ na kũndũ kũw’engu kĩkondenĩ kya mwĩĩ, o kũw’engu kweũ;'),
('kam', 'LEV', 13, 39, 'nĩvo mũthembi wĩsisya; na, sisya, ethĩwa kũndũ kũu kũw’engu kĩkondenĩ kya mwĩĩ kũkethĩwa kweu vanini, nĩ mũvĩvya, nĩwumĩlĩte kĩkondenĩ; nake nĩ mũtheu.'),
('kam', 'LEV', 13, 40, 'Na ethĩwa nzw’ĩĩ sya mũndũ nĩ ngunyũku mũtwe, e ũvaa; ĩndĩ nĩ mũtheu.'),
('kam', 'LEV', 13, 41, 'Na ethĩwa nzw’ĩĩ nĩ ngunyũku mũtwe kuma ũthyũnĩ, we e ũvaa wa kĩtulya; ĩndĩ nĩ mũtheu.'),
('kam', 'LEV', 13, 42, 'Ĩndĩ ethĩwa ve ũthĩn’yo mũtune vanini mũtwenĩ ũla wĩ ũvaa katĩ, kana kĩtulyanĩ kya ũthyũ kĩ ũvaa; nĩ mangũ maumĩlĩte mũtwenĩ wake wĩ ũvaa katĩ, kana kĩtulyanĩ kya ũthyũ kĩ ũvaa.'),
('kam', 'LEV', 13, 43, 'Nĩvo mũthembi wĩmũsisya; na, sisya, ethĩwa wimbu wa ũthĩn’yo nĩ mũtune vanini mũtwenĩ wake wĩ ũvaa, kana kĩtulyanĩ kyake kya ũthyũ kĩ ũvaa, ũkyoneka ta mangũ kĩkondenĩ kya mwĩĩ;'),
('kam', 'LEV', 13, 44, 'we nĩ mũndũ wĩ na mangũ, nĩ mũvuku; mũthembi ndatĩa kwasya nĩ mũvuku; ũthĩn’yo wake wĩ mũtwenĩ wake.'),
('kam', 'LEV', 13, 45, 'Na ũla wĩ na ũthĩn’yo ũsu, ngũa syake ikatembũangwe, na nzw’ĩĩ sya mũtwe wake ikavuwe, na akavw’ĩke kĩlomo kyake kya ĩũlũ, na kũneena na wasya mũnene, Mũvuku, mũvuku.'),
('kam', 'LEV', 13, 46, 'Mĩthenya yonthe ĩla wĩĩthĩwa na ũthĩn’yo akeethĩwa mũvuku; nake nĩ mũvuku: akekale e weka; ũtũo wake ũkeethĩwa ũtee wa mwako wa maeema.'),
('kam', 'LEV', 13, 47, 'Na ngũa ĩla yĩ na ũthĩn’yo wa mangũ nthĩnĩ wayo, ethĩwa nĩ ngũa ĩtumĩtwe ya maw’ĩa ma malondu, kana ngũa ya katane;'),
('kam', 'LEV', 13, 48, 'ethĩwa wĩ mbeinĩ, kana mbĩnonĩ; ngũanĩ ya katane, kana ya maw’ĩa ma malondu; ethĩwa wĩ kĩthumanĩ, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma;'),
('kam', 'LEV', 13, 49, 'ethĩwa ũthĩn’yo ũilyĩ waiũ kana mũtune wĩ ngũanĩ, kana kĩthumanĩ, kana mbeinĩ, kana mbĩnonĩ, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma; nĩ ũthĩn’yo wa mangũ, na mũvaka ũkonanw’e kwa mũthembi.'),
('kam', 'LEV', 13, 50, 'Na mũthembi akasisya ũthĩn’yo, na akavathe kĩla kĩ na ũthĩn’yo mĩthenya mũonza:'),
('kam', 'LEV', 13, 51, 'na akasisya ũthĩn’yo mũthenya wa mũonza: ethĩwa ũthĩn’yo nũendeee ngũanĩ, ethĩwa wĩ mbeinĩ, kana mbĩnonĩ, kana kĩthumanĩ, kĩthuma kya wĩa o na wĩva; ũthĩn’yo nĩ mangũ mai; nĩ mbuku.'),
('kam', 'LEV', 13, 52, 'Na akavĩvye ngũa, ethĩwa nĩ mbei kana mbĩno, ngũanĩ ya maw’ĩa ma ĩlondu kana ya katane, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma, kĩla kĩ na ũthĩn’yo nthĩnĩ wakyo: nũndũ nĩ mangũ mai; kĩvĩvw’e na mwaki.'),
('kam', 'LEV', 13, 53, 'Na ethĩwa mũthembi akasisya, na, sisya, ũthĩn’yo ndũnaendeea ngũanĩ, mbeinĩ, kana mbĩnonĩ, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma;'),
('kam', 'LEV', 13, 54, 'nĩvo mũthembi wĩtw’a mathambye kĩndũ kĩla kĩ na ũthĩn’yo nthĩnĩ wakyo, na akakĩvathe mĩthenya mũonza ĩngĩ:'),
('kam', 'LEV', 13, 55, 'na mũthembi akasisya, ĩtina wa kũthambw’a kwa ũthĩn’yo; na, sisya, ethĩwa ũthĩn’yo ndũnaalyũka langi waw’o, na ũthĩn’yo ndũnaendeea, nĩ mbuku; mĩvĩvye na mwaki: nĩ wai, ethĩwa ũvaa wĩ nthĩnĩ kana ũtee.'),
('kam', 'LEV', 13, 56, 'Na ethĩwa mũthembi akasisya, na, sisya, ũthĩn’yo nĩwambĩlĩlye kũvoa ĩtina wa kũthambw’a kwaw’o, nĩvo ĩndĩ wĩvatembũa aumye vala ve ũthĩn’yo ngũanĩ, kana kĩthumanĩ, kana mbeinĩ, kana mbĩnonĩ:'),
('kam', 'LEV', 13, 57, 'na ethĩwa ĩtina wa kwĩka ũu ũkooneka ngũanĩ, ethĩwa nĩ mbeinĩ kana mbĩnonĩ, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma, nũkumĩla: vĩvya na mwaki kĩndũ kĩla kĩ na ũthĩn’yo.'),
('kam', 'LEV', 13, 58, 'Na ngũa, mbei kana mbĩno, kana kĩndũ o na kĩva kĩseũvĩtw’e kya kĩthuma, kĩla wĩthambya, ethĩwa ũthĩn’yo nĩwumĩte nthĩnĩ wasyo, kĩkathambwe ĩvinda ya kelĩ, na kĩkeethĩwa kĩtheu.'),
('kam', 'LEV', 13, 59, 'Ũsu nĩw’o mwĩao wa ũthĩn’yo wa mangũ ngũanĩ ĩtumĩtwe na maw’ĩa ma ĩlondu kana ya katane, mbeinĩ kana mbĩnonĩ, kana kĩndũnĩ o na kĩva kĩseũvĩtw’e kya kĩthuma, wa kwasya nĩ kĩtheu, kana kwasya nĩ kĩvuku.'),
('kam', 'LEV', 14, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 14, 2, 'Ũũ ũkeethĩwa mwĩao wa ũla wĩ na mangũ mũthenya wa kũthew’a kwake: akaetwe kwa mũthembi:'),
('kam', 'LEV', 14, 3, 'na mũthembi akaumaale kuma mwakonĩ wa maeema; na mũthembi akasisya; na, sisya, ethĩwa ũthĩn’yo wa mangũ nũvoete mũndũnĩ ũla wĩ na mangũ,'),
('kam', 'LEV', 14, 4, 'nĩvo mũthembi wĩtw’a kana nyũnyi ilĩ ntheu syĩ thayũ ietwe kwondũ wa ũla wĩthew’a, vamwe na mũtĩ wa mũkũũ, na langi mũtune mũno, na ĩsovo:'),
('kam', 'LEV', 14, 5, 'na mũthembi akatw’a nyũnyi ĩmwe yũaĩwe kĩndũnĩ kya yũmba ĩũlũ wa manzĩ mavĩtĩte.'),
('kam', 'LEV', 14, 6, 'Na nyũnyi ĩla ĩngĩ yĩ thayũ, akamyose, vamwe na mũtĩ wa mũkũũ, na langi mũtune mũno, na ĩsovo, na akailikye vamwe na nyũnyi yĩ thayũ nthakamenĩ ya nyũnyi ĩla yũaĩwe ĩũlũ wa manzĩ mavĩtĩte:'),
('kam', 'LEV', 14, 7, 'na akamũminzangĩsye mũndũ ũla wa kũthew’a mangũ maminzangĩsya mũonza, na akasya nĩ mũtheu, na akalekye nyũnyi yĩ thayũ ĩthi weũnĩ.'),
('kam', 'LEV', 14, 8, 'Na ũla wa ũthew’a akathambye ngũa syake, na kwenza nzw’ĩĩ syake syonthe, na kũthamba manzĩnĩ; na akeethĩwa mũtheu: na ĩtina wa ũu akasyoka mwakonĩ wa maeema, ĩndĩ akekala ũtee wa ĩeema yake mĩthenya mũonza.'),
('kam', 'LEV', 14, 9, 'Na kũkeethĩwa mũthenya wa mũonza, akenze nzw’ĩĩ syake syonthe mũtwenĩ wake na kĩng’ew’a kyake na syĩnthakuva syake, o nzw’ĩĩ syake syonthe akenze: na akathambye ngũa syake, na akathambe mwĩĩ wake manzĩnĩ, na akeethĩwa mũtheu.'),
('kam', 'LEV', 14, 10, 'Na mũthenya wa nyanya akose tũtũlũme twĩlĩ tũte kĩema, na kamwatĩ kamwe ka mwaka ũmwe kate kĩema, na ilungu itatũ sya ĩkũmi sya eva ya mũtu mũvinyu wĩthĩwe nthembo ya mũtu, ũvulanĩtw’e na mauta, na kĩthimi kĩtawa loki ya mauta.'),
('kam', 'LEV', 14, 11, 'Na mũthembi ũla wĩmũthesya akamwĩkalya mũndũ ũla wĩthew’a, vamwe na syĩndũ isu, mbee wa Yeova, mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 14, 12, 'Na mũthembi akose kamwe ka tũla tũtũlũme, na kũkathemba kethĩwe nthembo ya ĩvĩtyo, vamwe na loki ya mauta, na kwivyũlangya syĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova:'),
('kam', 'LEV', 14, 13, 'na akoaĩe katũlũme vandũ vala moaĩaa nthembo ya naĩ na nthembo ya kũvĩvw’a, vala vandũ vatheu: o tondũ nthembo ya naĩ nĩ ya mũthembi, o ta ũu nthembo ya ĩvĩtyo nĩ yake: nĩ ntheu mũno.'),
('kam', 'LEV', 14, 14, 'Na mũthembi akose nthakame ĩmwe ya nthembo ya ĩvĩtyo, na mũthembi akamĩvaka mũthyanĩ wa kũtũ kwa ngalĩ ya kw’oko kwa aũme kwa ũla wa kũthew’a, na kyaanĩ kĩnene kya kw’oko kwake kwa aũme, na kyaanĩ kĩnene kya kũũ kwake kwa aũme.'),
('kam', 'LEV', 14, 15, 'Na mũthembi akose kĩthiminĩ kĩtawa loki ya mauta, na kwĩkĩa kĩtaanĩ kya kw’oko kwake kwa aka;'),
('kam', 'LEV', 14, 16, 'na mũthembi akatolye kyaa kyake kya kw’oko kwa aũme mautanĩ ala me kw’okonĩ kwa aka, na kũminzangĩsya mauta na kyaa kyake maminzangĩsya mũonza mbee wa Yeova.'),
('kam', 'LEV', 14, 17, 'Na ma mauta ala metiala kw’okonĩ kwake mũthembi akamavake mũthyanĩ wa kũtũ kwa ngalĩ ya kw’oko kwa aũme kwa ũla wĩthew’a, na kyaanĩ kĩnene kya kw’oko kwake kwa aũme, na kyaanĩ kĩnene kya kũũ kwake kwa aũme, vala ve nthakame ya nthembo ya ĩvĩtyo;'),
('kam', 'LEV', 14, 18, 'na mauta ala metiala kw’okonĩ kwa mũthembi akekĩe mũtwenĩ wa ũla wĩthew’a: na mũthembi akathembe nthembo ya wĩw’anĩthyo kwondũ wake mbee wa Yeova.'),
('kam', 'LEV', 14, 19, 'Na mũthembi akathembe nthembo ya naĩ, na kũmwĩw’anĩthya ũla wĩthew’a nũndũ wa ũvuku wake: na ĩtina akooaa nthembo ya kũvĩvw’a;'),
('kam', 'LEV', 14, 20, 'na mũthembi akathembe nthembo ya kũvĩvw’a na nthembo ya mũtu kĩthembeonĩ; na mũthembi akathembe nthembo ya wĩw’anĩthyo kwondũ wake, na akeethĩwa mũtheu.'),
('kam', 'LEV', 14, 21, 'Na ethĩwa nĩ ngya, na ndatonya kũsyona, nĩvo ĩndĩ wĩtwaa katũlũme kamwe kethĩwe nthembo ya ĩvĩtyo ka kũvyũlangw’a, ka wĩw’anĩthyo kwondũ wake, na kĩlungu kya ĩkũmi kya eva ya mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu, na loki ya mauta;'),
('kam', 'LEV', 14, 22, 'na ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ, o ũndũ ũtonya kwona; na ĩmwe ĩkeethĩwa nthembo ya naĩ, na ĩla ĩngĩ nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 14, 23, 'Na mũthenya wa nyanya akaiete kwa mũthembi kwondũ wa kũthew’a kwake, mũomonĩ wa ĩeema ya kũmbanĩa, mbee wa Yeova:'),
('kam', 'LEV', 14, 24, 'na mũthembi akose katũlũme ka nthembo ya ĩvĩtyo, na loki ya mauta, na mũthembi akaivyũlangya syĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova.'),
('kam', 'LEV', 14, 25, 'Na akoae katũlũme ka nthembo ya ĩvĩtyo; na mũthembi akose nthakame ĩmwe ya nthembo ya ĩvĩtyo, na kũmĩvaka mũthyanĩ wa kũtũ kwa ngalĩ ya kw’oko kwa aũme kwa ũla wĩthew’a, na kyaanĩ kĩla kĩnene kya kw’oko kwake kwa aũme, na kyaanĩ kĩla kĩnene kya kũũ kwake kwa aũme.'),
('kam', 'LEV', 14, 26, 'Na mũthembi akekĩe mauta amwe kĩtaanĩ kyake kya kw’oko kwa aka;'),
('kam', 'LEV', 14, 27, 'na mũthembi akaminzangĩsye na kyaa kyake kya kw’oko kwa aũme mauta amwe me kw’okonĩ kwake kwa aka maminzangĩsya mũonza mbee wa Yeova:'),
('kam', 'LEV', 14, 28, 'na mũthembi akavake mauta amwe ala me kw’okonĩ kwake mũthyanĩ wa kũtũ kwa ngalĩ ya kw’oko kwa aũme kwa ũla wĩthew’a, na kyaanĩ kĩla kĩnene kya kw’oko kwake kwa aũme, na kyaanĩ kĩnene kya kũũ kwake kwa aũme, vala ve nthakame ya nthembo ya ĩvĩtyo:'),
('kam', 'LEV', 14, 29, 'na mauta ala metiala kw’okonĩ kwa mũthembi akekĩe mũtwenĩ wa ũla wĩthew’a, methĩwe ma wĩw’anĩthyo kwondũ wake mbee wa Yeova.'),
('kam', 'LEV', 14, 30, 'Na akathembe ĩmwe ya ila ndumbũ, kana yĩmwe ya maswii ma ĩvũĩ, o ũndũ ũtonya kwona,'),
('kam', 'LEV', 14, 31, 'o ũndũ ũtonya kwona, ĩmwe yĩthĩwe nthembo ya naĩ, na ĩla ĩngĩ yĩthĩwe nthembo ya kũvĩvw’a, vamwe na nthembo ya mũtu: na mũthembi akathembe nthembo ya wĩw’anĩthyo kwondũ wa ũla wĩthew’a mbee wa Yeova.'),
('kam', 'LEV', 14, 32, 'Ũsu nĩw’o mwĩao wa ũla wĩ na ũthĩn’yo wa mangũ, ũla ũtatonya kwona kĩla kya kũthew’a kwake.'),
('kam', 'LEV', 14, 33, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'LEV', 14, 34, 'Mwalika nthĩ ya Kanaani, ĩla nĩmũnengae yĩthĩwe ng’ũndũ yenyu, na neekĩa ũthĩn’yo wa mangũ nyũmbanĩ yĩ nthĩ ya ng’ũndũ yenyu;'),
('kam', 'LEV', 14, 35, 'nĩvo ĩndĩ mwene nyũmba wĩthi kũtavya mũthembi, akĩmwĩa, Nĩngwona nyie kana ve ũthĩn’yo nyũmbanĩ.'),
('kam', 'LEV', 14, 36, 'Na mũthembi akatw’a maumaalye mĩio yonthe nyũmba ĩtiwe yĩ nthei, mũthembi atanalika kũsisya ũthĩn’yo, mĩio yonthe yĩ nyũmbanĩ ndĩkavukw’e: na ĩtina mũthembi akalika asisye nyũmba:'),
('kam', 'LEV', 14, 37, 'nake akasisya ũthĩn’yo; na, sisya, ethĩwa ũthĩn’yo wĩ mawakonĩ ma nyũmba wĩ myalĩkanĩ, yĩ langi wĩ waiũ kana mũtune, na kwoneka kwaw’o nĩ mũliku nthĩnĩ wakonĩ;'),
('kam', 'LEV', 14, 38, 'nĩvo mũthembi wĩuma nyũmbanĩ kũvika mũomonĩ wa nyũmba, na kũvinga nyũmba mĩthenya mũonza.'),
('kam', 'LEV', 14, 39, 'Na mũthembi akasyoka mũthenya wa mũonza, na akasisya; na, sisya, ethĩwa ũthĩn’yo nũendeee mawakonĩ ma nyũmba;'),
('kam', 'LEV', 14, 40, 'nĩvo ĩndĩ mũthembi wĩtw’a maumye mavia ala me na ũthĩn’yo nthĩnĩ, na kũmekya vandũ vavuku ũtee wa ndũa:'),
('kam', 'LEV', 14, 41, 'na akatuma nyũmba ĩsu ĩvalavalwa nthĩnĩ ngalĩ syonthe, na makete mũthanga ũla mavalavalile, ũtee wa ndũa vandũ vavuku:'),
('kam', 'LEV', 14, 42, 'na makose mavia angĩ, na kũmekĩa vandũ va mavia asu; na akose ndaka ĩngĩ, na kũvaka nyũmba.'),
('kam', 'LEV', 14, 43, 'Na ethĩwa ũthĩn’yo nũũsyoka, na kumĩla nyũmbanĩ, amina kumya mavia, na amina kũvalavala nyũmba, na yathela kũvakwa ndaka;'),
('kam', 'LEV', 14, 44, 'nĩvo mũthembi wĩlika na kũsisya; na, sisya, ethĩwa ũthĩn’yo nũendeee nyũmbanĩ, nĩ mangũ mai nyũmbanĩ: nĩ mbuku.'),
('kam', 'LEV', 14, 45, 'Na akamĩomboe nyũmba, mavia mayo, na mĩtĩ yayo, na ndaka yonthe ya nyũmba; na akaitwaa ũtee wa ndũa vandũ vavuku.'),
('kam', 'LEV', 14, 46, 'Na ĩngĩ ũla wĩlika nyũmbanĩ ĩvinda yonthe yĩ mbinge akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 14, 47, 'Na ũla wĩkoma ĩ nyũmba akathambye ngũa syake; na ũla wĩĩa ĩ nyũmba akathambye ngũa syake.'),
('kam', 'LEV', 14, 48, 'Na ethĩwa mũthembi akalika, na kũsisya, na, sisya, ũthĩn’yo ndũnaendeea nyũmbanĩ, nyũmba yathela kũvakwa ndaka; nĩvo ĩndĩ mũthembi wĩasya nyũmba nĩ ntheu, nĩkwĩthĩwa ũthĩn’yo nĩ mũthelu.'),
('kam', 'LEV', 14, 49, 'Na akose nyũnyi ilĩ sya kũthesya nyũmba, na mũtĩ wa mũkũũ, na langi mũtune mũno, na ĩsovo:'),
('kam', 'LEV', 14, 50, 'na akoaĩe nyũnyi ĩmwe kĩndũnĩ kya yũmba ĩũlũ wa manzĩ mavĩtĩte:'),
('kam', 'LEV', 14, 51, 'na akose ũla mũtĩ wa mũkũũ, na ĩsovo, na langi mũtune mũno, na nyũnyi yĩ thayũ, na kũlikya nthakamenĩ ya nyũnyi ĩla mbũae, na manzĩnĩ mavĩtĩte, na kũminzangĩsya nyũmba maminzangĩsya mũonza:'),
('kam', 'LEV', 14, 52, 'na akathesye nyũmba na nthakame ya nyũnyi ĩsu, na manzĩ ala mavĩtĩte, na nyũnyi yĩ thayũ, na mũtĩ ũsu wa mũkũũ, na ĩsovo, na langi mũtune mũno:'),
('kam', 'LEV', 14, 53, 'ĩndĩ akamĩlekye nyũnyi yĩ thayũ ĩende ũtee wa ndũa weũnĩ: o ta ũu akathembe nthembo ya wĩw’anĩthyo kwondũ wa nyũmba; na ĩkeethĩwa ntheu.'),
('kam', 'LEV', 14, 54, 'Ũsu nĩw’o mwĩao kwondũ wa mĩthemba yonthe ya ũthĩn’yo wa mangũ na wa kĩea,'),
('kam', 'LEV', 14, 55, 'na wa mangũ me ngũanĩ, na wa nyũmba,'),
('kam', 'LEV', 14, 56, 'na wa vandũ vaimbu, na wa ngũsĩ, na wa vandũ vaw’engu;'),
('kam', 'LEV', 14, 57, 'kũmanyĩsya yĩla wĩĩthĩwa mũvuku, na yĩla wĩĩthĩwa mũtheu: ũu nĩw’o mwĩao wa mangũ.'),
('kam', 'LEV', 15, 1, 'Na Yeova aneena na Mose na Aluni, akyasya,'),
('kam', 'LEV', 15, 2, 'Neenai na ana ma Isilaeli, noimea, Mũndũ o na wĩva e na mũluo kuma mwĩĩnĩ wake, nĩ mũvuku kwondũ wa mũluo wake.'),
('kam', 'LEV', 15, 3, 'Na ũvuku wake nĩ ũũ nthĩnĩ wa mũluo wake: ethĩwa mwĩĩ wake wĩumya mavia ma mũluo wake, kana ethĩwa mũluo wake nũsiĩĩwa mwĩĩnĩ wake, nĩ ũvuku wake.'),
('kam', 'LEV', 15, 4, 'Ũkomo o na wĩva ũla ũsu wĩ na mũluo ũkomee ũkeethĩwa wĩ mũvuku; na kĩla kĩndũ wĩĩkalĩla kĩkeethĩwa kĩ kĩvuku.'),
('kam', 'LEV', 15, 5, 'Na o ũla wĩkiita ũkomo wake mũvaka athambye ngũa syake, na akathamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 6, 'Na ũla wĩĩkalĩla kĩndũ kĩla kĩkalĩlwe nĩ ũla wĩ na mũluo mũvaka athambye ngũa syake, na akathamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 7, 'Na ũla wĩkiita mwĩĩ wa ũsu wĩ na mũluo mũvaka athambye ngũa syake, na akathamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 8, 'Na ethĩwa mũndũ ũsu wĩ na mũluo akamũtwĩla mata ũla mũtheu, nĩvo ĩndĩ wĩthambya ngũa syake, na akathamba na manzĩ, na akeethĩwa e mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 9, 'Na ĩtandĩko o na yĩva ũla wĩ na mũluo wĩtũla yĩkeethĩwa yĩ ĩvuku.'),
('kam', 'LEV', 15, 10, 'Na o ũla wĩkiita kĩndũ kĩla ũsu eĩtũlĩte akeethĩwa e mũvuku kũvika wĩoo: na ũla wĩkua syĩndũ isu akathambye ngũa syake, na kũthamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 11, 'Na o ũla wĩkiitwa nĩ ũsu wĩ na mũluo, atathambĩte moko na manzĩ, mũvaka athambye ngũa syake, na akathamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 12, 'Na kĩndũ kya yũmba, kĩla ũla wĩ na mũluo wĩkiita, mũvaka kyũawe; na kĩla kĩndũ kya mũtĩ kĩkathambw’e na manzĩ.'),
('kam', 'LEV', 15, 13, 'Na ũsu wĩ na mũluo athew’a mũluo wake, nĩvo wĩĩtalĩla mwene matukũ mũonza ma kũthew’a kwake, na akathambye ngũa syake; na kũthamba mwĩĩ wake na manzĩ mavĩtĩte, na akeethĩwa e mũtheu.'),
('kam', 'LEV', 15, 14, 'Na mũthenya wa nyanya akeeyosea ndumbũ ilĩ, kana maswii elĩ ma mavũĩ, nake akathi mbee wa Yeova mũomonĩ wa ĩeema ya kũmbanĩa, na akamũnenga mũthembi:'),
('kam', 'LEV', 15, 15, 'nake mũthembi akaithembe, ĩmwe ĩthĩwe nthembo ya naĩ, na ĩla ĩngĩ ĩthĩwe nthembo ya kũvĩvw’a; na mũthembi akamwĩw’anĩthya ũsu na Yeova kwondũ wa mũluo wake.'),
('kam', 'LEV', 15, 16, 'Ethĩwa mũndũ akaumwa nĩ ũsamba wake, nĩvo ĩndĩ athambe mwĩĩ wake w’onthe na manzĩ, na akeethĩwa mũvuka kũvika wĩoo.'),
('kam', 'LEV', 15, 17, 'Na kĩla ngũa, na kĩla kĩthuma, kĩ na ũsamba, ikathambw’e na manzĩ, na ikeethĩwa syĩ mbuku kũvika wĩoo.'),
('kam', 'LEV', 15, 18, 'Na mũndũ mũka nake ũla wĩkoma na mũndũ mũũme e na ũsamba, no mũvaka mathambe me elĩ na manzĩ, na kwĩthĩwa avuku kũvika wĩoo.'),
('kam', 'LEV', 15, 19, 'Na ethĩwa mũndũ mũka eumwa nĩ kĩndũ, na kĩndũ kyake kĩla wĩ nakyo mwĩĩnĩ wake nĩ nthakame, kũvathwa kwake nĩ ĩvinda ya matukũ mũonza: na o ũla wĩmũkiita akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 20, 'Na kĩndũ o na kĩva kyonthe kĩla wĩkomea yĩla ũvathĩtwe kĩkeethĩwa kivuku: na kĩndũ o na kĩva nakyo kĩla wĩĩkalĩla kĩkeethĩwa kĩvuku.'),
('kam', 'LEV', 15, 21, 'Na mũndũ mũũme o ũla wĩkiita ũkomo wake akathambye ngũa syake, na kũthamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 22, 'Na o ũla wĩkiita kĩndũ o na kĩva ũkĩkalĩle no mũvaka athambye ngũa syake, na akathamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 23, 'Ethĩwa nĩ ĩũlũ wa ũkomo, kana ĩũlũ wa kĩndũ o na kĩva kĩla wĩĩkalĩla, mũndũ mũũme akĩkiita akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 24, 'Na ethĩwa mũndũ mũũme akakoma nake, na ũvuku wake ũkĩthĩwa ĩũlũ wake, ũ mũndũ mũũme akeethĩwa mũvuku matukũ mũonza; na kĩla ũkomo wĩkomeaa ũkeethĩwa mũvuku.'),
('kam', 'LEV', 15, 25, 'Na ethĩwa mũndũ mũka eumwa nĩ nthakame yake mĩthenya mingĩ, na ti ĩvinda ya kwĩalũla kwake, kana ethĩwa eumwa ni nthakame kũvĩtũka ivinda ya kwĩalũla kwake; mĩthenya yonthe ya kumwa nthakame ya ũvuku wake akeethĩwa o ta mĩthenyanĩ ya kwĩalũla kwake: nĩ mũvuku.'),
('kam', 'LEV', 15, 26, 'Kĩla ũkomo wĩkomeaa mĩthenya yonthe ya kumwa kwake kwa nthakame ũkeethĩwa kwake ta ũkomo wa kwĩalũla kwake: na kĩla kĩndũ wĩĩkalĩla kĩkeethĩwa kĩvuku, o ta ũvuku wa kwĩalũla kwake.'),
('kam', 'LEV', 15, 27, 'Na mũndũ mũũme o ũla wĩkiita syĩndũ isu akeethĩwa mũvuku, na akathambye ngũa syake, na kũthamba na manzĩ, na akeethĩwa mũvuku kũvika wĩoo.'),
('kam', 'LEV', 15, 28, 'Ĩndĩ ethĩwa akathew’a kwa kumwa kwake kwa nthakame, nĩvo ĩndĩ wĩĩtalĩla mwene mĩthenya mũonza, na ĩtina wa ũu akeethĩwa mũtheu.'),
('kam', 'LEV', 15, 29, 'Na mũthenya wa nyanya akeeyosea ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ, na kũmũtwaĩa mũthembi, mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 15, 30, 'Na mũthembi akathembe yĩmwe yĩthĩwe nthembo ya naĩ, na yĩla yĩngĩ yĩthĩwe nthembo ya kũvĩvw’a; na mũthembi akamwĩw’anĩthya ũsu mbee wa Yeova kwondũ wa kumwa kwa nthakame yake kwa ũvuku wake.'),
('kam', 'LEV', 15, 31, 'Ũu nĩw’o mwĩvathanasya ana ma Isilaeli na ũvuku woo, matikakw’e ũvukunĩ woo, o yĩla mevukya ũla wĩkalo wakwa ũla wĩ katĩ woo.'),
('kam', 'LEV', 15, 32, 'Ũsu nĩw’o mwĩao kwa ũla wĩ na mũluo, na kwa ũla wĩumwa nĩ ũsamba wake, ũndũ watumie avuka;'),
('kam', 'LEV', 15, 33, 'na kwa ũla wĩalũlĩte, na kwa ũla wĩumwa nĩ nthakame, kwa mũndũ mũũme, na kwa mũndũ mũka, na kwa ũla wĩkoma na mũndũ mũka mũvuku.'),
('kam', 'LEV', 16, 1, 'Na Yeova aneena na Mose, ĩtina wa kĩkw’ũ kya ala ana elĩ ma Aluni, yĩla mamũthengeeie Yeova, na makw’a;'),
('kam', 'LEV', 16, 2, 'na Yeova amwĩa Mose, Neena na Aluni mwana‐a‐mwenyu, ndakalikae mavinda onthe vala vandũ vatheu nthĩnĩ wa tũtũ, mbee wa wĩkalo wa tei ũla wĩ ĩũlũ wa yĩla ĩsandũkũ; nĩ kana Ndakakw’e: nũndũ ngeeyonan’ya nĩ mũumbĩnĩ ĩũlũ wa wĩkalo wa tei.'),
('kam', 'LEV', 16, 3, 'Aluni akalikaa vala vandũ vatheu e na syĩndũ ii: kasalũ kethĩwe nthembo ya naĩ, na ndũũme yĩthĩwe nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 16, 4, 'Akekĩaa ũla kanzũ mũtheu wa katane, na akekĩaa ũla sulualĩ wa katane mwĩĩnĩ wake, na akeevotoaa mũsivi wa katane, na akeekĩaa ngutw’a ya katane: isu nĩsyo ngũa ntheu; na akathambe mwĩĩ wake na manzĩ, na kũsyĩkĩa.'),
('kam', 'LEV', 16, 5, 'Na akose ũmbanonĩ wa ana ma Isilaeli nthenge ilĩ syĩthĩwe nthembo ya naĩ, na ndũũme ĩmwe yĩthĩwe nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 16, 6, 'Na Aluni akaete kala kasalũ ka nthembo ya naĩ, nako nĩ kwondũ wake mwene, na kũkathemba kethĩwe wĩw’anĩthyo kwondũ wake mwene, na kwondũ wa nyũmba yake.'),
('kam', 'LEV', 16, 7, 'Na akose nthenge isu syelĩ, na kũsia mbee wa Yeova, mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'LEV', 16, 8, 'Na Aluni akaliman’ye nthenge isu syelĩ; kũliman’ya kũmwe kwĩthĩwe kwondũ wa Yeova, na kũliman’ya kũla kũngĩ kwĩthĩwe kwondũ wa Asaseli.'),
('kam', 'LEV', 16, 9, 'Na Aluni akaete nthenge ĩla yavalũkĩlwe nĩ mũlimano yĩthĩwe ya Yeova, na kũmĩthemba yĩthĩwe nthembo ya naĩ.'),
('kam', 'LEV', 16, 10, 'Ĩndĩ nthenge, ĩla yavalũkĩlwe nĩ mũlimano yĩthĩwe ya Asaseli, ĩkaekwe yĩ thayũ mbee wa Yeova, yĩthĩwe nthembo ya wĩw’anĩthyo, ĩlekw’e ĩthi weũnĩ yĩthĩwe ya Asaseli.'),
('kam', 'LEV', 16, 11, 'Na Aluni akaete kala kasalũ ka nthembo ya naĩ, nayo nĩ kwondũ wake mwene, na kũkathemba kethĩwe wĩw’anĩthyo kwondũ wake mwene, na kwondũ wa nyũmba yake, na akooaa kasalũ kau ka nthembo ya naĩ, ĩla yĩ kwondũ wake mwene.'),
('kam', 'LEV', 16, 12, 'Na akose kĩtoeesya kyusũĩtw’e makaa me mwaki kuma kĩthembeonĩ mbee wa Yeova, na mbĩ syusĩe ũvani wĩ mũuke mũseo mũkimange, na kũtwaa nthĩnĩ wa tũtũ:'),
('kam', 'LEV', 16, 13, 'na akekĩe ũvani mwakinĩ mbee wa Yeova, nĩ kana syũki ya ũvani yĩvw’ĩke wĩkalo wa tei ũla wĩ ĩũlũ wa yĩla ĩsandũkũ ya ũkũsĩ, nĩ kana ndakakw’e:'),
('kam', 'LEV', 16, 14, 'na akose nthakame ĩmwe ya kala kasalũ, na kũmĩminzangĩsya na kyaa kyake wĩkalonĩ wa tei ngalĩ ya wumĩlonĩ wa syũa; na akaminzangĩsye nthakame na kyaa kyake maminzangĩsya mũonza mbee wa wĩkalo wa tei.'),
('kam', 'LEV', 16, 15, 'Nĩvo ĩndĩ wĩũaa ĩla nthenge ya nthembo ya naĩ, ĩla yĩ kwondũ wa andũ, na kũete nthakame yayo nthĩnĩ wa tũtũ, na kwĩka na nthakame yayo o tondũ wekie na nthakame ya kala kasalũ, na kũmĩminzangĩsya wĩkalonĩ wa tei, na mbee wa wĩkalo wa tei:'),
('kam', 'LEV', 16, 16, 'na akathembe nthembo ya wĩw’anĩthyo kwondũ wa vala vandũ vatheu, nũndũ wa movuku ma ana ma Isilaeli, na nũndũ wa mavĩtyo moo, o naĩ syoo syonthe: na now’o ũkeka kwondũ wa ĩeema ya kũmbanĩa, yĩla yĩkalaa namo movukunĩ moo.'),
('kam', 'LEV', 16, 17, 'Na vatikethĩwe mũndũ o na wĩva ĩeemanĩ ya kũmbanĩa yĩla mũthembi wĩlika kũthemba nthembo ya wĩw’anĩthyo vala vandũ vatheu, kũvika yĩla wĩumaala, amina kũthemba nthembo ya wĩw’anĩthyo kwondũ wake mwene, na kwondũ wa andũ ma nyũmba yake, na kwondũ wa ũmbano w’onthe wa Isilaeli.'),
('kam', 'LEV', 16, 18, 'Na akaumaale aende vala ve kĩthembeo kĩla kĩ mbee wa Yeova, na kũthemba nthembo ya wĩw’anĩthyo kwondũ wakyo, na akose nthakame ĩmwe ya kala kasalũ, na nthakame ĩmwe ya ĩla nthenge, na kũmĩvaka mbyanĩ sya kĩthembeo ngalĩ syonthe.'),
('kam', 'LEV', 16, 19, 'Na akakĩminzangĩsye nthakame na kyaa kyake maminzangĩsya mũonza, na kũkĩthesya, na kũkĩvatha kĩthĩwe kĩtheu kwondũ wa movuku ma ana ma Isilaeli.'),
('kam', 'LEV', 16, 20, 'Na amina kũthemba nthembo ya wĩw’anĩthyo kwondũ wa vala vandũ vatheu, na ĩeema ya kũmbanĩa, na kĩthembeo, akaete ĩla nthenge yĩ thayũ:'),
('kam', 'LEV', 16, 21, 'na Aluni akailĩĩle moko make elĩ mũtwenĩ wa nthenge yĩ thayũ, na kumbũlĩla ĩũlũ wayo mothũku onthe ma ana ma Isilaeli, na mavĩtyo moo onthe, o naĩ syoo syonthe; nasyo akailĩĩle mũtwenĩ wa ĩla nthenge, na akamĩtwaĩthye weũnĩ na kw’oko kwa mũndũ ũla mũnyuve:'),
('kam', 'LEV', 16, 22, 'na nthenge ĩsu ĩkakua ĩũlũ wayo naĩ syoo syonthe ĩende nthĩ ĩte andũ: na mũndũ ũsu akalekya ĩla nthenge weũnĩ.'),
('kam', 'LEV', 16, 23, 'Na Aluni akalike ĩeemanĩ ya kũmbanĩa, na kumya ngũa sya katane ila wĩkĩe ailika vala vandũ vatheu, na kwitia vo:'),
('kam', 'LEV', 16, 24, 'na akathambĩa mwĩĩ wake na manzĩ vandũ vatheu, na kwĩkĩa ngũa syake, na kumaala, na kũthemba nthembo yake ya kũvĩvw’a na nthembo ya kũvĩvw’a ya andũ, syĩthĩwe wĩw’anĩthyo kwondũ wake mwene na kwondũ wa andũ.'),
('kam', 'LEV', 16, 25, 'Na mathunya ma nthembo ya naĩ akavĩvĩsye kĩthembeonĩ.'),
('kam', 'LEV', 16, 26, 'Na ũla wĩlekya nthenge ĩla yĩ kwondu wa Asaseli akathambye ngũa syake, na kũthamba mwĩĩ wake na manzĩ, na ĩtina akalika mwakonĩ wa maeema.'),
('kam', 'LEV', 16, 27, 'Na kala kasalũ ka nthembo ya naĩ, na ĩla nthenge ya nthembo ya naĩ, ila nthakame yasyo yaetiwe nthĩnĩ yĩthĩwe nthembo ya wĩw’anĩthyo nthĩnĩ wa vala vandũ vatheu, ikatwawe ũtee wa mwako wa maeema; na makavĩvye na mwaki ithuma syasyo, na nyama syasyo, na mũyoo wasyo.'),
('kam', 'LEV', 16, 28, 'Na ũla wĩivĩvya akathambye ngũa syake, na kũthamba mwĩĩ wake na manzĩ, na ĩtina wa ũu akasyoka mwakonĩ wa maeema.'),
('kam', 'LEV', 16, 29, 'Na ũũ ũkeethĩwa mwamũlo wa tene na tene kwenyu; mwei wa mũonza, mũthenya wa ĩkũmi wa mwei, mũkathĩn’ya ngoo syenyu, na mũtikatethye wĩa o na wĩva, ũla ũsyaawa kwenyu, kana mũeni ũla wĩkalaa ũeni kwenyu:'),
('kam', 'LEV', 16, 30, 'nũndũ mũthenya ũsu mũkathembewa nthembo ya wĩw’anĩthyo, ya kũmũthesya; mũkathew’a naĩ syenyu syonthe mbee wa Yeova.'),
('kam', 'LEV', 16, 31, 'Nĩ savato wa ũthũmũo mũuu kwenyu, na mũkathĩn’ye ngoo syenyu; nĩ mwamũlo wa tene na tene.'),
('kam', 'LEV', 16, 32, 'Na mũthembi, ũla wĩĩtĩkĩw’a mauta na kũvathanw’a ethĩwe mũthembi vandũ va ĩthe wake, akathembe nthembo ĩsu ya wĩw’anĩthyo, na kwĩkĩa ila ngũa sya katane, o ngũa isu ntheu:'),
('kam', 'LEV', 16, 33, 'na kũthemba nthembo ya wĩw’anĩthyo kwondũ wa vala vandũ vatheu; na akathembe nthembo ya wĩw’anĩthyo kwondũ wa ĩeema ya kũmbanĩa na kwondũ wa kĩthembeo; na akathembe nthembo ya wĩw’anĩthyo kwondũ wa athembi na kwondũ wa andũ onthe ma ũmbano.'),
('kam', 'LEV', 16, 34, 'Na ũsu ũkeethĩwa mwamũlo wa tene na tene kwenyu, kũthemba nthembo ya wĩw’anĩthyo kwondũ wa ana ma Isilaeli nũndũ wa naĩ syoo syonthe ĩvinda yĩmwe kĩla mwaka. Nake eeka o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 17, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 17, 2, 'Neena na Aluni, na ana make, na ana onthe ma Isilaeli, noimea: Ũũ nĩw’o ũla Yeova weaie, akyasya,'),
('kam', 'LEV', 17, 3, 'Mũndũ o na wĩva wa nyũmba ya Isilaeli, ũla wĩũaĩa ng’ombe, kana katena ka ĩlondu, kana mbũi, mwakonĩ wa maeema, kana kũmyũaĩa ũtee wa mwako wa maeema,'),
('kam', 'LEV', 17, 4, 'na ndanamĩete mũomonĩ wa ĩeema ya kũmbanĩa, kũmĩnengane yĩthĩwe nthembo ya kũmũthembea Yeova mbee wa wĩkalo wa Yeova: nthakame ĩkatalĩlwa mũndũ ũsu; nake nĩwĩtĩte nthakame; na mũndũ ũsu akavetwe andũnĩ make:'),
('kam', 'LEV', 17, 5, 'nĩ kana ana ma Isilaeli maete nthembo syoo, ila mathembeaa weũnĩ, o kana maietee Yeova, mũomonĩ wa ĩeema ya kũmbanĩa, vala ve mũthembi, na kwithembea Yeova syĩthĩwe nthembo sya nthembo sya mũuo.'),
('kam', 'LEV', 17, 6, 'Na mũthembi akaminzangĩsya nthakame kĩthembeonĩ kya Yeova mũomonĩ wa ĩeema ya kũmbanĩa, na kũmũvĩĩvĩsya Yeova mathunya methĩwe mũuke mũseo.'),
('kam', 'LEV', 17, 7, 'Na matikaithembee nthembo syoo nthenge, ila meekie ũmalwaya nasyo wa kwiatĩĩa. Ũsu ũkeethĩwa mwamũlo wa tene na tene kwoo mosyaanĩonĩ moo.'),
('kam', 'LEV', 17, 8, 'Naku matavye, Mũndũ o na wĩva wa nyũmba ya Isilaeli, kana wa aeni ala mekalaa ũeni kwoo, ũla wĩthemba nthembo ya kũvĩvw’a kana nthembo ya kũtonywa,'),
('kam', 'LEV', 17, 9, 'na ndanamĩete mũomonĩ wa ĩeema ya kũmbanĩa, kũmĩthembea Yeova; mũndũ ũsu akavetwe andũnĩ make.'),
('kam', 'LEV', 17, 10, 'Na mũndũ o na wĩva wa nyũmba ya Isilaeli, kana wa aeni ala mekalaa ũeni kwoo, ũla wĩya nthakame o na yĩva, ngamũlutĩla ũthyũ wakwa mũndũ ũsu ũla wĩya nthakame, na ngamũveta andũnĩ make.'),
('kam', 'LEV', 17, 11, 'Nũndũ thayũ wa mwĩĩ wĩ nthakamenĩ; na nĩnĩmũnengete yo kĩthembeonĩ yĩthĩwe ya wĩw’anĩthyo kwondũ wa mathayũ menyu: nũndũ nthakame nĩyo yĩw’anĩthasya mũndũ nũndũ yĩ thayũ.'),
('kam', 'LEV', 17, 12, 'Kwondũ wa ũu namea ana ma Isilaeli, Mũndũ o na wĩva wenyu ndakaye nthakame, o na mũeni o na wĩva ũla wĩkalaa ũeni kwenyu ndakaye nthakame.'),
('kam', 'LEV', 17, 13, 'Na mũndũ o na wĩva wa ana ma Isilaeli, o na wa aeni ala mekalaa ũeni kwoo, ũla wĩũaa nyamũ o na yĩva akĩsyĩma kana nyũnyi o na yĩva ĩla ĩtonya kũĩwa; akete nthakame yayo, na kũmĩvw’ĩka na mũthanga.'),
('kam', 'LEV', 17, 14, 'Nũndũ thayũ wa mĩĩ yonthe, nthakame yayo nĩ ũndũ ũmwe na thayũ wayo: nũndũ wa ũu namea ana ma Isilaeli, Mũtikaye nthakame ya nyama o na yĩva yonthe, nũndũ thayũ wa mĩĩ yonthe nĩ nthakame yayo: o ũla wĩmĩya akavetwe.'),
('kam', 'LEV', 17, 15, 'Na kĩla mũndũ ũla wĩya nyama ya kũkw’a, kana ĩla yalĩkile nĩ nyamũ, ethĩwa nĩ mũndũ ũla ũsyaawa kwoo kana mwĩkali wa ũeninĩ, akathambya ngũa syake, na kũthamba na manzĩ, na kwĩthĩwa mũvuku kũvika wĩoo: nĩvo ĩndĩ wĩĩthĩwa mũtheu.'),
('kam', 'LEV', 17, 16, 'Ĩndĩ ethĩwa ndakaithambya, kana kũthamba mwĩĩ wake, nĩvo wĩkua naĩ yake.'),
('kam', 'LEV', 18, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 18, 2, 'Neena na ana ma Isilaeli, noimea, Ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 18, 3, 'Mũtikeke kũatĩĩa meko ma nthĩ ya Misili, vala mwatwĩe: na mũtikeke kũatĩĩa meko ma Kanaani, vala nĩmũtwaĩte; o na mũtikaaende myamũlonĩ yoo.'),
('kam', 'LEV', 18, 4, 'Motw’ĩo makwa mũkekaa, na myamũlo yakwa mũkasũvĩaa, mũendae nthĩnĩ wayo: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 18, 5, 'Kwondũ wa ũu mũkasũvĩaa myamũlo yakwa, na motw’ĩo makwa; ala mũndũ ethĩwa nũmekaa, akekala thayu kwondũ wamo: ninyie Yeova.'),
('kam', 'LEV', 18, 6, 'Kũtikethĩwe mũndũ o na wĩva wenyu kũthengeea ũmwe wa ala ma mũvĩa wake, amũvue amwone e mũthei: ninyie Yeova.'),
('kam', 'LEV', 18, 7, 'Ndũkavue ĩthe waku ũmwone e mũthei, ũu nĩ kũvua inyia waku, nake nĩ inyia waku; ndũkamũvue ũmwone e mũthei.'),
('kam', 'LEV', 18, 8, 'Ndũkavue mũka wa au ũmwone e mũthei; nĩ kũvua au.'),
('kam', 'LEV', 18, 9, 'Ndũkavue mwĩĩtu wa au ũmwone e mũthei kana mwĩĩtu wa mwenyu, ethĩwa nĩwasyaĩwe kwenyu, kana nĩwasyaĩwe kũngĩ, ndũkamavue ũmone me athei.'),
('kam', 'LEV', 18, 10, 'Ndũkavue mwĩĩtu wa mwana waku, kana mwĩĩtu wa mwĩĩtu waku, ũmone me athei: nũndũ kũmavua ũmone me athei nĩ kwĩvua mwene.'),
('kam', 'LEV', 18, 11, 'Ndũkavue mwĩĩtu wa mũka wa au ũmwone e mũthei, ũla wasyaiwe nĩ au, nake nĩ mwĩĩtu wa au.'),
('kam', 'LEV', 18, 12, 'Ndũkavue mwĩĩtu‐a‐inyia wa au ũmwone e mũthei: nake nĩ wa mũvĩa wa au ũla wa vakuvĩ.'),
('kam', 'LEV', 18, 13, 'Ndũkavue mwĩĩtu wa inyia wa mwenyu ũmwone e mũthei: nũndũ nĩ wa mũvĩa wa mwenyu ũla wa vakuvĩ.'),
('kam', 'LEV', 18, 14, 'Ndũkavue mwana‐a‐inyia wa au ũmwone e mũthei, ndũkathengeee kĩveti kyake: nĩ inyia waku.'),
('kam', 'LEV', 18, 15, 'Ndũkavue kĩveti kya mwana waku ũmwone e mũthei: nĩ kĩveti kya mwana waku; ndũkakĩvue ũkyone kĩ kĩthei.'),
('kam', 'LEV', 18, 16, 'Ndũkavue kĩveti kya mwana‐a‐mwenyu ũkyone kĩ kĩthei: ũu nĩ kũvua mwana‐a‐mwenyu.'),
('kam', 'LEV', 18, 17, 'Ndũkavue mũndũ mũka na mwĩĩtu wake ũmone me athei; ndũkatwae mwĩĩtu wa mwana wa mũndũ mũka ũsu, kana mwĩĩtu wa mwĩĩtu wake, ũmũvue ũmwone e mũthei; nĩ aka ma ũko ũmwe: nĩ ũthũku mũno.'),
('kam', 'LEV', 18, 18, 'Ndũkatwaĩĩe mũndũ mũka mwĩĩtu‐a‐inyia wake, ethĩwe mũmũthĩn’ya, ũmũvue ũmwone e mũthei, ũla ũngĩ e thayũ.'),
('kam', 'LEV', 18, 19, 'Na ndũkathengee mũndũ mũka ũmũvue ũmwone e mũthei, yĩla ũvathĩtwe ũndũ wa kwĩalũla.'),
('kam', 'LEV', 18, 20, 'Na ndũkalaalae na kĩveti kya mũtũi waku, wĩvukye wĩ nakyo.'),
('kam', 'LEV', 18, 21, 'Na ndũkanengane ũmwe wa ũsyao waku ũmũvĩtĩlye mwakinĩ kwondũ wa Moleki; o na ndũkavukye syĩtwa ya Ngai waku: ninyie Yeova.'),
('kam', 'LEV', 18, 22, 'Ndũkakome na mbaa aũme, o ta mbaa aka: nĩ ũthatyo.'),
('kam', 'LEV', 18, 23, 'Na ndũkakome na nyamũ o na yĩva wĩvukye nayo; o na mũndũ mũka o na wĩva ndakaũngame mbee wa nyamũ, ĩmũlĩse: nĩ kĩthokoo.'),
('kam', 'LEV', 18, 24, 'Mũtikevukye maũndũnĩ asu o na meva: nũndũ nthĩnĩ wa asu onthe mbaĩ ila nalũngilye mbee wenyu nĩ mbukye;'),
('kam', 'LEV', 18, 25, 'na nthĩ nĩ mbukye: kwondũ wa ũu nĩngũmĩsilĩla ũndũ wa ũthũku wayo, na nthĩ nĩnĩũmatavĩka ala mamĩtwĩe.'),
('kam', 'LEV', 18, 26, 'Kwondũ wa ũu sũvĩai myamũlo yakwa na motw’ĩo makwa, na mũtikeke mothatyo asu o na meva; ũla wasyaĩwe kwenyu, o na mũeni ũla wĩkalaa ũeni katĩ wenyu'),
('kam', 'LEV', 18, 27, '(nũndũ mothatyo asu onthe aũme ma ĩ nthĩ, ala maĩ mbee wenyu, nĩmamekĩte, na ĩ nthĩ nĩvukĩtw’e);'),
('kam', 'LEV', 18, 28, 'nĩ kana nthĩ ndĩkaamũtavĩke inyw’ĩ, yĩla mwĩmĩvukya, o tondũ yatavĩkie mbaĩ ĩla yaĩ mbee wenyu.'),
('kam', 'LEV', 18, 29, 'Nũndũ o ũla ũkeka mothatyo asu o na meva, o andũ ala makameka makavetwe andũnĩ moo.'),
('kam', 'LEV', 18, 30, 'Kwondũ wa ũu mũkasũvĩe wĩaĩo wakwa, mũtikekae syĩthĩo isu sya kũthatya, ila syeekawa mũte kw’o, na mũtikevukye maũndũnĩ asu: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 19, 2, 'Neena na ũmbano w’onthe wa ana ma Isilaeli, na matavye, Ĩthĩwai atheu; nũndũ nyie Yeova Ngai wenyu nĩ mũtheu.'),
('kam', 'LEV', 19, 3, 'Kĩla mũndũ namũkĩe inyia wake na ĩthe wake; na lilikanai masavato makwa: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 4, 'Mũikethyũũĩe mĩvw’anano, kana mũikeseũvĩsye ngai na syĩndũ mũtwekethetye: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 5, 'Na mwamũthembea Yeova nthembo ya nthembo sya mũuo, mĩthembei nĩ kana mwĩtĩkĩlwe.'),
('kam', 'LEV', 19, 6, 'Ĩiwe o mũthenya ũsu mwĩmĩthemba, na ũnĩ ũsu: na ethĩwa ĩkatiala kũvika mũthenya wa katatũ, ĩvĩvw’e na mwaki.'),
('kam', 'LEV', 19, 7, 'Na ethĩwa ĩkaĩwa o na kanini mũthenya wa katatũ, nĩ ũthatyo; ndĩketĩkĩlwa:'),
('kam', 'LEV', 19, 8, 'ĩndĩ kĩla mũndũ ũla wĩmĩya akakua naĩ yake, nũndũ nũvukĩtye kĩndũ kĩtheu kya Yeova: na mũndũ ũsu akavetwe andũnĩ make.'),
('kam', 'LEV', 19, 9, 'Na mwaketha ngetha ya nthĩ yenyu, ndũkakethe ndee sya mũũnda waku, o na ndũkethĩan’ye ũtialyo wa ngetha yaku.'),
('kam', 'LEV', 19, 10, 'Na ndũkethĩan’ye mũũnda waku wa mĩsavivũ, o na ndũkakolan’ye ũsyao ũla mwĩtĩku wa mũũnda waku wa mĩsavivũ; ũeke kwondũ wa ngya na mwĩkali wa ũeninĩ: ninyie Yeova Ngai waku.'),
('kam', 'LEV', 19, 11, 'Mũikoye; o na mũikakengane, na mũikaneene movũngũ inyw’ĩ kwa inyw’ĩ.'),
('kam', 'LEV', 19, 12, 'Mũikevĩte ũvũngũ na syĩtwa yakwa, na kũvukya syĩtwa ya Ngai waku: ninyie Yeova.'),
('kam', 'LEV', 19, 13, 'Ndũkathĩn’ye mũtũi waku, kana kũmũvuta: ĩtuvi ya mũthũkũmi ũtuvawa yĩtikekale kwaku ũtukũ mũima kũvika kĩoko.'),
('kam', 'LEV', 19, 14, 'Ndũkaumanĩe ala mate matũ, kana kwĩkĩa kĩndũ kya kũlulutĩkya mbee wa ala matonaa nthĩ; ĩndĩ mũkĩe Ngai waku: ninyie Yeova.'),
('kam', 'LEV', 19, 15, 'Mũtikeke ũndũ ũte ũlũngalu mũisila: mũtikendeesye ngya, kana kũtaĩa ala me na ũtonyi; ĩndĩ tusĩaa mũtũi waku na ũlũngalu.'),
('kam', 'LEV', 19, 16, 'Ndũkaende kũũ na kũũ ta mwilĩanĩli andũnĩ maku: ndũkaũngamĩe ũvũngũ wa nthakame ya mũtũi waku: ninyie Yeova.'),
('kam', 'LEV', 19, 17, 'Ndũkamũmene mwana‐a‐au ngoonĩ yaku: ndũkatĩe kũkan’ya mũtũi waku, ndũkakue naĩ nũndũ wake.'),
('kam', 'LEV', 19, 18, 'Ndũkeĩvanĩsye, kana kwĩthĩwa na ũthũ na ana ma andũ maku; ĩndĩ mwende mũtũi waku o tondũ wĩyendete: ninyie Yeova.'),
('kam', 'LEV', 19, 19, 'Kwatai myamũlo yakwa. Ndũkaeke indo syaku kũsyaanaa na mũthemba ũngĩ: ndũkavande mũũnda waku mbeũ sya mĩthemba ĩlĩ: o na ndũkekĩe mwĩĩnĩ waku ngũa ĩvulanĩtw’e ndii sya mĩthemba ĩlĩ.'),
('kam', 'LEV', 19, 20, 'Na o ũla ũkalaalaa na mũndũ mũka, ngombo, wĩvaĩtw’e, nake ti mwovosye nongi, kana kũthaw’a; makasilĩlwe; maikoawe, nĩkwĩthĩwa mũndũ mũka ndaĩ mũthasye.'),
('kam', 'LEV', 19, 21, 'Na mũndũ mũũme ũsu akamũetee Yeova nthembo yake ya ĩvĩtyo, mũomonĩ wa ĩeema ya kũmbanĩa, o ndũũme yĩthĩwe nthembo ya ĩvĩtyo.'),
('kam', 'LEV', 19, 22, 'Na mũthembi akathembe nthembo ya kũmwĩw’anĩthya ũsu mbee wa Yeova, kwondũ wa ĩla ndũũme ya nthembo ya ĩvĩtyo kwondũ wa naĩ yake ĩla wavĩtisye: nake akaekewa naĩ ĩla wavĩtisye.'),
('kam', 'LEV', 19, 23, 'Na yĩla mwĩlika nthĩ ĩsu, na kũvanda mĩthemba yonthe ya mĩtĩ ĩla ĩĩsawa, nĩvo ĩndĩ mwĩtala mosyao mayo methĩwe ta ĩte myaĩke: myaka ĩtatũ ĩkeethĩwa kwenyu ta ĩte myaĩke; maikaĩwe.'),
('kam', 'LEV', 19, 24, 'Ĩndĩ mwaka wa kana mosyao onthe mayo makeethĩwa matheu, methĩwe ma kũmũtaĩa Yeova.'),
('kam', 'LEV', 19, 25, 'Na mwaka wa katano mũkaya mosyao mayo, nĩ kana ĩmwingĩvĩsye ũsyao wayo: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 26, 'Mũtikaye kĩndũ o na kĩva vamwe na nthakame yakyo: o na mũtikeke maũndũ ma mowe, o na mũikaingasye nyũnyi.'),
('kam', 'LEV', 19, 27, 'Mũikenze ithũkũ mĩtwenĩ yenyu, o na mũikatile mĩthya ya ing’ew’a syenyu.'),
('kam', 'LEV', 19, 28, 'Mũiketemange mĩĩ yenyu ũndũ wa akw’ũ, kana kwĩvana ũvano mĩĩnĩ yenyu: ninyie Yeova.'),
('kam', 'LEV', 19, 29, 'Ndũkatume mwĩĩtu waku atw’ĩka ĩlwaya; nthĩ ndĩkese kũatĩĩa ũlwaya, na nthĩ ĩkyusũwa nĩ ũthũku mũnene.'),
('kam', 'LEV', 19, 30, 'Lilikanai masavato makwa, na kũtaĩa vandũ vakwa vatheu: ninyie Yeova.'),
('kam', 'LEV', 19, 31, 'Mũikakũlye ala mesene na maveva, kana ala mombasya ithitũ; mũikamamanthe, mũvukw’e nĩo: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 32, 'Mũkĩlĩle ũla wĩ mũtwe wĩ mbuĩ, na kũtaĩa ũthyũ wa mũtumĩa, na mũkĩe Ngai waku: ninyie Yeova.'),
('kam', 'LEV', 19, 33, 'Na ethĩwa mũeni akekala ũeni kwaku nthĩ yaku, ndũkamwĩke naĩ.'),
('kam', 'LEV', 19, 34, 'Mũeni ũla wĩkalaa ũeni kwenyu akeethĩwa kwenyu ta ũla ũsyaawa kwenyu, na ũkamwende o tondũ wĩyendete; nũndũ inyw’ĩ mwaĩ ekali ma ũeninĩ nthĩ ya Misili: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 19, 35, 'Ndũkeke ũndũ ũte ũlũngalu ũisila, kana kũthimanĩ kwa ũasa, kana kwa latili, kana kwa kĩvava.'),
('kam', 'LEV', 19, 36, 'Ĩthĩwai na ithimi sya w’o, na mavia ma w’o, na eva ya w’o, na ini ya w’o: nyie nĩ Yeova Ngai wenyu, ũla wamumisye nthĩ ya Misili.'),
('kam', 'LEV', 19, 37, 'Na kwatai myamũlo yakwa yonthe, na motw’ĩo makwa onthe, na kũmeka: ninyie Yeova.'),
('kam', 'LEV', 20, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 20, 2, 'Na ĩngĩ, tavya ana ma Isilaeli, O ũla wa ana ma Isilaeli, kana wa aeni ala mekalaa ũeni nthĩnĩ wa Isilaeli, ũla ũkanenga Moleki ũmwe wa ũsyao wake; no mũvaka oawe: andũ ma ĩ nthĩ makamũkimanga na mavia.'),
('kam', 'LEV', 20, 3, 'Nakwa ngamũlutĩla mũndũ ũsu ũthyũ wakwa, na ngamũveta andũnĩ make; nĩkwĩthĩwa nũnengete Moleki ũmwe wa ũsyao wake, avukye vala vandũ vakwa vatheu, na kũvukya syĩtwa yakwa ĩtheu.'),
('kam', 'LEV', 20, 4, 'Na ethĩwa andũ ma ĩ nthĩ makalalya metho moo matikone mũndũ ũsu, yĩla ũkũnenga Moleki ũmwe wa ũsyao wake, na makalea kũmũaa;'),
('kam', 'LEV', 20, 5, 'nĩvo ĩndĩ nĩmũlutĩla mũndũ ũsu ũthyũ wakwa, o na nyũmba yake, na ngamũveta, na onthe ala mekaa ũmalwaya kwa kũmũatĩĩa, kwĩkaa ũmalwaya na Moleki, kuma andũnĩ moo.'),
('kam', 'LEV', 20, 6, 'Na mũndũ ũla ũmethyũũĩaa ala mesene na maveva, na ala mombasya ithitũ, eke ũmalwaya kwa kũmaatĩĩa, o nakwa ngamũlutĩla mũndũ ũsu ũthyũ wakwa, na ngamũveta andũnĩ make.'),
('kam', 'LEV', 20, 7, 'Kwondũ wa ũu ĩvathan’yei, na ĩthĩwai atheu; nũndũ ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 20, 8, 'Na mũkasũvĩe myamũlo yakwa, na mũkĩmĩka: ninyie Yeova ũla ũmũvathanasya mwĩthĩwe atheu.'),
('kam', 'LEV', 20, 9, 'Nũndũ kĩla mũndũ ũla wĩmũuma ĩthe kana nyinyia, no mũvaka oawe: nũumĩte ĩthe kana nyinyia; nthakame yake ĩkeethĩwa ĩũlũ wake.'),
('kam', 'LEV', 20, 10, 'Na mũndũ ũla ũkeka ulaalai na kĩveti kya mũndũ ũngĩ, o ũsu ũkeka ũlaalai na kĩveti kya mũtũi wake, no mũvaka ilaalai isu mũndũ mũũme na mũndũ mũka moawe.'),
('kam', 'LEV', 20, 11, 'Na mũndũ ũla ũkakoma na kĩveti kya ĩthe wake nũvuĩte ĩthe wake amwone e mũthei: no mũvaka me elĩ moawe; nthakame yoo ĩkeethĩwa ĩũlũ woo.'),
('kam', 'LEV', 20, 12, 'Na ethĩwa mũndũ akakoma na mũka wa mwana wake, no mũvaka me elĩ moawe: nĩmekĩte kĩthokoan’yo; nthakame yoo ikeethĩwa ĩũlũ woo.'),
('kam', 'LEV', 20, 13, 'Na ethĩwa mũndũ mũũme akakoma na mbaa aũme, o ta mbaa aka, me elĩ nĩmekĩte ũthatyo; no mũvaka moawe; nthakame yoo ĩkeethĩwa ĩũlũ woo.'),
('kam', 'LEV', 20, 14, 'Na ethĩwa mũndũ mũũme akatwaanĩsya mwĩĩtu na nyinyia, nĩ ũthũku mũno: makavĩvw’a na mwaki, we namo; nĩ kana kũtikethĩwe ũthũku katĩ wenyu.'),
('kam', 'LEV', 20, 15, 'Na ethĩwa mũndũ mũũme akakoma na nyamũ, no mũvaka oawe; na no mũvaka mũae ĩ nyamũ.'),
('kam', 'LEV', 20, 16, 'Na ethĩwa mũndũ mũka akathengeea nyamũ, na ĩkĩmũlĩsa, no mũvaka ũae ũ mũndũ mũka, o na nyamũ; no mũvaka mũndũ mũka oawe o na ĩ nyamũ: nthakame yoo ĩkeethĩwa ĩũlũ woo.'),
('kam', 'LEV', 20, 17, 'Na ethĩwa mũndũ akatwaa mwĩĩtua‐ĩthe, kana mwĩĩtu‐a‐inyia, na kũmwona e mũthei, na ũ mũndũ mũka akona ũ mũndũ mũũme e mũthei; nĩ ũndũ wĩ nthonĩ na makavetwe methonĩ ma ana ma andũ moo: nũvuĩte mwĩĩtu‐a‐inyia amwone e mũthei; akakua ũthũku wake.'),
('kam', 'LEV', 20, 18, 'Na ethĩwa mũndũ akakoma na mũndũ mũka ũla wealũlĩte, na akamũvua amwone e mũthei; nũvuĩte nthongo yake na ũ mũndũ mũka nĩwĩvuĩte nthongo ya nthakame yake: me elĩ makavetwe andũnĩ moo.'),
('kam', 'LEV', 20, 19, 'Na ndũkavue mwĩĩtu‐a‐inyia wa mwenyu, kana mwĩĩtu‐a‐inyia wa au ũmwone e mũthei; nũndũ nake nũvuĩte ũla wa mũvĩa wake wa vakuvĩ nake: makakua ũthũku woo.'),
('kam', 'LEV', 20, 20, 'Na ethĩwa mũndũ akakoma na kĩveti kya mwendw’a ĩthe, nũvuĩte mwendw’a ĩthe amwone e mũthei: makakua naĩ syoo; makakw’a mate kana.'),
('kam', 'LEV', 20, 21, 'Na ethĩwa mũndũ akatwaa kĩveti kya mwana‐a‐inyia, nĩ ũvuku: nũvuĩte mwana‐a‐inyia amwone e mũthei; makeethĩwa mate kana.'),
('kam', 'LEV', 20, 22, 'Kwondũ wa ũu sũvĩai myamũlo yakwa yonthe, na motw’ĩo makwa onthe, mũkĩmeka; nĩ kana nthĩ ĩla nĩmũtwaĩte mũmĩtũe, ndĩkaamũtavĩke.'),
('kam', 'LEV', 20, 23, 'Na mũtikaaende syĩthĩonĩ sya mbaĩ, ĩla nalũngilye mbee wenyu: nũndũ nĩmeekaa maũndũ asu onthe, na kwondũ wa ũu namathĩtha.'),
('kam', 'LEV', 20, 24, 'Ĩndĩ nĩnĩmũtavĩtye, Mũkatiĩwa nthĩ yoo, na ngamũnenga mũmĩmesye, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ: ninyie Yeova Ngai wenyu, ũla ũmũvathanĩtye na ngo sya andũ.'),
('kam', 'LEV', 20, 25, 'Kwondũ wa ũu vathũkanyai katĩ wa nyamũ ntheu na ĩla mbuku, na katĩ wa nyũnyi mbuku na ĩla ntheu: na mũtikaatw’ĩkĩthye mathayũ menyu kĩla kĩthatasya nũndũ wa nyamũ, kana nyũnyi, kana nũndũ wa kĩndũ o na kĩva kĩla kyusũĩte ĩũlũ wa nthĩ, kĩla nakĩvathĩte kwenyu kĩthĩwe kĩte kĩtheu.'),
('kam', 'LEV', 20, 26, 'Nenyu mũkeethĩwe atheu kwakwa: nũndũ nyie, Yeova, nĩ mũtheu, na nĩmũvathanĩtye na ngo sya andũ, nĩ kana mwĩthĩwe makwa.'),
('kam', 'LEV', 20, 27, 'Mũndũ mũũme kana mũndũ mũka ũla wĩsene na veva, kana ũla ũmbasya ithitũ, no mũvaka oawe: makamakimange na mavia; nthakame yoo ĩkeethĩwa ĩũlũ woo.'),
('kam', 'LEV', 21, 1, 'Na Yeova amwĩa Mose, Neena na athembi, ana ma Aluni, noimea, Mũthembi o na wĩva ndakevukye kwondũ wa akw’ũ andũnĩ make;'),
('kam', 'LEV', 21, 2, 'ate o kwondũ wa andũ ma mũvĩa wake, ala me vakuvĩ nake, kwondũ wa nyinyia, na ĩthe wake, na mwana wake, na mwĩĩtu wake, na mwana‐a‐inyia wake,'),
('kam', 'LEV', 21, 3, 'na mwĩĩtu‐a‐inyia ũla mũtheu, ũla wĩ vakuvĩ nake, ũla ũtaaĩthĩwa na mũũme; kwondũ wake nũtonya kwĩvukya.'),
('kam', 'LEV', 21, 4, 'Ndakevukye, na kwasya ũtheu wake, nũndũ nĩ mũndũ mũnene andũnĩ make.'),
('kam', 'LEV', 21, 5, 'Maikenze mũtwe ũvaa, o na maiketile mithya ya ing’ew’a syoo, kana kwĩtemanga mĩĩ yoo.'),
('kam', 'LEV', 21, 6, 'Methĩwe atheu kwa Ngai woo, na matikaavukye syĩtwa ya Ngai woo; nũndũ nĩmathembaa nthembo sya Yeova ila ivĩvaw’a na mwaki, lĩu wa Ngai woo: kwondũ wa ũu makeethĩwa atheu.'),
('kam', 'LEV', 21, 7, 'Matikatwae mũndũ mũka ĩlwaya, kana mũvukye; o na matikatwae mũndũ mũka ũeketwe nĩ mũũme: nũndũ mũthembi nĩ mũtheu kwa Ngai wake.'),
('kam', 'LEV', 21, 8, 'Kwondũ wa ũu mũvathe ethĩwe mũtheu; nũndũ nũthembaa lĩu wa Ngai waku; akeethĩwa mũtheu kwaku; nũndũ nyie Yeova, ũla ũkũvathanasya, nĩ mũtheu.'),
('kam', 'LEV', 21, 9, 'Na mwĩĩtu wa mũthembi o na wĩva, ethĩwa akeevukya kwondũ wa kũtw’ĩka ĩlwaya, nũvukasya ĩthe wake: akavĩvw’e na mwaki.'),
('kam', 'LEV', 21, 10, 'Na ũla mũthembi mũnene katĩ wa ana‐a‐ĩthe make, ũla wetĩkĩw’e mauta mũtwenĩ wake, na kũvathanw’a ethĩwe mũtheu ekĩe ila ngũa, ndakavue nzw’ĩĩ sya mũtwe wake, kana kũtembũanga ngũa syake;'),
('kam', 'LEV', 21, 11, 'o na ndakalike vala ve mũndũ mũkw’ũ, kana kwĩvukya kwondũ wa ĩthe wake, kana nyinyia;'),
('kam', 'LEV', 21, 12, 'o na ndakaume vala vandũ vatheu, kana kũvukya vandũ vatheu va Ngai wake; nũndũ kũvathanw’a kwondũ wa kwĩtĩkĩw’a mauta ma Ngai wake kwĩ ĩũlũ wake: ninyie Yeova.'),
('kam', 'LEV', 21, 13, 'Nake akatwae mwĩĩtu mũtheu ethĩwe mũka wake.'),
('kam', 'LEV', 21, 14, 'Mũndũ mũka ndiwa, kana ũla ũeketwe, kana ũla mũvukye, kana ĩlwaya, asu ndakatwae: ĩndĩ natwae mwĩĩtu mũtheu wa andũ make mwene ethĩwe mũka wake.'),
('kam', 'LEV', 21, 15, 'Ndakavukye ũsyao wake andũnĩ make: nũndũ ninyie Yeova ũla ũmũvathanasya ethĩwe mũtheu.'),
('kam', 'LEV', 21, 16, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 21, 17, 'Neena na Aluni, ũkĩmwĩa, O ũla wa ũsyao waku mosyaanĩonĩ moo ũla wĩ kĩema, ndakathengeee kũthemba lĩu wa Ngai wake.'),
('kam', 'LEV', 21, 18, 'Mũndũ o na wĩva wĩ kĩema, ndakathengeee: ethĩwa nĩ kĩlilinda, kana ũla ũthuaa, kana ũla wĩ ĩnyiũũ ĩmandĩku, kana ũla wĩ ĩmutha yongeleku,'),
('kam', 'LEV', 21, 19, 'kana mũndũ ũla wĩ kũũ kũtũlĩku, kana kw’oko kũtũlĩku,'),
('kam', 'LEV', 21, 20, 'kana ũla wĩ ngathĩ mũongo, kana mũndũ ũteanaa, kana ũla wĩ ĩlai, kana ũla wĩ na mũvolekango, kana ũla wĩ na ngũsĩ, kana ũla wĩ mee mavevenze;'),
('kam', 'LEV', 21, 21, 'mũndũ o na wĩva wa ũsyao wa mũthembi Aluni, ũla wĩ kĩema, ndakathengeee kũthemba nthembo sya Yeova ila ivĩvaw’a na mwaki: e kĩema; ndakathengeee kũthemba lĩu wa Ngai wake.'),
('kam', 'LEV', 21, 22, 'Akaĩsaa lĩu ũla mũtheu mũno, na ũla mũtheu, wa Ngai wake:'),
('kam', 'LEV', 21, 23, 'ĩndĩ ndakalike vala ve ũla tũtũ, kana kũthengeea kĩthembeo, nĩkwĩthĩwa e kĩema; ndakavukye kũndũ kwakwa kũtheu: nũndũ ninyie Yeova ũla ũmavathanasya methĩwe atheu.'),
('kam', 'LEV', 21, 24, 'O ta ũu Mose aneena na Aluni, na ana make, na ana onthe ma Isilaeli.'),
('kam', 'LEV', 22, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 22, 2, 'Neena na Aluni na ana make, mevathane na syĩndũ ntheu sya ana ma Isilaeli, ila mambathĩaa syĩthĩwe ntheu, na matĩkavukye syĩtwa yakwa ĩtheu: ninyie Yeova.'),
('kam', 'LEV', 22, 3, 'Matavye, O ũla wa ũsyao wenyu w’onthe mosyaanĩonĩ menyu, ũla wĩthengeea ila syĩndũ ntheu, ila ana ma Isilaeli mamũvathĩaa Yeova, e na ũvuku wake, mũndũ ũsu akavetwe mbee wakwa: ninyie Yeova.'),
('kam', 'LEV', 22, 4, 'Mũndũ o na wĩva wa ũsyao wa Aluni ũla wĩ na mangũ, kana wĩ na mũluo; ndakaye syĩndũ ntheu, mũvaka yĩla wĩĩthĩwa mũtheu. Na o ũla wĩkiita kĩndũ kĩvuku kwondũ wa akw’ũ, kana mũndũ ũla wĩumwa nĩ ũsamba wake;'),
('kam', 'LEV', 22, 5, 'kana o ũla wĩkiita kasamũ o na keva katambũkaa, kala katonya kũmũvukya, kana mũndũ ũngĩ ũla ũtonya kũmũkwatya ũvuku, ũvuku o na wĩva ũla wi naw’o;'),
('kam', 'LEV', 22, 6, 'mũndũ ũla wĩkiita kĩndũ o na kĩva kĩilyĩ ũu akeethĩwa mũvuku kũvika wĩoo, na ndakaye syĩndũ ntheu, atanamba kũthamba mwĩĩ wake na manzĩ.'),
('kam', 'LEV', 22, 7, 'Na syũa yathũa, akeethĩwa mũtheu; na ĩtina akaya syĩndũ ntheu, nĩkwĩthĩwa nĩ lĩu wake.'),
('kam', 'LEV', 22, 8, 'Nyamũ ya ũkw’a, kana ĩla yalĩkile nĩ nyamũ, ndakaye, ndakevukye nayo: ninyie Yeova,'),
('kam', 'LEV', 22, 9, 'Kwondũ wa ũu makwate wĩaĩo wakwa, matikakue naĩ kwondũ waw’o, na kũkw’ĩa nthĩnĩ wayo, ethĩwa makoovukya: ninyie Yeova ũla ũmavathanasya methĩwe atheu.'),
('kam', 'LEV', 22, 10, 'Mũeni ndakaye kya kĩla kĩndũ kĩtheu: mwĩkali wa ũeninĩ kwa mũthembi, kana mũthũkũmi ũtuvawa, ndakaye kĩndũ kĩtheu.'),
('kam', 'LEV', 22, 11, 'Ĩndĩ ethĩwa mũthembi akathooa mũndũ o na wĩva na mbesa syake, ũsu nũtonya kwiya; na ala masyaĩwe nyũmbanĩ yake, nao makaya lĩu wake.'),
('kam', 'LEV', 22, 12, 'Na ethĩwa mwĩĩtu wa mũthembi akatwawa nĩ mũeni, ndakaye nthembo ya kũkĩlw’a ya syĩndũ ntheu.'),
('kam', 'LEV', 22, 13, 'Na ethĩwa mwĩĩtu wa mũthembi nĩ ndiwa, kana aeketwe nĩ mũũme, na nde na kana, na asyokete nyũmbanĩ ya ĩthe wake, o tondũ wailyĩ e mwĩĩtu, akaĩsaa lĩu kwa ĩthe wake: ĩndĩ mũeni o na wĩva ndakaye lĩu ũsu.'),
('kam', 'LEV', 22, 14, 'Na ethĩwa mũndũ mũũme akaya kĩndũ kĩtheu atesĩ, nĩvo wĩkyongeleela kĩlungu kya katano, na kũmũnenga mũthembi kĩla kĩndũ kĩtheu.'),
('kam', 'LEV', 22, 15, 'Maikavukye syĩndũ ntheu sya ana ma Isilaeli, ila mamũthembeaa Yeova,'),
('kam', 'LEV', 22, 16, 'na kwondũ wa ũu makĩmakũĩthya ũthũku ũla ũetae ũsilĩlo, yĩla meya syĩndũ syoo ntheu: nũndũ ninyie Yeova ũla ũmavathanasya methĩwe atheu.'),
('kam', 'LEV', 22, 17, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 22, 18, 'Neena na Aluni, na ana make, na ana onthe ma Isilaeli, noimatavya, O ũla wa nyũmba ya Isilaeli, kana wa ekali ma ũeninĩ nthĩnĩ wa Isilaeli, ũla wĩumya nthembo yake, ethĩwa nĩ kwondũ wa mawĩvĩto moo o na meva, kana nthembo syoo o na syĩva sya kũthemba na ngoo ya kwenda, ila mamũthembeaa Yeova syĩthĩwe nthembo sya kũvĩvw’a;'),
('kam', 'LEV', 22, 19, 'nĩ kana mwĩtĩkĩlwe, etei ĩla nũme ĩte kĩema, ya tũsalũ twa mũew’a, kana ya malondu, kana ya mbũi.'),
('kam', 'LEV', 22, 20, 'Ĩndĩ o ĩla yĩ kĩema, mũikamĩthembe: nũndũ ndĩketĩkĩlwa kwondũ wenyu.'),
('kam', 'LEV', 22, 21, 'Na o ũla wĩumĩsya Yeova nthembo ya nthembo sya mũuo ya kwĩanĩsya wĩvĩto, kana yĩthĩwe nthembo ya kũthemba na ngoo ya kwenda, ethĩwa nĩ ya ndĩthya ya ng’ombe kana ya mbũi na malondu, nĩ kana ĩtĩkĩlwe mũvaka yĩthĩwe mbĩanĩu; ndĩkethĩwe kĩema.'),
('kam', 'LEV', 22, 22, 'Ĩla ĩte metho, kana ndũlĩku vandũ, kana ĩla yĩ kĩthu, kana ĩla yĩ itau, kana ĩla yĩ na mũvolekango, kana ĩla yĩ na ngũsĩ, isu mũikamũthembee Yeova, kana kũmũvĩvĩsya Yeova isu na mwaki kĩthembeonĩ.'),
('kam', 'LEV', 22, 23, 'Kasalũ ka mũew’a kana katena ka ĩlondu kala ke na ĩmutha yongeleku kana ĩmutha yĩte vo mwĩĩnĩ wako, nũtonya kũkathemba kethĩwe nthembo ya kumya na ngoo ya kwenda; ĩndĩ itiketĩkĩlwe kwondũ wa wĩvĩto.'),
('kam', 'LEV', 22, 24, 'Na ĩla yĩ na mee mavakũe, kana makũnange, kana makanyange, kana matile, mũikaithembee Yeova; o na mũikeke ũu mwavika nthĩ yenyu.'),
('kam', 'LEV', 22, 25, 'O na kuma kw’okonĩ kwa mũndũ wa nthĩ ĩngĩ mũikathembe lĩu wa Ngai wenyu wa ĩmwe ya isu; nĩkwĩthĩwa ũvuku wasyo wĩ nthĩnĩ wasyo, ve kĩema nthĩnĩ wasyo; itiketĩkĩlwa kwondũ wenyu.'),
('kam', 'LEV', 22, 26, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 22, 27, 'Yĩla kasalũ ka mũew’a, kana ĩlondu, kana mbũi ĩkasyawa, nĩyĩkale mĩthenya mũonza na nyinyia; na kuma mũthenya wa nyanya na mbee wa vau ĩketĩkĩlwa yĩthĩwe nthembo ya kũvĩvĩw’a Yeova na mwaki.'),
('kam', 'LEV', 22, 28, 'Na ethĩwa nĩ ng’ombe nga kana ĩlondu ĩka, mũikoaanĩsye na katena kayo mũthenya ũmwe.'),
('kam', 'LEV', 22, 29, 'Na mwamũthembea Yeova nthembo ya mũvea, mũkamĩthemba nĩ kana mwĩtĩkĩlwe.'),
('kam', 'LEV', 22, 30, 'Ĩĩwe mũthenya o ũsu; mũikatialye kũvika kĩoko: ninyie Yeova.'),
('kam', 'LEV', 22, 31, 'Kwondũ wa ũu kwatai mĩao yakwa, na kũmĩka: ninyie Yeova.'),
('kam', 'LEV', 22, 32, 'Na mũikavukye syĩtwa yakwa ĩtheu: ĩndĩ mũvaka nonanw’e nĩ mũtheu ananĩ ma Isilaeli: ninyie Yeova ũla ũmũvathaa mwĩthĩwe atheu,'),
('kam', 'LEV', 22, 33, 'ũla wamumisye nthĩ ya Misili, nĩthĩwe Ngai wenyu: ninyie Yeova.'),
('kam', 'LEV', 23, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 23, 2, 'Neena na ana ma Isilaeli, noimea, Mboka ila itw’ĩtwe sya Yeova, ila mũkatavan’ya atĩ nĩ maũmbano matheu, o ii nĩsyo mboka syakwa itw’ĩtwe.'),
('kam', 'LEV', 23, 3, 'Tethyai wĩa mĩthenya thanthatũ: ĩndĩ mũthenya wa mũonza nĩ savato wa ũthũmũo mũuu, ũmbano mũtheu; mũikatethye wĩa o na wĩva: nĩ savato wa Yeova motũonĩ menyu onthe.'),
('kam', 'LEV', 23, 4, 'Ii nĩsyo mboka itw’ĩtwe sya Yeova, o maũmbano matheu, ila mũkatavanasya ĩvinda yĩla yĩtw’ĩtwe yasyo.'),
('kam', 'LEV', 23, 5, 'Mwei wa mbee, mũthenya wa ĩkũmi na ĩna wa mwei wĩoo, nĩ vasaka wa Yeova.'),
('kam', 'LEV', 23, 6, 'Na mũthenya wa ĩkũmi na ĩtano mwei o ũsu nĩ mboka kwondũ wa Yeova ya kĩmũtũ kĩte ĩlawa: yai kĩmũtũ kĩte ĩlawa mĩthenya mũonza.'),
('kam', 'LEV', 23, 7, 'Mũthenya wa mbee mũkeethĩwa na ũmbano mũtheu: mũikatethye wĩa o na wĩva.'),
('kam', 'LEV', 23, 8, 'Ĩndi mũkamũthembee Yeova nthembo ya kũvĩvw’a na mwaki mĩthenya mũonza: mũthenya wa mũonza nĩ ũmbano mũtheu; mũikatethye wĩa o na wĩva.'),
('kam', 'LEV', 23, 9, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 23, 10, 'Neena na ana ma Isilaeli, noimea, Mwalika nthĩ ĩla nĩmũnengae, na mwaketha ngetha yayo, nĩvo ĩndĩ mwĩmũetee mũthembi kyove kya mosyao ma mbee ma ngetha yenyu:'),
('kam', 'LEV', 23, 11, 'nake akavyũlangya kyove mbee wa Yeova, kĩtĩkĩlwe kwondũ wenyu: savato ũnĩ usu mũthembi akakĩvyũlangya.'),
('kam', 'LEV', 23, 12, 'Na mũthenya ũla mwĩvyũlangya kyove, mũkamũthembea Yeova katũlũme kate kĩema ka mwaka ũmwe kethĩwe nthembo ya kũvĩvw’a.'),
('kam', 'LEV', 23, 13, 'Na nthembo ya mũtu ya kũthembanĩsya nayo ĩkeethĩwa ilungu ilĩ sya ĩkũmi sya eva ya mũtu mũvinyu ũvulanĩtw’e na mauta, nthembo ĩvĩvĩaw’a Yeova na mwaki yĩthĩwe mũuke mũseo; na nthembo ya kũnyuwa ya kũthembanĩsya nayo ĩkeethĩwa ya mbinyu, kĩlungu kya kana kya ini.'),
('kam', 'LEV', 23, 14, 'Na mũtikaye kĩmũtũ, kana lĩu wa mbaa ngetha ũkaangĩtwe na mwaki, kana iia mbĩu, kũvika mũthenya o ũsu, kũvika yĩla mwĩete nthembo ya Ngai wenyu: nĩ mwamũlo wa tene na tene mosyaanĩonĩ menyu motũonĩ menyu onthe.'),
('kam', 'LEV', 23, 15, 'Na mũketalĩle kwambĩlĩlya ũnĩ ũsu savato wathela, kuma mũthenya ũla mwaetie kyove kya nthembo ya kũvyũlw’a; masavato mũonza makeethĩwa meanĩe:'),
('kam', 'LEV', 23, 16, 'mũkatale mĩthenya mĩongo ĩtano o kũvika ũnĩ ũsu savato wa mũonza wathela; na mũkathembee Yeova nthembo ya mũtu mweũ.'),
('kam', 'LEV', 23, 17, 'Mũkaete kuma motũonĩ menyu imũtũ ilĩ sya kũvyũlw’a sya ilungu ilĩ sya ĩkũmi sya eva: ikeethĩwa sya mũtu mũvinyu, na ikauwa syĩ ĩlawa, syĩthĩwe mosyao ma mbee kwa Yeova.'),
('kam', 'LEV', 23, 18, 'Na vamwe na imũtũ mũkaete tũtena mũonza twa malondu tũte kĩema twa mwaka ũmwe, na kasalũ, na ndũũme ilĩ: ikeethĩwa nthembo ya kũvĩvĩw’a Yeova, na nthembo ya mũtu ya kũthembanĩsya nasyo, na nthembo sya kũnyuwa sya kũthembanĩsya nasyo, o nthembo ĩla ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'LEV', 23, 19, 'Na mũkathembe nthenge ĩmwe yĩthĩwe nthembo ya naĩ, na tũtũlũme twĩlĩ twa mwaka ũmwe twĩthĩwe nthembo ya nthembo sya mũuo.'),
('kam', 'LEV', 23, 20, 'Na mũthembi akaivyũlangye vamwe na kĩmũtũ kya mosyao ma mbee syĩthĩwe nthembo sya kũvyũlw’a mbee wa Yeova, vamwe na tũla tũtũlũme twĩlĩ: ikeethĩwa ntheu kwa Yeova kwondũ wa mũthembi.'),
('kam', 'LEV', 23, 21, 'Na mũkatavan’ye o mũthenya ũsu; kũkeethĩwa ũmbano mũtheu kwenyu; mũikatethye wĩa o na wĩva: nĩ mwamũlo wa tene na tene motũonĩ menyu onthe mosyaanĩonĩ menyu.'),
('kam', 'LEV', 23, 22, 'Na mwaketha ngetha ya nthĩ yenyu, ndũkakethe vyũ ndee sya mũũnda waku, o na ndũkethĩan’ye ngetha yaku: ũkatiĩa ngya, na mwĩkali wa ũeninĩ: ninyie Yeova Ngai waku.'),
('kam', 'LEV', 23, 23, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 23, 24, 'Neena na ana ma Isilaeli, ũkĩmea, Mwei wa mũonza, mũthenya wa mbee wa mwei, ũkeethĩwa ũthũmũo mũuu kwenyu, ũlilikan’yo wa kũvuva masoo, ũmbano mũtheu.'),
('kam', 'LEV', 23, 25, 'Mũikatethye wĩa o na wĩva; na mũkamũthembea Yeova nthembo ya kũvĩvw’a na mwaki.'),
('kam', 'LEV', 23, 26, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 23, 27, 'Na ĩngĩ mũthenya wa ĩkũmi wa mwei ũsu wa mũonza nĩ mũthenya wa wĩw’anĩthyo: ũkeethĩwa ũmbano mũtheu kwenyu, na mwĩthĩn’ye ngoo syenyu; na mũkamũthembee Yeova nthembo ya kũvĩvw’a na mwaki.'),
('kam', 'LEV', 23, 28, 'Na mũikatethye wĩa o na wĩva mũthenya ũsu; nũndũ nĩ mũthenya wa wĩw’anĩthyo, wa kũthemba nthembo ya wĩw’anĩthyo kwondũ wenyu mbee wa Yeova Ngai wenyu.'),
('kam', 'LEV', 23, 29, 'Nũndũ mũndũ o na wĩva ũla ũteĩthĩn’ya mũthenya o ũsu, akavetwe andũnĩ make.'),
('kam', 'LEV', 23, 30, 'Na mũndũ o na wĩva ũla wĩtethya mũthemba o na wĩva wa wĩa mũthenya ũsu, mũndũ ũsu ngamwananga aume andũnĩ make.'),
('kam', 'LEV', 23, 31, 'Mũikatethye wĩa o na wĩva: nĩ mwĩao wa tene na tene mosyaanĩonĩ menyu motũonĩ menyu onthe.'),
('kam', 'LEV', 23, 32, 'Mũthenya ũsu ũkeethĩwa kwenyu savato wa ũthũmũo mũuu, na mwĩthĩn’ye ngoo syenyu: mũthenya wa kenda wa mwei wĩoo, kuma wĩoo kũvika wĩoo, mũkalilikane savato wenyu.'),
('kam', 'LEV', 23, 33, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 23, 34, 'Neena na ana ma Isilaeli, ũkĩmea, Mũthenya wa ĩkũmi na ĩtano wa mwei wa mũonza nĩ mboka ya malwanda kwondũ wa Yeova vandũ va mĩthenya mũonza.'),
('kam', 'LEV', 23, 35, 'Mũthenya wa mbee kũkeethĩwa ũmbano mũtheu: mũikatethye wĩa o na wĩva.'),
('kam', 'LEV', 23, 36, 'Mĩthenya mũonza mũkamũthembee Yeova nthembo ĩvĩvaw’a na mwaki: mũthenya wa nyanya kũkeethĩwa ũmbano mũtheu kwenyu; na mũkamũthembee Yeova nthembo ĩvĩvaw’a na mwaki: nĩ ũmbano ũkilĩtye; mũikatethye wĩa o na wĩva.'),
('kam', 'LEV', 23, 37, 'Ii nĩsyo mboka itw’ĩtwe sya Yeova, ila mũkatavanasya syĩthĩwe maũmbano matheu, kũmũthembea Yeova nthembo ĩvĩvaw’a na mwaki, nthembo ya kũvĩvw’a, na nthembo ya mũtu, na nthembo ya ũtonywa, na nthembo sya kũnyuwa, kĩla ĩmwe mũthenya wayo;'),
('kam', 'LEV', 23, 38, 'vamwe na isu masavato ma Yeova, na mĩthĩnzĩo yenyu, na mawĩvĩto menyu onthe, na nthembo syenyu syonthe sya kumya na ngoo ya kwenda, ila mũmũnengae Yeova.'),
('kam', 'LEV', 23, 39, 'Na ĩndĩ mũthenya wa ĩkũmi na ĩtano wa mwei wa mũonza, mwamina kũmban’ya mosyao ma nthĩ, mũkalilikane mboka ya Yeova mĩthenya mũonza: mũthenya wa mbee kũkeethĩwa ũthũmũo mũuu, na mũthenya wa nyanya kũkeethĩwa ũthũmũo mũuu.'),
('kam', 'LEV', 23, 40, 'Na mũthenya wa mbee mũkeeyosea ũsyao wa mĩtĩ mĩseo, mathangũ ma mĩtende, na mbonge sya mĩtĩ mĩthungu, na mĩtĩ ĩla ĩmeaa kalũsĩnĩ; na mũkatana mbee wa Yeova Ngai wenyu mĩthenya mũonza.'),
('kam', 'LEV', 23, 41, 'Na mũkethĩawa na mboka kwondũ wa Yeova mĩthenya mũonza kĩla mwaka: nĩ mwamũlo wa tene na tene mosyaanĩonĩ menyu; mũkamĩlilikanaa mwei wa mũonza.'),
('kam', 'LEV', 23, 42, 'Mũkekale malwandanĩ mĩthenya mũonza; onthe ala masyaawa kwa Isilaeli makekale malwandanĩ;'),
('kam', 'LEV', 23, 43, 'nĩ kana nzyawa syenyu imanye kana nyie namekalilye ana ma Isilaeli malwandanĩ, yĩla namaumisye nthĩ ya Misili: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 23, 44, 'Na Mose amatavya ana ma Isilaeli mboka isu ila syatwiwe sya Yeova.'),
('kam', 'LEV', 24, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 24, 2, 'Ĩaĩe ana ma Isilaeli makũetee mauta matheu ma mosyao ma mĩthata makimĩte kwondũ wa kyeni, makanasya taa mavinda onthe.'),
('kam', 'LEV', 24, 3, 'Ũtee wa tũtũ wa ĩsandũkũ ya ũkũsĩ, ĩeemanĩ ya kũmbanĩa, Aluni akoseũvasye kuma wĩoo kũvika kĩoko mbee wa Yeova mavinda onthe: ũsu ũkeethĩwa mwamũlo wa tene na tene mosyaanĩonĩ menyu.'),
('kam', 'LEV', 24, 4, 'Akaseũvasye mataa ala me kĩndũnĩ kĩtheu kyamo mbee wa Yeova mavinda onthe.'),
('kam', 'LEV', 24, 5, 'Na ũkose mũtu mũvinyu, na kũua tũmũtũ ĩkũmi na twĩlĩ twaw’ö ilungu ilĩ sya ĩkũmi sya eva ikeethĩwa nthĩnĩ wa kĩla kamũtũ.'),
('kam', 'LEV', 24, 6, 'Na ũkatwie mĩsoa ĩlĩ, thanthatũ kĩla mũsoa, mesanĩ ntheu mbee wa Yeova.'),
('kam', 'LEV', 24, 7, 'Na ũkekĩe ũvumba mũtheu ĩũlũ wa kĩla mũsoa, wĩthĩwe ĩũlũ wa tũmũtũ kwondũ wa ũlilikan’yo, o nthembo ya kũvĩvĩaw’a Yeova na mwaki.'),
('kam', 'LEV', 24, 8, 'Kĩla mũthenya wa savato akatwiae nesa mbee wa Yeova mavinda onthe; nĩ kwondũ wa ana ma Isilaeli, ũtianĩo wa tene na tene.'),
('kam', 'LEV', 24, 9, 'Na tũkeethĩwa twa Aluni na ana make; na makatũĩsĩaa vandũ vatheu: nũndũ nĩ tũtheu mũno kwake katĩ wa nthembo sya Yeova ila ivĩvaw’a na mwaki ũndũ wa mwamũlo wa tene na tene.'),
('kam', 'LEV', 24, 10, 'Na mwana wa mũndũ mũka Mũisilaeli, ũla ĩthe wake waĩ Mũmisili, aenda ananĩ ma Isilaeli; na mwana ũsu wa mũndũ mũka Mũisilaeli na mũndũ mũũme wa Isilaeli mokitĩa mwakonĩ wa maeema:'),
('kam', 'LEV', 24, 11, 'na mwana ũsu wa mũndũ mũka Mũisilaeli ayĩuma yĩla Syĩtwa, na kũumanĩa; na mamũete vala ve Mose. Syĩtwa ya inyia wake eetawa Selomithi, mwĩĩtu wa Ndivili, wa mbaĩ ya Ndani.'),
('kam', 'LEV', 24, 12, 'Na mamwĩkĩa ũsũvĩonĩ, nĩ kana matavw’e ndeto ĩla yĩuma kanyw’anĩ wa Yeova.'),
('kam', 'LEV', 24, 13, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 24, 14, 'Mumaalye ũsu ũla waumanie ũtee wa mwako wa maeema; na onthe ala mamwĩwie nĩmailĩlĩle moko moo mũtwenĩ wake, na ũmbano w’onthe ũmũkime na mavia.'),
('kam', 'LEV', 24, 15, 'Na ũkaneena na ana ma Isilaeli, ũkĩmea, O ũla wĩmũuma Ngai wake akakue naĩ yake.'),
('kam', 'LEV', 24, 16, 'Na ũla wĩyĩuma syĩtwa ya Yeova, ndatĩa kũawa; mũvaka ũmbano w’onthe ũmũkime na mavia: mwĩkali wa ũeninĩ nĩ ũndũ ũmwe na ũla ũsyaawa kwenyu, auma syĩtwa ya Yeova, mũvaka oawe.'),
('kam', 'LEV', 24, 17, 'Na ũla wĩkũna mũndũ akw’e mũvaka oawe.'),
('kam', 'LEV', 24, 18, 'Na ũla wĩkũna nyamũ ĩkw’e akaĩva, thayũ vandũ va thayũ.'),
('kam', 'LEV', 24, 19, 'Na ethĩwa mũndũ akamwĩkĩa mũtũi wake kĩema; o ũndũ wekie, now’o wĩĩkwa:'),
('kam', 'LEV', 24, 20, 'ĩkũna vandũ va ĩkũna, itho vandũ va itho, ĩeo vandũ va ĩeo; o ũndũ wamwĩkĩie mũndũ kĩema, now’o wĩĩkwa.'),
('kam', 'LEV', 24, 21, 'Na ũla wĩũaa nyamũ akaĩva: na o ũla wĩũaa mũndũ akoawa.'),
('kam', 'LEV', 24, 22, 'Mũkeethĩwa na mwĩao wa mũthemba ũmwe ki, wa mwĩkali wa ũeninĩ ũndũ ũmwe na wa ũla ũsyaawa kwenyu: nũndũ ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 24, 23, 'Na Mose aneena na ana ma Isilaeli; na mamumaalya ũla waumanie kũmumya mwakonĩ wa maeema, na mamũkimanga na mavia. Na ana ma Isilaeli meeka o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'LEV', 25, 1, 'Na Yeova aneena na Mose kĩĩmanĩ kya Sinai, akĩmwĩa,'),
('kam', 'LEV', 25, 2, 'Neena na ana ma Isilaeli, noimea, Yĩla mwĩlika nthĩ ĩla nĩmũnengae, nĩvo ĩndĩ nthĩ yĩkwata savato kwondũ wa Yeova.'),
('kam', 'LEV', 25, 3, 'Myaka thanthatũ ũkavande mũũnda waku, na myaka thanthatũ ũkasee mũũnda waku wa mĩsavivũ, na kũketha mosyao maw’o;'),
('kam', 'LEV', 25, 4, 'ĩndĩ mwaka wa mũonza ũkeethĩwa savato wa ũthũmũo mũuu kwondũ wa nthĩ, savato wa Yeova: ndũkavande mũũnda waku, kana kũsea mũũnda waku wa mĩsavivũ.'),
('kam', 'LEV', 25, 5, 'Kĩla kĩĩmesya mũũndanĩ waku ndũkakethe, na nzavivũ sya mĩsavivũ yaku ũtaseete ndũkakethe: ũkeethĩwa mwaka wa ũthũmũo mũuu kwondũ wa nthĩ.'),
('kam', 'LEV', 25, 6, 'Na savato wa nthĩ ũkeethĩwa kwondũ wenyu ũndũ wa lĩu; kwondũ waku na kwondũ wa mũthũkũmi waku mũndũ mũũme na mũthũkũmi waku mwĩĩtu, na kwondũ wa mũthũkũmi waku ũtuvawa na mũeni waku, ũla wĩkalaa ũeni kwaku.'),
('kam', 'LEV', 25, 7, 'Wingĩvo w’onthe wayo ũkeethĩwa lĩu kwondũ wa indo syaku, na kwondũ wa nyamũ ila syĩ nthĩ yaku.'),
('kam', 'LEV', 25, 8, 'Na ũketalĩle masavato mũonza ma myaka, myaka mũonza kũndũ mũonza; na mĩthenya ya masavato mũonza ma myaka ĩkeethĩwa kwaku, o myaka mĩongo ĩna na kenda.'),
('kam', 'LEV', 25, 9, 'Nĩvo ĩndĩ wĩvuva soo wĩ wasya mũnene mũthenya wa ĩkũmi wa mwei wa mũonza; mũthenya wa wĩw’anĩthyo now’o mũkavuva soo nthĩ yenyu yonthe.'),
('kam', 'LEV', 25, 10, 'Na mũkavathe mwaka wa mĩongo ĩtano wĩthĩwe mũtheu, na kũtavan’ya ũthasyo nthĩ yonthe kwa andũ onthe ala mamĩtwĩe: ũkeethĩwa kwenyu mwaka wa kũtana wĩtawa yuvilii; na kĩla mũndũ wenyu akasyokea ng’ũndũ yake, na kĩla mũndũ akasyokea mũvĩa wake.'),
('kam', 'LEV', 25, 11, 'Mwaka ũsu wa mĩongo ĩtano ũkeethĩwa kwenyu mwaka wa kũtana wĩtawa yuvilii: mũikavande, na mũikakethe kĩla kĩĩmesya mwaka ũsu, kana kũtw’a nzavivũ sya mĩsavivũ ĩla ĩtaasewa mwaka ũsu.'),
('kam', 'LEV', 25, 12, 'Nũndũ nĩ yuvilii; ũkeethĩwa mũtheu kwenyu: mũkaya wingĩvo waw’o wumĩte mũũndanĩ.'),
('kam', 'LEV', 25, 13, 'Mwakanĩ ũsu wa yuvilii kĩla mũndũ wenyu akasyokeaa ng’ũndũ yake.'),
('kam', 'LEV', 25, 14, 'Na ethĩwa ũkamũthooesya mũtũi waku kĩndũ, kana kũthooa kĩndũ kwĩ kw’okonĩ kwa mũtũi waku, mũikakengane ene kwa ene.'),
('kam', 'LEV', 25, 15, 'Kwĩanana na ũndũ myaka yĩana ĩtina wa mwaka wa yuvilii ũkathooa kwa mũtũi waku, na kwĩanana na ũndũ myaka yĩana ya ngetha akathoosya kwaku.'),
('kam', 'LEV', 25, 16, 'Kwĩanana na wingĩ wa myaka ũkongela thooa wayo, na kwĩanana na ũvũthũ wa myaka ũkaola thooa wayo; nũndũ eũthooesya kwĩanana na ngetha o ũndũ yĩana.'),
('kam', 'LEV', 25, 17, 'Mũikakengane ene kwa ene; ĩndĩ kĩa Ngai waku: nũndũ ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 25, 18, 'Kwondũ wa ũu ĩkaai myamũlo yakwa, na sũvĩaai motw’ĩo makwa na kũmekaa; na mũkatũaa nthĩ vate mũisyo.'),
('kam', 'LEV', 25, 19, 'Na nthĩ ĩkasyaaa ũsyao wayo, na mũkaya na kũvũna, na kũtũa vo vate mũisyo.'),
('kam', 'LEV', 25, 20, 'Na ethĩwa mwĩasya, Tũkaya kyaũ mwaka wa mũonza? Sisya, tũikavanda, kana kũketha ngetha sitũ;'),
('kam', 'LEV', 25, 21, 'nĩvo nĩmwĩaĩĩa inyw’ĩ ũathimo wakwa mwaka wa thanthatũ, na mwaka ũsu ũkamũsyaĩa ũsyao vandũ va myaka ĩtatũ.'),
('kam', 'LEV', 25, 22, 'Na mũkavanda mwaka wa nyanya, na mũkaĩsaa o ala makũũ; kũvika mwaka wa kenda, kũvika mosyao maw’o makethwa, mũkaĩsaa o asu makũũ.'),
('kam', 'LEV', 25, 23, 'Na nthĩ ndĩkaathoow’e vyũ; nũndũ nthĩ nĩ yakwa: nũndũ inyw’ĩ mwĩ aeni na ekali ma ũeninĩ vamwe nakwa.'),
('kam', 'LEV', 25, 24, 'Na nthĩ yonthe ĩla ya ng’ũndũ yenyu mũketĩkĩle kwovoanĩasya nthĩ.'),
('kam', 'LEV', 25, 25, 'Ethĩwa mwana‐a‐au akatw’ĩka ngya, na kũthoosya kĩlungu kya ng’ũndũ yake, nĩvo ĩndĩ mũndũ wa mũvĩa wake ũla wa vakuvĩ nake wĩũka, na kwovosya kĩla mwana‐a‐ĩthe wathooisye.'),
('kam', 'LEV', 25, 26, 'Na ethĩwa mũndũ nde na mũndũ wake wa kũkyovosya, na esa kũtw’ĩka mũthwii na kwona ũthwii wĩanĩe wa kũkyovosya;'),
('kam', 'LEV', 25, 27, 'nĩvo ĩndĩ natale myaka ĩla ĩvĩtĩte kuma athoosya, na kũmũtũngĩa ũla mũndũ wamũthooee ũtandĩthyo wayo; nake akasyokea ng’ũndũ yake.'),
('kam', 'LEV', 25, 28, 'Ĩndĩ ethĩwa ndatonya kwĩyovoesya, nĩvo kĩla wathooisye kĩkekala kw’okonĩ kwa ũla wakĩthooie kũvika mwaka wa yuvilii: na mwaka ũsu wa yuvilii kĩkathaw’a, nake akasyokea ng’ũndũ yake.'),
('kam', 'LEV', 25, 29, 'Na ethĩwa mũndũ akathoosya nyũmba ya kwĩkala yĩ ndũanĩ mbiie, nĩvo wĩ na ũthei wa kũmyovosya mwaka ũmwe mũima ĩtina wa kũmĩthoosya; vandũ va mwaka mũima akeethĩwa na ũthei wa kũmyovosya.'),
('kam', 'LEV', 25, 30, 'Na ethiwa ndĩkovow’a vandũ va mwaka mũima, nĩvo nyũmba ĩla yĩ ndũanĩ mbiie ĩkalũmw’a yĩtw’ĩka vyũ ya ũla wamĩthooie, mosyaanĩonĩ make: ndĩkathaw’e mwaka wa yuvilii.'),
('kam', 'LEV', 25, 31, 'Ĩndĩ nyũmba ila syĩ mĩsyĩ ĩla ĩte miie ikatalwa vamwe na mĩũnda ya nthĩ: nitonya kwovow’a, na ikathaw’a mwaka wa yuvilii.'),
('kam', 'LEV', 25, 32, 'Ĩndĩ ndũa sya Alivai, nyũmba sya ndũa sya ng’ũndũ syoo, Alivai matonya kwovosya yĩla mekwenda.'),
('kam', 'LEV', 25, 33, 'Na ethĩwa mũndũ akoovosya kwa Alivai, nĩvo nyũmba ĩla yathooiw’e, na ndũa ya ng’ũndũ yake, ikathaw’a mwaka wa yuvilii; nũndũ nyũmba syĩ ndũanĩ sya Alivai nĩ ng’ũndũ sya Alivai katĩ wa ana ma Isilaeli.'),
('kam', 'LEV', 25, 34, 'Ĩndĩ mĩũnda yĩ syengonĩ sya ndũa syoo ititonya kũthoow’a; nũndũ nĩ ng’ũndũ yoo tene na tene.'),
('kam', 'LEV', 25, 35, 'Na ethĩwa mwana‐a‐au akatw’ĩka ngya mũno, na ndatonya kwĩyonea kĩndũ na kw’oko kwake e kwaku; nĩvo ĩndĩ mũtethye: akatũe naku ta mũeni na mwĩkali wa ũeninĩ.'),
('kam', 'LEV', 25, 36, 'Ndũkamwĩtye ũtandĩthyo kana wongeleko, ĩndĩ mũkĩe Ngai waku; nĩ kana mwana‐a‐au ekale naku.'),
('kam', 'LEV', 25, 37, 'Ndũkamũkovethye mbesa syaku kana wone ũtandĩthyo wasyo, kana kũmũmenga lĩu waku wone wongeleko waw’o.'),
('kam', 'LEV', 25, 38, 'Ninyie Yeova Ngai wenyu, ũla wamumisye nthĩ ya Misili, nĩmũnenge nthĩ ya Kanaani, nĩthĩwe Ngai wenyu.'),
('kam', 'LEV', 25, 39, 'Na ethĩwa mwana‐a‐au akatw’ĩka ngya atwĩe naku, na kwĩthoosya mwene kwaku; ndũkamũthũkũmĩthye ta ngombo.'),
('kam', 'LEV', 25, 40, 'Akekale naku ta mũthũkũmi ũtuvawa, na ta mwĩkali wa ũeninĩ; akakũthũkũme kũvika mwaka wa yuvilii:'),
('kam', 'LEV', 25, 41, 'nĩvo ĩndĩ wĩuma kwaku, we na syana syake vamwe nake, na akasyokea mũvĩa wake mwene, na akasyokea ng’ũndũ ya aaĩthe make.'),
('kam', 'LEV', 25, 42, 'Nũndũ nĩ athũkũmi makwa, ala naumisye nthĩ ya Misili: maikathoow’e methĩwe ngombo.'),
('kam', 'LEV', 25, 43, 'Ndũkamũsumbĩke na vinya, ĩndĩ mũkĩe Ngai waku.'),
('kam', 'LEV', 25, 44, 'Na ũndũ wa ngombo syaku aũme, na eĩtu, ila ũkethĩwa nasyo; sya mbaĩ ila imũthyũlũlũkĩte, kwasyo mũkathooa ngombo sya aũme na eĩtu.'),
('kam', 'LEV', 25, 45, 'O na ĩngĩ sya syana sya aeni ala mekalaa ũeni kwenyu mũkathooa kwasyo, na mĩvĩanĩ yasyo ĩla yĩ kwenyu, ila masyaĩe nthĩ yenyu: nasyo ikeethĩwa syenyu.'),
('kam', 'LEV', 25, 46, 'Na mũkamatw’ĩkĩthye ũtiĩwa wa syana syenyu ĩtina wenyu, methĩwe masyo; kuma andũnĩ asu mũkose ngombo syenyu tene na tene: ĩndĩ mũikasumbĩke ana‐a‐au, ana ma Isilaeli, ũmwe aisumbĩka ũngĩ na vinya.'),
('kam', 'LEV', 25, 47, 'Na ethĩwa mũeni kana mwĩkali wa ũeninĩ e kwaku akatw’ĩka mũthwii, na mwana‐a‐au aitw’ĩka ngya e vakuvĩ nake, na kwĩthooesya mũeni kana mwĩkali wa ũeninĩ ũla wĩ kwaku, kana andũ ma mũvĩa wa mũenĩ ũsu;'),
('kam', 'LEV', 25, 48, 've ũthei wa kwovow’a ĩtina wa kwĩthoosya kwake: ũmwe wa ana‐a‐ĩthe make nũtonya kũmwovosya;'),
('kam', 'LEV', 25, 49, 'kana mwendw’a ĩthe, kana mwana wa mwendw’a ĩthe, matonya kũmwovosya, kana mũndũ o na wĩva ũla wĩ vakuvĩ nake mbaĩnĩ yake nũtonya kũmwovosya; kana ethĩwa we mwene akatw’ĩka mũthwii, nũtonya kwĩyovosya.'),
('kam', 'LEV', 25, 50, 'Na akatalana na ũla wamũthooie kuma mwaka ũla wethooisye kwake kũvika mwaka wa yuvilii: na mbesa sya kwĩthoosya kwake ikeethĩwa kwĩanana na ũndũ myaka yĩana; akeethĩwa nake kwĩanana na ĩvinda ya mũthũkũmi ũtuvawa.'),
('kam', 'LEV', 25, 51, 'Ethĩwa kũkeethĩwa kũtiele myaka mingĩ, kwĩanana na ũndũ yĩana, akaĩva mbesa sya wovosyo wake kũsyumya mbesanĩ ila wathooiwe nasyo.'),
('kam', 'LEV', 25, 52, 'Na ethĩwa no myaka mĩvũthũ ĩtiele kũvika mwaka wa yuvilii, nĩvo wĩtalana nake; kwĩanana na myaka yake ũndũ yĩana akaĩve mbesa sya wovosyo wake.'),
('kam', 'LEV', 25, 53, 'Akekale nake ta mũthũkũmi ũtuvawa mwaka na mwaka: na ũsu ndakamũsumbĩke na vinya wene.'),
('kam', 'LEV', 25, 54, 'Na ethĩwa ndakovow’a myaka ĩsu, nĩvo ĩndĩ wĩuma mwaka wa yuvilii, we, na syana syake vamwe nake.'),
('kam', 'LEV', 25, 55, 'Nũndũ ana ma Isilaeli nĩ athũkũmi makwa; nĩ athũkũmi makwa ala naumisye nthĩ ya Misili: ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 26, 1, 'Mũikeseũvĩsye mĩvw’anano o na yĩva, o na mũikeũngamĩsye mũvw’anano mwasũvye, kana kĩtuĩ, o na mũikaie ĩvia o na yĩva yĩvanĩtwe nthĩ yenyu, nĩ kana mũyĩkunamĩe: nũndũ ninyie Yeova Ngai wenyu.'),
('kam', 'LEV', 26, 2, 'Lilikanai masavato makwa, na kũtaĩa vandũ vakwa vatheu: ninyie Yeova.'),
('kam', 'LEV', 26, 3, 'Ethĩwa mũkaendaa myamũlonĩ yakwa, na kũkwataa mĩao yakwa, na kũmĩkaa;'),
('kam', 'LEV', 26, 4, 'nĩvo ngaete mbua yenyu ivinda yayo, na nthĩ ĩkasyaaa ũsyao wayo, na mĩtĩ ya mũũnda ĩkasyaaa ũsyao wayo.'),
('kam', 'LEV', 26, 5, 'Na ngetha yenyu ya ũvũa ĩkekaala kũvika ngetha ya mĩũnda ya mĩsavivũ, na ngetha ĩsu ya mĩsavivũ ĩkekalaa kũvika ĩvinda ya kũvanda; na mũkaĩsaa lĩu wenyu na kũvũna, na kwĩkalaa nthĩ yenyu vate mũisyo.'),
('kam', 'LEV', 26, 6, 'Nakwa ngamĩnenga nthĩ mũuo, na mũkakomaa, na vaiĩ ũla wĩtuma mũkĩa: ngamina nyamũ mbai nthĩ yenyu, o na ũvyũ ndũkavĩtĩle nthĩ yenyu.'),
('kam', 'LEV', 26, 7, 'Mũkalũngya amaitha menyu, na makavalũkw’a mbee wenyu na ũvyũ.'),
('kam', 'LEV', 26, 8, 'Andũ atano menyu makalũngya ĩana, na ĩana menyu makalũngya ngili ĩkũmi; na amaitha menyu makavalũkw’a mbee wenyu na ũvyũ.'),
('kam', 'LEV', 26, 9, 'Na ngamwĩtĩkĩla, na ngamwongeleela, na kũmwingĩvya, na ngalũlũmĩlya ũtianĩo wakwa nenyu.'),
('kam', 'LEV', 26, 10, 'Mũkaĩsaa lĩu ũla mũkũũ wa mbio mĩthenya mingĩ, na mũkaumaalya ũla mũkũũ nũndũ wa ũla mweũ.'),
('kam', 'LEV', 26, 11, 'Na ngaaka wĩkalo wakwa katĩ wenyu: na ngoo yakwa ndĩkamũthĩtha.'),
('kam', 'LEV', 26, 12, 'Na ngaendaa katĩ wenyu, na ngeethĩwa Ngai wenyu, nenyu mũkeethĩwa andũ makwa.'),
('kam', 'LEV', 26, 13, 'Ninyie Yeova Ngai wenyu, ũla wamumisye nthĩ ya Misili, nĩ kana mũtikethĩwe ngombo syoo; na nĩndũlĩte mĩtĩ ya ĩsoki yenyu, na kũmũendethya mũlũngalĩte.'),
('kam', 'LEV', 26, 14, 'Ĩndĩ ethĩwa mũikambĩthukĩĩsya, na mũikakwata mĩao ĩno yonthe;'),
('kam', 'LEV', 26, 15, 'na ethĩwa mũkalea myamũlo yakwa, na ngoo yenyu ĩkathĩtha motw’ĩo makwa, ũndũ mũteka mĩao yakwa yonthe, ĩndĩ mũkyananga ũtianĩo wakwa;'),
('kam', 'LEV', 26, 16, 'nakwa ngamwĩka ũũ: ngeeaĩa w’ĩa ĩũlũ wenyu, ũwau wa ũkooa na ndetema, ũla wanangaa metho, na kũtuma thayũ ũsonzoma; na mũkavanda mbeũ syenyu mana, nũndũ amaitha menyu makaiya.'),
('kam', 'LEV', 26, 17, 'Ngamũlutĩla ũthyũ wakwa, na mũkakũnwa mbee wa amaitha menyu: ala mamũmenaa makamũsumbĩka; na mũkasemba yĩla vate mũndũ ũmũatĩĩĩte.'),
('kam', 'LEV', 26, 18, 'Na ethĩwa ĩtina wa maũndũ asu mũtikambĩthukĩĩsya, nĩvo ĩndĩ ngamũkũna makũna angĩ mũonza nũndũ wa naĩ syenyu.'),
('kam', 'LEV', 26, 19, 'Ngaananga ngathĩĩo ya vinya wenyu: na ngatw’ĩkĩthya ĩtu yenyu yĩthĩwe ta kĩaa, na nthĩ yenyu ta ũthuku;'),
('kam', 'LEV', 26, 20, 'na mũkananga vinya wenyu ta ũthuku; na mũkananga vinya wenyu mana; nũndũ nthĩ yenyu ndĩkasyaa ũsyao wayo, o na mĩtĩ ya nthĩ ndĩkasyaa ũsyao wayo.'),
('kam', 'LEV', 26, 21, 'Na ethĩwa mũkaendea na kũndea, na mũikambĩthukĩĩsya, ngamũetee mothĩn’yo kũndũ mũonza kwĩanana na naĩ syenyu.'),
('kam', 'LEV', 26, 22, 'Na ngaete nyamũ sya kĩtheka kwenyu, ila ikamũvuta syana syenyu, na kwananga indo syenyu, na mũkatiwa mwĩ avũthũ ũtalonĩ wenyu; na nzĩa syenyu ikaekwa.'),
('kam', 'LEV', 26, 23, 'Na ethĩwa kwondũ wa maũndũ asu mũtikaalyũlwa ninyie, ĩndĩ mũkaendeea na kũndea;'),
('kam', 'LEV', 26, 24, 'nĩvo ĩndĩ ngamũlea; na ngamũkũna, o nyie, makũna mũonza kwondũ wa naĩ syenyu.'),
('kam', 'LEV', 26, 25, 'Na ngaete ũvyũ wũke ĩũlũ wenyu, ũla ũkaĩvanĩsya ũĩvanĩsyo kwondũ wa ũtianĩo; na mũkoombanĩw’a ndũanĩ syenyu: na ngaete mũimũ katĩ wenyu; na mũkanenganwe kw’okonĩ kwa mũmaitha.'),
('kam', 'LEV', 26, 26, 'Yĩla nĩtũla ndata yenyu ya kĩmũtũ, aka ĩkũmi makauĩa kĩmũtũ kyenyu ikonĩ yĩmwe, na makamũnenga ĩngĩ kĩmũtũ kyenyu kwondũ wa kũthima: na mũkaya, na mũikavũna.'),
('kam', 'LEV', 26, 27, 'Na ethĩwa ĩtina wa ũu w’onthe mũkalea kũmbĩthukĩĩsya, ĩndĩ mũkaendeea na kũndea;'),
('kam', 'LEV', 26, 28, 'nĩvo ĩndĩ nakwa ngamũlea nĩ mũthilĩku; o na ngamũkũna makũna mũonza kwondũ wa naĩ syenyu.'),
('kam', 'LEV', 26, 29, 'Na mũkaya nyama sya ana maku, na nyama sya eĩtu maku mũkaya.'),
('kam', 'LEV', 26, 30, 'Na ngaananga kũndũ kwenyu kũtũlu, na kũtema mĩvw’anano yenyu ya syũa, na kwĩkya simba syenyu ĩũlũ wa mĩĩ ya mĩvw’anano yenyu; na ngoo yakwa ĩkamũthĩtha inyw’ĩ.'),
('kam', 'LEV', 26, 31, 'Na ngatw’ĩkĩthya ndũa syenyu maanzo, na ngaananga kũndũ kwenyu kũtheu, na ndikanyungĩa mĩuke yenyu mĩseo.'),
('kam', 'LEV', 26, 32, 'Na ngatw’ĩkĩthya nthĩ nthei; na amaitha menyu ala memĩtũa makaseng’a nũndũ wayo.'),
('kam', 'LEV', 26, 33, 'Nenyu ngamũnyaĩĩkya i mbaĩnĩ, na ngamũatĩĩa nĩkũĩte ũvyũ: na nthĩ yenyu ĩkeethĩwa nthei, na ndũa syenyu ikeethĩwa maanzo.'),
('kam', 'LEV', 26, 34, 'Nĩvo ĩndĩ nthĩ ĩkatanĩa masavato mayo, o ĩvinda yĩla yĩ nthei, na inyw’i mwĩ nthĩ ya amaitha menyu; o ĩvinda yĩu nthĩ ĩkathũmũa, na kũtanĩa masavato mayo.'),
('kam', 'LEV', 26, 35, 'O yĩla yĩ nthei ĩkeethĩwa na ũthũmũo, o ũthũmũo ũla ĩtaĩ naw’o masavatonĩ menyu, yĩla mwamĩtwĩe.'),
('kam', 'LEV', 26, 36, 'Na ũndũ wa ala menyu metiala, ngeekĩa ũleelu ngoonĩ syoo me nthĩ sya amaitha moo: na wasya wa ĩtũ yĩkĩthingithangw’a ũkatuma masemba; na makakĩa, ta mũndũ ũkĩĩte ũvyũ; na makavalũka yĩla vate mũndũ ũmaatĩĩĩte.'),
('kam', 'LEV', 26, 37, 'Na makavalũkangan’ya ene kwa ene, o ta makĩĩte mbee wa ũvyũ, yĩla vate mũndũ ũmaatĩĩĩte: na mũtikethĩwa na vinya wa kũũngama mbee wa amaitha menyu.'),
('kam', 'LEV', 26, 38, 'Na mũkaanangĩka mbaĩnĩ sya nthĩ, na nthĩ ya amaitha menyu ĩkamũmina.'),
('kam', 'LEV', 26, 39, 'Na ala menyu metiala makasonzomea naĩnĩ yoo me nthĩ sya amaitha menyu: o na mothũkũnĩ ma aaĩthe moo makasonzomea vamwe nao.'),
('kam', 'LEV', 26, 40, 'Na makaumbũla ũthũku woo, na ũthũku wa aaĩthe moo, ũndũ wa ĩvĩtyo yoo yĩla mambĩtanĩsye, na ĩngĩ, nũndũ maendeeie makĩndea,'),
('kam', 'LEV', 26, 41, 'nakwa naendeea ngĩmalea, na namatwaa nthĩ ya amaitha moo: ethĩwa ĩndĩ ngoo yoo ĩte mbaĩke ĩkeenyivya, na kwĩtĩkĩla ũsilĩlo wa ũthũku woo;'),
('kam', 'LEV', 26, 42, 'nĩvo ĩndĩ ngalilikana ũtianĩo wakwa na Yakovo; o na ũtianĩo wakwa na Isaka, o na ũtianĩo wakwa na Avalaamu ngalilikana; na ngalilikana ĩ nthĩ.'),
('kam', 'LEV', 26, 43, 'Nthĩ nayo ĩkatiwa nĩo, na ĩkatanĩa masavato mayo, yĩla yĩĩthĩwa nthei nao mate vo: na makeetĩkĩla ũsilĩlo wa ũthũku woo, nĩkwĩthĩwa, ĩĩ nĩkwĩthĩwa nĩmaleile motw’ĩo makwa, na ngoo syoo nĩsyathĩthie myamũlo yakwa.'),
('kam', 'LEV', 26, 44, 'Ĩndĩ o na ũu w’onthe, yĩla me nthĩ ya amaitha moo, nyie ndikamalea, o na ndikamathĩtha, nĩmanange vyũ, na kwananga ũtianĩo wakwa nao; nũndũ nyie nĩ Yeova Ngai woo;'),
('kam', 'LEV', 26, 45, 'ĩndĩ kwondũ woo ngalilikana ũtianĩo wa aaĩthe moo, ala naumisye nthĩ ya Misili mbaĩ sya nthĩ syene, nĩ kana nĩthĩwe Ngai woo: ninyie Yeova.'),
('kam', 'LEV', 26, 46, 'Myamũlo na motw’ĩo na mĩao, nĩyo ĩsu, ĩla Yeova watwie katĩ wake na ana ma Isilaeli kĩĩmanĩ kya Sinai na kanyw’a wa Mose.'),
('kam', 'LEV', 27, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'LEV', 27, 2, 'Neena na ana ma Isilaeli, noimea, Yĩla mũndũ wĩĩvĩta wĩvĩto, andũ makeethĩwa ma Yeova kwĩanana na ũndũ wĩmatalĩla wovosyo.'),
('kam', 'LEV', 27, 3, 'Na ũtalo waku ũkethĩwe ũũ: wa mũndũ mũũme kuma ũla wa myaka mĩongo ĩlĩ kũvika ũla wa myaka mĩongo thanthatũ, ũtalo waku ũkethĩwe sekeli mĩongo ĩtano ya vetha, kwĩanana na sekeli ya vala vandũ vatheu.'),
('kam', 'LEV', 27, 4, 'Na ethĩwa nĩ mũndũ mũka, nĩvo ũtalo waku ũkethĩwe sekeli mĩongo ĩtatũ.'),
('kam', 'LEV', 27, 5, 'Na ethĩwa nĩ kuma myaka ĩtano kũvika myaka mĩongo ĩlĩ, nĩvo ũtalo waku wa mũndũ mũũme ũkethĩwe sekeli mĩongo ĩlĩ, na wa mũndũ mũka sekeli ĩkũmi.'),
('kam', 'LEV', 27, 6, 'Na ethĩwa nĩ kuma mwei ũmwe kũvika myaka ĩtano, nĩvo ũtalo waku wa mũndũ mũũme ũkethĩwe sekeli itano sya vetha, na wa mũndũ mũka ũtalo waku ũkethĩwe sekeli itatũ sya vetha.'),
('kam', 'LEV', 27, 7, 'Na ethĩwa nĩ kuma myaka mĩongo thanthatũ na mbee; ethĩwa nĩ mũndũ mũũme, ũtalo waku ũkethĩwe sekeli ĩkũmi na itano, na wa mũndũ mũka sekeli ĩkũmi.'),
('kam', 'LEV', 27, 8, 'Ĩndĩ ethĩwa nĩ ngya ũndũ ũtatonya kumya ũtalo ũsu waku, nĩvo ĩndĩ wĩetwe mbee wa mũthembi, na mũthembi akamũtw’ĩĩe thooa; kwĩanana na ũtonyi wa ũla wevĩtie nĩw’o mũthembi wĩmũtw’ĩĩa thooa.'),
('kam', 'LEV', 27, 9, 'Na ethĩwa nĩ nyamũ, ĩla andũ mamũthembeaa Yeova nthembo nayo, syonthe sya isu ila andũ mamũnengae Yeova ikeethĩwa ntheu.'),
('kam', 'LEV', 27, 10, 'Ndakamĩalyũle kana kũmĩkũan’ya, nzeo vandũ va nthũku, kana nthũku vandũ va nzeo: na ethĩwa akakũan’ya nyamũ kwa nyamũ, nĩvo ĩndĩ ĩsu na ĩla ngũan’ye syelĩ ikeethĩwa ntheu.'),
('kam', 'LEV', 27, 11, 'Na ethĩwa nĩ nyamũ mbuku o na yĩva, ĩla matamũthembeaa Yeova, nĩvo ĩndĩ akaete nyamũ mbee wa mũthembi;'),
('kam', 'LEV', 27, 12, 'na mũthembi akatw’e thooa wayo, ethĩwa nĩ nzeo kana nthũku: o tondũ we mũthembi wĩtw’a thooa wayo, kũkeethĩwa ũu.'),
('kam', 'LEV', 27, 13, 'Ĩndĩ ethĩwa nĩ w’o akamyovosya, akongeleele ũtalo waku kĩlungu kya katano kyaw’o.'),
('kam', 'LEV', 27, 14, 'Na yĩla mũndũ wĩmũvathĩa Yeova nyũmba yake yĩthĩwe ntheu, nĩvo mũthembi wĩtw’a thooa wayo, ethĩwa nĩ nzeo kana nthũku; o ũndũ mũthembi wĩtw’a thooa wayo, o ũu thooa ũkekala.'),
('kam', 'LEV', 27, 15, 'Na ethĩwa ũla wamĩvathie yĩthĩwe ntheu akenda kwovosya nyũmba yake, akawongeleele ũtalo waku kĩlungu kya katano kya mbesa, na ĩkeethĩwa yake.'),
('kam', 'LEV', 27, 16, 'Na ethĩwa mũndũ akamũvathĩa Yeova kĩlungu kya mũũnda wake wa ng’ũndũ yake kĩthĩwe kĩtheu, nĩvo ũtalo waku ũkethĩwe kwĩanana na kũvandwa kwaw’o: kũvandwa kwa omeli ya mbaale kũkatalwe thooa wakw’o sekeli mĩongo ĩtano sya vetha.'),
('kam', 'LEV', 27, 17, 'Ethĩwa akavatha mũũnda wake wĩthĩwe mũtheu kuma mwaka wa yuvilii, ũtalo waku o ũndũ wĩana ũkekale.'),
('kam', 'LEV', 27, 18, 'Ĩndĩ ethĩwa akavatha mũũnda wake wĩthĩwe mũtheu mwaka wa yuvilii wathela, nĩvo mũthembi ũkamũtalĩle mbesa kwĩanana na ũndũ myaka yĩana ĩla yĩtialĩte ya kũvika mwaka wa yuvilii; na ikaolwe ũtalonĩ waku.'),
('kam', 'LEV', 27, 19, 'Na ethĩwa ũla wavathie mũũnda wĩthĩwe mũtheu akenda kũwovosya, akongeleele ũtalo waku kĩlungu kya katano kya mbesa syaw’o, na ũkeethĩwa wake.'),
('kam', 'LEV', 27, 20, 'Na ethĩwa ndekwenda kwovosya mũũnda, kana ethĩwa nũmũthooesye mũndũ ũngĩ mũũnda ũsu, ndũtonyeka kwovow’a ĩngĩ:'),
('kam', 'LEV', 27, 21, 'ĩndĩ mũũnda, yĩla wĩekwa mwaka wa yuvilii, ũkeethĩwa wĩ mũtheu kwa Yeova, o ta mũũnda wavathiwe; ũkeethĩwa wa mũthembi.'),
('kam', 'LEV', 27, 22, 'Na ethĩwa akavatha mũũnda ũla wathooie wĩthĩwe mũtheu kwa Yeova, na ti mũũnda wa ng’ũndũ yake;'),
('kam', 'LEV', 27, 23, 'nĩvo ĩndĩ mũthembi wĩmũtalĩla thooa kwĩanana na ũtalo waku kũvika mwaka wa yuvilii: na mũthenya ũsu akanengane thooa ũla ũtalĩte, wĩthĩwe kĩndũ kĩtheu kwa Yeova.'),
('kam', 'LEV', 27, 24, 'Mwaka wa yuvilii mũũnda nũsyokee ũla wathooisye, o ũsu ũla ĩ nthĩ nĩ yake.'),
('kam', 'LEV', 27, 25, 'Na motalo maku onthe makethĩwe kwĩanana na sekeli wa vala vandũ vatheu: ngela mĩongo ĩlĩ ĩkeethĩwa sekeli.'),
('kam', 'LEV', 27, 26, 'Ĩndĩ kĩla kĩsyaawa mbee nĩ nyamũ, kĩla kĩvathĩwe Yeova kĩthĩwe ũsyao wa mbee, mũndũ o na wĩva ndakavathe kĩthĩwe kĩtheu; ethĩwa nĩ ng’ombe kana ĩlondu, nĩ ya Yeova.'),
('kam', 'LEV', 27, 27, 'Na ethĩwa nĩ kya nyamũ mbuku, nĩvo akakyovosya kwĩanana na ũtalo waku, na akakyongeleele kĩlungu kya katano kyakyo: kana ethĩwa kĩtiovow’a, nĩvo kĩkathoow’a kwĩanana na ũtalo waku.'),
('kam', 'LEV', 27, 28, 'Ĩndĩ, kĩndũ o na kĩva kĩvathe, kĩla mũndũ ũvathĩe Yeova kya syonthe ila wĩ nasyo, ethĩwa nĩ mũndũ kana nyamũ, kana mũũnda wa ng’ũndũ yake, kĩtikathoow’e kana kwovow’a: kĩla kĩndũ kĩvathe nĩ kĩtheu mũno kwa Yeova.'),
('kam', 'LEV', 27, 29, 'Mũndũ o na wĩva mũvathe, ũla ũkavathwa kuma andũnĩ, ndakovow’e; no mũvaka oawe.'),
('kam', 'LEV', 27, 30, 'Na kĩlungu kyonthe kya ĩkũmi kya nthĩ, ethĩwa nĩ kya mbeũ sya nthĩ, kana ũsyao wa mũtĩ, nĩ kya Yeova: nĩ kĩtheu kwa Yeova.'),
('kam', 'LEV', 27, 31, 'Na ethĩwa mũndũ akenda kwovosya kĩlungu kyake kya ĩkũmi, akakyongeleele kĩlungu kya katano.'),
('kam', 'LEV', 27, 32, 'Na kĩlungu kyonthe kya ĩkũmi kya ndĩthya ya ng’ombe kana ya mbũi na malondu, o kĩla kĩvĩtĩlaa ĩtheo wa ndata, kĩlungu kya ĩkũmi kĩkeethĩwa kĩtheu kwa Yeova.'),
('kam', 'LEV', 27, 33, 'Ndakasisye ethĩwa nĩ nzeo kana nthũku, na ndakakũan’ye: na ethĩwa akakũan’ya, nĩvo ĩndĩ ĩsu na ĩla ngũan’ye syelĩ ikeethĩwa ntheu; ndĩkovow’a.'),
('kam', 'LEV', 27, 34, 'Ĩsu nĩyo mĩao, ĩla Yeova wamwĩaĩe Mose kwondũ wa ana ma Isilaeli kĩĩmanĩ kya Sinai.'),
('kam', 'NUM', 1, 1, 'Na Yeova aneena na Mose weũnĩ wa Sinai, ĩeemanĩ ya kũmbanĩa, mũthenya wa mbee wa mwei wa kelĩ, mwaka wa kelĩ ĩtina wa mauma nthĩ ya Misili, aimwĩa,'),
('kam', 'NUM', 1, 2, 'Tala ũmbano w’onthe wa ana ma Isilaeli, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, kĩla mũndũ mũũme, o mũndũ na mũndũ;'),
('kam', 'NUM', 1, 3, 'ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ma Isilaeli ala matonya kũthi kaũnĩ, we na Aluni mũkamatale kũatĩĩa nguthu syoo.'),
('kam', 'NUM', 1, 4, 'Na mũndũ ũmwe wa kĩla mbaĩ akethĩwe vamwe nenyu; kĩla ũmwe mũtongoi wa nyũmba ya aaĩthe make.'),
('kam', 'NUM', 1, 5, 'Na aa nĩ masyĩtwa ma andũ ala makaũngama nenyu. Wa Leuveni nĩ Elisuli mwana wa Seteuli.'),
('kam', 'NUM', 1, 6, 'Wa Simeoni: Selumieli mwana wa Nzulisatai.'),
('kam', 'NUM', 1, 7, 'Wa Yuta: Nasoni mwana wa Aminatavu.'),
('kam', 'NUM', 1, 8, 'Wa Isakali: Nethaneli mwana wa Nzuali.'),
('kam', 'NUM', 1, 9, 'Wa Nzevuluni: Eliavu mwana wa Eeloni.'),
('kam', 'NUM', 1, 10, 'Ma ana ma Yosevu: Wa Evalaimu: Elisama mwana wa Amiuti. Wa Manase: Ngamalieli mwana wa Vetasuli.'),
('kam', 'NUM', 1, 11, 'Wa Mbenyamini: Avitani mwana wa Kiteoni.'),
('kam', 'NUM', 1, 12, 'Wa Ndani: Aieseli mwana wa Amisatai.'),
('kam', 'NUM', 1, 13, 'Wa Aseli: Vakieli mwana wa Okalani.'),
('kam', 'NUM', 1, 14, 'Wa Ngati: Eliasavu mwana wa Ndeueli.'),
('kam', 'NUM', 1, 15, 'Wa Navitali: Aila mwana wa Enani.'),
('kam', 'NUM', 1, 16, 'Asu nĩo meetiwe nthĩnĩ wa ũla ũmbano, anene ma mbaĩ sya aaĩthe moo; nĩmo maĩ atongoi ma ngili sya Isilaeli.'),
('kam', 'NUM', 1, 17, 'Na Mose na Aluni moosa andũ asu ala mawetiwe na masyĩtwa moo:'),
('kam', 'NUM', 1, 18, 'nao moomban’ya ũmbano w’onthe mũthenya wa mbee wa mwei wa kelĩ; na matavan’ya mosyaanĩo moo kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ũla ũvikĩtye myaka mĩongo ĩlĩ na mbee, mũndũ na mũndũ.'),
('kam', 'NUM', 1, 19, 'O tondũ Yeova wamwĩaĩe Mose, nĩw’o wamatalĩle weũnĩ wa Sinai.'),
('kam', 'NUM', 1, 20, 'Na ana ma Leuveni, ĩkithathi ya Isilaeli, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, mũndũ na mũndũ, kĩla mũndũ mũũme ũvikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 21, 'ala matalilwe, ma mbaĩ ya Leuveni, maĩ ngili mĩongo ĩna na thanthatũ na maana atano.'),
('kam', 'NUM', 1, 22, 'Ma ana ma Simeoni, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, ala matalilwe, kwĩanana na ũtalo wa masyĩtwa, mũndũ na mũndũ, kĩla mũndũ mũũme ũvikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 23, 'ala matalilwe, ma mbaĩ ya Simeoni, maĩ ngili mĩongo ĩtano na kenda na maana atatũ.'),
('kam', 'NUM', 1, 24, 'Ma ana ma Ngati, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 25, 'ala matalilwe, ma mbaĩ ya Ngati, maĩ ngili mĩongo ĩna na itano na maana thanthatũ na mĩongo ĩtano.'),
('kam', 'NUM', 1, 26, 'Ma ana ma Yuta, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 27, 'ala matalilwe, ma mbaĩ ya Yuta, maĩ ngili mĩongo mũonza na inya na maana thanthatũ.'),
('kam', 'NUM', 1, 28, 'Ma ana ma Isakali, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 29, 'ala matalilwe, ma mbaĩ ya Isakali, maĩ ngili mĩongo ĩtano na inya na maana ana.'),
('kam', 'NUM', 1, 30, 'Ma ana ma Nzevuluni, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 31, 'ala matalilwe, ma mbaĩ ya Nzevuluni, maĩ ngili mĩongo ĩtano na mũonza na maana ana.'),
('kam', 'NUM', 1, 32, 'Ma ana ma Yosevu, nao nĩ ma ana ma Evalaimu, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 33, 'ala matalilwe, ma mbaĩ ya Evalaimu, maĩ ngili mĩongo ĩna na maana atano.'),
('kam', 'NUM', 1, 34, 'Ma ana ma Manase, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 35, 'ala matalilwe, ma mbaĩ ya Manase, maĩ ngili mĩongo ĩtatũ na ilĩ na maana elĩ.'),
('kam', 'NUM', 1, 36, 'Ma ana ma Mbenyamini, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũni;'),
('kam', 'NUM', 1, 37, 'ala matalilwe, ma mbaĩ ya Mbenyamini, maĩ ngili mĩongo ĩtatũ na itano na maana ana.'),
('kam', 'NUM', 1, 38, 'Ma ana ma Ndani, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 39, 'ala matalilwe, ma mbaĩ ya Ndani, maĩ ngili mĩongo thanthatũ na ilĩ na maana mũonza.'),
('kam', 'NUM', 1, 40, 'Ma ana ma Aseli, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 41, 'ala matalilwe, ma mbaĩ ya Aseli, maĩ ngili mĩongo ĩna na ĩmwe na maana atano.'),
('kam', 'NUM', 1, 42, 'Ma ana ma Navitali, nzyawa syoo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, kwĩanana na ũtalo wa masyĩtwa, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 43, 'ala matalilwe, ma mbaĩ ya Navitali, maĩ ngili mĩongo ĩtano na itatũ na maana ana.'),
('kam', 'NUM', 1, 44, 'Asu nĩo ala matalilwe, ala Mose na Aluni matalile, na anene ma Isilaeli, andũ ĩkũmi na elĩ: kĩla ũmwe aĩ vandũ va nyũmba ya aaĩthe make.'),
('kam', 'NUM', 1, 45, 'Na ĩndĩ onthe ala matalilwe ma ana ma Isilaeli kũatĩĩa nyũmba sya aaĩthe moo, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, onthe ma Isilaeli ala maĩ matonya kũthi kaũnĩ;'),
('kam', 'NUM', 1, 46, 'onthe nao ala matalilwe maĩ ngili maana thanthatũ na itatũ na maana atano na mĩongo ĩtano.'),
('kam', 'NUM', 1, 47, 'Ĩndĩ Alivai kũatĩĩa mbaĩ ya aaĩthe moo matyaatalanĩlw’a na asu.'),
('kam', 'NUM', 1, 48, 'Nũndũ Yeova nĩwaneenie na Mose, akĩmwĩa,'),
('kam', 'NUM', 1, 49, 'No mbaĩ ya Livai ĩtetalwa, o na ndũkamatalanĩlye na ana ma Isilaeli;'),
('kam', 'NUM', 1, 50, 'ĩndĩ maie Alivai asyaĩĩsya ma wĩkalo wa ũkũsĩ, na asyaĩĩsya ma mĩio yonthe yĩ nthĩnĩ waw’o, na asyaĩĩsya ma syĩndũ syonthe syaw’o: makakuae wĩkalo, na mĩio yaw’o yonthe; na makothũkũmae, na makambae maeema moo mathyũlũlũkĩte wĩkalo.'),
('kam', 'NUM', 1, 51, 'Na yĩla wĩkalo wĩtwawa mbee, Alivai makothasye; na yĩla wĩkalo wĩũngamw’a, Alivai makawakae: na mũeni ũla wĩthengeea mũvaka oawe.'),
('kam', 'NUM', 1, 52, 'Na ana ma Isilaeli makambae maeema moo, kĩla mũndũ vala ve mwako wa maeema wake mwene, na kĩla mũndũ vala ve kĩvevelo kyake mwene, o ũndũ nguthu syoo itilyĩ.'),
('kam', 'NUM', 1, 53, 'Ĩndĩ Alivai makambae maeema moo mathyũlũlũkĩte wĩkalo wa ũkũsĩ, nĩ kana vaikethĩwe ũthilĩku ĩũlũ wa ũmbano wa ana ma Isilaeli: na Alivai makasũvĩae wĩaĩo wa wĩkalo wa ũkũsĩ.'),
('kam', 'NUM', 1, 54, 'Ũu nĩw’o ana ma Isilaeli meekie; kwĩanana na onthe ala Yeova wamwĩaĩe Mose, nĩw’o meekie.'),
('kam', 'NUM', 2, 1, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'NUM', 2, 2, 'Ana ma Isilaeli makambae maeema moo kĩla mũndũ vakuvĩ na kĩvevelo kyake mwene, kĩ na ũvano wa nyũmba sya aaĩthe make: kũyelekela ĩeema ya kũmbanĩa, nĩvo meambaa maeema moo mayĩthyũlũlũkĩte ngalĩ syonthe.'),
('kam', 'NUM', 2, 3, 'Na ala meambaa maeema moo ngalĩ ya wumĩlonĩ wa syũa kwelekela vala syũa yumĩlaa makeethĩwa ala ma kĩvevelo kya mwako wa maeema wa Yuta, kwĩanana na nguthu syoo: na mũnene wa ana ma Yuta akeethĩwa Nasoni mwana wa Aminatavu.'),
('kam', 'NUM', 2, 4, 'Na nguthu yake, na ala matalilwe mayo maĩ ngili mĩongo mũonza na inya na maana thanthatũ.'),
('kam', 'NUM', 2, 5, 'Na ala meambaa maeema moo vakuvĩ nake makeethĩwa ma mbaĩ ya Isakali: na mũnene wa ana ma Isakali akeethĩwa Nethaneli mwana wa Nzuali.'),
('kam', 'NUM', 2, 6, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩtano na inya na maana ana.'),
('kam', 'NUM', 2, 7, 'Na mbaĩ ya Nzevuluni: na mũnene wa ana ma Nzevuluni akeethĩwa Eliavu mwana wa Eeloni.'),
('kam', 'NUM', 2, 8, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩtano na mũonza na maana ana.'),
('kam', 'NUM', 2, 9, 'Onthe ala matalilwe ma mwako wa maeema wa Yuta maĩ ngili ĩana na mĩongo nyanya na thanthatũ na maana ana, kwĩanana na nguthu syoo. Asu nĩo meambaa kũthi.'),
('kam', 'NUM', 2, 10, 'Ngalĩ ya ĩtheo kũkethĩwe kĩvevelo kya mwako wa maeema wa Leuveni kwĩanana na nguthu syoo: na mũnene wa ana ma Leuveni akeethĩwa Elisuli mwana wa Seteuli.'),
('kam', 'NUM', 2, 11, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩna na thanthatũ na maana atano.'),
('kam', 'NUM', 2, 12, 'Na ala meambaa maeema moo vakuvĩ nake makeethĩwa ma mbaĩ ya Simeoni: na mũnene wa ana ma Simeoni akeethĩwa Selumieli mwana wa Nzuli‐satai.'),
('kam', 'NUM', 2, 13, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩtano na kenda na maana atatũ.'),
('kam', 'NUM', 2, 14, 'Na mbaĩ ya Ngati: na mũnene wa ana ma Ngati akeethĩwa Eliasavu mwana wa Leueli.'),
('kam', 'NUM', 2, 15, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩna na itano na maana thanthatũ na mĩongo ĩtano.'),
('kam', 'NUM', 2, 16, 'Onthe ala matalilwe ma mwako wa maeema wa Leuveni maĩ ngili ĩana na mĩongo ĩtano na ĩmwe na maana ana na mĩongo ĩtano, kwĩanana na nguthu syoo. Asu nĩo ma kelĩ ma kũthi.'),
('kam', 'NUM', 2, 17, 'Nĩvo ĩndĩ ĩeema ya kũmbanĩa yĩendaa, yĩ vamwe na mwako wa maeema ma Alivai katĩ wa myako ya maeema yonthe: o ũndũ mambaa maeema moo, now’o makathi, kĩla mũndũ vandũ vake, vakuvĩ na kĩvevelo kyoo.'),
('kam', 'NUM', 2, 18, 'Ngalĩ ya ũthũĩlonĩ wa syũa kũkethĩwe kĩvevelo kya mwako wa maeema wa Evalaimu kwĩanana na nguthu syoo: na mũnene wa ana ma Evalaimu akeethĩwa Elisama mwana wa Amiuti.'),
('kam', 'NUM', 2, 19, 'Na nguthu yake, na ala matalilwe mayo maĩ ngili mĩongo ĩna na maana atano.'),
('kam', 'NUM', 2, 20, 'Na vakuvĩ nake kũkeethĩwa mbaĩ ya Manase: na mũnene wa ana ma Manase akeethĩwa Ngamalieli mwana wa Vetasuli.'),
('kam', 'NUM', 2, 21, 'Na nguthu yake na ala matalilwe mayo, maĩ ngili mĩongo ĩtatũ na ilĩ na maana elĩ.'),
('kam', 'NUM', 2, 22, 'Na mbaĩ ya Mbenyamini: na mũnene wa ana ma Mbenyamini akeethĩwa Avĩtani mwana wa Kiteoni.'),
('kam', 'NUM', 2, 23, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩtatũ na itano na maana ana.'),
('kam', 'NUM', 2, 24, 'Onthe ala matalilwe ma mwako wa maeema wa Evalaimu maĩ ngili ĩana na nyanya na ĩana yĩmwe, kwĩanana na nguthu syoo. Asu nĩo ma katatũ ma kũthi.'),
('kam', 'NUM', 2, 25, 'Ngalĩ ya ĩũlũ kũkethĩwe kĩvevelo kya mwako wa maeema wa Ndani kwĩanana na nguthu syoo: na mũnene wa ana ma Ndani akeethĩwa Aieseli mwana wa Amisatai.'),
('kam', 'NUM', 2, 26, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo thanthatũ na ilĩ na maana mũonza.'),
('kam', 'NUM', 2, 27, 'Na ala meambaa maeema moo vakuvĩ nake makeethĩwa ma mbaĩ ya Aseli: na mũnene wa ana ma Aseli akeethĩwa Vakieli mwana wa Okalani.'),
('kam', 'NUM', 2, 28, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo ĩna na ĩmwe na maana atano.'),
('kam', 'NUM', 2, 29, 'Na mbaĩ ya Navitali: na mũnene wa ana ma Navitali akeethĩwa Aila mwana wa Enani.'),
('kam', 'NUM', 2, 30, 'Na nguthu yake, na ala matalilwe mayo, maĩ ngili mĩongo itano na itatũ na maana ana.'),
('kam', 'NUM', 2, 31, 'Onthe ala matalilwe ma mwako wa maeema wa Ndani maĩ ngili ĩana na mĩongo ĩtano na mũonza na maana thanthatũ. Asu nĩo ma ĩtina ma kũthi maatĩĩe ivevelo syoo.'),
('kam', 'NUM', 2, 32, 'Asu nĩmo ala matalilwe ma ana ma Isilaeli kũatĩĩa nyũmba sya aaĩthe moo; onthe ala matalilwe ma myako ya maeema kwĩanana na nguthu syoo maĩ ngili maana thanthatũ na itatũ na maana atano na mĩongo ĩtano.'),
('kam', 'NUM', 2, 33, 'Ĩndĩ Alivai matyaatalanĩlw’a katĩ wa ana ma Isilaeli; o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 2, 34, 'Now’o ana ma Isilaeli meekie; kwĩanana na onthe ala Yeova wamwĩaĩe Mose, now’o mambaa maeema moo vakuvĩ na ivevelo syoo, na now’o maendaa, kĩla mũndũ kũatĩĩa mĩvĩa yoo, kwĩanana na nyũmba sya aaĩthe moo.'),
('kam', 'NUM', 3, 1, 'Na ĩndĩ ii nĩsyo nzyawa sya Aluni na Mose mũthenya ũla Yeova waneenee na Mose kĩĩmanĩ kya Sinai.'),
('kam', 'NUM', 3, 2, 'Na aa nĩmo masyĩtwa ma ana ma Aluni: Natavu ĩkithathi, na Aviu, na Eleasali, na Ithamali.'),
('kam', 'NUM', 3, 3, 'Nĩmo masyĩtwa ma ana ma Aluni, athembi ala metĩkĩiwe mauta, ala wamavathie methĩwe atheu mathũkũmae wĩanĩ wa ũthembi.'),
('kam', 'NUM', 3, 4, 'Na Natavu na Aviu makw’ĩa vu mbee wa Yeova, yĩla maumĩsye Yeova mwaki ũte wa vo, weũnĩ wa Sinai, nao matyaĩ na syana; na Eleasali na Ithamali mathũkũmaa wĩanĩ wa ũthembi Aluni ĩthe woo e vo.'),
('kam', 'NUM', 3, 5, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 3, 6, 'Thengeesya mbaĩ ya Livai, na maie mbee wa mũthembi Aluni mamũthũkũmae.'),
('kam', 'NUM', 3, 7, 'Nao makasũvĩae wĩaĩo wake, na wĩaĩo wa ũmbano w’onthe vu mbee wa ĩeema ya kũmbanĩa, mathũkũmae wĩanĩ wa wĩkalo.'),
('kam', 'NUM', 3, 8, 'Nao makasũvĩae mĩio yonthe ya ĩeema ya kũmbanĩa, na ũla wĩaĩo wa ana ma Isilaeli, mathũkũmae wĩanĩ wa wĩkalo.'),
('kam', 'NUM', 3, 9, 'Namo Alivai ũkanenge Aluni na ana make: na nĩmanenganĩtwe kwake vyũ kwondũ wa ana ma Isilaeli.'),
('kam', 'NUM', 3, 10, 'Naku ũkamaie Aluni na ana make, na makasũvĩae ũthembi woo: na mũeni ũla wĩthengeea mũvaka oawe.'),
('kam', 'NUM', 3, 11, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 3, 12, 'Nakwa, sisya, nĩnĩmaumĩtye Alivai nthĩnĩ wa ana ma Isilaeli vandũ va makithathi onthe ala mambaa kuma ĩvunĩ ya nyinyia ma ana ma Isilaeli; na Alivai makeethĩwa makwa:'),
('kam', 'NUM', 3, 13, 'nũndũ makithathi onthe nĩ makwa; mũthenya ũla nooaie makithathi onthe nthĩ ya Misili nĩnavathie makithathi onthe nthĩnĩ wa Isilaeli methĩwe atheu kwakwa, mũndũ o na nyamũ; makeethĩwa makwa; ninyie Yeova.'),
('kam', 'NUM', 3, 14, 'Na Yeova aneena na Mose weũnĩ wa Sinai, akĩmwĩa,'),
('kam', 'NUM', 3, 15, 'Tala ana ma Livai kũatĩĩa nyũmba sya aaĩthe moo, kũatĩĩa mĩvĩa yoo: kĩla mũndũ mũũme ũvikĩtye mwei ũmwe na mbee ũkamatale.'),
('kam', 'NUM', 3, 16, 'Na Mose amatala kwĩanana na ndeto ya Yeova, o ũndũ weaĩwe.'),
('kam', 'NUM', 3, 17, 'Na aa nĩo ana ma Livai na masyĩtwa moo: Ngelisoni, na Koathi, na Melali.'),
('kam', 'NUM', 3, 18, 'Na masyĩtwa ma ana ma Ngelisoni kũatĩĩa mĩvĩa yoo nĩ aa: Livini na Simei.'),
('kam', 'NUM', 3, 19, 'Na ana ma Koathi kũatĩĩa mĩvĩa yoo: Amilamu, na Isali, na Eviloni, na Usieli.'),
('kam', 'NUM', 3, 20, 'Na ana ma Melali kũatĩĩa mĩvĩa yoo: Mali na Musi. Ĩsu nĩyo mĩvĩa ya Alivai kũatĩĩa nyũmba sya aĩĩthe moo.'),
('kam', 'NUM', 3, 21, 'Kwa Ngelisoni kwaumie mũvĩa wa Alivini, na mũvia wa Asimei: ĩsu nĩ mĩvĩa ya Ngelisoni.'),
('kam', 'NUM', 3, 22, 'Ala matalilwe moo, kwĩanana na ũtalo wa aũme onthe, o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, o asu ala matalilwe moo maĩ ngili mũonza na maana atano.'),
('kam', 'NUM', 3, 23, 'Mĩvĩa ya Angelisoni makambae maeema moo mbĩlĩlo wa wĩkalo kwelekela ngalĩ ya ũthũĩlonĩ wa syũa.'),
('kam', 'NUM', 3, 24, 'Na mũnene wa nyũmba ya aaĩthe ma Angelisoni akeethĩwa Eliasavu mwana wa Laeli.'),
('kam', 'NUM', 3, 25, 'Na wĩaĩo wa ana ma Angelisoni ĩeemanĩ ya kũmbanĩa ũkeethĩwa wa kũsũvĩaa wĩkalo, na Ĩeema, na kĩla kya ũyĩvw’ĩka, na tama wa mũomonĩ wa ĩeema ya kũmbanĩa,'),
('kam', 'NUM', 3, 26, 'na ila ngũa sya kũniinw’a sya nza, na tama wa mũvĩanĩ wa nza, ĩla yĩ vakuvĩ na wĩkalo, na vakuvĩ na kĩthembeo kũkĩthyũlũlũka ngalĩ syonthe, na makanda mayo kwondũ wa ũthũkũmi w’onthe wayo.'),
('kam', 'NUM', 3, 27, 'Na kwa Koathi kwaumie mũvĩa wa Aamilamu, na mũvĩa wa Aisali, na mũvĩa wa Aeviloni, na mũvĩa wa Ausieli: ĩsu nĩyo mĩvĩa ya Akoathi.'),
('kam', 'NUM', 3, 28, 'Kwĩanana na ũtalo wa aũme onthe, o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, maĩ ngili nyanya na maana thanthatũ, makĩsũvĩaa wĩaĩo wa vala vandũ vatheu.'),
('kam', 'NUM', 3, 29, 'Mĩvĩa ya ana ma Koathi makambae maeema moo ngalĩ ya ĩtheo ya wĩkalo.'),
('kam', 'NUM', 3, 30, 'Na mũnene wa nyũmba ya aaĩthe ma mĩvĩa ya Akoathi akeethĩwa Elisavani mwana wa Usieli.'),
('kam', 'NUM', 3, 31, 'Na wĩaĩo woo ũkeethĩwa wa kũsũvĩaa yĩla ĩsandũkũ, na mesa, na kĩla kĩndũ kĩkĩawa mataa, na ithembeo, na mĩio ya vala vandũ vatheu ĩla mathũkũmaa nayo, na ũla tama, na ũthũkũmi wa vo w’onthe.'),
('kam', 'NUM', 3, 32, 'Na Eleasali mwana wa mũthembi Aluni akeethĩwa mũnene wa anene ma Alivai, akeethĩwa mũsyaĩĩsya wa ala masũvĩaa wĩaĩo wa vala vandũ vatheu.'),
('kam', 'NUM', 3, 33, 'Kwa Melali kwaumie mũvĩa wa Amali, na mũvĩa wa Amusi: ĩsu nĩyo mĩvĩa ya Melali.'),
('kam', 'NUM', 3, 34, 'Na ala matalilwe moo, kwĩanana na ũtalo wa aũme onthe, o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, maĩ ngili thanthatũ na maana elĩ.'),
('kam', 'NUM', 3, 35, 'Na mũnene wa nyũmba ya aaĩthe ma mĩvĩa ya Melali aĩ Nzulieli mwana wa Aviaili: asu makambae maeema moo ngalĩ ya ĩũlũ ya wĩkalo.'),
('kam', 'NUM', 3, 36, 'Na wĩaĩo ũla ana ma Melali meaĩĩtwe ũkethĩwe wa kũsũvĩaa mbwaũ sya wĩkalo, na mĩamba yaw’o, na ituĩ syaw’o, na iĩndĩ syaw’o, na mĩio yonthe yaw’o, na ũthũkũmi wa vo w’onthe,'),
('kam', 'NUM', 3, 37, 'na ituĩ sya nza ila ithyũlũlũkĩte ngalĩ syonthe, na iĩndĩ syasyo, na syambo syasyo, na makanda masyo.'),
('kam', 'NUM', 3, 38, 'Na ala meambaa maeema moo ngalĩ ya mbee ya wĩkalo ngalĩ ya wumĩlonĩ wa syũa, mbee wa ĩeema ya kũmbanĩa kwelekela vala syũa yumĩlaa, makethĩwe Mose, na Aluni na ana make, makĩsũvĩaa wĩaĩo wa vala vandũ vatheu, o wĩaĩo wa ana ma Isilaeli; na mũeni ũla wĩthengeea mũvaka oawe.'),
('kam', 'NUM', 3, 39, 'Onthe ala matalilwe ma Alivai, ala Mose na Aluni matalile nũndũ wa mwĩao wa Yeova, kũatĩĩa mĩvĩa yoo, aũme onthe o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, maĩ ngili mĩongo ĩlĩ na ilĩ.'),
('kam', 'NUM', 3, 40, 'Na Yeova amwĩa Mose, Tala makithathi onthe aũme ma ana ma Isilaeli o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, noitala masyĩtwa moo.'),
('kam', 'NUM', 3, 41, 'Na ũkambosee Alivai (ninyie Yeova) vandũ va makithathi onthe ma ana ma Isilaeli; na indo sya Alivai vandũ va makithathi ma indo ma ana ma Isilaeli.'),
('kam', 'NUM', 3, 42, 'Na Mose atala makithathi onthe ma ana ma Isilaeli, o tondũ Yeova wamwĩaĩe.'),
('kam', 'NUM', 3, 43, 'Na makithathi onthe aũme kwĩanana na ũtalo wa masyĩtwa, o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee, ma ala matalilwe moo, maĩ ngili mĩongo ĩlĩ na ilĩ na maana elĩ na mĩongo mũonza na atatũ.'),
('kam', 'NUM', 3, 44, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 3, 45, 'Osa Alivai vandũ va makithathi onthe ma ana ma Isilaeli, na indo sya Alivai vandũ va indo syoo; na Alivai makeethĩwa makwa: ninyie Yeova.'),
('kam', 'NUM', 3, 46, 'Na ũndũ wa wovosyo wa ala maana elĩ na mĩongo mũonza na atatũ ma makithathi ma ana ma Isilaeli, ala mavĩtũkĩte ũtalo wa Alivai,'),
('kam', 'NUM', 3, 47, 'ũkose sekeli itano kwa kĩla mũndũ; kwĩanana na sekeli ya vala vandũ vatheu ũkasyosa (sekeli nĩ ngela mĩongo ĩlĩ):'),
('kam', 'NUM', 3, 48, 'na ũkanenge Aluni na ana make mbesa isu, ila syovoisye ala mavĩtũkĩte Alivai.'),
('kam', 'NUM', 3, 49, 'Na Mose amaumya asu ala mathonokie ala movoiwe nĩ Alivai mbesa sya wovosyo;'),
('kam', 'NUM', 3, 50, 'na oosa mbesa isu kwa makithathi ma ana ma Isilaeli, sekeli ngili imwe na maana atatũ na mĩongo thanthatũ na itano, kwĩanana na sekeli ya vala vandũ vatheu:'),
('kam', 'NUM', 3, 51, 'na Mose anenga Aluni na ana make mbesa isu sya wovosyo, kwĩanana na ndeto ya Yeova, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 4, 1, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'NUM', 4, 2, 'Vetai ũtalo wa ana ma Koathi vala ve ana ma Livai, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo,'),
('kam', 'NUM', 4, 3, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano, onthe ala malikaa ũthũkũminĩ, matethye wĩa ĩeemanĩ ya kũmbanĩa.'),
('kam', 'NUM', 4, 4, 'Ũũ nĩw’o ũthũkũmi wa ana ma Koathi ĩeemanĩ ya kũmbanĩa, syĩndũnĩ ila ntheu mbee:'),
('kam', 'NUM', 4, 5, 'yĩla maeema meambũawa mathi, Aluni na ana make makalike na kumya ula tũtũ wa kũtilan’ya, na kũvw’ĩka ĩsandũkũ ya ũkũsĩ naw’o,'),
('kam', 'NUM', 4, 6, 'na makavw’ĩke ĩũlũ wayo ũa wa vomboo, na makalan’ye ĩũlũ waw’o ngũa ya vuluu mũthei, na makĩkĩa mĩtĩ yayo ya ũyĩkua.'),
('kam', 'NUM', 4, 7, 'Na mesanĩ ya imũtũ ila siĩawa Yeova makalan’ye ngũa ya vuluu, na kwia masaani ĩũlũ wayo, na syĩko, na mbakũli na ikombe sya kwĩtĩkĩasya; na imutu ila itatw’ĩkanaa ikeethĩwa ĩũlũ wayo:'),
('kam', 'NUM', 4, 8, 'na makalan’ye ĩũlũ wasyo ngũa ndune mũno, na kũvw’ĩka ngũa ĩsu na ũa wa vomboo, na makekĩe mĩtĩ yayo.'),
('kam', 'NUM', 4, 9, 'Na makose ngũa ya vuluu na kũvw’ĩka kĩla kĩndũ kĩkĩawa mataa ala mamulĩkaa, na mataa makyo, na mĩkasĩ yakyo, na masaani makyo ma makaa, na mĩio yonthe ya mauta makyo, ĩla matethasya wĩa wakyo nayo:'),
('kam', 'NUM', 4, 10, 'na makakĩkĩe vamwe na mĩio yonthe yakyo nthĩnĩ wa ũa wa vomboo, na makia ĩũlũ wa mĩtĩ ya ũkua nayo.'),
('kam', 'NUM', 4, 11, 'Na ĩũlũ wa kĩthembeo kya thaavu makalan’ye ngũa ya vuluu, na maimĩvw’ĩka ũa wa vomboo, na kwĩkĩa ĩla mĩtĩ yakyo:'),
('kam', 'NUM', 4, 12, 'na makose mĩio yonthe ya ũthũkũmi ĩla mathũkũmaa nayo nthĩnĩ wa vala vandũ vatheu, na kũmĩkĩa ngũanĩ ya vuluu, na kũmĩvw’ĩka ũa wa vomboo, na kũmia ĩũlũ wa mĩtĩ ya kũkua nayo.'),
('kam', 'NUM', 4, 13, 'Na makooke mũu kĩthembeonĩ, na kwalan’ya ngũa ĩtilyĩ ta ndune ĩũlũ wakyo:'),
('kam', 'NUM', 4, 14, 'nao makaie ĩũlũ wayo mĩio yonthe yayo, ĩla mathũkũmaa nayo, tũvũngũlyũ twa ũkua makaa, na itonyi sya nyama, na mĩko, na masaani manene, mĩio yonthe ya kĩla kĩthembeo; na makalan’ye ĩũlũ wayo ũa wa vomboo, na kwĩkĩa mĩtĩ yakyo.'),
('kam', 'NUM', 4, 15, 'Na yĩla Aluni na ana make memina kũvw’ĩka vala vandũ vatheu, na mĩio yonthe ya vala vandũ vatheu, o yĩla meambũa maeema mathi; ĩtina wa ũu, ana ma Koathi makooka kũkua: ĩndĩ matikakiite vala vandũ vatheu, matikakw’e. Syĩndũ isu nĩ mĩio ya ana ma Koathi ĩeemanĩ ya kũmbanĩa.'),
('kam', 'NUM', 4, 16, 'Na wĩaĩo wa Eleasali mwana wa mũthembi Aluni ũkethĩwe wa kũsũvĩaa mauta ma kwakan’ya taa, na ũvani ũla ũnyungaa nesa, na nthembo ya mũtu ĩtatw’ĩkanaa, na mauta ma kwĩtĩkĩsya, o wĩaĩo wa wĩkalo w’onthe, na wa mĩio yonthe ĩla yĩ nthĩnĩ waw’o, vala vandũ vatheu, na mĩio ya vo.'),
('kam', 'NUM', 4, 17, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'NUM', 4, 18, 'Mũikavete mbaĩ ya mĩvĩa ya Akoathi kuma katĩ wa Alivai:'),
('kam', 'NUM', 4, 19, 'ĩndĩ mekaei ũndũ ũũ, nĩ kana mekalae thayũ, maikakw’e, yĩla meũthengeea syĩndũ ntheu mbee; Aluni na ana make makalike nthĩnĩ na kũmwiĩa kĩla mũndũ ũthũkũmi wake na mũio wake;'),
('kam', 'NUM', 4, 20, 'ĩndĩ asu matikalike kũsisya vala vandũ vatheu o na kavinda kanini, matikakw’e.'),
('kam', 'NUM', 4, 21, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 4, 22, 'Tala ana ma Ngelisoni, kũatĩĩa nyũmba sya aaĩthe moo, kũatĩĩa mĩvĩa yoo;'),
('kam', 'NUM', 4, 23, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee kũvika myaka mĩongo ĩtano ũkamatale; onthe ala malikaa kũthũkũma, matethye wĩa ĩeemanĩ ya kũmbanĩa.'),
('kam', 'NUM', 4, 24, 'Ũũ nĩw’o ũthũkũmi wa mĩvĩa ya Angelisoni wa kũthũkũma na kũkua mĩio:'),
('kam', 'NUM', 4, 25, 'makakuae masuka ma wĩkalo, na ĩeema ya kũmbanĩa, na kĩndũ kya kũyĩvw’ĩka, na kĩngĩ kya kũvw’ĩka kya ũa wa vomboo kĩ ĩũlũ wayo, na tama wa mũomonĩ wa ĩeema ya kũmbanĩa;'),
('kam', 'NUM', 4, 26, 'na ngũa sya kũniinw’a sya nza, na tama wa mũomonĩ wa mbingĩlo ya nza, ũla wĩ vakuvĩ na wĩkalo na vakuvĩ na kĩthembeo kũkĩthyũlũlũka ngalĩ syonthe, na makanda masyo, na mĩio yonthe ya ũthũkũmi wasyo, na w’onthe o na wĩva ũla ũkekwa nasyo: makathũkũmae wĩanĩ ũsu.'),
('kam', 'NUM', 4, 27, 'Ũthũkũmi w’onthe wa ana ma Angelisoni, ũndũ wa mĩio yoo yonthe, na ũndũ wa ũthũkũmi woo w’onthe, ũkeethĩwa ũkĩaĩwa nĩ Aluni na ana make; nenyu mũkamaiĩe mĩio yoo yonthe mamĩsũvĩae.'),
('kam', 'NUM', 4, 28, 'Ũsu nĩw’o ũthũkũmi wa mĩvĩa ya ana ma Ngelisoni ĩeemanĩ ya kũmbanĩa: kwĩaĩwa kwoo kũkethĩwe kw’okonĩ kwa Ithamali mwana wa mũthembi Aluni.'),
('kam', 'NUM', 4, 29, 'Ũndũ wa ana ma Melali, ũkamatale kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo;'),
('kam', 'NUM', 4, 30, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano ũkamatale, kĩla ũmwe ũlikaa ũthũkũminĩ ũsu, kũtethya wĩa wa ĩeema ya kũmbanĩa.'),
('kam', 'NUM', 4, 31, 'Kwĩaĩwa kwoo kwondũ wa mĩio yoo, kwĩanana na ũthũkũmi woo w’onthe ĩeemanĩ ya kũmbanĩa nĩkw’o kũũ: mbwaũ sya wĩkalo, na mĩamba yaw’o, na ituĩ syaw’o, na iĩndĩ syaw’o;'),
('kam', 'NUM', 4, 32, 'na ituĩ sya nza sya kũthyũlũlũka ngalĩ syonthe, na iĩndĩ syasyo, na syambo syasyo, na makanda masyo, vamwe na mĩio yasyo yonthe, na vamwe na ũthũkũmi wasyo w’onthe: ũkamũwetee kĩla mũndũ mĩio yake na masyĩtwa mayo ĩla weaĩwe asũvĩae.'),
('kam', 'NUM', 4, 33, 'Ũsu nĩw’o ũthũkũmi wa mĩvĩa ya ana ma Melali, kwĩanana na ũthũkũmi woo w’onthe, ĩeemanĩ ya kũmbanĩa, ũkĩsiaĩĩw’a nĩ Ithamali mwana wa mũthembi Aluni.'),
('kam', 'NUM', 4, 34, 'Na Mose na Aluni na anene ma ũmbano matala ana ma Akoathi kũatĩĩa mĩvĩa yoo, na kũatĩĩa nyũmba sya aaĩthe moo,'),
('kam', 'NUM', 4, 35, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano, kĩla mũndũ ũla walikaa ũthũkũminĩ ũsu, kwondũ wa wĩa ĩeemanĩ ya kũmbanĩa;'),
('kam', 'NUM', 4, 36, 'na ala matalilwe moo kũatĩĩa mĩvĩa yoo maĩ ngili ilĩ na maana mũonza na mĩongo ĩtano.'),
('kam', 'NUM', 4, 37, 'Asu nĩo ala matalilwe ma mĩvĩa ya Akoathi, onthe ala mathũkũmaa ĩeemanĩ ya kũmbanĩa, ala Mose na Aluni matalile o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 4, 38, 'Na ala matalilwe ma ana ma Ngelisoni, kũatĩĩa mĩvĩa yoo, na kũatĩĩa nyũmba sya aaĩthe moo,'),
('kam', 'NUM', 4, 39, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano, kĩla ũmwe ũla walikaa ũthũkũminĩ ũsu wa wĩa ĩeemanĩ ya kũmbanĩa,'),
('kam', 'NUM', 4, 40, 'o asu ala matalilwe moo, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo, maĩ ngili ili na maana thanthatũ na mĩongo ĩtatũ.'),
('kam', 'NUM', 4, 41, 'Asu nĩo ala matalilwe ma mĩvĩa ya ana ma Ngelisoni, onthe ala mathũkũmaa ĩeemanĩ ya kũmbanĩa, ala Mose na Aluni matalile kwĩanana na mwĩao wa Yeova.'),
('kam', 'NUM', 4, 42, 'Na ala matalilwe ma mĩvĩa ya ana ma Melali, kũatĩĩa mĩvĩa yoo, kũatĩĩa nyũmba sya aaĩthe moo,'),
('kam', 'NUM', 4, 43, 'ala mavikĩtye myaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano, kĩla ũmwe ũla walikaa ũthũkũminĩ ũsu wa wĩa ĩeemanĩ ya kũmbanĩa,'),
('kam', 'NUM', 4, 44, 'o asu ala matalilwe ma mĩvĩa yoo, maĩ ngili itatũ na maana elĩ.'),
('kam', 'NUM', 4, 45, 'Asu nĩo ala matalilwe ma mĩvĩa ya ana ma Melali, ala Mose na Aluni matalile o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 4, 46, 'Onthe ala matalilwe ma Alivai, ala Mose na Aluni na anene ma Isilaeli matalile, kũatĩĩa mĩvĩa yoo, na kũatĩĩa nyũmba sya aaĩthe moo,'),
('kam', 'NUM', 4, 47, 'ala mavikĩtye mayaka mĩongo ĩtatũ na mbee o kũvika myaka mĩongo ĩtano, kĩla ũmwe ũla walikaa kũtethya wĩa wa ũthũkũmi ũsu, na wĩa wa kũkua mĩio ĩeemanĩ ya kũmbanĩa,'),
('kam', 'NUM', 4, 48, 'o asu matalilwe moo maĩ ngili nyanya na maana atano na mĩongo nyanya.'),
('kam', 'NUM', 4, 49, 'Matalilwe nĩ Mose kwĩanana na mwĩao wa Yeova, kĩla mũndũ o ũndũ ũthũkũmi wake ũilyĩ, na ũndũ mĩio yake ĩilyĩ: ũu nĩw’o matalilwe nĩwe, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 5, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 5, 2, 'Meaĩe ana ma Isilaeli, mavete mwakonĩ wa maeema kĩla mũndũ ũwaĩte mangũ, na kĩla mũndũ ũwaĩte mũluo, na o ũla ũvukĩtwe nĩ kimba:'),
('kam', 'NUM', 5, 3, 'aũme o na aka mũkamaumaalye, na mũkamaie ũtee wa mwako wa maeema; matikavukye mwako wa maeema woo, ũla nĩkalaa nthĩnĩ waw’o.'),
('kam', 'NUM', 5, 4, 'Na ana ma Isilaeli mekaa ũu, na mamaumaalasya ũtee wa mwako wa maeema; o tondũ Yeova wamũtavisye Mose, nĩw’o ana ma Isilaeli mekaa.'),
('kam', 'NUM', 5, 5, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 5, 6, 'Matavye ana ma Isilaeli atĩĩ, Yĩla mũndũ mũũme kana mũndũ mũka meĩka naĩ o na yĩva yĩkawa nĩ andũ, na kũmũvĩtanĩsya Yeova, na mũndũ ũsu akethĩwa e mũvĩtan’ya;'),
('kam', 'NUM', 5, 7, 'nĩvo ĩndĩ wĩumbũlaa naĩ yake ĩla wĩkĩte: na akaĩva vyũ kwondũ wa ũvĩtan’yo wake, na kwongeleela kĩlungu kya katano na kũmũnenga ũla wamũvĩtanĩsye.'),
('kam', 'NUM', 5, 8, 'Ĩndĩ ethĩwa mũndũ ũsu nde na mũndũ wa mũvĩa wake ũla ũtonya kũĩvĩwa ũvĩtan’yo ũsu, kĩla kĩkũĩvĩwa ĩvĩtyo yake kwa Yeova kĩkeethĩwa kya mũthembi; eka ndũũme ya wĩw’anĩthyo, ĩla wĩw’anĩthw’a kwondũ wayo.'),
('kam', 'NUM', 5, 9, 'Na kĩla nthembo ya kũkĩlw’a ya syĩndũ syonthe ntheu sya ana ma Isilaeli, ĩla memũtwaĩa mũthembi, ĩkeethĩwa yake.'),
('kam', 'NUM', 5, 10, 'Na syĩndũ ivathĩtwe nĩ mũndũ syĩthĩwe ntheu ikeethĩwa sya mũthembi: o kĩla mũndũ o na wĩva ũnengae mũthembi kĩkeethĩwa kyake.'),
('kam', 'NUM', 5, 11, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 5, 12, 'Neena na ana ma Isilaeli, ũmatavye, Ethĩwa mũka wa mũndũ o na wiva nũnũũtambũka na kũmũvĩtanĩsya mũũme,'),
('kam', 'NUM', 5, 13, 'na mũndũ akĩkoma nake na kũlaalaa, na ũndũ ũsu ũivĩthwa mũũme ndakone, na kũvithwa ki, nake nĩwĩvukitye, na vati ngũsĩ yĩsĩ, na ndaaoneka akĩka ũu,'),
('kam', 'NUM', 5, 14, 'na mũũme aikwatwa nĩ nzika ngoonĩ yake, na kwĩw’a nzika ũndũ wa mũka wake, nake nĩwĩvukĩtye: kana ethĩwa akakwatwa nĩ nzika ngoonĩ, na kwĩw’a nzika ũndũ wa mũka, nake ndevukitye:'),
('kam', 'NUM', 5, 15, 'nĩvo ĩndĩ ũla mũndũ wĩtwaa mũka wake vala ve mũthembi, na aitwaa nthembo ũndũ wake, kĩlungu kya ĩkũmi kya eva ya mũtu wa mbaale; ndakekĩe mauta ĩũlũ waw’o, kana kwĩkĩa ũvumba ĩũlũ waw’o; nũndũ nĩ nthembo ya mũtu kwondũ wa nzika, nthembo ya mũtu ya ũlilikan’yo, ya kũlilikan’ya ũthũku.'),
('kam', 'NUM', 5, 16, 'Na mũthembi akamũthengeesye na kũmwĩkalya mbee wa Yeova:'),
('kam', 'NUM', 5, 17, 'na mũthembi akekĩe manzĩ matheu ĩsaaninĩ ya yũmba; na akyosa kĩtoo kĩla kĩ vo nthĩ wĩkalonĩ, na kũkĩkĩa manzĩnĩ.'),
('kam', 'NUM', 5, 18, 'Na mũthembi akamwĩkalye ũla mũndũ mũka mbee wa Yeova, na kwithalĩkya nzw’ĩĩ sya mũtwe wa mũndũ mũka, na kwĩkĩa nthembo ya mũtu ya ũlilikan’yo mokonĩ make, nayo nĩ nthembo ya mũtu kwondũ wa nzika: na mũthembi akethĩwe na manzĩ asu me ũũ kw’okonĩ kwake ala maetae kĩumo.'),
('kam', 'NUM', 5, 19, 'Na mũthembi akamũavĩthye, na kwĩa ũla mũndũ mũka, Ethĩwa mũndũ mũũme ndaakoma naku, na ethĩwa ndwaalika wathavunĩ, wĩ mwĩaonĩ wa mũemeu, manzĩ aa me ũũ ala maetae kĩumo maikakũkwate.'),
('kam', 'NUM', 5, 20, 'Ĩndĩ ethĩwa nũlikĩte wathavunĩ, wĩ mwĩaonĩ wa mũemeu, na ethĩwa nĩwĩvukĩtye, na mũndũ nũkomete naku ũte mũemeu:'),
('kam', 'NUM', 5, 21, 'nĩvo ĩndĩ mũthembi wĩmũavĩthya ũla mũndũ mũka na wĩvĩto wa kwĩvĩta, na mũthembi akee mũndũ mũka ũsu, Yeova akũtw’ĩkĩthye kĩumo na wĩvĩto andũnĩ maku, yĩla Yeova ũkakwonzethya ĩtako yaku, na kwimbĩthya ĩvu yaku;'),
('kam', 'NUM', 5, 22, 'na manzĩ aa ala maetae kĩumo makalika nda yaku, na kwimbĩthya ĩvu yaku, na kwonzethya ĩtako yaku. Na mũndũ mũka ũsu akasye, Ameni, Ameni.'),
('kam', 'NUM', 5, 23, 'Na mũthembi akaandĩke iumo isu ĩvukunĩ, na akaithambĩsya nthĩnĩ wa ala manzĩ me ũũ:'),
('kam', 'NUM', 5, 24, 'na akamũkundye ũla mũndũ mũka manzĩ asu me ũũ ala maetae kĩumo; na manzĩ ala maetae kĩumo makalika nthĩnĩ wake nao makeethĩwa me ũũ.'),
('kam', 'NUM', 5, 25, 'Mũthembi akaumye ĩla nthembo ya mũtu kwondũ wa nzika kw’okonĩ kwa mũndũ mũka, na akavyũlangya nthembo ya mũtu mbee wa Yeova, na kũmĩtwaa kĩthembeoni:'),
('kam', 'NUM', 5, 26, 'na mũthembi akaute ũvĩ wa nthembo ya mũtu, wĩthĩwe ũlilikan’yo wayo, na kũvĩvĩsya kĩthembeonĩ, na ĩtina akamũkundye ũ mũndũ mũka manzĩ asu.'),
('kam', 'NUM', 5, 27, 'Na amina kũmũkundya ala manzĩ, nĩvo ĩndĩ kwĩthĩwa, ethĩwa nĩwĩvukĩtye, na kũmũvĩtanĩsya mũũme, manzĩ ala maetae kĩumo makalika nthĩnĩ wake na makeethĩwa me ũũ, na ĩvu yake yĩkaimba, na ĩtako yake yĩkonza: na ũ mũndũ mũka akeethĩwa e kĩumo andũnĩ make.'),
('kam', 'NUM', 5, 28, 'Na ethĩwa mũndũ mũka ndevukĩtye, ĩndĩ nĩ mũtheu; nĩvo ĩndĩ wĩthĩwa ate na ũndũ, nake akaitava.'),
('kam', 'NUM', 5, 29, 'Ũsu nĩw’o mwĩao wa nzika, yĩla mũndũ mũka, e mwĩaonĩ wa mũũme, wĩlika wathavunĩ na kwĩvukya;'),
('kam', 'NUM', 5, 30, 'kana yĩla nzika syĩmũkwata mũndũ mũũme ngoonĩ, na ailikwa nĩ nzika ũndũ wa mũka; nĩvo ĩndĩ wĩmwĩkalya mũka mbee wa Yeova, na mũthembi akamwĩka maũndũ onthe ma mwĩao ũsu.'),
('kam', 'NUM', 5, 31, 'Na mũndũ mũũme ũsu akeethĩwa ate na ũthũku, na mũndũ mũka ũsu akakua ũthũku wake.'),
('kam', 'NUM', 6, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 6, 2, 'Neena na ana ma Isilaeli, ũmatavye, Yĩla mũndũ mũũme kana mũndũ mũka ũkevĩta wĩvĩto, wĩvĩto wa Mũnasali, nĩ kana evathe ethĩwe wa Yeova,'),
('kam', 'NUM', 6, 3, 'akevathane na mbinyu na kĩla kĩtoonasya; ndakanyw’e siki wa mbinyu, kana siki wa kĩla kĩtoonasya, o na ndakanyw’e ngoyoo o na yĩva ya nzavivũ, kana kũya nzavivũ mbĩu kana mbovu.'),
('kam', 'NUM', 6, 4, 'Mĩthenya yonthe ya kwĩvatha kwake ndakaye kĩndũ kĩseũvĩtw’e kya mũsavivũ, kuma mbĩndĩ o na kũvika makonde.'),
('kam', 'NUM', 6, 5, 'Mĩthenya yonthe ya wĩvĩto wake wa kwĩvathan’ya, wenzi ndũkaavike mũtwe wake: kũvika yĩla mĩthenya yĩĩanĩa, ĩla wevathanisye ethĩwe wa Yeova, akeethĩwa e mũtheu; akaeke nzw’ĩĩ sya mũtwe wake iasave.'),
('kam', 'NUM', 6, 6, 'Mĩthenya yonthe ĩla wevathanisye ethĩwe wa Yeova ndakathengeee kimba.'),
('kam', 'NUM', 6, 7, 'Ndakevukye kwondũ wa ĩthe, kana kwondũ wa nyinyia, kana kwondũ wa mwana‐a‐inyia, kana kwondũ wa mwĩĩtũa‐inyia, yĩla makw’a; nũndũ kwĩvatha kwake ethĩwe wa Ngai kwĩ mũtwenĩ wake.'),
('kam', 'NUM', 6, 8, 'Mĩthenya yonthe ya kwĩvathan’ya kwake nĩ mũtheu kwa Yeova.'),
('kam', 'NUM', 6, 9, 'Na ethĩwa mũndũ o na wĩva akatũmũkĩa vakuvĩ nake, na akavukya mũtwe wa kwĩvatha kwake; nĩvo ĩndĩ wĩenza mũtwe wake mũthenya wa kwĩthesya kwake, mũthenya wa mũonza akawenze.'),
('kam', 'NUM', 6, 10, 'Na mũthenya wa nyanya akamũtwaĩe mũthembi ndumbũ ilĩ, kana maswii elĩ ma ĩvũĩ mũomonĩ wa ĩeema ya kũmbanĩa:'),
('kam', 'NUM', 6, 11, 'na mũthembi akathembe ĩmwe yĩthĩwe nthembo kwondũ wa naĩ, na ĩla ĩngĩ yĩthĩwe nthembo ya kũvĩvw’a, amwĩw’anĩthye, nũndũ nĩwavĩtisye nũndũ wa kimba, na akavathan’ye mũtwe wake mũthenya o ũsu.'),
('kam', 'NUM', 6, 12, 'Nake akamũvathĩa Yeova mĩthenya ya kwĩvatha kwake, na akaete katũlũme ka mwaka ũmwe kethĩwe nthembo kwondũ wa ĩvĩtyo: ĩndĩ mĩthenya ĩla mĩvĩtu ndĩkatalwa, nĩkwĩthĩwa kwĩvatha kwake nĩ kũvukye.'),
('kam', 'NUM', 6, 13, 'Na ũũ nĩw’o mwĩao wa Mũnasali, yĩla mĩthenya ya kwĩvatha kwake yeanĩa: akaetwe mũomonĩ wa ĩeema ya kũmbanĩa:'),
('kam', 'NUM', 6, 14, 'na akamũthembee Yeova nthembo yake, katũlũme kamwe kate kĩema ka mwaka ũmwe kethĩwe nthembo ya kũvĩvw’a, na kamwatĩ kamwe ka mwaka ũmwe kate kĩema kethĩwe nthembo kwondũ wa naĩ, na ndũũme ĩmwe ĩte kĩema yĩthĩwe nthembo ya mũuo,'),
('kam', 'NUM', 6, 15, 'na kĩkavũ kya kĩmũtũ kĩte ĩlawa, na tũmũtũ twa mũtu mũvinyu ũvulanĩtw’e na mauta, na tũmĩkate tũvũthũ tũte ĩlawa tũvakĩtwe mauta, na nthembo ya mũtu ya kũthembanĩsya nasyo, na nthembo sya kũnyuwa sya kũthembanĩsya nasyo.'),
('kam', 'NUM', 6, 16, 'Na mũthembi akaitwaĩe Yeova, na akathembe nthembo yake kwondũ wa naĩ, na nthembo yake ya kũvĩvw’a:'),
('kam', 'NUM', 6, 17, 'na akathembee Yeova ĩla ndũũme yĩthĩwe yĩ nthembo ya nthembo sya mũuo, vamwe na kĩkavũ kya kĩmũtũ kĩte ĩlawa: na ĩngĩ mũthembi akathembe nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 6, 18, 'Na Mũnasali akenzee mũtwe wa kwĩvathan’ya kwake mũomonĩ wa ĩeema ya kũmbanĩa, na akose nzw’ĩĩ sya mũtwe wa kwĩvathan’ya kwake, na kwĩkĩa mwakinĩ ũla wĩ ungu wa nthembo ya nthembo sya mũuo.'),
('kam', 'NUM', 6, 19, 'Na mũthembi akose kw’oko kũue kwa ndũũme, na kamũtũ kamwe kate ĩlawa kĩkavũnĩ, na kamũkate kamwe kavũthũ kate ĩlawa, na kwĩkĩa mokonĩ ma Mũnasali, amina kwenza mũtwe wa kwĩvathan’ya kwake;'),
('kam', 'NUM', 6, 20, 'na mũthembi akaivyũlangye syĩthĩwe nthembo ya kũvyũlw’a mbee wa Yeova; kyu nĩ kĩndũ kĩtheu kwondũ wa mũthembi, vamwe na kĩng’eng’eto kya kũvyũlw’a na kũũ kwa kũkĩlw’a: na ĩtina wa ũu ũla Mũnasali nũtonya kũnyw’a mbinyu.'),
('kam', 'NUM', 6, 21, 'Ũsu nĩw’o mwĩao wa Mũnasali ũla ũnũkwĩvĩta, na wa nthembo yake kwondũ wa Yeova ũndũ wa kwĩvathan’ya kwake, o vamwe na syĩndũ ila ũtonya kwosa: kwĩanana na wĩvĩto wake ũndũ wĩvĩtĩte, mũvaka eke ũu aiatĩĩa mwĩao wa kwĩvathan’ya kwake.'),
('kam', 'NUM', 6, 22, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 6, 23, 'Neena na Aluni na ana make, ũkĩmea, Ũũ nĩw’o mũkaathima ana ma Isilaeli: mũkamee atĩĩ,'),
('kam', 'NUM', 6, 24, 'Yeova nakũathime, na ukũsũvĩa:'),
('kam', 'NUM', 6, 25, 'Yeova nakũtisĩasye ũthyũ wake, na ũkwĩka nesa:'),
('kam', 'NUM', 6, 26, 'Yeova akũkĩlĩlye ũthyũ wake, na ũkũnenga mũuo.'),
('kam', 'NUM', 6, 27, 'Ũu nĩw’o makaia syĩtwa yakwa ananĩ ma Isilaeli; nakwa ngamaathima.'),
('kam', 'NUM', 7, 1, 'Na kweethĩwa mũthenya ũla Mose waminie kũngamya wĩkalo, na kũwĩtĩkĩsya mauta, na kũvathan’ya wĩthĩwe wĩ mũtheu, na mĩio yonthe yaw’o, na kĩthembeo na mĩio yonthe yakyo, na kũsyĩtĩkĩsya mauta na kwivathan’ya syĩthĩwe syĩ ntheu;'),
('kam', 'NUM', 7, 2, 'nĩvo ĩndĩ anene ma Isilaeli, atongoi ma nyũmba sya aaĩthe moo, maetie moelo. Aa maĩ anene ma ila mbaĩ, aa nĩo maĩ anene ma ala matalilwe:'),
('kam', 'NUM', 7, 3, 'na mamũetee Yeova moelo moo, makasya thanthatũ ala maĩ mavw’ĩke ĩũlũ, na ng’ombe ĩkũmi na ilĩ; kĩla ĩkasya yaumiw’e nĩ anene elĩ, na ng’ombe ĩmwe yaumaw’a nĩ kĩla mũnene: na maiete mbee wa wĩkalo.'),
('kam', 'NUM', 7, 4, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 7, 5, 'Osa syĩndũ isu maete syĩthĩwe sya kũthũkũmaa nasyo ũthũkũminĩ wa ĩeema ya kũmbanĩa; na ũkamanenge Alivai syĩndũ isu, kĩla mũndũ kwĩanana na ũthũkũmi wake.'),
('kam', 'NUM', 7, 6, 'Na Mose oosa makasya asu na ng’ombe isu na amanenga Alivai.'),
('kam', 'NUM', 7, 7, 'Anenga ana ma Ngelisoni makasya elĩ na ng’ombe inya, kwĩanana na ũthũkũmi woo;'),
('kam', 'NUM', 7, 8, 'na anenga ana ma Melali makasya ana na ng’ombe nyanya, kwĩanana na ũthũkũmi woo, makĩsyaĩĩw’a nĩ Ithamali mwana wa mũthembi Aluni.'),
('kam', 'NUM', 7, 9, 'Ĩndĩ ana ma Koathi ndaamanenga kĩndũ, nĩkwĩthĩwa ũthũkũmi wa vala vandũ vatheu waĩ woo; nĩmakuaa na ituo syoo.'),
('kam', 'NUM', 7, 10, 'Na ala anene maumya moelo kwondũ wa kũvatha kĩthembeo kĩthĩwe kĩ kĩtheu mũthenya ũla kyetĩkĩw’e mauta, asu anene maete moelo moo kĩthembeonĩ.'),
('kam', 'NUM', 7, 11, 'Na Yeova amwĩa Mose, Makaete moelo moo, kĩla mũnene mũthenya wake, kwondũ wa kũvatha kĩthembeo kĩthĩwe kĩ kĩtheu.'),
('kam', 'NUM', 7, 12, 'Na ũla waetie ũelo wake mũthenya wa mbee nĩ Nasoni mwana wa Aminatavu, wa mbaĩ ya Yuta:'),
('kam', 'NUM', 7, 13, 'na ũelo wake waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 14, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 15, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 16, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 17, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Nasoni mwana wa Aminatavu.'),
('kam', 'NUM', 7, 18, 'Mũthenya wa kelĩ Nethaneli mwana wa Nzuali, mũnene wa Isakali, aete ũelo wake:'),
('kam', 'NUM', 7, 19, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 20, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 21, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 22, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 23, 'na nthembo ya nthembo sya mũuo ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Nethaneli mwana wa Nzuali.'),
('kam', 'NUM', 7, 24, 'Mũthenya wa katatũ Eliavu mwana wa Eeloni, mũnene wa ana ma Nzevulunĩ, aete ũelo wake:'),
('kam', 'NUM', 7, 25, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 26, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 27, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 28, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 29, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Eliavu mwana wa Eeloni.'),
('kam', 'NUM', 7, 30, 'Mũthenya wa kana Elisuli mwana wa Seteuli, mũnene wa ana ma Leuveni, aete ũelo wake:'),
('kam', 'NUM', 7, 31, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 32, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 33, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 34, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 35, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Elisuli mwana wa Seteuli.'),
('kam', 'NUM', 7, 36, 'Mũthenya wa katano Selumieli mwana wa Nzuli‐satai, mũnene wa ana ma Simeoni, aete ũelo wake:'),
('kam', 'NUM', 7, 37, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syeli syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 38, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 39, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 40, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 41, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Selumieli mwana wa Nzulisatai.'),
('kam', 'NUM', 7, 42, 'Mũthenya wa thanthatũ Eliasavu mwana wa Ndeueli, mũnene wa ana ma Ngati, aete ũelo wake:'),
('kam', 'NUM', 7, 43, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 44, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 45, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 46, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 47, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Eliasavu mwana wa Ndeueli.'),
('kam', 'NUM', 7, 48, 'Mũthenya wa mũonza Elisama mwana wa Amiuti, mũnene wa ana ma Evalaimu, aete ũelo wake:'),
('kam', 'NUM', 7, 49, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 50, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 51, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 52, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 53, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe; isu nĩsyo syaĩ ũelo wa Elisama mwana wa Amiuti.'),
('kam', 'NUM', 7, 54, 'Mũthenya wa nyanya Ngamalieli mwana wa Vetasuli, mũnene wa ana ma Manase, aete ũelo wake:'),
('kam', 'NUM', 7, 55, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 56, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 57, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 58, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 59, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Ngamalieli mwana wa Vetasuli.'),
('kam', 'NUM', 7, 60, 'Mũthenya wa kenda Avitani mwana wa Kiteoni, mũnene wa ana ma Mbenyamini, aete ũelo wake:'),
('kam', 'NUM', 7, 61, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 62, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 63, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 64, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 65, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Avitani mwana wa Kiteoni.'),
('kam', 'NUM', 7, 66, 'Mũthenya wa ĩkũmi Aieseli mwana wa Amisatai, mũnene wa ana ma Ndani, aete ũelo wake:'),
('kam', 'NUM', 7, 67, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 68, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 69, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 70, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 71, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe; isu nĩsyo syaĩ ũelo wa Aieseli mwana wa Amisatai.'),
('kam', 'NUM', 7, 72, 'Mũthenya wa ĩkũmi na ũmwe Vakieli mwana wa Okalani, mũnene wa ana ma Aseli, aete ũelo wake:'),
('kam', 'NUM', 7, 73, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 74, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 75, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 76, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 77, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Vakieli mwana wa Okalani.'),
('kam', 'NUM', 7, 78, 'Mũthenya wa ĩkũmi na ĩlĩ Aila mwana wa Enani, mũnene wa ana ma Navitali, aete ũelo wake:'),
('kam', 'NUM', 7, 79, 'ũelo wake ũla waetie waĩ ĩsaani yĩmwe ya vetha, ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na mbakũli ĩmwe ya vetha ya sekeli mĩongo mũonza, kwĩanana na sekeli ya vala vandũ vatheu; isu syelĩ syusĩe mũtu mũvinyu ũvulanĩtw’e na mauta wĩthĩwe nthembo ya mũtu;'),
('kam', 'NUM', 7, 80, 'na kĩko kĩmwe kya thaavu kya sekeli ĩkũmi, kyusĩe ũvani;'),
('kam', 'NUM', 7, 81, 'na kasalũ kamwe, na ndũũme ĩmwe, na katũlũme kamwe ka mwaka ũmwe, syĩthĩwe nthembo ya kũvĩvw’a;'),
('kam', 'NUM', 7, 82, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 83, 'na nthembo ya nthembo sya mũuo, ng’ombe ilĩ, na ndũũme itano, na nthenge itano, na tũtũlũme tũtano twa mwaka ũmwe: isu nĩsyo syaĩ ũelo wa Aila mwana wa Enani.'),
('kam', 'NUM', 7, 84, 'Moelo asu nĩmaumiw’e nũndũ wa kũvatha kĩthembeo kĩthĩwe kĩ kĩtheu, mũthenya ũla kyetĩkĩw’e mauta nĩ anene ma Isilaeli: masaani ĩkũmi na elĩ ma vetha, na mbakũli ikũmi na ĩlĩ sya vetha, na syĩko ĩkũmi na ĩlĩ sya thaavu;'),
('kam', 'NUM', 7, 85, 'kĩla ĩsaani ya vetha ũito wayo waĩ sekeli ĩana yĩmwe na mĩongo ĩtatũ, na kĩla mbakũli, sekeli mĩongo mũonza; vetha w’onthe wa mĩio waĩ sekeli ngili ilĩ na maana ana, kwĩanana na sekeli ya vala vandũ vatheu;'),
('kam', 'NUM', 7, 86, 'na syĩko ĩkũmi na ilĩ sya thaavu syusĩe ũvani, ũito wa kĩla kĩmwe waĩ sekeli ĩkũmi, kwĩanana na sekeli ya vala vandũ vatheu; thaavu w’onthe wa syĩko waĩ sekeli ĩana yĩmwe na mĩongo ĩlĩ;'),
('kam', 'NUM', 7, 87, 'ng’ombe syonthe sya nthembo ya kũvĩvw’a syaĩ tũsalũ twa mũew’a ĩkũmi na twĩlĩ, na ndũũme ĩkũmi na ilĩ, na tũtũlũme twa mwaka ũmwe ĩkũmi na twĩlĩ, na nthembo ya mũtu ya kũthembanĩsya nasyo; na nthenge ĩkũmi na ilĩ sya nthembo kwondũ wa naĩ;'),
('kam', 'NUM', 7, 88, 'na ng’ombe syonthe sya nthembo ya nthembo sya mũuo syaĩ tũsalũ twa mũew’a mĩongo ĩlĩ na tũna, na ndũũme mĩongo thanthatũ na nthenge mĩongo thanthatũ na tũtũlũme twa mwaka ũmwe mĩongo thanthatũ. Moelo asu nĩmaumiw’e nũndũ wa kũvatha kĩthembeo kĩthĩwe kĩ kĩtheu, kyamina kwĩtĩkĩw’a mauta.'),
('kam', 'NUM', 7, 89, 'Na yĩla Mose walikile ĩeemanĩ ya kũmbanĩa aneene nake, nĩvo ĩndĩ wewie ũla Wasya ũkĩneena nake ũkyuma wĩkalonĩ wa tei ũla waĩ ĩũlũ wa ĩsandũkũ ya ũkũsĩ, kuma katĩ wa ala akeluvi elĩ: na Yeova aneena nake.'),
('kam', 'NUM', 8, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 8, 2, 'Neena na Aluni, noimũtavya, Yĩla wĩkwatasya mataa, ala mataa mũonza makamulĩkaa vu mbee wa kĩla kĩndũ kĩkĩawa mataa.'),
('kam', 'NUM', 8, 3, 'Na Aluni eeka ũu; akwatya mataa makyo nĩ kana mamulĩke vu mbee wa kĩla kĩndũ kĩkĩawa mataa, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 8, 4, 'Na ũũ waĩ mũtuĩle wa kĩla kĩndũ kĩkĩawa mataa, mũtuĩle wa thaavu; o ĩtina yakyo o na malaa makyo, kyaĩ kĩtue: kwĩanana na ngelekan’yo ĩla Yeova wamwonisye Mose, ũu nĩw’o waseũvisye kĩla kĩndũ kĩkĩawa mataa.'),
('kam', 'NUM', 8, 5, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 8, 6, 'Maumye Alivai nthĩnĩ wa ana ma Isilaeli, ũmathesye.'),
('kam', 'NUM', 8, 7, 'Na ũũ nĩw’o wĩmeka ũmathesye: maminzangĩsye manzĩ ma kũmathesya, nao meyenze mĩĩ yoo yonthe, na mathambye ngũa syoo, na kwĩthesya ene.'),
('kam', 'NUM', 8, 8, 'Nĩvo ĩndĩ mose kasalũ, na nthembo ya mũtu ya kũthembanĩsya nako, mũtu mũvinyu ũvulanĩtw’e na mauta; na ũkose kasalũ kangĩ kethĩwe nthembo kwondũ wa naĩ.'),
('kam', 'NUM', 8, 9, 'Na ũkamaete Alivai ngalĩ ya mbee ya ĩeema ya kũmbanĩa: na ũkomban’ye ũmbano w’onthe wa ana ma Isilaeli:'),
('kam', 'NUM', 8, 10, 'na ũkamaete Alivai vu mbee wa Yeova. Na ana ma Isilaeli makamailĩĩle Alivai moko moo:'),
('kam', 'NUM', 8, 11, 'na Aluni akamũetee Yeova asu Alivai methĩwe nthembo ya kũvyũlw’a vandũ va ana ma Isilaeli methĩwe ma kũthũkũmaa Yeova.'),
('kam', 'NUM', 8, 12, 'Na Alivai makailĩĩle moko moo mĩtwenĩ ya tũla tũsalũ: naku ũkamũthembee Yeova kamwe kethĩwe nthembo kwondũ wa naĩ, na kala kangĩ kethĩwe nthembo ya kũvĩvw’a, kwondũ wa wĩw’anĩthyo wa Alivai.'),
('kam', 'NUM', 8, 13, 'Na ũkaie Alivai mbee wa Aluni, na mbee wa ana make, na kũmũnenga Yeova methĩwe nthembo ya kũvyũlw’a.'),
('kam', 'NUM', 8, 14, 'Ũu nĩw’o wĩmavathan’ya Alivai na ana ma Isilaeli; na Alivai makeethĩwa makwa.'),
('kam', 'NUM', 8, 15, 'Na ĩtina wa ũu Alivai makalika nthĩnĩ kũtethasya wĩa wa ĩeema ya kũmbanĩa: na ũkamathesye na kũmanengane methĩwe nthembo ya kũvyũlw’a.'),
('kam', 'NUM', 8, 16, 'Nũndũ nĩnĩnengetwe andũ asu vyũ kuma nthĩnĩ wa ana ma Isilaeli; nĩnĩmosete methĩwe makwa vandũ va onthe ala mambaa kuma ĩvunĩ ya nyinyia, o makithathi ma ana onthe ma Isilaeli.'),
('kam', 'NUM', 8, 17, 'Nũndũ makithathi onthe ma ana ma Isilaeli nĩ makwa, mũndũ o na nyamũ: mũthenya ũla nooaie makithathi onthe nthĩ ya Misili nĩnamavathie methĩwe makwa.'),
('kam', 'NUM', 8, 18, 'Nakwa nĩnĩmosete Alivai vandũ va makithathi onthe ma ana ma Isilaeli.'),
('kam', 'NUM', 8, 19, 'Na nĩnĩmũnengete Aluni na ana make asu Alivai kuma nthĩnĩ wa ana ma Isilaeli, matethye wĩa wa ana ma Isilaeli ĩeemanĩ ya kũmbanĩa, mamathembeae ana ma Isilaeli nthembo ya wĩw’anĩthyo; nĩ kana vatikethĩwe ũthĩn’yo kwa ana ma Isilaeli, yĩla ana ma Isilaeli meũthengeea vala vandũ vatheu.'),
('kam', 'NUM', 8, 20, 'Ũu nĩw’o Mose na Aluni na ũmbano w’onthe wa ana ma Isilaeli mamekie Alivai: kwĩanana na onthe ala Yeova wamwĩaĩe Mose ũndũ wa Alivai, ũu nĩw’o ana ma Isilaeli mamekie.'),
('kam', 'NUM', 8, 21, 'Na Alivai meethesya naĩ, na mathambya ngũa syoo: na Aluni amũnenga Yeova mo methĩwe nthembo ya kũvyũlw’a; na Aluni athemba nthembo ya wĩw’anĩthyo kwondũ woo amathesya.'),
('kam', 'NUM', 8, 22, 'Na ĩtina wa ũu Alivai nĩmalikile kũthũkũmaa ĩeemanĩ ya kũmbanĩa makĩsiw’a nĩ Aluni na ana make: o tondũ Yeova wamwĩaĩe Mose ũndũ wa Alivai, nĩw’o mamekie.'),
('kam', 'NUM', 8, 23, 'Na Yeova aneena na Mose, akimwĩa,'),
('kam', 'NUM', 8, 24, 'Maũndũ ala maĩle kwikwa nĩ Alivai nĩ aa: ala mavikitye myaka mĩongo ĩlĩ na ĩtano na mbee makalike nthĩnĩ kũthũkũmaa wĩanĩ wa ĩeema ya kũmbanĩa:'),
('kam', 'NUM', 8, 25, 'na ala mavikĩtye myaka mĩongo ĩtano makaeke ũtethya wĩa ũsu, na maikathũkũma ĩngĩ,'),
('kam', 'NUM', 8, 26, 'ĩndĩ makatethanasya na ana‐a‐ĩthe moo ĩeemanĩ ya kũmbanĩa, makĩsũvĩaa wĩaĩo, na maikatethya wĩa nongi. Uu nĩw’o wĩmeka Alivai ũndũ wa mawĩaĩo moo.'),
('kam', 'NUM', 9, 1, 'Na Yeova aneena na Mose weũnĩ wa Sinai, mwei wa mbee wa mwaka wa kelĩ ĩtina wa mauma nthĩ ya Misili, akĩmwĩa,'),
('kam', 'NUM', 9, 2, 'Na ĩngĩ, ana ma Isilaeli nĩmalilikanae vasaka ĩvinda yĩla yĩtw’ĩtwe yaw’o.'),
('kam', 'NUM', 9, 3, 'Mũthenya wa ĩkũmi na ĩna wa mwei ũũ, wĩoo, mũkalilikane ĩvinda yĩla yĩtw’ĩtwe yaw’o: kwĩanana na myamũlo yonthe yaw’o, na kwĩanana na motw’ĩo onthe maw’o, mũkolilikane.'),
('kam', 'NUM', 9, 4, 'Na Mose aneena na ana ma Isilaeli malilikane vasaka.'),
('kam', 'NUM', 9, 5, 'Na malilikanĩla vasaka mwei wa mbee, mũthenya wa ĩkũmi na ĩna wa mwei, wĩoo, weũnĩ wa Sinai: kwĩanana na onthe ala Yeova wamwĩaĩe Mose, ũu nĩw’o ana ma Isilaeli meekie.'),
('kam', 'NUM', 9, 6, 'Na kwaĩ andũ amwe ala maĩ avuku nũndũ wa kimba kya mũndũ, na kwondũ wa ũu maiaatonya kũlilikana vasaka mũthenya ũsu: nao mathi vala ve Mose na Aluni mũthenya ũsu:'),
('kam', 'NUM', 9, 7, 'na andũ asu mamwĩa, Ithyĩ twĩ avuku nũndũ wa kimba kya mũndũ: twĩsiĩĩwa nĩkĩ tũikamũthembee Yeova ĩvinda yĩla yĩtw’ĩtwe ananĩ ma Isilaeli?'),
('kam', 'NUM', 9, 8, 'Na Mose amea, Eteelai, nĩw’e ũndũ Yeova ũnũkwĩaa ũndũ wenyu.'),
('kam', 'NUM', 9, 9, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 9, 10, 'Neena na ana ma Isilaeli, ũkĩmea, Ethĩwa mũndũ o na wĩva wa inyw’ĩ kana wa nzyawa syenyu akethĩwa mũvuku nũndũ wa kimba, kana akethĩwa e kũasa kyalonĩ, ĩndĩ akalilikana vasaka kwondũ wa Yeova.'),
('kam', 'NUM', 9, 11, 'Mwei wa kelĩ mũthenya wa ĩkũmi na ĩna wĩoo makolilikane; makaye na kĩmũtũ kĩte ĩlawa na nyũnyi syĩ ũũ:'),
('kam', 'NUM', 9, 12, 'matikatialye kĩndũ kyaw’o kũvika kĩoko, o na maikatũle ĩvĩndĩ yayo: kwĩanana na mwamũlo w’onthe wa vasaka nĩw’o meya.'),
('kam', 'NUM', 9, 13, 'Ĩndĩ mũndũ ũla mũtheu, na nde kyalonĩ, na ailea kũlilikana vasaka, mũndũ ũsu akavetwa kuma andũnĩ make; nĩkwĩthĩwa ndaathemba nthembo ya Yeova ĩvinda yĩla yĩtw’ĩtwe, mũndũ ũsu akakua naĩ syake.'),
('kam', 'NUM', 9, 14, 'Na ethĩwa mũeni akekala ũeni kwenyu, na enda kũlilikana vasaka kwondũ wa Yeova; kwĩanana na mwamũlo wa vasaka, na kwĩanana na ũtw’ĩo waw’o, nĩw’o wĩĩka: mũkeethĩwa na mwamũlo ũmwe, ũndũ wa mwĩkali wa ũeninĩ, o na ũndũ wa ũla wasyaĩwe nthĩ yenyu'),
('kam', 'NUM', 9, 15, 'Na mũthenya ũla wĩkalo waũngamiw’e mũumbĩ wavw’ĩka wĩkalo, naw’o nĩ ĩeema ya ũkũsĩ: na wĩoo waĩ ĩũlũ wa wĩkalo ũilyĩ mwaki, kũvika kĩoko.'),
('kam', 'NUM', 9, 16, 'Wailyĩ ũu mavinda onthe: mũumbĩ ũkyũvw’ĩka, na wailyĩ mwaki ũtukũ.'),
('kam', 'NUM', 9, 17, 'Na o yĩla mũumbĩ wookĩlw’a kuma Ĩeemanĩ, nĩvo ĩndĩ ĩtina wa ũu ana ma Isilaeli maendaa kyalo: na vandũ vala mũumbĩ waũngama, vau nĩvo ana ma Isilaeli mambaa maeema moo.'),
('kam', 'NUM', 9, 18, 'Kwondũ wa mwĩao wa Yeova ana ma Isilaeli nĩmaendaa kyalo, na kwondũ wa mwĩao wa Yeova nĩmambaa maeema moo: o yĩla mũumbĩ wekalaa ĩũlũ wa wĩkalo mekalaa maeemani moo.'),
('kam', 'NUM', 9, 19, 'Na yĩla mũumbĩ wekalaa ĩũlũ wa wĩkalo mĩthenya mingĩ, nĩvo ĩndĩ ana ma Isilaeli masũvĩaa wĩaĩo wa Yeova, na matyaendaa kyalo.'),
('kam', 'NUM', 9, 20, 'Na mavinda amwe mũumbĩ waĩ ĩũlũ wa wĩkalo mĩthenya mĩvũthũ; na ĩndĩ kwĩanana na mwĩao wa Yeova nĩmekalaa maeemanĩ, moo, na kwĩanana na mwĩao wa Yeova nĩmaendaa kyalo.'),
('kam', 'NUM', 9, 21, 'Na mavinda amwe mũumbĩ waĩ vo kuma wĩoo kũvika kĩoko; na mũumbĩ wookĩlw’a kĩoko, nĩmaendaa kyalo: kana ethĩwa nĩwekalaa mũthenga na ũtukũ, o yĩla mũumbĩ wookĩlw’a, nĩmaendaa kyalo.'),
('kam', 'NUM', 9, 22, 'Ethĩwa nĩ mĩthenya ĩlĩ, kana mwei, kana mwaka, mũumbĩ waũngama ĩũlũ wa wĩkalo, ũkĩkala ĩũlũ waw’o, ana ma Isilaeli nĩmekalaa maeemanĩ moo, na matyaendaa kyalo; ĩndĩ yĩla wookĩlw’a nĩmaendaa kyalo.'),
('kam', 'NUM', 9, 23, 'Meaĩwa nĩ Yeova nĩmambaa maeema, na meaĩwa nĩ Yeova nĩmaendaa kyalo: nĩmasũvĩaa wĩaĩo wa Yeova, kwĩanana na mwĩao wa Yeova ũla weaĩe Mose.'),
('kam', 'NUM', 10, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 10, 2, 'Ĩseũvĩsye masoo elĩ ma vetha; ũkamaseũvye na kũtua: na makeethĩwa ma kũmban’ya ũmbano, na ma syalo sya myako ya maeema.'),
('kam', 'NUM', 10, 3, 'Na yĩla mevuva, ũmbano w’onthe ũkoombana vala ũĩ mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'NUM', 10, 4, 'Na ethĩwa mavuva o ũmwe, nĩvo ĩndĩ anene, atongoi ma ngili sya Isilaeli, makoombana vala ũĩ.'),
('kam', 'NUM', 10, 5, 'Na yĩla mwĩvuva soo wĩ wasya wa kũtĩsya, myako ya maeema ya ngalĩ ya wumĩlonĩ wa syũa ĩkathi kyalo.'),
('kam', 'NUM', 10, 6, 'Na yĩla mwĩvuva soo wĩ wasya ũsu ĩvinda ya kelĩ, myako ya maeema ya ngalĩ ya ĩtheo ĩkathi kyalo: makavuve soo wĩ wasya wa ũtĩsya kwondũ wa syalo syoo.'),
('kam', 'NUM', 10, 7, 'Ĩndĩ yĩla ũmbano ũkũmbanw’a, mũkavuve, ĩndĩ mũtikavuve na wasya wa kũtĩsya.'),
('kam', 'NUM', 10, 8, 'Na ana ma Aluni, ala athembi, nĩo mevuva masoo; na ũndũ ũsu ũkeethĩwa mwamũlo kwenyu mosyaanĩonĩ menyu tene na tene.'),
('kam', 'NUM', 10, 9, 'Na yĩla mũkakwatya kaũ na mũmaitha ũla ũnũũmũnyamasya nthĩ yenyu, mũkavuve masoo asu me wasya wa kũtĩsya; na mũkalilikanwa nĩ Yeova Ngai wenyu, na mũkatangĩĩwa kuma amaithanĩ menyu.'),
('kam', 'NUM', 10, 10, 'Na ĩngĩ mũthenya wa ũtanu wenyu, na mavinda ma mboka syenyu itw’ĩtwe, na myambĩlĩlyo ya myei yenyu, mũkavuve masoo ĩũlũ wa nthembo syenyu sya kũvĩvw’a, na ĩũlũ wa nthembo sya nthembo syenyu sya mũuo; na ikeethĩwa kwenyu ũlilikan’yo vala ve Ngai wenyu: ninyie Yeova Ngai wenyu.'),
('kam', 'NUM', 10, 11, 'Na kweethĩwa mwaka wa kelĩ, mwei wa kelĩ, mũthenya wa mĩongo ĩlĩ wa mwei, mũumbĩ wookĩlw’a kuma ĩũlũ wa wĩkalo wa ũkũsĩ.')
